-- 4) Service manager may also delete servants within his service
drop policy if exists profiles_delete on public.profiles;
create policy profiles_delete on public.profiles for delete using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and service_id = public.my_service())
);


-- #####################################################################
-- ##  0006_null_scope_means_all.sql
-- #####################################################################

-- 0006: empty (null) scope at a lower level means "ALL" under the parent scope.
-- e.g. service_manager with null service_id => all services in his church;
--      class_servant with null class_id => all classes in his service (or church).

-- 1) can_access with cascading null semantics
create or replace function public.can_access(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select case public.my_role()
    when 'owner' then true
    when 'church_manager' then p_church = public.my_church()
    when 'service_manager' then
      (public.my_service() is null and p_church = public.my_church())
      or p_service = public.my_service()
    when 'class_servant' then
      (public.my_class() is null and (
        (public.my_service() is null and p_church = public.my_church())
        or p_service = public.my_service()
      ))
      or p_class = public.my_class()
    else false
  end
$$;

-- 2) services_select: null service scope => all services of own church
drop policy if exists services_select on public.services;
create policy services_select on public.services for select using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() in ('service_manager','class_servant') and (
       id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

-- 3) profiles_select: service manager with null service sees his whole church
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles for select using (
  id = auth.uid()
  or public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

-- 4) profiles_update_mgmt / profiles_delete: same null-scope semantics
drop policy if exists profiles_update_mgmt on public.profiles;
create policy profiles_update_mgmt on public.profiles for update using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

drop policy if exists profiles_delete on public.profiles;
create policy profiles_delete on public.profiles for delete using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

-- 5) services_update: null-scope service manager may edit all services of his church
drop policy if exists services_update on public.services;
create policy services_update on public.services for update using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

-- 6) classes insert/update/delete: null-scope semantics for service manager
drop policy if exists classes_insert on public.classes;
create policy classes_insert on public.classes for insert with check (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);

drop policy if exists classes_update on public.classes;
create policy classes_update on public.classes for update using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
  or (public.my_role() = 'class_servant' and id = public.my_class())
);

drop policy if exists classes_delete on public.classes;
create policy classes_delete on public.classes for delete using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and (
       service_id = public.my_service()
       or (public.my_service() is null and church_id = public.my_church())
  ))
);


-- #####################################################################
-- ##  0007_child_job.sql
-- #####################################################################

-- 0007: add "job" (الوظيفة) field to children
-- Used by the children page job selector/filter.

alter table public.children
  add column if not exists job text;

comment on column public.children.job is 'وظيفة المخدوم (اختياري) — يُستخدم في فلترة صفحة المخدومين';


-- #####################################################################
-- ##  0008_attendance_points_logs.sql
-- #####################################################################

-- =====================================================================
-- 0008: Attendance log + Points log tables
--       Jobs are now app-code constants → drop children.job (from 0007)
-- =====================================================================

-- Jobs live in the app code now, not the database
alter table public.children drop column if exists job;

-- ---------- ATTENDANCE LOG ----------
-- Every attendance register/remove action from the children page.
create table public.attendance_log (
  id uuid primary key default gen_random_uuid(),
  child_id uuid not null references public.children(id) on delete cascade,
  church_id uuid not null references public.churches(id) on delete cascade,
  service_id uuid not null references public.services(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  action text not null check (action in ('add', 'remove')),
  points_delta integer not null default 5 check (points_delta >= 0),
  recorded_by uuid references public.profiles(id),
  created_at timestamptz not null default now()
);
create index idx_attendance_log_child on public.attendance_log(child_id);
create index idx_attendance_log_created on public.attendance_log(created_at);

-- ---------- POINTS LOG ----------
-- Every manual points add/subtract action from the children page.
create table public.points_log (
  id uuid primary key default gen_random_uuid(),
  child_id uuid not null references public.children(id) on delete cascade,
  church_id uuid not null references public.churches(id) on delete cascade,
  service_id uuid not null references public.services(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  delta integer not null check (delta <> 0),   -- positive = add, negative = subtract
  recorded_by uuid references public.profiles(id),
  created_at timestamptz not null default now()
);
create index idx_points_log_child on public.points_log(child_id);
create index idx_points_log_created on public.points_log(created_at);

-- ---------- RLS ----------
alter table public.attendance_log enable row level security;
alter table public.points_log enable row level security;

create policy attendance_log_select on public.attendance_log for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy attendance_log_insert on public.attendance_log for insert with check (
  public.can_access(church_id, service_id, class_id) and recorded_by = auth.uid()
);

create policy points_log_select on public.points_log for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy points_log_insert on public.points_log for insert with check (
  public.can_access(church_id, service_id, class_id) and recorded_by = auth.uid()
);

-- ---------- SIDE-EFFECT TRIGGERS (update children counters) ----------
create or replace function public.on_attendance_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.action = 'add' then
    update public.children
       set attendance_count = attendance_count + 1,
           points = points + new.points_delta,
           updated_at = now()
     where id = new.child_id;
  else -- remove
    update public.children
       set attendance_count = greatest(attendance_count - 1, 0),
           points = greatest(points - new.points_delta, 0),
           updated_at = now()
     where id = new.child_id;
  end if;
  return new;
end $$;
create trigger trg_attendance_log_insert after insert on public.attendance_log
for each row execute function public.on_attendance_log_insert();

create or replace function public.on_points_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.children
     set points = greatest(points + new.delta, 0),
         updated_at = now()
   where id = new.child_id;
  return new;
end $$;
create trigger trg_points_log_insert after insert on public.points_log
for each row execute function public.on_points_log_insert();

-- ---------- REALTIME ----------
alter publication supabase_realtime add table public.attendance_log;
alter publication supabase_realtime add table public.points_log;
alter table public.attendance_log replica identity full;
alter table public.points_log replica identity full;


-- #####################################################################
-- ##  0009_child_gender_photo.sql
-- #####################################################################

-- =====================================================================
-- 0009: Add-child module fields
--       gender (boy/girl) + photo_url (webp stored in photos bucket)
-- =====================================================================

alter table public.children
  add column if not exists gender text check (gender in ('boy', 'girl')),
  add column if not exists photo_url text;

comment on column public.children.gender is 'نوع المخدوم: boy = ولد، girl = بنت';
comment on column public.children.photo_url is 'صورة المخدوم (webp) من bucket الصور العام';


-- #####################################################################
-- ##  0010_rebuild_children_order.sql
-- #####################################################################

-- =====================================================================
-- 0010: REBUILD public.children with the new column order
--
--   id, church_id, service_id, class_id,
--   qr_code, name, gender, birthdate, phone, address, notes,
--   attendance_count, points, image_url,
--   created_at, created_by, edited_at, edited_by
--
-- Postgres cannot reorder columns, so we recreate the table and copy
-- the data, then re-attach FKs, RLS policies, triggers and realtime.
-- Existing data is PRESERVED.
-- =====================================================================


-- ---------- 1. New table in the exact requested order ----------
create table public.children_new (
  id               uuid primary key default gen_random_uuid(),
  church_id        uuid not null references public.churches(id) on delete cascade,
  service_id       uuid not null references public.services(id) on delete cascade,
  class_id         uuid not null references public.classes(id) on delete cascade,
  qr_code          text unique default encode(gen_random_bytes(12), 'hex'),
  name             text not null,
  gender           text check (gender in ('boy', 'girl')),
  birthdate        date,
  phone            text,
  address          text,
  notes            text,
  attendance_count integer not null default 0,
  points           integer not null default 0,
  image_url        text,
  created_at       timestamptz not null default now(),
  created_by       uuid references public.profiles(id),
  edited_at        timestamptz not null default now(),
  edited_by        uuid references public.profiles(id)
);

-- ---------- 2. Copy existing data ----------
insert into public.children_new (
  id, church_id, service_id, class_id,
  qr_code, name, gender, birthdate, phone, address, notes,
  attendance_count, points, image_url,
  created_at, created_by, edited_at, edited_by
)
select
  id, church_id, service_id, class_id,
  qr_code, name, gender, birthdate, phone, address, notes,
  attendance_count, points, photo_url,
  created_at, created_by, updated_at, null
from public.children;

-- ---------- 3. Detach dependents from the old table ----------
alter table public.attendance     drop constraint if exists attendance_child_id_fkey;
alter table public.attendance_log drop constraint if exists attendance_log_child_id_fkey;
alter table public.points_log     drop constraint if exists points_log_child_id_fkey;

alter publication supabase_realtime drop table public.children;

drop table public.children;

-- ---------- 4. Swap in the new table ----------
alter table public.children_new rename to children;

create index idx_children_class   on public.children(class_id);
create index idx_children_service on public.children(service_id);
create index idx_children_church  on public.children(church_id);

-- ---------- 5. Re-attach dependent FKs ----------
alter table public.attendance
  add constraint attendance_child_id_fkey
  foreign key (child_id) references public.children(id) on delete cascade;
alter table public.attendance_log
  add constraint attendance_log_child_id_fkey
  foreign key (child_id) references public.children(id) on delete cascade;
alter table public.points_log
  add constraint points_log_child_id_fkey
  foreign key (child_id) references public.children(id) on delete cascade;

-- ---------- 6. RLS + policies (same rules as before) ----------
alter table public.children enable row level security;

create policy children_select on public.children for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy children_insert on public.children for insert with check (
  public.can_access(church_id, service_id, class_id)
);
create policy children_update on public.children for update using (
  public.can_access(church_id, service_id, class_id)
);
create policy children_delete on public.children for delete using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and service_id = public.my_service())
);

-- ---------- 7. Touch trigger: keep edited_at / edited_by fresh ----------
create or replace function public.touch_child_edited()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.edited_at := now();
  -- only stamp edited_by when the update comes from a logged-in user
  if auth.uid() is not null then
    new.edited_by := auth.uid();
  end if;
  return new;
end $$;
create trigger trg_children_edited before update on public.children
for each row execute function public.touch_child_edited();

-- ---------- 8. Counter trigger functions: drop updated_at references ----------
create or replace function public.on_attendance_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.children
     set attendance_count = attendance_count + 1,
         points = points + new.points_awarded
   where id = new.child_id;
  return new;
end $$;

create or replace function public.on_attendance_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.children
     set attendance_count = greatest(attendance_count - 1, 0),
         points = greatest(points - old.points_awarded, 0)
   where id = old.child_id;
  return old;
end $$;

create or replace function public.on_attendance_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.action = 'add' then
    update public.children
       set attendance_count = attendance_count + 1,
           points = points + new.points_delta
     where id = new.child_id;
  else -- remove
    update public.children
       set attendance_count = greatest(attendance_count - 1, 0),
           points = greatest(points - new.points_delta, 0)
     where id = new.child_id;
  end if;
  return new;
end $$;

create or replace function public.on_points_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.children
     set points = greatest(points + new.delta, 0)
   where id = new.child_id;
  return new;
end $$;

-- ---------- 9. Realtime ----------
alter publication supabase_realtime add table public.children;
alter table public.children replica identity full;



-- #####################################################################
-- ##  0011_persons_enrollments.sql
-- #####################################################################

-- =====================================================================
-- 0011: PERSON-CENTRIC REBUILD
--
-- New philosophy: the app is built on PERSONS.
--   persons      = identity table: national_id (the QR code), name,
--                  birthdate, gender (male/female), phone (+ photo etc.)
--   enrollments  = a person bound to church + service + class.
--                  One person may have MANY enrollments (many churches /
--                  services / classes). Attendance & points live on the
--                  enrollment.
--
-- Adding a person in any module (e.g. Sunday school):
--   1. person data goes to persons (upsert by national_id)
--   2. an enrollment row registers him in that church/service/class
--
-- Existing children data is PRESERVED:
--   1 child row -> 1 person + 1 enrollment (ids reused, so attendance,
--   attendance_log and points_log simply re-point to enrollment_id).
-- =====================================================================


-- =====================================================================
-- 1. PERSONS — the identity table
-- =====================================================================
create table public.persons (
  id           uuid primary key default gen_random_uuid(),
  national_id  text not null unique default encode(gen_random_bytes(12), 'hex'),
  name         text not null,
  birthdate    date,
  gender       text check (gender in ('male', 'female')),
  phone        text,
  address      text,
  notes        text,
  image_url    text,
  created_at   timestamptz not null default now(),
  created_by   uuid references public.profiles(id),
  edited_at    timestamptz not null default now(),
  edited_by    uuid references public.profiles(id)
);
create index idx_persons_national_id on public.persons(national_id);
create index idx_persons_name on public.persons(name);

comment on table public.persons is 'الأشخاص — جدول الهوية المركزي: الرقم القومي (QR) والاسم وتاريخ الميلاد والنوع والهاتف';
comment on column public.persons.national_id is 'الرقم القومي — هو نفسه كود الـ QR، فريد لكل شخص';

-- =====================================================================
-- 2. ENROLLMENTS — person bound to church / service / class
-- =====================================================================
create table public.enrollments (
  id               uuid primary key default gen_random_uuid(),
  person_id        uuid not null references public.persons(id) on delete cascade,
  church_id        uuid not null references public.churches(id) on delete cascade,
  service_id       uuid not null references public.services(id) on delete cascade,
  class_id         uuid not null references public.classes(id) on delete cascade,
  attendance_count integer not null default 0,
  points           integer not null default 0,
  created_at       timestamptz not null default now(),
  created_by       uuid references public.profiles(id),
  edited_at        timestamptz not null default now(),
  edited_by        uuid references public.profiles(id),
  unique (person_id, class_id)
);
create index idx_enrollments_person  on public.enrollments(person_id);
create index idx_enrollments_class   on public.enrollments(class_id);
create index idx_enrollments_service on public.enrollments(service_id);
create index idx_enrollments_church  on public.enrollments(church_id);

comment on table public.enrollments is 'تسجيلات الأشخاص — ربط الشخص بالكنيسة والخدمة والفصل، الحضور والنقاط لكل تسجيل';

-- =====================================================================
-- 3. MIGRATE existing children -> persons + enrollments
--    (person id AND enrollment id both reuse the child id so that
--     attendance / logs re-point without any value changes)
-- =====================================================================
insert into public.persons (
  id, national_id, name, birthdate, gender, phone, address, notes,
  image_url, created_at, created_by, edited_at, edited_by
)
select
  id,
  coalesce(qr_code, encode(gen_random_bytes(12), 'hex')),
  name,
  birthdate,
  case gender when 'boy' then 'male' when 'girl' then 'female' else null end,
  phone, address, notes, image_url,
  created_at, created_by, edited_at, edited_by
from public.children;

insert into public.enrollments (
  id, person_id, church_id, service_id, class_id,
  attendance_count, points, created_at, created_by, edited_at, edited_by
)
select
  id, id, church_id, service_id, class_id,
  attendance_count, points, created_at, created_by, edited_at, edited_by
from public.children;

-- =====================================================================
-- 4. RE-POINT attendance / attendance_log / points_log to enrollments
-- =====================================================================
alter table public.attendance drop constraint if exists attendance_child_id_fkey;
alter table public.attendance rename column child_id to enrollment_id;
alter table public.attendance
  add constraint attendance_enrollment_id_fkey
  foreign key (enrollment_id) references public.enrollments(id) on delete cascade;

alter table public.attendance_log drop constraint if exists attendance_log_child_id_fkey;
alter table public.attendance_log rename column child_id to enrollment_id;
alter table public.attendance_log
  add constraint attendance_log_enrollment_id_fkey
  foreign key (enrollment_id) references public.enrollments(id) on delete cascade;

alter table public.points_log drop constraint if exists points_log_child_id_fkey;
alter table public.points_log rename column child_id to enrollment_id;
alter table public.points_log
  add constraint points_log_enrollment_id_fkey
  foreign key (enrollment_id) references public.enrollments(id) on delete cascade;

-- =====================================================================
-- 5. DROP the old children table
-- =====================================================================
alter publication supabase_realtime drop table public.children;
drop table public.children;

-- =====================================================================
-- 6. COUNTER TRIGGERS now update enrollments
-- =====================================================================
create or replace function public.on_attendance_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set attendance_count = attendance_count + 1,
         points = points + new.points_awarded
   where id = new.enrollment_id;
  return new;
end $$;

create or replace function public.on_attendance_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set attendance_count = greatest(attendance_count - 1, 0),
         points = greatest(points - old.points_awarded, 0)
   where id = old.enrollment_id;
  return old;
end $$;

create or replace function public.on_attendance_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.action = 'add' then
    update public.enrollments
       set attendance_count = attendance_count + 1,
           points = points + new.points_delta
     where id = new.enrollment_id;
  else -- remove
    update public.enrollments
       set attendance_count = greatest(attendance_count - 1, 0),
           points = greatest(points - new.points_delta, 0)
     where id = new.enrollment_id;
  end if;
  return new;
end $$;

create or replace function public.on_points_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set points = greatest(points + new.delta, 0)
   where id = new.enrollment_id;
  return new;
end $$;

-- =====================================================================
-- 7. TOUCH triggers (edited_at / edited_by)
-- =====================================================================
create or replace function public.touch_edited()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.edited_at := now();
  if auth.uid() is not null then
    new.edited_by := auth.uid();
  end if;
  return new;
end $$;

create trigger trg_persons_edited before update on public.persons
for each row execute function public.touch_edited();
create trigger trg_enrollments_edited before update on public.enrollments
for each row execute function public.touch_edited();

-- =====================================================================
-- 8. RLS
-- =====================================================================
alter table public.persons enable row level security;
alter table public.enrollments enable row level security;

-- A person is visible when the user can access ANY of his enrollments
-- (or created him, or is the owner)
create or replace function public.can_see_person(p_person uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_owner()
      or exists (
        select 1 from public.enrollments e
         where e.person_id = p_person
           and public.can_access(e.church_id, e.service_id, e.class_id)
      )
$$;

-- ---------- PERSONS ----------
create policy persons_select on public.persons for select using (
  created_by = auth.uid() or public.can_see_person(id)
);
-- Any approved user may create persons (needed when adding in any module)
create policy persons_insert on public.persons for insert with check (
  public.my_role() is not null
);
create policy persons_update on public.persons for update using (
  created_by = auth.uid() or public.can_see_person(id)
);
create policy persons_delete on public.persons for delete using (public.is_owner());

-- ---------- ENROLLMENTS (same tenant rules as old children) ----------
create policy enrollments_select on public.enrollments for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy enrollments_insert on public.enrollments for insert with check (
  public.can_access(church_id, service_id, class_id)
);
create policy enrollments_update on public.enrollments for update using (
  public.can_access(church_id, service_id, class_id)
);
create policy enrollments_delete on public.enrollments for delete using (
  public.is_owner()
  or (public.my_role() = 'church_manager' and church_id = public.my_church())
  or (public.my_role() = 'service_manager' and service_id = public.my_service())
);

-- =====================================================================
-- 9. RPCs — the person-centric flows
-- =====================================================================

-- Cross-scope lookup by national id (QR). Security definer so a servant
-- can recognize a person already registered at ANOTHER church/service,
-- instead of creating a duplicate.
create or replace function public.find_person_by_national_id(p_national_id text)
returns setof public.persons
language sql stable security definer set search_path = public as $$
  select p.* from public.persons p
   where public.my_role() is not null
     and p.national_id = nullif(trim(p_national_id), '')
   limit 1
$$;

-- The core "add person in a module" flow:
--   1. upsert person by national_id (data goes to persons table)
--   2. register him as an enrollment in church + service + class
-- Returns: person_id, enrollment_id, national_id,
--          person_created (new person?), already_enrolled (dup in class?)
create or replace function public.add_person_and_enroll(
  p_church uuid,
  p_service uuid,
  p_class uuid,
  p_name text,
  p_national_id text default null,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_image_url text default null,
  p_points integer default 0
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_nid text;
  v_person public.persons%rowtype;
  v_person_created boolean := false;
  v_enrollment_id uuid;
  v_already boolean := false;
begin
  if public.my_role() is null then
    raise exception 'not_approved' using errcode = '42501';
  end if;
  if not public.can_access(p_church, p_service, p_class) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if coalesce(trim(p_name), '') = '' then
    raise exception 'name_required';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender';
  end if;

  v_nid := nullif(trim(p_national_id), '');
  if v_nid is null then
    v_nid := encode(gen_random_bytes(12), 'hex');
  end if;

  select * into v_person from public.persons where national_id = v_nid;

  if not found then
    insert into public.persons (
      national_id, name, gender, birthdate, phone, address, notes,
      image_url, created_by, edited_by
    ) values (
      v_nid, trim(p_name), p_gender, p_birthdate,
      nullif(trim(coalesce(p_phone, '')), ''),
      nullif(trim(coalesce(p_address, '')), ''),
      nullif(trim(coalesce(p_notes, '')), ''),
      p_image_url, auth.uid(), auth.uid()
    ) returning * into v_person;
    v_person_created := true;
  else
    -- Person exists: fill in the blanks only (never overwrite existing data)
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = auth.uid(),
      edited_at = now()
    where id = v_person.id;
  end if;

  -- Register the enrollment (person may already be in this class)
  insert into public.enrollments (person_id, church_id, service_id, class_id, points, created_by, edited_by)
  values (v_person.id, p_church, p_service, p_class, greatest(coalesce(p_points, 0), 0), auth.uid(), auth.uid())
  on conflict (person_id, class_id) do nothing
  returning id into v_enrollment_id;

  if v_enrollment_id is null then
    v_already := true;
    select id into v_enrollment_id from public.enrollments
     where person_id = v_person.id and class_id = p_class;
  end if;

  return jsonb_build_object(
    'person_id', v_person.id,
    'enrollment_id', v_enrollment_id,
    'national_id', v_nid,
    'person_created', v_person_created,
    'already_enrolled', v_already
  );
end $$;

-- =====================================================================
-- 10. REALTIME
-- =====================================================================
alter publication supabase_realtime add table public.persons;
alter publication supabase_realtime add table public.enrollments;
alter table public.persons replica identity full;
alter table public.enrollments replica identity full;



-- #####################################################################
-- ##  0012_simplify_logs.sql
-- #####################################################################

-- =====================================================================
-- 0012: SIMPLIFY THE LOG TABLES
--
-- The enrollment_id already says which church / service / class the
-- action belongs to, so the log tables no longer repeat those columns.
--
--   attendance_log: id, enrollment_id, action, points_delta,
--                   recorded_by, created_at
--   points_log:     id, enrollment_id, delta, recorded_by, created_at
--
-- (enrollment_id comes right after id; created/edited audit columns
--  live only on persons — for adding the person — and on enrollments —
--  for creating the enrollment.)
--
-- The old `attendance` table (scanner v1) is REMOVED — the app now uses
-- attendance_log everywhere. Its history is copied into attendance_log
-- first so no data is lost.
-- =====================================================================


-- =====================================================================
-- 1. Helper: scope check derived from the enrollment
-- =====================================================================
create or replace function public.can_access_enrollment(p_enrollment uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.enrollments e
     where e.id = p_enrollment
       and public.can_access(e.church_id, e.service_id, e.class_id)
  )
$$;

-- =====================================================================
-- 2. Rebuild ATTENDANCE_LOG in the new simple shape
-- =====================================================================
create table public.attendance_log_new (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  action        text not null check (action in ('add', 'remove')),
  points_delta  integer not null default 5 check (points_delta >= 0),
  recorded_by   uuid references public.profiles(id),
  created_at    timestamptz not null default now()
);

-- Copy existing log rows
insert into public.attendance_log_new (id, enrollment_id, action, points_delta, recorded_by, created_at)
select id, enrollment_id, action, points_delta, recorded_by, created_at
from public.attendance_log;

-- Preserve the old scanner `attendance` history as 'add' log entries
-- (skip ids that would collide — there should be none, but be safe)
insert into public.attendance_log_new (id, enrollment_id, action, points_delta, recorded_by, created_at)
select a.id, a.enrollment_id, 'add', a.points_awarded, a.recorded_by, a.created_at
from public.attendance a
where not exists (select 1 from public.attendance_log_new n where n.id = a.id);

alter publication supabase_realtime drop table public.attendance_log;
drop table public.attendance_log;
alter table public.attendance_log_new rename to attendance_log;

create index idx_attendance_log_enrollment on public.attendance_log(enrollment_id);
create index idx_attendance_log_created on public.attendance_log(created_at);

-- =====================================================================
-- 3. Rebuild POINTS_LOG in the new simple shape
-- =====================================================================
create table public.points_log_new (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  delta         integer not null check (delta <> 0),   -- positive = add, negative = subtract
  recorded_by   uuid references public.profiles(id),
  created_at    timestamptz not null default now()
);

insert into public.points_log_new (id, enrollment_id, delta, recorded_by, created_at)
select id, enrollment_id, delta, recorded_by, created_at
from public.points_log;

alter publication supabase_realtime drop table public.points_log;
drop table public.points_log;
alter table public.points_log_new rename to points_log;

create index idx_points_log_enrollment on public.points_log(enrollment_id);
create index idx_points_log_created on public.points_log(created_at);

-- =====================================================================
-- 4. REMOVE the old attendance table (unused — history copied above)
-- =====================================================================
alter publication supabase_realtime drop table public.attendance;
drop function if exists public.on_attendance_insert() cascade;
drop function if exists public.on_attendance_delete() cascade;
drop table public.attendance;

-- =====================================================================
-- 5. RLS — scope derived from the enrollment
-- =====================================================================
alter table public.attendance_log enable row level security;
alter table public.points_log enable row level security;

create policy attendance_log_select on public.attendance_log for select using (
  public.can_access_enrollment(enrollment_id)
);
create policy attendance_log_insert on public.attendance_log for insert with check (
  public.can_access_enrollment(enrollment_id) and recorded_by = auth.uid()
);

create policy points_log_select on public.points_log for select using (
  public.can_access_enrollment(enrollment_id)
);
create policy points_log_insert on public.points_log for insert with check (
  public.can_access_enrollment(enrollment_id) and recorded_by = auth.uid()
);

-- =====================================================================
-- 6. COUNTER TRIGGERS (re-attach to the rebuilt tables)
-- =====================================================================
create or replace function public.on_attendance_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.action = 'add' then
    update public.enrollments
       set attendance_count = attendance_count + 1,
           points = points + new.points_delta
     where id = new.enrollment_id;
  else -- remove
    update public.enrollments
       set attendance_count = greatest(attendance_count - 1, 0),
           points = greatest(points - new.points_delta, 0)
     where id = new.enrollment_id;
  end if;
  return new;
end $$;
create trigger trg_attendance_log_insert after insert on public.attendance_log
for each row execute function public.on_attendance_log_insert();

create or replace function public.on_points_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set points = greatest(points + new.delta, 0)
   where id = new.enrollment_id;
  return new;
end $$;
create trigger trg_points_log_insert after insert on public.points_log
for each row execute function public.on_points_log_insert();

-- =====================================================================
-- 7. REALTIME
-- =====================================================================
alter publication supabase_realtime add table public.attendance_log;
alter publication supabase_realtime add table public.points_log;
alter table public.attendance_log replica identity full;
alter table public.points_log replica identity full;



-- #####################################################################
-- ##  0013_events_causes.sql
-- #####################################################################

-- =====================================================================
-- 0013: EVENTS & CAUSES
--
-- 1. New master table `events`  — bound to church/service/class.
--    Attendance is registered AGAINST AN EVENT: attendance_log now has
--    event_id (right after enrollment_id) instead of the old `action`
--    column. One attendance per enrollment per event (unique).
--
-- 2. Attendance REMOVAL no longer adds a 'remove' entry — it DELETES
--    the attendance entry, and a delete-trigger reverts the counters
--    (attendance_count - 1, points - points_delta).
--
-- 3. New master table `causes` — bound to church/service/class.
--    points_log now has cause_id BEFORE delta.
--
-- Legacy data: old 'remove' rows are netted against the most recent
-- 'add' rows of the same enrollment (they cancel each other), and the
-- remaining 'add' rows are kept with event_id = null. Enrollment
-- counters are stored values and remain unchanged.
-- =====================================================================


-- =====================================================================
-- 1. EVENTS — bound to church / service / class
-- =====================================================================
create table public.events (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid not null references public.services(id) on delete cascade,
  class_id    uuid not null references public.classes(id) on delete cascade,
  name        text not null,
  description text,
  event_date  date,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.profiles(id)
);
create index idx_events_class on public.events(class_id);

-- =====================================================================
-- 2. CAUSES — bound to church / service / class (reasons for points)
-- =====================================================================
create table public.causes (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid not null references public.services(id) on delete cascade,
  class_id    uuid not null references public.classes(id) on delete cascade,
  name        text not null,
  description text,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.profiles(id)
);
create index idx_causes_class on public.causes(class_id);

-- touch triggers (edited_at) — reuse the helper from 0011
create trigger trg_events_touch before update on public.events
for each row execute function public.touch_edited();
create trigger trg_causes_touch before update on public.causes
for each row execute function public.touch_edited();

-- RLS: scoped exactly like classes
alter table public.events enable row level security;
alter table public.causes enable row level security;

create policy events_select on public.events for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy events_insert on public.events for insert with check (
  public.can_access(church_id, service_id, class_id)
);
create policy events_update on public.events for update using (
  public.can_access(church_id, service_id, class_id)
) with check (
  public.can_access(church_id, service_id, class_id)
);
create policy events_delete on public.events for delete using (
  public.can_access(church_id, service_id, class_id)
);

create policy causes_select on public.causes for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy causes_insert on public.causes for insert with check (
  public.can_access(church_id, service_id, class_id)
);
create policy causes_update on public.causes for update using (
  public.can_access(church_id, service_id, class_id)
) with check (
  public.can_access(church_id, service_id, class_id)
);
create policy causes_delete on public.causes for delete using (
  public.can_access(church_id, service_id, class_id)
);

-- =====================================================================
-- 3. Rebuild ATTENDANCE_LOG: event_id instead of action
-- =====================================================================
create table public.attendance_log_new (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  event_id      uuid references public.events(id) on delete set null,
  points_delta  integer not null default 5 check (points_delta >= 0),
  recorded_by   uuid references public.profiles(id),
  created_at    timestamptz not null default now()
);

-- keep the 'add' history (legacy rows have no event)
insert into public.attendance_log_new (id, enrollment_id, event_id, points_delta, recorded_by, created_at)
select id, enrollment_id, null, points_delta, recorded_by, created_at
from public.attendance_log
where action = 'add';

-- net legacy 'remove' rows: each remove cancels the most recent add
-- of the same enrollment (counters are stored and stay unchanged)
with removes as (
  select id, enrollment_id,
         row_number() over (partition by enrollment_id order by created_at) as rn
  from public.attendance_log where action = 'remove'
),
adds as (
  select id, enrollment_id,
         row_number() over (partition by enrollment_id order by created_at desc) as rn
  from public.attendance_log where action = 'add'
)
delete from public.attendance_log_new n
using removes r
join adds a on a.enrollment_id = r.enrollment_id and a.rn = r.rn
where n.id = a.id;

alter publication supabase_realtime drop table public.attendance_log;
drop table public.attendance_log;
alter table public.attendance_log_new rename to attendance_log;

create index idx_attendance_log_enrollment on public.attendance_log(enrollment_id);
create index idx_attendance_log_created on public.attendance_log(created_at);
-- one attendance per enrollment per event
create unique index uq_attendance_enrollment_event
  on public.attendance_log(enrollment_id, event_id)
  where event_id is not null;

-- =====================================================================
-- 4. Rebuild POINTS_LOG: cause_id before delta
-- =====================================================================
create table public.points_log_new (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  cause_id      uuid references public.causes(id) on delete set null,
  delta         integer not null check (delta <> 0),
  recorded_by   uuid references public.profiles(id),
  created_at    timestamptz not null default now()
);

insert into public.points_log_new (id, enrollment_id, cause_id, delta, recorded_by, created_at)
select id, enrollment_id, null, delta, recorded_by, created_at
from public.points_log;

alter publication supabase_realtime drop table public.points_log;
drop table public.points_log;
alter table public.points_log_new rename to points_log;

create index idx_points_log_enrollment on public.points_log(enrollment_id);
create index idx_points_log_created on public.points_log(created_at);

-- =====================================================================
-- 5. RLS on the rebuilt logs
-- =====================================================================
alter table public.attendance_log enable row level security;
alter table public.points_log enable row level security;

create policy attendance_log_select on public.attendance_log for select using (
  public.can_access_enrollment(enrollment_id)
);
create policy attendance_log_insert on public.attendance_log for insert with check (
  public.can_access_enrollment(enrollment_id) and recorded_by = auth.uid()
);
-- removal = deleting the entry (reverted by trigger below)
create policy attendance_log_delete on public.attendance_log for delete using (
  public.can_access_enrollment(enrollment_id)
);

create policy points_log_select on public.points_log for select using (
  public.can_access_enrollment(enrollment_id)
);
create policy points_log_insert on public.points_log for insert with check (
  public.can_access_enrollment(enrollment_id) and recorded_by = auth.uid()
);

-- =====================================================================
-- 6. Integrity: event/cause must belong to the enrollment's class
-- =====================================================================
create or replace function public.check_attendance_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1
      from public.events ev
      join public.enrollments en on en.id = new.enrollment_id
      where ev.id = new.event_id and ev.class_id = en.class_id
    ) then
      raise exception 'event does not belong to the enrollment class';
    end if;
  end if;
  return new;
end $$;
create trigger trg_attendance_event_scope before insert on public.attendance_log
for each row execute function public.check_attendance_event_scope();

create or replace function public.check_points_cause_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.cause_id is not null then
    if not exists (
      select 1
      from public.causes ca
      join public.enrollments en on en.id = new.enrollment_id
      where ca.id = new.cause_id and ca.class_id = en.class_id
    ) then
      raise exception 'cause does not belong to the enrollment class';
    end if;
  end if;
  return new;
end $$;
create trigger trg_points_cause_scope before insert on public.points_log
for each row execute function public.check_points_cause_scope();

-- =====================================================================
-- 7. COUNTER TRIGGERS
--    insert = attend (+1 attendance, +points_delta)
--    delete = remove attendance (-1 attendance, -points_delta)
-- =====================================================================
create or replace function public.on_attendance_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set attendance_count = attendance_count + 1,
         points = points + new.points_delta
   where id = new.enrollment_id;
  return new;
end $$;
create trigger trg_attendance_log_insert after insert on public.attendance_log
for each row execute function public.on_attendance_log_insert();

create or replace function public.on_attendance_log_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set attendance_count = greatest(attendance_count - 1, 0),
         points = greatest(points - old.points_delta, 0)
   where id = old.enrollment_id;
  return old;
end $$;
create trigger trg_attendance_log_delete after delete on public.attendance_log
for each row execute function public.on_attendance_log_delete();

create or replace function public.on_points_log_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.enrollments
     set points = greatest(points + new.delta, 0)
   where id = new.enrollment_id;
  return new;
end $$;
create trigger trg_points_log_insert after insert on public.points_log
for each row execute function public.on_points_log_insert();

-- =====================================================================
-- 8. REALTIME
-- =====================================================================
alter publication supabase_realtime add table public.events;
alter publication supabase_realtime add table public.causes;
alter publication supabase_realtime add table public.attendance_log;
alter publication supabase_realtime add table public.points_log;
alter table public.events replica identity full;
alter table public.causes replica identity full;
alter table public.attendance_log replica identity full;
alter table public.points_log replica identity full;



-- #####################################################################
-- ##  0014_event_schedule_scope_points.sql
-- #####################################################################

-- =====================================================================
-- 0014: EVENT SCHEDULING + FLEXIBLE SCOPE + BOUND POINTS (Cairo time)
--
-- 1. EVENTS
--    - recurrence: 'once' (has event_date) or 'weekly' (weekdays[] —
--      one day = every week, several days = week days).
--    - optional start_time / end_time (Africa/Cairo local time).
--    - points: amount of points bound to attending this event.
--    - scope: service_id / class_id become NULLABLE.
--        service_id null  => ALL services of the church (=> class null too)
--        class_id  null   => ALL classes of the (church, service)
--
-- 2. CAUSES
--    - points: amount of points bound to this cause.
--    - scope: service_id / class_id become NULLABLE (same semantics).
--
-- 3. RLS uses new scope_overlaps (select) / scope_contains (write)
--    helpers so church-wide events/causes stay visible to service and
--    class managers inside that church.
--
-- 4. Attendance uniqueness becomes PER CAIRO DAY so weekly events can
--    be attended once each occurrence day. attendance_log.attended_on
--    (date, Africa/Cairo) is added.
--
-- 5. Scope-check triggers updated: an event/cause applies to an
--    enrollment when the enrollment falls INSIDE the event/cause scope.
-- =====================================================================


-- =====================================================================
-- 1. EVENTS: schedule + points + nullable scope
-- =====================================================================
alter table public.events
  alter column service_id drop not null,
  alter column class_id drop not null,
  add column recurrence text not null default 'once'
    check (recurrence in ('once', 'weekly')),
  add column weekdays smallint[] check (
    weekdays is null or (
      array_length(weekdays, 1) >= 1
      and weekdays <@ array[0,1,2,3,4,5,6]::smallint[]
    )
  ),
  add column start_time time,
  add column end_time time,
  add column points integer not null default 1 check (points >= 0);

comment on column public.events.weekdays is
  '0=Sunday .. 6=Saturday (Africa/Cairo). Used when recurrence = weekly.';
comment on column public.events.start_time is 'Africa/Cairo local time';
comment on column public.events.end_time is 'Africa/Cairo local time';

-- scope chain consistency: if service_id is null, class_id must be null
alter table public.events add constraint events_scope_chain
  check (service_id is not null or class_id is null);

-- =====================================================================
-- 2. CAUSES: points + nullable scope
-- =====================================================================
alter table public.causes
  alter column service_id drop not null,
  alter column class_id drop not null,
  add column points integer not null default 1 check (points >= 0);

alter table public.causes add constraint causes_scope_chain
  check (service_id is not null or class_id is null);

-- =====================================================================
-- 3. Scope helpers + RLS rebuild
--    scope_overlaps: viewer scope and target scope intersect (SELECT).
--    scope_contains: viewer scope fully contains target scope (WRITE).
--    Target: p_service / p_class null = "all" under the parent.
--    Viewer: profile null scope cascades as in 0006 (null = all).
-- =====================================================================
create or replace function public.scope_overlaps(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select case public.my_role()
    when 'owner' then true
    when 'church_manager' then p_church = public.my_church()
    when 'service_manager' then
      p_church = public.my_church()
      and (public.my_service() is null or p_service is null or p_service = public.my_service())
    when 'class_servant' then
      p_church = public.my_church()
      and (public.my_service() is null or p_service is null or p_service = public.my_service())
      and (public.my_class() is null or p_class is null or p_class = public.my_class())
    else false
  end
$$;

create or replace function public.scope_contains(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select case public.my_role()
    when 'owner' then true
    when 'church_manager' then p_church = public.my_church()
    when 'service_manager' then
      p_church = public.my_church()
      and (
        public.my_service() is null
        or (p_service is not null and p_service = public.my_service())
      )
    when 'class_servant' then
      p_church = public.my_church()
      and (
        public.my_service() is null
        or (p_service is not null and p_service = public.my_service())
      )
      and (
        public.my_class() is null
        or (p_class is not null and p_class = public.my_class())
      )
    else false
  end
$$;

-- events policies
drop policy if exists events_select on public.events;
drop policy if exists events_insert on public.events;
drop policy if exists events_update on public.events;
drop policy if exists events_delete on public.events;

create policy events_select on public.events for select using (
  public.scope_overlaps(church_id, service_id, class_id)
);
create policy events_insert on public.events for insert with check (
  public.scope_contains(church_id, service_id, class_id)
);
create policy events_update on public.events for update using (
  public.scope_contains(church_id, service_id, class_id)
) with check (
  public.scope_contains(church_id, service_id, class_id)
);
create policy events_delete on public.events for delete using (
  public.scope_contains(church_id, service_id, class_id)
);

-- causes policies
drop policy if exists causes_select on public.causes;
drop policy if exists causes_insert on public.causes;
drop policy if exists causes_update on public.causes;
drop policy if exists causes_delete on public.causes;

create policy causes_select on public.causes for select using (
  public.scope_overlaps(church_id, service_id, class_id)
);
create policy causes_insert on public.causes for insert with check (
  public.scope_contains(church_id, service_id, class_id)
);
create policy causes_update on public.causes for update using (
  public.scope_contains(church_id, service_id, class_id)
) with check (
  public.scope_contains(church_id, service_id, class_id)
);
create policy causes_delete on public.causes for delete using (
  public.scope_contains(church_id, service_id, class_id)
);

-- =====================================================================
-- 4. Attendance uniqueness: once per enrollment per event PER CAIRO DAY
--    (weekly events repeat — each occurrence day is a fresh attendance)
-- =====================================================================
alter table public.attendance_log
  add column attended_on date not null
    default ((now() at time zone 'Africa/Cairo')::date);

-- backfill legacy rows with their creation day (Cairo)
update public.attendance_log
   set attended_on = (created_at at time zone 'Africa/Cairo')::date;

drop index if exists public.uq_attendance_enrollment_event;
create unique index uq_attendance_enrollment_event_day
  on public.attendance_log(enrollment_id, event_id, attended_on)
  where event_id is not null;

-- =====================================================================
-- 5. Scope-check triggers: enrollment must fall INSIDE event/cause scope
-- =====================================================================
create or replace function public.check_attendance_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1
      from public.events ev
      join public.enrollments en on en.id = new.enrollment_id
      where ev.id = new.event_id
        and ev.church_id = en.church_id
        and (ev.service_id is null or ev.service_id = en.service_id)
        and (ev.class_id is null or ev.class_id = en.class_id)
    ) then
      raise exception 'event does not apply to the enrollment scope';
    end if;
  end if;
  return new;
end $$;

create or replace function public.check_points_cause_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.cause_id is not null then
    if not exists (
      select 1
      from public.causes ca
      join public.enrollments en on en.id = new.enrollment_id
      where ca.id = new.cause_id
        and ca.church_id = en.church_id
        and (ca.service_id is null or ca.service_id = en.service_id)
        and (ca.class_id is null or ca.class_id = en.class_id)
    ) then
      raise exception 'cause does not apply to the enrollment scope';
    end if;
  end if;
  return new;
end $$;



-- #####################################################################
-- ##  0015_default_and_points_mode.sql
-- #####################################################################

-- 0015: default event/cause + points mode
--
-- 1. is_default: one event & one cause can be marked as the DEFAULT so the
--    children / scanner pages preselect it automatically.
--    (The app clears other defaults when a new one is set.)
--
-- 2. points_mode: how the points amount behaves when recording:
--    'fixed'    -> the bound number cannot be changed
--    'editable' -> the bound number is the default but can be changed
--    'open'     -> no bound number; the servant enters it each time

alter table public.events
  add column if not exists is_default boolean not null default false,
  add column if not exists points_mode text not null default 'fixed';

alter table public.causes
  add column if not exists is_default boolean not null default false,
  add column if not exists points_mode text not null default 'fixed';

-- check constraints (added separately so re-runs don't fail)
do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'events_points_mode_check'
  ) then
    alter table public.events
      add constraint events_points_mode_check
      check (points_mode in ('open', 'editable', 'fixed'));
  end if;

  if not exists (
    select 1 from pg_constraint where conname = 'causes_points_mode_check'
  ) then
    alter table public.causes
      add constraint causes_points_mode_check
      check (points_mode in ('open', 'editable', 'fixed'));
  end if;
end $$;

-- helpful partial indexes for the "find the default" query
create index if not exists idx_events_default on public.events (church_id) where is_default;
create index if not exists idx_causes_default on public.causes (church_id) where is_default;


-- #####################################################################
-- ##  0016_data_job_delete.sql
-- #####################################################################

-- =====================================================================
-- 0016: DATA JOB — view / edit / delete a person from the children page
--
-- 1. Enrollment delete: anyone who can access the enrollment scope may
--    remove the person FROM that class/service/church (previously only
--    owner / church_manager / service_manager).
--    FK cascade: enrollment -> attendance, attendance_log, points_log.
--
-- 2. delete_person_cascade RPC: delete the person COMPLETELY from the
--    database. FK cascade removes ALL his enrollments and every log row
--    that references them (attendance / attendance_log / points_log).
--    Allowed for the owner, or for a user who can access EVERY
--    enrollment of the person (so nobody wipes data of another scope).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Enrollment delete follows the same scope rule as insert/update
-- ---------------------------------------------------------------------
drop policy if exists enrollments_delete on public.enrollments;
create policy enrollments_delete on public.enrollments for delete using (
  public.can_access(church_id, service_id, class_id)
);

-- ---------------------------------------------------------------------
-- 2. Full cascade delete of a person (all enrollments + all logs)
-- ---------------------------------------------------------------------
create or replace function public.delete_person_cascade(p_person uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.my_role() is null then
    raise exception 'not_approved' using errcode = '42501';
  end if;

  if not public.is_owner() then
    -- The user must be able to access EVERY enrollment of this person —
    -- otherwise he would be wiping data belonging to another scope.
    if exists (
      select 1 from public.enrollments e
       where e.person_id = p_person
         and not public.can_access(e.church_id, e.service_id, e.class_id)
    ) then
      raise exception 'no_access' using errcode = '42501';
    end if;

    -- Person without any enrollment: only his creator (or owner) may delete
    if not exists (select 1 from public.enrollments e where e.person_id = p_person) then
      if not exists (
        select 1 from public.persons p
         where p.id = p_person and p.created_by = auth.uid()
      ) then
        raise exception 'no_access' using errcode = '42501';
      end if;
    end if;
  end if;

  -- FK cascade: persons -> enrollments -> attendance / attendance_log / points_log
  delete from public.persons where id = p_person;
end $$;



-- #####################################################################
-- ##  0017_card_templates.sql
-- #####################################################################

-- =====================================================================
-- 0017: CARD TEMPLATES — design ID cards for the children (persons)
--
-- One row per template. The visual design + print settings are stored
-- as JSONB (schema versioned in app code: src/lib/card-types.ts).
-- Scoped to church / service / class exactly like events & causes
-- (null service/class = whole church / whole service).
-- =====================================================================


create table public.card_templates (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  name        text not null,
  design         jsonb not null default '{}'::jsonb,
  print_settings jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.profiles(id)
);

create index idx_card_templates_church on public.card_templates(church_id);

create trigger trg_card_templates_touch before update on public.card_templates
for each row execute function public.touch_edited();

-- RLS: same scope rules as events / causes
alter table public.card_templates enable row level security;

create policy card_templates_select on public.card_templates for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy card_templates_insert on public.card_templates for insert with check (
  public.can_access(church_id, service_id, class_id)
);
create policy card_templates_update on public.card_templates for update using (
  public.can_access(church_id, service_id, class_id)
) with check (
  public.can_access(church_id, service_id, class_id)
);
create policy card_templates_delete on public.card_templates for delete using (
  public.can_access(church_id, service_id, class_id)
);



-- #####################################################################
-- ##  0018_card_print_requests.sql
-- #####################################################################

-- =====================================================================
-- 0018: CARD PRINT REQUESTS — "طباعة كارت" job on the children page
--
-- A servant taps the print-card button on a child → a request row is
-- created here. The print page (تصميم الكروت → الطباعة) can then print
-- from the requested list and delete one / a group / all of them.
--
-- One PENDING request per enrollment (unique) → inserting a duplicate
-- fails with 23505 and the app tells the user it's already requested.
-- =====================================================================


create table public.card_print_requests (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  -- denormalized scope (copied from the enrollment) so the print page can
  -- filter by church / service / class without joins in RLS
  church_id     uuid not null references public.churches(id) on delete cascade,
  service_id    uuid not null references public.services(id) on delete cascade,
  class_id      uuid not null references public.classes(id) on delete cascade,
  requested_by  uuid references public.profiles(id),
  created_at    timestamptz not null default now(),
  unique (enrollment_id)
);

create index idx_card_print_requests_church  on public.card_print_requests(church_id);
create index idx_card_print_requests_service on public.card_print_requests(service_id);
create index idx_card_print_requests_class   on public.card_print_requests(class_id);

comment on table public.card_print_requests is
  'طلبات طباعة الكروت — يرسلها الخادم من صفحة المخدومين وتُطبع من صفحة الطباعة';

-- keep the denormalized scope in sync with the enrollment on insert
create or replace function public.card_print_request_fill_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  select e.church_id, e.service_id, e.class_id
    into new.church_id, new.service_id, new.class_id
  from public.enrollments e where e.id = new.enrollment_id;
  if new.church_id is null then
    raise exception 'enrollment not found';
  end if;
  return new;
end $$;

create trigger trg_card_print_request_scope
before insert on public.card_print_requests
for each row execute function public.card_print_request_fill_scope();

-- RLS: same scope rules as everything else
alter table public.card_print_requests enable row level security;

create policy card_print_requests_select on public.card_print_requests for select using (
  public.can_access(church_id, service_id, class_id)
);
create policy card_print_requests_insert on public.card_print_requests for insert with check (
  exists (
    select 1 from public.enrollments e
    where e.id = enrollment_id
      and public.can_access(e.church_id, e.service_id, e.class_id)
  )
);
create policy card_print_requests_delete on public.card_print_requests for delete using (
  public.can_access(church_id, service_id, class_id)
);

-- realtime so the requested list updates live on the print page
alter publication supabase_realtime add table public.card_print_requests;



-- #####################################################################
-- ##  0019_performance_rls_indexes_rpc.sql
-- #####################################################################

-- =====================================================================
-- 0019: PERFORMANCE & STABILITY
--
-- Goal: make the app usable for a whole diocese (tens of thousands of
-- persons, hundreds of servants online at once) on the cheapest
-- Supabase tier, by removing the three things that made cost grow
-- quadratically with data size:
--
--   1. RLS helper calls are wrapped in `(select ...)` so Postgres
--      evaluates them ONCE PER QUERY (InitPlan) instead of ONCE PER ROW.
--      This is Supabase's documented RLS performance recommendation and is
--      typically a 10–100x speedup on the persons / enrollments queries.
--
--   2. Scope helpers (my_role / my_church / my_service / my_class) are
--      collapsed into ONE profile lookup (`my_scope()`), and the
--      per-row `can_access(...)` is rewritten as a pure expression over
--      that single cached row — no nested function calls per row.
--
--   3. Missing indexes for the exact filters the app uses
--      (attendance_log(event_id, attended_on), persons(phone),
--       enrollments(class_id, person_id), events/causes by church…).
--
--   4. Aggregation RPCs so the stats / home pages fetch NUMBERS, not
--      every row: `stats_summary()`, `stats_week()`, `stats_leaderboard()`,
--      plus `lookup_enrollments_by_national_id()` for the QR scanner so it
--      never needs the whole enrollments table in memory.
--
-- Everything is idempotent (drop/create) and preserves the exact access
-- semantics of migrations 0006 / 0011 / 0012 / 0014 / 0016 / 0017 / 0018.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Single cached scope lookup
-- ---------------------------------------------------------------------
create or replace function public.my_scope()
returns table (role public.app_role, church_id uuid, service_id uuid, class_id uuid)
language sql stable security definer set search_path = public as $$
  select role, church_id, service_id, class_id
    from public.profiles
   where id = auth.uid() and status = 'approved'
$$;

-- Keep the old helpers (other code / policies still reference them) but
-- make them read from the same single-row lookup.
create or replace function public.my_role() returns public.app_role
language sql stable security definer set search_path = public as
$$ select role from public.my_scope() $$;

create or replace function public.my_church() returns uuid
language sql stable security definer set search_path = public as
$$ select church_id from public.my_scope() $$;

create or replace function public.my_service() returns uuid
language sql stable security definer set search_path = public as
$$ select service_id from public.my_scope() $$;

create or replace function public.my_class() returns uuid
language sql stable security definer set search_path = public as
$$ select class_id from public.my_scope() $$;

create or replace function public.is_owner() returns boolean
language sql stable security definer set search_path = public as
$$ select coalesce((select role from public.my_scope()) = 'owner', false) $$;

-- can_access: identical truth table to 0006, but ONE profile read.
create or replace function public.can_access(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        (s.service_id is null and p_church = s.church_id)
        or p_service = s.service_id
      when 'class_servant' then
        (s.class_id is null and (
          (s.service_id is null and p_church = s.church_id)
          or p_service = s.service_id
        ))
        or p_class = s.class_id
      else false
    end
    from public.my_scope() s
  ), false)
$$;

-- scope_overlaps / scope_contains (events, causes) — same semantics as 0014
create or replace function public.scope_overlaps(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        p_church = s.church_id
        and (s.service_id is null or p_service is null or p_service = s.service_id)
      when 'class_servant' then
        p_church = s.church_id
        and (s.service_id is null or p_service is null or p_service = s.service_id)
        and (s.class_id is null or p_class is null or p_class = s.class_id)
      else false
    end
    from public.my_scope() s
  ), false)
$$;

create or replace function public.scope_contains(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        p_church = s.church_id
        and (s.service_id is null or (p_service is not null and p_service = s.service_id))
      when 'class_servant' then
        p_church = s.church_id
        and (s.service_id is null or (p_service is not null and p_service = s.service_id))
        and (s.class_id is null or (p_class is not null and p_class = s.class_id))
      else false
    end
    from public.my_scope() s
  ), false)
$$;

-- ---------------------------------------------------------------------
-- 2. Indexes for the filters the app actually issues
-- ---------------------------------------------------------------------
create index if not exists idx_attendance_log_event_day
  on public.attendance_log(event_id, attended_on);
create index if not exists idx_attendance_log_attended_on
  on public.attendance_log(attended_on);
create index if not exists idx_attendance_log_enrollment_created
  on public.attendance_log(enrollment_id, created_at desc);
create index if not exists idx_points_log_enrollment_created
  on public.points_log(enrollment_id, created_at desc);
create index if not exists idx_enrollments_class_person
  on public.enrollments(class_id, person_id);
create index if not exists idx_enrollments_service_class
  on public.enrollments(service_id, class_id);
create index if not exists idx_enrollments_church_service
  on public.enrollments(church_id, service_id);
create index if not exists idx_enrollments_points_desc
  on public.enrollments(points desc);
create index if not exists idx_persons_phone on public.persons(phone);
create index if not exists idx_persons_created_by on public.persons(created_by);
create index if not exists idx_events_church on public.events(church_id);
create index if not exists idx_events_service on public.events(service_id);
create index if not exists idx_causes_church on public.causes(church_id);
create index if not exists idx_causes_service on public.causes(service_id);
create index if not exists idx_profiles_service on public.profiles(service_id);
create index if not exists idx_profiles_class on public.profiles(class_id);
create index if not exists idx_card_print_requests_enrollment
  on public.card_print_requests(enrollment_id);

-- ---------------------------------------------------------------------
-- 3. Policies rewritten with (select ...) so the helper is an InitPlan
--    evaluated once per statement rather than once per row.
-- ---------------------------------------------------------------------

-- ---------- CHURCHES ----------
drop policy if exists churches_select on public.churches;
create policy churches_select on public.churches for select using (
  (select public.is_owner()) or id = (select public.my_church())
);
drop policy if exists churches_update on public.churches;
create policy churches_update on public.churches for update using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and id = (select public.my_church()))
);

-- ---------- SERVICES ----------
drop policy if exists services_select on public.services;
create policy services_select on public.services for select using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) in ('service_manager','class_servant') and (
       id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);
drop policy if exists services_update on public.services;
create policy services_update on public.services for update using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);

-- ---------- CLASSES ----------
drop policy if exists classes_select on public.classes;
create policy classes_select on public.classes for select using (
  (select public.is_owner())
  or (
    -- inline can_access(church_id, service_id, id) against the cached scope
    exists (
      select 1 from public.my_scope() s
      where case s.role
        when 'church_manager' then classes.church_id = s.church_id
        when 'service_manager' then
          (s.service_id is null and classes.church_id = s.church_id)
          or classes.service_id = s.service_id
        when 'class_servant' then
          (s.class_id is null and (
            (s.service_id is null and classes.church_id = s.church_id)
            or classes.service_id = s.service_id
          ))
          or classes.id = s.class_id
        else false
      end
    )
  )
);

-- ---------- PROFILES ----------
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles for select using (
  id = auth.uid()
  or (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);
drop policy if exists profiles_update_mgmt on public.profiles;
create policy profiles_update_mgmt on public.profiles for update using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);
drop policy if exists profiles_delete on public.profiles;
create policy profiles_delete on public.profiles for delete using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);

-- ---------- ENROLLMENTS ----------
-- The heaviest table. Inline the access rule as a plain expression over the
-- single cached scope row (one InitPlan), so the planner can use the
-- church/service/class indexes directly.
create or replace function public.enrollment_visible(p_church uuid, p_service uuid, p_class uuid,
                                                     s_role public.app_role, s_church uuid,
                                                     s_service uuid, s_class uuid)
returns boolean language sql immutable as $$
  select case s_role
    when 'owner' then true
    when 'church_manager' then p_church = s_church
    when 'service_manager' then (s_service is null and p_church = s_church) or p_service = s_service
    when 'class_servant' then
      (s_class is null and ((s_service is null and p_church = s_church) or p_service = s_service))
      or p_class = s_class
    else false
  end
$$;

drop policy if exists enrollments_select on public.enrollments;
create policy enrollments_select on public.enrollments for select using (
  public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists enrollments_insert on public.enrollments;
create policy enrollments_insert on public.enrollments for insert with check (
  public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists enrollments_update on public.enrollments;
create policy enrollments_update on public.enrollments for update using (
  public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists enrollments_delete on public.enrollments;
create policy enrollments_delete on public.enrollments for delete using (
  public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);

-- ---------- PERSONS ----------
-- Visible when created by me, or I can see ANY enrollment of that person.
-- The EXISTS uses idx_enrollments_person and the inlined visibility rule.
drop policy if exists persons_select on public.persons;
create policy persons_select on public.persons for select using (
  created_by = auth.uid()
  or (select public.is_owner())
  or exists (
    select 1 from public.enrollments e
     where e.person_id = persons.id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);
drop policy if exists persons_insert on public.persons;
create policy persons_insert on public.persons for insert with check (
  (select public.my_role()) is not null
);
drop policy if exists persons_update on public.persons;
create policy persons_update on public.persons for update using (
  created_by = auth.uid()
  or (select public.is_owner())
  or exists (
    select 1 from public.enrollments e
     where e.person_id = persons.id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);
drop policy if exists persons_delete on public.persons;
create policy persons_delete on public.persons for delete using ((select public.is_owner()));

-- ---------- ATTENDANCE_LOG / POINTS_LOG ----------
-- Join to the (already RLS-filtered-by-expression) enrollment once.
drop policy if exists attendance_log_select on public.attendance_log;
create policy attendance_log_select on public.attendance_log for select using (
  exists (
    select 1 from public.enrollments e
     where e.id = attendance_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);
drop policy if exists attendance_log_insert on public.attendance_log;
create policy attendance_log_insert on public.attendance_log for insert with check (
  recorded_by = auth.uid() and exists (
    select 1 from public.enrollments e
     where e.id = attendance_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);
drop policy if exists attendance_log_delete on public.attendance_log;
create policy attendance_log_delete on public.attendance_log for delete using (
  exists (
    select 1 from public.enrollments e
     where e.id = attendance_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
