-- ---------------------------------------------------------------------
-- 4. Aggregation / lookup RPCs — fetch numbers, not rows
--    All run as the caller (security invoker) so RLS still applies.
-- ---------------------------------------------------------------------

-- Totals for the stats page (optionally narrowed by scope)
create or replace function public.stats_summary(
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (enrollments bigint, persons bigint, total_attendance bigint, total_points bigint)
language sql stable security invoker set search_path = public as $$
  select count(*)::bigint,
         count(distinct person_id)::bigint,
         coalesce(sum(attendance_count), 0)::bigint,
         coalesce(sum(points), 0)::bigint
    from public.enrollments
   where (p_church  is null or church_id  = p_church)
     and (p_service is null or service_id = p_service)
     and (p_class   is null or class_id   = p_class)
$$;

-- Attendance per Cairo day for the last N days (default 7)
create or replace function public.stats_week(
  p_days int default 7,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (day date, count bigint)
language sql stable security invoker set search_path = public as $$
  select a.attended_on, count(*)::bigint
    from public.attendance_log a
    join public.enrollments e on e.id = a.enrollment_id
   where a.attended_on >= ((now() at time zone 'Africa/Cairo')::date - (p_days - 1))
     and (p_church  is null or e.church_id  = p_church)
     and (p_service is null or e.service_id = p_service)
     and (p_class   is null or e.class_id   = p_class)
   group by a.attended_on
   order by a.attended_on
$$;

-- Top-N leaderboard (default 10)
create or replace function public.stats_leaderboard(
  p_limit int default 10,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (enrollment_id uuid, person_id uuid, name text, points integer, attendance_count integer)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, p.name, e.points, e.attendance_count
    from public.enrollments e
    join public.persons p on p.id = e.person_id
   where (p_church  is null or e.church_id  = p_church)
     and (p_service is null or e.service_id = p_service)
     and (p_class   is null or e.class_id   = p_class)
   order by e.points desc, p.name
   limit greatest(1, least(p_limit, 100))
$$;

-- Home dashboard: every counter in ONE round-trip
create or replace function public.dashboard_counts(p_today_start timestamptz)
returns table (
  persons bigint, enrollments bigint, today_attendance bigint,
  pending_servants bigint, churches bigint, services bigint, classes bigint)
language sql stable security invoker set search_path = public as $$
  select
    (select count(distinct person_id) from public.enrollments),
    (select count(*) from public.enrollments),
    (select count(*) from public.attendance_log where created_at >= p_today_start),
    (select count(*) from public.profiles where status = 'pending'),
    (select count(*) from public.churches),
    (select count(*) from public.services),
    (select count(*) from public.classes)
$$;

-- QR scanner: national id -> that person's enrollments in my scope.
-- Returns the same shape the app uses (enrollment + embedded person).
create or replace function public.lookup_enrollments_by_national_id(p_national_id text)
returns table (
  id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  attendance_count integer, points integer, created_at timestamptz,
  person jsonb)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, e.church_id, e.service_id, e.class_id,
         e.attendance_count, e.points, e.created_at,
         to_jsonb(p) as person
    from public.persons p
    join public.enrollments e on e.person_id = p.id
   where p.national_id = p_national_id
   order by e.created_at
$$;

grant execute on function public.stats_summary(uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_week(int, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_leaderboard(int, uuid, uuid, uuid) to authenticated;
grant execute on function public.dashboard_counts(timestamptz) to authenticated;
grant execute on function public.lookup_enrollments_by_national_id(text) to authenticated;
grant execute on function public.my_scope() to authenticated, anon;
grant execute on function public.enrollment_visible(uuid, uuid, uuid, public.app_role, uuid, uuid, uuid) to authenticated, anon;

-- ---------------------------------------------------------------------
-- 5. Make sure the planner has fresh statistics for the new indexes
-- ---------------------------------------------------------------------
analyze public.persons;
analyze public.enrollments;
analyze public.attendance_log;
analyze public.points_log;



-- #####################################################################
-- ##  0020_statistics_rpcs.sql
-- #####################################################################

-- =====================================================================
-- 0020: STATISTICS TAB — comprehensive aggregation RPCs
--
-- The rebuilt الإحصائيات tab is driven by three scope selectors
-- (church / service / class — each with a "كل الـ..." = null option), a
-- selected day (the header working date) and a period + granularity for
-- the timeline chart. Every number on the screen comes from ONE of the
-- functions below, so the browser never downloads log rows — cost grows
-- with the number of events / causes / buckets, not with the size of the
-- diocese.
--
-- All functions are SECURITY INVOKER → RLS on enrollments / attendance_log
-- / points_log / events / causes still applies, so a class servant only
-- ever aggregates what he is allowed to see.
--
-- Scope arguments: p_church / p_service / p_class — null means "all".
-- Dates are Cairo calendar days ('YYYY-MM-DD', the app's attended_on).
-- Everything is idempotent (create or replace).
--
--   stats_scope_summary       — headline KPIs for the scope
--   stats_day_summary         — KPIs of ONE selected day
--   stats_attendance_by_event — attendance on a day, grouped by event
--   stats_points_by_cause     — points granted on a day, grouped by cause
--   stats_attendance_timeline — attendance per bucket (day/week/month) × event
--   stats_points_timeline     — points per bucket (day/week/month) × cause
--   stats_attendance_by_class — attendance on a day per class (breakdown)
--   stats_leaderboard_scoped  — top-N by points / attendance for the scope
--   stats_weekday_profile     — attendance by weekday over a period
-- =====================================================================


-- ---------------------------------------------------------------------
-- Scope helper: the enrollments this statistic is about.
-- (inlined into each function as a WHERE clause — kept here as doc)
--   (p_church  is null or e.church_id  = p_church)
--   (p_service is null or e.service_id = p_service)
--   (p_class   is null or e.class_id   = p_class)
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 1. Headline KPIs of the scope (all time)
-- ---------------------------------------------------------------------
drop function if exists public.stats_scope_summary(uuid, uuid, uuid);
create or replace function public.stats_scope_summary(
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  enrollments      bigint,   -- إجمالي التسجيلات
  persons          bigint,   -- إجمالي المخدومين (distinct persons)
  males            bigint,
  females          bigint,
  total_attendance bigint,   -- sum(enrollments.attendance_count)
  total_points     bigint,   -- sum(enrollments.points) — current balance
  attendance_points bigint,  -- points that came with attendance (all time)
  cause_points_added bigint, -- positive cause deltas (all time)
  cause_points_removed bigint, -- abs(negative cause deltas) (all time)
  events_count     bigint,   -- events applying to the scope
  causes_count     bigint,   -- causes applying to the scope
  classes_count    bigint,   -- distinct classes with enrollments in scope
  first_attendance date,     -- earliest attended_on in scope
  last_attendance  date      -- latest attended_on in scope
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id,
           e.attendance_count, e.points
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  )
  select
    (select count(*) from sc),
    (select count(distinct person_id) from sc),
    (select count(distinct sc.person_id) from sc join public.persons p on p.id = sc.person_id where p.gender = 'male'),
    (select count(distinct sc.person_id) from sc join public.persons p on p.id = sc.person_id where p.gender = 'female'),
    (select coalesce(sum(attendance_count), 0) from sc),
    (select coalesce(sum(points), 0) from sc),
    (select coalesce(sum(a.points_delta), 0) from public.attendance_log a join sc on sc.id = a.enrollment_id),
    (select coalesce(sum(l.delta), 0) from public.points_log l join sc on sc.id = l.enrollment_id where l.delta > 0),
    (select coalesce(-sum(l.delta), 0) from public.points_log l join sc on sc.id = l.enrollment_id where l.delta < 0),
    (select count(*) from public.events ev
      where (p_church  is null or ev.church_id = p_church)
        and (p_service is null or ev.service_id is null or ev.service_id = p_service)
        and (p_class   is null or ev.class_id   is null or ev.class_id   = p_class)),
    (select count(*) from public.causes ca
      where (p_church  is null or ca.church_id = p_church)
        and (p_service is null or ca.service_id is null or ca.service_id = p_service)
        and (p_class   is null or ca.class_id   is null or ca.class_id   = p_class)),
    (select count(distinct class_id) from sc),
    (select min(a.attended_on) from public.attendance_log a join sc on sc.id = a.enrollment_id),
    (select max(a.attended_on) from public.attendance_log a join sc on sc.id = a.enrollment_id)
$$;

-- ---------------------------------------------------------------------
-- 2. KPIs of ONE selected day
-- ---------------------------------------------------------------------
drop function if exists public.stats_day_summary(date, uuid, uuid, uuid);
create or replace function public.stats_day_summary(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  attendance        bigint,  -- attendance rows on the day
  attendees         bigint,  -- distinct persons who attended
  events_attended   bigint,  -- distinct events with ≥1 attendance
  attendance_points bigint,  -- points granted with attendance
  cause_points_added   bigint,
  cause_points_removed bigint,
  cause_entries     bigint,  -- points_log rows on the day
  causes_used       bigint,  -- distinct causes used
  scope_persons     bigint   -- persons in scope (denominator for %)
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  att as (
    select a.*, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  ),
  pts as (
    select l.*
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date = p_day
  )
  select
    (select count(*) from att),
    (select count(distinct person_id) from att),
    (select count(distinct event_id) from att where event_id is not null),
    (select coalesce(sum(points_delta), 0) from att),
    (select coalesce(sum(delta), 0) from pts where delta > 0),
    (select coalesce(-sum(delta), 0) from pts where delta < 0),
    (select count(*) from pts),
    (select count(distinct cause_id) from pts where cause_id is not null),
    (select count(distinct person_id) from sc)
$$;

-- ---------------------------------------------------------------------
-- 3. Attendance on a day, grouped by EVENT (sorted by event)
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_by_event(date, uuid, uuid, uuid);
create or replace function public.stats_attendance_by_event(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  event_id      uuid,
  event_name    text,
  church_id     uuid,     -- to disambiguate same-named events across churches
  event_scope   text,     -- 'church' | 'service' | 'class'
  attendance    bigint,   -- rows
  attendees     bigint,   -- distinct persons
  points        bigint,   -- sum(points_delta)
  eligible      bigint,   -- enrollments in scope the event applies to
  first_at      timestamptz,
  last_at       timestamptz
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  att as (
    select a.event_id, a.points_delta, a.created_at, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  ),
  grp as (
    select event_id,
           count(*)::bigint as attendance,
           count(distinct person_id)::bigint as attendees,
           coalesce(sum(points_delta), 0)::bigint as points,
           min(created_at) as first_at,
           max(created_at) as last_at
      from att group by event_id
  )
  select g.event_id,
         coalesce(ev.name, 'بدون مناسبة') as event_name,
         ev.church_id,
         case when ev.id is null then 'church'
              when ev.class_id is not null then 'class'
              when ev.service_id is not null then 'service'
              else 'church' end as event_scope,
         g.attendance, g.attendees, g.points,
         (select count(*) from sc
           where ev.id is not null
             and sc.church_id = ev.church_id
             and (ev.service_id is null or sc.service_id = ev.service_id)
             and (ev.class_id   is null or sc.class_id   = ev.class_id))::bigint as eligible,
         g.first_at, g.last_at
    from grp g
    left join public.events ev on ev.id = g.event_id
   order by event_name, g.event_id
$$;

-- ---------------------------------------------------------------------
-- 4. Points granted on a day, grouped by CAUSE (sorted by cause)
-- ---------------------------------------------------------------------
drop function if exists public.stats_points_by_cause(date, uuid, uuid, uuid);
create or replace function public.stats_points_by_cause(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  cause_id      uuid,
  cause_name    text,
  church_id     uuid,
  cause_scope   text,
  entries       bigint,   -- points_log rows
  recipients    bigint,   -- distinct persons
  added         bigint,   -- sum of positive deltas
  removed       bigint,   -- abs(sum of negative deltas)
  net           bigint,   -- added - removed
  first_at      timestamptz,
  last_at       timestamptz
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  pts as (
    select l.cause_id, l.delta, l.created_at, sc.person_id
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date = p_day
  ),
  grp as (
    select cause_id,
           count(*)::bigint as entries,
           count(distinct person_id)::bigint as recipients,
           coalesce(sum(case when delta > 0 then delta else 0 end), 0)::bigint as added,
           coalesce(sum(case when delta < 0 then -delta else 0 end), 0)::bigint as removed,
           coalesce(sum(delta), 0)::bigint as net,
           min(created_at) as first_at,
           max(created_at) as last_at
      from pts group by cause_id
  )
  select g.cause_id,
         coalesce(ca.name, 'بدون سبب') as cause_name,
         ca.church_id,
         case when ca.id is null then 'church'
              when ca.class_id is not null then 'class'
              when ca.service_id is not null then 'service'
              else 'church' end as cause_scope,
         g.entries, g.recipients, g.added, g.removed, g.net, g.first_at, g.last_at
    from grp g
    left join public.causes ca on ca.id = g.cause_id
   order by cause_name, g.cause_id
$$;

-- ---------------------------------------------------------------------
-- 5. Attendance TIMELINE — per bucket × event over a period
--    p_bucket: 'day' | 'week' | 'month'. Buckets are Cairo calendar
--    days / ISO weeks (Monday start) / months, returned as the bucket's
--    first day. The client fills empty buckets with zero.
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_timeline(date, date, text, uuid, uuid, uuid);
create or replace function public.stats_attendance_timeline(
  p_from date, p_to date, p_bucket text default 'day',
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  bucket      date,
  event_id    uuid,
  event_name  text,
  church_id   uuid,
  attendance  bigint,
  attendees   bigint,
  points      bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  att as (
    select case lower(coalesce(p_bucket, 'day'))
             when 'week'  then date_trunc('week',  a.attended_on::timestamp)::date
             when 'month' then date_trunc('month', a.attended_on::timestamp)::date
             else a.attended_on
           end as bucket,
           a.event_id, a.points_delta, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on between p_from and p_to
  )
  select att.bucket, att.event_id,
         coalesce(ev.name, 'بدون مناسبة') as event_name,
         ev.church_id,
         count(*)::bigint,
         count(distinct att.person_id)::bigint,
         coalesce(sum(att.points_delta), 0)::bigint
    from att
    left join public.events ev on ev.id = att.event_id
   group by att.bucket, att.event_id, ev.name, ev.church_id
   order by att.bucket, event_name
$$;

-- ---------------------------------------------------------------------
-- 6. Points TIMELINE — per bucket × cause over a period
-- ---------------------------------------------------------------------
drop function if exists public.stats_points_timeline(date, date, text, uuid, uuid, uuid);
create or replace function public.stats_points_timeline(
  p_from date, p_to date, p_bucket text default 'day',
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  bucket      date,
  cause_id    uuid,
  cause_name  text,
  church_id   uuid,
  entries     bigint,
  added       bigint,
  removed     bigint,
  net         bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  pts as (
    select (l.created_at at time zone 'Africa/Cairo')::date as day, l.cause_id, l.delta
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date between p_from and p_to
  ),
  b as (
    select case lower(coalesce(p_bucket, 'day'))
             when 'week'  then date_trunc('week',  day::timestamp)::date
             when 'month' then date_trunc('month', day::timestamp)::date
             else day
           end as bucket, cause_id, delta
      from pts
  )
  select b.bucket, b.cause_id,
         coalesce(ca.name, 'بدون سبب') as cause_name,
         ca.church_id,
         count(*)::bigint,
         coalesce(sum(case when b.delta > 0 then b.delta else 0 end), 0)::bigint,
         coalesce(sum(case when b.delta < 0 then -b.delta else 0 end), 0)::bigint,
         coalesce(sum(b.delta), 0)::bigint
    from b
    left join public.causes ca on ca.id = b.cause_id
   group by b.bucket, b.cause_id, ca.name, ca.church_id
   order by b.bucket, cause_name
$$;

-- ---------------------------------------------------------------------
-- 7. Attendance on a day per CLASS (with % of enrolled)
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_by_class(date, uuid, uuid, uuid);
create or replace function public.stats_attendance_by_class(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  class_id     uuid,
  class_name   text,
  service_name text,
  church_name  text,
  enrolled     bigint,
  attendees    bigint,   -- distinct persons attended (any event)
  attendance   bigint,   -- rows
  points       bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.class_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  att as (
    select sc.class_id, sc.person_id, a.points_delta
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  )
  select c.id, c.name, s.name, ch.name,
         (select count(*) from sc where sc.class_id = c.id)::bigint,
         (select count(distinct person_id) from att where att.class_id = c.id)::bigint,
         (select count(*) from att where att.class_id = c.id)::bigint,
         (select coalesce(sum(points_delta), 0) from att where att.class_id = c.id)::bigint
    from public.classes c
    join public.services s on s.id = c.service_id
    join public.churches ch on ch.id = c.church_id
   where c.id in (select distinct class_id from sc)
   order by ch.name, s.name, c.name
$$;

-- ---------------------------------------------------------------------
-- 8. Leaderboard for the scope — by points or by attendance
-- ---------------------------------------------------------------------
drop function if exists public.stats_leaderboard_scoped(text, int, uuid, uuid, uuid);
create or replace function public.stats_leaderboard_scoped(
  p_by text default 'points', p_limit int default 10,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  enrollment_id uuid, person_id uuid, name text, image_url text,
  class_name text, points integer, attendance_count integer)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, p.name, p.image_url, c.name, e.points, e.attendance_count
    from public.enrollments e
    join public.persons p on p.id = e.person_id
    left join public.classes c on c.id = e.class_id
   where (p_church  is null or e.church_id  = p_church)
     and (p_service is null or e.service_id = p_service)
     and (p_class   is null or e.class_id   = p_class)
   order by
     case when lower(coalesce(p_by, 'points')) = 'attendance' then e.attendance_count else e.points end desc,
     case when lower(coalesce(p_by, 'points')) = 'attendance' then e.points else e.attendance_count end desc,
     p.name
   limit greatest(1, least(coalesce(p_limit, 10), 100))
$$;

-- ---------------------------------------------------------------------
-- 9. Weekday profile — attendance by weekday (0=Sun..6=Sat) over a period
-- ---------------------------------------------------------------------
drop function if exists public.stats_weekday_profile(date, date, uuid, uuid, uuid);
create or replace function public.stats_weekday_profile(
  p_from date, p_to date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (weekday int, attendance bigint, days_with_attendance bigint)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  )
  select extract(dow from a.attended_on)::int,
         count(*)::bigint,
         count(distinct a.attended_on)::bigint
    from public.attendance_log a join sc on sc.id = a.enrollment_id
   where a.attended_on between p_from and p_to
   group by 1 order by 1
$$;

-- ---------------------------------------------------------------------
-- Index for the points-by-day queries (Cairo-day expression)
-- ---------------------------------------------------------------------
create index if not exists idx_points_log_cairo_day
  on public.points_log (((created_at at time zone 'Africa/Cairo')::date));
create index if not exists idx_points_log_cause on public.points_log(cause_id);

-- ---------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------
grant execute on function public.stats_scope_summary(uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_day_summary(date, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_attendance_by_event(date, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_points_by_cause(date, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_attendance_timeline(date, date, text, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_points_timeline(date, date, text, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_attendance_by_class(date, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_leaderboard_scoped(text, int, uuid, uuid, uuid) to authenticated;
grant execute on function public.stats_weekday_profile(date, date, uuid, uuid, uuid) to authenticated;

analyze public.points_log;



-- #####################################################################
-- ##  0021_child_portal.sql
-- #####################################################################

-- =====================================================================
-- 0021: CHILD PORTAL (بوابة المخدوم)
--
-- A child opens the app, taps "دخول المخدوم" and scans his card QR
-- (= persons.national_id). He has NO Supabase auth account; the scanned
-- code is his bearer token. Every read/write of the portal goes through a
-- SECURITY DEFINER RPC that takes `p_national_id` and returns / touches
-- ONLY that person's rows. The RPCs are granted to `anon`, so the portal
-- works with the public anon key and RLS on the base tables stays intact
-- (anon still has no direct table access).
--
--   child_portal_profile(nid)           person + enrollments (+ scope names / logo)
--   child_portal_attendance(nid)        every attendance_log row of the person
--   child_portal_points(nid)            points_log + attendance points, merged
--   child_portal_requests(nid)          his data change requests
--   child_portal_submit_request(...)    ask to change data / photo  -> pending
--   child_portal_cancel_request(...)    withdraw a pending request
--
-- Servants side:
--   data_change_requests                table (RLS: managers of ANY of the
--                                       person's enrollments — class servant,
--                                       service manager, church manager, owner)
--   review_data_change_request(...)     approve (applies to persons) / reject
--
-- Storage: anon may upload ONLY under photos/child-requests/ so a child can
-- propose a new photo; it is copied to persons.image_url on approval.
-- Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. DATA CHANGE REQUESTS
-- ---------------------------------------------------------------------
create table if not exists public.data_change_requests (
  id             uuid primary key default gen_random_uuid(),
  person_id      uuid not null references public.persons(id) on delete cascade,
  kind           text not null check (kind in ('data', 'photo')),
  -- proposed values. data  -> {name?, birthdate?, gender?, phone?, address?}
  --                  photo -> {image_url}
  changes        jsonb not null default '{}'::jsonb,
  -- snapshot of the current values at request time (for the diff view)
  previous       jsonb not null default '{}'::jsonb,
  note           text,
  status         text not null default 'pending'
                 check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  decision_note  text,
  decided_by     uuid references public.profiles(id),
  decided_at     timestamptz,
  created_at     timestamptz not null default now()
);
create index if not exists idx_dcr_person_created on public.data_change_requests(person_id, created_at desc);
create index if not exists idx_dcr_status_created on public.data_change_requests(status, created_at desc);

comment on table public.data_change_requests is
  'طلبات تعديل البيانات من بوابة المخدوم — يوافق عليها أو يرفضها خادم الفصل / مسؤول الخدمة / مدير الكنيسة';

alter table public.data_change_requests enable row level security;
alter table public.data_change_requests replica identity full;

-- a manager may see / decide a request if he can access ANY enrollment of the person
create or replace function public.can_access_person(p_person uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.enrollments e
     where e.person_id = p_person
       and public.can_access(e.church_id, e.service_id, e.class_id)
  )
$$;
grant execute on function public.can_access_person(uuid) to authenticated;

drop policy if exists dcr_select on public.data_change_requests;
create policy dcr_select on public.data_change_requests for select to authenticated
  using (public.can_access_person(person_id));

drop policy if exists dcr_delete on public.data_change_requests;
create policy dcr_delete on public.data_change_requests for delete to authenticated
  using (public.can_access_person(person_id));

-- inserts / updates happen only through the RPCs below (security definer)

do $$
begin
  alter publication supabase_realtime add table public.data_change_requests;
exception when duplicate_object then null;
end $$;

-- ---------------------------------------------------------------------
-- 2. Helper — resolve the token (national id) to a person, or raise
-- ---------------------------------------------------------------------
create or replace function public.child_portal_person(p_national_id text)
returns public.persons language plpgsql stable security definer set search_path = public as $$
declare
  v public.persons;
begin
  if p_national_id is null or length(trim(p_national_id)) = 0 then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;
  select * into v from public.persons where national_id = trim(p_national_id);
  if not found then
    raise exception 'unknown_code' using errcode = 'P0002';
  end if;
  return v;
end $$;
revoke all on function public.child_portal_person(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. PROFILE — person + enrollments with names, logo, counters
-- ---------------------------------------------------------------------
create or replace function public.child_portal_profile(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
  enr jsonb;
begin
  p := public.child_portal_person(p_national_id);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id,
           'church_id', e.church_id,
           'service_id', e.service_id,
           'class_id', e.class_id,
           'attendance_count', e.attendance_count,
           'points', e.points,
           'created_at', e.created_at,
           'church_name', ch.name,
           'church_logo', ch.logo_url,
           'service_name', sv.name,
           'service_photo', sv.photo_url,
           'class_name', cl.name,
           'class_photo', cl.photo_url
         ) order by e.created_at), '[]'::jsonb)
    into enr
    from public.enrollments e
    join public.churches ch on ch.id = e.church_id
    join public.services sv on sv.id = e.service_id
    join public.classes  cl on cl.id = e.class_id
   where e.person_id = p.id;

  return jsonb_build_object(
    'person', jsonb_build_object(
      'id', p.id,
      'national_id', p.national_id,
      'name', p.name,
      'birthdate', p.birthdate,
      'gender', p.gender,
      'phone', p.phone,
      'address', p.address,
      'image_url', p.image_url,
      'created_at', p.created_at
    ),
    'enrollments', enr
  );
end $$;
grant execute on function public.child_portal_profile(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. ATTENDANCE — every attendance row of the person (all enrollments)
-- ---------------------------------------------------------------------
create or replace function public.child_portal_attendance(p_national_id text)
returns table (
  id uuid, enrollment_id uuid, event_id uuid, event_name text,
  points_delta integer, attended_on date, created_at timestamptz,
  recorded_by_name text, class_name text, service_name text, church_name text
) language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select a.id, a.enrollment_id, a.event_id, ev.name,
           a.points_delta, a.attended_on, a.created_at,
           pr.full_name, cl.name, sv.name, ch.name
      from public.attendance_log a
      join public.enrollments e on e.id = a.enrollment_id
      left join public.events   ev on ev.id = a.event_id
      left join public.profiles pr on pr.id = a.recorded_by
      join public.classes  cl on cl.id = e.class_id
      join public.services sv on sv.id = e.service_id
      join public.churches ch on ch.id = e.church_id
     where e.person_id = p.id
     order by a.attended_on desc, a.created_at desc;
end $$;
grant execute on function public.child_portal_attendance(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. POINTS — cause points + attendance points, merged, newest first
-- ---------------------------------------------------------------------
create or replace function public.child_portal_points(p_national_id text)
returns table (
  id uuid, enrollment_id uuid, source text, reason text,
  delta integer, created_at timestamptz, recorded_by_name text,
  class_name text, service_name text, church_name text
) language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select x.id, x.enrollment_id, x.source, x.reason, x.delta, x.created_at,
           pr.full_name, cl.name, sv.name, ch.name
      from (
        select pl.id, pl.enrollment_id, 'cause'::text as source,
               ca.name as reason, pl.delta, pl.created_at, pl.recorded_by
          from public.points_log pl
          join public.enrollments e on e.id = pl.enrollment_id
          left join public.causes ca on ca.id = pl.cause_id
         where e.person_id = p.id
        union all
        select a.id, a.enrollment_id, 'attendance'::text,
               ev.name, a.points_delta, a.created_at, a.recorded_by
          from public.attendance_log a
          join public.enrollments e on e.id = a.enrollment_id
          left join public.events ev on ev.id = a.event_id
         where e.person_id = p.id and a.points_delta <> 0
      ) x
      join public.enrollments e2 on e2.id = x.enrollment_id
      left join public.profiles pr on pr.id = x.recorded_by
      join public.classes  cl on cl.id = e2.class_id
      join public.services sv on sv.id = e2.service_id
      join public.churches ch on ch.id = e2.church_id
     order by x.created_at desc;
end $$;
grant execute on function public.child_portal_points(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. REQUESTS — list / submit / cancel
-- ---------------------------------------------------------------------
create or replace function public.child_portal_requests(p_national_id text)
returns setof public.data_change_requests
language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select * from public.data_change_requests
     where person_id = p.id
     order by created_at desc
     limit 100;
end $$;
grant execute on function public.child_portal_requests(text) to anon, authenticated;

create or replace function public.child_portal_submit_request(
  p_national_id text, p_kind text, p_changes jsonb, p_note text default null)
returns public.data_change_requests
language plpgsql security definer set search_path = public as $$
declare
  p public.persons;
  clean jsonb := '{}'::jsonb;
  prev  jsonb := '{}'::jsonb;
  r public.data_change_requests;
  k text;
  allowed text[] := array['name', 'birthdate', 'gender', 'phone', 'address'];
begin
  p := public.child_portal_person(p_national_id);

  if p_kind not in ('data', 'photo') then
    raise exception 'invalid_kind' using errcode = 'P0003';
  end if;

  -- one pending request per kind at a time
  if exists (select 1 from public.data_change_requests
              where person_id = p.id and kind = p_kind and status = 'pending') then
    raise exception 'pending_exists' using errcode = 'P0004';
  end if;

  if p_kind = 'photo' then
    if coalesce(p_changes->>'image_url', '') = '' then
      raise exception 'invalid_changes' using errcode = 'P0005';
    end if;
    clean := jsonb_build_object('image_url', p_changes->>'image_url');
    prev  := jsonb_build_object('image_url', p.image_url);
  else
    -- whitelist fields + keep only the ones that actually differ
    foreach k in array allowed loop
      if p_changes ? k then
        if k = 'gender' and coalesce(p_changes->>k, '') not in ('', 'male', 'female') then
          raise exception 'invalid_changes' using errcode = 'P0005';
        end if;
        if coalesce(p_changes->>k, '') is distinct from coalesce(
             case k
               when 'name' then p.name
               when 'birthdate' then p.birthdate::text
               when 'gender' then p.gender
               when 'phone' then p.phone
               when 'address' then p.address
             end, '') then
          clean := clean || jsonb_build_object(k, nullif(trim(p_changes->>k), ''));
          prev  := prev  || jsonb_build_object(k,
                     case k
                       when 'name' then to_jsonb(p.name)
                       when 'birthdate' then to_jsonb(p.birthdate)
                       when 'gender' then to_jsonb(p.gender)
                       when 'phone' then to_jsonb(p.phone)
                       when 'address' then to_jsonb(p.address)
                     end);
        end if;
      end if;
    end loop;
    if clean = '{}'::jsonb then
      raise exception 'no_changes' using errcode = 'P0006';
    end if;
    -- name may never be emptied
    if clean ? 'name' and clean->>'name' is null then
      raise exception 'invalid_changes' using errcode = 'P0005';
    end if;
  end if;

  insert into public.data_change_requests (person_id, kind, changes, previous, note)
  values (p.id, p_kind, clean, prev, nullif(trim(coalesce(p_note, '')), ''))
  returning * into r;
  return r;
end $$;
grant execute on function public.child_portal_submit_request(text, text, jsonb, text) to anon, authenticated;

create or replace function public.child_portal_cancel_request(p_national_id text, p_request uuid)
returns public.data_change_requests
language plpgsql security definer set search_path = public as $$
declare
  p public.persons;
  r public.data_change_requests;
begin
  p := public.child_portal_person(p_national_id);
  update public.data_change_requests
     set status = 'cancelled', decided_at = now()
   where id = p_request and person_id = p.id and status = 'pending'
  returning * into r;
  if not found then
    raise exception 'not_pending' using errcode = 'P0007';
  end if;
  return r;
end $$;
grant execute on function public.child_portal_cancel_request(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 7. REVIEW (servants) — approve applies the change to persons
-- ---------------------------------------------------------------------
create or replace function public.review_data_change_request(
  p_request uuid, p_approve boolean, p_note text default null)
returns public.data_change_requests
language plpgsql security definer set search_path = public as $$
declare
  r public.data_change_requests;
begin
  select * into r from public.data_change_requests where id = p_request for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0008';
  end if;
  if r.status <> 'pending' then
    raise exception 'not_pending' using errcode = 'P0007';
  end if;
  if not public.can_access_person(r.person_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if p_approve then
    if r.kind = 'photo' then
      update public.persons
         set image_url = r.changes->>'image_url',
             edited_at = now(), edited_by = auth.uid()
       where id = r.person_id;
    else
      update public.persons
         set name      = case when r.changes ? 'name'      then coalesce(r.changes->>'name', name) else name end,
             birthdate = case when r.changes ? 'birthdate' then (r.changes->>'birthdate')::date else birthdate end,
             gender    = case when r.changes ? 'gender'    then r.changes->>'gender' else gender end,
             phone     = case when r.changes ? 'phone'     then r.changes->>'phone' else phone end,
             address   = case when r.changes ? 'address'   then r.changes->>'address' else address end,
             edited_at = now(), edited_by = auth.uid()
       where id = r.person_id;
    end if;
  end if;

  update public.data_change_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         decision_note = nullif(trim(coalesce(p_note, '')), ''),
         decided_by = auth.uid(),
         decided_at = now()
   where id = p_request
  returning * into r;
  return r;
end $$;
revoke all on function public.review_data_change_request(uuid, boolean, text) from public, anon;
grant execute on function public.review_data_change_request(uuid, boolean, text) to authenticated;

-- pending requests count for the managers' badge (scoped by RLS through can_access_person)
create or replace function public.pending_data_requests_count()
returns integer language sql stable security invoker set search_path = public as $$
  select count(*)::int from public.data_change_requests where status = 'pending'
$$;
revoke all on function public.pending_data_requests_count() from public, anon;
grant execute on function public.pending_data_requests_count() to authenticated;

-- ---------------------------------------------------------------------
-- 8. STORAGE — child may upload a proposed photo under child-requests/
-- ---------------------------------------------------------------------
drop policy if exists "photos_child_request_upload" on storage.objects;
create policy "photos_child_request_upload" on storage.objects for insert to anon
  with check (bucket_id = 'photos' and (storage.foldername(name))[1] = 'child-requests');



-- #####################################################################
-- ##  0022_event_bound_operations.sql
-- #####################################################################

-- =====================================================================
-- 0022: EVENT-BOUND OPERATIONS
--
-- The hierarchy becomes  church → service → class → EVENT.
-- Every operation a servant performs on a child happens INSIDE an event:
--
--   attendance  → attendance_log.event_id   (already, since 0013)
--   points      → points_log.event_id       (NEW — nullable for legacy rows)
--   call / msg  → contact_log (NEW table)   — a follow-up made for an event
--
-- 1. points_log.event_id + scope check (event must apply to the enrollment)
-- 2. contact_log: kind = call | whatsapp | sms | internal, event_id,
--    template text (for messages), recorded_by. Used to know who was
--    followed up for an event (e.g. absent children who were called).
-- 3. RLS (same InitPlan pattern as 0019), indexes, realtime.
--
-- Idempotent — safe to re-run.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. POINTS ARE GIVEN INSIDE AN EVENT
-- ---------------------------------------------------------------------
alter table public.points_log
  add column if not exists event_id uuid references public.events(id) on delete set null;

create index if not exists idx_points_log_event on public.points_log(event_id);
create index if not exists idx_points_log_event_created on public.points_log(event_id, created_at desc);

-- The event must apply to the enrollment's scope (same rule as attendance)
create or replace function public.check_points_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1
      from public.events ev
      join public.enrollments en on en.id = new.enrollment_id
      where ev.id = new.event_id
        and ev.church_id = en.church_id
        and (ev.service_id is null or ev.service_id = en.service_id)
        and (ev.class_id is null or ev.class_id = en.class_id)
    ) then
      raise exception 'event does not apply to the enrollment scope';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_points_event_scope on public.points_log;
create trigger trg_points_event_scope before insert on public.points_log
for each row execute function public.check_points_event_scope();

-- ---------------------------------------------------------------------
-- 2. CONTACT LOG — calls & messages made for an event (follow-up)
-- ---------------------------------------------------------------------
create table if not exists public.contact_log (
  id            uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  event_id      uuid references public.events(id) on delete set null,
  kind          text not null check (kind in ('call', 'whatsapp', 'sms', 'internal')),
  -- the message text actually sent (variables already substituted); null for calls
  message       text,
  -- Cairo day the follow-up was made on (lets us list "who was contacted
  -- for this event occurrence")
  contacted_on  date not null default ((now() at time zone 'Africa/Cairo')::date),
  recorded_by   uuid references public.profiles(id),
  created_at    timestamptz not null default now()
);

create index if not exists idx_contact_log_enrollment_created
  on public.contact_log(enrollment_id, created_at desc);
create index if not exists idx_contact_log_event_day
  on public.contact_log(event_id, contacted_on);
create index if not exists idx_contact_log_created
  on public.contact_log(created_at);

-- Event must apply to the enrollment's scope
create or replace function public.check_contact_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1
      from public.events ev
      join public.enrollments en on en.id = new.enrollment_id
      where ev.id = new.event_id
        and ev.church_id = en.church_id
        and (ev.service_id is null or ev.service_id = en.service_id)
        and (ev.class_id is null or ev.class_id = en.class_id)
    ) then
      raise exception 'event does not apply to the enrollment scope';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_contact_event_scope on public.contact_log;
create trigger trg_contact_event_scope before insert on public.contact_log
for each row execute function public.check_contact_event_scope();

-- ---------------------------------------------------------------------
-- 3. RLS — same InitPlan pattern as 0019 (one my_scope() lookup)
-- ---------------------------------------------------------------------
alter table public.contact_log enable row level security;

drop policy if exists contact_log_select on public.contact_log;
create policy contact_log_select on public.contact_log for select using (
  exists (
    select 1 from public.enrollments e
     where e.id = contact_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

drop policy if exists contact_log_insert on public.contact_log;
create policy contact_log_insert on public.contact_log for insert with check (
  recorded_by = auth.uid() and exists (
    select 1 from public.enrollments e
     where e.id = contact_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

drop policy if exists contact_log_delete on public.contact_log;
create policy contact_log_delete on public.contact_log for delete using (
  exists (
    select 1 from public.enrollments e
     where e.id = contact_log.enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

-- ---------------------------------------------------------------------
-- 4. REALTIME
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'contact_log'
  ) then
    alter publication supabase_realtime add table public.contact_log;
  end if;
end $$;
alter table public.contact_log replica identity full;

-- ---------------------------------------------------------------------
-- 5. Child portal: expose the event on points entries (reason keeps the
--    cause name; event_name is added as a new trailing column)
-- ---------------------------------------------------------------------
drop function if exists public.child_portal_points(text);
create or replace function public.child_portal_points(p_national_id text)
returns table (
  id uuid, enrollment_id uuid, source text, reason text,
  delta integer, created_at timestamptz, recorded_by_name text,
  class_name text, service_name text, church_name text,
  event_name text
) language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select x.id, x.enrollment_id, x.source, x.reason, x.delta, x.created_at,
           pr.full_name, cl.name, sv.name, ch.name, x.event_name
      from (
        select pl.id, pl.enrollment_id, 'cause'::text as source,
               ca.name as reason, pl.delta, pl.created_at, pl.recorded_by,
               ev.name as event_name
          from public.points_log pl
          join public.enrollments e on e.id = pl.enrollment_id
          left join public.causes ca on ca.id = pl.cause_id
          left join public.events ev on ev.id = pl.event_id
         where e.person_id = p.id
        union all
        select a.id, a.enrollment_id, 'attendance'::text,
               ev.name, a.points_delta, a.created_at, a.recorded_by,
               ev.name
          from public.attendance_log a
          join public.enrollments e on e.id = a.enrollment_id
          left join public.events ev on ev.id = a.event_id
         where e.person_id = p.id and a.points_delta <> 0
      ) x
      join public.enrollments e2 on e2.id = x.enrollment_id
      left join public.profiles pr on pr.id = x.recorded_by
      join public.classes  cl on cl.id = e2.class_id
      join public.services sv on sv.id = e2.service_id
      join public.churches ch on ch.id = e2.church_id
     order by x.created_at desc;
end $$;
grant execute on function public.child_portal_points(text) to anon, authenticated;

analyze public.points_log;



-- #####################################################################
-- ##  0023_call_feedbacks.sql
-- #####################################################################

-- =====================================================================
-- 0023: CALL FEEDBACKS (نتائج الاتصال)
--
-- A servant calls a child as a FOLLOW-UP for an event occurrence (e.g. the
-- absentees of Friday's mass). The outcome of that call is a FEEDBACK
-- chosen from a list the managers define — each feedback has a NAME, a
-- COLOR and an ICON and is bound to a scope exactly like events / causes:
--
--     church → service (null = all) → class (null = all) → event (null = all)
--
-- The children page & scanner show a CALL FEEDBACK BADGE right after the
-- status badge:
--     لم يُتصل به بعد  (not called yet) — the follow-up cycle is still open
--     لم يُتصل به      (wasn't called)  — the next occurrence has started
--                                        and nobody called him
--     <feedback>       (color + icon + name) — the recorded outcome
--
-- Storage: the feedback is a `contact_log` row (kind = 'call') carrying the
-- chosen `feedback_id` and the `occurrence_on` day the follow-up refers to.
-- Keeping it in contact_log preserves the history (a log, like attendance
-- and points); the badge shows the LATEST feedback for the occurrence.
--
-- Idempotent — safe to re-run. Depends on 0019 (scope_overlaps /
-- scope_contains) and 0022 (contact_log).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. MASTER TABLE: call_feedbacks
-- ---------------------------------------------------------------------
create table if not exists public.call_feedbacks (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,  -- null = all services
  class_id    uuid references public.classes(id)  on delete cascade,  -- null = all classes
  event_id    uuid references public.events(id)   on delete cascade,  -- null = all events
  name        text not null,
  color       text not null default '#6366f1',   -- hex color of the badge / button
  icon        text not null default 'phone',     -- lucide icon key (see src/lib/call-feedback.ts)
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.profiles(id),
  constraint call_feedbacks_color_hex check (color ~* '^#[0-9a-f]{6}$'),
  constraint call_feedbacks_name_len check (char_length(btrim(name)) between 1 and 60)
);

create index if not exists idx_call_feedbacks_church  on public.call_feedbacks(church_id);
create index if not exists idx_call_feedbacks_service on public.call_feedbacks(service_id);
create index if not exists idx_call_feedbacks_class   on public.call_feedbacks(class_id);
create index if not exists idx_call_feedbacks_event   on public.call_feedbacks(event_id);

drop trigger if exists trg_call_feedbacks_touch on public.call_feedbacks;
create trigger trg_call_feedbacks_touch before update on public.call_feedbacks
for each row execute function public.touch_edited();

-- The bound event (when given) must live inside the feedback's scope
create or replace function public.check_call_feedback_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1 from public.events ev
       where ev.id = new.event_id
         and ev.church_id = new.church_id
         and (ev.service_id is null or new.service_id is null or ev.service_id = new.service_id)
         and (ev.class_id   is null or new.class_id   is null or ev.class_id   = new.class_id)
    ) then
      raise exception 'event does not belong to the feedback scope';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_call_feedback_event_scope on public.call_feedbacks;
create trigger trg_call_feedback_event_scope before insert or update on public.call_feedbacks
for each row execute function public.check_call_feedback_event_scope();

-- RLS — same rules as causes (0019): read what overlaps my scope, write
-- only inside my scope.
alter table public.call_feedbacks enable row level security;

drop policy if exists call_feedbacks_select on public.call_feedbacks;
create policy call_feedbacks_select on public.call_feedbacks for select using (
  (select public.scope_overlaps(church_id, service_id, class_id))
);
drop policy if exists call_feedbacks_insert on public.call_feedbacks;
create policy call_feedbacks_insert on public.call_feedbacks for insert with check (
  (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists call_feedbacks_update on public.call_feedbacks;
create policy call_feedbacks_update on public.call_feedbacks for update using (
  (select public.scope_contains(church_id, service_id, class_id))
) with check (
  (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists call_feedbacks_delete on public.call_feedbacks;
create policy call_feedbacks_delete on public.call_feedbacks for delete using (
  (select public.scope_contains(church_id, service_id, class_id))
);

-- ---------------------------------------------------------------------
-- 2. contact_log: the feedback + the occurrence day it refers to
-- ---------------------------------------------------------------------
alter table public.contact_log
  add column if not exists feedback_id uuid references public.call_feedbacks(id) on delete set null;
alter table public.contact_log
  add column if not exists occurrence_on date;   -- Cairo day of the event occurrence followed up

-- Badge lookup: latest feedback per (enrollment, event, occurrence)
create index if not exists idx_contact_log_feedback_lookup
  on public.contact_log(event_id, occurrence_on, enrollment_id, created_at desc)
  where feedback_id is not null;

-- Extend the scope trigger: the feedback must apply to the enrollment and
-- (when bound to an event) to the event of the row.
create or replace function public.check_contact_event_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.event_id is not null then
    if not exists (
      select 1
      from public.events ev
      join public.enrollments en on en.id = new.enrollment_id
      where ev.id = new.event_id
        and ev.church_id = en.church_id
        and (ev.service_id is null or ev.service_id = en.service_id)
        and (ev.class_id is null or ev.class_id = en.class_id)
    ) then
      raise exception 'event does not apply to the enrollment scope';
    end if;
  end if;

  if new.feedback_id is not null then
    if not exists (
      select 1
      from public.call_feedbacks fb
      join public.enrollments en on en.id = new.enrollment_id
      where fb.id = new.feedback_id
        and fb.church_id = en.church_id
        and (fb.service_id is null or fb.service_id = en.service_id)
        and (fb.class_id   is null or fb.class_id   = en.class_id)
        and (fb.event_id   is null or fb.event_id   = new.event_id)
    ) then
      raise exception 'feedback does not apply to the enrollment / event';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_contact_event_scope on public.contact_log;
create trigger trg_contact_event_scope before insert on public.contact_log
for each row execute function public.check_contact_event_scope();

-- ---------------------------------------------------------------------
-- 3. REALTIME
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'call_feedbacks'
  ) then
    alter publication supabase_realtime add table public.call_feedbacks;
  end if;
end $$;
alter table public.call_feedbacks replica identity full;

analyze public.contact_log;



-- #####################################################################
-- ##  0024_owner_module_access.sql
-- #####################################################################

-- =====================================================================
-- 0024: OWNER MODULE — MODULE ACCESS CONTROL (وحدة المالك — صلاحيات الوحدات)
--
-- The app is made of a fixed core (الرئيسية · المخدومين · الماسح ·
-- الإحصائيات · الإعدادات) plus optional MODULES (الوحدات) — today only the
-- card designer / print module (`cards`). Modules are defined in app code
-- (`src/lib/modules.ts`); this migration adds the OWNER-controlled table
-- that decides WHO can see each module.
--
--   module_access — one row = one GRANT of a module to a scope:
--     church_id  null  → every church (the module is available to everyone)
--     service_id null  → all services of that church
--     class_id   null  → all classes of that (church, service)
--
-- A servant sees a module when at least one grant OVERLAPS his scope (same
-- `scope_overlaps` semantics used by events / causes / call feedbacks). The
-- OWNER always sees every module and is the ONLY one who can write grants.
--
-- The card tables (`card_templates`, `card_print_requests`) additionally
-- require `module_visible('cards')` in their RLS, so hiding the module in
-- the UI is backed by the database.
--
-- Seeds one global grant for `cards` so the current behaviour (everybody
-- sees the card module) is preserved until the owner restricts it.
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / is_owner /
-- scope_overlaps / can_access / enrollment_visible) and 0017 / 0018.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE: module_access
-- ---------------------------------------------------------------------
create table if not exists public.module_access (
  id          uuid primary key default gen_random_uuid(),
  module_key  text not null,                                             -- app-code key (e.g. 'cards')
  church_id   uuid references public.churches(id) on delete cascade,    -- null = all churches
  service_id  uuid references public.services(id) on delete cascade,    -- null = all services
  class_id    uuid references public.classes(id)  on delete cascade,    -- null = all classes
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  constraint module_access_key_len check (module_key ~ '^[a-z][a-z0-9_]{1,40}$'),
  -- a service needs its church, a class needs its service
  constraint module_access_scope_chain check (
    (service_id is null or church_id is not null)
    and (class_id is null or service_id is not null)
  )
);

-- No duplicate grants for the exact same scope (nulls treated as equal)
create unique index if not exists uq_module_access_scope
  on public.module_access (
    module_key,
    coalesce(church_id,  '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(class_id,   '00000000-0000-0000-0000-000000000000'::uuid)
  );

create index if not exists idx_module_access_key    on public.module_access(module_key);
create index if not exists idx_module_access_church on public.module_access(church_id);

-- The service / class must belong to the given church / service
create or replace function public.check_module_access_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.service_id is not null then
    if not exists (
      select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id
    ) then
      raise exception 'service does not belong to the church';
    end if;
  end if;
  if new.class_id is not null then
    if not exists (
      select 1 from public.classes c
       where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id
    ) then
      raise exception 'class does not belong to the service';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_module_access_scope on public.module_access;
create trigger trg_module_access_scope before insert or update on public.module_access
for each row execute function public.check_module_access_scope();

-- ---------------------------------------------------------------------
-- 2. HELPER: module_visible(key) — can the caller see this module?
-- ---------------------------------------------------------------------
create or replace function public.module_visible(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select (select public.is_owner())
      or exists (
           select 1 from public.module_access m
            where m.module_key = p_key
              and (m.church_id is null
                   or public.scope_overlaps(m.church_id, m.service_id, m.class_id))
         )
$$;

grant execute on function public.module_visible(text) to authenticated;

-- ---------------------------------------------------------------------
-- 3. RLS — everyone reads the grants that concern him (so the UI knows
--    which modules to show); only the OWNER writes.
-- ---------------------------------------------------------------------
alter table public.module_access enable row level security;

drop policy if exists module_access_select on public.module_access;
create policy module_access_select on public.module_access for select using (
  (select public.is_owner())
  or church_id is null
  or (select public.scope_overlaps(church_id, service_id, class_id))
);
drop policy if exists module_access_insert on public.module_access;
create policy module_access_insert on public.module_access for insert with check (
  (select public.is_owner())
);
drop policy if exists module_access_update on public.module_access;
create policy module_access_update on public.module_access for update using (
  (select public.is_owner())
) with check (
  (select public.is_owner())
);
drop policy if exists module_access_delete on public.module_access;
create policy module_access_delete on public.module_access for delete using (
  (select public.is_owner())
);

-- ---------------------------------------------------------------------
-- 4. CARD MODULE — its tables are only usable when the module is visible
-- ---------------------------------------------------------------------
drop policy if exists card_templates_select on public.card_templates;
create policy card_templates_select on public.card_templates for select using (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);
drop policy if exists card_templates_insert on public.card_templates;
create policy card_templates_insert on public.card_templates for insert with check (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);
drop policy if exists card_templates_update on public.card_templates;
create policy card_templates_update on public.card_templates for update using (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
) with check (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);
drop policy if exists card_templates_delete on public.card_templates;
create policy card_templates_delete on public.card_templates for delete using (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);

drop policy if exists card_print_requests_select on public.card_print_requests;
create policy card_print_requests_select on public.card_print_requests for select using (
  (select public.module_visible('cards'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists card_print_requests_insert on public.card_print_requests;
create policy card_print_requests_insert on public.card_print_requests for insert with check (
  (select public.module_visible('cards'))
  and exists (
    select 1 from public.enrollments e
    where e.id = enrollment_id
      and public.can_access(e.church_id, e.service_id, e.class_id)
  )
);
drop policy if exists card_print_requests_delete on public.card_print_requests;
create policy card_print_requests_delete on public.card_print_requests for delete using (
  (select public.module_visible('cards'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);

-- ---------------------------------------------------------------------
-- 5. SEED — keep today's behaviour: the card module is open to everyone
--    until the owner restricts it from وحدة المالك → صلاحيات الوحدات.
-- ---------------------------------------------------------------------
insert into public.module_access (module_key, church_id, service_id, class_id)
select 'cards', null, null, null
where not exists (select 1 from public.module_access where module_key = 'cards');

-- ---------------------------------------------------------------------
-- 6. REALTIME — menus / settings update the moment the owner changes a grant
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'module_access'
  ) then
    alter publication supabase_realtime add table public.module_access;
  end if;
end $$;
alter table public.module_access replica identity full;



-- #####################################################################
-- ##  0025_shepherd_groups.sql
-- #####################################################################

-- =====================================================================
-- 0025: SHEPHERDS MODULE — الأشابين (servant ↔ children groups)
--
-- Every servant (الأشبين) is bound to a number of children — HIS GROUP.
-- He opens the module, picks children from his scope into his group and
-- can add / remove them at any time. A child can belong to ONE group only:
-- a child already chosen by another servant cannot be chosen again
-- (enforced by the unique index on enrollment_id, not just by the UI).
--
-- On the children page a «مجموعتي» button (below the church / service /
-- class selectors) narrows the list to the caller's group — everything
-- else (attendance, calls, points, data …) works exactly the same.
--
-- The module is optional: its table is usable only when the owner granted
-- the `shepherds` module to the caller's scope (`module_visible`, 0024).
--
--   shepherd_groups — one row = one child in one servant's group
--     servant_id    → profiles   (the أشبين)
--     enrollment_id → enrollments (the child, bound to church/service/class)
--     church_id / service_id / class_id — denormalized from the enrollment
--                     (filled by trigger) for cheap RLS + realtime filters
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / is_owner /
-- enrollment_visible) and 0024 (module_visible).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE: shepherd_groups
-- ---------------------------------------------------------------------
create table if not exists public.shepherd_groups (
  id            uuid primary key default gen_random_uuid(),
  servant_id    uuid not null references public.profiles(id)    on delete cascade,
  enrollment_id uuid not null references public.enrollments(id) on delete cascade,
  -- denormalized scope (copied from the enrollment by trigger)
  church_id     uuid not null references public.churches(id) on delete cascade,
  service_id    uuid not null references public.services(id) on delete cascade,
  class_id      uuid not null references public.classes(id)  on delete cascade,
  created_at    timestamptz not null default now()
);

comment on table public.shepherd_groups is
  'الأشابين — كل صف = مخدوم واحد داخل مجموعة خادم واحد (المخدوم لا يكون إلا في مجموعة واحدة)';

-- A child is in ONE group only
create unique index if not exists uq_shepherd_groups_enrollment
  on public.shepherd_groups (enrollment_id);

create index if not exists idx_shepherd_groups_servant on public.shepherd_groups(servant_id);
create index if not exists idx_shepherd_groups_church  on public.shepherd_groups(church_id);
create index if not exists idx_shepherd_groups_service on public.shepherd_groups(service_id);
create index if not exists idx_shepherd_groups_class   on public.shepherd_groups(class_id);

-- keep the denormalized scope in sync with the enrollment on insert
create or replace function public.shepherd_group_fill_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  select e.church_id, e.service_id, e.class_id
    into new.church_id, new.service_id, new.class_id
  from public.enrollments e where e.id = new.enrollment_id;
  if new.church_id is null then
    raise exception 'enrollment not found';
  end if;
  return new;
end $$;

drop trigger if exists trg_shepherd_group_scope on public.shepherd_groups;
create trigger trg_shepherd_group_scope
before insert on public.shepherd_groups
for each row execute function public.shepherd_group_fill_scope();

-- ---------------------------------------------------------------------
-- 2. RLS — usable only when the module is visible to the caller
--    read : every row of an enrollment I can see (so I know which children
--           are already taken)
--    write: I add children to MY OWN group only, within my scope
--    delete: my own rows; managers (owner / church / service) may also
--           free a child from any group in their scope
-- ---------------------------------------------------------------------
alter table public.shepherd_groups enable row level security;

drop policy if exists shepherd_groups_select on public.shepherd_groups;
create policy shepherd_groups_select on public.shepherd_groups for select using (
  (select public.module_visible('shepherds'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);

drop policy if exists shepherd_groups_insert on public.shepherd_groups;
create policy shepherd_groups_insert on public.shepherd_groups for insert with check (
  (select public.module_visible('shepherds'))
  and servant_id = auth.uid()
  and exists (
    select 1 from public.enrollments e
     where e.id = enrollment_id
       and public.enrollment_visible(e.church_id, e.service_id, e.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

drop policy if exists shepherd_groups_delete on public.shepherd_groups;
create policy shepherd_groups_delete on public.shepherd_groups for delete using (
  (select public.module_visible('shepherds'))
  and (
    servant_id = auth.uid()
    or (
      (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
      and public.enrollment_visible(church_id, service_id, class_id,
        (select role from public.my_scope()), (select church_id from public.my_scope()),
        (select service_id from public.my_scope()), (select class_id from public.my_scope()))
    )
  )
);

-- ---------------------------------------------------------------------
-- 3. RPC: shepherd_claims — who holds each child I can see?
--    A class servant cannot read other servants' profiles through RLS,
--    yet the picker must say «في مجموعة فلان». SECURITY DEFINER, but it
--    only returns claims of enrollments VISIBLE to the caller and only
--    when the module is granted to him. Optional scope narrowing.
-- ---------------------------------------------------------------------
create or replace function public.shepherd_claims(
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  enrollment_id uuid,
  servant_id    uuid,
  servant_name  text,
  servant_photo text,
  created_at    timestamptz
)
language sql stable security definer set search_path = public as $$
  select g.enrollment_id, g.servant_id, p.full_name, p.photo_url, g.created_at
    from public.shepherd_groups g
    join public.profiles p on p.id = g.servant_id
   where (select public.module_visible('shepherds'))
     and public.enrollment_visible(g.church_id, g.service_id, g.class_id,
       (select role from public.my_scope()), (select church_id from public.my_scope()),
       (select service_id from public.my_scope()), (select class_id from public.my_scope()))
     and (p_church  is null or g.church_id  = p_church)
     and (p_service is null or g.service_id = p_service)
     and (p_class   is null or g.class_id   = p_class)
$$;

grant execute on function public.shepherd_claims(uuid, uuid, uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 4. RPC: shepherd_group_summary — per-servant group sizes in my scope
--    (managers' overview; a servant sees at least his own row)
-- ---------------------------------------------------------------------
create or replace function public.shepherd_group_summary(
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (
  servant_id    uuid,
  servant_name  text,
  servant_photo text,
  children      bigint
)
language sql stable security definer set search_path = public as $$
  select g.servant_id, p.full_name, p.photo_url, count(*)::bigint
    from public.shepherd_groups g
    join public.profiles p on p.id = g.servant_id
   where (select public.module_visible('shepherds'))
     and public.enrollment_visible(g.church_id, g.service_id, g.class_id,
       (select role from public.my_scope()), (select church_id from public.my_scope()),
       (select service_id from public.my_scope()), (select class_id from public.my_scope()))
     and (p_church  is null or g.church_id  = p_church)
     and (p_service is null or g.service_id = p_service)
     and (p_class   is null or g.class_id   = p_class)
   group by g.servant_id, p.full_name, p.photo_url
   order by count(*) desc, p.full_name
$$;

grant execute on function public.shepherd_group_summary(uuid, uuid, uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 5. REALTIME — the picker / children page react the moment a child is
--    claimed or released by anyone
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'shepherd_groups'
  ) then
    alter publication supabase_realtime add table public.shepherd_groups;
  end if;
end $$;
alter table public.shepherd_groups replica identity full;



-- #####################################################################
-- ##  0026_points_store.sql
-- #####################################################################

-- =====================================================================
-- 0026: POINTS STORE MODULE — إستبدال النقاط (POS: spend points on items)
--
-- A small point-of-sale for the children's points:
--
--   1. INVENTORY  (store_items)  — every item has a code (= QR label),
--      name, picture, price in points, stock (available count), active
--      flag. Scoped church → service → class (null = all) exactly like
--      causes / events: an item applies to a child when its scope covers
--      the child's enrollment.
--   2. POS        (store_checkout RPC) — the servant scans / searches a
--      child, opens a basket, scans / picks items with quantities; the
--      DB re-checks EVERYTHING inside one transaction: module granted,
--      enrollment visible to the caller, items active + in scope,
--      stock, and total ≤ the child's balance. Then it writes the bill
--      (store_orders + store_order_items), decrements stock and inserts
--      ONE points_log row (delta = −total) → the existing trigger updates
--      enrollments.points, so the balance, the children page badges and
--      the child portal all see the redemption instantly.
--   3. ARCHIVE    (store_orders) — every bill with its lines, the
--      balance before / after and who sold. Managers (owner / church /
--      service) can CANCEL a bill (store_cancel_order): the points are
--      refunded through a +delta points_log row and stock is restored.
--   4. CHILD PORTAL — child_portal_points gets a new source 'store'
--      (reason «إستبدال نقاط», order_id) and child_portal_store_orders
--      returns the child's bills with their lines.
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / is_owner /
-- enrollment_visible / scope_overlaps / scope_contains), 0021 (child
-- portal), 0022 (points_log.event_id) and 0024 (module_visible).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE: store_items (المخزون)
-- ---------------------------------------------------------------------
create table if not exists public.store_items (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,   -- null = all services
  class_id    uuid references public.classes(id)  on delete cascade,   -- null = all classes
  code        text not null,                                            -- printed as the QR label
  name        text not null,
  description text,
  image_url   text,
  price       integer not null default 1 check (price >= 0),            -- in points
  stock       integer not null default 0 check (stock >= 0),            -- available count
  is_active   boolean not null default true,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles(id),
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.profiles(id),
  constraint store_items_code_not_blank check (length(trim(code)) > 0),
  constraint store_items_scope_chain check (not (class_id is not null and service_id is null))
);

comment on table public.store_items is
  'إستبدال النقاط — أصناف المخزون: كود (QR) · اسم · صورة · السعر بالنقاط · الكمية المتاحة';

-- one code per church
create unique index if not exists uq_store_items_church_code
  on public.store_items (church_id, lower(trim(code)));
create index if not exists idx_store_items_church  on public.store_items(church_id);
create index if not exists idx_store_items_service on public.store_items(service_id);
create index if not exists idx_store_items_class   on public.store_items(class_id);
create index if not exists idx_store_items_active  on public.store_items(church_id, is_active);

drop trigger if exists trg_store_items_touch on public.store_items;
create trigger trg_store_items_touch before update on public.store_items
for each row execute function public.touch_edited();

-- the service must belong to the church, the class to the service
create or replace function public.check_store_item_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.code := trim(new.code);
  if new.service_id is not null and not exists (
    select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id
  ) then
    raise exception 'service does not belong to the church';
  end if;
  if new.class_id is not null and not exists (
    select 1 from public.classes c
     where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id
  ) then
    raise exception 'class does not belong to the service';
  end if;
  return new;
end $$;

drop trigger if exists trg_store_item_scope on public.store_items;
create trigger trg_store_item_scope before insert or update on public.store_items
for each row execute function public.check_store_item_scope();

-- ---------------------------------------------------------------------
-- 2. TABLES: store_orders (الفاتورة) + store_order_items (بنود الفاتورة)
-- ---------------------------------------------------------------------
create table if not exists public.store_orders (
  id                   uuid primary key default gen_random_uuid(),
  enrollment_id        uuid not null references public.enrollments(id) on delete cascade,
  person_id            uuid not null references public.persons(id)     on delete cascade,
  -- denormalized scope (from the enrollment) for cheap RLS + realtime filters
  church_id            uuid not null references public.churches(id) on delete cascade,
  service_id           uuid not null references public.services(id) on delete cascade,
  class_id             uuid not null references public.classes(id)  on delete cascade,
  status               text not null default 'completed' check (status in ('completed', 'cancelled')),
  items_count          integer not null default 0,            -- sum of quantities
  total_points         integer not null default 0 check (total_points >= 0),
  balance_before       integer not null default 0,
  balance_after        integer not null default 0,
  note                 text,
  points_log_id        uuid references public.points_log(id) on delete set null,   -- the −total row
  refund_points_log_id uuid references public.points_log(id) on delete set null,   -- the +total row (cancel)
  recorded_by          uuid references public.profiles(id),
  created_at           timestamptz not null default now(),
  cancelled_by         uuid references public.profiles(id),
  cancelled_at         timestamptz
);

comment on table public.store_orders is
  'إستبدال النقاط — أرشيف الفواتير: كل عملية شراء بالنقاط مع الرصيد قبل وبعد';

create index if not exists idx_store_orders_enrollment on public.store_orders(enrollment_id, created_at desc);
create index if not exists idx_store_orders_person     on public.store_orders(person_id, created_at desc);
create index if not exists idx_store_orders_created    on public.store_orders(created_at desc);
create index if not exists idx_store_orders_church     on public.store_orders(church_id);
create index if not exists idx_store_orders_service    on public.store_orders(service_id);
create index if not exists idx_store_orders_class      on public.store_orders(class_id);
create index if not exists idx_store_orders_points_log on public.store_orders(points_log_id);

create table if not exists public.store_order_items (
  id          uuid primary key default gen_random_uuid(),
  order_id    uuid not null references public.store_orders(id) on delete cascade,
  item_id     uuid references public.store_items(id) on delete set null,
  -- snapshot at sale time (the item may be renamed / deleted later)
  item_code   text not null,
  item_name   text not null,
  image_url   text,
  unit_price  integer not null check (unit_price >= 0),
  qty         integer not null check (qty > 0),
  line_total  integer not null check (line_total >= 0)
);

create index if not exists idx_store_order_items_order on public.store_order_items(order_id);
create index if not exists idx_store_order_items_item  on public.store_order_items(item_id);

-- ---------------------------------------------------------------------
-- 3. RLS — everything requires module_visible('store')
--    store_items : read via scope_overlaps, write via scope_contains
--    store_orders / store_order_items : read rows of enrollments I can see;
--    NO insert / update / delete policies — writes go through the RPCs
--    (security definer) which re-validate every rule.
-- ---------------------------------------------------------------------
alter table public.store_items       enable row level security;
alter table public.store_orders      enable row level security;
alter table public.store_order_items enable row level security;

drop policy if exists store_items_select on public.store_items;
create policy store_items_select on public.store_items for select using (
  (select public.module_visible('store'))
  and (select public.scope_overlaps(church_id, service_id, class_id))
);
drop policy if exists store_items_insert on public.store_items;
create policy store_items_insert on public.store_items for insert with check (
  (select public.module_visible('store'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists store_items_update on public.store_items;
create policy store_items_update on public.store_items for update using (
  (select public.module_visible('store'))
  and (select public.scope_contains(church_id, service_id, class_id))
) with check (
  (select public.module_visible('store'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists store_items_delete on public.store_items;
create policy store_items_delete on public.store_items for delete using (
  (select public.module_visible('store'))
  and (select public.scope_contains(church_id, service_id, class_id))
);

drop policy if exists store_orders_select on public.store_orders;
create policy store_orders_select on public.store_orders for select using (
  (select public.module_visible('store'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);

drop policy if exists store_order_items_select on public.store_order_items;
create policy store_order_items_select on public.store_order_items for select using (
  exists (
    select 1 from public.store_orders o
     where o.id = store_order_items.order_id
       and (select public.module_visible('store'))
       and public.enrollment_visible(o.church_id, o.service_id, o.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

-- ---------------------------------------------------------------------
-- 4. RPC: store_checkout — the whole sale in ONE transaction
--    p_lines = [{ "item_id": uuid, "qty": int }, ...]
--    Returns { order_id, total_points, items_count, balance_before, balance_after }
-- ---------------------------------------------------------------------
create or replace function public.store_checkout(
  p_enrollment uuid, p_lines jsonb, p_note text default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  s        record;                 -- caller scope
  e        public.enrollments;
  it       public.store_items;
  ln       record;
  v_order  uuid;
  v_total  integer := 0;
  v_count  integer := 0;
  v_before integer;
  v_after  integer;
  v_pl     uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if not public.module_visible('store') then
    raise exception 'module_not_visible' using errcode = 'P0001';
  end if;
  select * into s from public.my_scope();
  if not found then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  -- lock the enrollment row: two cashiers can't overspend the same balance
  select * into e from public.enrollments where id = p_enrollment for update;
  if not found then
    raise exception 'enrollment_not_found' using errcode = 'P0002';
  end if;
  if not public.enrollment_visible(e.church_id, e.service_id, e.class_id,
                                   s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'empty_basket' using errcode = 'P0001';
  end if;

  v_before := e.points;

  insert into public.store_orders (
    enrollment_id, person_id, church_id, service_id, class_id,
    balance_before, balance_after, note, recorded_by)
  values (e.id, e.person_id, e.church_id, e.service_id, e.class_id,
          v_before, v_before, nullif(trim(coalesce(p_note, '')), ''), auth.uid())
  returning id into v_order;

  -- merge duplicate lines of the same item, then process each one
  for ln in
    select (x->>'item_id')::uuid as item_id, sum((x->>'qty')::int) as qty
      from jsonb_array_elements(p_lines) x
     group by 1
  loop
    if ln.item_id is null or ln.qty is null or ln.qty <= 0 then
      raise exception 'invalid_line' using errcode = 'P0001';
    end if;

    -- lock the item row so stock can't go negative under concurrency
    select * into it from public.store_items where id = ln.item_id for update;
    if not found then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
    if not it.is_active then
      raise exception 'item_inactive:%', it.name using errcode = 'P0001';
    end if;
    -- the item must apply to the child's scope
    if not (it.church_id = e.church_id
            and (it.service_id is null or it.service_id = e.service_id)
            and (it.class_id   is null or it.class_id   = e.class_id)) then
      raise exception 'item_out_of_scope:%', it.name using errcode = 'P0001';
    end if;
    if it.stock < ln.qty then
      raise exception 'insufficient_stock:%', it.name using errcode = 'P0001';
    end if;

    update public.store_items set stock = stock - ln.qty where id = it.id;

    insert into public.store_order_items (
      order_id, item_id, item_code, item_name, image_url, unit_price, qty, line_total)
    values (v_order, it.id, it.code, it.name, it.image_url, it.price, ln.qty, it.price * ln.qty);

    v_total := v_total + it.price * ln.qty;
    v_count := v_count + ln.qty;
  end loop;

  if v_total > v_before then
    raise exception 'insufficient_points' using errcode = 'P0001';
  end if;

  -- the redemption itself: ONE points_log row (trigger updates the balance)
  if v_total > 0 then
    insert into public.points_log (enrollment_id, cause_id, event_id, delta, recorded_by)
    values (e.id, null, null, -v_total, auth.uid())
    returning id into v_pl;
  end if;

  select points into v_after from public.enrollments where id = e.id;

  update public.store_orders
     set items_count = v_count, total_points = v_total,
         balance_after = v_after, points_log_id = v_pl
   where id = v_order;

  return jsonb_build_object(
    'order_id', v_order, 'total_points', v_total, 'items_count', v_count,
    'balance_before', v_before, 'balance_after', v_after);
end $$;

grant execute on function public.store_checkout(uuid, jsonb, text) to authenticated;

-- ---------------------------------------------------------------------
-- 5. RPC: store_cancel_order — managers void a bill: refund + restock
-- ---------------------------------------------------------------------
create or replace function public.store_cancel_order(p_order uuid, p_note text default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  s     record;
  o     public.store_orders;
  li    record;
  v_pl  uuid;
  v_after integer;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if not public.module_visible('store') then
    raise exception 'module_not_visible' using errcode = 'P0001';
  end if;
  select * into s from public.my_scope();
  if not found or s.role not in ('owner', 'church_manager', 'service_manager') then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  select * into o from public.store_orders where id = p_order for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if not public.enrollment_visible(o.church_id, o.service_id, o.class_id,
                                   s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if o.status <> 'completed' then
    raise exception 'not_completed' using errcode = 'P0001';
  end if;

  -- restock (items that were deleted since are skipped)
  for li in select item_id, qty from public.store_order_items where order_id = o.id loop
    if li.item_id is not null then
      update public.store_items set stock = stock + li.qty where id = li.item_id;
    end if;
  end loop;

  -- refund
  if o.total_points > 0 then
    insert into public.points_log (enrollment_id, cause_id, event_id, delta, recorded_by)
    values (o.enrollment_id, null, null, o.total_points, auth.uid())
    returning id into v_pl;
  end if;

  select points into v_after from public.enrollments where id = o.enrollment_id;

  update public.store_orders
     set status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now(),
         refund_points_log_id = v_pl,
         note = case when nullif(trim(coalesce(p_note, '')), '') is null then note
                     else concat_ws(' · ', note, trim(p_note)) end
   where id = o.id;

  return jsonb_build_object('order_id', o.id, 'refunded', o.total_points, 'balance_after', v_after);
end $$;

grant execute on function public.store_cancel_order(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 6. RPC: store_lookup_item — resolve a scanned item code (QR label)
--    (RLS-scoped: security invoker; the code is unique per church, so a
--    servant of several churches may get several rows — the UI narrows
--    them to the child's church)
-- ---------------------------------------------------------------------
create or replace function public.store_lookup_item(p_code text)
returns setof public.store_items
language sql stable security invoker set search_path = public as $$
  select * from public.store_items
   where lower(trim(code)) = lower(trim(p_code))
   order by created_at
$$;

grant execute on function public.store_lookup_item(text) to authenticated;

-- ---------------------------------------------------------------------
-- 7. CHILD PORTAL — points list learns the 'store' source + order_id,
--    and a new RPC returns the child's bills with their lines
-- ---------------------------------------------------------------------
drop function if exists public.child_portal_points(text);
create or replace function public.child_portal_points(p_national_id text)
returns table (
  id uuid, enrollment_id uuid, source text, reason text,
  delta integer, created_at timestamptz, recorded_by_name text,
  class_name text, service_name text, church_name text,
  event_name text, order_id uuid
) language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select x.id, x.enrollment_id, x.source, x.reason, x.delta, x.created_at,
           pr.full_name, cl.name, sv.name, ch.name, x.event_name, x.order_id
      from (
        select pl.id, pl.enrollment_id,
               case when so.id is not null or sr.id is not null then 'store'::text else 'cause'::text end as source,
               case when so.id is not null then 'إستبدال نقاط — ' || so.items_count || ' صنف'
                    when sr.id is not null then 'إلغاء عملية إستبدال — استرداد النقاط'
                    else ca.name end as reason,
               pl.delta, pl.created_at, pl.recorded_by,
               ev.name as event_name,
               coalesce(so.id, sr.id) as order_id
          from public.points_log pl
          join public.enrollments e on e.id = pl.enrollment_id
          left join public.causes ca on ca.id = pl.cause_id
          left join public.events ev on ev.id = pl.event_id
          left join public.store_orders so on so.points_log_id = pl.id
          left join public.store_orders sr on sr.refund_points_log_id = pl.id
         where e.person_id = p.id
        union all
        select a.id, a.enrollment_id, 'attendance'::text,
               ev.name, a.points_delta, a.created_at, a.recorded_by,
               ev.name, null::uuid
          from public.attendance_log a
          join public.enrollments e on e.id = a.enrollment_id
          left join public.events ev on ev.id = a.event_id
         where e.person_id = p.id and a.points_delta <> 0
      ) x
      join public.enrollments e2 on e2.id = x.enrollment_id
      left join public.profiles pr on pr.id = x.recorded_by
      join public.classes  cl on cl.id = e2.class_id
      join public.services sv on sv.id = e2.service_id
      join public.churches ch on ch.id = e2.church_id
     order by x.created_at desc;
end $$;
grant execute on function public.child_portal_points(text) to anon, authenticated;

-- the child's bills (with lines) — newest first
create or replace function public.child_portal_store_orders(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
  res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id,
           'enrollment_id', o.enrollment_id,
           'status', o.status,
           'items_count', o.items_count,
           'total_points', o.total_points,
           'balance_before', o.balance_before,
           'balance_after', o.balance_after,
           'created_at', o.created_at,
           'cancelled_at', o.cancelled_at,
           'recorded_by_name', pr.full_name,
           'class_name', cl.name,
           'service_name', sv.name,
           'church_name', ch.name,
           'items', (
             select coalesce(jsonb_agg(jsonb_build_object(
                      'id', li.id, 'item_name', li.item_name, 'item_code', li.item_code,
                      'image_url', li.image_url, 'unit_price', li.unit_price,
                      'qty', li.qty, 'line_total', li.line_total) order by li.item_name), '[]'::jsonb)
               from public.store_order_items li where li.order_id = o.id)
         ) order by o.created_at desc), '[]'::jsonb)
    into res
    from public.store_orders o
    join public.enrollments e on e.id = o.enrollment_id
    left join public.profiles pr on pr.id = o.recorded_by
    join public.classes  cl on cl.id = o.class_id
    join public.services sv on sv.id = o.service_id
    join public.churches ch on ch.id = o.church_id
   where e.person_id = p.id;
  return res;
end $$;
grant execute on function public.child_portal_store_orders(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. REALTIME — inventory & archive update live on every screen
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'store_items'
  ) then
    alter publication supabase_realtime add table public.store_items;
  end if;
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'store_orders'
  ) then
    alter publication supabase_realtime add table public.store_orders;
  end if;
end $$;
alter table public.store_items  replica identity full;
alter table public.store_orders replica identity full;

analyze public.store_items;
analyze public.store_orders;
analyze public.store_order_items;



-- #####################################################################
-- ##  0027_exams.sql
-- #####################################################################

-- =====================================================================
-- 0027: EXAMS MODULE — الامتحانات (multiple-choice exams for the children)
--
--   1. exams            — title, scope (church → service → class, null = all),
--                         status draft | published | closed, availability
--                         window, defaults (seconds / points per question),
--                         pass rule (percent or score), points for pass /
--                         full mark, question mode (all | random N),
--                         shuffle, attempts, what the child sees afterwards.
--   2. exam_questions   — text, picture, 2..6 options (jsonb), correct index,
--                         points, seconds (null → exam default), sort order.
--   3. exam_attempts    — one sitting of one child (enrollment). Questions
--                         are picked at START (random / all, shuffled) and
--                         SNAPSHOTTED into exam_answers with a per-question
--                         option permutation. The child NEVER receives the
--                         correct index: every payload is built server-side.
--                         Per-question timer is enforced HERE: a question is
--                         served with a deadline (served_at + seconds); an
--                         answer after the deadline (+3 s grace) is recorded
--                         as timed-out. Going back is impossible — only the
--                         current question can be answered.
--   4. Grading          — at the last answer the attempt is finalized: score,
--                         max score, percent, passed, full mark, points →
--                         ONE points_log row (the existing trigger updates
--                         enrollments.points) so the badge / child portal
--                         see the reward instantly.
--   5. Child portal     — child_portal_exams / child_exam_start /
--                         child_exam_current / child_exam_answer /
--                         child_exam_result (SECURITY DEFINER, anon by the
--                         scanned national id — same model as 0021).
--   6. Servant side     — exams / questions via RLS (module_visible('exams')),
--                         results via exam_attempts + exam_answers (read-only),
--                         exam_cancel_attempt (undo + refund → retake),
--                         exam_duplicate.
--   7. child_portal_points learns source 'exam'.
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / is_owner /
-- enrollment_visible / scope_overlaps / scope_contains), 0021 (child
-- portal), 0022 (points_log.event_id), 0024 (module_access / module_visible),
-- 0026 (child_portal_points shape with store rows).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. HELPER: is a module granted for a concrete scope? (usable by anon
--    RPCs — module_visible() needs an authenticated caller)
-- ---------------------------------------------------------------------
create or replace function public.module_granted_for(p_key text, p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.module_access m
     where m.module_key = p_key
       and (m.church_id is null
            or (m.church_id = p_church
                and (m.service_id is null or m.service_id = p_service)
                and (m.class_id   is null or m.class_id   = p_class)))
  )
$$;
revoke all on function public.module_granted_for(text, uuid, uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 1. TABLE: exams
-- ---------------------------------------------------------------------
create table if not exists public.exams (
  id                  uuid primary key default gen_random_uuid(),
  church_id           uuid not null references public.churches(id) on delete cascade,
  service_id          uuid references public.services(id) on delete cascade,   -- null = all services
  class_id            uuid references public.classes(id)  on delete cascade,   -- null = all classes
  title               text not null,
  description         text,
  image_url           text,
  status              text not null default 'draft' check (status in ('draft', 'published', 'closed')),
  opens_at            timestamptz,                                              -- null = immediately
  closes_at           timestamptz,                                              -- null = never
  -- defaults per question (a question may override)
  default_seconds     integer not null default 30 check (default_seconds between 5 and 3600),
  default_points      integer not null default 1  check (default_points between 0 and 1000),
  -- pass rule
  pass_mode           text not null default 'percent' check (pass_mode in ('percent', 'score')),
  pass_value          numeric(8,2) not null default 50 check (pass_value >= 0),
  -- rewards (points_log)
  points_pass         integer not null default 0 check (points_pass >= 0),
  points_full         integer not null default 0 check (points_full >= 0),
  -- which questions each child gets
  question_mode       text not null default 'all' check (question_mode in ('all', 'random')),
  random_count        integer not null default 10 check (random_count >= 1),
  shuffle_questions   boolean not null default true,
  shuffle_options     boolean not null default true,
  max_attempts        integer not null default 1 check (max_attempts between 1 and 100),
  -- what the child sees after finishing
  show_result         boolean not null default true,    -- score / pass
  show_answers        boolean not null default false,   -- correct answers review
  created_at          timestamptz not null default now(),
  created_by          uuid references public.profiles(id),
  edited_at           timestamptz not null default now(),
  edited_by           uuid references public.profiles(id),
  constraint exams_title_not_blank check (length(trim(title)) > 0),
  constraint exams_scope_chain check (not (class_id is not null and service_id is null)),
  constraint exams_window check (opens_at is null or closes_at is null or closes_at > opens_at)
);

comment on table public.exams is
  'الامتحانات — امتحان اختيار من متعدد مقيد بنطاق كنيسة → خدمة → فصل، بمؤقت لكل سؤال ودرجات ونقاط للنجاح';

create index if not exists idx_exams_church  on public.exams(church_id);
create index if not exists idx_exams_service on public.exams(service_id);
create index if not exists idx_exams_class   on public.exams(class_id);
create index if not exists idx_exams_status  on public.exams(church_id, status);

drop trigger if exists trg_exams_touch on public.exams;
create trigger trg_exams_touch before update on public.exams
for each row execute function public.touch_edited();

create or replace function public.check_exam_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.title := trim(new.title);
  if new.service_id is not null and not exists (
    select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id
  ) then
    raise exception 'service does not belong to the church';
  end if;
  if new.class_id is not null and not exists (
    select 1 from public.classes c
     where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id
  ) then
    raise exception 'class does not belong to the service';
  end if;
  if new.pass_mode = 'percent' and new.pass_value > 100 then
    raise exception 'pass_percent_out_of_range';
  end if;
  return new;
end $$;

drop trigger if exists trg_exam_scope on public.exams;
create trigger trg_exam_scope before insert or update on public.exams
for each row execute function public.check_exam_scope();

-- ---------------------------------------------------------------------
-- 2. TABLE: exam_questions
-- ---------------------------------------------------------------------
create table if not exists public.exam_questions (
  id            uuid primary key default gen_random_uuid(),
  exam_id       uuid not null references public.exams(id) on delete cascade,
  sort_order    integer not null default 0,
  text          text not null,
  image_url     text,
  options       jsonb not null,                       -- ["…", "…", …] 2..6 strings
  correct_index integer not null check (correct_index >= 0),
  points        integer not null default 1 check (points between 0 and 1000),
  seconds       integer check (seconds is null or seconds between 5 and 3600),   -- null → exam default
  created_at    timestamptz not null default now(),
  edited_at     timestamptz not null default now(),
  constraint exam_questions_text_not_blank check (length(trim(text)) > 0)
);

create index if not exists idx_exam_questions_exam on public.exam_questions(exam_id, sort_order);

drop trigger if exists trg_exam_questions_touch on public.exam_questions;
create trigger trg_exam_questions_touch before update on public.exam_questions
for each row execute function public.touch_edited();

create or replace function public.check_exam_question()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n integer;
  i integer;
begin
  new.text := trim(new.text);
  if jsonb_typeof(new.options) <> 'array' then
    raise exception 'options_must_be_array';
  end if;
  n := jsonb_array_length(new.options);
  if n < 2 or n > 6 then
    raise exception 'options_count_out_of_range';
  end if;
  for i in 0 .. n - 1 loop
    if jsonb_typeof(new.options -> i) <> 'string' or length(trim(new.options ->> i)) = 0 then
      raise exception 'option_blank:%', i + 1;
    end if;
  end loop;
  if new.correct_index >= n then
    raise exception 'correct_index_out_of_range';
  end if;
  return new;
end $$;

drop trigger if exists trg_exam_question_check on public.exam_questions;
create trigger trg_exam_question_check before insert or update on public.exam_questions
for each row execute function public.check_exam_question();

-- ---------------------------------------------------------------------
-- 3. TABLES: exam_attempts + exam_answers
-- ---------------------------------------------------------------------
create table if not exists public.exam_attempts (
  id                   uuid primary key default gen_random_uuid(),
  exam_id              uuid not null references public.exams(id) on delete cascade,
  enrollment_id        uuid not null references public.enrollments(id) on delete cascade,
  person_id            uuid not null references public.persons(id) on delete cascade,
  church_id            uuid not null references public.churches(id) on delete cascade,
  service_id           uuid not null references public.services(id) on delete cascade,
  class_id             uuid not null references public.classes(id)  on delete cascade,
  status               text not null default 'in_progress'
                       check (status in ('in_progress', 'submitted', 'cancelled')),
  attempt_no           integer not null default 1,
  questions_count      integer not null default 0,
  current_index        integer not null default 0,      -- 0-based position of the question being served
  started_at           timestamptz not null default now(),
  finished_at          timestamptz,
  -- result (filled at finalize)
  score                numeric(10,2) not null default 0,
  max_score            numeric(10,2) not null default 0,
  percent              numeric(5,2)  not null default 0,
  correct_count        integer not null default 0,
  answered_count       integer not null default 0,
  timed_out_count      integer not null default 0,
  passed               boolean,
  full_mark            boolean,
  points_granted       integer not null default 0,
  points_log_id        uuid references public.points_log(id) on delete set null,
  refund_points_log_id uuid references public.points_log(id) on delete set null,
  cancelled_by         uuid references public.profiles(id),
  cancelled_at         timestamptz,
  cancel_note          text
);

comment on table public.exam_attempts is
  'الامتحانات — محاولة مخدوم واحدة: الأسئلة المختارة، الموضع الحالي، النتيجة والنقاط';

create index if not exists idx_exam_attempts_exam       on public.exam_attempts(exam_id, started_at desc);
create index if not exists idx_exam_attempts_enrollment on public.exam_attempts(enrollment_id, exam_id);
create index if not exists idx_exam_attempts_person     on public.exam_attempts(person_id);
create index if not exists idx_exam_attempts_church     on public.exam_attempts(church_id);
create index if not exists idx_exam_attempts_service    on public.exam_attempts(service_id);
create index if not exists idx_exam_attempts_class      on public.exam_attempts(class_id);
create index if not exists idx_exam_attempts_points_log on public.exam_attempts(points_log_id);
-- one open sitting per child per exam
create unique index if not exists uq_exam_attempts_open
  on public.exam_attempts(exam_id, enrollment_id) where status = 'in_progress';

create table if not exists public.exam_answers (
  id               uuid primary key default gen_random_uuid(),
  attempt_id       uuid not null references public.exam_attempts(id) on delete cascade,
  exam_id          uuid not null references public.exams(id) on delete cascade,
  question_id      uuid references public.exam_questions(id) on delete set null,
  position         integer not null,                     -- 0-based order in this attempt
  -- snapshot of the question at start (edits / deletions never change a result)
  question_text    text not null,
  image_url        text,
  options          jsonb not null,                       -- ORIGINAL order
  option_order     integer[] not null,                   -- served order → original index
  correct_index    integer not null,                     -- original index
  points           integer not null,
  seconds          integer not null,
  -- serving / answering
  served_at        timestamptz,
  deadline_at      timestamptz,
  answered_at      timestamptz,
  selected_index   integer,                              -- original index, null = no answer
  is_correct       boolean,
  points_earned    numeric(10,2) not null default 0,
  timed_out        boolean not null default false,
  time_spent_ms    integer,
  constraint uq_exam_answers_position unique (attempt_id, position)
);

create index if not exists idx_exam_answers_attempt  on public.exam_answers(attempt_id, position);
create index if not exists idx_exam_answers_exam     on public.exam_answers(exam_id);
create index if not exists idx_exam_answers_question on public.exam_answers(question_id);

-- ---------------------------------------------------------------------
-- 4. RLS — everything requires module_visible('exams')
-- ---------------------------------------------------------------------
alter table public.exams          enable row level security;
alter table public.exam_questions enable row level security;
alter table public.exam_attempts  enable row level security;
alter table public.exam_answers   enable row level security;

drop policy if exists exams_select on public.exams;
create policy exams_select on public.exams for select using (
  (select public.module_visible('exams'))
  and (select public.scope_overlaps(church_id, service_id, class_id))
);
drop policy if exists exams_insert on public.exams;
create policy exams_insert on public.exams for insert with check (
  (select public.module_visible('exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists exams_update on public.exams;
create policy exams_update on public.exams for update using (
  (select public.module_visible('exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
) with check (
  (select public.module_visible('exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists exams_delete on public.exams;
create policy exams_delete on public.exams for delete using (
  (select public.module_visible('exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
);

-- questions follow their exam
drop policy if exists exam_questions_select on public.exam_questions;
create policy exam_questions_select on public.exam_questions for select using (
  exists (select 1 from public.exams x where x.id = exam_questions.exam_id
            and (select public.module_visible('exams'))
            and (select public.scope_overlaps(x.church_id, x.service_id, x.class_id)))
);
drop policy if exists exam_questions_insert on public.exam_questions;
create policy exam_questions_insert on public.exam_questions for insert with check (
  exists (select 1 from public.exams x where x.id = exam_questions.exam_id
            and (select public.module_visible('exams'))
            and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
);
drop policy if exists exam_questions_update on public.exam_questions;
create policy exam_questions_update on public.exam_questions for update using (
  exists (select 1 from public.exams x where x.id = exam_questions.exam_id
            and (select public.module_visible('exams'))
            and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
) with check (
  exists (select 1 from public.exams x where x.id = exam_questions.exam_id
            and (select public.module_visible('exams'))
            and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
);
drop policy if exists exam_questions_delete on public.exam_questions;
create policy exam_questions_delete on public.exam_questions for delete using (
  exists (select 1 from public.exams x where x.id = exam_questions.exam_id
            and (select public.module_visible('exams'))
            and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
);

-- attempts / answers: read rows of enrollments I can see; writes only via RPCs
drop policy if exists exam_attempts_select on public.exam_attempts;
create policy exam_attempts_select on public.exam_attempts for select using (
  (select public.module_visible('exams'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists exam_answers_select on public.exam_answers;
create policy exam_answers_select on public.exam_answers for select using (
  exists (
    select 1 from public.exam_attempts a
     where a.id = exam_answers.attempt_id
       and (select public.module_visible('exams'))
       and public.enrollment_visible(a.church_id, a.service_id, a.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

-- ---------------------------------------------------------------------
-- 5. INTERNAL HELPERS (not callable from the API)
-- ---------------------------------------------------------------------

-- Is the exam open for this enrollment right now? (published, window,
-- scope, module granted). Raises a specific error otherwise.
create or replace function public.exam_assert_open(x public.exams, e public.enrollments)
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.module_granted_for('exams', e.church_id, e.service_id, e.class_id) then
    raise exception 'module_not_visible' using errcode = 'P0001';
  end if;
  if not (x.church_id = e.church_id
          and (x.service_id is null or x.service_id = e.service_id)
          and (x.class_id   is null or x.class_id   = e.class_id)) then
    raise exception 'exam_out_of_scope' using errcode = 'P0001';
  end if;
  if x.status <> 'published' then
    raise exception 'exam_not_published' using errcode = 'P0001';
  end if;
  if x.opens_at is not null and now() < x.opens_at then
    raise exception 'exam_not_open_yet' using errcode = 'P0001';
  end if;
  if x.closes_at is not null and now() > x.closes_at then
    raise exception 'exam_closed' using errcode = 'P0001';
  end if;
end $$;
revoke all on function public.exam_assert_open(public.exams, public.enrollments) from public, anon, authenticated;

-- The question payload the child receives (NO correct index).
create or replace function public.exam_question_payload(a public.exam_answers, total integer)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'position', a.position,
    'total', total,
    'question_id', a.question_id,
    'text', a.question_text,
    'image_url', a.image_url,
    'options', (
      select coalesce(jsonb_agg(a.options -> o.idx order by o.pos), '[]'::jsonb)
        from unnest(a.option_order) with ordinality as o(idx, pos)
    ),
    'points', a.points,
    'seconds', a.seconds,
    'served_at', a.served_at,
    'deadline_at', a.deadline_at,
    'server_now', now()
  )
$$;
revoke all on function public.exam_question_payload(public.exam_answers, integer) from public, anon, authenticated;

-- Result payload (respects show_result / show_answers unless p_full).
create or replace function public.exam_result_payload(a public.exam_attempts, p_full boolean)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  x public.exams;
  res jsonb;
begin
  select * into x from public.exams where id = a.exam_id;
  res := jsonb_build_object(
    'attempt_id', a.id,
    'exam_id', a.exam_id,
    'exam_title', x.title,
    'status', a.status,
    'attempt_no', a.attempt_no,
    'questions_count', a.questions_count,
    'started_at', a.started_at,
    'finished_at', a.finished_at,
    'show_result', x.show_result,
    'show_answers', x.show_answers,
    'answered_count', a.answered_count,
    'timed_out_count', a.timed_out_count
  );
  if p_full or x.show_result then
    res := res || jsonb_build_object(
      'score', a.score, 'max_score', a.max_score, 'percent', a.percent,
      'correct_count', a.correct_count, 'passed', a.passed, 'full_mark', a.full_mark,
      'points_granted', a.points_granted,
      'pass_mode', x.pass_mode, 'pass_value', x.pass_value
    );
  end if;
  if p_full or x.show_answers then
    res := res || jsonb_build_object('answers', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'position', an.position,
               'text', an.question_text,
               'image_url', an.image_url,
               'options', an.options,
               'correct_index', an.correct_index,
               'selected_index', an.selected_index,
               'is_correct', an.is_correct,
               'points', an.points,
               'points_earned', an.points_earned,
               'timed_out', an.timed_out,
               'time_spent_ms', an.time_spent_ms
             ) order by an.position), '[]'::jsonb)
        from public.exam_answers an where an.attempt_id = a.id));
  end if;
  return res;
end $$;
revoke all on function public.exam_result_payload(public.exam_attempts, boolean) from public, anon, authenticated;

-- Finalize: grade + reward. Idempotent (no-op if already submitted).
create or replace function public.exam_finalize(p_attempt uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  a        public.exam_attempts;
  x        public.exams;
  v_score  numeric(10,2);
  v_max    numeric(10,2);
  v_pct    numeric(5,2);
  v_ok     integer;
  v_ans    integer;
  v_to     integer;
  v_pass   boolean;
  v_full   boolean;
  v_points integer := 0;
  v_pl     uuid;
begin
  select * into a from public.exam_attempts where id = p_attempt for update;
  if not found or a.status <> 'in_progress' then return; end if;
  select * into x from public.exams where id = a.exam_id;

  select coalesce(sum(points_earned), 0), coalesce(sum(points), 0),
         count(*) filter (where is_correct), count(*) filter (where selected_index is not null),
         count(*) filter (where timed_out)
    into v_score, v_max, v_ok, v_ans, v_to
    from public.exam_answers where attempt_id = a.id;

  v_pct  := case when v_max > 0 then round(v_score * 100.0 / v_max, 2) else 0 end;
  v_full := v_max > 0 and v_score >= v_max;
  v_pass := case when x.pass_mode = 'percent' then v_pct >= x.pass_value else v_score >= x.pass_value end;
  if v_full then v_pass := true; end if;
  v_points := case when v_full then greatest(x.points_full, x.points_pass) when v_pass then x.points_pass else 0 end;

  if v_points > 0 then
    insert into public.points_log (enrollment_id, cause_id, event_id, delta, recorded_by)
    values (a.enrollment_id, null, null, v_points, null)
    returning id into v_pl;
  end if;

  update public.exam_attempts
     set status = 'submitted', finished_at = now(),
         score = v_score, max_score = v_max, percent = v_pct,
         correct_count = v_ok, answered_count = v_ans, timed_out_count = v_to,
         passed = v_pass, full_mark = v_full,
         points_granted = v_points, points_log_id = v_pl,
         current_index = a.questions_count
   where id = a.id;
end $$;
revoke all on function public.exam_finalize(uuid) from public, anon, authenticated;

-- Advance the attempt past every served question whose deadline passed
-- (child closed the app mid-exam). Then serve the current question (set
-- served_at / deadline_at if not yet). Finalizes when nothing is left.
create or replace function public.exam_advance(p_attempt uuid)
returns public.exam_attempts language plpgsql volatile security definer set search_path = public as $$
declare
  a  public.exam_attempts;
  an public.exam_answers;
  grace constant interval := interval '3 seconds';
begin
  select * into a from public.exam_attempts where id = p_attempt for update;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  if a.status <> 'in_progress' then return a; end if;

  loop
    if a.current_index >= a.questions_count then
      perform public.exam_finalize(a.id);
      select * into a from public.exam_attempts where id = a.id;
      return a;
    end if;
    select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index;
    if an.served_at is null then
      update public.exam_answers
         set served_at = now(), deadline_at = now() + make_interval(secs => an.seconds)
       where id = an.id;
      return a;
    end if;
    if now() <= an.deadline_at + grace then
      return a;   -- still answerable
    end if;
    -- deadline passed without an answer → timed out, move on
    update public.exam_answers
       set timed_out = true, is_correct = false, points_earned = 0,
           answered_at = coalesce(answered_at, an.deadline_at),
           time_spent_ms = an.seconds * 1000
     where id = an.id;
    update public.exam_attempts set current_index = current_index + 1 where id = a.id
      returning * into a;
  end loop;
end $$;
revoke all on function public.exam_advance(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. CHILD PORTAL RPCs (anon, keyed by the scanned national id)
-- ---------------------------------------------------------------------

-- The exams the child can see: published + in scope + module granted,
-- with his attempt state; plus closed exams he already took.
create or replace function public.child_portal_exams(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p   public.persons;
  res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(to_jsonb(t) - 'sort_key' order by t.sort_key, t.created_at desc), '[]'::jsonb)
    into res
    from (
      select x.id, x.title, x.description, x.image_url, x.status, x.opens_at, x.closes_at,
             x.default_seconds, x.question_mode, x.random_count, x.max_attempts,
             x.show_result, x.pass_mode, x.pass_value, x.points_pass, x.points_full, x.created_at,
             e.id as enrollment_id, cl.name as class_name, sv.name as service_name, ch.name as church_name,
             (select count(*) from public.exam_questions q where q.exam_id = x.id) as total_questions,
             case when x.question_mode = 'random'
                  then least(x.random_count, (select count(*) from public.exam_questions q where q.exam_id = x.id))
                  else (select count(*) from public.exam_questions q where q.exam_id = x.id) end as served_questions,
             (select count(*) from public.exam_attempts a
               where a.exam_id = x.id and a.enrollment_id = e.id and a.status = 'submitted') as attempts_used,
             (select a.id from public.exam_attempts a
               where a.exam_id = x.id and a.enrollment_id = e.id and a.status = 'in_progress' limit 1) as open_attempt_id,
             (select public.exam_result_payload(a, false) from public.exam_attempts a
               where a.exam_id = x.id and a.enrollment_id = e.id and a.status = 'submitted'
               order by a.finished_at desc limit 1) as last_result,
             (x.status = 'published'
                and (x.opens_at is null or now() >= x.opens_at)
                and (x.closes_at is null or now() <= x.closes_at)) as is_open,
             case when x.status = 'published'
                    and (x.opens_at is null or now() >= x.opens_at)
                    and (x.closes_at is null or now() <= x.closes_at) then 0 else 1 end as sort_key
        from public.enrollments e
        join public.exams x
          on x.church_id = e.church_id
         and (x.service_id is null or x.service_id = e.service_id)
         and (x.class_id   is null or x.class_id   = e.class_id)
        join public.classes  cl on cl.id = e.class_id
        join public.services sv on sv.id = e.service_id
        join public.churches ch on ch.id = e.church_id
       where e.person_id = p.id
         and x.status in ('published', 'closed')
         and public.module_granted_for('exams', e.church_id, e.service_id, e.class_id)
         and (x.status = 'published'
              or exists (select 1 from public.exam_attempts a
                          where a.exam_id = x.id and a.enrollment_id = e.id and a.status = 'submitted'))
    ) t;
  return res;
end $$;
grant execute on function public.child_portal_exams(text) to anon, authenticated;

-- Start (or resume) an attempt. Picks + snapshots the questions, then
-- serves the first one. Returns { attempt_id, questions_count, finished, question | result }.
create or replace function public.child_exam_start(p_national_id text, p_exam uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p       public.persons;
  x       public.exams;
  e       public.enrollments;
  a       public.exam_attempts;
  an      public.exam_answers;
  q       record;
  v_used  integer;
  v_pos   integer := 0;
  v_n     integer;
  v_order integer[];
begin
  p := public.child_portal_person(p_national_id);
  select * into x from public.exams where id = p_exam;
  if not found then
    raise exception 'exam_not_found' using errcode = 'P0002';
  end if;
  -- the enrollment of this child covered by the exam
  select en.* into e from public.enrollments en
   where en.person_id = p.id
     and x.church_id = en.church_id
     and (x.service_id is null or x.service_id = en.service_id)
     and (x.class_id   is null or x.class_id   = en.class_id)
   order by en.created_at limit 1;
  if not found then
    raise exception 'exam_out_of_scope' using errcode = 'P0001';
  end if;
  perform public.exam_assert_open(x, e);

  -- resume an open sitting
  select * into a from public.exam_attempts
   where exam_id = x.id and enrollment_id = e.id and status = 'in_progress' for update;
  if found then
    a := public.exam_advance(a.id);
    if a.status <> 'in_progress' then
      return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                                'finished', true, 'result', public.exam_result_payload(a, false));
    end if;
    select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index;
    return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                              'finished', false, 'question', public.exam_question_payload(an, a.questions_count));
  end if;

  select count(*) into v_used from public.exam_attempts
   where exam_id = x.id and enrollment_id = e.id and status = 'submitted';
  if v_used >= x.max_attempts then
    raise exception 'no_attempts_left' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.exam_questions where exam_id = x.id) then
    raise exception 'exam_has_no_questions' using errcode = 'P0001';
  end if;

  insert into public.exam_attempts (exam_id, enrollment_id, person_id, church_id, service_id, class_id, attempt_no)
  values (x.id, e.id, p.id, e.church_id, e.service_id, e.class_id, v_used + 1)
  returning * into a;

  -- pick + snapshot the questions
  for q in
    select * from public.exam_questions
     where exam_id = x.id
     order by case when x.question_mode = 'random' or x.shuffle_questions then random() else 0 end,
              sort_order, created_at
     limit case when x.question_mode = 'random' then x.random_count else null end
  loop
    v_n := jsonb_array_length(q.options);
    if x.shuffle_options then
      select array_agg(i order by random()) into v_order from generate_series(0, v_n - 1) i;
    else
      select array_agg(i order by i) into v_order from generate_series(0, v_n - 1) i;
    end if;
    insert into public.exam_answers (
      attempt_id, exam_id, question_id, position, question_text, image_url, options, option_order,
      correct_index, points, seconds)
    values (a.id, x.id, q.id, v_pos, q.text, q.image_url, q.options, v_order,
            q.correct_index, q.points, coalesce(q.seconds, x.default_seconds));
    v_pos := v_pos + 1;
  end loop;

  update public.exam_attempts set questions_count = v_pos where id = a.id returning * into a;
  a := public.exam_advance(a.id);
  select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index;
  return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                            'finished', false, 'question', public.exam_question_payload(an, a.questions_count));
end $$;
grant execute on function public.child_exam_start(text, uuid) to anon, authenticated;

-- The question being served right now (re-serves after a reload; expired
-- questions are skipped as timed-out). Returns { finished, question | result }.
create or replace function public.child_exam_current(p_national_id text, p_attempt uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p  public.persons;
  a  public.exam_attempts;
  an public.exam_answers;
begin
  p := public.child_portal_person(p_national_id);
  select * into a from public.exam_attempts where id = p_attempt and person_id = p.id;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  a := public.exam_advance(a.id);
  if a.status <> 'in_progress' then
    return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                              'finished', true, 'result', public.exam_result_payload(a, false));
  end if;
  select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index;
  return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                            'finished', false, 'question', public.exam_question_payload(an, a.questions_count));
end $$;
grant execute on function public.child_exam_current(text, uuid) to anon, authenticated;

-- Answer the CURRENT question (p_selected = position in the SERVED option
-- order, or null = skip / time ran out). Moves forward; never back.
create or replace function public.child_exam_answer(
  p_national_id text, p_attempt uuid, p_position integer, p_selected integer)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p       public.persons;
  a       public.exam_attempts;
  an      public.exam_answers;
  v_orig  integer;
  v_ok    boolean;
  grace constant interval := interval '3 seconds';
begin
  p := public.child_portal_person(p_national_id);
  select * into a from public.exam_attempts where id = p_attempt and person_id = p.id for update;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  if a.status <> 'in_progress' then
    return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                              'finished', true, 'result', public.exam_result_payload(a, false));
  end if;

  -- a stale answer for an older question (double tap / reconnect) is ignored
  if p_position = a.current_index then
    select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index for update;
    if an.served_at is null then
      raise exception 'question_not_served' using errcode = 'P0001';
    end if;
    if now() > an.deadline_at + grace or p_selected is null then
      update public.exam_answers
         set timed_out = (now() > an.deadline_at + grace), is_correct = false, points_earned = 0,
             answered_at = now(), selected_index = null,
             time_spent_ms = least(an.seconds * 1000, (extract(epoch from now() - an.served_at) * 1000)::int)
       where id = an.id;
    else
      if p_selected < 0 or p_selected >= array_length(an.option_order, 1) then
        raise exception 'invalid_option' using errcode = 'P0001';
      end if;
      v_orig := an.option_order[p_selected + 1];
      v_ok   := v_orig = an.correct_index;
      update public.exam_answers
         set selected_index = v_orig, is_correct = v_ok,
             points_earned = case when v_ok then an.points else 0 end,
             answered_at = now(), timed_out = false,
             time_spent_ms = (extract(epoch from now() - an.served_at) * 1000)::int
       where id = an.id;
    end if;
    update public.exam_attempts set current_index = current_index + 1 where id = a.id;
  elsif p_position > a.current_index then
    raise exception 'position_mismatch' using errcode = 'P0001';
  end if;

  a := public.exam_advance(a.id);
  if a.status <> 'in_progress' then
    return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                              'finished', true, 'result', public.exam_result_payload(a, false));
  end if;
  select * into an from public.exam_answers where attempt_id = a.id and position = a.current_index;
  return jsonb_build_object('attempt_id', a.id, 'questions_count', a.questions_count,
                            'finished', false, 'question', public.exam_question_payload(an, a.questions_count));
end $$;
grant execute on function public.child_exam_answer(text, uuid, integer, integer) to anon, authenticated;

-- A finished attempt's result (what the exam allows the child to see).
create or replace function public.child_exam_result(p_national_id text, p_attempt uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
  a public.exam_attempts;
begin
  p := public.child_portal_person(p_national_id);
  select * into a from public.exam_attempts where id = p_attempt and person_id = p.id;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  if a.status = 'in_progress' then
    raise exception 'attempt_in_progress' using errcode = 'P0001';
  end if;
  return public.exam_result_payload(a, false);
end $$;
grant execute on function public.child_exam_result(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 7. SERVANT RPCs
-- ---------------------------------------------------------------------

-- Full result of an attempt (servant view: always includes answers).
create or replace function public.exam_attempt_detail(p_attempt uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  a public.exam_attempts;
  s record;
begin
  if auth.uid() is null or not public.module_visible('exams') then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  select * into a from public.exam_attempts where id = p_attempt;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  select * into s from public.my_scope();
  if not public.enrollment_visible(a.church_id, a.service_id, a.class_id, s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  return public.exam_result_payload(a, true);
end $$;
grant execute on function public.exam_attempt_detail(uuid) to authenticated;

-- Cancel an attempt (servant with write scope on the exam): refunds the
-- granted points, marks it cancelled so the child may sit again.
create or replace function public.exam_cancel_attempt(p_attempt uuid, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  a    public.exam_attempts;
  x    public.exams;
  v_pl uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if not public.module_visible('exams') then
    raise exception 'module_not_visible' using errcode = 'P0001';
  end if;
  select * into a from public.exam_attempts where id = p_attempt for update;
  if not found then
    raise exception 'attempt_not_found' using errcode = 'P0002';
  end if;
  select * into x from public.exams where id = a.exam_id;
  if not public.scope_contains(x.church_id, x.service_id, x.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if a.status = 'cancelled' then
    raise exception 'already_cancelled' using errcode = 'P0001';
  end if;
  if a.status = 'submitted' and a.points_granted > 0 then
    insert into public.points_log (enrollment_id, cause_id, event_id, delta, recorded_by)
    values (a.enrollment_id, null, null, -a.points_granted, auth.uid())
    returning id into v_pl;
  end if;
  update public.exam_attempts
     set status = 'cancelled', cancelled_by = auth.uid(), cancelled_at = now(),
         refund_points_log_id = v_pl, cancel_note = nullif(trim(coalesce(p_note, '')), ''),
         finished_at = coalesce(finished_at, now())
   where id = a.id;
  return jsonb_build_object('attempt_id', a.id, 'refunded', a.points_granted);
end $$;
grant execute on function public.exam_cancel_attempt(uuid, text) to authenticated;

-- Duplicate an exam with all its questions (as a draft) — handy for the
-- next class / year. Returns the new exam id.
create or replace function public.exam_duplicate(p_exam uuid, p_title text default null)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  x     public.exams;
  v_new uuid;
begin
  if auth.uid() is null or not public.module_visible('exams') then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  select * into x from public.exams where id = p_exam;
  if not found then
    raise exception 'exam_not_found' using errcode = 'P0002';
  end if;
  if not public.scope_contains(x.church_id, x.service_id, x.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  insert into public.exams (
    church_id, service_id, class_id, title, description, image_url, status, opens_at, closes_at,
    default_seconds, default_points, pass_mode, pass_value, points_pass, points_full,
    question_mode, random_count, shuffle_questions, shuffle_options, max_attempts,
    show_result, show_answers, created_by, edited_by)
  values (
    x.church_id, x.service_id, x.class_id, coalesce(nullif(trim(p_title), ''), x.title || ' (نسخة)'),
    x.description, x.image_url, 'draft', null, null,
    x.default_seconds, x.default_points, x.pass_mode, x.pass_value, x.points_pass, x.points_full,
    x.question_mode, x.random_count, x.shuffle_questions, x.shuffle_options, x.max_attempts,
    x.show_result, x.show_answers, auth.uid(), auth.uid())
  returning id into v_new;
  insert into public.exam_questions (exam_id, sort_order, text, image_url, options, correct_index, points, seconds)
  select v_new, sort_order, text, image_url, options, correct_index, points, seconds
    from public.exam_questions where exam_id = x.id order by sort_order, created_at;
  return v_new;
end $$;
grant execute on function public.exam_duplicate(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 8. CHILD PORTAL — points list learns the 'exam' source
-- ---------------------------------------------------------------------
drop function if exists public.child_portal_points(text);
create or replace function public.child_portal_points(p_national_id text)
returns table (
  id uuid, enrollment_id uuid, source text, reason text,
  delta integer, created_at timestamptz, recorded_by_name text,
  class_name text, service_name text, church_name text,
  event_name text, order_id uuid, attempt_id uuid
) language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return query
    select x.id, x.enrollment_id, x.source, x.reason, x.delta, x.created_at,
           pr.full_name, cl.name, sv.name, ch.name, x.event_name, x.order_id, x.attempt_id
      from (
        select pl.id, pl.enrollment_id,
               case when so.id is not null or sr.id is not null then 'store'::text
                    when xa.id is not null or xr.id is not null then 'exam'::text
                    else 'cause'::text end as source,
               case when so.id is not null then 'إستبدال نقاط — ' || so.items_count || ' صنف'
                    when sr.id is not null then 'إلغاء عملية إستبدال — استرداد النقاط'
                    when xa.id is not null then case when xa.full_mark then 'الدرجة الكاملة في امتحان «' else 'النجاح في امتحان «' end || xe.title || '»'
                    when xr.id is not null then 'إلغاء محاولة امتحان «' || xre.title || '»'
                    else ca.name end as reason,
               pl.delta, pl.created_at, pl.recorded_by,
               ev.name as event_name,
               coalesce(so.id, sr.id) as order_id,
               coalesce(xa.id, xr.id) as attempt_id
          from public.points_log pl
          join public.enrollments e on e.id = pl.enrollment_id
          left join public.causes ca on ca.id = pl.cause_id
          left join public.events ev on ev.id = pl.event_id
          left join public.store_orders so on so.points_log_id = pl.id
          left join public.store_orders sr on sr.refund_points_log_id = pl.id
          left join public.exam_attempts xa on xa.points_log_id = pl.id
          left join public.exams xe on xe.id = xa.exam_id
          left join public.exam_attempts xr on xr.refund_points_log_id = pl.id
          left join public.exams xre on xre.id = xr.exam_id
         where e.person_id = p.id
        union all
        select a.id, a.enrollment_id, 'attendance'::text,
               ev.name, a.points_delta, a.created_at, a.recorded_by,
               ev.name, null::uuid, null::uuid
          from public.attendance_log a
          join public.enrollments e on e.id = a.enrollment_id
          left join public.events ev on ev.id = a.event_id
         where e.person_id = p.id and a.points_delta <> 0
      ) x
      join public.enrollments e2 on e2.id = x.enrollment_id
      left join public.profiles pr on pr.id = x.recorded_by
      join public.classes  cl on cl.id = e2.class_id
      join public.services sv on sv.id = e2.service_id
      join public.churches ch on ch.id = e2.church_id
     order by x.created_at desc;
end $$;
grant execute on function public.child_portal_points(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 9. REALTIME
