do $$
declare t text;
begin
  foreach t in array array['occasions', 'occasion_registrations', 'occasion_checklist_items',
                           'occasion_checklist_marks', 'occasion_notifications'] loop
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
alter table public.occasions                replica identity full;
alter table public.occasion_registrations   replica identity full;
alter table public.occasion_checklist_items replica identity full;
alter table public.occasion_checklist_marks replica identity full;
alter table public.occasion_notifications   replica identity full;



-- #####################################################################
-- ##  0033_occasions_ticket_code_fix.sql
-- #####################################################################

-- =====================================================================
-- 0033: HOTFIX — occasion ticket code without pgcrypto
--
-- `occasion_new_ticket_code()` (0032) used `gen_random_bytes`, which on
-- Supabase lives in the `extensions` schema; the function pins
-- `search_path = public`, so every registration failed with
--   42883: function gen_random_bytes(integer) does not exist
-- Rebuilt on core `gen_random_uuid()` — same «T-» + 10 hex-char shape.
-- 0032 itself is patched the same way for fresh installs. Idempotent.
-- =====================================================================


create or replace function public.occasion_new_ticket_code()
returns text language plpgsql volatile security definer set search_path = public as $$
declare v text; i integer := 0;
begin
  loop
    v := 'T-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    exit when not exists (select 1 from public.occasion_registrations r where r.ticket_code = v);
    i := i + 1;
    if i > 20 then raise exception 'ticket_code_collision'; end if;
  end loop;
  return v;
end $$;
revoke all on function public.occasion_new_ticket_code() from public, anon, authenticated;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  0034_notifications.sql
-- #####################################################################

-- =====================================================================
-- 0034: NOTIFICATIONS MODULE — الإشعارات (simple v1)
--
-- Create → choose recipients → send / schedule → receive → history, plus
-- App event → automatic notification. Web-push delivery (device tray) is
-- done by the Next.js API route /api/notifications/dispatch with the
-- VAPID keys; the database only decides WHO gets WHAT and WHEN.
--
--   1. notifications             — one send (manual or automatic): title ·
--      body · image · link · target (all | church | service | class |
--      group | person) · audience (children | staff) · schedule · status
--      (scheduled | sent | failed | cancelled) · recipients_count · source.
--   2. notification_recipients   — one row per recipient (the inbox):
--      enrollment (child) OR profile (servant) · snapshot of the text ·
--      read_at · push_status (pending | sent | failed | no_device).
--   3. notification_automations  — Trigger → Recipient → Notification:
--      trigger_key (attendance · points_added · points_deducted ·
--      online_class_started · exam_published · achievement_earned ·
--      occasion_reminder) · recipient (student | class_servants) ·
--      title / body templates with [variables] · link · scope church →
--      service → class (null = all) · is_active · config (jsonb).
--      Adding a trigger later = one new trigger function that calls
--      notif_fire_enrollment() or notif_fire_scope().
--   4. notification_automation_runs — «fired once» guard.
--   5. push_subscriptions         — one device (Web Push endpoint) bound
--      to a servant (profile_id) or a child (person_id).
--   6. notif_tick()               — materializes due scheduled sends and
--      the occasion reminders; scheduled with pg_cron when available and
--      also called by the dispatch API route.
--
-- Permissions (existing RBAC — role + scope + module grant):
--   see history : module_visible('notifications') + scope_overlaps / own
--   send        : module_visible + scope_contains (all churches = owner;
--                 group = my own group, managers may pick a servant in scope;
--                 person = enrollment_visible)
--   automations : select scope_overlaps · write scope_contains
--   delete      : creator, or owner / church_manager / service_manager in scope
--   inbox       : my own recipient rows (profile_id = auth.uid()); the child
--                 reads through child_notifications(national id).
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / scope_* /
-- enrollment_visible), 0021 (child portal), 0024 (module_visible),
-- 0025 (shepherd_groups), 0027 (exams), 0030 (online_classes), 0031
-- (user_achievements), 0032 (occasions). NO module grant is seeded — the
-- owner enables it per scope in وحدة المالك → صلاحيات الوحدات.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE: notifications
-- ---------------------------------------------------------------------
create table if not exists public.notifications (
  id                 uuid primary key default gen_random_uuid(),
  church_id          uuid references public.churches(id) on delete cascade,   -- null = all churches (owner)
  service_id         uuid references public.services(id) on delete cascade,   -- null = all services
  class_id           uuid references public.classes(id)  on delete cascade,   -- null = all classes
  title              text not null,
  body               text not null default '',
  image_url          text,
  link_url           text,                                                     -- in-app path ('/child/points') or https URL
  target_kind        text not null default 'class'
                     check (target_kind in ('all', 'church', 'service', 'class', 'group', 'person')),
  audience           text not null default 'children' check (audience in ('children', 'staff')),
  target_servant_id  uuid references public.profiles(id) on delete set null,   -- group = this servant's shepherd group
  enrollment_ids     uuid[],                                                   -- person = these enrollments
  status             text not null default 'sent'
                     check (status in ('scheduled', 'sent', 'failed', 'cancelled')),
  scheduled_at       timestamptz,                                              -- null = sent immediately
  sent_at            timestamptz,
  recipients_count   integer not null default 0,
  error              text,
  source             text not null default 'manual' check (source in ('manual', 'automation')),
  automation_id      uuid,                                                     -- fk added after the automations table
  created_at         timestamptz not null default now(),
  created_by         uuid references public.profiles(id) on delete set null,
  constraint notifications_title_not_blank check (length(trim(title)) > 0),
  constraint notifications_title_len       check (length(title) <= 120),
  constraint notifications_body_len        check (length(body) <= 1000),
  constraint notifications_scope_chain     check (not (class_id is not null and service_id is null)),
  constraint notifications_scope_chain2    check (not (service_id is not null and church_id is null))
);

comment on table public.notifications is
  'الإشعارات — إرسال واحد (يدوي أو تلقائي): عنوان، نص، صورة، رابط، المستلمون (كنيسة / خدمة / فصل / مجموعة / مخدوم)، موعد الإرسال، الحالة';

create index if not exists idx_notifications_church     on public.notifications(church_id, created_at desc);
create index if not exists idx_notifications_created_by on public.notifications(created_by, created_at desc);
create index if not exists idx_notifications_scheduled  on public.notifications(scheduled_at) where status = 'scheduled';
create index if not exists idx_notifications_source     on public.notifications(source, created_at desc);

-- ---------------------------------------------------------------------
-- 2. TABLE: notification_recipients (the inbox rows)
-- ---------------------------------------------------------------------
create table if not exists public.notification_recipients (
  id               uuid primary key default gen_random_uuid(),
  notification_id  uuid not null references public.notifications(id) on delete cascade,
  enrollment_id    uuid references public.enrollments(id) on delete cascade,
  person_id        uuid references public.persons(id)     on delete cascade,   -- child recipient
  profile_id       uuid references public.profiles(id)    on delete cascade,   -- servant recipient
  title            text not null,
  body             text not null default '',
  image_url        text,
  link_url         text,
  read_at          timestamptz,
  push_status      text not null default 'pending'
                   check (push_status in ('pending', 'sent', 'failed', 'no_device')),
  push_error       text,
  pushed_at        timestamptz,
  created_at       timestamptz not null default now(),
  constraint notif_recipient_one_target check (
    (person_id is not null and profile_id is null) or (person_id is null and profile_id is not null)
  )
);

comment on table public.notification_recipients is
  'مستلمو الإشعار — صف لكل مستلم (مخدوم أو خادم) مع نسخة من النص وحالة القراءة وحالة إشعار الجهاز';

create index if not exists idx_notif_rcpt_notification on public.notification_recipients(notification_id);
create index if not exists idx_notif_rcpt_person       on public.notification_recipients(person_id, created_at desc);
create index if not exists idx_notif_rcpt_profile      on public.notification_recipients(profile_id, created_at desc);
create index if not exists idx_notif_rcpt_push_pending on public.notification_recipients(created_at) where push_status = 'pending';

-- ---------------------------------------------------------------------
-- 3. TABLE: notification_automations (Trigger → Recipient → Notification)
-- ---------------------------------------------------------------------
create table if not exists public.notification_automations (
  id              uuid primary key default gen_random_uuid(),
  church_id       uuid references public.churches(id) on delete cascade,   -- null = all churches (owner)
  service_id      uuid references public.services(id) on delete cascade,   -- null = all services
  class_id        uuid references public.classes(id)  on delete cascade,   -- null = all classes
  trigger_key     text not null check (trigger_key in (
                    'attendance', 'points_added', 'points_deducted', 'online_class_started',
                    'exam_published', 'achievement_earned', 'occasion_reminder')),
  recipient       text not null default 'student' check (recipient in ('student', 'class_servants')),
  name            text not null,
  title_template  text not null,
  body_template   text not null default '',
  image_url       text,
  link_url        text,                    -- null = the trigger's default page
  is_active       boolean not null default true,
  config          jsonb not null default '{}'::jsonb,   -- e.g. {"min_points": 5, "hours_before": 24}
  created_at      timestamptz not null default now(),
  created_by      uuid references public.profiles(id) on delete set null,
  edited_at       timestamptz not null default now(),
  edited_by       uuid references public.profiles(id) on delete set null,
  constraint notif_auto_name_not_blank  check (length(trim(name)) > 0),
  constraint notif_auto_title_not_blank check (length(trim(title_template)) > 0),
  constraint notif_auto_title_len       check (length(title_template) <= 120),
  constraint notif_auto_body_len        check (length(body_template) <= 1000),
  constraint notif_auto_scope_chain     check (not (class_id is not null and service_id is null)),
  constraint notif_auto_scope_chain2    check (not (service_id is not null and church_id is null))
);

comment on table public.notification_automations is
  'الإشعارات التلقائية — حدث في التطبيق ← مستلم ← إشعار بقالب فيه متغيرات مثل [الاسم] و[النقاط]';

create index if not exists idx_notif_auto_trigger on public.notification_automations(trigger_key, is_active);
create index if not exists idx_notif_auto_church  on public.notification_automations(church_id);

drop trigger if exists trg_notif_auto_touch on public.notification_automations;
create trigger trg_notif_auto_touch before update on public.notification_automations
for each row execute function public.touch_edited();

do $$ begin
  alter table public.notifications
    add constraint notifications_automation_fk
    foreign key (automation_id) references public.notification_automations(id) on delete set null;
exception when duplicate_object then null; end $$;

-- «fired once» guard for the automations
create table if not exists public.notification_automation_runs (
  automation_id uuid not null references public.notification_automations(id) on delete cascade,
  ref_key       text not null,          -- 'exam:<id>' · 'online:<id>:<day>' · 'occasion:<id>' · 'att:<event>:<day>:<enrollment>'
  fired_at      timestamptz not null default now(),
  primary key (automation_id, ref_key)
);

-- ---------------------------------------------------------------------
-- 4. TABLE: push_subscriptions (one device)
-- ---------------------------------------------------------------------
create table if not exists public.push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  endpoint      text not null unique,
  p256dh        text not null,
  auth          text not null,
  profile_id    uuid references public.profiles(id) on delete cascade,   -- servant device
  person_id     uuid references public.persons(id)  on delete cascade,   -- child device
  user_agent    text,
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  failed_at     timestamptz,
  constraint push_sub_one_owner check (
    (profile_id is not null and person_id is null) or (profile_id is null and person_id is not null)
  )
);

comment on table public.push_subscriptions is
  'اشتراكات إشعارات الجهاز (Web Push) — جهاز واحد لخادم أو لمخدوم';

create index if not exists idx_push_sub_profile on public.push_subscriptions(profile_id);
create index if not exists idx_push_sub_person  on public.push_subscriptions(person_id);

-- scope chain checks (service ∈ church, class ∈ service)
create or replace function public.check_notif_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.service_id is not null and not exists (
    select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id
  ) then
    raise exception 'service does not belong to the church';
  end if;
  if new.class_id is not null and not exists (
    select 1 from public.classes c
     where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id
  ) then
    raise exception 'class does not belong to the service';
  end if;
  return new;
end $$;

drop trigger if exists trg_notifications_scope on public.notifications;
create trigger trg_notifications_scope before insert or update on public.notifications
for each row execute function public.check_notif_scope();
drop trigger if exists trg_notif_auto_scope on public.notification_automations;
create trigger trg_notif_auto_scope before insert or update on public.notification_automations
for each row execute function public.check_notif_scope();

-- ---------------------------------------------------------------------
-- 5. RLS
-- ---------------------------------------------------------------------
alter table public.notifications                enable row level security;
alter table public.notification_recipients      enable row level security;
alter table public.notification_automations     enable row level security;
alter table public.notification_automation_runs enable row level security;
alter table public.push_subscriptions           enable row level security;

-- notifications: history is visible inside my scope (or my own sends)
drop policy if exists notifications_select on public.notifications;
create policy notifications_select on public.notifications for select using (
  public.module_visible('notifications') and (
    created_by = auth.uid()
    or (church_id is null and public.is_owner())
    or (church_id is not null and public.scope_overlaps(church_id, service_id, class_id))
  )
);
-- writes go through notif_send / notif_cancel (security definer); deleting = creator or managers in scope
drop policy if exists notifications_delete on public.notifications;
create policy notifications_delete on public.notifications for delete using (
  public.module_visible('notifications') and (
    created_by = auth.uid()
    or (public.my_role() in ('owner', 'church_manager', 'service_manager')
        and ((church_id is null and public.is_owner()) or public.scope_contains(church_id, service_id, class_id)))
  )
);

-- recipients: a servant reads his own inbox rows; senders / managers read the
-- delivery rows of the notifications they can see (for the history counts)
drop policy if exists notif_rcpt_select on public.notification_recipients;
create policy notif_rcpt_select on public.notification_recipients for select using (
  profile_id = auth.uid()
  -- delivery rows of a send I made, or (managers) of any send visible to me — RLS of notifications applies
  or exists (select 1 from public.notifications n
              where n.id = notification_id
                and (n.created_by = auth.uid() or public.my_role() in ('owner', 'church_manager', 'service_manager')))
);
drop policy if exists notif_rcpt_update on public.notification_recipients;
create policy notif_rcpt_update on public.notification_recipients for update using (
  profile_id = auth.uid()
) with check (
  profile_id = auth.uid()
);

-- automations
drop policy if exists notif_auto_select on public.notification_automations;
create policy notif_auto_select on public.notification_automations for select using (
  public.module_visible('notifications') and (
    church_id is null or public.scope_overlaps(church_id, service_id, class_id)
  )
);
drop policy if exists notif_auto_insert on public.notification_automations;
create policy notif_auto_insert on public.notification_automations for insert with check (
  public.module_visible('notifications')
  and ((church_id is null and public.is_owner()) or public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists notif_auto_update on public.notification_automations;
create policy notif_auto_update on public.notification_automations for update using (
  public.module_visible('notifications')
  and ((church_id is null and public.is_owner()) or public.scope_contains(church_id, service_id, class_id))
) with check (
  public.module_visible('notifications')
  and ((church_id is null and public.is_owner()) or public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists notif_auto_delete on public.notification_automations;
create policy notif_auto_delete on public.notification_automations for delete using (
  public.module_visible('notifications')
  and ((church_id is null and public.is_owner()) or public.scope_contains(church_id, service_id, class_id))
);

drop policy if exists notif_auto_runs_select on public.notification_automation_runs;
create policy notif_auto_runs_select on public.notification_automation_runs for select using (
  exists (select 1 from public.notification_automations a where a.id = automation_id)
);

-- push subscriptions: my own devices only (children use the anon RPCs)
drop policy if exists push_sub_select on public.push_subscriptions;
create policy push_sub_select on public.push_subscriptions for select using (profile_id = auth.uid());
drop policy if exists push_sub_insert on public.push_subscriptions;
create policy push_sub_insert on public.push_subscriptions for insert with check (profile_id = auth.uid());
drop policy if exists push_sub_update on public.push_subscriptions;
create policy push_sub_update on public.push_subscriptions for update using (profile_id = auth.uid()) with check (profile_id = auth.uid());
drop policy if exists push_sub_delete on public.push_subscriptions;
create policy push_sub_delete on public.push_subscriptions for delete using (profile_id = auth.uid());

-- the anon role never reads these tables directly
revoke all on public.notifications, public.notification_recipients, public.notification_automations,
           public.notification_automation_runs, public.push_subscriptions from anon;

-- ---------------------------------------------------------------------
-- 6. HELPERS
-- ---------------------------------------------------------------------
-- [متغير] substitution: every key of p_vars replaces "[key]" in the text
create or replace function public.notif_render(p_text text, p_vars jsonb)
returns text language plpgsql immutable as $$
declare
  k text; v text; out text := coalesce(p_text, '');
begin
  if p_vars is null then return out; end if;
  for k, v in select key, value from jsonb_each_text(p_vars) loop
    out := replace(out, '[' || k || ']', coalesce(v, ''));
  end loop;
  return out;
end $$;

-- link must be an in-app path or an https URL
create or replace function public.notif_clean_link(p text)
returns text language sql immutable as $$
  select case
    when p is null or length(trim(p)) = 0 then null
    when trim(p) like '/%' or trim(p) like 'https://%' then left(trim(p), 500)
    else null end
$$;

-- «كنيسة ← خدمة ← فصل» label of a target, for the history list
create or replace function public.notif_target_label(
  p_kind text, p_church uuid, p_service uuid, p_class uuid, p_servant uuid, p_ids uuid[], p_audience text)
returns text language sql stable security definer set search_path = public as $$
  select case p_kind
    when 'all'     then case when p_audience = 'staff' then 'كل الخدام' else 'كل الكنائس' end
    when 'church'  then coalesce((select 'كنيسة ' || name from public.churches where id = p_church), 'كنيسة')
    when 'service' then coalesce((select 'خدمة ' || name from public.services where id = p_service), 'خدمة')
    when 'class'   then coalesce((select 'فصل ' || name from public.classes where id = p_class), 'فصل')
    when 'group'   then coalesce((select 'مجموعة ' || full_name from public.profiles where id = p_servant), 'مجموعة')
    when 'person'  then case
      when coalesce(array_length(p_ids, 1), 0) = 1 then coalesce((
        select pe.name from public.enrollments e join public.persons pe on pe.id = e.person_id where e.id = p_ids[1]), 'مخدوم')
      else coalesce(array_length(p_ids, 1), 0) || ' مخدوم' end
    else p_kind end
    || case when p_audience = 'staff' and p_kind <> 'all' then ' (الخدام)' else '' end
$$;

-- the servant profiles that cover a scope (recipient = staff / class_servants)
create or replace function public.notif_staff_in_scope(p_church uuid, p_service uuid, p_class uuid)
returns setof uuid language sql stable security definer set search_path = public as $$
  select t.id from public.profiles t
   where t.status = 'approved' and t.role <> 'owner'
     and (p_church is null or t.church_id = p_church)
     and (p_service is null or t.service_id is null or t.service_id = p_service)
     and (p_class   is null or t.class_id   is null or t.class_id   = p_class)
$$;

-- ---------------------------------------------------------------------
-- 7. MATERIALIZE the recipient rows of a notification (internal)
-- ---------------------------------------------------------------------
create or replace function public.notif_materialize(p_id uuid)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  n public.notifications;
  cnt integer := 0;
begin
  select * into n from public.notifications where id = p_id for update;
  if not found then return 0; end if;
  delete from public.notification_recipients where notification_id = n.id;

  if n.audience = 'staff' then
    insert into public.notification_recipients (notification_id, profile_id, title, body, image_url, link_url)
    select n.id, t, n.title, n.body, n.image_url, n.link_url
      from public.notif_staff_in_scope(n.church_id, n.service_id, n.class_id) t
     where t is distinct from n.created_by;
    get diagnostics cnt = row_count;
  else
    insert into public.notification_recipients (notification_id, enrollment_id, person_id, title, body, image_url, link_url)
    select n.id, e.id, e.person_id, n.title, n.body, n.image_url, n.link_url
      from public.enrollments e
     where case n.target_kind
             when 'person' then e.id = any(coalesce(n.enrollment_ids, '{}'))
             when 'group'  then exists (select 1 from public.shepherd_groups g where g.enrollment_id = e.id and g.servant_id = n.target_servant_id)
             else (n.church_id  is null or e.church_id  = n.church_id)
              and (n.service_id is null or e.service_id = n.service_id)
              and (n.class_id   is null or e.class_id   = n.class_id)
           end;
    get diagnostics cnt = row_count;
  end if;

  update public.notifications
     set status = case when cnt > 0 then 'sent' else 'failed' end,
         error  = case when cnt > 0 then null else 'no_recipients' end,
         sent_at = now(), recipients_count = cnt
   where id = n.id;
  return cnt;
end $$;
revoke all on function public.notif_materialize(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. RPC: notif_audience_count — preview «سيصل إلى N» before sending
-- ---------------------------------------------------------------------
create or replace function public.notif_audience_count(p jsonb)
returns integer language plpgsql stable security definer set search_path = public as $$
declare
  v_kind     text := coalesce(p->>'target_kind', 'class');
  v_aud      text := coalesce(p->>'audience', 'children');
  v_church   uuid := nullif(p->>'church_id', '')::uuid;
  v_service  uuid := nullif(p->>'service_id', '')::uuid;
  v_class    uuid := nullif(p->>'class_id', '')::uuid;
  v_servant  uuid := coalesce(nullif(p->>'target_servant_id', '')::uuid, auth.uid());
  v_ids      uuid[];
  s record;
begin
  if not public.module_visible('notifications') then return 0; end if;
  select * into s from public.my_scope();
  if not found then return 0; end if;
  if p ? 'enrollment_ids' and jsonb_typeof(p->'enrollment_ids') = 'array' then
    select array_agg(distinct x::uuid) into v_ids from jsonb_array_elements_text(p->'enrollment_ids') x;
  end if;

  if v_aud = 'staff' then
    if v_kind = 'all' and s.role <> 'owner' then return 0; end if;
    if v_kind <> 'all' and not public.scope_contains(v_church, v_service, v_class) then return 0; end if;
    return (select count(*)::int from public.notif_staff_in_scope(v_church, v_service, v_class) t where t <> auth.uid());
  end if;

  return (
    select count(*)::int from public.enrollments e
     where case v_kind
             when 'person' then e.id = any(coalesce(v_ids, '{}'))
               and public.enrollment_visible(e.church_id, e.service_id, e.class_id, s.role, s.church_id, s.service_id, s.class_id)
             when 'group'  then exists (select 1 from public.shepherd_groups g where g.enrollment_id = e.id and g.servant_id = v_servant)
               and public.enrollment_visible(e.church_id, e.service_id, e.class_id, s.role, s.church_id, s.service_id, s.class_id)
             when 'all'    then s.role = 'owner'
             else public.scope_contains(v_church, v_service, v_class)
              and (v_church  is null or e.church_id  = v_church)
              and (v_service is null or e.service_id = v_service)
              and (v_class   is null or e.class_id   = v_class)
           end);
end $$;
grant execute on function public.notif_audience_count(jsonb) to authenticated;

-- ---------------------------------------------------------------------
-- 9. RPC: notif_send — the ONE write entry for servants
--    p: { title, body?, image_url?, link_url?, audience?: 'children'|'staff',
--         target_kind: 'all'|'church'|'service'|'class'|'group'|'person',
--         church_id?, service_id?, class_id?, target_servant_id?,
--         enrollment_ids?: uuid[], scheduled_at?: timestamptz }
-- ---------------------------------------------------------------------
create or replace function public.notif_send(p jsonb)
returns public.notifications language plpgsql volatile security definer set search_path = public as $$
declare
  v_uid      uuid := auth.uid();
  v_title    text := trim(coalesce(p->>'title', ''));
  v_body     text := trim(coalesce(p->>'body', ''));
  v_image    text := nullif(trim(coalesce(p->>'image_url', '')), '');
  v_link     text := public.notif_clean_link(p->>'link_url');
  v_kind     text := coalesce(p->>'target_kind', 'class');
  v_aud      text := coalesce(p->>'audience', 'children');
  v_church   uuid := nullif(p->>'church_id', '')::uuid;
  v_service  uuid := nullif(p->>'service_id', '')::uuid;
  v_class    uuid := nullif(p->>'class_id', '')::uuid;
  v_servant  uuid := nullif(p->>'target_servant_id', '')::uuid;
  v_when     timestamptz := nullif(p->>'scheduled_at', '')::timestamptz;
  v_ids      uuid[];
  v_id       uuid;
  e          public.enrollments;
  t          public.profiles;
  s          record;
  n          public.notifications;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not public.module_visible('notifications') then raise exception 'module_not_visible' using errcode = '42501'; end if;
  select * into s from public.my_scope();
  if not found then raise exception 'not_approved' using errcode = '42501'; end if;
  if length(v_title) = 0 then raise exception 'empty_title' using errcode = '22023'; end if;
  if length(v_title) > 120 or length(v_body) > 1000 then raise exception 'text_too_long' using errcode = '22023'; end if;
  if v_aud not in ('children', 'staff') then raise exception 'bad_audience' using errcode = '22023'; end if;
  if v_when is not null and v_when < now() - interval '1 minute' then raise exception 'schedule_in_past' using errcode = '22023'; end if;
  if v_when is not null and v_when < now() + interval '30 seconds' then v_when := null; end if;   -- «now» in effect

  -- normalize the scope per target kind + permission check
  if v_kind = 'all' then
    if s.role <> 'owner' then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
    v_church := null; v_service := null; v_class := null;
  elsif v_kind = 'church' then
    v_service := null; v_class := null;
    if v_church is null or not public.scope_contains(v_church, null, null) then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
  elsif v_kind = 'service' then
    v_class := null;
    if v_church is null or v_service is null or not public.scope_contains(v_church, v_service, null) then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
  elsif v_kind = 'class' then
    if v_church is null or v_service is null or v_class is null or not public.scope_contains(v_church, v_service, v_class) then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
  elsif v_kind = 'group' then
    if v_aud = 'staff' then raise exception 'bad_target' using errcode = '22023'; end if;
    v_servant := coalesce(v_servant, v_uid);
    if v_servant <> v_uid then
      select * into t from public.profiles where id = v_servant;
      if not found or s.role = 'class_servant' or not public.can_access(t.church_id, t.service_id, t.class_id) then
        raise exception 'scope_not_allowed' using errcode = '42501';
      end if;
    end if;
    -- keep the group's scope for the history label
    select g.church_id, g.service_id, g.class_id into v_church, v_service, v_class
      from public.shepherd_groups g where g.servant_id = v_servant limit 1;
    if v_church is null then v_service := null; v_class := null; end if;
    if v_service is not null and exists (select 1 from public.shepherd_groups g where g.servant_id = v_servant and g.service_id <> v_service) then v_service := null; v_class := null; end if;
    if v_class is not null and exists (select 1 from public.shepherd_groups g where g.servant_id = v_servant and g.class_id <> v_class) then v_class := null; end if;
  elsif v_kind = 'person' then
    if v_aud = 'staff' then raise exception 'bad_target' using errcode = '22023'; end if;
    if not (p ? 'enrollment_ids' and jsonb_typeof(p->'enrollment_ids') = 'array' and jsonb_array_length(p->'enrollment_ids') > 0) then
      raise exception 'no_recipients' using errcode = '22023';
    end if;
    select array_agg(distinct x::uuid) into v_ids from jsonb_array_elements_text(p->'enrollment_ids') x;
    if array_length(v_ids, 1) > 500 then raise exception 'too_many_recipients' using errcode = '22023'; end if;
    v_church := null; v_service := null; v_class := null;
    foreach v_id in array v_ids loop
      select * into e from public.enrollments where id = v_id;
      if not found then raise exception 'enrollment_not_found' using errcode = 'P0002'; end if;
      if not public.enrollment_visible(e.church_id, e.service_id, e.class_id, s.role, s.church_id, s.service_id, s.class_id) then
        raise exception 'enrollment_not_visible' using errcode = '42501';
      end if;
      if array_length(v_ids, 1) = 1 then v_church := e.church_id; v_service := e.service_id; v_class := e.class_id; end if;
    end loop;
  else
    raise exception 'bad_target' using errcode = '22023';
  end if;

  insert into public.notifications (church_id, service_id, class_id, title, body, image_url, link_url, target_kind, audience,
                                    target_servant_id, enrollment_ids, status, scheduled_at, source, created_by)
  values (v_church, v_service, v_class, v_title, v_body, v_image, v_link, v_kind, v_aud,
          case when v_kind = 'group' then v_servant end, v_ids,
          case when v_when is null then 'sent' else 'scheduled' end, v_when, 'manual', v_uid)
  returning * into n;

  if v_when is null then
    perform public.notif_materialize(n.id);
    select * into n from public.notifications where id = n.id;
  end if;
  return n;
end $$;
grant execute on function public.notif_send(jsonb) to authenticated;

-- cancel a scheduled send (creator or managers in scope)
create or replace function public.notif_cancel(p_id uuid)
returns public.notifications language plpgsql volatile security definer set search_path = public as $$
declare
  n public.notifications; s record;
begin
  if not public.module_visible('notifications') then raise exception 'module_not_visible' using errcode = '42501'; end if;
  select * into s from public.my_scope();
  select * into n from public.notifications where id = p_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if n.status <> 'scheduled' then raise exception 'not_scheduled' using errcode = 'P0001'; end if;
  if not (n.created_by = auth.uid()
          or (s.role in ('owner', 'church_manager', 'service_manager')
              and ((n.church_id is null and s.role = 'owner') or public.scope_contains(n.church_id, n.service_id, n.class_id)))) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  update public.notifications set status = 'cancelled' where id = n.id returning * into n;
  return n;
end $$;
grant execute on function public.notif_cancel(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 10. RPC: notif_history — sent / scheduled / failed list for the servant
-- ---------------------------------------------------------------------
create or replace function public.notif_history(p_limit integer default 60, p_before timestamptz default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select case when not public.module_visible('notifications') then '[]'::jsonb else coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', n.id, 'title', n.title, 'body', n.body, 'image_url', n.image_url, 'link_url', n.link_url,
             'target_kind', n.target_kind, 'audience', n.audience,
             'church_id', n.church_id, 'service_id', n.service_id, 'class_id', n.class_id,
             'target_label', public.notif_target_label(n.target_kind, n.church_id, n.service_id, n.class_id, n.target_servant_id, n.enrollment_ids, n.audience),
             'status', n.status, 'scheduled_at', n.scheduled_at, 'sent_at', n.sent_at, 'created_at', n.created_at,
             'recipients_count', n.recipients_count, 'error', n.error, 'source', n.source,
             'automation_id', n.automation_id, 'automation_name', a.name,
             'sender_name', sp.full_name, 'is_mine', n.created_by = auth.uid(),
             'read_count', (select count(*) from public.notification_recipients r where r.notification_id = n.id and r.read_at is not null),
             'push_sent',  (select count(*) from public.notification_recipients r where r.notification_id = n.id and r.push_status = 'sent'),
             'can_cancel', n.status = 'scheduled' and (n.created_by = auth.uid() or public.my_role() in ('owner', 'church_manager', 'service_manager'))
           ) order by coalesce(n.scheduled_at, n.created_at) desc)
      from (
        select * from public.notifications n
         where (p_before is null or coalesce(n.scheduled_at, n.created_at) < p_before)
           and (n.created_by = auth.uid()
                or (n.church_id is null and public.is_owner())
                or (n.church_id is not null and public.scope_overlaps(n.church_id, n.service_id, n.class_id)))
         order by coalesce(n.scheduled_at, n.created_at) desc
         limit greatest(1, least(coalesce(p_limit, 60), 200))
      ) n
      left join public.profiles sp on sp.id = n.created_by
      left join public.notification_automations a on a.id = n.automation_id
  ), '[]'::jsonb) end
$$;
grant execute on function public.notif_history(integer, timestamptz) to authenticated;

-- ---------------------------------------------------------------------
-- 11. SERVANT INBOX (the bell) — my own recipient rows
-- ---------------------------------------------------------------------
create or replace function public.notif_inbox(p_limit integer default 50)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', r.id, 'notification_id', r.notification_id, 'title', r.title, 'body', r.body,
             'image_url', r.image_url, 'link_url', r.link_url, 'read_at', r.read_at, 'created_at', r.created_at,
             'sender_name', sp.full_name, 'source', n.source
           ) order by r.created_at desc)
      from (select * from public.notification_recipients where profile_id = auth.uid()
             order by created_at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) r
      left join public.notifications n on n.id = r.notification_id
      left join public.profiles sp on sp.id = n.created_by
  ), '[]'::jsonb)
$$;
grant execute on function public.notif_inbox(integer) to authenticated;

create or replace function public.notif_unread_count()
returns integer language sql stable security definer set search_path = public as $$
  select count(*)::int from public.notification_recipients where profile_id = auth.uid() and read_at is null
$$;
grant execute on function public.notif_unread_count() to authenticated;

-- p_ids null = mark everything read
create or replace function public.notif_mark_read(p_ids uuid[] default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare n integer;
begin
  update public.notification_recipients
     set read_at = now()
   where profile_id = auth.uid() and read_at is null
     and (p_ids is null or id = any(p_ids));
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.notif_mark_read(uuid[]) to authenticated;

-- ---------------------------------------------------------------------
-- 12. CHILD PORTAL (anon, token = national id)
-- ---------------------------------------------------------------------
create or replace function public.child_notifications(p_national_id text, p_limit integer default 50)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', r.id, 'notification_id', r.notification_id, 'title', r.title, 'body', r.body,
             'image_url', r.image_url, 'link_url', r.link_url, 'read_at', r.read_at, 'created_at', r.created_at,
             'sender_name', sp.full_name, 'source', n.source
           ) order by r.created_at desc)
      from (select * from public.notification_recipients where person_id = p.id
             order by created_at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) r
      left join public.notifications n on n.id = r.notification_id
      left join public.profiles sp on sp.id = n.created_by
  ), '[]'::jsonb);
end $$;
grant execute on function public.child_notifications(text, integer) to anon, authenticated;

create or replace function public.child_notif_unread(p_national_id text)
returns integer language plpgsql stable security definer set search_path = public as $$
declare p public.persons;
begin
  p := public.child_portal_person(p_national_id);
  return (select count(*)::int from public.notification_recipients where person_id = p.id and read_at is null);
end $$;
grant execute on function public.child_notif_unread(text) to anon, authenticated;

create or replace function public.child_notif_mark_read(p_national_id text, p_ids uuid[] default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare p public.persons; n integer;
begin
  p := public.child_portal_person(p_national_id);
  update public.notification_recipients set read_at = now()
   where person_id = p.id and read_at is null and (p_ids is null or id = any(p_ids));
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.child_notif_mark_read(text, uuid[]) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 13. PUSH SUBSCRIPTIONS (device registration)
-- ---------------------------------------------------------------------
-- servant: {endpoint, keys:{p256dh, auth}, user_agent?}
create or replace function public.push_subscribe(p jsonb)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  v_endpoint text := trim(coalesce(p->>'endpoint', ''));
  v_p256 text := coalesce(p->'keys'->>'p256dh', p->>'p256dh');
  v_auth text := coalesce(p->'keys'->>'auth', p->>'auth');
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if v_endpoint not like 'https://%' or v_p256 is null or v_auth is null then raise exception 'bad_subscription' using errcode = '22023'; end if;
  insert into public.push_subscriptions (endpoint, p256dh, auth, profile_id, person_id, user_agent)
  values (v_endpoint, v_p256, v_auth, auth.uid(), null, left(p->>'user_agent', 300))
  on conflict (endpoint) do update
    set p256dh = excluded.p256dh, auth = excluded.auth, profile_id = excluded.profile_id, person_id = null,
        user_agent = excluded.user_agent, last_seen_at = now(), failed_at = null
  returning id into v_id;
  return v_id;
end $$;
grant execute on function public.push_subscribe(jsonb) to authenticated;

create or replace function public.push_unsubscribe(p_endpoint text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
begin
  delete from public.push_subscriptions where endpoint = p_endpoint and profile_id = auth.uid();
  return found;
end $$;
grant execute on function public.push_unsubscribe(text) to authenticated;

-- child device (anon, token = national id)
create or replace function public.child_push_subscribe(p_national_id text, p jsonb)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  pe public.persons;
  v_endpoint text := trim(coalesce(p->>'endpoint', ''));
  v_p256 text := coalesce(p->'keys'->>'p256dh', p->>'p256dh');
  v_auth text := coalesce(p->'keys'->>'auth', p->>'auth');
  v_id uuid;
begin
  pe := public.child_portal_person(p_national_id);
  if v_endpoint not like 'https://%' or v_p256 is null or v_auth is null then raise exception 'bad_subscription' using errcode = '22023'; end if;
  insert into public.push_subscriptions (endpoint, p256dh, auth, profile_id, person_id, user_agent)
  values (v_endpoint, v_p256, v_auth, null, pe.id, left(p->>'user_agent', 300))
  on conflict (endpoint) do update
    set p256dh = excluded.p256dh, auth = excluded.auth, person_id = excluded.person_id, profile_id = null,
        user_agent = excluded.user_agent, last_seen_at = now(), failed_at = null
  returning id into v_id;
  return v_id;
end $$;
grant execute on function public.child_push_subscribe(text, jsonb) to anon, authenticated;

create or replace function public.child_push_unsubscribe(p_national_id text, p_endpoint text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare pe public.persons;
begin
  pe := public.child_portal_person(p_national_id);
  delete from public.push_subscriptions where endpoint = p_endpoint and person_id = pe.id;
  return found;
end $$;
grant execute on function public.child_push_unsubscribe(text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 14. PUSH QUEUE for the dispatcher (service role ONLY)
-- ---------------------------------------------------------------------
create or replace function public.notif_push_queue(p_limit integer default 200)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare out jsonb;
begin
  -- recipients without any device → no_device (done)
  update public.notification_recipients r set push_status = 'no_device'
   where r.push_status = 'pending'
     and not exists (select 1 from public.push_subscriptions s
                      where s.failed_at is null
                        and ((r.person_id is not null and s.person_id = r.person_id)
                          or (r.profile_id is not null and s.profile_id = r.profile_id)));
  select coalesce(jsonb_agg(jsonb_build_object(
           'recipient_id', r.id, 'subscription_id', s.id,
           'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth,
           'title', r.title, 'body', r.body, 'image_url', r.image_url, 'link_url', r.link_url,
           'is_child', r.person_id is not null, 'notification_id', r.notification_id
         )), '[]'::jsonb) into out
    from (select * from public.notification_recipients where push_status = 'pending'
           order by created_at limit greatest(1, least(coalesce(p_limit, 200), 1000))) r
    join public.push_subscriptions s
      on s.failed_at is null
     and ((r.person_id is not null and s.person_id = r.person_id) or (r.profile_id is not null and s.profile_id = r.profile_id));
  return out;
end $$;
revoke all on function public.notif_push_queue(integer) from public, anon, authenticated;
grant execute on function public.notif_push_queue(integer) to service_role;

-- p: [{recipient_id, subscription_id, ok: bool, gone: bool, error?}]
create or replace function public.notif_push_mark(p jsonb)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare x jsonb; n integer := 0;
begin
  for x in select * from jsonb_array_elements(coalesce(p, '[]'::jsonb)) loop
    if (x->>'ok')::boolean then
      update public.notification_recipients set push_status = 'sent', pushed_at = now(), push_error = null
       where id = (x->>'recipient_id')::uuid and push_status in ('pending', 'failed');
      update public.push_subscriptions set last_seen_at = now(), failed_at = null where id = (x->>'subscription_id')::uuid;
    else
      if coalesce((x->>'gone')::boolean, false) then
        delete from public.push_subscriptions where id = (x->>'subscription_id')::uuid;
      else
        update public.push_subscriptions set failed_at = now() where id = (x->>'subscription_id')::uuid;
      end if;
      update public.notification_recipients set push_status = 'failed', push_error = left(x->>'error', 300)
       where id = (x->>'recipient_id')::uuid and push_status = 'pending';
    end if;
    n := n + 1;
  end loop;
  -- recipients whose every device is now gone / failed
  update public.notification_recipients r set push_status = 'no_device'
   where r.push_status = 'pending'
     and not exists (select 1 from public.push_subscriptions s
                      where s.failed_at is null
                        and ((r.person_id is not null and s.person_id = r.person_id)
                          or (r.profile_id is not null and s.profile_id = r.profile_id)));
  return n;
end $$;
revoke all on function public.notif_push_mark(jsonb) from public, anon, authenticated;
grant execute on function public.notif_push_mark(jsonb) to service_role;

-- ---------------------------------------------------------------------
-- 15. AUTOMATIONS ENGINE — App event → automatic notification
--     Two entry points, reusable for future triggers:
--       notif_fire_enrollment(trigger, enrollment, vars, default_link, ref)
--         → the event concerns ONE child (attendance, points, achievement)
--       notif_fire_scope(trigger, church, service, class, vars, link, ref, ids)
--         → the event concerns a whole scope (class live, exam published)
--     Every automation whose trigger + scope match creates ONE notification
--     (source = 'automation') with the rendered title / body and the
--     recipient rows (student → the child · class_servants → the servants
--     covering the class). Triggers never break the parent operation.
-- ---------------------------------------------------------------------
create or replace function public.notif_module_covers(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.module_access m
     where m.module_key = 'notifications'
       and (m.church_id is null
            or (m.church_id = p_church
                and (m.service_id is null or p_service is null or m.service_id = p_service)
                and (m.class_id   is null or p_class   is null or m.class_id   = p_class)))
  )
$$;
revoke all on function public.notif_module_covers(uuid, uuid, uuid) from public, anon, authenticated;

-- the standard variables of a child (merged with the trigger's own)
create or replace function public.notif_enrollment_vars(p_enrollment uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
           'الاسم', pe.name,
           'الاسم الأول', split_part(pe.name, ' ', 1),
           'الرصيد', e.points,
           'عدد الحضور', e.attendance_count,
           'الفصل', cl.name, 'الخدمة', sv.name, 'الكنيسة', ch.name,
           'التاريخ', to_char(now() at time zone 'Africa/Cairo', 'YYYY-MM-DD'),
           'الوقت', to_char(now() at time zone 'Africa/Cairo', 'HH24:MI'))
    from public.enrollments e
    join public.persons pe on pe.id = e.person_id
    join public.churches ch on ch.id = e.church_id
    join public.services sv on sv.id = e.service_id
    join public.classes  cl on cl.id = e.class_id
   where e.id = p_enrollment
$$;
revoke all on function public.notif_enrollment_vars(uuid) from public, anon, authenticated;

create or replace function public.notif_fire_enrollment(
  p_trigger text, p_enrollment uuid, p_vars jsonb default '{}'::jsonb,
  p_default_link text default null, p_ref text default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  e public.enrollments;
  a public.notification_automations;
  vars jsonb;
  n_id uuid;
  fired integer := 0;
  v_title text; v_body text; v_link text;
begin
  select * into e from public.enrollments where id = p_enrollment;
  if not found then return 0; end if;
  if not exists (select 1 from public.notification_automations where trigger_key = p_trigger and is_active) then return 0; end if;
  if not public.notif_module_covers(e.church_id, e.service_id, e.class_id) then return 0; end if;
  vars := coalesce(public.notif_enrollment_vars(e.id), '{}'::jsonb) || coalesce(p_vars, '{}'::jsonb);

  for a in
    select * from public.notification_automations x
     where x.trigger_key = p_trigger and x.is_active
       and (x.church_id  is null or x.church_id  = e.church_id)
       and (x.service_id is null or x.service_id = e.service_id)
       and (x.class_id   is null or x.class_id   = e.class_id)
  loop
    -- per-trigger config filters
    if p_trigger in ('points_added', 'points_deducted')
       and abs(coalesce((p_vars->>'_delta')::int, 0)) < coalesce((a.config->>'min_points')::int, 1) then
      continue;
    end if;
    -- «once per ref» guard (e.g. one attendance notification per day per child)
    if p_ref is not null then
      begin
        insert into public.notification_automation_runs (automation_id, ref_key) values (a.id, p_ref || ':' || e.id);
      exception when unique_violation then continue; end;
    end if;

    v_title := left(public.notif_render(a.title_template, vars), 120);
    v_body  := left(public.notif_render(a.body_template, vars), 1000);
    v_link  := coalesce(public.notif_clean_link(a.link_url), public.notif_clean_link(p_default_link));
    if length(trim(v_title)) = 0 then v_title := a.name; end if;

    insert into public.notifications (church_id, service_id, class_id, title, body, image_url, link_url, target_kind, audience,
                                      enrollment_ids, status, sent_at, source, automation_id, created_by)
    values (e.church_id, e.service_id, e.class_id, v_title, v_body, a.image_url, v_link,
            'person', case when a.recipient = 'class_servants' then 'staff' else 'children' end,
            array[e.id], 'sent', now(), 'automation', a.id, null)
    returning id into n_id;

    if a.recipient = 'class_servants' then
      insert into public.notification_recipients (notification_id, profile_id, title, body, image_url, link_url)
      select n_id, t, v_title, v_body, a.image_url, v_link
        from public.notif_staff_in_scope(e.church_id, e.service_id, e.class_id) t;
    else
      insert into public.notification_recipients (notification_id, enrollment_id, person_id, title, body, image_url, link_url)
      values (n_id, e.id, e.person_id, v_title, v_body, a.image_url, v_link);
    end if;
    update public.notifications set recipients_count = (select count(*) from public.notification_recipients where notification_id = n_id),
           status = case when exists (select 1 from public.notification_recipients where notification_id = n_id) then 'sent' else 'failed' end
     where id = n_id;
    fired := fired + 1;
  end loop;
  return fired;
end $$;
revoke all on function public.notif_fire_enrollment(text, uuid, jsonb, text, text) from public, anon, authenticated;

create or replace function public.notif_fire_scope(
  p_trigger text, p_church uuid, p_service uuid, p_class uuid, p_vars jsonb default '{}'::jsonb,
  p_default_link text default null, p_ref text default null, p_enrollment_ids uuid[] default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  a public.notification_automations;
  vars jsonb;
  n_id uuid;
  fired integer := 0;
  v_title text; v_body text; v_link text;
  v_church uuid; v_service uuid; v_class uuid;
  cnt integer;
begin
  if p_church is null then return 0; end if;
  if not exists (select 1 from public.notification_automations where trigger_key = p_trigger and is_active) then return 0; end if;
  if not public.notif_module_covers(p_church, p_service, p_class) then return 0; end if;
  vars := jsonb_build_object(
            'الكنيسة', (select name from public.churches where id = p_church),
            'الخدمة',  (select name from public.services where id = p_service),
            'الفصل',   (select name from public.classes  where id = p_class),
            'التاريخ', to_char(now() at time zone 'Africa/Cairo', 'YYYY-MM-DD'),
            'الوقت',   to_char(now() at time zone 'Africa/Cairo', 'HH24:MI'))
          || coalesce(p_vars, '{}'::jsonb);

  for a in
    select * from public.notification_automations x
     where x.trigger_key = p_trigger and x.is_active
       and (x.church_id  is null or x.church_id  = p_church)
       and (x.service_id is null or p_service is null or x.service_id = p_service)
       and (x.class_id   is null or p_class   is null or x.class_id   = p_class)
  loop
    if p_ref is not null then
      begin
        insert into public.notification_automation_runs (automation_id, ref_key) values (a.id, p_ref);
      exception when unique_violation then continue; end;
    end if;
    -- effective scope = the narrower of the event's and the automation's
    v_church  := p_church;
    v_service := coalesce(p_service, a.service_id);
    v_class   := coalesce(p_class, a.class_id);
    if v_class is not null and v_service is null then
      select service_id into v_service from public.classes where id = v_class;
    end if;

    v_title := left(public.notif_render(a.title_template, vars), 120);
    v_body  := left(public.notif_render(a.body_template, vars), 1000);
    v_link  := coalesce(public.notif_clean_link(a.link_url), public.notif_clean_link(p_default_link));
    if length(trim(v_title)) = 0 then v_title := a.name; end if;

    insert into public.notifications (church_id, service_id, class_id, title, body, image_url, link_url, target_kind, audience,
                                      enrollment_ids, status, sent_at, source, automation_id, created_by)
    values (v_church, v_service, v_class, v_title, v_body, a.image_url, v_link,
            case when p_enrollment_ids is not null then 'person' when v_class is not null then 'class' when v_service is not null then 'service' else 'church' end,
            case when a.recipient = 'class_servants' then 'staff' else 'children' end,
            p_enrollment_ids, 'sent', now(), 'automation', a.id, null)
    returning id into n_id;

    if a.recipient = 'class_servants' then
      insert into public.notification_recipients (notification_id, profile_id, title, body, image_url, link_url)
      select n_id, t, v_title, v_body, a.image_url, v_link
        from public.notif_staff_in_scope(v_church, v_service, v_class) t;
    else
      insert into public.notification_recipients (notification_id, enrollment_id, person_id, title, body, image_url, link_url)
      select n_id, e.id, e.person_id, v_title, v_body, a.image_url, v_link
        from public.enrollments e
       where e.church_id = v_church
         and (v_service is null or e.service_id = v_service)
         and (v_class   is null or e.class_id   = v_class)
         and (p_enrollment_ids is null or e.id = any(p_enrollment_ids));
    end if;
    select count(*) into cnt from public.notification_recipients where notification_id = n_id;
    update public.notifications set recipients_count = cnt, status = case when cnt > 0 then 'sent' else 'failed' end,
           error = case when cnt > 0 then null else 'no_recipients' end
     where id = n_id;
    fired := fired + 1;
  end loop;
  return fired;
end $$;
revoke all on function public.notif_fire_scope(text, uuid, uuid, uuid, jsonb, text, text, uuid[]) from public, anon, authenticated;

-- ---- trigger: attendance (attendance_log insert) — once per event per day ----
create or replace function public.notif_on_attendance()
returns trigger language plpgsql security definer set search_path = public as $$
declare ev text;
begin
  begin
    select name into ev from public.events where id = new.event_id;
    perform public.notif_fire_enrollment('attendance', new.enrollment_id,
      jsonb_build_object('المناسبة', coalesce(ev, 'الحضور'), 'النقاط', new.points_delta, '_delta', new.points_delta),
      '/child/attendance', 'att:' || coalesce(new.event_id::text, '-') || ':' || (now() at time zone 'Africa/Cairo')::date);
  exception when others then
    raise notice 'notif_on_attendance skipped: %', sqlerrm;
  end;
  return new;
end $$;
drop trigger if exists zz_notif_on_attendance on public.attendance_log;
create trigger zz_notif_on_attendance after insert on public.attendance_log
for each row execute function public.notif_on_attendance();

-- ---- trigger: points added / deducted (points_log insert) ----
create or replace function public.notif_on_points()
returns trigger language plpgsql security definer set search_path = public as $$
declare cause text; ev text;
begin
  if new.delta = 0 then return new; end if;
  begin
    select name into cause from public.causes where id = new.cause_id;
    select name into ev from public.events where id = new.event_id;
    perform public.notif_fire_enrollment(
      case when new.delta > 0 then 'points_added' else 'points_deducted' end, new.enrollment_id,
      jsonb_build_object('النقاط', abs(new.delta), 'السبب', coalesce(cause, ''), 'المناسبة', coalesce(ev, ''), '_delta', new.delta),
      '/child/points', null);
  exception when others then
    raise notice 'notif_on_points skipped: %', sqlerrm;
  end;
  return new;
end $$;
drop trigger if exists zz_notif_on_points on public.points_log;
create trigger zz_notif_on_points after insert on public.points_log
for each row execute function public.notif_on_points();

-- ---- trigger: achievement earned (user_achievements insert) ----
create or replace function public.notif_on_achievement()
returns trigger language plpgsql security definer set search_path = public as $$
declare a_name text;
begin
  begin
    select name into a_name from public.achievements where id = new.achievement_id;
    perform public.notif_fire_enrollment('achievement_earned', new.enrollment_id,
      jsonb_build_object('الإنجاز', coalesce(a_name, ''), 'النقاط', new.points_awarded, '_delta', new.points_awarded),
      '/child/achievements', null);
  exception when others then
    raise notice 'notif_on_achievement skipped: %', sqlerrm;
  end;
  return new;
end $$;
do $$ begin
  if to_regclass('public.user_achievements') is not null then
    drop trigger if exists zz_notif_on_achievement on public.user_achievements;
    create trigger zz_notif_on_achievement after insert on public.user_achievements
    for each row execute function public.notif_on_achievement();
  end if;
end $$;

-- ---- trigger: online class started (online_classes status → live) ----
create or replace function public.notif_on_online_live()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'live' and (tg_op = 'INSERT' or old.status is distinct from 'live') then
    begin
      perform public.notif_fire_scope('online_class_started', new.church_id, new.service_id, new.class_id,
        jsonb_build_object('العنوان', new.title, 'المنصة', new.platform,
                           'الوقت', to_char(new.starts_at at time zone 'Africa/Cairo', 'HH24:MI')),
        '/child/online/' || new.id, 'online:' || new.id || ':' || coalesce(new.started_at, now())::date);
    exception when others then
      raise notice 'notif_on_online_live skipped: %', sqlerrm;
    end;
  end if;
  return new;
end $$;
do $$ begin
  if to_regclass('public.online_classes') is not null then
    drop trigger if exists zz_notif_on_online_live on public.online_classes;
    create trigger zz_notif_on_online_live after insert or update of status on public.online_classes
    for each row execute function public.notif_on_online_live();
  end if;
end $$;

-- ---- trigger: exam published (exams status → published, already open) ----
create or replace function public.notif_on_exam_published()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published')
     and (new.opens_at is null or new.opens_at <= now()) then
    begin
      perform public.notif_fire_scope('exam_published', new.church_id, new.service_id, new.class_id,
        jsonb_build_object('العنوان', new.title,
                           'آخر موعد', coalesce(to_char(new.closes_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI'), '')),
        '/child/exams/' || new.id, 'exam:' || new.id);
    exception when others then
      raise notice 'notif_on_exam_published skipped: %', sqlerrm;
    end;
  end if;
  return new;
end $$;
do $$ begin
  if to_regclass('public.exams') is not null then
    drop trigger if exists zz_notif_on_exam_published on public.exams;
    create trigger zz_notif_on_exam_published after insert or update of status, opens_at on public.exams
    for each row execute function public.notif_on_exam_published();
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 16. notif_tick() — due scheduled sends + occasion reminders + exams
--     whose opens_at has arrived. Called by pg_cron (every minute, when
--     the extension exists) and by the dispatch API route.
-- ---------------------------------------------------------------------
create or replace function public.notif_tick()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r record; au record; released integer := 0; reminders integer := 0; exams_n integer := 0;
  ids uuid[];
begin
  -- 1) scheduled sends whose time has come
  for r in select id from public.notifications where status = 'scheduled' and scheduled_at <= now()
           order by scheduled_at limit 100 loop
    perform public.notif_materialize(r.id);
    released := released + 1;
  end loop;

  -- 2) occasion reminders: every active automation × published occasion that
  --    starts within `hours_before` (default 24) — once per (automation, occasion)
  if to_regclass('public.occasions') is not null then
    for au in select * from public.notification_automations where trigger_key = 'occasion_reminder' and is_active loop
      for r in
        select o.* from public.occasions o
         where o.status = 'published'
           and o.starts_at > now()
           and o.starts_at <= now() + make_interval(hours => coalesce((au.config->>'hours_before')::int, 24))
           and (au.church_id  is null or au.church_id  = o.church_id)
           and (au.service_id is null or o.service_id is null or au.service_id = o.service_id)
           and (au.class_id   is null or o.class_id   is null or au.class_id   = o.class_id)
           and not exists (select 1 from public.notification_automation_runs x where x.automation_id = au.id and x.ref_key = 'occasion:' || o.id)
      loop
        -- registered participants only; when nobody registered → the whole scope
        select array_agg(enrollment_id) into ids
          from public.occasion_registrations g where g.occasion_id = r.id and g.status in ('pending', 'confirmed');
        reminders := reminders + public.notif_fire_scope('occasion_reminder', r.church_id, r.service_id, r.class_id,
          jsonb_build_object('العنوان', r.title, 'المكان', coalesce(r.location, ''),
                             'التاريخ', to_char(r.starts_at at time zone 'Africa/Cairo', 'YYYY-MM-DD'),
                             'الوقت', to_char(r.starts_at at time zone 'Africa/Cairo', 'HH24:MI')),
          '/child/occasions/' || r.id, 'occasion:' || r.id, ids);
      end loop;
    end loop;
  end if;

  -- 3) exams published earlier with a future opens_at that has now arrived
  if to_regclass('public.exams') is not null then
    for r in select x.* from public.exams x
              where x.status = 'published' and x.opens_at is not null and x.opens_at <= now() and x.opens_at > now() - interval '1 day'
                and exists (select 1 from public.notification_automations a where a.trigger_key = 'exam_published' and a.is_active
                            and not exists (select 1 from public.notification_automation_runs z where z.automation_id = a.id and z.ref_key = 'exam:' || x.id))
    loop
      exams_n := exams_n + public.notif_fire_scope('exam_published', r.church_id, r.service_id, r.class_id,
        jsonb_build_object('العنوان', r.title, 'آخر موعد', coalesce(to_char(r.closes_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI'), '')),
        '/child/exams/' || r.id, 'exam:' || r.id);
    end loop;
  end if;

  return jsonb_build_object('released', released, 'reminders', reminders, 'exams', exams_n, 'at', now());
end $$;
revoke all on function public.notif_tick() from public, anon, authenticated;
grant execute on function public.notif_tick() to service_role;

-- pg_cron (Supabase: Database → Extensions → pg_cron). Skipped silently elsewhere.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'notif_tick';
    perform cron.schedule('notif_tick', '* * * * *', 'select public.notif_tick()');
  end if;
exception when others then
  raise notice 'pg_cron schedule skipped: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------
-- 17. PERMISSIONS summary for the UI
-- ---------------------------------------------------------------------
create or replace function public.notif_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'visible', public.module_visible('notifications'),
    'can_send_all', public.is_owner(),
    'can_manage', public.my_role() in ('owner', 'church_manager', 'service_manager'),
    'role', public.my_role()
  )
$$;
grant execute on function public.notif_permissions() to authenticated;

-- ---------------------------------------------------------------------
-- 18. REALTIME
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['notifications', 'notification_recipients', 'notification_automations'] loop
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
alter table public.notifications            replica identity full;
alter table public.notification_recipients  replica identity full;
alter table public.notification_automations replica identity full;

-- storage: notification images go to photos/notifications (authenticated write — policy from 0005)



-- #####################################################################
-- ##  0035_app_customization.sql
-- #####################################################################

-- =====================================================================
-- 0035: APP CUSTOMIZATION (تخصيص التطبيق) — owner-controlled settings
--
-- A tiny key/value store for APP-WIDE customization decided by the OWNER
-- from وحدة المالك → تخصيص التطبيق. First consumer: the NAVIGATION layout
--
--   key = 'navigation' → {
--     version: 1,
--     taskbar: [{ key, icon?, label? } × 5],   -- the 5 bottom-bar slots
--     header:  [{ key, icon? } …]              -- header icons, in order
--   }
--
-- `taskbar[].key` is a navigation destination: one of the core pages
-- (home · children · scanner · stats · settings), any module key from the
-- registry (`src/lib/modules.ts`) or `owner`. Everything that is NOT in the
-- taskbar is listed in the side menu under the 5 main slots. `header[].key`
-- is a header widget (`date` · `messages` · `notifications`) or
-- `link:<destination>` for a quick-link icon. The menu button is fixed.
--
-- Resolution (which module a given servant may actually see) stays in the
-- app: a slot pointing at a module hidden from the caller falls back to the
-- next default core page — see `src/lib/customization-context.tsx`.
--
-- RLS: every authenticated user READS (the shell needs it); only the OWNER
-- WRITES. Realtime so every open app re-lays its bars the moment the owner
-- saves. Idempotent — safe to re-run. Depends on 0019 (is_owner).
-- =====================================================================


create table if not exists public.app_settings (
  key         text primary key,
  value       jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  uuid references public.profiles(id),
  constraint app_settings_key_fmt check (key ~ '^[a-z][a-z0-9_:-]{1,60}$')
);

alter table public.app_settings enable row level security;

drop policy if exists app_settings_select on public.app_settings;
create policy app_settings_select on public.app_settings for select using (
  auth.role() = 'authenticated'
);
drop policy if exists app_settings_insert on public.app_settings;
create policy app_settings_insert on public.app_settings for insert with check (
  (select public.is_owner())
);
drop policy if exists app_settings_update on public.app_settings;
create policy app_settings_update on public.app_settings for update using (
  (select public.is_owner())
) with check (
  (select public.is_owner())
);
drop policy if exists app_settings_delete on public.app_settings;
create policy app_settings_delete on public.app_settings for delete using (
  (select public.is_owner())
);

-- keep updated_at honest
create or replace function public.touch_app_settings()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists trg_touch_app_settings on public.app_settings;
create trigger trg_touch_app_settings before update on public.app_settings
for each row execute function public.touch_app_settings();

-- realtime — bars re-lay instantly on every device
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'app_settings'
  ) then
    alter publication supabase_realtime add table public.app_settings;
  end if;
end $$;
alter table public.app_settings replica identity full;



-- #####################################################################
-- ##  0036_home_widgets_and_names.sql
-- #####################################################################

-- =====================================================================
-- 0036: HOME WIDGETS + CUSTOM NAMES (تخصيص التطبيق — الرئيسية والأسماء)
--
-- No new tables: this migration only DOCUMENTS the two new keys stored in
-- `app_settings` (created in 0035, owner-write / all-read / realtime) and
-- adds a validation trigger so the owner can never save a malformed layout.
--
--   key = 'widgets' → {
--     version: 1,
--     items: [{ key, size?, title? } …]      -- home-page widgets, in order
--   }
--   `items[].key`  — a widget from the registry (`src/lib/widgets.ts`)
--   `items[].size` — 'full' | 'half' (grid span on the home page)
--   `items[].title`— optional custom heading (≤ 30 chars)
--
--   key = 'names' → { "<destination key>": "<custom label>", … }
--   A single source of truth for the DISPLAY NAME of every destination
--   (core pages · modules · owner module). The name entered here — or in
--   the taskbar slot editor — is what the taskbar, the side menu, the
--   settings hub, the module headers and the page titles all show.
--
-- Resolution (which widget a given servant actually sees) stays in the
-- app: a widget bound to a module hidden from the caller is skipped — see
-- `src/lib/customization-context.tsx`. Idempotent — safe to re-run.
-- =====================================================================


create or replace function public.validate_app_settings()
returns trigger language plpgsql as $$
begin
  if jsonb_typeof(new.value) <> 'object' then
    raise exception 'app_settings.value must be a JSON object (key %)', new.key;
  end if;
  if new.key = 'names' then
    if exists (
      select 1 from jsonb_each(new.value) kv
       where jsonb_typeof(kv.value) <> 'string'
          or length(kv.value #>> '{}') = 0
          or length(kv.value #>> '{}') > 30
    ) then
      raise exception 'app_settings.names: every label must be a 1–30 character string';
    end if;
  end if;
  if new.key = 'widgets' then
    if jsonb_typeof(new.value -> 'items') <> 'array'
       or jsonb_array_length(new.value -> 'items') > 40 then
      raise exception 'app_settings.widgets: items must be an array (max 40)';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_validate_app_settings on public.app_settings;
create trigger trg_validate_app_settings before insert or update on public.app_settings
for each row execute function public.validate_app_settings();



-- #####################################################################
-- ##  0037_servant_enrollments_permissions.sql
-- #####################################################################

-- =====================================================================
-- 0037: SERVANTS ARCHITECTURE REDESIGN
--
--   profiles  ──renamed──▶  servant_enrollments  (تسجيلات الخدام)
--
-- The servant is now a PERSON first (same identity table as the children:
-- `persons`, national_id = the code / QR) and is then registered as a
-- *servant enrollment* bound to church → service → class — exactly the
-- same architecture as a child's `enrollments` row.
--
--   persons (الأشخاص)                servant_enrollments (تسجيلات الخدام)
--     id · national_id (code/QR)  ◀──  person_id
--     name · gender · birthdate        id = auth.users.id (login account)
--     phone · address · notes          user_id (= the code, login name)
--     image_url                        role · status · church/service/class
--                                      full_name · phone · photo_url (mirrors)
--
-- Signup flow (RPC `servant_signup`):
--   1. church / service / class (chosen or pre-filled from the invite link)
--   2. code (typed or scanned QR)        → persons.national_id
--   3. name · gender · phone · birthdate · address · notes
--      (same rules as adding a child)   → persons
--   4. password + confirmation           → auth.users
--   → person upserted by code, then a PENDING servant enrollment is created.
--
-- PERMISSIONS
--   permission_profiles (ملفات الصلاحيات) — made by the OWNER in the owner
--     module: a named set of permission keys (app-code registry).
--   permissions (الصلاحيات) — connects a servant enrollment to a permission
--     profile.  `my_permissions()` / `has_permission(key)` resolve them.
--
-- BACKWARD COMPATIBILITY
--   A `public.profiles` VIEW (security_invoker) over servant_enrollments
--   keeps every existing function / query working unchanged.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. RENAME profiles → servant_enrollments (idempotent)
-- ---------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
              where n.nspname = 'public' and c.relname = 'profiles' and c.relkind = 'r')
     and not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
              where n.nspname = 'public' and c.relname = 'servant_enrollments') then
    alter table public.profiles rename to servant_enrollments;
  end if;
end $$;

comment on table public.servant_enrollments is
  'تسجيلات الخدام — حساب الخادم (id = auth.users.id) مربوط بشخص في persons وبنطاق كنيسة → خدمة → فصل';

alter index if exists idx_profiles_church  rename to idx_servant_enrollments_church;
alter index if exists idx_profiles_status  rename to idx_servant_enrollments_status;
alter index if exists idx_profiles_service rename to idx_servant_enrollments_service;
alter index if exists idx_profiles_class   rename to idx_servant_enrollments_class;

do $$
begin
  if exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
              where c.relname = 'servant_enrollments' and t.tgname = 'trg_guard_profile') then
    alter trigger trg_guard_profile on public.servant_enrollments rename to trg_guard_servant_enrollment;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1b. COMPATIBILITY VIEW right away — the triggers / helpers that run
--     during the backfill below (guard_profile_update → my_role →
--     my_scope) still read `public.profiles`.
-- ---------------------------------------------------------------------
drop view if exists public.profiles;
create view public.profiles with (security_invoker = true) as
  select * from public.servant_enrollments;
grant select, insert, update, delete on public.profiles to authenticated;
grant select, insert, update, delete on public.profiles to service_role;

-- The guard trigger must also freeze person_id for a self-update by a non-manager
create or replace function public.guard_profile_update()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_role public.app_role;
begin
  -- servant_signup (security definer RPC) may attach the person / refresh
  -- the pending request — it flags itself through app.in_servant_signup.
  if current_setting('app.in_servant_signup', true) = '1' then
    new.updated_at := now();
    return new;
  end if;
  v_role := public.my_role();
  if auth.uid() = new.id and (v_role is null or v_role = 'class_servant') then
    new.role := old.role;
    new.status := old.status;
    new.church_id := old.church_id;
    new.service_id := old.service_id;
    new.class_id := old.class_id;
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    new.person_id := old.person_id;
  end if;
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 2. person_id — the servant IS a person
-- ---------------------------------------------------------------------
alter table public.servant_enrollments
  add column if not exists person_id uuid references public.persons(id) on delete set null;
create index if not exists idx_servant_enrollments_person on public.servant_enrollments(person_id);

comment on column public.servant_enrollments.person_id is 'الشخص (persons) — الخادم شخص أولاً، الكود = national_id';
comment on column public.servant_enrollments.user_id   is 'اسم الدخول = الكود (national_id) بعد التطبيع';

-- Backfill: every existing servant without a person gets one (code = his user_id
-- unless that code is already taken by someone else).
do $$
declare
  r record;
  v_nid text;
  v_pid uuid;
begin
  perform set_config('app.in_servant_signup', '1', true);   -- bypass the guard trigger
  for r in select * from public.servant_enrollments where person_id is null loop
    v_nid := r.user_id;
    if exists (select 1 from public.persons p where p.national_id = v_nid) then
      v_nid := 'S-' || upper(encode(gen_random_bytes(5), 'hex'));
    end if;
    insert into public.persons (national_id, name, phone, image_url, created_by, edited_by, created_at)
    values (v_nid, r.full_name, nullif(r.phone, ''), r.photo_url, r.id, r.id, r.created_at)
    returning id into v_pid;
    update public.servant_enrollments set person_id = v_pid where id = r.id;
  end loop;
  perform set_config('app.in_servant_signup', '0', true);
end $$;

-- Any servant enrollment inserted WITHOUT a person (e.g. the bootstrap owner
-- script 0002, or old code) gets one automatically. `servant_signup` sets
-- app.in_servant_signup because it creates the person itself.
create or replace function public.auto_person_for_servant()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_nid text;
  v_pid uuid;
begin
  if new.person_id is not null or current_setting('app.in_servant_signup', true) = '1' then
    return new;
  end if;
  v_nid := new.user_id;
  if exists (select 1 from public.persons p where p.national_id = v_nid) then
    v_nid := 'S-' || upper(encode(gen_random_bytes(5), 'hex'));
  end if;
  insert into public.persons (national_id, name, phone, image_url, created_by, edited_by)
  values (v_nid, new.full_name, nullif(new.phone, ''), new.photo_url, new.id, new.id)
  returning id into v_pid;
  update public.servant_enrollments set person_id = v_pid where id = new.id;
  return new;
end $$;
drop trigger if exists trg_auto_person_for_servant on public.servant_enrollments;
create trigger trg_auto_person_for_servant after insert on public.servant_enrollments
for each row execute function public.auto_person_for_servant();

-- ---------------------------------------------------------------------
-- 3. Keep the mirrored columns (full_name / phone / photo_url) in sync
--    with the person — both directions, loop-safe.
-- ---------------------------------------------------------------------
create or replace function public.sync_servant_to_person()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() > 1 or new.person_id is null then return new; end if;
  update public.persons p
     set name      = new.full_name,
         phone     = nullif(new.phone, ''),
         image_url = new.photo_url,
         edited_at = now(),
         edited_by = coalesce(auth.uid(), p.edited_by)
   where p.id = new.person_id
     and (p.name is distinct from new.full_name
       or p.phone is distinct from nullif(new.phone, '')
       or p.image_url is distinct from new.photo_url);
  return new;
end $$;

drop trigger if exists trg_sync_servant_to_person on public.servant_enrollments;
create trigger trg_sync_servant_to_person
after insert or update of full_name, phone, photo_url, person_id on public.servant_enrollments
for each row execute function public.sync_servant_to_person();

create or replace function public.sync_person_to_servant()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if pg_trigger_depth() > 1 then return new; end if;
  update public.servant_enrollments s
     set full_name = new.name,
         phone     = coalesce(new.phone, ''),
         photo_url = new.image_url,
         updated_at = now()
   where s.person_id = new.id
     and (s.full_name is distinct from new.name
       or s.phone is distinct from coalesce(new.phone, '')
       or s.photo_url is distinct from new.image_url);
  return new;
end $$;

drop trigger if exists trg_sync_person_to_servant on public.persons;
create trigger trg_sync_person_to_servant
after update of name, phone, image_url on public.persons
for each row execute function public.sync_person_to_servant();

-- ---------------------------------------------------------------------
-- 4. POLICIES — same semantics as 0019, new names
-- ---------------------------------------------------------------------
drop policy if exists profiles_select      on public.servant_enrollments;
drop policy if exists profiles_insert_self on public.servant_enrollments;
drop policy if exists profiles_update_self on public.servant_enrollments;
drop policy if exists profiles_update_mgmt on public.servant_enrollments;
drop policy if exists profiles_delete      on public.servant_enrollments;

drop policy if exists servant_enrollments_select on public.servant_enrollments;
create policy servant_enrollments_select on public.servant_enrollments for select using (
  id = auth.uid()
  or (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);
drop policy if exists servant_enrollments_insert_self on public.servant_enrollments;
create policy servant_enrollments_insert_self on public.servant_enrollments for insert with check (
  id = auth.uid() and status = 'pending'
);
drop policy if exists servant_enrollments_update_self on public.servant_enrollments;
create policy servant_enrollments_update_self on public.servant_enrollments for update using (id = auth.uid());
drop policy if exists servant_enrollments_update_mgmt on public.servant_enrollments;
create policy servant_enrollments_update_mgmt on public.servant_enrollments for update using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);
drop policy if exists servant_enrollments_delete on public.servant_enrollments;
create policy servant_enrollments_delete on public.servant_enrollments for delete using (
  (select public.is_owner())
  or ((select public.my_role()) = 'church_manager' and church_id = (select public.my_church()))
  or ((select public.my_role()) = 'service_manager' and (
       service_id = (select public.my_service())
       or ((select public.my_service()) is null and church_id = (select public.my_church()))
  ))
);

-- PERSONS: a servant sees / edits his own person row; managers see the
-- persons of the servant enrollments they manage (pending ones included).
drop policy if exists persons_select_self on public.persons;
create policy persons_select_self on public.persons for select using (
  id = (select s.person_id from public.servant_enrollments s where s.id = auth.uid())
);
drop policy if exists persons_update_self on public.persons;
create policy persons_update_self on public.persons for update using (
  id = (select s.person_id from public.servant_enrollments s where s.id = auth.uid())
);
drop policy if exists persons_select_servants on public.persons;
create policy persons_select_servants on public.persons for select using (
  exists (
    select 1 from public.servant_enrollments s
     where s.person_id = persons.id
       and (
         (select public.is_owner())
         or ((select public.my_role()) = 'church_manager' and s.church_id = (select public.my_church()))
         or ((select public.my_role()) = 'service_manager' and (
              s.service_id = (select public.my_service())
              or ((select public.my_service()) is null and s.church_id = (select public.my_church()))
         ))
       )
  )
);
drop policy if exists persons_update_servants on public.persons;
create policy persons_update_servants on public.persons for update using (
  exists (
    select 1 from public.servant_enrollments s
     where s.person_id = persons.id
       and (
         (select public.is_owner())
         or ((select public.my_role()) = 'church_manager' and s.church_id = (select public.my_church()))
         or ((select public.my_role()) = 'service_manager' and (
              s.service_id = (select public.my_service())
              or ((select public.my_service()) is null and s.church_id = (select public.my_church()))
         ))
       )
  )
);

-- ---------------------------------------------------------------------
-- 4b. Deleting a servant must never be blocked by his audit trail.
--     Every nullable `created_by / edited_by / recorded_by …` column that
--     references servant_enrollments with the default NO ACTION becomes
--     ON DELETE SET NULL (the row stays, the author becomes «unknown»).
-- ---------------------------------------------------------------------
do $$
declare r record;
begin
  for r in
    select c.conname, c.conrelid::regclass as tbl,
           (select string_agg(quote_ident(a.attname), ', ' order by a.attnum)
              from pg_attribute a where a.attrelid = c.conrelid and a.attnum = any (c.conkey)) as cols,
           (select bool_and(not a.attnotnull)
              from pg_attribute a where a.attrelid = c.conrelid and a.attnum = any (c.conkey)) as nullable
      from pg_constraint c
     where c.contype = 'f'
       and c.confrelid = 'public.servant_enrollments'::regclass
       and c.confdeltype = 'a'
  loop
    if r.nullable then
      execute format('alter table %s drop constraint %I', r.tbl, r.conname);
      execute format('alter table %s add constraint %I foreign key (%s) references public.servant_enrollments(id) on delete set null',
                     r.tbl, r.conname, r.cols);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 5. COMPATIBILITY VIEW  public.profiles  → servant_enrollments
--    security_invoker ⇒ the caller's RLS on the base table applies.
--    Simple single-table view ⇒ insert / update / delete pass through.
-- ---------------------------------------------------------------------
drop view if exists public.profiles;   -- recreate: person_id column added above
create view public.profiles with (security_invoker = true) as
  select * from public.servant_enrollments;
comment on view public.profiles is 'توافق قديم — اسم الجدول أصبح servant_enrollments (تسجيلات الخدام)';
grant select, insert, update, delete on public.profiles to authenticated;
grant select, insert, update, delete on public.profiles to service_role;

-- ---------------------------------------------------------------------
-- 6. SIGNUP RPCs
-- ---------------------------------------------------------------------

-- Login name derived from the code (must be a valid e-mail local part)
create or replace function public.code_to_user_id(p_code text)
returns text language sql immutable as $$
  select lower(regexp_replace(trim(p_code), '[^a-zA-Z0-9._-]', '-', 'g'))
$$;

-- Step 2 of the signup: is this code already a known person? Returns the
-- (limited) person data to pre-fill the form. Same exposure level as the
-- child portal (`child_portal_profile`): whoever holds the code / card.
create or replace function public.signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else (
      select jsonb_build_object(
        'name', p.name, 'gender', p.gender, 'birthdate', p.birthdate,
        'phone', p.phone, 'address', p.address, 'image_url', p.image_url,
        'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
      from public.persons p where p.national_id = trim(p_code) limit 1)
  end
$$;
grant execute on function public.signup_lookup_code(text) to anon, authenticated;

-- The signup itself (called right after auth.signUp, so auth.uid() is set):
--   1. person upserted by code (fill blanks only — never overwrite)
--   2. PENDING servant enrollment created for this account
create or replace function public.servant_signup(
  p_code text,
  p_full_name text,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null,
  p_image_url text default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_code text := nullif(trim(p_code), '');
  v_user_id text;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_full_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_phone is null then raise exception 'phone_required' using errcode = '22023'; end if;

  -- scope chain must be consistent (all optional — the approver may set it)
  if p_service is not null and (p_church is null
      or not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church)) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and (p_service is null
      or not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;

  v_user_id := public.code_to_user_id(v_code);
  if exists (select 1 from public.servant_enrollments s where s.user_id = v_user_id and s.id <> v_uid) then
    raise exception 'code_taken' using errcode = '23505';
  end if;

  -- 0) the servant enrollment row must exist BEFORE the person because
  --    persons.created_by references servant_enrollments(id). Insert it as a
  --    placeholder (pending), the person is attached right after.
  perform set_config('app.in_servant_signup', '1', true);
  insert into public.servant_enrollments (id, full_name, user_id, phone, role, status,
                                          church_id, service_id, class_id)
  values (v_uid, trim(p_full_name), v_user_id, v_phone, 'class_servant', 'pending',
          p_church, p_service, p_class)
  on conflict (id) do nothing;
  if not exists (select 1 from public.servant_enrollments s where s.id = v_uid and s.status = 'pending') then
    raise exception 'already_registered' using errcode = '23505';
  end if;

  -- 1) the person
  select * into v_person from public.persons where national_id = v_code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, trim(p_full_name), p_gender, p_birthdate, v_phone,
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            p_image_url, v_uid, v_uid)
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, v_phone),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = v_uid, edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  -- 2) attach the person to the (pending) servant enrollment. Re-running for
  --    the same account while still pending simply refreshes the request.
  update public.servant_enrollments set
    person_id  = v_person.id,
    full_name  = v_person.name,
    user_id    = v_user_id,
    phone      = coalesce(v_person.phone, v_phone),
    church_id  = p_church,
    service_id = p_service,
    class_id   = p_class,
    photo_url  = v_person.image_url,
    updated_at = now()
  where id = v_uid and status = 'pending';

  perform set_config('app.in_servant_signup', '0', true);
  return jsonb_build_object('person_id', v_person.id, 'person_created', v_created,
                            'national_id', v_person.national_id, 'user_id', v_user_id);
end $$;
grant execute on function public.servant_signup(text, text, text, date, text, text, text, uuid, uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 7. PERMISSION PROFILES (ملفات الصلاحيات) — owner-made named key sets
-- ---------------------------------------------------------------------
create table if not exists public.permission_profiles (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  description text,
  permissions text[] not null default '{}',   -- keys from src/lib/permissions.ts
  color       text not null default '#1e3a8a',
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint permission_profiles_name_len check (length(trim(name)) between 1 and 80)
);
create unique index if not exists uq_permission_profiles_name on public.permission_profiles(lower(name));
comment on table public.permission_profiles is 'ملفات الصلاحيات — مجموعة مفاتيح صلاحيات باسم، يصنعها المالك من وحدة المالك';

-- ---------------------------------------------------------------------
-- 8. PERMISSIONS (الصلاحيات) — servant enrollment ↔ permission profile
-- ---------------------------------------------------------------------
create table if not exists public.permissions (
  id                    uuid primary key default gen_random_uuid(),
  servant_id            uuid not null references public.servant_enrollments(id) on delete cascade,
  permission_profile_id uuid not null references public.permission_profiles(id) on delete cascade,
  granted_by            uuid references public.servant_enrollments(id) on delete set null,
  created_at            timestamptz not null default now(),
  unique (servant_id, permission_profile_id)
);
create index if not exists idx_permissions_servant on public.permissions(servant_id);
create index if not exists idx_permissions_profile on public.permissions(permission_profile_id);
comment on table public.permissions is 'الصلاحيات — ربط تسجيل الخادم بملف صلاحيات';

alter table public.permission_profiles enable row level security;
alter table public.permissions enable row level security;

-- helpers --------------------------------------------------------------
-- Can the caller MANAGE (assign / revoke) permissions of this servant?
-- owner: anyone; church / service manager: servants inside his scope,
-- never himself, never an owner.
create or replace function public.can_manage_servant(p_servant uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when p_servant = auth.uid() then false
      when s.role = 'owner' then true
      when s.role = 'church_manager' then t.role <> 'owner' and t.church_id = s.church_id
      when s.role = 'service_manager' then t.role in ('class_servant')
           and (t.service_id = s.service_id or (s.service_id is null and t.church_id = s.church_id))
      else false
    end
    from public.my_scope() s, public.servant_enrollments t
    where t.id = p_servant
  ), false)
$$;

-- All permission keys of the caller. Owner ⇒ {'*'} (everything).
create or replace function public.my_permissions()
returns text[] language sql stable security definer set search_path = public as $$
  select case
    when (select role from public.my_scope()) = 'owner' then array['*']
    when (select role from public.my_scope()) is null then '{}'::text[]
    else coalesce((
      select array_agg(distinct k)
        from public.permissions p
        join public.permission_profiles pp on pp.id = p.permission_profile_id
        cross join unnest(pp.permissions) k
       where p.servant_id = auth.uid()), '{}'::text[])
  end
$$;

create or replace function public.has_permission(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select role from public.my_scope()) = 'owner', false)
      or p_key = any (public.my_permissions())
$$;
grant execute on function public.can_manage_servant(uuid) to authenticated;
grant execute on function public.my_permissions() to authenticated;
grant execute on function public.has_permission(text) to authenticated;

-- policies -------------------------------------------------------------
drop policy if exists permission_profiles_select on public.permission_profiles;
create policy permission_profiles_select on public.permission_profiles for select using (
  (select public.my_role()) is not null
);
drop policy if exists permission_profiles_insert on public.permission_profiles;
create policy permission_profiles_insert on public.permission_profiles for insert with check ((select public.is_owner()));
drop policy if exists permission_profiles_update on public.permission_profiles;
create policy permission_profiles_update on public.permission_profiles for update using ((select public.is_owner()));
drop policy if exists permission_profiles_delete on public.permission_profiles;
create policy permission_profiles_delete on public.permission_profiles for delete using ((select public.is_owner()));

drop policy if exists permissions_select on public.permissions;
create policy permissions_select on public.permissions for select using (
  servant_id = auth.uid()
  or (select public.is_owner())
  or public.can_manage_servant(servant_id)
);
drop policy if exists permissions_insert on public.permissions;
create policy permissions_insert on public.permissions for insert with check (
  public.can_manage_servant(servant_id)
);
drop policy if exists permissions_delete on public.permissions;
create policy permissions_delete on public.permissions for delete using (
  public.can_manage_servant(servant_id)
);

create or replace function public.touch_permission_profile()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.edited_at := now();
  new.edited_by := coalesce(auth.uid(), new.edited_by);
  if tg_op = 'INSERT' then new.created_by := coalesce(new.created_by, auth.uid()); end if;
  return new;
end $$;
drop trigger if exists trg_touch_permission_profile on public.permission_profiles;
create trigger trg_touch_permission_profile before insert or update on public.permission_profiles
for each row execute function public.touch_permission_profile();

create or replace function public.stamp_permission_grant()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.granted_by := coalesce(new.granted_by, auth.uid());
  return new;
end $$;
drop trigger if exists trg_stamp_permission_grant on public.permissions;
create trigger trg_stamp_permission_grant before insert on public.permissions
for each row execute function public.stamp_permission_grant();

-- Managers list: which permission profiles does each visible servant hold?
create or replace function public.servant_permission_map()
returns table (servant_id uuid, permission_profile_ids uuid[])
language sql stable security invoker set search_path = public as $$
  select p.servant_id, array_agg(p.permission_profile_id order by p.created_at)
    from public.permissions p
   group by p.servant_id
$$;
grant execute on function public.servant_permission_map() to authenticated;

-- ---------------------------------------------------------------------
-- 9. REALTIME
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'permission_profiles') then
    alter publication supabase_realtime add table public.permission_profiles;
  end if;
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'permissions') then
    alter publication supabase_realtime add table public.permissions;
  end if;
end $$;
alter table public.permission_profiles replica identity full;
alter table public.permissions replica identity full;



-- #####################################################################
-- ##  0038_exam_results.sql
-- #####################################################################

-- =====================================================================
-- 0038: EXAM RESULTS MODULE — نتائج الامتحانات
--
-- Servants create EXAMS (paper / oral exams — not the online MCQ exams of
-- migration 0027), define SUBJECTS with full / pass degrees, pick a
-- configurable GRADING SYSTEM, then enter every student's score per subject
-- (one by one, in bulk, or from Excel). Percentages, grades, totals, pass /
-- fail and rank are ALWAYS computed by the database — never typed.
--
--   grading_systems  — name · church (null = every church, owner-made)
--   grading_grades   — Grade 1..N: name · min % · max % · color · description
--   result_exams     — name · date · scope church → service? → class? ·
--                      academic year · status draft | open | completed |
--                      archived · grading system · grade_overall /
--                      grade_subject flags · pass rule · absent_as_zero ·
--                      min_required_subjects · locked (+ by / at) ·
--                      published_at (child portal) · audit
--   result_subjects  — per exam: name · code · full · pass · weight ·
--                      is_bonus (adds to the total, not to the full) · order
--   exam_results     — ONE row per (exam, subject, enrollment): score ·
--                      status draft | completed | absent | excused · note ·
--                      COMPUTED percent · grade_id · passed · audit
--
-- Computation lives in ONE place:
--   trg exam_results  → validates (score ≤ full, not locked, enrollment in
--                       scope) and fills percent / grade / passed.
--   result_summary_core(exam, enrollment?) → per-student totals: total /
--                       full / percent (weighted when every subject has a
--                       weight) / overall grade / pass-fail / status
--                       not_entered | incomplete | draft | absent | passed |
--                       failed. result_exam_summary adds competition
--                       ranking (1 2 2 4) by percent and by total score.
--   Changing a subject's degrees or the exam's grading re-computes rows.
--
-- Permissions (existing RBAC — module grant + role + permission keys of
-- migration 0037). result_can(key):
--   module_visible('results') AND (role in owner / church_manager /
--   service_manager  OR  key in (results.view, results.stats)  OR
--   has_permission(key))  — i.e. managers can do everything in their scope,
--   class servants view & see statistics by default and need a permission
--   profile for enter / edit / import / export / manage_* / lock.
--   Locked exam → only results.lock holders may write results / subjects.
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / scope_* /
-- enrollment_visible), 0021 (child portal), 0024 (module_visible),
-- 0037 (has_permission). NO module grant is seeded — the owner enables it
-- per scope in وحدة المالك → صلاحيات الوحدات.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. PERMISSION HELPER
-- ---------------------------------------------------------------------
create or replace function public.result_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('results')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or p_key in ('results.view', 'results.stats')
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.result_can(text) to authenticated;

create or replace function public.result_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',           public.result_can('results.view'),
    'enter',          public.result_can('results.enter'),
    'edit',           public.result_can('results.edit'),
    'import',         public.result_can('results.import'),
    'export',         public.result_can('results.export'),
    'manage_exams',   public.result_can('results.manage_exams'),
    'manage_subjects',public.result_can('results.manage_subjects'),
    'manage_grading', public.result_can('results.manage_grading'),
    'lock',           public.result_can('results.lock'),
    'stats',          public.result_can('results.stats')
  )
$$;
grant execute on function public.result_permissions() to authenticated;

-- ---------------------------------------------------------------------
-- 1. GRADING SYSTEMS + GRADES
-- ---------------------------------------------------------------------
create table if not exists public.grading_systems (
  id           uuid primary key default gen_random_uuid(),
  church_id    uuid references public.churches(id) on delete cascade,   -- null = every church (owner)
  name         text not null,
  description  text,
  is_default   boolean not null default false,
  created_at   timestamptz not null default now(),
  created_by   uuid references public.servant_enrollments(id) on delete set null,
  edited_at    timestamptz not null default now(),
  edited_by    uuid references public.servant_enrollments(id) on delete set null,
  constraint grading_systems_name_not_blank check (length(trim(name)) > 0)
);
comment on table public.grading_systems is 'أنظمة التقدير — نظام قابل للتخصيص من درجات ونسب (Grade 1..N)';
create index if not exists idx_grading_systems_church on public.grading_systems(church_id);

create table if not exists public.grading_grades (
  id                 uuid primary key default gen_random_uuid(),
  grading_system_id  uuid not null references public.grading_systems(id) on delete cascade,
  name               text not null,
  min_percent        numeric(6,2) not null check (min_percent >= 0 and min_percent <= 100),
  max_percent        numeric(6,2) not null check (max_percent >= 0 and max_percent <= 100),
  description        text,
  color              text,                                  -- hex
  is_pass            boolean not null default true,         -- informational
  sort_order         integer not null default 0,
  constraint grading_grades_range check (min_percent <= max_percent),
  constraint grading_grades_name_not_blank check (length(trim(name)) > 0)
);
comment on table public.grading_grades is 'درجات التقدير — الاسم · من ٪ · إلى ٪ · لون · وصف';
create index if not exists idx_grading_grades_system on public.grading_grades(grading_system_id, min_percent desc);

drop trigger if exists trg_grading_systems_touch on public.grading_systems;
create trigger trg_grading_systems_touch before update on public.grading_systems
for each row execute function public.touch_edited();

create or replace function public.grading_system_before_insert()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.name := trim(new.name);
  new.created_by := coalesce(new.created_by, auth.uid());
  new.edited_by  := coalesce(new.edited_by, auth.uid());
  return new;
end $$;
drop trigger if exists trg_grading_system_insert on public.grading_systems;
create trigger trg_grading_system_insert before insert on public.grading_systems
for each row execute function public.grading_system_before_insert();

-- The grade a percentage falls into (highest matching band). null = none.
create or replace function public.grade_for_percent(p_system uuid, p_pct numeric)
returns uuid language sql stable security definer set search_path = public as $$
  select g.id
    from public.grading_grades g
   where p_system is not null and p_pct is not null
     and g.grading_system_id = p_system
     and round(p_pct, 2) >= g.min_percent and round(p_pct, 2) <= g.max_percent
   order by g.min_percent desc, g.sort_order
   limit 1
$$;
grant execute on function public.grade_for_percent(uuid, numeric) to authenticated, anon;

-- ---------------------------------------------------------------------
-- 2. EXAMS
-- ---------------------------------------------------------------------
create table if not exists public.result_exams (
  id                     uuid primary key default gen_random_uuid(),
  church_id              uuid not null references public.churches(id) on delete cascade,
  service_id             uuid references public.services(id) on delete cascade,   -- null = all services
  class_id               uuid references public.classes(id)  on delete cascade,   -- null = all classes
  name                   text not null,
  exam_date              date,
  academic_year          text,
  description            text,
  status                 text not null default 'draft' check (status in ('draft', 'open', 'completed', 'archived')),
  grading_system_id      uuid references public.grading_systems(id) on delete set null,
  grade_overall          boolean not null default true,    -- option A: grade from the total percentage
  grade_subject          boolean not null default true,    -- option B: a grade per subject
  pass_rule              text not null default 'overall' check (pass_rule in ('overall', 'subjects', 'both')),
  pass_percent           numeric(6,2) not null default 50 check (pass_percent >= 0 and pass_percent <= 100),
  absent_as_zero         boolean not null default false,
  min_required_subjects  integer check (min_required_subjects is null or min_required_subjects >= 1),
  locked                 boolean not null default false,
  locked_at              timestamptz,
  locked_by              uuid references public.servant_enrollments(id) on delete set null,
  published_at           timestamptz,                       -- null = hidden from the child portal
  created_at             timestamptz not null default now(),
  created_by             uuid references public.servant_enrollments(id) on delete set null,
  edited_at              timestamptz not null default now(),
  edited_by              uuid references public.servant_enrollments(id) on delete set null,
  constraint result_exams_name_not_blank check (length(trim(name)) > 0),
  constraint result_exams_scope_chain    check (not (class_id is not null and service_id is null))
);
comment on table public.result_exams is 'امتحانات النتائج — اسم · تاريخ · نطاق · عام دراسي · حالة · نظام تقدير · قواعد النجاح · قفل';
create index if not exists idx_result_exams_church  on public.result_exams(church_id, exam_date desc);
create index if not exists idx_result_exams_service on public.result_exams(service_id);
create index if not exists idx_result_exams_class   on public.result_exams(class_id);
create index if not exists idx_result_exams_status  on public.result_exams(status);

drop trigger if exists trg_result_exams_touch on public.result_exams;
create trigger trg_result_exams_touch before update on public.result_exams
for each row execute function public.touch_edited();

create or replace function public.result_exam_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.name := trim(new.name);
  if new.service_id is not null and not exists (
    select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id) then
    raise exception 'service_not_in_church' using errcode = 'P0001';
  end if;
  if new.class_id is not null and not exists (
    select 1 from public.classes c where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id) then
    raise exception 'class_not_in_service' using errcode = 'P0001';
  end if;
  if new.grading_system_id is not null and not exists (
    select 1 from public.grading_systems g where g.id = new.grading_system_id and (g.church_id is null or g.church_id = new.church_id)) then
    raise exception 'grading_system_out_of_scope' using errcode = 'P0001';
  end if;
  if tg_op = 'INSERT' then
    new.created_by := coalesce(new.created_by, auth.uid());
    new.edited_by  := coalesce(new.edited_by, auth.uid());
  else
    -- lock / unlock only through result_exam_set_lock (needs results.lock)
    if new.locked <> old.locked and coalesce(current_setting('results.lock_rpc', true), '') <> '1' then
      raise exception 'use_lock_rpc' using errcode = 'P0001';
    end if;
    if old.locked and new.locked and coalesce(current_setting('results.lock_rpc', true), '') <> '1'
       and not public.result_can('results.lock')
       and (new.grading_system_id is distinct from old.grading_system_id
            or new.grade_overall <> old.grade_overall or new.grade_subject <> old.grade_subject
            or new.pass_rule <> old.pass_rule or new.pass_percent <> old.pass_percent
            or new.absent_as_zero <> old.absent_as_zero
            or new.min_required_subjects is distinct from old.min_required_subjects) then
      raise exception 'results_locked' using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_result_exam_write on public.result_exams;
create trigger trg_result_exam_write before insert or update on public.result_exams
for each row execute function public.result_exam_before_write();

-- ---------------------------------------------------------------------
-- 3. SUBJECTS
-- ---------------------------------------------------------------------
create table if not exists public.result_subjects (
  id           uuid primary key default gen_random_uuid(),
  exam_id      uuid not null references public.result_exams(id) on delete cascade,
  name         text not null,
  code         text,
  full_degree  numeric(8,2) not null check (full_degree > 0),
  pass_degree  numeric(8,2) not null default 0 check (pass_degree >= 0),
  weight       numeric(8,2) check (weight is null or weight >= 0),     -- null = plain sum
  is_bonus     boolean not null default false,                         -- extra credit: adds to the total, not to the full
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  edited_at    timestamptz not null default now(),
  constraint result_subjects_name_not_blank check (length(trim(name)) > 0),
  constraint result_subjects_pass_le_full check (pass_degree <= full_degree)
);
comment on table public.result_subjects is 'مواد الامتحان — الاسم · الكود · الدرجة الكاملة · درجة النجاح · الوزن · إضافي · الترتيب';
create index if not exists idx_result_subjects_exam on public.result_subjects(exam_id, sort_order);

create or replace function public.result_subject_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
declare x public.result_exams;
begin
  select * into x from public.result_exams where id = new.exam_id;
  if x.id is null then raise exception 'exam_not_found' using errcode = 'P0001'; end if;
  if x.locked and not public.result_can('results.lock') then
    raise exception 'results_locked' using errcode = 'P0001';
  end if;
  new.name := trim(new.name);
  new.code := nullif(trim(coalesce(new.code, '')), '');
  new.edited_at := now();
  return new;
end $$;
drop trigger if exists trg_result_subject_write on public.result_subjects;
create trigger trg_result_subject_write before insert or update on public.result_subjects
for each row execute function public.result_subject_before_write();

create or replace function public.result_subject_before_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select locked from public.result_exams where id = old.exam_id) and not public.result_can('results.lock') then
    raise exception 'results_locked' using errcode = 'P0001';
  end if;
  return old;
end $$;
drop trigger if exists trg_result_subject_delete on public.result_subjects;
create trigger trg_result_subject_delete before delete on public.result_subjects
for each row execute function public.result_subject_before_delete();

-- ---------------------------------------------------------------------
-- 4. RESULTS (one row per exam × subject × enrollment)
-- ---------------------------------------------------------------------
create table if not exists public.exam_results (
  id             uuid primary key default gen_random_uuid(),
  exam_id        uuid not null references public.result_exams(id)    on delete cascade,
  subject_id     uuid not null references public.result_subjects(id) on delete cascade,
  enrollment_id  uuid not null references public.enrollments(id)     on delete cascade,
  person_id      uuid not null references public.persons(id)         on delete cascade,
  -- denormalized scope of the enrollment (cheap RLS + realtime filters)
  church_id      uuid not null references public.churches(id) on delete cascade,
  service_id     uuid not null references public.services(id) on delete cascade,
  class_id       uuid not null references public.classes(id)  on delete cascade,
  score          numeric(8,2),                                  -- null when absent / excused
  status         text not null default 'completed' check (status in ('draft', 'completed', 'absent', 'excused')),
  note           text,
  -- COMPUTED by the trigger — never written by the app
  percent        numeric(6,2),
  grade_id       uuid references public.grading_grades(id) on delete set null,
  passed         boolean,
  created_at     timestamptz not null default now(),
  created_by     uuid references public.servant_enrollments(id) on delete set null,
  edited_at      timestamptz not null default now(),
  edited_by      uuid references public.servant_enrollments(id) on delete set null,
  constraint exam_results_unique unique (exam_id, subject_id, enrollment_id)
);
comment on table public.exam_results is 'نتائج الامتحانات — لكل (امتحان · مادة · تسجيل): الدرجة · الحالة · النسبة والتقدير والنجاح محسوبة تلقائياً';
create index if not exists idx_exam_results_exam       on public.exam_results(exam_id, enrollment_id);
create index if not exists idx_exam_results_subject    on public.exam_results(subject_id);
create index if not exists idx_exam_results_enrollment on public.exam_results(enrollment_id);
create index if not exists idx_exam_results_person     on public.exam_results(person_id);
create index if not exists idx_exam_results_church     on public.exam_results(church_id);
create index if not exists idx_exam_results_service    on public.exam_results(service_id);
create index if not exists idx_exam_results_class      on public.exam_results(class_id);

create or replace function public.exam_result_before_write()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  x public.result_exams;
  s public.result_subjects;
  e public.enrollments;
  recalc boolean := coalesce(current_setting('results.recalc', true), '') = '1';
begin
  select * into x from public.result_exams where id = new.exam_id;
  if x.id is null then raise exception 'exam_not_found' using errcode = 'P0001'; end if;
  select * into s from public.result_subjects where id = new.subject_id and exam_id = new.exam_id;
  if s.id is null then raise exception 'subject_not_in_exam' using errcode = 'P0001'; end if;
  select * into e from public.enrollments where id = new.enrollment_id;
  if e.id is null then raise exception 'enrollment_not_found' using errcode = 'P0001'; end if;
  if not (e.church_id = x.church_id
          and (x.service_id is null or e.service_id = x.service_id)
          and (x.class_id   is null or e.class_id   = x.class_id)) then
    raise exception 'enrollment_out_of_scope' using errcode = 'P0001';
  end if;
  if not recalc then
    if x.locked and not public.result_can('results.lock') then
      raise exception 'results_locked' using errcode = 'P0001';
    end if;
    if x.status = 'archived' then
      raise exception 'exam_archived' using errcode = 'P0001';
    end if;
  end if;

  new.person_id  := e.person_id;
  new.church_id  := e.church_id;
  new.service_id := e.service_id;
  new.class_id   := e.class_id;
  new.note       := nullif(trim(coalesce(new.note, '')), '');

  if new.status in ('absent', 'excused') then
    new.score := null;
    if x.absent_as_zero then
      new.percent := 0; new.passed := (s.pass_degree <= 0);
    else
      new.percent := null; new.passed := null;
    end if;
  else
    if new.score is null then raise exception 'score_required' using errcode = 'P0001'; end if;
    if new.score < 0 then raise exception 'score_negative' using errcode = 'P0001'; end if;
    if new.score > s.full_degree then raise exception 'score_over_full' using errcode = 'P0001'; end if;
    new.percent := round(new.score / s.full_degree * 100, 2);
    new.passed  := new.score >= s.pass_degree;
  end if;
  new.grade_id := case when x.grade_subject and new.percent is not null
                       then public.grade_for_percent(x.grading_system_id, new.percent) end;

  if tg_op = 'INSERT' then
    new.created_at := now();
    new.created_by := coalesce(new.created_by, auth.uid());
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
  end if;
  if not recalc then
    new.edited_at := now();
    new.edited_by := coalesce(auth.uid(), new.edited_by);
  else
    new.edited_at := old.edited_at; new.edited_by := old.edited_by;
  end if;
  return new;
end $$;
drop trigger if exists trg_exam_result_write on public.exam_results;
create trigger trg_exam_result_write before insert or update on public.exam_results
for each row execute function public.exam_result_before_write();

create or replace function public.exam_result_before_delete()
returns trigger language plpgsql security definer set search_path = public as $$
declare x public.result_exams;
begin
  select * into x from public.result_exams where id = old.exam_id;
  if x.locked and not public.result_can('results.lock') then
    raise exception 'results_locked' using errcode = 'P0001';
  end if;
  return old;
end $$;
drop trigger if exists trg_exam_result_delete on public.exam_results;
create trigger trg_exam_result_delete before delete on public.exam_results
for each row execute function public.exam_result_before_delete();

-- Re-compute every stored row of an exam (grading / degrees changed)
create or replace function public.result_recalc(p_exam uuid)
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  perform set_config('results.recalc', '1', true);
  update public.exam_results set score = score where exam_id = p_exam;
  get diagnostics n = row_count;
  perform set_config('results.recalc', '', true);
  return n;
end $$;
revoke all on function public.result_recalc(uuid) from public, anon, authenticated;

create or replace function public.result_subject_after_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.full_degree <> old.full_degree or new.pass_degree <> old.pass_degree then
    perform set_config('results.recalc', '1', true);
    update public.exam_results set score = least(score, new.full_degree) where subject_id = new.id;
    perform set_config('results.recalc', '', true);
  end if;
  return null;
end $$;
drop trigger if exists trg_result_subject_recalc on public.result_subjects;
create trigger trg_result_subject_recalc after update on public.result_subjects
for each row execute function public.result_subject_after_change();

create or replace function public.result_exam_after_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.grading_system_id is distinct from old.grading_system_id
     or new.grade_subject <> old.grade_subject or new.absent_as_zero <> old.absent_as_zero then
    perform public.result_recalc(new.id);
  end if;
  return null;
end $$;
drop trigger if exists trg_result_exam_recalc on public.result_exams;
create trigger trg_result_exam_recalc after update on public.result_exams
for each row execute function public.result_exam_after_change();

-- grades edited → recompute exams using that system
create or replace function public.grading_grade_after_change()
returns trigger language plpgsql security definer set search_path = public as $$
declare sid uuid := coalesce(new.grading_system_id, old.grading_system_id); x uuid;
begin
  for x in select id from public.result_exams where grading_system_id = sid loop
    perform public.result_recalc(x);
  end loop;
  return null;
end $$;
drop trigger if exists trg_grading_grade_recalc on public.grading_grades;
create trigger trg_grading_grade_recalc after insert or update or delete on public.grading_grades
for each row execute function public.grading_grade_after_change();

-- ---------------------------------------------------------------------
-- 5. RLS
-- ---------------------------------------------------------------------
alter table public.grading_systems enable row level security;
alter table public.grading_grades  enable row level security;
alter table public.result_exams    enable row level security;
alter table public.result_subjects enable row level security;
alter table public.exam_results    enable row level security;

-- grading systems: read = module + (global or my church); write = manage_grading
drop policy if exists grading_systems_select on public.grading_systems;
create policy grading_systems_select on public.grading_systems for select using (
  (select public.result_can('results.view'))
  and (church_id is null or (select public.scope_overlaps(church_id, null, null)))
);
drop policy if exists grading_systems_write on public.grading_systems;
create policy grading_systems_write on public.grading_systems for all using (
  (select public.result_can('results.manage_grading'))
  and (case when church_id is null then (select public.is_owner()) else (select public.scope_contains(church_id, null, null)) end)
) with check (
  (select public.result_can('results.manage_grading'))
  and (case when church_id is null then (select public.is_owner()) else (select public.scope_contains(church_id, null, null)) end)
);

drop policy if exists grading_grades_select on public.grading_grades;
create policy grading_grades_select on public.grading_grades for select using (
  exists (select 1 from public.grading_systems g where g.id = grading_system_id)
);
drop policy if exists grading_grades_write on public.grading_grades;
create policy grading_grades_write on public.grading_grades for all using (
  (select public.result_can('results.manage_grading'))
  and exists (select 1 from public.grading_systems g where g.id = grading_system_id
              and (case when g.church_id is null then (select public.is_owner()) else (select public.scope_contains(g.church_id, null, null)) end))
) with check (
  (select public.result_can('results.manage_grading'))
  and exists (select 1 from public.grading_systems g where g.id = grading_system_id
              and (case when g.church_id is null then (select public.is_owner()) else (select public.scope_contains(g.church_id, null, null)) end))
);

-- exams
drop policy if exists result_exams_select on public.result_exams;
create policy result_exams_select on public.result_exams for select using (
  (select public.result_can('results.view'))
  and (select public.scope_overlaps(church_id, service_id, class_id))
);
drop policy if exists result_exams_insert on public.result_exams;
create policy result_exams_insert on public.result_exams for insert with check (
  (select public.result_can('results.manage_exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists result_exams_update on public.result_exams;
create policy result_exams_update on public.result_exams for update using (
  (select public.result_can('results.manage_exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
) with check (
  (select public.result_can('results.manage_exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
);
drop policy if exists result_exams_delete on public.result_exams;
create policy result_exams_delete on public.result_exams for delete using (
  (select public.result_can('results.manage_exams'))
  and (select public.scope_contains(church_id, service_id, class_id))
  and not locked
);

-- subjects: visible with the exam; write = manage_subjects on an exam I contain
drop policy if exists result_subjects_select on public.result_subjects;
create policy result_subjects_select on public.result_subjects for select using (
  exists (select 1 from public.result_exams x where x.id = exam_id)
);
drop policy if exists result_subjects_write on public.result_subjects;
create policy result_subjects_write on public.result_subjects for all using (
  (select public.result_can('results.manage_subjects'))
  and exists (select 1 from public.result_exams x where x.id = exam_id
              and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
) with check (
  (select public.result_can('results.manage_subjects'))
  and exists (select 1 from public.result_exams x where x.id = exam_id
              and (select public.scope_contains(x.church_id, x.service_id, x.class_id)))
);

-- results: rows of enrollments I can see; enter = insert; edit = update /
-- delete (a plain "enter" holder may still update his DRAFT rows)
drop policy if exists exam_results_select on public.exam_results;
create policy exam_results_select on public.exam_results for select using (
  (select public.result_can('results.view'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists exam_results_insert on public.exam_results;
create policy exam_results_insert on public.exam_results for insert with check (
  (select public.result_can('results.enter'))
  and exists (select 1 from public.enrollments e where e.id = enrollment_id)   -- RLS of enrollments = my scope
);
drop policy if exists exam_results_update on public.exam_results;
create policy exam_results_update on public.exam_results for update using (
  ((select public.result_can('results.edit')) or ((select public.result_can('results.enter')) and status = 'draft'))
  and exists (select 1 from public.enrollments e where e.id = enrollment_id)
) with check (
  ((select public.result_can('results.edit')) or (select public.result_can('results.enter')))
  and exists (select 1 from public.enrollments e where e.id = enrollment_id)
);
drop policy if exists exam_results_delete on public.exam_results;
create policy exam_results_delete on public.exam_results for delete using (
  (select public.result_can('results.edit'))
  and exists (select 1 from public.enrollments e where e.id = enrollment_id)
);

-- ---------------------------------------------------------------------
-- 6. SUMMARY — per-student computed totals (the single source of truth)
-- ---------------------------------------------------------------------
create or replace function public.result_summary_core(p_exam uuid, p_enrollment uuid default null)
returns table (
  enrollment_id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  subjects_total integer, subjects_entered integer, subjects_absent integer, subjects_draft integer,
  total_score numeric, total_full numeric, percent numeric,
  grade_id uuid, passed boolean, status text
) language sql stable security definer set search_path = public as $$
  with x as (select * from public.result_exams where id = p_exam),
  subj as (select s.* from public.result_subjects s where s.exam_id = p_exam),
  tot as (
    select count(*) filter (where not is_bonus)::integer                         as n_subj,
           coalesce(sum(full_degree) filter (where not is_bonus), 0)             as full_sum,
           coalesce(bool_and(weight is not null) filter (where not is_bonus), false)
             and coalesce(sum(weight) filter (where not is_bonus), 0) > 0        as weighted
      from subj
  ),
  enr as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id
      from public.enrollments e, x
     where e.church_id = x.church_id
       and (x.service_id is null or e.service_id = x.service_id)
       and (x.class_id   is null or e.class_id   = x.class_id)
       and (p_enrollment is null or e.id = p_enrollment)
  ),
  r as (
    select r.*, s.full_degree, s.weight, s.is_bonus,
           case when r.percent is null then null else coalesce(r.score, 0) end as eff_score
      from public.exam_results r join subj s on s.id = r.subject_id
     where r.exam_id = p_exam and (p_enrollment is null or r.enrollment_id = p_enrollment)
  ),
  agg as (
    select enr.id as enrollment_id, enr.person_id, enr.church_id, enr.service_id, enr.class_id,
           count(r.id) filter (where not r.is_bonus)::integer                                        as entered,
           count(r.id) filter (where r.status = 'draft')::integer                                    as n_draft,
           count(r.id) filter (where r.status in ('absent', 'excused') and not r.is_bonus)::integer  as n_absent,
           sum(r.eff_score)   filter (where not r.is_bonus)                                          as score_sum,
           sum(r.full_degree) filter (where r.eff_score is not null and not r.is_bonus)              as full_taken,
           coalesce(sum(r.eff_score) filter (where r.is_bonus), 0)                                   as bonus_sum,
           sum(r.percent * r.weight) filter (where r.eff_score is not null and not r.is_bonus)       as wpct_sum,
           sum(r.weight)            filter (where r.eff_score is not null and not r.is_bonus)        as w_taken,
           coalesce(sum(r.percent * coalesce(r.weight, 0) / 100) filter (where r.eff_score is not null and r.is_bonus), 0) as bonus_wpct,
           coalesce(bool_and(r.passed) filter (where r.eff_score is not null and not r.is_bonus), false) as all_passed
      from enr left join r on r.enrollment_id = enr.id
     group by 1, 2, 3, 4, 5
  ),
  calc as (
    select a.*, t.n_subj, t.full_sum,
           case
             when t.weighted and coalesce(a.w_taken, 0) > 0
               then least(100, round(a.wpct_sum / a.w_taken + a.bonus_wpct, 2))
             when coalesce(a.full_taken, 0) > 0
               then least(100, round((a.score_sum + a.bonus_sum) / a.full_taken * 100, 2))
             else null
           end as pct,
           coalesce(x.min_required_subjects, t.n_subj) as required
      from agg a cross join tot t cross join x
  )
  select c.enrollment_id, c.person_id, c.church_id, c.service_id, c.class_id,
         c.n_subj, c.entered, c.n_absent, c.n_draft,
         case when c.entered > 0 then coalesce(c.score_sum, 0) + c.bonus_sum end as total_score,
         c.full_sum as total_full,
         c.pct as percent,
         case when x.grade_overall then public.grade_for_percent(x.grading_system_id, c.pct) end as grade_id,
         case when c.entered = 0 or c.entered < least(c.required, c.n_subj) or c.n_draft > 0 then null
              when c.n_absent >= c.n_subj and c.n_subj > 0 and c.pct is null then false
              else (case x.pass_rule
                      when 'overall'  then c.pct is not null and c.pct >= x.pass_percent
                      when 'subjects' then c.all_passed and c.pct is not null
                      else c.pct is not null and c.pct >= x.pass_percent and c.all_passed
                    end)
         end as passed,
         case
           when c.n_subj = 0 or c.entered = 0                       then 'not_entered'
           when c.n_absent >= c.n_subj                              then 'absent'
           when c.entered < least(c.required, c.n_subj)             then 'incomplete'
           when c.n_draft > 0                                       then 'draft'
           when (case x.pass_rule
                   when 'overall'  then c.pct is not null and c.pct >= x.pass_percent
                   when 'subjects' then c.all_passed and c.pct is not null
                   else c.pct is not null and c.pct >= x.pass_percent and c.all_passed
                 end)                                               then 'passed'
           else 'failed'
         end as status
    from calc c cross join x
$$;
revoke all on function public.result_summary_core(uuid, uuid) from public, anon, authenticated;

-- Servant view: every student of the exam scope I can see, with rank.
create or replace function public.result_exam_summary(p_exam uuid)
returns table (
  enrollment_id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  name text, national_id text, image_url text,
  subjects_total integer, subjects_entered integer, subjects_absent integer, subjects_draft integer,
  total_score numeric, total_full numeric, percent numeric,
  grade_id uuid, grade_name text, grade_color text, passed boolean, status text,
  rank integer,          -- competition ranking by PERCENT (1 2 2 4) — final results only
  rank_score integer     -- competition ranking by TOTAL SCORE
) language sql stable security definer set search_path = public as $$
  select c.enrollment_id, c.person_id, c.church_id, c.service_id, c.class_id,
         p.name, p.national_id, p.image_url,
         c.subjects_total, c.subjects_entered, c.subjects_absent, c.subjects_draft,
         c.total_score, c.total_full, c.percent,
         c.grade_id, g.name, g.color, c.passed, c.status,
         case when c.status in ('passed', 'failed') then
           (rank() over (order by case when c.status in ('passed', 'failed') then c.percent end desc nulls last))::integer
         end as rank,
         case when c.status in ('passed', 'failed') then
           (rank() over (order by case when c.status in ('passed', 'failed') then c.total_score end desc nulls last))::integer
         end as rank_score
    from public.result_summary_core(p_exam) c
    join public.persons p on p.id = c.person_id
    left join public.grading_grades g on g.id = c.grade_id
   where public.result_can('results.view')
     and exists (select 1 from public.result_exams x where x.id = p_exam
                 and public.scope_overlaps(x.church_id, x.service_id, x.class_id))
     and public.enrollment_visible(c.church_id, c.service_id, c.class_id,
           (select role from public.my_scope()), (select church_id from public.my_scope()),
           (select service_id from public.my_scope()), (select class_id from public.my_scope()))
   order by p.name
$$;
grant execute on function public.result_exam_summary(uuid) to authenticated;

-- Exam history of one person (all his enrollments), newest first.
create or replace function public.result_student_history(p_person uuid)
returns table (
  exam_id uuid, exam_name text, exam_date date, academic_year text, exam_status text, locked boolean, published_at timestamptz,
  enrollment_id uuid, class_id uuid, class_name text, service_name text, church_name text,
  subjects_total integer, subjects_entered integer,
  total_score numeric, total_full numeric, percent numeric,
  grade_id uuid, grade_name text, grade_color text, passed boolean, status text
) language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare e record;
begin
  if not public.result_can('results.view') then return; end if;
  for e in
    select en.id, en.church_id, en.service_id, en.class_id
      from public.enrollments en
     where en.person_id = p_person
       and public.enrollment_visible(en.church_id, en.service_id, en.class_id,
             (select role from public.my_scope()), (select church_id from public.my_scope()),
             (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  loop
    return query
      select x.id, x.name, x.exam_date, x.academic_year, x.status, x.locked, x.published_at,
             e.id, e.class_id, cl.name, sv.name, ch.name,
             c.subjects_total, c.subjects_entered, c.total_score, c.total_full, c.percent,
             c.grade_id, g.name, g.color, c.passed, c.status
        from public.result_exams x
        join public.classes  cl on cl.id = e.class_id
        join public.services sv on sv.id = e.service_id
        join public.churches ch on ch.id = e.church_id
        cross join lateral public.result_summary_core(x.id, e.id) c
        left join public.grading_grades g on g.id = c.grade_id
       where x.church_id = e.church_id
         and (x.service_id is null or x.service_id = e.service_id)
         and (x.class_id   is null or x.class_id   = e.class_id)
         and c.status <> 'not_entered'
       order by x.exam_date desc nulls last, x.created_at desc;
  end loop;
end $$;
grant execute on function public.result_student_history(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 7. WRITE RPCs
-- ---------------------------------------------------------------------
-- Bulk upsert (security INVOKER → RLS + triggers decide per row).
-- p_rows: [{subject_id, enrollment_id, score, status, note}]
-- Returns [{subject_id, enrollment_id, ok, error}] — the caller retries the failures.
create or replace function public.result_save_bulk(p_exam uuid, p_rows jsonb)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare r jsonb; out jsonb := '[]'::jsonb; v_status text; v_score numeric;
begin
  for r in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    begin
      v_status := coalesce(r->>'status', 'completed');
      v_score  := case when r->>'score' is null or r->>'score' = '' then null else (r->>'score')::numeric end;
      insert into public.exam_results (exam_id, subject_id, enrollment_id, score, status, note, person_id, church_id, service_id, class_id)
      select p_exam, (r->>'subject_id')::uuid, e.id, v_score, v_status, r->>'note', e.person_id, e.church_id, e.service_id, e.class_id
        from public.enrollments e where e.id = (r->>'enrollment_id')::uuid
      on conflict (exam_id, subject_id, enrollment_id) do update
        set score = excluded.score, status = excluded.status,
            note  = coalesce(excluded.note, public.exam_results.note);
      if not found then raise exception 'enrollment_not_found' using errcode = 'P0001'; end if;
      out := out || jsonb_build_object('subject_id', r->>'subject_id', 'enrollment_id', r->>'enrollment_id', 'ok', true);
    exception when others then
      out := out || jsonb_build_object('subject_id', r->>'subject_id', 'enrollment_id', r->>'enrollment_id', 'ok', false,
                                       'error', case when sqlstate = '42501' then 'forbidden' else sqlerrm end);
    end;
  end loop;
  return out;
end $$;
grant execute on function public.result_save_bulk(uuid, jsonb) to authenticated;

-- Copy results from another exam: subjects matched by code, then by name;
-- scores scaled when the full degrees differ. Existing rows are kept.
create or replace function public.result_copy_from_exam(p_from uuid, p_to uuid)
returns integer language plpgsql security invoker set search_path = public as $$
declare n integer;
begin
  insert into public.exam_results (exam_id, subject_id, enrollment_id, score, status, note, person_id, church_id, service_id, class_id)
  select distinct on (st.id, r.enrollment_id)
         p_to, st.id, r.enrollment_id,
         case when r.score is null then null else round(r.score * st.full_degree / sf.full_degree, 2) end,
         r.status, r.note, e.person_id, e.church_id, e.service_id, e.class_id
    from public.exam_results r
    join public.result_subjects sf on sf.id = r.subject_id
    join public.result_subjects st on st.exam_id = p_to
         and ((st.code is not null and sf.code is not null and lower(st.code) = lower(sf.code)) or lower(st.name) = lower(sf.name))
    join public.enrollments e on e.id = r.enrollment_id
    join public.result_exams x on x.id = p_to
   where r.exam_id = p_from
     and e.church_id = x.church_id
     and (x.service_id is null or e.service_id = x.service_id)
     and (x.class_id   is null or e.class_id   = x.class_id)
   order by st.id, r.enrollment_id, (st.code is not null and sf.code is not null and lower(st.code) = lower(sf.code)) desc
  on conflict (exam_id, subject_id, enrollment_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.result_copy_from_exam(uuid, uuid) to authenticated;

-- Clear results of an exam (one subject or all). RLS delete policy applies.
create or replace function public.result_clear(p_exam uuid, p_subject uuid default null, p_enrollments uuid[] default null)
returns integer language plpgsql security invoker set search_path = public as $$
declare n integer;
begin
  delete from public.exam_results
   where exam_id = p_exam
     and (p_subject is null or subject_id = p_subject)
     and (p_enrollments is null or enrollment_id = any (p_enrollments));
  get diagnostics n = row_count;
  return n;
end $$;
grant execute on function public.result_clear(uuid, uuid, uuid[]) to authenticated;

-- Lock / unlock (admins — results.lock)
create or replace function public.result_exam_set_lock(p_exam uuid, p_locked boolean)
returns public.result_exams language plpgsql security definer set search_path = public as $$
declare x public.result_exams;
begin
  select * into x from public.result_exams where id = p_exam;
  if x.id is null then raise exception 'exam_not_found' using errcode = 'P0001'; end if;
  if not (public.result_can('results.lock') and public.scope_contains(x.church_id, x.service_id, x.class_id)) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  perform set_config('results.lock_rpc', '1', true);
  update public.result_exams
     set locked = p_locked,
         locked_at = case when p_locked then now() else null end,
         locked_by = case when p_locked then auth.uid() else null end,
         status = case when p_locked and status in ('draft', 'open') then 'completed' else status end
   where id = p_exam returning * into x;
  perform set_config('results.lock_rpc', '', true);
  return x;
end $$;
grant execute on function public.result_exam_set_lock(uuid, boolean) to authenticated;

-- Duplicate an exam with its subjects (no results)
create or replace function public.result_exam_duplicate(p_exam uuid, p_name text default null)
returns uuid language plpgsql security invoker set search_path = public as $$
declare x public.result_exams; nid uuid;
begin
  select * into x from public.result_exams where id = p_exam;
  if x.id is null then raise exception 'exam_not_found' using errcode = 'P0001'; end if;
  insert into public.result_exams (church_id, service_id, class_id, name, exam_date, academic_year, description, status,
    grading_system_id, grade_overall, grade_subject, pass_rule, pass_percent, absent_as_zero, min_required_subjects)
  values (x.church_id, x.service_id, x.class_id, coalesce(nullif(trim(p_name), ''), x.name || ' (نسخة)'), null, x.academic_year, x.description, 'draft',
    x.grading_system_id, x.grade_overall, x.grade_subject, x.pass_rule, x.pass_percent, x.absent_as_zero, x.min_required_subjects)
  returning id into nid;
  insert into public.result_subjects (exam_id, name, code, full_degree, pass_degree, weight, is_bonus, sort_order)
  select nid, name, code, full_degree, pass_degree, weight, is_bonus, sort_order from public.result_subjects where exam_id = p_exam;
  return nid;
end $$;
grant execute on function public.result_exam_duplicate(uuid, text) to authenticated;

-- Duplicate a grading system (with its grades)
create or replace function public.grading_system_duplicate(p_system uuid, p_name text default null)
returns uuid language plpgsql security invoker set search_path = public as $$
declare g public.grading_systems; nid uuid;
begin
  select * into g from public.grading_systems where id = p_system;
  if g.id is null then raise exception 'grading_system_not_found' using errcode = 'P0001'; end if;
  insert into public.grading_systems (church_id, name, description)
  values (case when (select public.is_owner()) then g.church_id else coalesce(g.church_id, (select church_id from public.my_scope())) end,
          coalesce(nullif(trim(p_name), ''), g.name || ' (نسخة)'), g.description)
  returning id into nid;
  insert into public.grading_grades (grading_system_id, name, min_percent, max_percent, description, color, is_pass, sort_order)
  select nid, name, min_percent, max_percent, description, color, is_pass, sort_order from public.grading_grades where grading_system_id = p_system;
  return nid;
end $$;
grant execute on function public.grading_system_duplicate(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 8. CHILD PORTAL — published exams of the child (no auth; QR code)
-- ---------------------------------------------------------------------
create or replace function public.child_portal_results(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.persons; out jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.exam_date desc nulls last), '[]'::jsonb) into out
    from (
      select x.id as exam_id, x.name as exam_name, x.exam_date, x.academic_year, x.published_at,
             e.id as enrollment_id, cl.name as class_name, sv.name as service_name, ch.name as church_name,
             c.subjects_total, c.subjects_entered, c.total_score, c.total_full, c.percent,
             g.name as grade_name, g.color as grade_color, c.passed, c.status,
             (select coalesce(jsonb_agg(jsonb_build_object(
                 'subject_id', s.id, 'subject', s.name, 'full_degree', s.full_degree, 'pass_degree', s.pass_degree, 'is_bonus', s.is_bonus,
                 'score', r.score, 'status', r.status, 'percent', r.percent, 'passed', r.passed,
                 'grade_name', gg.name, 'grade_color', gg.color) order by s.sort_order, s.name), '[]'::jsonb)
                from public.result_subjects s
                left join public.exam_results r on r.subject_id = s.id and r.enrollment_id = e.id
                left join public.grading_grades gg on gg.id = r.grade_id
               where s.exam_id = x.id) as subjects
        from public.enrollments e
        join public.classes  cl on cl.id = e.class_id
        join public.services sv on sv.id = e.service_id
        join public.churches ch on ch.id = e.church_id
        join public.result_exams x on x.church_id = e.church_id
             and (x.service_id is null or x.service_id = e.service_id)
             and (x.class_id   is null or x.class_id   = e.class_id)
        cross join lateral public.result_summary_core(x.id, e.id) c
        left join public.grading_grades g on g.id = c.grade_id
       where e.person_id = p.id
         and x.published_at is not null
         and c.status <> 'not_entered'
    ) t;
  return out;
end $$;
grant execute on function public.child_portal_results(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 9. REALTIME
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['grading_systems', 'grading_grades', 'result_exams', 'result_subjects', 'exam_results'] loop
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
alter table public.result_exams    replica identity full;
alter table public.result_subjects replica identity full;
alter table public.exam_results    replica identity full;
alter table public.grading_systems replica identity full;
alter table public.grading_grades  replica identity full;



-- #####################################################################
-- ##  0039_library.sql
-- #####################################################################

-- =====================================================================
-- 0039: LIBRARY MODULE — المكتبة (links only, simple v1)
--
-- A library organised by SUBJECTS. Each subject holds BOOKS (PDF links)
-- and LECTURES (video / voice links). Nothing is uploaded or stored — every
-- book / lecture / cover / thumbnail is a URL (Google Drive, YouTube, direct
-- PDF / audio / video …).
--
--   1. library_subjects   — name · description · cover image · audience
--   2. library_books      — subject · title · author · description · cover ·
--                           pdf_url · audience
--   3. library_lectures   — subject · title · speaker · description · date ·
--                           kind (video | voice) · media_url · thumbnail ·
--                           audience
--   4. library_favorites  — ⭐ per servant (user_id) or per child (person_id)
--                           on a book or a lecture
--
-- AUDIENCE (من يرى المحتوى) — reuses the existing scope model:
--   everyone : every servant + every child (child portal)
--   servants : servants only (never shown in the child portal)
--   service  : servants whose scope overlaps church → service, and children
--              enrolled in that service
--   class    : servants whose scope overlaps church → service → class, and
--              children enrolled in that class
--   A book / lecture is visible only when ITS audience AND ITS SUBJECT's
--   audience both allow the viewer.
--
-- PERMISSIONS (existing RBAC — module grant + role + permission keys 0037):
--   library_can(key): module_visible('library') AND (role in owner /
--   church_manager / service_manager  OR  key = 'library.view'  OR
--   has_permission(key)).
--     library.view    — browse (every servant of a granted scope)
--     library.manage  — add / edit / delete subjects, books, lectures
--   Rows with audience service / class additionally require
--   scope_contains(church, service, class) to be written.
--
-- CHILD PORTAL (anon, token = national id):
--   child_portal_library(nid)          → subjects + books + lectures +
--                                        favorites the child may see
--   child_portal_library_favorite(...) → toggle ⭐
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope / scope_*), 0021
-- (child portal), 0024 (module_visible), 0027 (module_granted_for), 0037
-- (has_permission, servant_enrollments). NO module grant is seeded — the
-- owner enables it per scope in وحدة المالك → صلاحيات الوحدات.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. PERMISSION HELPERS
-- ---------------------------------------------------------------------
create or replace function public.library_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('library')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or p_key = 'library.view'
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.library_can(text) to authenticated;

create or replace function public.library_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',   public.library_can('library.view'),
    'manage', public.library_can('library.manage')
  )
$$;
grant execute on function public.library_permissions() to authenticated;

-- Can the signed-in SERVANT see content with this audience?
create or replace function public.library_audience_visible(
  p_audience text, p_church uuid, p_service uuid, p_class uuid
) returns boolean language sql stable security definer set search_path = public as $$
  select case p_audience
    when 'everyone' then true
    when 'servants' then true
    when 'service'  then public.scope_overlaps(p_church, p_service, null)
    when 'class'    then public.scope_overlaps(p_church, p_service, p_class)
    else false
  end
$$;
grant execute on function public.library_audience_visible(text, uuid, uuid, uuid) to authenticated;

-- May the signed-in servant WRITE content with this audience?
create or replace function public.library_audience_writable(
  p_audience text, p_church uuid, p_service uuid, p_class uuid
) returns boolean language sql stable security definer set search_path = public as $$
  select public.library_can('library.manage')
     and case p_audience
       when 'everyone' then true
       when 'servants' then true
       when 'service'  then public.scope_contains(p_church, p_service, null)
       when 'class'    then public.scope_contains(p_church, p_service, p_class)
       else false
     end
$$;
grant execute on function public.library_audience_writable(text, uuid, uuid, uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 1. TABLE: library_subjects (المواضيع)
-- ---------------------------------------------------------------------
create table if not exists public.library_subjects (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  description  text,
  image_url    text,
  audience     text not null default 'everyone' check (audience in ('everyone', 'servants', 'service', 'class')),
  church_id    uuid references public.churches(id) on delete cascade,
  service_id   uuid references public.services(id) on delete cascade,
  class_id     uuid references public.classes(id)  on delete cascade,
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  created_by   uuid references public.servant_enrollments(id) on delete set null,
  edited_at    timestamptz not null default now(),
  edited_by    uuid references public.servant_enrollments(id) on delete set null,
  constraint library_subjects_name_not_blank check (length(trim(name)) > 0),
  constraint library_subjects_audience_scope check (
    (audience in ('everyone', 'servants') and church_id is null and service_id is null and class_id is null)
    or (audience = 'service' and church_id is not null and service_id is not null and class_id is null)
    or (audience = 'class'   and church_id is not null and service_id is not null and class_id is not null)
  )
);
comment on table public.library_subjects is 'المكتبة — المواضيع (اسم · وصف · صورة · من يراه)';

create index if not exists idx_library_subjects_order on public.library_subjects(sort_order, name);
create index if not exists idx_library_subjects_scope on public.library_subjects(church_id, service_id, class_id);

-- ---------------------------------------------------------------------
-- 2. TABLE: library_books (الكتب — روابط PDF)
-- ---------------------------------------------------------------------
create table if not exists public.library_books (
  id           uuid primary key default gen_random_uuid(),
  subject_id   uuid not null references public.library_subjects(id) on delete cascade,
  title        text not null,
  author       text,
  description  text,
  cover_url    text,
  pdf_url      text not null,
  audience     text not null default 'everyone' check (audience in ('everyone', 'servants', 'service', 'class')),
  church_id    uuid references public.churches(id) on delete cascade,
  service_id   uuid references public.services(id) on delete cascade,
  class_id     uuid references public.classes(id)  on delete cascade,
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  created_by   uuid references public.servant_enrollments(id) on delete set null,
  edited_at    timestamptz not null default now(),
  edited_by    uuid references public.servant_enrollments(id) on delete set null,
  constraint library_books_title_not_blank check (length(trim(title)) > 0),
  constraint library_books_url_not_blank   check (length(trim(pdf_url)) > 0),
  constraint library_books_audience_scope check (
    (audience in ('everyone', 'servants') and church_id is null and service_id is null and class_id is null)
    or (audience = 'service' and church_id is not null and service_id is not null and class_id is null)
    or (audience = 'class'   and church_id is not null and service_id is not null and class_id is not null)
  )
);
comment on table public.library_books is 'المكتبة — الكتب (رابط PDF · عنوان · مؤلف · وصف · غلاف)';

create index if not exists idx_library_books_subject on public.library_books(subject_id, sort_order, title);
create index if not exists idx_library_books_scope   on public.library_books(church_id, service_id, class_id);

-- ---------------------------------------------------------------------
-- 3. TABLE: library_lectures (المحاضرات — فيديو / صوت)
-- ---------------------------------------------------------------------
create table if not exists public.library_lectures (
  id             uuid primary key default gen_random_uuid(),
  subject_id     uuid not null references public.library_subjects(id) on delete cascade,
  title          text not null,
  speaker        text,
  description    text,
  lecture_date   date,
  kind           text not null default 'video' check (kind in ('video', 'voice')),
  media_url      text not null,
  thumbnail_url  text,
  audience       text not null default 'everyone' check (audience in ('everyone', 'servants', 'service', 'class')),
  church_id      uuid references public.churches(id) on delete cascade,
  service_id     uuid references public.services(id) on delete cascade,
  class_id       uuid references public.classes(id)  on delete cascade,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now(),
  created_by     uuid references public.servant_enrollments(id) on delete set null,
  edited_at      timestamptz not null default now(),
  edited_by      uuid references public.servant_enrollments(id) on delete set null,
  constraint library_lectures_title_not_blank check (length(trim(title)) > 0),
  constraint library_lectures_url_not_blank   check (length(trim(media_url)) > 0),
  constraint library_lectures_audience_scope check (
    (audience in ('everyone', 'servants') and church_id is null and service_id is null and class_id is null)
    or (audience = 'service' and church_id is not null and service_id is not null and class_id is null)
    or (audience = 'class'   and church_id is not null and service_id is not null and class_id is not null)
  )
);
comment on table public.library_lectures is 'المكتبة — المحاضرات (فيديو أو صوت · رابط · متحدث · تاريخ · صورة)';

create index if not exists idx_library_lectures_subject on public.library_lectures(subject_id, sort_order, lecture_date desc);
create index if not exists idx_library_lectures_scope   on public.library_lectures(church_id, service_id, class_id);

-- ---------------------------------------------------------------------
-- 4. TABLE: library_favorites (⭐ المفضلة)
-- ---------------------------------------------------------------------
create table if not exists public.library_favorites (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references public.servant_enrollments(id) on delete cascade,  -- a servant …
  person_id   uuid references public.persons(id)             on delete cascade,  -- … or a child
  book_id     uuid references public.library_books(id)       on delete cascade,
  lecture_id  uuid references public.library_lectures(id)    on delete cascade,
  created_at  timestamptz not null default now(),
  constraint library_favorites_one_owner check ((user_id is null) <> (person_id is null)),
  constraint library_favorites_one_item  check ((book_id is null) <> (lecture_id is null))
);
comment on table public.library_favorites is 'المكتبة — المفضلة: خادم (user_id) أو مخدوم (person_id) ⭐ كتاب أو محاضرة';

create unique index if not exists uq_library_fav_user_book      on public.library_favorites(user_id, book_id)      where user_id is not null and book_id is not null;
