do $$
declare t text;
begin
  foreach t in array array['library_subjects', 'library_books', 'library_lectures', 'library_favorites'] loop
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
exception when undefined_object then null;   -- no publication on a local shim
end $$;
alter table public.library_subjects  replica identity full;
alter table public.library_books     replica identity full;
alter table public.library_lectures  replica identity full;
alter table public.library_favorites replica identity full;



-- #####################################################################
-- ##  0040_code_system.sql
-- #####################################################################

-- =====================================================================
-- 0040: CODE SYSTEM (تخصيص التطبيق → نظام الأكواد)
--
-- The OWNER designs how the codes generated by the app look. A code is a
-- TEMPLATE = ordered PARTS joined by a SEPARATOR, e.g.
--
--     [text "P"] - [timestamp]                        →  P-1702655732293
--     [church] - [class] - [date YYMMDD] - [random 4] →  STM-C1-231215-4F7K
--
-- Stored in `app_settings` (0035 — owner-write / all-read / realtime):
--
--   key = 'codes' → {
--     version: 1,
--     default:    { parts: [...], separator: '-', case: 'none'|'upper'|'lower' },
--     generators: {                       -- one entry per generator in the app
--       person:     { mode: 'default'|'custom'|'legacy', template? },
--       servant:    { ... },
--       store_item: { ... },
--       ticket:     { ... }               -- rendered HERE (render_code) by the trigger
--     },
--     scopes: {                           -- abbreviations used by church/service/class parts
--       churches: { "<uuid>": "STM" }, services: { ... }, classes: { ... }
--     }
--   }
--
--   parts[].type ∈ text {value} · timestamp · date {format} · random {length, charset}
--                  · church | service | class {fallback}
--
-- The app renders codes in `src/lib/code-templates.ts` (`renderTemplate`);
-- `public.render_code()` below is its SQL mirror so DATABASE-generated codes
-- (occasion tickets) follow the same design. `public.code_settings()` lets the
-- anonymous SIGNUP page read the configuration (the servant code is generated
-- before the account exists). Idempotent — safe to re-run.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Validation — the owner can never save a malformed code system
-- ---------------------------------------------------------------------
create or replace function public.validate_code_template(t jsonb, label text)
returns void language plpgsql immutable as $$
declare p jsonb; n int;
begin
  if jsonb_typeof(t) <> 'object' then
    raise exception 'app_settings.codes: % must be an object', label;
  end if;
  if jsonb_typeof(t -> 'parts') <> 'array' or jsonb_array_length(t -> 'parts') > 8 then
    raise exception 'app_settings.codes: %.parts must be an array (max 8)', label;
  end if;
  if t ? 'separator' and (jsonb_typeof(t -> 'separator') <> 'string'
      or length(t ->> 'separator') > 3 or (t ->> 'separator') !~ '^[A-Za-z0-9._-]*$') then
    raise exception 'app_settings.codes: %.separator must be ≤ 3 safe characters', label;
  end if;
  if t ? 'case' and (t ->> 'case') not in ('none', 'upper', 'lower') then
    raise exception 'app_settings.codes: %.case invalid', label;
  end if;
  for p in select * from jsonb_array_elements(t -> 'parts') loop
    if jsonb_typeof(p) <> 'object' then raise exception 'app_settings.codes: %.parts[] must be objects', label; end if;
    case p ->> 'type'
      when 'text' then
        if coalesce(p ->> 'value', '') !~ '^[A-Za-z0-9._-]{1,12}$' then
          raise exception 'app_settings.codes: %: text part must be 1–12 safe characters', label;
        end if;
      when 'timestamp' then null;
      when 'date' then
        if coalesce(p ->> 'format', '') not in ('YYYYMMDD','YYMMDD','DDMMYYYY','DDMMYY','YYYYMM','YYMM','YYYY','YY') then
          raise exception 'app_settings.codes: %: invalid date format', label;
        end if;
      when 'random' then
        n := (p ->> 'length')::int;
        if n is null or n < 1 or n > 16 then raise exception 'app_settings.codes: %: random length must be 1–16', label; end if;
        if coalesce(p ->> 'charset', 'alnum') not in ('alnum', 'digits', 'letters', 'hex') then
          raise exception 'app_settings.codes: %: invalid random charset', label;
        end if;
      when 'church', 'service', 'class' then
        if coalesce(p ->> 'fallback', '') !~ '^[A-Za-z0-9._-]{0,8}$' then
          raise exception 'app_settings.codes: %: scope fallback must be ≤ 8 safe characters', label;
        end if;
      else
        raise exception 'app_settings.codes: %: unknown part type %', label, p ->> 'type';
    end case;
  end loop;
end $$;

create or replace function public.validate_app_settings()
returns trigger language plpgsql as $$
declare g text; gen jsonb; kv record;
begin
  if jsonb_typeof(new.value) <> 'object' then
    raise exception 'app_settings.value must be a JSON object (key %)', new.key;
  end if;
  if new.key = 'names' then
    if exists (
      select 1 from jsonb_each(new.value) kv
       where jsonb_typeof(kv.value) <> 'string'
          or length(kv.value #>> '{}') = 0
          or length(kv.value #>> '{}') > 30
    ) then
      raise exception 'app_settings.names: every label must be a 1–30 character string';
    end if;
  end if;
  if new.key = 'widgets' then
    if jsonb_typeof(new.value -> 'items') <> 'array'
       or jsonb_array_length(new.value -> 'items') > 40 then
      raise exception 'app_settings.widgets: items must be an array (max 40)';
    end if;
  end if;
  if new.key = 'codes' then
    perform public.validate_code_template(new.value -> 'default', 'default');
    if jsonb_array_length(new.value -> 'default' -> 'parts') = 0 then
      raise exception 'app_settings.codes: default template needs at least one part';
    end if;
    if new.value ? 'generators' then
      if jsonb_typeof(new.value -> 'generators') <> 'object' then
        raise exception 'app_settings.codes: generators must be an object';
      end if;
      for g, gen in select * from jsonb_each(new.value -> 'generators') loop
        if g not in ('person', 'servant', 'store_item', 'ticket') then
          raise exception 'app_settings.codes: unknown generator %', g;
        end if;
        if coalesce(gen ->> 'mode', 'legacy') not in ('default', 'custom', 'legacy') then
          raise exception 'app_settings.codes: generator % has an invalid mode', g;
        end if;
        if gen ? 'template' then perform public.validate_code_template(gen -> 'template', g); end if;
        if gen ->> 'mode' = 'custom' and jsonb_array_length(coalesce(gen -> 'template' -> 'parts', '[]'::jsonb)) = 0 then
          raise exception 'app_settings.codes: generator % is custom but has no parts', g;
        end if;
      end loop;
    end if;
    if new.value ? 'scopes' then
      for kv in
        select m.key as grp, e.key as id, e.value as abbr
          from jsonb_each(new.value -> 'scopes') m
          cross join lateral jsonb_each(m.value) e
      loop
        if kv.grp not in ('churches', 'services', 'classes') then
          raise exception 'app_settings.codes: unknown scope group %', kv.grp;
        end if;
        if jsonb_typeof(kv.abbr) <> 'string' or (kv.abbr #>> '{}') !~ '^[A-Za-z0-9._-]{1,8}$' then
          raise exception 'app_settings.codes: abbreviation for % must be 1–8 safe characters', kv.id;
        end if;
      end loop;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_validate_app_settings on public.app_settings;
create trigger trg_validate_app_settings before insert or update on public.app_settings
for each row execute function public.validate_app_settings();

-- ---------------------------------------------------------------------
-- 2. render_code — SQL mirror of renderTemplate() (src/lib/code-templates.ts)
-- ---------------------------------------------------------------------
create or replace function public.random_code_chars(n int, charset text)
returns text language plpgsql volatile as $$
declare
  alphabet text := case charset
    when 'digits'  then '0123456789'
    when 'letters' then 'ABCDEFGHJKLMNPQRSTUVWXYZ'
    when 'hex'     then '0123456789ABCDEF'
    else 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789' end;
  out text := '';
  i int;
begin
  for i in 1..greatest(1, least(16, coalesce(n, 6))) loop
    out := out || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return out;
end $$;

create or replace function public.format_code_date(d timestamptz, fmt text)
returns text language sql immutable as $$
  select to_char(d at time zone 'Africa/Cairo', case fmt
    when 'YYYYMMDD' then 'YYYYMMDD'
    when 'YYMMDD'   then 'YYMMDD'
    when 'DDMMYYYY' then 'DDMMYYYY'
    when 'DDMMYY'   then 'DDMMYY'
    when 'YYYYMM'   then 'YYYYMM'
    when 'YYMM'     then 'YYMM'
    when 'YYYY'     then 'YYYY'
    when 'YY'       then 'YY'
    else 'YYYYMMDD' end)
$$;

-- t = template object · scopes = codes.scopes · the three ids = generation context
create or replace function public.render_code(
  t jsonb, scopes jsonb, p_church uuid, p_service uuid, p_class uuid, p_now timestamptz default clock_timestamp())
returns text language plpgsql volatile as $$
declare
  p jsonb; seg text; segs text[] := '{}'; sep text; kase text; res text; sid text;
begin
  if t is null or jsonb_typeof(t -> 'parts') <> 'array' then return null; end if;
  sep  := coalesce(t ->> 'separator', '-');
  kase := coalesce(t ->> 'case', 'none');
  for p in select * from jsonb_array_elements(t -> 'parts') loop
    case p ->> 'type'
      when 'text'      then seg := p ->> 'value';
      when 'timestamp' then seg := (floor(extract(epoch from p_now) * 1000))::bigint::text;
      when 'date'      then seg := public.format_code_date(p_now, p ->> 'format');
      when 'random'    then seg := public.random_code_chars((p ->> 'length')::int, p ->> 'charset');
      when 'church'    then
        sid := p_church::text;
        seg := coalesce(nullif(scopes -> 'churches' ->> sid, ''), p ->> 'fallback', '');
      when 'service'   then
        sid := p_service::text;
        seg := coalesce(nullif(scopes -> 'services' ->> sid, ''), p ->> 'fallback', '');
      when 'class'     then
        sid := p_class::text;
        seg := coalesce(nullif(scopes -> 'classes' ->> sid, ''), p ->> 'fallback', '');
      else seg := '';
    end case;
    if coalesce(seg, '') <> '' then segs := segs || seg; end if;
  end loop;
  res := array_to_string(segs, sep);
  if kase = 'upper' then res := upper(res); elsif kase = 'lower' then res := lower(res); end if;
  return nullif(res, '');
end $$;

-- the template a generator actually uses — null = legacy built-in
create or replace function public.code_template_for(p_kind text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare cfg jsonb; gen jsonb; mode text;
begin
  select value into cfg from public.app_settings where key = 'codes';
  if cfg is null then return null; end if;
  gen  := cfg -> 'generators' -> p_kind;
  mode := coalesce(gen ->> 'mode', 'legacy');
  if mode = 'legacy' then return null; end if;
  if mode = 'custom' and jsonb_array_length(coalesce(gen -> 'template' -> 'parts', '[]'::jsonb)) > 0 then
    return gen -> 'template';
  end if;
  if jsonb_array_length(coalesce(cfg -> 'default' -> 'parts', '[]'::jsonb)) > 0 then
    return cfg -> 'default';
  end if;
  return null;
end $$;
revoke all on function public.code_template_for(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. Occasion ticket code → follows the owner's design (legacy when unset)
-- ---------------------------------------------------------------------
create or replace function public.occasion_new_ticket_code(p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v text; i integer := 0; t jsonb; scopes jsonb;
begin
  t := public.code_template_for('ticket');
  select value -> 'scopes' into scopes from public.app_settings where key = 'codes';
  loop
    if t is not null then
      v := public.render_code(t, coalesce(scopes, '{}'::jsonb), p_church, p_service, p_class);
      -- a template without any random / timestamp part could repeat → add a tiny suffix on retry
      if i > 0 then v := v || '-' || public.random_code_chars(2, 'alnum'); end if;
    end if;
    if v is null then
      v := 'T-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    end if;
    exit when not exists (select 1 from public.occasion_registrations r where r.ticket_code = v);
    i := i + 1;
    if i > 20 then raise exception 'ticket_code_collision'; end if;
    perform pg_sleep(0.001);   -- lets a timestamp-based template move forward
  end loop;
  return v;
end $$;
revoke all on function public.occasion_new_ticket_code(uuid, uuid, uuid) from public, anon, authenticated;
-- drop the old zero-arg overload (0032/0033) so the trigger resolves unambiguously
drop function if exists public.occasion_new_ticket_code();

create or replace function public.occasion_registration_fill()
returns trigger language plpgsql security definer set search_path = public as $$
declare e public.enrollments; o public.occasions;
begin
  select * into e from public.enrollments where id = new.enrollment_id;
  if not found then raise exception 'enrollment_not_found' using errcode = 'P0002'; end if;
  select * into o from public.occasions where id = new.occasion_id;
  if not found then raise exception 'occasion_not_found' using errcode = 'P0002'; end if;
  if not (o.church_id = e.church_id
          and (o.service_id is null or o.service_id = e.service_id)
          and (o.class_id   is null or o.class_id   = e.class_id)) then
    raise exception 'out_of_scope' using errcode = 'P0001';
  end if;
  new.person_id  := e.person_id;
  new.church_id  := e.church_id;
  new.service_id := e.service_id;
  new.class_id   := e.class_id;
  if new.ticket_code is null or length(trim(new.ticket_code)) = 0 then
    new.ticket_code := public.occasion_new_ticket_code(e.church_id, e.service_id, e.class_id);
  end if;
  return new;
end $$;

drop trigger if exists trg_occ_reg_fill on public.occasion_registrations;
create trigger trg_occ_reg_fill before insert on public.occasion_registrations
for each row execute function public.occasion_registration_fill();

-- ---------------------------------------------------------------------
-- 4. Fallback person code inside add_person_and_enroll (no code given)
--    follows the 'person' generator instead of 24 hex chars.
-- ---------------------------------------------------------------------
create or replace function public.new_person_code(p_church uuid, p_service uuid, p_class uuid)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v text; i int := 0; t jsonb; scopes jsonb;
begin
  t := public.code_template_for('person');
  select value -> 'scopes' into scopes from public.app_settings where key = 'codes';
  loop
    if t is not null then
      v := public.render_code(t, coalesce(scopes, '{}'::jsonb), p_church, p_service, p_class);
      if i > 0 then v := v || '-' || public.random_code_chars(2, 'alnum'); end if;
    end if;
    if v is null then v := 'P-' || public.random_code_chars(8, 'alnum'); end if;
    exit when not exists (select 1 from public.persons p where p.national_id = v);
    i := i + 1;
    if i > 20 then raise exception 'person_code_collision'; end if;
    perform pg_sleep(0.001);
  end loop;
  return v;
end $$;
revoke all on function public.new_person_code(uuid, uuid, uuid) from public, anon, authenticated;

-- same body as 0011, only the fallback code changed (hex → new_person_code)
create or replace function public.add_person_and_enroll(
  p_church uuid,
  p_service uuid,
  p_class uuid,
  p_name text,
  p_national_id text default null,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_image_url text default null,
  p_points integer default 0
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_nid text;
  v_person public.persons%rowtype;
  v_person_created boolean := false;
  v_enrollment_id uuid;
  v_already boolean := false;
begin
  if public.my_role() is null then
    raise exception 'not_approved' using errcode = '42501';
  end if;
  if not public.can_access(p_church, p_service, p_class) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if coalesce(trim(p_name), '') = '' then
    raise exception 'name_required';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender';
  end if;

  v_nid := nullif(trim(p_national_id), '');
  if v_nid is null then
    v_nid := public.new_person_code(p_church, p_service, p_class);
  end if;

  select * into v_person from public.persons where national_id = v_nid;

  if not found then
    insert into public.persons (
      national_id, name, gender, birthdate, phone, address, notes,
      image_url, created_by, edited_by
    ) values (
      v_nid, trim(p_name), p_gender, p_birthdate,
      nullif(trim(coalesce(p_phone, '')), ''),
      nullif(trim(coalesce(p_address, '')), ''),
      nullif(trim(coalesce(p_notes, '')), ''),
      p_image_url, auth.uid(), auth.uid()
    ) returning * into v_person;
    v_person_created := true;
  else
    -- Person exists: fill in the blanks only (never overwrite existing data)
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = auth.uid(),
      edited_at = now()
    where id = v_person.id;
  end if;

  -- Register the enrollment (person may already be in this class)
  insert into public.enrollments (person_id, church_id, service_id, class_id, points, created_by, edited_by)
  values (v_person.id, p_church, p_service, p_class, greatest(coalesce(p_points, 0), 0), auth.uid(), auth.uid())
  on conflict (person_id, class_id) do nothing
  returning id into v_enrollment_id;

  if v_enrollment_id is null then
    v_already := true;
    select id into v_enrollment_id from public.enrollments
     where person_id = v_person.id and class_id = p_class;
  end if;

  return jsonb_build_object(
    'person_id', v_person.id,
    'enrollment_id', v_enrollment_id,
    'national_id', v_nid,
    'person_created', v_person_created,
    'already_enrolled', v_already
  );
end $$;

-- ---------------------------------------------------------------------
-- 5. code_settings — read-only access for the anonymous SIGNUP page
--    (the servant generates his code before he has an account)
-- ---------------------------------------------------------------------
create or replace function public.code_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select value from public.app_settings where key = 'codes'
$$;
grant execute on function public.code_settings() to anon, authenticated;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  0041_admin_add_servants.sql
-- #####################################################################

-- =====================================================================
-- 0041: ADD SERVANTS DIRECTLY (إضافة خدام — فردي / جماعي)
--
-- Until now a servant could only join through the SIGNUP wizard (he
-- creates his own account, the manager approves). This migration lets an
-- owner / church manager / service manager ADD servants himself — one by
-- one or in bulk (Excel / paste) — exactly like adding children:
--
--   manager (browser) ──▶ POST /api/servants/create  (Next.js, server)
--                              │ 1. caller session → actor id
--                              │ 2. auth.admin.createUser (login = the code)
--                              ▼
--                         admin_add_servant(actor, account, …)   ◀── THIS FILE
--                              │ validates the ACTOR's rights (role + scope)
--                              │ person upserted by code, APPROVED servant
--                              │ enrollment, permission profiles granted
--                              ▼
--                         servant logs in with code + password right away
--
-- The RPC is SECURITY DEFINER and executable by service_role ONLY — the
-- browser never calls it. The actor is passed explicitly (the server has
-- already verified his session) and every rule a manager is bound to in
-- the approval flow is re-checked here:
--   owner            → any role but owner, any scope
--   church_manager   → service_manager / class_servant inside his church
--   service_manager  → class_servant inside his service (or his church
--                      when he has no service)
-- =====================================================================


create or replace function public.admin_add_servant(
  p_actor     uuid,
  p_account   uuid,                       -- the freshly created auth.users id
  p_code      text,
  p_full_name text,
  p_role      public.app_role default 'class_servant',
  p_church    uuid default null,
  p_service   uuid default null,
  p_class     uuid default null,
  p_gender    text default null,
  p_birthdate date default null,
  p_phone     text default null,
  p_address   text default null,
  p_notes     text default null,
  p_image_url text default null,
  p_profiles  uuid[] default '{}'
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor  public.servant_enrollments%rowtype;
  v_code   text := nullif(trim(p_code), '');
  v_name   text := nullif(trim(coalesce(p_full_name, '')), '');
  v_phone  text := nullif(trim(coalesce(p_phone, '')), '');
  v_user_id text;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_granted integer := 0;
begin
  -- ---------- actor ----------
  if p_actor is null or p_account is null then
    raise exception 'actor_required' using errcode = '22023';
  end if;
  select * into v_actor from public.servant_enrollments where id = p_actor;
  if not found or v_actor.status <> 'approved'
     or v_actor.role not in ('owner', 'church_manager', 'service_manager') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  -- ---------- input ----------
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender' using errcode = '22023';
  end if;
  if p_role = 'owner' then raise exception 'role_not_allowed' using errcode = '42501'; end if;
  if p_church is null then raise exception 'church_required' using errcode = '22023'; end if;

  -- scope chain must be consistent
  if not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_not_found' using errcode = '22023';
  end if;
  if p_service is not null
     and not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and (p_service is null
      or not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;

  -- ---------- what may THIS actor grant? (mirror of the approval flow) ----------
  if v_actor.role = 'church_manager' then
    if p_role = 'church_manager' then raise exception 'role_not_allowed' using errcode = '42501'; end if;
    if p_church is distinct from v_actor.church_id then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
  elsif v_actor.role = 'service_manager' then
    if p_role <> 'class_servant' then raise exception 'role_not_allowed' using errcode = '42501'; end if;
    if p_church is distinct from v_actor.church_id then raise exception 'scope_not_allowed' using errcode = '42501'; end if;
    if v_actor.service_id is not null and p_service is distinct from v_actor.service_id then
      raise exception 'scope_not_allowed' using errcode = '42501';
    end if;
  end if;

  -- ---------- the code = login name ----------
  v_user_id := public.code_to_user_id(v_code);
  if exists (select 1 from public.servant_enrollments s where s.user_id = v_user_id) then
    raise exception 'code_taken' using errcode = '23505';
  end if;
  if exists (select 1 from public.servant_enrollments s where s.id = p_account) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  -- the code may already belong to a PERSON (e.g. an older child / a card
  -- printed for him) — fine, we bind the account to that person — unless
  -- that person already has a servant account.
  select * into v_person from public.persons where national_id = v_code;
  if found and exists (select 1 from public.servant_enrollments s where s.person_id = v_person.id) then
    raise exception 'code_taken' using errcode = '23505';
  end if;

  -- ---------- 1) the APPROVED servant enrollment (placeholder first:
  --            persons.created_by references servant_enrollments) ----------
  perform set_config('app.in_servant_signup', '1', true);   -- bypass auto-person + guard triggers
  insert into public.servant_enrollments
    (id, full_name, user_id, phone, role, status, church_id, service_id, class_id,
     approved_by, approved_at)
  values
    (p_account, v_name, v_user_id, coalesce(v_phone, ''), p_role, 'approved',
     p_church, p_service, p_class, p_actor, now());

  -- ---------- 2) the person (upsert by code) ----------
  if v_person.id is null then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, v_name, p_gender, p_birthdate, v_phone,
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            p_image_url, p_actor, p_actor)
    returning * into v_person;
    v_created := true;
  else
    -- the manager typed the data himself → what he provided wins, blanks keep the old value
    update public.persons set
      name      = v_name,
      gender    = coalesce(p_gender, gender),
      birthdate = coalesce(p_birthdate, birthdate),
      phone     = coalesce(v_phone, phone),
      address   = coalesce(nullif(trim(coalesce(p_address, '')), ''), address),
      notes     = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
      image_url = coalesce(p_image_url, image_url),
      edited_by = p_actor, edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  -- ---------- 3) bind + mirrors ----------
  update public.servant_enrollments set
    person_id = v_person.id,
    full_name = v_person.name,
    phone     = coalesce(v_person.phone, ''),
    photo_url = v_person.image_url,
    updated_at = now()
  where id = p_account;
  perform set_config('app.in_servant_signup', '0', true);

  -- ---------- 4) permission profiles ----------
  if p_profiles is not null and cardinality(p_profiles) > 0 and p_role <> 'owner' then
    insert into public.permissions (servant_id, permission_profile_id, granted_by)
    select p_account, pp.id, p_actor
      from public.permission_profiles pp
     where pp.id = any (p_profiles)
    on conflict do nothing;
    get diagnostics v_granted = row_count;
  end if;

  return jsonb_build_object(
    'servant_id', p_account,
    'person_id', v_person.id,
    'person_created', v_created,
    'national_id', v_person.national_id,
    'user_id', v_user_id,
    'profiles_granted', v_granted
  );
end $$;

comment on function public.admin_add_servant is
  'إضافة خادم مباشرة (معتمد) من مسؤول — يُستدعى من الخادم فقط (service_role) بعد إنشاء حساب الدخول';

revoke all on function public.admin_add_servant(uuid, uuid, text, text, public.app_role, uuid, uuid, uuid, text, date, text, text, text, text, uuid[])
  from public, anon, authenticated;
grant execute on function public.admin_add_servant(uuid, uuid, text, text, public.app_role, uuid, uuid, uuid, text, date, text, text, text, text, uuid[])
  to service_role;

-- ---------------------------------------------------------------------
-- Pre-check for the ADD form (browser, authenticated managers): is this
-- code free? Same exposure as signup_lookup_code but tells the caller
-- whether the code already has an ACCOUNT (blocked) or only a PERSON
-- (data pre-filled) — used live while typing / scanning.
-- ---------------------------------------------------------------------
create or replace function public.admin_servant_code_lookup(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'user_id', public.code_to_user_id(trim(p_code)),
      'login_taken', exists (select 1 from public.servant_enrollments s
                              where s.user_id = public.code_to_user_id(trim(p_code))),
      'person', (
        select jsonb_build_object(
          'name', p.name, 'gender', p.gender, 'birthdate', p.birthdate,
          'phone', p.phone, 'address', p.address, 'notes', p.notes, 'image_url', p.image_url,
          'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
        from public.persons p where p.national_id = trim(p_code) limit 1)
    )
  end
$$;
revoke all on function public.admin_servant_code_lookup(text) from public, anon;
grant execute on function public.admin_servant_code_lookup(text) to authenticated;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  0042_child_accounts_servant_mirror.sql
-- #####################################################################

-- =====================================================================
-- 0042: CHILD ACCOUNTS (كلمة مرور المخدوم + طلبات انضمام المخدومين)
--       + SERVANTS AS ENROLLMENTS (الخدام كفصول في صفحة المخدومين)
--
-- A. enrollments.kind  ('child' | 'servant') + enrollments.servant_id
--    Every APPROVED (or suspended) servant whose scope is complete
--    (church → service → class) gets a MIRROR row in `enrollments`
--    (kind = 'servant', servant_id = his account). The children page can
--    therefore switch between «المخدومين» and «الخدام» and offer EVERY job
--    (attendance · points · calls · messages · data · cards · achievements)
--    on servants too, grouped by class exactly like children. A trigger on
--    servant_enrollments keeps the mirror in sync (scope / status / delete).
--    All statistics RPCs gain `p_kind` (default 'child') so the numbers of
--    the children keep meaning "children".
--
-- B. person_credentials — a PASSWORD for the child portal. The card QR
--    (national id) is no longer a bearer token by itself: the child logs in
--    with code + password (`child_login`) and receives a SESSION TOKEN
--    (`child_sessions`, sha-256 stored, 12 h or 90 days with «تذكرني»).
--    `child_portal_person(token)` — the resolver every child_portal_* RPC
--    already uses — now accepts ONLY a live session token, so all ~50 portal
--    RPCs are protected at once without touching them.
--
-- C. child_join_requests — «إنشاء حساب مخدوم» (/child/signup): code (typed
--    or scanned) + data + password + desired class → a PENDING request the
--    servants review in إدارة المخدومين → الطلبات (`review_child_join_request`
--    creates / binds the person, the enrollment and the credentials).
--
-- D. Password management: child_change_password (the child himself),
--    admin_set_child_password (a servant who can access the person — used by
--    the edit modal on the children page and by the add-child form).
--
-- pgcrypto: on Supabase it lives in the `extensions` schema, so every
-- function that hashes uses `search_path = public, extensions`.
-- Idempotent.
-- =====================================================================


do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pgcrypto') then
    begin
      create extension pgcrypto with schema extensions;
    exception when others then
      create extension if not exists pgcrypto;
    end;
  end if;
end $$;

-- =====================================================================
-- A. ENROLLMENTS.KIND + SERVANT MIRROR
-- =====================================================================
alter table public.enrollments
  add column if not exists kind text not null default 'child',
  add column if not exists servant_id uuid references public.servant_enrollments(id) on delete cascade;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'enrollments_kind_check') then
    alter table public.enrollments add constraint enrollments_kind_check check (kind in ('child', 'servant'));
  end if;
end $$;

create index if not exists idx_enrollments_kind on public.enrollments(kind);
create unique index if not exists uq_enrollments_servant on public.enrollments(servant_id) where servant_id is not null;

comment on column public.enrollments.kind is 'child = مخدوم · servant = خادم (صف مرآة لتسجيل الخادم — يُدار بالمشغّل sync_servant_mirror_enrollment)';
comment on column public.enrollments.servant_id is 'حساب الخادم الذي يعكسه هذا الصف (kind = servant)';

-- Keep the mirror in sync with the servant enrollment
create or replace function public.sync_servant_mirror_enrollment()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  m   public.enrollments%rowtype;
  cur public.servant_enrollments%rowtype;
begin
  if tg_op = 'DELETE' then
    delete from public.enrollments where servant_id = old.id;
    return old;
  end if;

  -- Re-read the live row: other AFTER triggers (auto_person_for_servant) may have
  -- already updated it (person_id) in a nested statement, leaving NEW stale.
  select * into cur from public.servant_enrollments where id = new.id;
  if not found then
    return new;
  end if;

  -- a mirror needs a person + a COMPLETE scope + a live account
  if cur.person_id is null or cur.church_id is null or cur.service_id is null or cur.class_id is null
     or cur.status not in ('approved', 'suspended') then
    delete from public.enrollments where servant_id = cur.id;
    return new;
  end if;

  select * into m from public.enrollments where servant_id = cur.id;
  if found then
    if m.person_id <> cur.person_id or m.church_id <> cur.church_id
       or m.service_id <> cur.service_id or m.class_id <> cur.class_id then
      begin
        update public.enrollments
           set person_id = cur.person_id, church_id = cur.church_id,
               service_id = cur.service_id, class_id = cur.class_id
         where id = m.id;
      exception when unique_violation then
        -- the person already has a row in the target class → adopt it
        delete from public.enrollments where id = m.id;
        update public.enrollments set kind = 'servant', servant_id = cur.id
         where person_id = cur.person_id and class_id = cur.class_id;
      end;
    end if;
  else
    insert into public.enrollments (person_id, church_id, service_id, class_id, kind, servant_id, created_by, edited_by)
    values (cur.person_id, cur.church_id, cur.service_id, cur.class_id, 'servant', cur.id,
            coalesce(cur.approved_by, cur.id), coalesce(cur.approved_by, cur.id))
    on conflict (person_id, class_id) do update set kind = 'servant', servant_id = excluded.servant_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_sync_servant_mirror_enrollment on public.servant_enrollments;
create trigger trg_sync_servant_mirror_enrollment
after insert or update of person_id, church_id, service_id, class_id, status or delete
on public.servant_enrollments
for each row execute function public.sync_servant_mirror_enrollment();

-- Backfill the existing servants
insert into public.enrollments (person_id, church_id, service_id, class_id, kind, servant_id, created_by, edited_by)
select s.person_id, s.church_id, s.service_id, s.class_id, 'servant', s.id,
       coalesce(s.approved_by, s.id), coalesce(s.approved_by, s.id)
  from public.servant_enrollments s
 where s.person_id is not null and s.church_id is not null and s.service_id is not null and s.class_id is not null
   and s.status in ('approved', 'suspended')
   and not exists (select 1 from public.enrollments e where e.servant_id = s.id)
on conflict (person_id, class_id) do update set kind = 'servant', servant_id = excluded.servant_id;

-- Home counters: children only
create or replace function public.dashboard_counts(p_today_start timestamptz)
returns table (
  persons bigint, enrollments bigint, today_attendance bigint,
  pending_servants bigint, churches bigint, services bigint, classes bigint)
language sql stable security invoker set search_path = public as $$
  select
    (select count(distinct person_id) from public.enrollments where kind = 'child'),
    (select count(*) from public.enrollments where kind = 'child'),
    (select count(*) from public.attendance_log where created_at >= p_today_start),
    (select count(*) from public.servant_enrollments where status = 'pending'),
    (select count(*) from public.churches),
    (select count(*) from public.services),
    (select count(*) from public.classes)
$$;

-- ---------------------------------------------------------------------
-- A2. STATISTICS RPCs — same bodies as 0020 + `p_kind` (child | servant | all)
-- ---------------------------------------------------------------------
-- ---------------------------------------------------------------------
-- 1. Headline KPIs of the scope (all time)
-- ---------------------------------------------------------------------
drop function if exists public.stats_scope_summary(uuid, uuid, uuid);
create or replace function public.stats_scope_summary(
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  enrollments      bigint,   -- إجمالي التسجيلات
  persons          bigint,   -- إجمالي المخدومين (distinct persons)
  males            bigint,
  females          bigint,
  total_attendance bigint,   -- sum(enrollments.attendance_count)
  total_points     bigint,   -- sum(enrollments.points) — current balance
  attendance_points bigint,  -- points that came with attendance (all time)
  cause_points_added bigint, -- positive cause deltas (all time)
  cause_points_removed bigint, -- abs(negative cause deltas) (all time)
  events_count     bigint,   -- events applying to the scope
  causes_count     bigint,   -- causes applying to the scope
  classes_count    bigint,   -- distinct classes with enrollments in scope
  first_attendance date,     -- earliest attended_on in scope
  last_attendance  date      -- latest attended_on in scope
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id,
           e.attendance_count, e.points
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  )
  select
    (select count(*) from sc),
    (select count(distinct person_id) from sc),
    (select count(distinct sc.person_id) from sc join public.persons p on p.id = sc.person_id where p.gender = 'male'),
    (select count(distinct sc.person_id) from sc join public.persons p on p.id = sc.person_id where p.gender = 'female'),
    (select coalesce(sum(attendance_count), 0) from sc),
    (select coalesce(sum(points), 0) from sc),
    (select coalesce(sum(a.points_delta), 0) from public.attendance_log a join sc on sc.id = a.enrollment_id),
    (select coalesce(sum(l.delta), 0) from public.points_log l join sc on sc.id = l.enrollment_id where l.delta > 0),
    (select coalesce(-sum(l.delta), 0) from public.points_log l join sc on sc.id = l.enrollment_id where l.delta < 0),
    (select count(*) from public.events ev
      where (p_church  is null or ev.church_id = p_church)
        and (p_service is null or ev.service_id is null or ev.service_id = p_service)
        and (p_class   is null or ev.class_id   is null or ev.class_id   = p_class)),
    (select count(*) from public.causes ca
      where (p_church  is null or ca.church_id = p_church)
        and (p_service is null or ca.service_id is null or ca.service_id = p_service)
        and (p_class   is null or ca.class_id   is null or ca.class_id   = p_class)),
    (select count(distinct class_id) from sc),
    (select min(a.attended_on) from public.attendance_log a join sc on sc.id = a.enrollment_id),
    (select max(a.attended_on) from public.attendance_log a join sc on sc.id = a.enrollment_id)
$$;

-- ---------------------------------------------------------------------
-- 2. KPIs of ONE selected day
-- ---------------------------------------------------------------------
drop function if exists public.stats_day_summary(date, uuid, uuid, uuid);
create or replace function public.stats_day_summary(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  attendance        bigint,  -- attendance rows on the day
  attendees         bigint,  -- distinct persons who attended
  events_attended   bigint,  -- distinct events with ≥1 attendance
  attendance_points bigint,  -- points granted with attendance
  cause_points_added   bigint,
  cause_points_removed bigint,
  cause_entries     bigint,  -- points_log rows on the day
  causes_used       bigint,  -- distinct causes used
  scope_persons     bigint   -- persons in scope (denominator for %)
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  att as (
    select a.*, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  ),
  pts as (
    select l.*
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date = p_day
  )
  select
    (select count(*) from att),
    (select count(distinct person_id) from att),
    (select count(distinct event_id) from att where event_id is not null),
    (select coalesce(sum(points_delta), 0) from att),
    (select coalesce(sum(delta), 0) from pts where delta > 0),
    (select coalesce(-sum(delta), 0) from pts where delta < 0),
    (select count(*) from pts),
    (select count(distinct cause_id) from pts where cause_id is not null),
    (select count(distinct person_id) from sc)
$$;

-- ---------------------------------------------------------------------
-- 3. Attendance on a day, grouped by EVENT (sorted by event)
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_by_event(date, uuid, uuid, uuid);
create or replace function public.stats_attendance_by_event(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  event_id      uuid,
  event_name    text,
  church_id     uuid,     -- to disambiguate same-named events across churches
  event_scope   text,     -- 'church' | 'service' | 'class'
  attendance    bigint,   -- rows
  attendees     bigint,   -- distinct persons
  points        bigint,   -- sum(points_delta)
  eligible      bigint,   -- enrollments in scope the event applies to
  first_at      timestamptz,
  last_at       timestamptz
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  att as (
    select a.event_id, a.points_delta, a.created_at, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  ),
  grp as (
    select event_id,
           count(*)::bigint as attendance,
           count(distinct person_id)::bigint as attendees,
           coalesce(sum(points_delta), 0)::bigint as points,
           min(created_at) as first_at,
           max(created_at) as last_at
      from att group by event_id
  )
  select g.event_id,
         coalesce(ev.name, 'بدون مناسبة') as event_name,
         ev.church_id,
         case when ev.id is null then 'church'
              when ev.class_id is not null then 'class'
              when ev.service_id is not null then 'service'
              else 'church' end as event_scope,
         g.attendance, g.attendees, g.points,
         (select count(*) from sc
           where ev.id is not null
             and sc.church_id = ev.church_id
             and (ev.service_id is null or sc.service_id = ev.service_id)
             and (ev.class_id   is null or sc.class_id   = ev.class_id))::bigint as eligible,
         g.first_at, g.last_at
    from grp g
    left join public.events ev on ev.id = g.event_id
   order by event_name, g.event_id
$$;

-- ---------------------------------------------------------------------
-- 4. Points granted on a day, grouped by CAUSE (sorted by cause)
-- ---------------------------------------------------------------------
drop function if exists public.stats_points_by_cause(date, uuid, uuid, uuid);
create or replace function public.stats_points_by_cause(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  cause_id      uuid,
  cause_name    text,
  church_id     uuid,
  cause_scope   text,
  entries       bigint,   -- points_log rows
  recipients    bigint,   -- distinct persons
  added         bigint,   -- sum of positive deltas
  removed       bigint,   -- abs(sum of negative deltas)
  net           bigint,   -- added - removed
  first_at      timestamptz,
  last_at       timestamptz
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  pts as (
    select l.cause_id, l.delta, l.created_at, sc.person_id
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date = p_day
  ),
  grp as (
    select cause_id,
           count(*)::bigint as entries,
           count(distinct person_id)::bigint as recipients,
           coalesce(sum(case when delta > 0 then delta else 0 end), 0)::bigint as added,
           coalesce(sum(case when delta < 0 then -delta else 0 end), 0)::bigint as removed,
           coalesce(sum(delta), 0)::bigint as net,
           min(created_at) as first_at,
           max(created_at) as last_at
      from pts group by cause_id
  )
  select g.cause_id,
         coalesce(ca.name, 'بدون سبب') as cause_name,
         ca.church_id,
         case when ca.id is null then 'church'
              when ca.class_id is not null then 'class'
              when ca.service_id is not null then 'service'
              else 'church' end as cause_scope,
         g.entries, g.recipients, g.added, g.removed, g.net, g.first_at, g.last_at
    from grp g
    left join public.causes ca on ca.id = g.cause_id
   order by cause_name, g.cause_id
$$;

-- ---------------------------------------------------------------------
-- 5. Attendance TIMELINE — per bucket × event over a period
--    p_bucket: 'day' | 'week' | 'month'. Buckets are Cairo calendar
--    days / ISO weeks (Monday start) / months, returned as the bucket's
--    first day. The client fills empty buckets with zero.
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_timeline(date, date, text, uuid, uuid, uuid);
create or replace function public.stats_attendance_timeline(
  p_from date, p_to date, p_bucket text default 'day',
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  bucket      date,
  event_id    uuid,
  event_name  text,
  church_id   uuid,
  attendance  bigint,
  attendees   bigint,
  points      bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  att as (
    select case lower(coalesce(p_bucket, 'day'))
             when 'week'  then date_trunc('week',  a.attended_on::timestamp)::date
             when 'month' then date_trunc('month', a.attended_on::timestamp)::date
             else a.attended_on
           end as bucket,
           a.event_id, a.points_delta, sc.person_id
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on between p_from and p_to
  )
  select att.bucket, att.event_id,
         coalesce(ev.name, 'بدون مناسبة') as event_name,
         ev.church_id,
         count(*)::bigint,
         count(distinct att.person_id)::bigint,
         coalesce(sum(att.points_delta), 0)::bigint
    from att
    left join public.events ev on ev.id = att.event_id
   group by att.bucket, att.event_id, ev.name, ev.church_id
   order by att.bucket, event_name
$$;

-- ---------------------------------------------------------------------
-- 6. Points TIMELINE — per bucket × cause over a period
-- ---------------------------------------------------------------------
drop function if exists public.stats_points_timeline(date, date, text, uuid, uuid, uuid);
create or replace function public.stats_points_timeline(
  p_from date, p_to date, p_bucket text default 'day',
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  bucket      date,
  cause_id    uuid,
  cause_name  text,
  church_id   uuid,
  entries     bigint,
  added       bigint,
  removed     bigint,
  net         bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  pts as (
    select (l.created_at at time zone 'Africa/Cairo')::date as day, l.cause_id, l.delta
      from public.points_log l join sc on sc.id = l.enrollment_id
     where (l.created_at at time zone 'Africa/Cairo')::date between p_from and p_to
  ),
  b as (
    select case lower(coalesce(p_bucket, 'day'))
             when 'week'  then date_trunc('week',  day::timestamp)::date
             when 'month' then date_trunc('month', day::timestamp)::date
             else day
           end as bucket, cause_id, delta
      from pts
  )
  select b.bucket, b.cause_id,
         coalesce(ca.name, 'بدون سبب') as cause_name,
         ca.church_id,
         count(*)::bigint,
         coalesce(sum(case when b.delta > 0 then b.delta else 0 end), 0)::bigint,
         coalesce(sum(case when b.delta < 0 then -b.delta else 0 end), 0)::bigint,
         coalesce(sum(b.delta), 0)::bigint
    from b
    left join public.causes ca on ca.id = b.cause_id
   group by b.bucket, b.cause_id, ca.name, ca.church_id
   order by b.bucket, cause_name
$$;

-- ---------------------------------------------------------------------
-- 7. Attendance on a day per CLASS (with % of enrolled)
-- ---------------------------------------------------------------------
drop function if exists public.stats_attendance_by_class(date, uuid, uuid, uuid);
create or replace function public.stats_attendance_by_class(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  class_id     uuid,
  class_name   text,
  service_name text,
  church_name  text,
  enrolled     bigint,
  attendees    bigint,   -- distinct persons attended (any event)
  attendance   bigint,   -- rows
  points       bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.class_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  att as (
    select sc.class_id, sc.person_id, a.points_delta
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  )
  select c.id, c.name, s.name, ch.name,
         (select count(*) from sc where sc.class_id = c.id)::bigint,
         (select count(distinct person_id) from att where att.class_id = c.id)::bigint,
         (select count(*) from att where att.class_id = c.id)::bigint,
         (select coalesce(sum(points_delta), 0) from att where att.class_id = c.id)::bigint
    from public.classes c
    join public.services s on s.id = c.service_id
    join public.churches ch on ch.id = c.church_id
   where c.id in (select distinct class_id from sc)
   order by ch.name, s.name, c.name
$$;

-- ---------------------------------------------------------------------
-- 8. Leaderboard for the scope — by points or by attendance
-- ---------------------------------------------------------------------
drop function if exists public.stats_leaderboard_scoped(text, int, uuid, uuid, uuid);
create or replace function public.stats_leaderboard_scoped(
  p_by text default 'points', p_limit int default 10,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  enrollment_id uuid, person_id uuid, name text, image_url text,
  class_name text, points integer, attendance_count integer)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, p.name, p.image_url, c.name, e.points, e.attendance_count
    from public.enrollments e
    join public.persons p on p.id = e.person_id
    left join public.classes c on c.id = e.class_id
   where (p_church  is null or e.church_id  = p_church)
     and (p_service is null or e.service_id = p_service)
     and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
   order by
     case when lower(coalesce(p_by, 'points')) = 'attendance' then e.attendance_count else e.points end desc,
     case when lower(coalesce(p_by, 'points')) = 'attendance' then e.points else e.attendance_count end desc,
     p.name
   limit greatest(1, least(coalesce(p_limit, 10), 100))
$$;

-- ---------------------------------------------------------------------
-- 9. Weekday profile — attendance by weekday (0=Sun..6=Sat) over a period
-- ---------------------------------------------------------------------
drop function if exists public.stats_weekday_profile(date, date, uuid, uuid, uuid);
create or replace function public.stats_weekday_profile(
  p_from date, p_to date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (weekday int, attendance bigint, days_with_attendance bigint)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  )
  select extract(dow from a.attended_on)::int,
         count(*)::bigint,
         count(distinct a.attended_on)::bigint
    from public.attendance_log a join sc on sc.id = a.enrollment_id
   where a.attended_on between p_from and p_to
   group by 1 order by 1
$$;

grant execute on function public.stats_scope_summary(uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_day_summary(date, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_attendance_by_event(date, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_points_by_cause(date, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_attendance_timeline(date, date, text, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_points_timeline(date, date, text, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_attendance_by_class(date, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_leaderboard_scoped(text, int, uuid, uuid, uuid, text) to authenticated;
grant execute on function public.stats_weekday_profile(date, date, uuid, uuid, uuid, text) to authenticated;

-- =====================================================================
-- B. CHILD CREDENTIALS + SESSIONS (كلمة مرور المخدوم)
-- =====================================================================
create table if not exists public.person_credentials (
  person_id      uuid primary key references public.persons(id) on delete cascade,
  password_hash  text not null,
  set_by         uuid references public.servant_enrollments(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
comment on table public.person_credentials is 'كلمة مرور بوابة المخدوم (bcrypt) — شخص واحد = كلمة مرور واحدة';
alter table public.person_credentials enable row level security;
-- no direct table access: everything goes through the RPCs below
revoke all on public.person_credentials from anon, authenticated;

create table if not exists public.child_sessions (
  id           uuid primary key default gen_random_uuid(),
  person_id    uuid not null references public.persons(id) on delete cascade,
  token_hash   text not null unique,
  remember     boolean not null default false,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  last_seen_at timestamptz not null default now(),
  user_agent   text
);
create index if not exists idx_child_sessions_person on public.child_sessions(person_id);
create index if not exists idx_child_sessions_expires on public.child_sessions(expires_at);
comment on table public.child_sessions is 'جلسات بوابة المخدوم — التوكن مخزَّن كـ sha256؛ 12 ساعة أو 90 يومًا مع «تذكرني»';
alter table public.child_sessions enable row level security;
revoke all on public.child_sessions from anon, authenticated;

-- Does this person have a portal password?
create or replace function public.person_has_password(p_person uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.person_credentials c where c.person_id = p_person)
$$;
grant execute on function public.person_has_password(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- The resolver every child_portal_* RPC uses. Accepts a SESSION TOKEN only.
-- STABLE (read-only) so the many STABLE portal RPCs can keep calling it;
-- the sliding «remember me» extension happens in child_session_touch().
-- ---------------------------------------------------------------------
create or replace function public.child_portal_person(p_national_id text)
returns public.persons language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v public.persons;
  s public.child_sessions;
begin
  if nullif(trim(coalesce(p_national_id, '')), '') is null then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;
  -- the parameter is now a SESSION TOKEN (issued by child_login); a raw code
  -- never matches a stored hash so it simply ends up as «session_expired»
  select * into s from public.child_sessions
   where token_hash = encode(digest(trim(p_national_id), 'sha256'), 'hex');
  if not found or s.expires_at < now() then
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  select * into v from public.persons where id = s.person_id;
  if not found then
    raise exception 'unknown_code' using errcode = 'P0002';
  end if;
  return v;
end $$;
revoke all on function public.child_portal_person(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- child_login(code, password, remember) → { token, expires_at, person_id }
-- ---------------------------------------------------------------------
create or replace function public.child_login(p_code text, p_password text, p_remember boolean default false, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  c public.person_credentials;
  v_token text;
  v_exp timestamptz;
begin
  if nullif(trim(coalesce(p_code, '')), '') is null then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into p from public.persons where national_id = trim(p_code);
  if not found then raise exception 'unknown_code' using errcode = 'P0002'; end if;
  -- a person that is only a servant (no child enrollment) can't use the portal
  if not exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child') then
    raise exception 'unknown_code' using errcode = 'P0002';
  end if;
  select * into c from public.person_credentials where person_id = p.id;
  if not found then raise exception 'no_password' using errcode = 'P0009'; end if;
  if coalesce(p_password, '') = '' or c.password_hash <> crypt(p_password, c.password_hash) then
    perform pg_sleep(0.25);   -- slow down brute force a little
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_exp := case when coalesce(p_remember, false) then now() + interval '90 days' else now() + interval '12 hours' end;
  insert into public.child_sessions (person_id, token_hash, remember, expires_at, user_agent)
  values (p.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, false), v_exp, left(p_user_agent, 300));
  -- housekeeping
  delete from public.child_sessions where expires_at < now() - interval '1 day';

  return jsonb_build_object('token', v_token, 'expires_at', v_exp, 'person_id', p.id, 'remember', coalesce(p_remember, false));
end $$;
grant execute on function public.child_login(text, text, boolean, text) to anon, authenticated;

create or replace function public.child_logout(p_token text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if nullif(trim(coalesce(p_token, '')), '') is null then return; end if;
  delete from public.child_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
end $$;
grant execute on function public.child_logout(text) to anon, authenticated;

-- Called by the portal on boot / when the tab becomes visible: validates the
-- session, refreshes last_seen and extends a «remember me» session.
create or replace function public.child_session_touch(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare s public.child_sessions;
begin
  if p_token is null or length(trim(p_token)) < 20 then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into s from public.child_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
  if not found then raise exception 'session_expired' using errcode = 'P0002'; end if;
  if s.expires_at < now() then
    delete from public.child_sessions where id = s.id;
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  update public.child_sessions
     set last_seen_at = now(),
         expires_at = case when remember then greatest(expires_at, now() + interval '90 days') else expires_at end
   where id = s.id
   returning * into s;
  return jsonb_build_object('person_id', s.person_id, 'expires_at', s.expires_at, 'remember', s.remember);
end $$;
grant execute on function public.child_session_touch(text) to anon, authenticated;

-- The child changes his own password (current one required)
create or replace function public.child_change_password(p_token text, p_current text, p_new text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  c public.person_credentials;
begin
  p := public.child_portal_person(p_token);
  if length(coalesce(p_new, '')) < 6 then raise exception 'weak_password' using errcode = 'P0001'; end if;
  select * into c from public.person_credentials where person_id = p.id;
  if not found or c.password_hash <> crypt(coalesce(p_current, ''), c.password_hash) then
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  update public.person_credentials
     set password_hash = crypt(p_new, gen_salt('bf', 10)), updated_at = now()
   where person_id = p.id;
  -- every OTHER session is closed
  delete from public.child_sessions
   where person_id = p.id
     and token_hash <> encode(digest(trim(p_token), 'sha256'), 'hex');
end $$;
grant execute on function public.child_change_password(text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- D. A servant sets / resets the password of a person he can access
--    (children page → تعديل البيانات → «إعادة تعيين كلمة المرور», and the
--    add-child form). Servants' own accounts are handled by Supabase Auth.
-- ---------------------------------------------------------------------
create or replace function public.admin_set_child_password(p_person uuid, p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if not (public.is_owner() or public.can_access_person(p_person)
          or exists (select 1 from public.persons x where x.id = p_person and x.created_by = auth.uid())) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  insert into public.person_credentials (person_id, password_hash, set_by)
  values (p_person, crypt(p_password, gen_salt('bf', 10)), auth.uid())
  on conflict (person_id) do update
    set password_hash = excluded.password_hash, set_by = auth.uid(), updated_at = now();
  delete from public.child_sessions where person_id = p_person;   -- force re-login
end $$;
revoke all on function public.admin_set_child_password(uuid, text) from public, anon;
grant execute on function public.admin_set_child_password(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- The ADD-CHILD RPC learns an optional password (set right away)
-- ---------------------------------------------------------------------
create or replace function public.add_person_and_enroll(
  p_church uuid,
  p_service uuid,
  p_class uuid,
  p_name text,
  p_national_id text default null,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_image_url text default null,
  p_points integer default 0,
  p_password text default null
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_nid text;
  v_person public.persons%rowtype;
  v_person_created boolean := false;
  v_enrollment_id uuid;
  v_already boolean := false;
begin
  if public.my_role() is null then
    raise exception 'not_approved' using errcode = '42501';
  end if;
  if not public.can_access(p_church, p_service, p_class) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if coalesce(trim(p_name), '') = '' then
    raise exception 'name_required';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender';
  end if;
  if p_password is not null and length(p_password) < 6 then
    raise exception 'weak_password' using errcode = '22023';
  end if;

  v_nid := nullif(trim(p_national_id), '');
  if v_nid is null then
    v_nid := public.new_person_code(p_church, p_service, p_class);
  end if;

  select * into v_person from public.persons where national_id = v_nid;

  if not found then
    insert into public.persons (
      national_id, name, gender, birthdate, phone, address, notes,
      image_url, created_by, edited_by
    ) values (
      v_nid, trim(p_name), p_gender, p_birthdate,
      nullif(trim(coalesce(p_phone, '')), ''),
      nullif(trim(coalesce(p_address, '')), ''),
      nullif(trim(coalesce(p_notes, '')), ''),
      p_image_url, auth.uid(), auth.uid()
    ) returning * into v_person;
    v_person_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = auth.uid(),
      edited_at = now()
    where id = v_person.id;
  end if;

  insert into public.enrollments (person_id, church_id, service_id, class_id, points, created_by, edited_by)
  values (v_person.id, p_church, p_service, p_class, greatest(coalesce(p_points, 0), 0), auth.uid(), auth.uid())
  on conflict (person_id, class_id) do nothing
  returning id into v_enrollment_id;

  if v_enrollment_id is null then
    v_already := true;
    select id into v_enrollment_id from public.enrollments
     where person_id = v_person.id and class_id = p_class;
  end if;

  -- password: set on a NEW person, or when the person has none yet
  if p_password is not null and (v_person_created or not public.person_has_password(v_person.id)) then
    insert into public.person_credentials (person_id, password_hash, set_by)
    values (v_person.id, crypt(p_password, gen_salt('bf', 10)), auth.uid())
    on conflict (person_id) do nothing;
  end if;

  return jsonb_build_object(
    'person_id', v_person.id,
    'enrollment_id', v_enrollment_id,
    'national_id', v_nid,
    'person_created', v_person_created,
    'already_enrolled', v_already,
    'has_password', public.person_has_password(v_person.id)
  );
end $$;

-- =====================================================================
-- C. CHILD JOIN REQUESTS (طلبات انضمام المخدومين — /child/signup)
-- =====================================================================
create table if not exists public.child_join_requests (
  id             uuid primary key default gen_random_uuid(),
  code           text not null,                     -- the card code (typed / scanned / generated)
  name           text not null,
  gender         text check (gender in ('male', 'female')),
  birthdate      date,
  phone          text,
  address        text,
  notes          text,
  image_url      text,
  password_hash  text not null,
  church_id      uuid references public.churches(id) on delete cascade,
  service_id     uuid references public.services(id) on delete cascade,
  class_id       uuid references public.classes(id) on delete cascade,
  status         text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decision_note  text,
  decided_by     uuid references public.servant_enrollments(id) on delete set null,
  decided_at     timestamptz,
  person_id      uuid references public.persons(id) on delete set null,   -- filled on approval
  enrollment_id  uuid references public.enrollments(id) on delete set null,
  created_at     timestamptz not null default now()
);
create index if not exists idx_cjr_status_created on public.child_join_requests(status, created_at desc);
create index if not exists idx_cjr_scope on public.child_join_requests(church_id, service_id, class_id);
create unique index if not exists uq_cjr_pending_code on public.child_join_requests(code) where status = 'pending';
comment on table public.child_join_requests is 'طلبات انضمام المخدومين من صفحة «إنشاء حساب مخدوم» — يوافق عليها الخدام من إدارة المخدومين ← الطلبات';

alter table public.child_join_requests enable row level security;
alter table public.child_join_requests replica identity full;

-- Who sees a request? Whoever can access its desired scope (class servant of
-- that class, service manager, church manager, owner). Requests with no scope
-- at all are for the owner / church managers.
drop policy if exists cjr_select on public.child_join_requests;
create policy cjr_select on public.child_join_requests for select to authenticated using (
  (select public.is_owner())
  or (church_id is not null and public.can_access(church_id, service_id, class_id))
);
drop policy if exists cjr_delete on public.child_join_requests;
create policy cjr_delete on public.child_join_requests for delete to authenticated using (
  (select public.is_owner())
  or (church_id is not null and public.can_access(church_id, service_id, class_id))
);
-- the password hash never leaves the database
revoke all on public.child_join_requests from anon;
revoke all on public.child_join_requests from authenticated;
grant select (id, code, name, gender, birthdate, phone, address, notes, image_url, church_id, service_id, class_id,
              status, decision_note, decided_by, decided_at, person_id, enrollment_id, created_at),
      delete on public.child_join_requests to authenticated;

do $$
begin
  alter publication supabase_realtime add table public.child_join_requests;
exception when duplicate_object then null;
end $$;

-- Step «الكود» of the child signup: is this code known? (same exposure as
-- signup_lookup_code for servants — whoever holds the card)
create or replace function public.child_signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'exists', exists (select 1 from public.persons p where p.national_id = trim(p_code)),
      'has_password', exists (select 1 from public.persons p join public.person_credentials c on c.person_id = p.id
                               where p.national_id = trim(p_code)),
      'pending', exists (select 1 from public.child_join_requests r where r.code = trim(p_code) and r.status = 'pending'),
      'name', (select p.name from public.persons p where p.national_id = trim(p_code) limit 1)
    )
  end
$$;
grant execute on function public.child_signup_lookup_code(text) to anon, authenticated;

-- The signup itself → a PENDING request
create or replace function public.child_signup(
  p_code text,
  p_name text,
  p_password text,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_image_url text default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid;
begin
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if p_church is null then raise exception 'church_required' using errcode = '22023'; end if;
  if p_service is not null and not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and (p_service is null
      or not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  -- a code that already has a portal password = an existing account
  if exists (select 1 from public.persons p join public.person_credentials c on c.person_id = p.id where p.national_id = v_code) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  if exists (select 1 from public.child_join_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;

  insert into public.child_join_requests
    (code, name, gender, birthdate, phone, address, notes, image_url, password_hash, church_id, service_id, class_id)
  values
    (v_code, trim(p_name), p_gender, p_birthdate,
     nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
     nullif(trim(coalesce(p_notes, '')), ''), p_image_url,
     crypt(p_password, gen_salt('bf', 10)), p_church, p_service, p_class)
  returning id into v_id;

  return jsonb_build_object('request_id', v_id, 'code', v_code);
end $$;
grant execute on function public.child_signup(text, text, text, text, date, text, text, text, text, uuid, uuid, uuid) to anon, authenticated;

-- Polling from the signup success screen: pending / approved / rejected
create or replace function public.child_signup_status(p_request uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('status', r.status, 'decision_note', r.decision_note, 'code', r.code)
    from public.child_join_requests r where r.id = p_request
$$;
grant execute on function public.child_signup_status(uuid) to anon, authenticated;

-- Pending count for the badge (scoped by RLS)
create or replace function public.pending_child_join_requests_count()
returns integer language sql stable security invoker set search_path = public as $$
  select count(*)::int from public.child_join_requests where status = 'pending'
$$;
grant execute on function public.pending_child_join_requests_count() to authenticated;

-- Approve / reject. On approval the reviewer may fix the scope (the class
-- is REQUIRED); the person is upserted by code, the enrollment created and
-- the password moved into person_credentials.
create or replace function public.review_child_join_request(
  p_request uuid,
  p_approve boolean,
  p_note text default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  r public.child_join_requests;
  v_church uuid; v_service uuid; v_class uuid;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_enr uuid;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  select * into r from public.child_join_requests where id = p_request;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
  if not (public.is_owner() or (r.church_id is not null and public.can_access(r.church_id, r.service_id, r.class_id))) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not p_approve then
    update public.child_join_requests
       set status = 'rejected', decision_note = nullif(trim(coalesce(p_note, '')), ''),
           decided_by = auth.uid(), decided_at = now()
     where id = r.id;
    return jsonb_build_object('status', 'rejected');
  end if;

  v_church := coalesce(p_church, r.church_id);
  v_service := coalesce(p_service, r.service_id);
  v_class := coalesce(p_class, r.class_id);
  if v_church is null or v_service is null or v_class is null then
    raise exception 'scope_required' using errcode = '22023';
  end if;
  if not exists (select 1 from public.classes c where c.id = v_class and c.service_id = v_service and c.church_id = v_church) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  if not public.can_access(v_church, v_service, v_class) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- person (upsert by code — typed data fills the blanks)
  select * into v_person from public.persons where national_id = r.code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (r.code, r.name, r.gender, r.birthdate, r.phone, r.address, r.notes, r.image_url, auth.uid(), auth.uid())
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, r.gender),
      birthdate = coalesce(birthdate, r.birthdate),
      phone     = coalesce(phone, r.phone),
      address   = coalesce(address, r.address),
      notes     = coalesce(notes, r.notes),
      image_url = coalesce(image_url, r.image_url),
      edited_by = auth.uid(), edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  insert into public.enrollments (person_id, church_id, service_id, class_id, created_by, edited_by)
  values (v_person.id, v_church, v_service, v_class, auth.uid(), auth.uid())
  on conflict (person_id, class_id) do nothing
  returning id into v_enr;
  if v_enr is null then
    select id into v_enr from public.enrollments where person_id = v_person.id and class_id = v_class;
  end if;

  insert into public.person_credentials (person_id, password_hash, set_by)
  values (v_person.id, r.password_hash, auth.uid())
  on conflict (person_id) do update set password_hash = excluded.password_hash, set_by = auth.uid(), updated_at = now();

  update public.child_join_requests
     set status = 'approved', decision_note = nullif(trim(coalesce(p_note, '')), ''),
         decided_by = auth.uid(), decided_at = now(),
         church_id = v_church, service_id = v_service, class_id = v_class,
         person_id = v_person.id, enrollment_id = v_enr
   where id = r.id;

  return jsonb_build_object('status', 'approved', 'person_id', v_person.id, 'person_created', v_created, 'enrollment_id', v_enr);
end $$;
revoke all on function public.review_child_join_request(uuid, boolean, text, uuid, uuid, uuid) from public, anon;
grant execute on function public.review_child_join_request(uuid, boolean, text, uuid, uuid, uuid) to authenticated;

-- =====================================================================
-- Audience / roster helpers that enumerate a scope: children ONLY.
-- Servant mirror rows must not be counted as recipients, exam candidates,
-- birthday children, leaderboard members, …
-- =====================================================================
-- stats_summary (from 0019) — children only
create or replace function public.stats_summary(
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (enrollments bigint, persons bigint, total_attendance bigint, total_points bigint)
language sql stable security invoker set search_path = public as $$
  select count(*)::bigint,
         count(distinct person_id)::bigint,
         coalesce(sum(attendance_count), 0)::bigint,
         coalesce(sum(points), 0)::bigint
    from public.enrollments
   where kind = 'child'
     and (p_church  is null or church_id  = p_church)
     and (p_service is null or service_id = p_service)
     and (p_class   is null or class_id   = p_class)
$$;

-- stats_leaderboard (from 0019) — children only
create or replace function public.stats_leaderboard(
  p_limit int default 10,
  p_church uuid default null, p_service uuid default null, p_class uuid default null)
returns table (enrollment_id uuid, person_id uuid, name text, points integer, attendance_count integer)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, p.name, e.points, e.attendance_count
    from public.enrollments e
    join public.persons p on p.id = e.person_id
   where e.kind = 'child'
     and (p_church  is null or e.church_id  = p_church)
     and (p_service is null or e.service_id = p_service)
     and (p_class   is null or e.class_id   = p_class)
   order by e.points desc, p.name
   limit greatest(1, least(p_limit, 100))
$$;

-- chat_audience_count (from 0029) — children only
create or replace function public.chat_audience_count(p_target text, p_church uuid, p_service uuid, p_class uuid)
returns integer language sql stable security definer set search_path = public as $$
  select case
    when not public.module_visible('messages') or not public.scope_contains(p_church, p_service, p_class) then 0
    when p_target = 'staff' then (
      select count(*)::int from public.profiles t
       where t.status = 'approved' and t.id <> auth.uid() and t.role <> 'owner'
         and (p_church  is null or t.church_id  = p_church)
         and (p_service is null or t.service_id = p_service)
         and (p_class   is null or t.class_id   = p_class))
    else (
      select count(*)::int from public.enrollments e
       where e.kind = 'child'
         and (p_church  is null or e.church_id  = p_church)
         and (p_service is null or e.service_id = p_service)
         and (p_class   is null or e.class_id   = p_class))
  end
$$;

-- online_class_live_stats (from 0030) — children only
create or replace function public.online_class_live_stats(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c   public.online_classes;
  s   record;
  v_from timestamptz; v_to timestamptz; v_span integer;
  v_rows jsonb;
  v_checks integer;
begin
  if auth.uid() is null or not public.module_visible('online') then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  select * into c from public.online_classes where id = p_class;
  if not found then
    raise exception 'class_not_found' using errcode = 'P0002';
  end if;
  if not public.scope_overlaps(c.church_id, c.service_id, c.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  select * into v_from, v_to, v_span from public.online_class_span(c);
  select count(*) into v_checks from public.online_class_checks where class_id = c.id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'participant_id', pt.id,
           'enrollment_id', pt.enrollment_id,
           'person_id', pt.person_id,
           'name', p.name,
           'image_url', p.image_url,
           'national_id', p.national_id,
           'class_name', cl.name,
           'first_joined_at', pt.first_joined_at,
           'last_seen_at', pt.last_seen_at,
           'left_at', pt.left_at,
           'online', (pt.left_at is null and pt.last_seen_at >= now() - interval '90 seconds' and c.status = 'live'),
           'sessions_count', pt.sessions_count,
           'seconds', e.o_seconds,
           'percent', e.o_percent,
           'checks_ok', pt.checks_ok,
           'checks_late', pt.checks_late,
           'checks_total', e.o_checks_total,
           'answers_count', pt.answers_count,
           'correct_count', pt.correct_count,
           'messages_count', pt.messages_count,
           'rule_present', e.o_rule_present,
           'status', e.o_status,
           'override_status', pt.override_status,
           'final_status', pt.final_status,
           'attendance_log_id', pt.attendance_log_id
         ) order by p.name), '[]'::jsonb)
    into v_rows
    from public.online_class_participants pt
    join public.persons p on p.id = pt.person_id
    join public.classes cl on cl.id = pt.room_class_id
    cross join lateral public.online_evaluate(c, pt) e
   where pt.class_id = c.id;

  return jsonb_build_object(
    'class_id', c.id,
    'status', c.status,
    'span_from', v_from, 'span_to', v_to, 'span_seconds', v_span,
    'checks_sent', v_checks,
    'server_now', now(),
    'participants', v_rows,
    'totals', jsonb_build_object(
      'entered', jsonb_array_length(v_rows),
      'online', (select count(*) from jsonb_array_elements(v_rows) r where (r->>'online')::boolean),
      'present', (select count(*) from jsonb_array_elements(v_rows) r where r->>'status' = 'present'),
      'absent',  (select count(*) from jsonb_array_elements(v_rows) r where r->>'status' = 'absent'),
      'eligible', (select count(*) from public.enrollments en
                    where en.kind = 'child' and en.church_id = c.church_id
                      and (c.service_id is null or en.service_id = c.service_id)
                      and (c.class_id is null or en.class_id = c.class_id))
    )
  );
end $$;

-- notif_audience_count (from 0034) — children only
create or replace function public.notif_audience_count(p jsonb)
returns integer language plpgsql stable security definer set search_path = public as $$
declare
  v_kind     text := coalesce(p->>'target_kind', 'class');
  v_aud      text := coalesce(p->>'audience', 'children');
  v_church   uuid := nullif(p->>'church_id', '')::uuid;
  v_service  uuid := nullif(p->>'service_id', '')::uuid;
  v_class    uuid := nullif(p->>'class_id', '')::uuid;
  v_servant  uuid := coalesce(nullif(p->>'target_servant_id', '')::uuid, auth.uid());
  v_ids      uuid[];
  s record;
begin
  if not public.module_visible('notifications') then return 0; end if;
  select * into s from public.my_scope();
  if not found then return 0; end if;
  if p ? 'enrollment_ids' and jsonb_typeof(p->'enrollment_ids') = 'array' then
    select array_agg(distinct x::uuid) into v_ids from jsonb_array_elements_text(p->'enrollment_ids') x;
  end if;

  if v_aud = 'staff' then
    if v_kind = 'all' and s.role <> 'owner' then return 0; end if;
    if v_kind <> 'all' and not public.scope_contains(v_church, v_service, v_class) then return 0; end if;
    return (select count(*)::int from public.notif_staff_in_scope(v_church, v_service, v_class) t where t <> auth.uid());
  end if;

  return (
    select count(*)::int from public.enrollments e
     where e.kind = 'child' and case v_kind
             when 'person' then e.id = any(coalesce(v_ids, '{}'))
               and public.enrollment_visible(e.church_id, e.service_id, e.class_id, s.role, s.church_id, s.service_id, s.class_id)
             when 'group'  then exists (select 1 from public.shepherd_groups g where g.enrollment_id = e.id and g.servant_id = v_servant)
               and public.enrollment_visible(e.church_id, e.service_id, e.class_id, s.role, s.church_id, s.service_id, s.class_id)
             when 'all'    then s.role = 'owner'
             else public.scope_contains(v_church, v_service, v_class)
              and (v_church  is null or e.church_id  = v_church)
              and (v_service is null or e.service_id = v_service)
              and (v_class   is null or e.class_id   = v_class)
           end);
end $$;

-- notif_materialize (from 0034) — children only
create or replace function public.notif_materialize(p_id uuid)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  n public.notifications;
  cnt integer := 0;
begin
  select * into n from public.notifications where id = p_id for update;
  if not found then return 0; end if;
  delete from public.notification_recipients where notification_id = n.id;

  if n.audience = 'staff' then
    insert into public.notification_recipients (notification_id, profile_id, title, body, image_url, link_url)
    select n.id, t, n.title, n.body, n.image_url, n.link_url
      from public.notif_staff_in_scope(n.church_id, n.service_id, n.class_id) t
     where t is distinct from n.created_by;
    get diagnostics cnt = row_count;
  else
    insert into public.notification_recipients (notification_id, enrollment_id, person_id, title, body, image_url, link_url)
    select n.id, e.id, e.person_id, n.title, n.body, n.image_url, n.link_url
      from public.enrollments e
     where e.kind = 'child' and case n.target_kind
             when 'person' then e.id = any(coalesce(n.enrollment_ids, '{}'))
             when 'group'  then exists (select 1 from public.shepherd_groups g where g.enrollment_id = e.id and g.servant_id = n.target_servant_id)
             else (n.church_id  is null or e.church_id  = n.church_id)
              and (n.service_id is null or e.service_id = n.service_id)
              and (n.class_id   is null or e.class_id   = n.class_id)
           end;
    get diagnostics cnt = row_count;
  end if;

  update public.notifications
     set status = case when cnt > 0 then 'sent' else 'failed' end,
         error  = case when cnt > 0 then null else 'no_recipients' end,
         sent_at = now(), recipients_count = cnt
   where id = n.id;
  return cnt;
end $$;

-- notif_fire_scope (from 0034) — children only
create or replace function public.notif_fire_scope(
  p_trigger text, p_church uuid, p_service uuid, p_class uuid, p_vars jsonb default '{}'::jsonb,
  p_default_link text default null, p_ref text default null, p_enrollment_ids uuid[] default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare
  a public.notification_automations;
  vars jsonb;
  n_id uuid;
  fired integer := 0;
  v_title text; v_body text; v_link text;
  v_church uuid; v_service uuid; v_class uuid;
  cnt integer;
begin
  if p_church is null then return 0; end if;
  if not exists (select 1 from public.notification_automations where trigger_key = p_trigger and is_active) then return 0; end if;
  if not public.notif_module_covers(p_church, p_service, p_class) then return 0; end if;
  vars := jsonb_build_object(
            'الكنيسة', (select name from public.churches where id = p_church),
            'الخدمة',  (select name from public.services where id = p_service),
            'الفصل',   (select name from public.classes  where id = p_class),
            'التاريخ', to_char(now() at time zone 'Africa/Cairo', 'YYYY-MM-DD'),
            'الوقت',   to_char(now() at time zone 'Africa/Cairo', 'HH24:MI'))
          || coalesce(p_vars, '{}'::jsonb);

  for a in
    select * from public.notification_automations x
     where x.trigger_key = p_trigger and x.is_active
       and (x.church_id  is null or x.church_id  = p_church)
       and (x.service_id is null or p_service is null or x.service_id = p_service)
       and (x.class_id   is null or p_class   is null or x.class_id   = p_class)
  loop
    if p_ref is not null then
      begin
        insert into public.notification_automation_runs (automation_id, ref_key) values (a.id, p_ref);
      exception when unique_violation then continue; end;
    end if;
    -- effective scope = the narrower of the event's and the automation's
    v_church  := p_church;
    v_service := coalesce(p_service, a.service_id);
    v_class   := coalesce(p_class, a.class_id);
    if v_class is not null and v_service is null then
      select service_id into v_service from public.classes where id = v_class;
    end if;

    v_title := left(public.notif_render(a.title_template, vars), 120);
    v_body  := left(public.notif_render(a.body_template, vars), 1000);
    v_link  := coalesce(public.notif_clean_link(a.link_url), public.notif_clean_link(p_default_link));
    if length(trim(v_title)) = 0 then v_title := a.name; end if;

    insert into public.notifications (church_id, service_id, class_id, title, body, image_url, link_url, target_kind, audience,
                                      enrollment_ids, status, sent_at, source, automation_id, created_by)
    values (v_church, v_service, v_class, v_title, v_body, a.image_url, v_link,
            case when p_enrollment_ids is not null then 'person' when v_class is not null then 'class' when v_service is not null then 'service' else 'church' end,
            case when a.recipient = 'class_servants' then 'staff' else 'children' end,
            p_enrollment_ids, 'sent', now(), 'automation', a.id, null)
    returning id into n_id;

    if a.recipient = 'class_servants' then
      insert into public.notification_recipients (notification_id, profile_id, title, body, image_url, link_url)
      select n_id, t, v_title, v_body, a.image_url, v_link
        from public.notif_staff_in_scope(v_church, v_service, v_class) t;
    else
      insert into public.notification_recipients (notification_id, enrollment_id, person_id, title, body, image_url, link_url)
      select n_id, e.id, e.person_id, v_title, v_body, a.image_url, v_link
        from public.enrollments e
       where e.kind = 'child' and e.church_id = v_church
         and (v_service is null or e.service_id = v_service)
         and (v_class   is null or e.class_id   = v_class)
         and (p_enrollment_ids is null or e.id = any(p_enrollment_ids));
    end if;
    select count(*) into cnt from public.notification_recipients where notification_id = n_id;
    update public.notifications set recipients_count = cnt, status = case when cnt > 0 then 'sent' else 'failed' end,
           error = case when cnt > 0 then null else 'no_recipients' end
     where id = n_id;
    fired := fired + 1;
  end loop;
  return fired;
end $$;

-- result_summary_core (from 0038) — children only
create or replace function public.result_summary_core(p_exam uuid, p_enrollment uuid default null)
returns table (
  enrollment_id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  subjects_total integer, subjects_entered integer, subjects_absent integer, subjects_draft integer,
  total_score numeric, total_full numeric, percent numeric,
  grade_id uuid, passed boolean, status text
) language sql stable security definer set search_path = public as $$
  with x as (select * from public.result_exams where id = p_exam),
  subj as (select s.* from public.result_subjects s where s.exam_id = p_exam),
  tot as (
    select count(*) filter (where not is_bonus)::integer                         as n_subj,
           coalesce(sum(full_degree) filter (where not is_bonus), 0)             as full_sum,
           coalesce(bool_and(weight is not null) filter (where not is_bonus), false)
             and coalesce(sum(weight) filter (where not is_bonus), 0) > 0        as weighted
      from subj
  ),
  enr as (
    select e.id, e.person_id, e.church_id, e.service_id, e.class_id
      from public.enrollments e, x
     where e.kind = 'child' and e.church_id = x.church_id
       and (x.service_id is null or e.service_id = x.service_id)
       and (x.class_id   is null or e.class_id   = x.class_id)
       and (p_enrollment is null or e.id = p_enrollment)
  ),
  r as (
    select r.*, s.full_degree, s.weight, s.is_bonus,
           case when r.percent is null then null else coalesce(r.score, 0) end as eff_score
      from public.exam_results r join subj s on s.id = r.subject_id
     where r.exam_id = p_exam and (p_enrollment is null or r.enrollment_id = p_enrollment)
  ),
  agg as (
    select enr.id as enrollment_id, enr.person_id, enr.church_id, enr.service_id, enr.class_id,
           count(r.id) filter (where not r.is_bonus)::integer                                        as entered,
           count(r.id) filter (where r.status = 'draft')::integer                                    as n_draft,
           count(r.id) filter (where r.status in ('absent', 'excused') and not r.is_bonus)::integer  as n_absent,
           sum(r.eff_score)   filter (where not r.is_bonus)                                          as score_sum,
           sum(r.full_degree) filter (where r.eff_score is not null and not r.is_bonus)              as full_taken,
           coalesce(sum(r.eff_score) filter (where r.is_bonus), 0)                                   as bonus_sum,
           sum(r.percent * r.weight) filter (where r.eff_score is not null and not r.is_bonus)       as wpct_sum,
           sum(r.weight)            filter (where r.eff_score is not null and not r.is_bonus)        as w_taken,
           coalesce(sum(r.percent * coalesce(r.weight, 0) / 100) filter (where r.eff_score is not null and r.is_bonus), 0) as bonus_wpct,
           coalesce(bool_and(r.passed) filter (where r.eff_score is not null and not r.is_bonus), false) as all_passed
      from enr left join r on r.enrollment_id = enr.id
     group by 1, 2, 3, 4, 5
  ),
  calc as (
    select a.*, t.n_subj, t.full_sum,
           case
             when t.weighted and coalesce(a.w_taken, 0) > 0
               then least(100, round(a.wpct_sum / a.w_taken + a.bonus_wpct, 2))
             when coalesce(a.full_taken, 0) > 0
               then least(100, round((a.score_sum + a.bonus_sum) / a.full_taken * 100, 2))
             else null
           end as pct,
           coalesce(x.min_required_subjects, t.n_subj) as required
      from agg a cross join tot t cross join x
  )
  select c.enrollment_id, c.person_id, c.church_id, c.service_id, c.class_id,
         c.n_subj, c.entered, c.n_absent, c.n_draft,
         case when c.entered > 0 then coalesce(c.score_sum, 0) + c.bonus_sum end as total_score,
         c.full_sum as total_full,
         c.pct as percent,
         case when x.grade_overall then public.grade_for_percent(x.grading_system_id, c.pct) end as grade_id,
         case when c.entered = 0 or c.entered < least(c.required, c.n_subj) or c.n_draft > 0 then null
              when c.n_absent >= c.n_subj and c.n_subj > 0 and c.pct is null then false
              else (case x.pass_rule
                      when 'overall'  then c.pct is not null and c.pct >= x.pass_percent
                      when 'subjects' then c.all_passed and c.pct is not null
                      else c.pct is not null and c.pct >= x.pass_percent and c.all_passed
                    end)
         end as passed,
         case
           when c.n_subj = 0 or c.entered = 0                       then 'not_entered'
           when c.n_absent >= c.n_subj                              then 'absent'
           when c.entered < least(c.required, c.n_subj)             then 'incomplete'
           when c.n_draft > 0                                       then 'draft'
           when (case x.pass_rule
                   when 'overall'  then c.pct is not null and c.pct >= x.pass_percent
                   when 'subjects' then c.all_passed and c.pct is not null
                   else c.pct is not null and c.pct >= x.pass_percent and c.all_passed
                 end)                                               then 'passed'
           else 'failed'
         end as status
    from calc c cross join x
$$;

-- birthdays_in_month (from 0028) — children only
create or replace function public.birthdays_in_month(
  p_year integer, p_month integer,
  p_church uuid default null, p_service uuid default null, p_class uuid default null
)
returns table (
  enrollment_id uuid, person_id uuid,
  church_id uuid, service_id uuid, class_id uuid,
  national_id text, name text, birthdate date, gender text, phone text, address text, image_url text,
  points integer, attendance_count integer,
  birth_day integer, birth_month integer,
  turns_age integer,                      -- age he turns in p_year
  greetings jsonb,                        -- [{id, kind, created_at, points, message, recorded_by_name}] of p_year
  gift_points integer,                    -- points gifted in p_year (null = not yet)
  enrollments_count integer               -- how many visible enrollments this person has (in scope)
)
language sql stable security invoker set search_path = public as $$
  with vis as (
    -- one row per person: his first visible enrollment (narrowed by the scope)
    select distinct on (e.person_id)
           e.id as enrollment_id, e.person_id, e.church_id, e.service_id, e.class_id,
           e.points, e.attendance_count,
           count(*) over (partition by e.person_id)::int as enrollments_count
      from public.enrollments e
      join public.persons p on p.id = e.person_id
     where e.kind = 'child' and p.birthdate is not null
       and extract(month from p.birthdate)::int = p_month
       and (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
     order by e.person_id, e.created_at, e.id
  )
  select v.enrollment_id, v.person_id, v.church_id, v.service_id, v.class_id,
         p.national_id, p.name, p.birthdate, p.gender::text, p.phone, p.address, p.image_url,
         v.points, v.attendance_count,
         extract(day from p.birthdate)::int, extract(month from p.birthdate)::int,
         (p_year - extract(year from p.birthdate)::int),
         coalesce((
           select jsonb_agg(jsonb_build_object(
                    'id', g.id, 'kind', g.kind, 'created_at', g.created_at,
                    'points', g.points, 'message', g.message,
                    'recorded_by', g.recorded_by, 'recorded_by_name', pr.full_name)
                  order by g.created_at desc)
             from public.birthday_greetings g
             left join public.profiles pr on pr.id = g.recorded_by
            where g.person_id = v.person_id and g.year = p_year
         ), '[]'::jsonb),
         (select g.points from public.birthday_greetings g
           where g.person_id = v.person_id and g.year = p_year and g.kind = 'gift' limit 1),
         v.enrollments_count
    from vis v
    join public.persons p on p.id = v.person_id
   order by extract(day from p.birthdate), p.name
$$;

-- birthdays_upcoming (from 0028) — children only
create or replace function public.birthdays_upcoming(p_days integer default 7, p_today date default null)
returns table (
  enrollment_id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  name text, phone text, image_url text, birthdate date, next_birthday date, days_left integer, turns_age integer
)
language sql stable security invoker set search_path = public as $$
  with t as (
    select coalesce(p_today, (now() at time zone 'Africa/Cairo')::date) as today
  ),
  vis as (
    select distinct on (e.person_id)
           e.id as enrollment_id, e.person_id, e.church_id, e.service_id, e.class_id
      from public.enrollments e
      join public.persons p on p.id = e.person_id
     where e.kind = 'child' and p.birthdate is not null
     order by e.person_id, e.created_at, e.id
  ),
  nb as (
    select v.*, p.name, p.phone, p.image_url, p.birthdate,
           public.next_birthday(p.birthdate, t.today) as next_birthday, t.today
      from vis v
      join public.persons p on p.id = v.person_id
      cross join t
  )
  select enrollment_id, person_id, church_id, service_id, class_id,
         name, phone, image_url, birthdate, next_birthday,
         (next_birthday - today)::int as days_left,
         (extract(year from next_birthday)::int - extract(year from birthdate)::int) as turns_age
    from nb
   where next_birthday - today between 0 and greatest(p_days, 0)
   order by next_birthday, name
$$;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  0043_stop_enrollments_default_password.sql
-- #####################################################################

-- =====================================================================
-- 0043: STOP (إيقاف) FOR CHILDREN + DEFAULT PASSWORD 000000
--
-- A. enrollments.status ('active' | 'stopped')
--    A STOPPED child keeps his data, his enrollments and his history, but:
--      * no attendance / points can be logged for him (trigger guard on
--        attendance_log + points_log → exception `enrollment_stopped`),
--      * he cannot log in to the portal while every child enrollment of his
--        is stopped (`account_stopped`), live sessions are refused too,
--      * the children page shows him greyed out with a «موقوف» badge.
--    Servants already have `suspended`; their MIRROR enrollment now carries
--    status = 'stopped' while the account is suspended (sync trigger).
--
--    set_enrollments_status(status, ids | church → service → class, kind)
--    stops / re-activates ONE child, a list of children, or a WHOLE class /
--    service / church at once (children, servants or both) — scope-checked
--    with can_access / can_manage_servant. Used by إدارة المخدومين → المخدومين.
--
-- B. DEFAULT PASSWORD = 000000 (`default_password()`)
--    A child who never had a password set logs in with 000000; changing it
--    from the portal requires the old one (000000 counts as the old one).
--    Servant accounts are created with 000000 by default in the add flows
--    (client side); the reset section offers the default with one tap.
--
-- C. lookup_enrollments_by_national_id gains `kind` + `servant_id` + `status`.
-- Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- A. enrollments.status
-- ---------------------------------------------------------------------
alter table public.enrollments
  add column if not exists status text not null default 'active';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'enrollments_status_check') then
    alter table public.enrollments add constraint enrollments_status_check check (status in ('active', 'stopped'));
  end if;
end $$;

create index if not exists idx_enrollments_status on public.enrollments(status) where status = 'stopped';

comment on column public.enrollments.status is
  'active = يعمل · stopped = موقوف (لا حضور ولا نقاط ولا دخول للبوابة) — يُدار من إدارة المخدومين ← المخدومين';

-- Default portal / login password
create or replace function public.default_password()
returns text language sql immutable as $$ select '000000'::text $$;
grant execute on function public.default_password() to anon, authenticated;

-- Guard: nothing can be logged against a stopped enrollment
create or replace function public.guard_stopped_enrollment()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.enrollments e where e.id = new.enrollment_id and e.status = 'stopped') then
    raise exception 'enrollment_stopped' using errcode = 'P0020';
  end if;
  return new;
end $$;

drop trigger if exists trg_attendance_log_guard_stopped on public.attendance_log;
create trigger trg_attendance_log_guard_stopped
before insert on public.attendance_log
for each row execute function public.guard_stopped_enrollment();

drop trigger if exists trg_points_log_guard_stopped on public.points_log;
create trigger trg_points_log_guard_stopped
before insert on public.points_log
for each row execute function public.guard_stopped_enrollment();

-- The servant mirror follows the account: suspended ⇢ stopped
create or replace function public.sync_servant_mirror_enrollment()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  m   public.enrollments%rowtype;
  cur public.servant_enrollments%rowtype;
  v_status text;
begin
  if tg_op = 'DELETE' then
    delete from public.enrollments where servant_id = old.id;
    return old;
  end if;

  -- Re-read the live row: other AFTER triggers (auto_person_for_servant) may have
  -- already updated it (person_id) in a nested statement, leaving NEW stale.
  select * into cur from public.servant_enrollments where id = new.id;
  if not found then
    return new;
  end if;

  -- a mirror needs a person + a COMPLETE scope + a live account
  if cur.person_id is null or cur.church_id is null or cur.service_id is null or cur.class_id is null
     or cur.status not in ('approved', 'suspended') then
    delete from public.enrollments where servant_id = cur.id;
    return new;
  end if;

  v_status := case when cur.status = 'suspended' then 'stopped' else 'active' end;

  select * into m from public.enrollments where servant_id = cur.id;
  if found then
    if m.person_id <> cur.person_id or m.church_id <> cur.church_id
       or m.service_id <> cur.service_id or m.class_id <> cur.class_id then
      begin
        update public.enrollments
           set person_id = cur.person_id, church_id = cur.church_id,
               service_id = cur.service_id, class_id = cur.class_id, status = v_status
         where id = m.id;
      exception when unique_violation then
        -- the person already has a row in the target class → adopt it
        delete from public.enrollments where id = m.id;
        update public.enrollments set kind = 'servant', servant_id = cur.id, status = v_status
         where person_id = cur.person_id and class_id = cur.class_id;
      end;
    elsif m.status <> v_status then
      update public.enrollments set status = v_status where id = m.id;
    end if;
  else
    insert into public.enrollments (person_id, church_id, service_id, class_id, kind, servant_id, status, created_by, edited_by)
    values (cur.person_id, cur.church_id, cur.service_id, cur.class_id, 'servant', cur.id, v_status,
            coalesce(cur.approved_by, cur.id), coalesce(cur.approved_by, cur.id))
    on conflict (person_id, class_id) do update
      set kind = 'servant', servant_id = excluded.servant_id, status = excluded.status;
  end if;
  return new;
end $$;

-- backfill mirrors of currently suspended servants
update public.enrollments e
   set status = 'stopped'
  from public.servant_enrollments s
 where e.servant_id = s.id and s.status = 'suspended' and e.status <> 'stopped';

-- ---------------------------------------------------------------------
-- set_enrollments_status — stop / activate one, many, or a whole scope
--   p_enrollment_ids  → exactly these CHILD rows (scope-checked per row)
--   p_church [→ p_service [→ p_class]] → the whole scope
--   p_kind: 'child' | 'servant' | 'all' (scope mode only)
-- Servants are stopped through their ACCOUNT (status suspended / approved);
-- the mirror row follows automatically.
-- ---------------------------------------------------------------------
create or replace function public.set_enrollments_status(
  p_status text,
  p_enrollment_ids uuid[] default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null,
  p_kind text default 'child'
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_children int := 0;
  v_servants int := 0;
  v_srv_status public.approval_status;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_status not in ('active', 'stopped') then raise exception 'invalid_status' using errcode = '22023'; end if;
  if coalesce(p_kind, 'child') not in ('child', 'servant', 'all') then raise exception 'invalid_kind' using errcode = '22023'; end if;

  -- 1) explicit rows
  if p_enrollment_ids is not null then
    with upd as (
      update public.enrollments e
         set status = p_status, edited_by = auth.uid(), edited_at = now()
       where e.id = any (p_enrollment_ids)
         and e.kind = 'child'
         and e.status <> p_status
         and public.can_access(e.church_id, e.service_id, e.class_id)
      returning 1)
    select count(*) into v_children from upd;
    return jsonb_build_object('children', v_children, 'servants', 0);
  end if;

  -- 2) a whole scope
  if p_church is null then raise exception 'scope_required' using errcode = '22023'; end if;
  if not public.can_access(p_church, p_service, p_class) then raise exception 'forbidden' using errcode = '42501'; end if;

  if coalesce(p_kind, 'child') in ('child', 'all') then
    with upd as (
      update public.enrollments e
         set status = p_status, edited_by = auth.uid(), edited_at = now()
       where e.kind = 'child'
         and e.church_id = p_church
         and (p_service is null or e.service_id = p_service)
         and (p_class   is null or e.class_id   = p_class)
         and e.status <> p_status
      returning 1)
    select count(*) into v_children from upd;
  end if;

  if coalesce(p_kind, 'child') in ('servant', 'all') then
    v_srv_status := case when p_status = 'stopped' then 'suspended'::public.approval_status else 'approved'::public.approval_status end;
    with upd as (
      update public.servant_enrollments s
         set status = v_srv_status
       where s.church_id = p_church
         and (p_service is null or s.service_id = p_service)
         and (p_class   is null or s.class_id   = p_class)
         and s.status in ('approved', 'suspended')
         and s.status <> v_srv_status
         and public.can_manage_servant(s.id)
      returning 1)
    select count(*) into v_servants from upd;
  end if;

  return jsonb_build_object('children', v_children, 'servants', v_servants);
end $$;
revoke all on function public.set_enrollments_status(text, uuid[], uuid, uuid, uuid, text) from public, anon;
grant execute on function public.set_enrollments_status(text, uuid[], uuid, uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- B. Portal login / password change with the DEFAULT password
-- ---------------------------------------------------------------------
create or replace function public.child_login(p_code text, p_password text, p_remember boolean default false, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  c public.person_credentials;
  v_token text;
  v_exp timestamptz;
  v_default boolean := false;
begin
  if nullif(trim(coalesce(p_code, '')), '') is null then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into p from public.persons where national_id = trim(p_code);
  if not found then raise exception 'unknown_code' using errcode = 'P0002'; end if;
  -- a person that is only a servant (no child enrollment) can't use the portal
  if not exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child') then
    raise exception 'unknown_code' using errcode = 'P0002';
  end if;
  -- stopped everywhere → no portal
  if not exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child' and e.status = 'active') then
    raise exception 'account_stopped' using errcode = 'P0011';
  end if;

  select * into c from public.person_credentials where person_id = p.id;
  if not found then
    -- never set → the DEFAULT password applies
    v_default := true;
    if coalesce(p_password, '') <> public.default_password() then
      perform pg_sleep(0.25);
      raise exception 'wrong_password' using errcode = 'P0010';
    end if;
  elsif coalesce(p_password, '') = '' or c.password_hash <> crypt(p_password, c.password_hash) then
    perform pg_sleep(0.25);   -- slow down brute force a little
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_exp := case when coalesce(p_remember, false) then now() + interval '90 days' else now() + interval '12 hours' end;
  insert into public.child_sessions (person_id, token_hash, remember, expires_at, user_agent)
  values (p.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, false), v_exp, left(p_user_agent, 300));
  -- housekeeping
  delete from public.child_sessions where expires_at < now() - interval '1 day';

  return jsonb_build_object('token', v_token, 'expires_at', v_exp, 'person_id', p.id, 'remember', coalesce(p_remember, false),
                            'default_password', v_default);
end $$;
grant execute on function public.child_login(text, text, boolean, text) to anon, authenticated;

-- a stopped child loses his live sessions too
create or replace function public.child_session_touch(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare s public.child_sessions;
begin
  if p_token is null or length(trim(p_token)) < 20 then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into s from public.child_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
  if not found then raise exception 'session_expired' using errcode = 'P0002'; end if;
  if s.expires_at < now() then
    delete from public.child_sessions where id = s.id;
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.enrollments e where e.person_id = s.person_id and e.kind = 'child' and e.status = 'active') then
    delete from public.child_sessions where person_id = s.person_id;
    raise exception 'account_stopped' using errcode = 'P0011';
  end if;
  update public.child_sessions
     set last_seen_at = now(),
         expires_at = case when remember then greatest(expires_at, now() + interval '90 days') else expires_at end
   where id = s.id
   returning * into s;
  return jsonb_build_object('person_id', s.person_id, 'expires_at', s.expires_at, 'remember', s.remember);
end $$;
grant execute on function public.child_session_touch(text) to anon, authenticated;

-- The child changes his own password — the old one is required (000000 when never set)
create or replace function public.child_change_password(p_token text, p_current text, p_new text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  c public.person_credentials;
begin
  p := public.child_portal_person(p_token);
  if length(coalesce(p_new, '')) < 6 then raise exception 'weak_password' using errcode = 'P0001'; end if;
  select * into c from public.person_credentials where person_id = p.id;
  if not found then
    if coalesce(p_current, '') <> public.default_password() then
      raise exception 'wrong_password' using errcode = 'P0010';
    end if;
  elsif c.password_hash <> crypt(coalesce(p_current, ''), c.password_hash) then
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  insert into public.person_credentials (person_id, password_hash, set_by)
  values (p.id, crypt(p_new, gen_salt('bf', 10)), null)
  on conflict (person_id) do update
    set password_hash = excluded.password_hash, updated_at = now();
  -- every OTHER session is closed
  delete from public.child_sessions
   where person_id = p.id
     and token_hash <> encode(digest(trim(p_token), 'sha256'), 'hex');
end $$;
grant execute on function public.child_change_password(text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- C. Scanner lookup: expose kind + servant_id + status
-- ---------------------------------------------------------------------
drop function if exists public.lookup_enrollments_by_national_id(text);
create or replace function public.lookup_enrollments_by_national_id(p_national_id text)
returns table (
  id uuid, person_id uuid, church_id uuid, service_id uuid, class_id uuid,
  attendance_count integer, points integer, created_at timestamptz,
  kind text, servant_id uuid, status text,
  person jsonb)
language sql stable security invoker set search_path = public as $$
  select e.id, e.person_id, e.church_id, e.service_id, e.class_id,
         e.attendance_count, e.points, e.created_at,
         e.kind, e.servant_id, e.status,
         to_jsonb(p) as person
    from public.persons p
    join public.enrollments e on e.person_id = p.id
   where p.national_id = p_national_id
   order by e.created_at
$$;
grant execute on function public.lookup_enrollments_by_national_id(text) to authenticated;



-- #####################################################################
-- ##  0044_backup_restore.sql
-- #####################################################################

-- =====================================================================
-- 0044: BACKUP & RESTORE — النسخ الاحتياطي والاسترجاع
--
-- Settings → النشاط → «النسخ الاحتياطي والاسترجاع» (/settings/backup).
-- OWNER ONLY (or the service role from the scheduler route).
--
-- Everything is done through security-definer RPCs so the browser needs
-- no service key and RLS / statement limits never get in the way:
--
--   backup_tables()                       catalogue of every public table:
--                                         rows · pk · columns · FK parents
--   backup_dump_table(t, offset, limit)   one page of rows as jsonb (pk order)
--   backup_dump_auth_users()              login accounts of the servants
--                                         (id · email · password HASH · meta)
--
--   backup_restore_begin(mode, tables, meta)         → job id
--   backup_restore_stage(job, table, seq, rows)      stage one chunk
--   backup_restore_order(job)                        tables in FK order
--   backup_restore_delete_missing(job, table)        replace mode: rows not
--                                                    in the backup are removed
--   backup_restore_apply_chunk(job, table, seq)      upsert one chunk with the
--                                                    user triggers disabled
--   backup_restore_finish(job, status, error)        close the job
--
-- The restore is driven chunk by chunk from the client (progress bar,
-- every call well under the 8 s limit). Parents are always applied before
-- children (FK order from pg_constraint — no hard-coded list, new tables
-- are picked up automatically). Merge mode = upsert by primary key;
-- replace mode additionally deletes the rows the backup does not contain
-- (cascades follow the FK rules of the schema).
--
-- backup_schedules — النسخ المجدولة (daily / weekly / monthly at an hour,
--   Africa/Cairo), executed by /api/backup/cron (Vercel Cron) which stores
--   the file in the private `backups` bucket and prunes to keep_last.
-- backup_runs      — history (manual · scheduled · restore) with the file
--   path so scheduled files can be downloaded to the device later.
-- Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. Who may use the backup system
-- ---------------------------------------------------------------------
create or replace function public.backup_allowed()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.is_owner(), false)
      or coalesce(auth.role(), '') = 'service_role'
$$;
revoke all on function public.backup_allowed() from public;
grant execute on function public.backup_allowed() to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------
create table if not exists public.backup_schedules (
  id            uuid primary key default gen_random_uuid(),
  name          text not null default 'نسخة مجدولة',
  enabled       boolean not null default true,
  frequency     text not null default 'weekly' check (frequency in ('daily', 'weekly', 'monthly')),
  weekday       smallint not null default 0 check (weekday between 0 and 6),        -- 0 = Sunday (weekly)
  day_of_month  smallint not null default 1 check (day_of_month between 1 and 28),  -- monthly
  hour          smallint not null default 3 check (hour between 0 and 23),          -- Africa/Cairo
  tables        text[],                      -- null = every table
  include_auth  boolean not null default true,
  keep_last     integer not null default 10 check (keep_last between 1 and 100),
  last_run_at   timestamptz,
  last_status   text,
  next_run_at   timestamptz,
  created_by    uuid references public.servant_enrollments(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table if not exists public.backup_runs (
  id            uuid primary key default gen_random_uuid(),
  kind          text not null check (kind in ('manual', 'scheduled', 'restore')),
  schedule_id   uuid references public.backup_schedules(id) on delete set null,
  status        text not null default 'running' check (status in ('running', 'done', 'failed', 'partial')),
  mode          text check (mode in ('merge', 'replace')),           -- restore only
  tables        text[] not null default '{}',
  include_auth  boolean not null default false,
  row_counts    jsonb not null default '{}'::jsonb,                  -- {table: n}
  size_bytes    bigint,
  file_name     text,
  storage_path  text,                                                -- in bucket `backups` (null = downloaded only)
  error         text,
  created_by    uuid references public.servant_enrollments(id) on delete set null,
  created_at    timestamptz not null default now(),
  finished_at   timestamptz
);
create index if not exists idx_backup_runs_created on public.backup_runs (created_at desc);
create index if not exists idx_backup_runs_schedule on public.backup_runs (schedule_id, created_at desc);

-- staging for restores
create table if not exists public.backup_restore_jobs (
  id          uuid primary key default gen_random_uuid(),
  mode        text not null check (mode in ('merge', 'replace')),
  tables      text[] not null,
  meta        jsonb not null default '{}'::jsonb,   -- {columns: {table: [..]}, file: {...}}
  status      text not null default 'staging' check (status in ('staging', 'applying', 'done', 'failed')),
  result      jsonb not null default '{}'::jsonb,
  error       text,
  created_by  uuid,
  created_at  timestamptz not null default now(),
  finished_at timestamptz
);
create table if not exists public.backup_restore_rows (
  job_id     uuid not null references public.backup_restore_jobs(id) on delete cascade,
  table_name text not null,
  seq        integer not null,
  rows       jsonb not null,
  applied    boolean not null default false,
  primary key (job_id, table_name, seq)
);
create table if not exists public.backup_restore_keys (
  job_id     uuid not null references public.backup_restore_jobs(id) on delete cascade,
  table_name text not null,
  key        text not null,
  primary key (job_id, table_name, key)
);

comment on table public.backup_schedules is 'النسخ الاحتياطية المجدولة — تُنفَّذ من /api/backup/cron وتُحفظ في bucket backups';
comment on table public.backup_runs is 'سجل النسخ الاحتياطية والاسترجاعات';
comment on table public.backup_restore_jobs is 'مرحلة الاسترجاع — الملف يُرفع على أجزاء ثم يُطبَّق جدولاً جدولاً';

-- RLS — owner only (the RPCs are security definer anyway)
alter table public.backup_schedules    enable row level security;
alter table public.backup_runs         enable row level security;
alter table public.backup_restore_jobs enable row level security;
alter table public.backup_restore_rows enable row level security;
alter table public.backup_restore_keys enable row level security;

drop policy if exists backup_schedules_owner on public.backup_schedules;
create policy backup_schedules_owner on public.backup_schedules for all
  using ((select public.is_owner())) with check ((select public.is_owner()));
drop policy if exists backup_runs_owner on public.backup_runs;
create policy backup_runs_owner on public.backup_runs for all
  using ((select public.is_owner())) with check ((select public.is_owner()));
drop policy if exists backup_restore_jobs_owner on public.backup_restore_jobs;
create policy backup_restore_jobs_owner on public.backup_restore_jobs for select
  using ((select public.is_owner()));
-- staging rows / keys: no direct access at all (RPC only)

-- touch updated_at + next_run_at
create or replace function public.backup_next_run(
  p_frequency text, p_weekday int, p_day_of_month int, p_hour int, p_from timestamptz default now()
) returns timestamptz language plpgsql stable as $$
declare
  tz constant text := 'Africa/Cairo';
  local_now timestamp := p_from at time zone tz;
  d date := local_now::date;
  candidate timestamp;
  i int;
begin
  if p_frequency = 'daily' then
    candidate := d + make_interval(hours => p_hour);
    if candidate <= local_now then candidate := candidate + interval '1 day'; end if;
  elsif p_frequency = 'weekly' then
    -- next date with extract(dow) = p_weekday (0 = Sunday) at p_hour
    for i in 0..7 loop
      candidate := (d + i) + make_interval(hours => p_hour);
      exit when extract(dow from (d + i))::int = p_weekday and candidate > local_now;
    end loop;
  else -- monthly
    candidate := make_timestamp(extract(year from d)::int, extract(month from d)::int, p_day_of_month, p_hour, 0, 0);
    if candidate <= local_now then
      candidate := (date_trunc('month', d) + interval '1 month')::date + (p_day_of_month - 1) + make_interval(hours => p_hour);
    end if;
  end if;
  return candidate at time zone tz;
end $$;

create or replace function public.touch_backup_schedule()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  if tg_op = 'INSERT'
     or new.next_run_at is null
     or new.frequency is distinct from old.frequency
     or new.weekday is distinct from old.weekday
     or new.day_of_month is distinct from old.day_of_month
     or new.hour is distinct from old.hour
     or (new.enabled and not old.enabled) then
    new.next_run_at := public.backup_next_run(new.frequency, new.weekday, new.day_of_month, new.hour, now());
  end if;
  return new;
end $$;
drop trigger if exists trg_touch_backup_schedule on public.backup_schedules;
create trigger trg_touch_backup_schedule before insert or update on public.backup_schedules
for each row execute function public.touch_backup_schedule();

-- realtime (history refreshes while a scheduled run finishes)
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'backup_runs') then
    alter publication supabase_realtime add table public.backup_runs;
  end if;
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'backup_schedules') then
    alter publication supabase_realtime add table public.backup_schedules;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 2. Storage bucket (private) — scheduled files + optional manual copies
-- ---------------------------------------------------------------------
insert into storage.buckets (id, name, public) values ('backups', 'backups', false)
on conflict (id) do nothing;

drop policy if exists "backups_owner_read"   on storage.objects;
drop policy if exists "backups_owner_write"  on storage.objects;
drop policy if exists "backups_owner_update" on storage.objects;
drop policy if exists "backups_owner_delete" on storage.objects;
create policy "backups_owner_read"   on storage.objects for select using (bucket_id = 'backups' and (select public.is_owner()));
create policy "backups_owner_write"  on storage.objects for insert with check (bucket_id = 'backups' and (select public.is_owner()));
create policy "backups_owner_update" on storage.objects for update using (bucket_id = 'backups' and (select public.is_owner()));
create policy "backups_owner_delete" on storage.objects for delete using (bucket_id = 'backups' and (select public.is_owner()));

-- ---------------------------------------------------------------------
-- 3. Catalogue helpers
-- ---------------------------------------------------------------------
-- Is `t` a public base table that may be backed up? (internal staging
-- tables and the profiles VIEW are excluded)
create or replace function public.backup_is_table(t text)
returns boolean language sql stable as $$
  select exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind in ('r', 'p') and c.relname = t
       and c.relname not like 'backup\_restore\_%'
  )
$$;

-- primary-key columns in order
create or replace function public.backup_pk_columns(t text)
returns text[] language sql stable as $$
  select coalesce(array_agg(a.attname::text order by k.ord), '{}')
    from pg_index i
    join pg_class c on c.oid = i.indrelid
    join pg_namespace n on n.oid = c.relnamespace
    cross join lateral unnest(i.indkey) with ordinality as k(attnum, ord)
    join pg_attribute a on a.attrelid = c.oid and a.attnum = k.attnum
   where n.nspname = 'public' and c.relname = t and i.indisprimary
$$;

-- insertable (non-generated, non-dropped) columns in order
create or replace function public.backup_columns(t text)
returns text[] language sql stable as $$
  select coalesce(array_agg(a.attname::text order by a.attnum), '{}')
    from pg_attribute a
    join pg_class c on c.oid = a.attrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relname = t
     and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
$$;

-- FK parents inside public (self references ignored)
create or replace function public.backup_parents(t text)
returns text[] language sql stable as $$
  select coalesce(array_agg(distinct p.relname::text), '{}')
    from pg_constraint f
    join pg_class c on c.oid = f.conrelid
    join pg_class p on p.oid = f.confrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_namespace pn on pn.oid = p.relnamespace
   where f.contype = 'f' and n.nspname = 'public' and pn.nspname = 'public'
     and c.relname = t and p.relname <> t
$$;

-- Kahn order for a set of tables (parents first). Tables outside the set
-- are ignored (they must already exist in the database).
create or replace function public.backup_topo_order(p_tables text[])
returns text[] language plpgsql stable as $$
declare
  remaining text[] := (select coalesce(array_agg(distinct x order by x), '{}') from unnest(p_tables) x);
  ordered   text[] := '{}';
  t text; progressed boolean;
begin
  while cardinality(remaining) > 0 loop
    progressed := false;
    foreach t in array remaining loop
      -- every parent that is in the set must already be ordered
      if not exists (
        select 1 from unnest(public.backup_parents(t)) p
         where p = any(remaining) and not (p = any(ordered))
      ) then
        ordered := ordered || t;
        remaining := array_remove(remaining, t);
        progressed := true;
      end if;
    end loop;
    if not progressed then          -- cycle: append the rest as-is
      ordered := ordered || remaining;
      exit;
    end if;
  end loop;
  return ordered;
end $$;

-- ---------------------------------------------------------------------
-- 4. Catalogue + dump
-- ---------------------------------------------------------------------
create or replace function public.backup_tables()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  out jsonb := '[]'::jsonb;
  r record; n bigint;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  for r in
    select c.relname::text as name
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and c.relname not like 'backup\_restore\_%'
     order by c.relname
  loop
    execute format('select count(*) from public.%I', r.name) into n;
    out := out || jsonb_build_object(
      'name', r.name,
      'rows', n,
      'pk', to_jsonb(public.backup_pk_columns(r.name)),
      'columns', to_jsonb(public.backup_columns(r.name)),
      'parents', to_jsonb(public.backup_parents(r.name))
    );
  end loop;
  return out;
end $$;
revoke all on function public.backup_tables() from public;
grant execute on function public.backup_tables() to authenticated, service_role;

create or replace function public.backup_dump_table(p_table text, p_offset integer default 0, p_limit integer default 1000)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  pk text[]; ord text; out jsonb;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if not public.backup_is_table(p_table) then raise exception 'unknown_table' using errcode = 'P0001'; end if;
  pk := public.backup_pk_columns(p_table);
  select string_agg(format('%I', c), ', ') into ord from unnest(pk) c;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.%I order by %s offset %s limit %s) t',
    p_table, coalesce(ord, '1'), greatest(p_offset, 0), least(greatest(p_limit, 1), 2000)
  ) into out;
  return out;
end $$;
revoke all on function public.backup_dump_table(text, integer, integer) from public;
grant execute on function public.backup_dump_table(text, integer, integer) to authenticated, service_role;

-- Servant login accounts. Only the columns the Admin API can re-create:
-- id · email · phone · encrypted_password (bcrypt hash) · metadata ·
-- email_confirmed_at · created_at. Only accounts that ARE servants.
create or replace function public.backup_dump_auth_users()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare out jsonb;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', u.id,
             'email', j->>'email',
             'phone', j->>'phone',
             'encrypted_password', j->>'encrypted_password',
             'email_confirmed_at', j->>'email_confirmed_at',
             'raw_user_meta_data', coalesce(j->'raw_user_meta_data', '{}'::jsonb),
             'raw_app_meta_data', coalesce(j->'raw_app_meta_data', '{}'::jsonb),
             'created_at', j->>'created_at'
           ) order by j->>'created_at'), '[]'::jsonb)
    into out
    from auth.users u
    cross join lateral to_jsonb(u) j
   where exists (select 1 from public.servant_enrollments s where s.id = u.id);
  return out;
end $$;
revoke all on function public.backup_dump_auth_users() from public;
grant execute on function public.backup_dump_auth_users() to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 5. Restore — staged, chunked, FK ordered
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_begin(p_mode text, p_tables text[], p_meta jsonb default '{}'::jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare jid uuid; t text; bad text[] := '{}';
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if p_mode not in ('merge', 'replace') then raise exception 'bad_mode' using errcode = 'P0001'; end if;
  if p_tables is null or cardinality(p_tables) = 0 then raise exception 'no_tables' using errcode = 'P0001'; end if;
  foreach t in array p_tables loop
    if not public.backup_is_table(t) then bad := bad || t; end if;
  end loop;
  if cardinality(bad) > 0 then
    raise exception 'unknown_table:%', array_to_string(bad, ',') using errcode = 'P0001';
  end if;
  -- forget stale jobs of the same caller (abandoned uploads)
  delete from public.backup_restore_jobs
   where status = 'staging' and created_at < now() - interval '6 hours';
  insert into public.backup_restore_jobs (mode, tables, meta, created_by)
  values (p_mode, public.backup_topo_order(p_tables), coalesce(p_meta, '{}'::jsonb), auth.uid())
  returning id into jid;
  return jid;
end $$;
revoke all on function public.backup_restore_begin(text, text[], jsonb) from public;
grant execute on function public.backup_restore_begin(text, text[], jsonb) to authenticated, service_role;

create or replace function public.backup_restore_stage(p_job uuid, p_table text, p_seq integer, p_rows jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare j public.backup_restore_jobs; pk text[]; n integer;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job for update;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.status <> 'staging' then raise exception 'job_not_staging' using errcode = 'P0001'; end if;
  if not (p_table = any(j.tables)) then raise exception 'table_not_in_job' using errcode = 'P0001'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'rows_not_array' using errcode = 'P0001'; end if;

  insert into public.backup_restore_rows (job_id, table_name, seq, rows)
  values (p_job, p_table, p_seq, p_rows)
  on conflict (job_id, table_name, seq) do update set rows = excluded.rows, applied = false;

  -- pk keys (for replace mode's delete-missing)
  pk := public.backup_pk_columns(p_table);
  insert into public.backup_restore_keys (job_id, table_name, key)
  select p_job, p_table, k
    from (
      select string_agg(coalesce(r->>c, ''), '|' order by ord) as k
        from jsonb_array_elements(p_rows) with ordinality as e(r, i)
        cross join lateral unnest(pk) with ordinality as pc(c, ord)
       group by i
    ) s
  on conflict do nothing;

  n := jsonb_array_length(p_rows);
  return n;
end $$;
revoke all on function public.backup_restore_stage(uuid, text, integer, jsonb) from public;
grant execute on function public.backup_restore_stage(uuid, text, integer, jsonb) to authenticated, service_role;

-- tables of the job in FK order (parents first) + chunk counts
create or replace function public.backup_restore_order(p_job uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare j public.backup_restore_jobs; out jsonb := '[]'::jsonb; t text; c integer; n bigint;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  update public.backup_restore_jobs set status = 'applying' where id = p_job and status = 'staging';
  foreach t in array j.tables loop
    select count(*), coalesce(sum(jsonb_array_length(rows)), 0) into c, n
      from public.backup_restore_rows where job_id = p_job and table_name = t;
    out := out || jsonb_build_object('table', t, 'chunks', c, 'rows', n,
                                     'seqs', (select coalesce(jsonb_agg(seq order by seq), '[]'::jsonb)
                                                from public.backup_restore_rows where job_id = p_job and table_name = t));
  end loop;
  return out;
end $$;
revoke all on function public.backup_restore_order(uuid) from public;
grant execute on function public.backup_restore_order(uuid) to authenticated, service_role;

-- REPLACE mode: remove the rows the backup does not contain. Call in
-- REVERSE FK order (children first) before applying any chunk.
create or replace function public.backup_restore_delete_missing(p_job uuid, p_table text)
returns integer language plpgsql security definer set search_path = public as $$
declare j public.backup_restore_jobs; pk text[]; keyexpr text; n integer;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.mode <> 'replace' then return 0; end if;
  if not (p_table = any(j.tables)) then raise exception 'table_not_in_job' using errcode = 'P0001'; end if;
  pk := public.backup_pk_columns(p_table);
  if cardinality(pk) = 0 then return 0; end if;
  select string_agg(format('coalesce(t.%I::text, '''')', c), ' || ''|'' || ' order by ord)
    into keyexpr from unnest(pk) with ordinality as pc(c, ord);

  execute format('alter table public.%I disable trigger user', p_table);
  execute format(
    'delete from public.%I t where not exists (select 1 from public.backup_restore_keys k where k.job_id = $1 and k.table_name = $2 and k.key = %s)',
    p_table, keyexpr) using p_job, p_table;
  get diagnostics n = row_count;
  execute format('alter table public.%I enable trigger user', p_table);

  update public.backup_restore_jobs
     set result = jsonb_set(result, array[p_table, 'deleted'], to_jsonb(n), true)
   where id = p_job;
  return n;
end $$;
revoke all on function public.backup_restore_delete_missing(uuid, text) from public;
grant execute on function public.backup_restore_delete_missing(uuid, text) to authenticated, service_role;

-- Upsert one staged chunk. Columns = (columns in the backup) ∩ (current
-- insertable columns) — a column added by a later migration keeps its
-- default, a column removed since is ignored.
create or replace function public.backup_restore_apply_chunk(p_job uuid, p_table text, p_seq integer)
returns integer language plpgsql security definer set search_path = public as $$
declare
  j public.backup_restore_jobs; chunk jsonb; pk text[]; cols text[]; backup_cols text[];
  col_list text; set_list text; pk_list text; n integer;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.status not in ('staging', 'applying') then raise exception 'job_closed' using errcode = 'P0001'; end if;
  if not (p_table = any(j.tables)) then raise exception 'table_not_in_job' using errcode = 'P0001'; end if;

  select rows into chunk from public.backup_restore_rows
   where job_id = p_job and table_name = p_table and seq = p_seq for update;
  if chunk is null then raise exception 'chunk_not_found' using errcode = 'P0001'; end if;
  if jsonb_array_length(chunk) = 0 then return 0; end if;

  pk := public.backup_pk_columns(p_table);
  cols := public.backup_columns(p_table);
  -- columns known to the backup file (fallback: keys of the first row)
  select coalesce(array_agg(x), '{}') into backup_cols
    from jsonb_array_elements_text(coalesce(j.meta->'columns'->p_table, (select jsonb_agg(k) from jsonb_object_keys(chunk->0) k))) x;
  cols := (select coalesce(array_agg(c order by ord), '{}') from unnest(cols) with ordinality as cc(c, ord) where c = any(backup_cols));
  if cardinality(cols) = 0 then raise exception 'no_columns' using errcode = 'P0001'; end if;

  select string_agg(format('%I', c), ', ') into col_list from unnest(cols) c;
  select string_agg(format('%I', c), ', ') into pk_list  from unnest(pk) c;
  select string_agg(format('%1$I = excluded.%1$I', c), ', ') into set_list
    from unnest(cols) c where not (c = any(pk));

  execute format('alter table public.%I disable trigger user', p_table);
  if pk_list is null then
    execute format('insert into public.%1$I (%2$s) select %2$s from jsonb_populate_recordset(null::public.%1$I, $1)',
                   p_table, col_list) using chunk;
  elsif set_list is null then
    execute format('insert into public.%1$I (%2$s) select %2$s from jsonb_populate_recordset(null::public.%1$I, $1) on conflict (%3$s) do nothing',
                   p_table, col_list, pk_list) using chunk;
  else
    execute format('insert into public.%1$I (%2$s) select %2$s from jsonb_populate_recordset(null::public.%1$I, $1) on conflict (%3$s) do update set %4$s',
                   p_table, col_list, pk_list, set_list) using chunk;
  end if;
  get diagnostics n = row_count;
  execute format('alter table public.%I enable trigger user', p_table);

  update public.backup_restore_rows set applied = true
   where job_id = p_job and table_name = p_table and seq = p_seq;
  update public.backup_restore_jobs
     set result = jsonb_set(result, array[p_table, 'upserted'],
                            to_jsonb(coalesce((result->p_table->>'upserted')::int, 0) + n), true)
   where id = p_job;
  return n;
end $$;
revoke all on function public.backup_restore_apply_chunk(uuid, text, integer) from public;
grant execute on function public.backup_restore_apply_chunk(uuid, text, integer) to authenticated, service_role;

create or replace function public.backup_restore_finish(p_job uuid, p_status text, p_error text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare j public.backup_restore_jobs;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if p_status not in ('done', 'failed') then raise exception 'bad_status' using errcode = 'P0001'; end if;
  update public.backup_restore_jobs
     set status = p_status, error = p_error, finished_at = now()
   where id = p_job
  returning * into j;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  -- staged data is no longer needed
  delete from public.backup_restore_rows where job_id = p_job;
  delete from public.backup_restore_keys where job_id = p_job;
  return jsonb_build_object('id', j.id, 'status', j.status, 'result', j.result, 'tables', to_jsonb(j.tables));
end $$;
revoke all on function public.backup_restore_finish(uuid, text, text) from public;
grant execute on function public.backup_restore_finish(uuid, text, text) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 6. Schedules due for the cron route (service role)
-- ---------------------------------------------------------------------
create or replace function public.backup_schedules_due()
returns setof public.backup_schedules language sql stable security definer set search_path = public as $$
  select * from public.backup_schedules
   where public.backup_allowed() and enabled and next_run_at is not null and next_run_at <= now()
   order by next_run_at
$$;
revoke all on function public.backup_schedules_due() from public;
grant execute on function public.backup_schedules_due() to authenticated, service_role;

-- after a scheduled run: stamp + move on
create or replace function public.backup_schedule_ran(p_schedule uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
declare s public.backup_schedules;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into s from public.backup_schedules where id = p_schedule;
  if s.id is null then return; end if;
  update public.backup_schedules
     set last_run_at = now(), last_status = p_status,
         next_run_at = public.backup_next_run(s.frequency, s.weekday, s.day_of_month, s.hour, now())
   where id = p_schedule;
end $$;
revoke all on function public.backup_schedule_ran(uuid, text) from public;
grant execute on function public.backup_schedule_ran(uuid, text) to authenticated, service_role;

-- grants on the tables (RLS still applies for authenticated)
grant select, insert, update, delete on public.backup_schedules, public.backup_runs to authenticated, service_role;
grant select on public.backup_restore_jobs to authenticated, service_role;



-- #####################################################################
-- ##  0045_multi_scope_servants.sql
-- #####################################################################

-- =====================================================================
-- 0045: ONE PERSON → MANY PLACES (نطاقات متعددة للخادم · فصول متعددة للمخدوم)
--
-- A servant may now serve in SEVERAL churches / services / classes at the
-- same time, and a child may be enrolled in several classes (that was
-- already possible through `enrollments`, now it is EASY in the UI).
--
--   servant_enrollments (تسجيل الخادم — the account)
--     role · status · church_id · service_id · class_id   ← the PRIMARY scope
--                                                            (unchanged, so every
--                                                            older function keeps
--                                                            working)
--   servant_scopes (نطاقات الخادم الإضافية)                ← NEW
--     servant_id → servant_enrollments · church_id · service_id · class_id
--
--   my_scopes()                 = primary ∪ servant_scopes of the caller
--   servant_all_scopes(id)      = primary ∪ servant_scopes of ANY servant
--   can_access / scope_overlaps / scope_contains / enrollment_visible /
--   can_manage_servant          → true when ANY of the caller's scopes matches
--   churches / services / classes / servant_enrollments / persons policies
--                               → rewritten over my_scopes()
--   servant mirror rows         → ONE `enrollments` row PER CLASS the servant
--                                 serves in (was: one per servant)
--   set_servant_scopes(servant, scopes) → replace the list (manager / owner)
--   servant_signup / admin_add_servant  → accept p_scopes (array)
--   set_enrollments_status      → a scope-wide stop reaches servants whose
--                                 EXTRA scope lies inside it too
--
-- The role is ONE per servant and applies to every scope.
-- Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. servant_scopes — the additional places of a servant
-- ---------------------------------------------------------------------
create table if not exists public.servant_scopes (
  id          uuid primary key default gen_random_uuid(),
  servant_id  uuid not null references public.servant_enrollments(id) on delete cascade,
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null
);
comment on table public.servant_scopes is
  'نطاقات الخادم الإضافية — أماكن خدمة أخرى (كنيسة → خدمة → فصل) بجانب النطاق الأساسي في servant_enrollments';

create index if not exists idx_servant_scopes_servant on public.servant_scopes(servant_id);
create index if not exists idx_servant_scopes_church  on public.servant_scopes(church_id);
create index if not exists idx_servant_scopes_service on public.servant_scopes(service_id);
create index if not exists idx_servant_scopes_class   on public.servant_scopes(class_id);
-- one row per (servant, exact scope) — nulls compare equal here
create unique index if not exists uq_servant_scopes on public.servant_scopes(
  servant_id, church_id,
  coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(class_id,   '00000000-0000-0000-0000-000000000000'::uuid));

alter table public.servant_scopes enable row level security;
alter table public.servant_scopes replica identity full;
do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'servant_scopes') then
    alter publication supabase_realtime add table public.servant_scopes;
  end if;
end $$;

-- the chain must be consistent: service in church, class in service
create or replace function public.check_servant_scope_chain()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.service_id is not null
     and not exists (select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if new.class_id is not null and (new.service_id is null
      or not exists (select 1 from public.classes c where c.id = new.class_id and c.service_id = new.service_id)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  return new;
end $$;
drop trigger if exists trg_check_servant_scope_chain on public.servant_scopes;
create trigger trg_check_servant_scope_chain before insert or update on public.servant_scopes
for each row execute function public.check_servant_scope_chain();

-- ---------------------------------------------------------------------
-- 2. Scope readers
-- ---------------------------------------------------------------------
-- ALL scopes of any servant (primary ∪ extras). Security definer: used by
-- policies and helpers, never blocked by RLS.
create or replace function public.servant_all_scopes(p_servant uuid)
returns table (church_id uuid, service_id uuid, class_id uuid)
language sql stable security definer set search_path = public as $$
  select s.church_id, s.service_id, s.class_id
    from public.servant_enrollments s
   where s.id = p_servant and s.church_id is not null
  union
  select x.church_id, x.service_id, x.class_id
    from public.servant_scopes x
   where x.servant_id = p_servant
$$;
grant execute on function public.servant_all_scopes(uuid) to authenticated;

-- ALL scopes of the CALLER (approved only). The owner / a servant without
-- a scope still yields one row (role + nulls) exactly like my_scope().
create or replace function public.my_scopes()
returns table (role public.app_role, church_id uuid, service_id uuid, class_id uuid)
language sql stable security definer set search_path = public as $$
  select s.role, s.church_id, s.service_id, s.class_id
    from public.servant_enrollments s
   where s.id = auth.uid() and s.status = 'approved'
  union
  select s.role, x.church_id, x.service_id, x.class_id
    from public.servant_enrollments s
    join public.servant_scopes x on x.servant_id = s.id
   where s.id = auth.uid() and s.status = 'approved'
$$;
grant execute on function public.my_scopes() to authenticated, anon;

-- ---------------------------------------------------------------------
-- 3. Access predicates — ANY scope of the caller may match
-- ---------------------------------------------------------------------
create or replace function public.can_access(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select bool_or(case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        (s.service_id is null and p_church = s.church_id)
        or p_service = s.service_id
      when 'class_servant' then
        (s.class_id is null and (
          (s.service_id is null and p_church = s.church_id)
          or p_service = s.service_id
        ))
        or p_class = s.class_id
      else false
    end)
    from public.my_scopes() s
  ), false)
$$;

create or replace function public.scope_overlaps(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select bool_or(case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        p_church = s.church_id
        and (s.service_id is null or p_service is null or p_service = s.service_id)
      when 'class_servant' then
        p_church = s.church_id
        and (s.service_id is null or p_service is null or p_service = s.service_id)
        and (s.class_id is null or p_class is null or p_class = s.class_id)
      else false
    end)
    from public.my_scopes() s
  ), false)
$$;

create or replace function public.scope_contains(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select bool_or(case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then
        p_church = s.church_id
        and (s.service_id is null or (p_service is not null and p_service = s.service_id))
      when 'class_servant' then
        p_church = s.church_id
        and (s.service_id is null or (p_service is not null and p_service = s.service_id))
        and (s.class_id is null or (p_class is not null and p_class = s.class_id))
      else false
    end)
    from public.my_scopes() s
  ), false)
$$;

-- enrollment_visible(row scope, caller PRIMARY scope) is inlined in ~30
-- policies and ~15 RPCs. It keeps its signature; the primary check stays a
-- plain expression, and only when it fails the caller's EXTRA scopes are
-- looked up (cheap: indexed by servant_id, evaluated last thanks to the cost).
create or replace function public.extra_scope_visible(p_church uuid, p_service uuid, p_class uuid, s_role public.app_role)
returns boolean language sql stable security definer set search_path = public cost 500 as $$
  select s_role is not null and s_role <> 'owner' and exists (
    select 1 from public.servant_scopes x
     where x.servant_id = auth.uid()
       and case s_role
         when 'church_manager' then p_church = x.church_id
         when 'service_manager' then (x.service_id is null and p_church = x.church_id) or p_service = x.service_id
         when 'class_servant' then
           (x.class_id is null and ((x.service_id is null and p_church = x.church_id) or p_service = x.service_id))
           or p_class = x.class_id
         else false
       end)
$$;
grant execute on function public.extra_scope_visible(uuid, uuid, uuid, public.app_role) to authenticated, anon;

create or replace function public.enrollment_visible(p_church uuid, p_service uuid, p_class uuid,
                                                     s_role public.app_role, s_church uuid,
                                                     s_service uuid, s_class uuid)
returns boolean language sql stable as $$
  select coalesce(case s_role
    when 'owner' then true
    when 'church_manager' then p_church = s_church
    when 'service_manager' then (s_service is null and p_church = s_church) or p_service = s_service
    when 'class_servant' then
      (s_class is null and ((s_service is null and p_church = s_church) or p_service = s_service))
      or p_class = s_class
    else false
  end, false)
  or public.extra_scope_visible(p_church, p_service, p_class, s_role)
$$;

-- Is this servant (any of HIS scopes) inside the caller's management area?
-- church manager: same church · service manager: same service, or same
-- church when he manages the whole church. Owner handled by the callers.
create or replace function public.servant_in_my_scope(p_servant uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
      from public.my_scopes() s
      join public.servant_all_scopes(p_servant) t
        on case s.role
             when 'church_manager'  then t.church_id = s.church_id
             when 'service_manager' then (s.service_id is null and t.church_id = s.church_id) or t.service_id = s.service_id
             else false
           end
  )
$$;
grant execute on function public.servant_in_my_scope(uuid) to authenticated;

-- May the caller grant THIS scope to a servant? (approval / add / edit)
create or replace function public.scope_grantable(p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select bool_or(case s.role
      when 'owner' then true
      when 'church_manager' then p_church = s.church_id
      when 'service_manager' then (s.service_id is null and p_church = s.church_id) or (p_service is not null and p_service = s.service_id)
      else false
    end)
    from public.my_scopes() s), false)
$$;
grant execute on function public.scope_grantable(uuid, uuid, uuid) to authenticated;

-- Same rule for an explicit actor (service-role RPCs such as admin_add_servant)
create or replace function public.scope_grantable_by(p_actor uuid, p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select bool_or(case a.role
      when 'owner' then true
      when 'church_manager' then p_church = t.church_id
      when 'service_manager' then (t.service_id is null and p_church = t.church_id) or (p_service is not null and p_service = t.service_id)
      else false
    end)
    from public.servant_enrollments a
    left join public.servant_all_scopes(p_actor) t on true
    where a.id = p_actor and a.status = 'approved'), false)
$$;

-- can_manage_servant — owner: anyone but himself; managers: servants with
-- ANY scope inside ANY of theirs (never himself, never an owner).
create or replace function public.can_manage_servant(p_servant uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when p_servant = auth.uid() then false
      when me.role = 'owner' then true
      when me.role = 'church_manager' then t.role <> 'owner' and public.servant_in_my_scope(t.id)
      when me.role = 'service_manager' then t.role = 'class_servant' and public.servant_in_my_scope(t.id)
      else false
    end
    from public.my_scope() me, public.servant_enrollments t
    where t.id = p_servant
  ), false)
$$;

-- ---------------------------------------------------------------------
-- 4. Structural policies over my_scopes()
-- ---------------------------------------------------------------------
drop policy if exists churches_select on public.churches;
create policy churches_select on public.churches for select using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s where s.church_id = churches.id)
);
drop policy if exists churches_update on public.churches;
create policy churches_update on public.churches for update using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s where s.role = 'church_manager' and s.church_id = churches.id)
);

drop policy if exists services_select on public.services;
create policy services_select on public.services for select using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where s.church_id = services.church_id
                and (s.role = 'church_manager' or s.service_id is null or s.service_id = services.id))
);
drop policy if exists services_insert on public.services;
create policy services_insert on public.services for insert with check (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s where s.role = 'church_manager' and s.church_id = services.church_id)
);
drop policy if exists services_update on public.services;
create policy services_update on public.services for update using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where s.church_id = services.church_id
                and (s.role = 'church_manager'
                     or (s.role = 'service_manager' and (s.service_id is null or s.service_id = services.id))))
);
drop policy if exists services_delete on public.services;
create policy services_delete on public.services for delete using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s where s.role = 'church_manager' and s.church_id = services.church_id)
);

drop policy if exists classes_select on public.classes;
create policy classes_select on public.classes for select using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where case s.role
                when 'church_manager'  then classes.church_id = s.church_id
                when 'service_manager' then (s.service_id is null and classes.church_id = s.church_id) or classes.service_id = s.service_id
                when 'class_servant'   then (s.class_id is null and ((s.service_id is null and classes.church_id = s.church_id) or classes.service_id = s.service_id))
                                            or classes.id = s.class_id
                else false end)
);
drop policy if exists classes_insert on public.classes;
create policy classes_insert on public.classes for insert with check (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where (s.role = 'church_manager' and classes.church_id = s.church_id)
                 or (s.role = 'service_manager' and ((s.service_id is null and classes.church_id = s.church_id) or classes.service_id = s.service_id)))
);
drop policy if exists classes_update on public.classes;
create policy classes_update on public.classes for update using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where (s.role = 'church_manager' and classes.church_id = s.church_id)
                 or (s.role = 'service_manager' and ((s.service_id is null and classes.church_id = s.church_id) or classes.service_id = s.service_id))
                 or (s.role = 'class_servant' and classes.id = s.class_id))
);
drop policy if exists classes_delete on public.classes;
create policy classes_delete on public.classes for delete using (
  (select public.is_owner())
  or exists (select 1 from public.my_scopes() s
              where (s.role = 'church_manager' and classes.church_id = s.church_id)
                 or (s.role = 'service_manager' and ((s.service_id is null and classes.church_id = s.church_id) or classes.service_id = s.service_id)))
);

drop policy if exists servant_enrollments_select on public.servant_enrollments;
create policy servant_enrollments_select on public.servant_enrollments for select using (
  id = auth.uid()
  or (select public.is_owner())
  or public.servant_in_my_scope(id)
);
drop policy if exists servant_enrollments_update_mgmt on public.servant_enrollments;
create policy servant_enrollments_update_mgmt on public.servant_enrollments for update using (
  (select public.is_owner())
  or public.servant_in_my_scope(id)
);
drop policy if exists servant_enrollments_delete on public.servant_enrollments;
create policy servant_enrollments_delete on public.servant_enrollments for delete using (
  (select public.is_owner())
  or public.servant_in_my_scope(id)
);

drop policy if exists persons_select_servants on public.persons;
create policy persons_select_servants on public.persons for select using (
  exists (select 1 from public.servant_enrollments s
           where s.person_id = persons.id
             and ((select public.is_owner()) or public.servant_in_my_scope(s.id)))
);
drop policy if exists persons_update_servants on public.persons;
create policy persons_update_servants on public.persons for update using (
  exists (select 1 from public.servant_enrollments s
           where s.person_id = persons.id
             and ((select public.is_owner()) or public.servant_in_my_scope(s.id)))
);

-- servant_scopes: read = the servant himself · owner · his managers.
-- Writes go through set_servant_scopes / the signup & add RPCs only.
drop policy if exists servant_scopes_select on public.servant_scopes;
create policy servant_scopes_select on public.servant_scopes for select using (
  servant_id = auth.uid()
  or (select public.is_owner())
  or public.servant_in_my_scope(servant_id)
);
grant select on public.servant_scopes to authenticated;
grant all on public.servant_scopes to service_role;

-- ---------------------------------------------------------------------
-- 5. Servant mirror rows — ONE per class he serves in
-- ---------------------------------------------------------------------
drop index if exists public.uq_enrollments_servant;
create index if not exists idx_enrollments_servant on public.enrollments(servant_id) where servant_id is not null;

create or replace function public.sync_servant_mirrors(p_servant uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  cur public.servant_enrollments%rowtype;
  v_status text;
  r record;
begin
  select * into cur from public.servant_enrollments where id = p_servant;
  if not found or cur.person_id is null or cur.status not in ('approved', 'suspended') then
    delete from public.enrollments where servant_id = p_servant;
    return;
  end if;
  v_status := case when cur.status = 'suspended' then 'stopped' else 'active' end;

  -- mirrors of classes he no longer serves in, or of an older person
  delete from public.enrollments e
   where e.servant_id = p_servant
     and (e.person_id <> cur.person_id
          or not exists (select 1 from public.servant_all_scopes(p_servant) t where t.class_id = e.class_id));

  for r in
    select distinct t.church_id, t.service_id, t.class_id
      from public.servant_all_scopes(p_servant) t
     where t.class_id is not null
  loop
    insert into public.enrollments (person_id, church_id, service_id, class_id, kind, servant_id, status, created_by, edited_by)
    values (cur.person_id, r.church_id, r.service_id, r.class_id, 'servant', p_servant, v_status,
            coalesce(cur.approved_by, cur.id), coalesce(cur.approved_by, cur.id))
    on conflict (person_id, class_id) do update
      set kind = 'servant', servant_id = excluded.servant_id, status = excluded.status,
          church_id = excluded.church_id, service_id = excluded.service_id;
  end loop;
end $$;

create or replace function public.sync_servant_mirror_enrollment()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    delete from public.enrollments where servant_id = old.id;
    return old;
  end if;
  perform public.sync_servant_mirrors(new.id);
  return new;
end $$;
-- (trigger trg_sync_servant_mirror_enrollment from 0042 stays bound to this function)

create or replace function public.sync_servant_mirror_from_scopes()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then perform public.sync_servant_mirrors(old.servant_id); end if;
  if tg_op in ('INSERT', 'UPDATE') and (tg_op = 'INSERT' or new.servant_id <> old.servant_id) then
    perform public.sync_servant_mirrors(new.servant_id);
  end if;
  return null;
end $$;
drop trigger if exists trg_sync_servant_mirror_from_scopes on public.servant_scopes;
create trigger trg_sync_servant_mirror_from_scopes
after insert or update or delete on public.servant_scopes
for each row execute function public.sync_servant_mirror_from_scopes();

-- ---------------------------------------------------------------------
-- 6. set_servant_scopes — replace the list of places of a servant
--    p_scopes: [{church_id, service_id, class_id}, …] — the FIRST becomes the
--    primary scope (servant_enrollments columns), the rest → servant_scopes.
--    A manager may only touch scopes inside his own area: his provided list
--    replaces the servant's scopes WITHIN that area; scopes outside it are
--    kept untouched. The owner replaces everything.
-- ---------------------------------------------------------------------
create or replace function public.set_servant_scopes(p_servant uuid, p_scopes jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  t public.servant_enrollments%rowtype;
  v jsonb;
  v_c uuid; v_s uuid; v_k uuid;
  v_kept jsonb := '[]'::jsonb;       -- scopes outside the caller's area (untouched)
  v_given jsonb := '[]'::jsonb;      -- validated + deduplicated input
  v_final jsonb;
  v_first boolean := true;
  v_pc uuid; v_ps uuid; v_pk uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into t from public.servant_enrollments where id = p_servant;
  if not found then raise exception 'servant_not_found' using errcode = '22023'; end if;
  if not (public.is_owner() or public.can_manage_servant(p_servant)) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_scopes is null or jsonb_typeof(p_scopes) <> 'array' then
    raise exception 'scopes_required' using errcode = '22023';
  end if;

  -- 1) scopes the caller may NOT touch stay (never for the owner)
  if not public.is_owner() then
    select coalesce(jsonb_agg(jsonb_build_object('church_id', x.church_id, 'service_id', x.service_id, 'class_id', x.class_id)), '[]'::jsonb)
      into v_kept
      from public.servant_all_scopes(p_servant) x
     where not public.scope_grantable(x.church_id, x.service_id, x.class_id);
  end if;

  -- 2) validate + normalise the provided ones (role decides the depth)
  for v in select * from jsonb_array_elements(p_scopes) loop
    v_c := nullif(v->>'church_id', '')::uuid;
    v_s := nullif(v->>'service_id', '')::uuid;
    v_k := nullif(v->>'class_id', '')::uuid;
    if v_c is null then raise exception 'church_required' using errcode = '22023'; end if;
    if t.role = 'church_manager' then v_s := null; v_k := null; end if;
    if t.role = 'service_manager' then v_k := null; end if;
    if not exists (select 1 from public.churches c where c.id = v_c) then
      raise exception 'church_not_found' using errcode = '22023';
    end if;
    if v_s is not null and not exists (select 1 from public.services s where s.id = v_s and s.church_id = v_c) then
      raise exception 'service_not_in_church' using errcode = '22023';
    end if;
    if v_k is not null and (v_s is null or not exists (select 1 from public.classes c where c.id = v_k and c.service_id = v_s)) then
      raise exception 'class_not_in_service' using errcode = '22023';
    end if;
    if not public.scope_grantable(v_c, v_s, v_k) then
      raise exception 'scope_not_allowed' using errcode = '42501';
    end if;
    if not exists (select 1 from jsonb_array_elements(v_given) e
                    where (e->>'church_id')::uuid = v_c
                      and nullif(e->>'service_id', '')::uuid is not distinct from v_s
                      and nullif(e->>'class_id', '')::uuid is not distinct from v_k) then
      v_given := v_given || jsonb_build_object('church_id', v_c, 'service_id', v_s, 'class_id', v_k);
    end if;
  end loop;
  -- the provided scopes come FIRST (the first provided = primary), the kept ones after
  v_final := v_given || v_kept;
  if jsonb_array_length(v_final) = 0 then raise exception 'scopes_required' using errcode = '22023'; end if;

  -- 3) write: first → primary, rest → servant_scopes
  perform set_config('app.in_servant_signup', '1', true);   -- bypass the self-update guard
  delete from public.servant_scopes where servant_id = p_servant;
  for v in select * from jsonb_array_elements(v_final) loop
    v_c := (v->>'church_id')::uuid; v_s := (v->>'service_id')::uuid; v_k := (v->>'class_id')::uuid;
    if v_first then
      v_pc := v_c; v_ps := v_s; v_pk := v_k; v_first := false;
    else
      insert into public.servant_scopes (servant_id, church_id, service_id, class_id, created_by)
      values (p_servant, v_c, v_s, v_k, auth.uid())
      on conflict do nothing;
    end if;
  end loop;
  update public.servant_enrollments
     set church_id = v_pc, service_id = v_ps, class_id = v_pk, updated_at = now()
   where id = p_servant;
  perform set_config('app.in_servant_signup', '0', true);

  return jsonb_build_object('servant_id', p_servant, 'scopes', v_final, 'count', jsonb_array_length(v_final));
end $$;
revoke all on function public.set_servant_scopes(uuid, jsonb) from public, anon;
grant execute on function public.set_servant_scopes(uuid, jsonb) to authenticated;

-- ---------------------------------------------------------------------
-- 7. servant_signup — p_scopes (array of places); the old single-scope
--    parameters keep working when p_scopes is null.
-- ---------------------------------------------------------------------
drop function if exists public.servant_signup(text, text, text, date, text, text, text, uuid, uuid, uuid, text);
create or replace function public.servant_signup(
  p_code text,
  p_full_name text,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null,
  p_image_url text default null,
  p_scopes jsonb default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_code text := nullif(trim(p_code), '');
  v_user_id text;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_scopes jsonb;
  v jsonb; v_c uuid; v_s uuid; v_k uuid;
  v_i int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_full_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_phone is null then raise exception 'phone_required' using errcode = '22023'; end if;

  -- the list of places: p_scopes, or the legacy single scope
  v_scopes := case
    when p_scopes is not null and jsonb_typeof(p_scopes) = 'array' and jsonb_array_length(p_scopes) > 0 then p_scopes
    when p_church is not null then jsonb_build_array(jsonb_build_object('church_id', p_church, 'service_id', p_service, 'class_id', p_class))
    else '[]'::jsonb end;

  -- every chain must be consistent (all optional — the approver may set it)
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_c := nullif(v->>'church_id', '')::uuid; v_s := nullif(v->>'service_id', '')::uuid; v_k := nullif(v->>'class_id', '')::uuid;
    if v_c is null then raise exception 'church_required' using errcode = '22023'; end if;
    if v_s is not null and not exists (select 1 from public.services s where s.id = v_s and s.church_id = v_c) then
      raise exception 'service_not_in_church' using errcode = '22023';
    end if;
    if v_k is not null and (v_s is null or not exists (select 1 from public.classes c where c.id = v_k and c.service_id = v_s)) then
      raise exception 'class_not_in_service' using errcode = '22023';
    end if;
  end loop;
  -- primary = the first place
  v_c := nullif(v_scopes->0->>'church_id', '')::uuid;
  v_s := nullif(v_scopes->0->>'service_id', '')::uuid;
  v_k := nullif(v_scopes->0->>'class_id', '')::uuid;

  v_user_id := public.code_to_user_id(v_code);
  if exists (select 1 from public.servant_enrollments s where s.user_id = v_user_id and s.id <> v_uid) then
    raise exception 'code_taken' using errcode = '23505';
  end if;

  perform set_config('app.in_servant_signup', '1', true);
  insert into public.servant_enrollments (id, full_name, user_id, phone, role, status, church_id, service_id, class_id)
  values (v_uid, trim(p_full_name), v_user_id, v_phone, 'class_servant', 'pending', v_c, v_s, v_k)
  on conflict (id) do nothing;
  if not exists (select 1 from public.servant_enrollments s where s.id = v_uid and s.status = 'pending') then
    raise exception 'already_registered' using errcode = '23505';
  end if;

  select * into v_person from public.persons where national_id = v_code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, trim(p_full_name), p_gender, p_birthdate, v_phone,
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            p_image_url, v_uid, v_uid)
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, v_phone),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = v_uid, edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  update public.servant_enrollments set
    person_id  = v_person.id,
    full_name  = v_person.name,
    user_id    = v_user_id,
    phone      = coalesce(v_person.phone, v_phone),
    church_id  = v_c,
    service_id = v_s,
    class_id   = v_k,
    photo_url  = v_person.image_url,
    updated_at = now()
  where id = v_uid and status = 'pending';

  -- the other requested places (re-running the signup refreshes them)
  delete from public.servant_scopes where servant_id = v_uid;
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_i := v_i + 1;
    if v_i = 1 then continue; end if;
    insert into public.servant_scopes (servant_id, church_id, service_id, class_id, created_by)
    values (v_uid, nullif(v->>'church_id', '')::uuid, nullif(v->>'service_id', '')::uuid, nullif(v->>'class_id', '')::uuid, v_uid)
    on conflict do nothing;
  end loop;

  perform set_config('app.in_servant_signup', '0', true);
  return jsonb_build_object('person_id', v_person.id, 'person_created', v_created,
                            'national_id', v_person.national_id, 'user_id', v_user_id,
                            'scopes', jsonb_array_length(v_scopes));
end $$;
grant execute on function public.servant_signup(text, text, text, date, text, text, text, uuid, uuid, uuid, text, jsonb) to authenticated;

-- ---------------------------------------------------------------------
-- 8. admin_add_servant — p_scopes (service_role only, as in 0041)
-- ---------------------------------------------------------------------
drop function if exists public.admin_add_servant(uuid, uuid, text, text, public.app_role, uuid, uuid, uuid, text, date, text, text, text, text, uuid[]);
create or replace function public.admin_add_servant(
  p_actor     uuid,
  p_account   uuid,
  p_code      text,
  p_full_name text,
  p_role      public.app_role default 'class_servant',
  p_church    uuid default null,
  p_service   uuid default null,
  p_class     uuid default null,
  p_gender    text default null,
  p_birthdate date default null,
  p_phone     text default null,
  p_address   text default null,
  p_notes     text default null,
  p_image_url text default null,
  p_profiles  uuid[] default '{}',
  p_scopes    jsonb default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_actor  public.servant_enrollments%rowtype;
  v_code   text := nullif(trim(p_code), '');
  v_name   text := nullif(trim(coalesce(p_full_name, '')), '');
  v_phone  text := nullif(trim(coalesce(p_phone, '')), '');
  v_user_id text;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_granted integer := 0;
  v_scopes jsonb;
  v jsonb; v_c uuid; v_s uuid; v_k uuid;
  v_i int := 0;
begin
  if p_actor is null or p_account is null then
    raise exception 'actor_required' using errcode = '22023';
  end if;
  select * into v_actor from public.servant_enrollments where id = p_actor;
  if not found or v_actor.status <> 'approved'
     or v_actor.role not in ('owner', 'church_manager', 'service_manager') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender' using errcode = '22023';
  end if;
  if p_role = 'owner' then raise exception 'role_not_allowed' using errcode = '42501'; end if;

  -- what may THIS actor grant? (role)
  if v_actor.role = 'church_manager' and p_role = 'church_manager' then raise exception 'role_not_allowed' using errcode = '42501'; end if;
  if v_actor.role = 'service_manager' and p_role <> 'class_servant' then raise exception 'role_not_allowed' using errcode = '42501'; end if;

  v_scopes := case
    when p_scopes is not null and jsonb_typeof(p_scopes) = 'array' and jsonb_array_length(p_scopes) > 0 then p_scopes
    when p_church is not null then jsonb_build_array(jsonb_build_object('church_id', p_church, 'service_id', p_service, 'class_id', p_class))
    else '[]'::jsonb end;
  if jsonb_array_length(v_scopes) = 0 then raise exception 'church_required' using errcode = '22023'; end if;

  -- validate + normalise every place; the actor must be allowed to grant each
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_c := nullif(v->>'church_id', '')::uuid; v_s := nullif(v->>'service_id', '')::uuid; v_k := nullif(v->>'class_id', '')::uuid;
    if v_c is null then raise exception 'church_required' using errcode = '22023'; end if;
    if p_role = 'church_manager' then v_s := null; v_k := null; end if;
    if p_role = 'service_manager' then v_k := null; end if;
    if not exists (select 1 from public.churches c where c.id = v_c) then
      raise exception 'church_not_found' using errcode = '22023';
    end if;
    if v_s is not null and not exists (select 1 from public.services s where s.id = v_s and s.church_id = v_c) then
      raise exception 'service_not_in_church' using errcode = '22023';
    end if;
    if v_k is not null and (v_s is null or not exists (select 1 from public.classes c where c.id = v_k and c.service_id = v_s)) then
      raise exception 'class_not_in_service' using errcode = '22023';
    end if;
    if not public.scope_grantable_by(p_actor, v_c, v_s, v_k) then
      raise exception 'scope_not_allowed' using errcode = '42501';
    end if;
  end loop;
  v_c := nullif(v_scopes->0->>'church_id', '')::uuid;
  v_s := case when p_role = 'church_manager' then null else nullif(v_scopes->0->>'service_id', '')::uuid end;
  v_k := case when p_role = 'class_servant' then nullif(v_scopes->0->>'class_id', '')::uuid else null end;

  v_user_id := public.code_to_user_id(v_code);
  if exists (select 1 from public.servant_enrollments s where s.user_id = v_user_id) then
    raise exception 'code_taken' using errcode = '23505';
  end if;
  if exists (select 1 from public.servant_enrollments s where s.id = p_account) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  select * into v_person from public.persons where national_id = v_code;
  if found and exists (select 1 from public.servant_enrollments s where s.person_id = v_person.id) then
    raise exception 'code_taken' using errcode = '23505';
  end if;

  perform set_config('app.in_servant_signup', '1', true);
  insert into public.servant_enrollments
    (id, full_name, user_id, phone, role, status, church_id, service_id, class_id, approved_by, approved_at)
  values
    (p_account, v_name, v_user_id, coalesce(v_phone, ''), p_role, 'approved', v_c, v_s, v_k, p_actor, now());

  if v_person.id is null then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, v_name, p_gender, p_birthdate, v_phone,
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            p_image_url, p_actor, p_actor)
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      name      = v_name,
      gender    = coalesce(p_gender, gender),
      birthdate = coalesce(p_birthdate, birthdate),
      phone     = coalesce(v_phone, phone),
      address   = coalesce(nullif(trim(coalesce(p_address, '')), ''), address),
      notes     = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
      image_url = coalesce(p_image_url, image_url),
      edited_by = p_actor, edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  update public.servant_enrollments set
    person_id = v_person.id,
    full_name = v_person.name,
    phone     = coalesce(v_person.phone, ''),
    photo_url = v_person.image_url,
    updated_at = now()
  where id = p_account;

  -- the other places
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_i := v_i + 1;
    if v_i = 1 then continue; end if;
    insert into public.servant_scopes (servant_id, church_id, service_id, class_id, created_by)
    values (p_account, nullif(v->>'church_id', '')::uuid,
            case when p_role = 'church_manager' then null else nullif(v->>'service_id', '')::uuid end,
            case when p_role = 'class_servant' then nullif(v->>'class_id', '')::uuid else null end,
            p_actor)
    on conflict do nothing;
  end loop;
  perform set_config('app.in_servant_signup', '0', true);

  -- permission profiles
  if p_profiles is not null and array_length(p_profiles, 1) > 0 then
    insert into public.permissions (servant_id, permission_profile_id, granted_by)
    select p_account, pp.id, p_actor
      from public.permission_profiles pp
     where pp.id = any (p_profiles)
    on conflict (servant_id, permission_profile_id) do nothing;
    get diagnostics v_granted = row_count;
  end if;

  return jsonb_build_object(
    'servant_id', p_account, 'person_id', v_person.id, 'person_created', v_created,
    'national_id', v_person.national_id, 'user_id', v_user_id,
    'profiles_granted', v_granted, 'scopes', jsonb_array_length(v_scopes));
end $$;
revoke all on function public.admin_add_servant(uuid, uuid, text, text, public.app_role, uuid, uuid, uuid, text, date, text, text, text, text, uuid[], jsonb) from public, anon, authenticated;
grant execute on function public.admin_add_servant(uuid, uuid, text, text, public.app_role, uuid, uuid, uuid, text, date, text, text, text, text, uuid[], jsonb) to service_role;

-- ---------------------------------------------------------------------
-- 9. set_enrollments_status — a scope-wide stop reaches servants whose
--    EXTRA scope lies inside it too (same body as 0043 otherwise)
-- ---------------------------------------------------------------------
create or replace function public.set_enrollments_status(
  p_status text,
  p_enrollment_ids uuid[] default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null,
  p_kind text default 'child'
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_children int := 0;
  v_servants int := 0;
  v_srv_status public.approval_status;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_status not in ('active', 'stopped') then raise exception 'invalid_status' using errcode = '22023'; end if;
  if coalesce(p_kind, 'child') not in ('child', 'servant', 'all') then raise exception 'invalid_kind' using errcode = '22023'; end if;

  if p_enrollment_ids is not null then
    with upd as (
      update public.enrollments e
         set status = p_status, edited_by = auth.uid(), edited_at = now()
       where e.id = any (p_enrollment_ids)
         and e.kind = 'child'
         and e.status <> p_status
         and public.can_access(e.church_id, e.service_id, e.class_id)
      returning 1)
    select count(*) into v_children from upd;
    return jsonb_build_object('children', v_children, 'servants', 0);
  end if;

  if p_church is null then raise exception 'scope_required' using errcode = '22023'; end if;
  if not public.can_access(p_church, p_service, p_class) then raise exception 'forbidden' using errcode = '42501'; end if;

  if coalesce(p_kind, 'child') in ('child', 'all') then
    with upd as (
      update public.enrollments e
         set status = p_status, edited_by = auth.uid(), edited_at = now()
       where e.kind = 'child'
         and e.church_id = p_church
         and (p_service is null or e.service_id = p_service)
         and (p_class   is null or e.class_id   = p_class)
         and e.status <> p_status
      returning 1)
    select count(*) into v_children from upd;
  end if;

  if coalesce(p_kind, 'child') in ('servant', 'all') then
    v_srv_status := case when p_status = 'stopped' then 'suspended'::public.approval_status else 'approved'::public.approval_status end;
    with upd as (
      update public.servant_enrollments s
         set status = v_srv_status
       where exists (select 1 from public.servant_all_scopes(s.id) t
                      where t.church_id = p_church
                        and (p_service is null or t.service_id = p_service)
                        and (p_class   is null or t.class_id   = p_class))
         and s.status in ('approved', 'suspended')
         and s.status <> v_srv_status
         and public.can_manage_servant(s.id)
      returning 1)
    select count(*) into v_servants from upd;
  end if;

  return jsonb_build_object('children', v_children, 'servants', v_servants);
end $$;

-- ---------------------------------------------------------------------
-- 10. Housekeeping: 0042 added `p_password` to add_person_and_enroll but
--     left the older 12-argument overload in place → a call with the
--     defaults is ambiguous ("could not choose a best candidate"). Keep
--     only the 13-argument version.
-- ---------------------------------------------------------------------
drop function if exists public.add_person_and_enroll(uuid, uuid, uuid, text, text, text, date, text, text, text, text, integer);

-- ---------------------------------------------------------------------
-- 11. Backfill: mirrors of every servant are rebuilt under the new rule
-- ---------------------------------------------------------------------
do $$
declare r record;
begin
  for r in select id from public.servant_enrollments where status in ('approved', 'suspended') loop
    perform public.sync_servant_mirrors(r.id);
  end loop;
end $$;



-- #####################################################################
-- ##  0046_realtime_broadcast_scale.sql
-- #####################################################################

-- =====================================================================
-- 0046: SCALE — realtime broadcast instead of postgres_changes on the
--       hot tables, search indexes, dispatcher gate
--
-- WHY. With ~60–80 servants online on a scan day the app became laggy and
-- then failed. Every open app held 8–18 `postgres_changes` subscriptions
-- (header bells · 3 contexts · the page · up to 10 home widgets), many of
-- them on the HOT tables (attendance_log · points_log · enrollments ·
-- persons · contact_log · notification_recipients · chat_messages …).
-- For `postgres_changes` the Realtime server re-evaluates the table's RLS
-- policy ONCE PER CHANGE × PER SUBSCRIBER. One scan = 1 attendance_log
-- insert + 1 enrollments update (+ notification rows) → with 80 devices ×
-- ~10 channels that is ~3 000 policy queries hitting Postgres per scan —
-- the database saturated, every request queued behind it, the app "hung".
--
-- FIX. The hot tables leave the `supabase_realtime` publication. Instead a
-- STATEMENT-level trigger sends ONE small broadcast message per statement
-- (`realtime.send`) on a per-church topic (`scope:church:<id>`), plus
-- `scope:all` for the owner and `user:<uid>` for personal rows. Broadcast
-- authorization happens ONCE when the client joins the channel (RLS on
-- `realtime.messages`), not per row per subscriber. The browser keeps ONE
-- channel per topic and fans the message out to every screen/widget that
-- asked for that table (src/lib/realtime.ts) — the 84 call sites in the
-- app keep their code unchanged. Cost per scan: 2 tiny inserts, whatever
-- the number of connected devices.
--
-- ALSO
--   • pg_trgm GIN indexes on persons(name / phone / national_id) — the
--     search box issues `ilike '%x%'` which was a sequential scan of the
--     whole persons table per keystroke per user.
--   • composite indexes for the exact filters of the list / badges.
--   • notif_dispatch_gate(): the push dispatcher was kicked by EVERY open
--     app every 2 minutes (80 users → 40 serverless runs a minute, each
--     running notif_tick() with the service role). The gate lets one run
--     through per interval and answers "skip" to the others.
--
-- Idempotent; safe on a plain Postgres without the realtime schema (the
-- broadcast helper degrades to a no-op there). Rollback: re-add the tables
-- to the publication (see the bottom comment).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Broadcast helper — no-op when realtime.send is unavailable
-- ---------------------------------------------------------------------
create or replace function public.rt_send(p_topic text, p_payload jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  begin
    perform realtime.send(p_payload, 'change', p_topic, true);
  exception
    when undefined_function or invalid_schema_name or undefined_table then
      null; -- local Postgres / realtime not installed → nothing to do
    when others then
      raise notice 'rt_send skipped: %', sqlerrm;
  end;
end $$;
revoke all on function public.rt_send(text, jsonb) from public, anon, authenticated;

-- Send one message about `p_table` to every church in `p_churches` (+ the
-- owner topic). ids: first 50 affected ids so screens can patch locally.
create or replace function public.rt_notify_scope(p_table text, p_op text, p_churches uuid[], p_ids uuid[])
returns void language plpgsql security definer set search_path = public as $$
declare
  c uuid;
  payload jsonb := jsonb_build_object(
    't', p_table, 'op', p_op,
    'n', coalesce(array_length(p_ids, 1), 0),
    'ids', to_jsonb(coalesce(p_ids[1:50], '{}'::uuid[])));
begin
  perform public.rt_send('scope:all', payload);
  if p_churches is not null then
    foreach c in array p_churches loop
      if c is not null then perform public.rt_send('scope:church:' || c::text, payload); end if;
    end loop;
  end if;
end $$;
revoke all on function public.rt_notify_scope(text, text, uuid[], uuid[]) from public, anon, authenticated;

create or replace function public.rt_notify_users(p_table text, p_op text, p_users uuid[])
returns void language plpgsql security definer set search_path = public as $$
declare
  u uuid;
  payload jsonb := jsonb_build_object('t', p_table, 'op', p_op);
begin
  if p_users is null then return; end if;
  foreach u in array p_users loop
    if u is not null then perform public.rt_send('user:' || u::text, payload); end if;
  end loop;
end $$;
revoke all on function public.rt_notify_users(text, text, uuid[]) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 2. Statement-level triggers (transition tables → ONE message per
--    statement, however many rows a bulk import / scan burst touched)
-- ---------------------------------------------------------------------

-- Tables carrying church_id directly (enrollments · store_orders …)
create or replace function public.rt_trg_scoped()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[]; ids uuid[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct church_id), array_agg(id) into churches, ids from new_rows;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct church_id), array_agg(id) into churches, ids from old_rows;
  else
    select array_agg(distinct church_id), array_agg(distinct id) into churches, ids
      from (select church_id, id from new_rows union all select church_id, id from old_rows) x;
  end if;
  if ids is not null then perform public.rt_notify_scope(tg_table_name, tg_op, churches, ids); end if;
  return null;
end $$;

-- Tables that reach the church through enrollment_id (attendance_log ·
-- points_log · contact_log · card_print_requests · user_achievements)
create or replace function public.rt_trg_by_enrollment()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[]; ids uuid[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct e.church_id), array_agg(n.enrollment_id) into churches, ids
      from new_rows n join public.enrollments e on e.id = n.enrollment_id;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct e.church_id), array_agg(o.enrollment_id) into churches, ids
      from old_rows o join public.enrollments e on e.id = o.enrollment_id;
  else
    select array_agg(distinct e.church_id), array_agg(distinct n.enrollment_id) into churches, ids
      from new_rows n join public.enrollments e on e.id = n.enrollment_id;
  end if;
  if churches is not null then perform public.rt_notify_scope(tg_table_name, tg_op, churches, ids); end if;
  return null;
end $$;

-- persons: church through the person's enrollments (a person with no
-- enrollment yet is only interesting to the one who is creating him)
create or replace function public.rt_trg_persons()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[]; ids uuid[];
begin
  if tg_op = 'INSERT' then
    select array_agg(id) into ids from new_rows;
  elsif tg_op = 'DELETE' then
    select array_agg(id) into ids from old_rows;
  else
    select array_agg(id) into ids from new_rows;
  end if;
  if ids is null then return null; end if;
  select array_agg(distinct e.church_id) into churches
    from public.enrollments e where e.person_id = any(ids);
  perform public.rt_notify_scope('persons', tg_op, churches, ids);
  return null;
end $$;

-- notification_recipients → the staff recipient's personal topic.
-- (Children have no auth session → the child portal polls, see the app.)
create or replace function public.rt_trg_notification_recipients()
returns trigger language plpgsql security definer set search_path = public as $$
declare users uuid[];
begin
  if tg_op = 'DELETE' then
    select array_agg(distinct profile_id) into users from old_rows where profile_id is not null;
  else
    select array_agg(distinct profile_id) into users from new_rows where profile_id is not null;
  end if;
  perform public.rt_notify_users('notification_recipients', tg_op, users);
  return null;
end $$;

-- chat_messages: staff ↔ staff → both parties; child conversations and
-- broadcasts → the church topic (null church = every church)
create or replace function public.rt_trg_chat_messages()
returns trigger language plpgsql security definer set search_path = public as $$
declare users uuid[]; churches uuid[]; ids uuid[]; any_all boolean;
begin
  if tg_op = 'DELETE' then return null; end if;
  select array_agg(distinct u) into users
    from (select to_profile_id u from new_rows where to_profile_id is not null
          union select sender_profile_id from new_rows where sender_profile_id is not null) x;
  select array_agg(distinct church_id), array_agg(id), bool_or(church_id is null)
    into churches, ids, any_all
    from new_rows where kind <> 'staff';
  if any_all then select array_agg(id) into churches from public.churches; end if;
  if users is not null then perform public.rt_notify_users('chat_messages', tg_op, users); end if;
  if ids is not null then perform public.rt_notify_scope('chat_messages', tg_op, churches, ids); end if;
  return null;
end $$;

create or replace function public.rt_trg_chat_read_state()
returns trigger language plpgsql security definer set search_path = public as $$
declare users uuid[];
begin
  if tg_op = 'DELETE' then
    select array_agg(distinct reader_profile_id) into users from old_rows where reader_profile_id is not null;
  else
    select array_agg(distinct reader_profile_id) into users from new_rows where reader_profile_id is not null;
  end if;
  perform public.rt_notify_users('chat_read_state', tg_op, users);
  return null;
end $$;

-- servant_enrollments / servant_scopes: the servant himself (approval,
-- role change, new place) + his church (managers' lists)
create or replace function public.rt_trg_servant_enrollments()
returns trigger language plpgsql security definer set search_path = public as $$
declare users uuid[]; churches uuid[]; ids uuid[];
begin
  if tg_op = 'DELETE' then
    select array_agg(id), array_agg(distinct church_id) into ids, churches from old_rows;
  elsif tg_op = 'INSERT' then
    select array_agg(id), array_agg(distinct church_id) into ids, churches from new_rows;
  else
    select array_agg(distinct id), array_agg(distinct church_id) into ids, churches
      from (select id, church_id from new_rows union all select id, church_id from old_rows) x;
  end if;
  users := ids;
  perform public.rt_notify_users('servant_enrollments', tg_op, users);
  perform public.rt_notify_scope('servant_enrollments', tg_op, churches, ids);
  return null;
end $$;

create or replace function public.rt_trg_servant_scopes()
returns trigger language plpgsql security definer set search_path = public as $$
declare users uuid[]; churches uuid[];
begin
  if tg_op = 'DELETE' then
    select array_agg(distinct servant_id), array_agg(distinct church_id) into users, churches from old_rows;
  else
    select array_agg(distinct servant_id), array_agg(distinct church_id) into users, churches from new_rows;
  end if;
  perform public.rt_notify_users('servant_scopes', tg_op, users);
  perform public.rt_notify_scope('servant_scopes', tg_op, churches, users);
  return null;
end $$;

-- Attach: for each (table, function) three statement triggers with the
-- right transition tables. Skips tables that don't exist (older DBs).
do $$
declare
  spec record;
begin
  for spec in
    select * from (values
      ('enrollments',             'rt_trg_scoped'),
      ('store_orders',            'rt_trg_scoped'),
      ('attendance_log',          'rt_trg_by_enrollment'),
      ('points_log',              'rt_trg_by_enrollment'),
      ('contact_log',             'rt_trg_by_enrollment'),
      ('card_print_requests',     'rt_trg_by_enrollment'),
      ('user_achievements',       'rt_trg_by_enrollment'),
      ('persons',                 'rt_trg_persons'),
      ('notification_recipients', 'rt_trg_notification_recipients'),
      ('chat_messages',           'rt_trg_chat_messages'),
      ('chat_read_state',         'rt_trg_chat_read_state'),
      ('servant_enrollments',     'rt_trg_servant_enrollments'),
      ('servant_scopes',          'rt_trg_servant_scopes')
    ) as t(tbl, fn)
  loop
    if to_regclass('public.' || spec.tbl) is null then continue; end if;
    -- user_achievements may not carry enrollment_id in old schemas
    if spec.fn = 'rt_trg_by_enrollment' and not exists (
      select 1 from information_schema.columns
       where table_schema = 'public' and table_name = spec.tbl and column_name = 'enrollment_id') then
      continue;
    end if;
    execute format('drop trigger if exists zzz_rt_ins on public.%I', spec.tbl);
    execute format('drop trigger if exists zzz_rt_upd on public.%I', spec.tbl);
    execute format('drop trigger if exists zzz_rt_del on public.%I', spec.tbl);
    execute format(
      'create trigger zzz_rt_ins after insert on public.%I referencing new table as new_rows for each statement execute function public.%I()',
      spec.tbl, spec.fn);
    execute format(
      'create trigger zzz_rt_upd after update on public.%I referencing old table as old_rows new table as new_rows for each statement execute function public.%I()',
      spec.tbl, spec.fn);
    execute format(
      'create trigger zzz_rt_del after delete on public.%I referencing old table as old_rows for each statement execute function public.%I()',
      spec.tbl, spec.fn);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 3. Authorize the private broadcast topics (RLS on realtime.messages)
--      user:<uid>          — only that servant
--      scope:all           — the owner
--      scope:church:<id>   — anyone whose scopes include that church
-- ---------------------------------------------------------------------
create or replace function public.rt_topic_allowed(p_topic text)
returns boolean language sql stable security definer set search_path = public as $$
  select case
    when p_topic = 'user:' || coalesce(auth.uid()::text, '') then true
    when p_topic = 'scope:all' then public.is_owner()
    when p_topic like 'scope:church:%' then
      public.is_owner()
      or exists (select 1 from public.my_scopes() s
                  where s.church_id is not null and s.church_id::text = split_part(p_topic, ':', 3))
    else false
  end
$$;
grant execute on function public.rt_topic_allowed(text) to authenticated;

do $$
begin
  if to_regclass('realtime.messages') is not null then
    execute 'drop policy if exists "rt scope topics read" on realtime.messages';
    execute $p$create policy "rt scope topics read" on realtime.messages
              for select to authenticated
              using (public.rt_topic_allowed(realtime.topic()))$p$;
  end if;
exception when others then
  raise notice 'realtime.messages policy skipped: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------
-- 4. Take the hot tables OUT of the postgres_changes publication
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'attendance_log', 'points_log', 'contact_log', 'enrollments', 'persons',
    'notification_recipients', 'chat_messages', 'chat_read_state', 'store_orders',
    'card_print_requests', 'user_achievements', 'servant_enrollments', 'servant_scopes'
  ] loop
    if exists (select 1 from pg_publication_tables
                where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime drop table public.%I', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 5. Search: trigram indexes for the `ilike '%x%'` filters
-- ---------------------------------------------------------------------
do $$
declare nsp text;
begin
  if exists (select 1 from pg_namespace where nspname = 'extensions') then
    create extension if not exists pg_trgm with schema extensions;
  else
    create extension if not exists pg_trgm;
  end if;
  select n.nspname into nsp from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'pg_trgm';
  execute format('create index if not exists idx_persons_name_trgm on public.persons using gin (name %I.gin_trgm_ops)', nsp);
  execute format('create index if not exists idx_persons_phone_trgm on public.persons using gin (phone %I.gin_trgm_ops)', nsp);
  execute format('create index if not exists idx_persons_national_id_trgm on public.persons using gin (national_id %I.gin_trgm_ops)', nsp);
exception when others then
  raise notice 'pg_trgm indexes skipped: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------
-- 6. Composite indexes for the list / badge queries
-- ---------------------------------------------------------------------
create index if not exists idx_enrollments_kind_class   on public.enrollments(kind, class_id);
create index if not exists idx_enrollments_kind_service on public.enrollments(kind, service_id);
create index if not exists idx_enrollments_kind_church  on public.enrollments(kind, church_id);
create index if not exists idx_attendance_log_event_enrollment
  on public.attendance_log(event_id, enrollment_id, attended_on);
do $$
begin
  if to_regclass('public.notification_recipients') is not null then
    create index if not exists idx_notif_rcpt_profile_unread
      on public.notification_recipients(profile_id) where read_at is null;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 7. Dispatcher gate — at most ONE push-dispatch run per interval.
--    Own tiny table (NOT app_settings: that table is streamed to every
--    client through postgres_changes and a write there would make every
--    device reload its customization).
-- ---------------------------------------------------------------------
create table if not exists public.rt_gates (
  key        text primary key,
  fired_at   timestamptz not null default now()
);
alter table public.rt_gates enable row level security;
revoke all on public.rt_gates from public, anon, authenticated;

create or replace function public.notif_dispatch_gate(p_min_seconds integer default 45)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare ok boolean := false;
begin
  insert into public.rt_gates (key, fired_at) values ('notif_dispatch', now())
  on conflict (key) do update
    set fired_at = now()
    where public.rt_gates.fired_at <= now() - make_interval(secs => p_min_seconds)
  returning true into ok;
  return coalesce(ok, false);
end $$;
revoke all on function public.notif_dispatch_gate(integer) from public, anon, authenticated;
grant execute on function public.notif_dispatch_gate(integer) to service_role;

analyze public.persons;
analyze public.enrollments;
analyze public.attendance_log;


