-- #####################################################################
-- ##  0047_activity_log.sql
-- #####################################################################

-- =====================================================================
-- 0047: ACTIVITY LOG MODULE — سجل النشاط (كل ما يحدث في التطبيق)
--
-- ONE table — `activity_log` — receives EVERY operation that happens in the
-- app, wherever it comes from (a screen, an RPC, a server route, a trigger,
-- the child portal):
--
--   WHO    actor_kind (servant | child | system) · actor_id · actor_name ·
--          actor_role
--   WHAT   table_name · op (INSERT | UPDATE | DELETE | EVENT) · action
--          (a stable app key, e.g. attendance.add · points.add ·
--          person.update · auth.login …) · changed (columns that changed)
--   ON     row_id · target_kind · target_person_id · target_name ·
--          enrollment_id
--   WHERE  church_id · service_id · class_id (best effort resolution)
--   DIFF   old_data · new_data (UPDATE keeps ONLY the changed columns; row
--          snapshots are trimmed to the interesting columns)
--   BATCH  batch_id — every row written by ONE statement shares an id
--          (bulk import = 300 rows, one batch) · batch_size
--
-- HOW IT IS FILLED
--   1. A GENERIC statement-level trigger (`activity_audit`) on every
--      business table (list in §4 — one call to `activity_audit_attach()`
--      per table, idempotent). Uses transition tables → one function call
--      per statement, however many rows. The trigger resolves the actor from
--      auth.uid() (servant), from the child-portal session set by
--      `child_portal_person()` (child), or marks it `system` (cron / service
--      role / triggers without a caller).
--   2. `log_activity(action, target, meta)` — RPC for app-level EVENTS that
--      are not table writes: login · logout · export · print · scan …
--   3. Skips: `activity_log` itself, the backup staging tables, realtime
--      gates, push subscriptions, child_sessions (token hashes) and every
--      column that holds a secret (password_hash …).
--      `set_config('app.audit_off', '1')` inside a transaction disables the
--      trigger — backup restore uses it (0044 `disable trigger user` already
--      covers it, this is a belt on top).
--
-- WHO MAY READ (RLS)
--   module_visible('activity') AND
--     owner              → everything
--     church_manager     → rows of his church (+ rows without a church made
--                          by servants of his church)
--     service_manager    → his service · with `activity.view_all` he sees
--                          the whole church
--     class_servant      → nothing unless he holds `activity.view`
--                          (then: his class only)
--   `activity.view`      — read the log in scope
--   `activity.view_all`  — read the whole church (managers)
--   `activity.manage`    — settings (retention) + prune (owner only anyway)
--
-- READ API
--   activity_feed(p_filters jsonb, p_limit int, p_before timestamptz,
--                 p_before_id uuid)                 → keyset page (10…1000)
--   activity_summary(p_filters jsonb)               → counts by action /
--                                                     actor / table / day
--   activity_actors(p_filters jsonb)                → who did anything
--   activity_prune(p_keep_days int)                 → owner housekeeping
--   activity_settings() / activity_settings_set()   → retention in
--                                                     app_settings.activity
--
-- REALTIME: the table joins the 0046 broadcast bus (one message per
-- statement on scope:all + scope:church:<id>) so the log screen is live.
--
-- Idempotent — safe to re-run. Depends on 0019 (my_scope), 0024
-- (module_visible), 0037 (has_permission), 0042 (child_portal_person),
-- 0045 (scope_overlaps), 0046 (rt_notify_scope). NO module grant is
-- seeded — the owner enables it per scope in وحدة المالك.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE
-- ---------------------------------------------------------------------
create table if not exists public.activity_log (
  id               uuid primary key default gen_random_uuid(),
  created_at       timestamptz not null default now(),
  -- who
  actor_kind       text not null default 'system' check (actor_kind in ('servant', 'child', 'system')),
  actor_id         uuid,                       -- servant_enrollments.id | persons.id (child) | null
  actor_name       text,
  actor_role       text,                       -- owner | church_manager | … | child | system
  -- what
  table_name       text not null,
  op               text not null check (op in ('INSERT', 'UPDATE', 'DELETE', 'EVENT')),
  action           text not null,              -- stable key: attendance.add · person.update · auth.login …
  changed          text[],                     -- UPDATE: columns that changed
  -- on
  row_id           uuid,
  target_kind      text,                       -- person | servant | church | service | class | event | … | null
  target_person_id uuid,
  target_name      text,
  enrollment_id    uuid,
  -- where
  church_id        uuid,
  service_id       uuid,
  class_id         uuid,
  -- diff
  old_data         jsonb,
  new_data         jsonb,
  meta             jsonb,                      -- free extra (EVENT rows · trigger notes)
  -- batch
  batch_id         uuid,
  batch_size       integer not null default 1,
  source           text not null default 'db'  -- db | app | system
);

comment on table public.activity_log is 'سجل النشاط — كل عملية تحدث في التطبيق: مَن فعل ماذا على مَن وأين ومتى، مع الفرق قبل/بعد';

-- feed order + keyset pagination
create index if not exists idx_activity_log_created on public.activity_log (created_at desc, id desc);
create index if not exists idx_activity_log_actor    on public.activity_log (actor_kind, actor_id, created_at desc);
create index if not exists idx_activity_log_action   on public.activity_log (action, created_at desc);
create index if not exists idx_activity_log_table    on public.activity_log (table_name, created_at desc);
create index if not exists idx_activity_log_target   on public.activity_log (target_person_id, created_at desc) where target_person_id is not null;
create index if not exists idx_activity_log_row      on public.activity_log (row_id) where row_id is not null;
create index if not exists idx_activity_log_church   on public.activity_log (church_id, created_at desc);
create index if not exists idx_activity_log_batch    on public.activity_log (batch_id) where batch_id is not null;

alter table public.activity_log enable row level security;

-- nobody writes through the API — only the trigger / RPCs (security definer)
revoke insert, update, delete on public.activity_log from anon, authenticated;
grant select on public.activity_log to authenticated;

-- ---------------------------------------------------------------------
-- 2. PERMISSIONS
-- ---------------------------------------------------------------------
create or replace function public.activity_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('activity')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager')
       or (p_key in ('activity.view') and (select role from public.my_scope()) = 'service_manager')
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.activity_can(text) to authenticated;

create or replace function public.activity_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',     public.activity_can('activity.view'),
    'view_all', public.activity_can('activity.view_all'),
    'manage',   public.is_owner() and public.module_visible('activity')
  )
$$;
grant execute on function public.activity_permissions() to authenticated;

-- Row visibility for the policy. Owner: all. Church manager / view_all:
-- his church (or rows made by servants of his church that carry no church).
-- Service manager / class servant with activity.view: his scope.
create or replace function public.activity_row_visible(
  p_church uuid, p_service uuid, p_class uuid, p_actor_kind text, p_actor_id uuid
) returns boolean language sql stable security definer set search_path = public as $$
  select case
    when public.is_owner() then true
    when not public.activity_can('activity.view') then false
    when p_church is not null then
      case
        when (select role from public.my_scope()) = 'church_manager' or public.has_permission('activity.view_all')
          then exists (select 1 from public.my_scopes() s where s.church_id = p_church)
        else public.scope_overlaps(p_church, p_service, p_class)
      end
    -- no church on the row: a manager sees what servants of HIS church did
    when p_actor_kind = 'servant' and p_actor_id is not null then
      exists (select 1 from public.servant_enrollments se
               join public.my_scopes() s on s.church_id = se.church_id
              where se.id = p_actor_id)
      and ((select role from public.my_scope()) = 'church_manager' or public.has_permission('activity.view_all'))
    else false
  end
$$;
grant execute on function public.activity_row_visible(uuid, uuid, uuid, text, uuid) to authenticated;

drop policy if exists activity_log_select on public.activity_log;
create policy activity_log_select on public.activity_log for select using (
  public.activity_row_visible(church_id, service_id, class_id, actor_kind, actor_id)
);

-- ---------------------------------------------------------------------
-- 3. ACTOR RESOLUTION
-- ---------------------------------------------------------------------
-- The child portal never has an auth session: every child_portal_* RPC
-- calls child_portal_person(token). We stamp the resolved person on the
-- transaction (set_config local) so the audit trigger can name the actor.
create or replace function public.child_portal_person(p_national_id text)
returns public.persons language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v public.persons;
  s public.child_sessions;
begin
  if nullif(trim(coalesce(p_national_id, '')), '') is null then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;
  select * into s from public.child_sessions
   where token_hash = encode(digest(trim(p_national_id), 'sha256'), 'hex');
  if not found or s.expires_at < now() then
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  select * into v from public.persons where id = s.person_id;
  if not found then
    raise exception 'unknown_code' using errcode = 'P0002';
  end if;
  -- 0047: remember the child for the audit trigger (transaction-local)
  perform set_config('app.child_actor', v.id::text, true);
  return v;
end $$;
revoke all on function public.child_portal_person(text) from public, anon, authenticated;

-- Also stamp the child on login (child_login does not go through child_portal_person)
create or replace function public.activity_stamp_child(p_person uuid)
returns void language sql volatile security definer set search_path = public as $$
  select set_config('app.child_actor', coalesce(p_person::text, ''), true)
$$;
revoke all on function public.activity_stamp_child(uuid) from public, anon, authenticated;

-- (kind, id, name, role) of whoever is acting in this transaction
create or replace function public.activity_actor()
returns table (kind text, id uuid, name text, role text)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_variable
declare
  uid uuid := auth.uid();
  cid text := current_setting('app.child_actor', true);
  se  public.servant_enrollments;
begin
  if uid is not null then
    select * into se from public.servant_enrollments x where x.id = uid;
    if found then
      return query select 'servant'::text, se.id, se.full_name, se.role::text;
      return;
    end if;
    return query select 'servant'::text, uid, null::text, 'unknown'::text;
    return;
  end if;
  if nullif(cid, '') is not null then
    return query select 'child'::text, p.id, p.name, 'child'::text from public.persons p where p.id = cid::uuid;
    if found then return; end if;
  end if;
  return query select 'system'::text, null::uuid, null::text,
    case when auth.role() = 'service_role' then 'service_role' else 'system' end;
end $$;
revoke all on function public.activity_actor() from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. GENERIC AUDIT TRIGGER
-- ---------------------------------------------------------------------
-- Columns never written to the log
create or replace function public.activity_secret_columns()
returns text[] language sql immutable as $$
  select array['password_hash', 'token_hash', 'auth', 'p256dh', 'endpoint', 'design', 'value_large']
$$;

-- Strip secrets + oversized values from a row snapshot
create or replace function public.activity_trim(p_row jsonb)
returns jsonb language sql immutable as $$
  select coalesce((
    select jsonb_object_agg(k,
             case when jsonb_typeof(v) = 'string' and length(v #>> '{}') > 600
                  then to_jsonb(left(v #>> '{}', 600) || '…')
                  when jsonb_typeof(v) in ('object', 'array') and length(v::text) > 2000
                  then to_jsonb('{…' || length(v::text) || '}')
                  else v end)
      from jsonb_each(p_row) as e(k, v)
     where not (k = any (public.activity_secret_columns()))
  ), '{}'::jsonb)
$$;

-- Human "target" of a row: which person / entity does it concern?
-- Returns (target_kind, target_person_id, target_name, enrollment_id,
-- church_id, service_id, class_id) — best effort, never raises.
create or replace function public.activity_resolve_target(p_table text, r jsonb)
returns table (target_kind text, target_person_id uuid, target_name text, enrollment_id uuid,
               church_id uuid, service_id uuid, class_id uuid)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_variable
declare
  eid uuid; pid uuid; sid uuid;
  e public.enrollments; p public.persons; se public.servant_enrollments;
  tk text := null; tn text := null;
  ch uuid := nullif(r->>'church_id', '')::uuid;
  sv uuid := nullif(r->>'service_id', '')::uuid;
  cl uuid := nullif(r->>'class_id', '')::uuid;
begin
  eid := nullif(r->>'enrollment_id', '')::uuid;
  pid := nullif(r->>'person_id', '')::uuid;
  sid := nullif(r->>'servant_id', '')::uuid;

  if p_table = 'persons' then
    pid := nullif(r->>'id', '')::uuid; tk := 'person'; tn := r->>'name';
  elsif p_table = 'enrollments' then
    eid := nullif(r->>'id', '')::uuid; tk := case when r->>'kind' = 'servant' then 'servant' else 'person' end;
  elsif p_table = 'servant_enrollments' then
    sid := nullif(r->>'id', '')::uuid; tk := 'servant'; tn := r->>'full_name';
  elsif p_table in ('servant_scopes', 'permissions', 'shepherd_groups') then
    tk := 'servant';
  elsif p_table = 'churches' then tk := 'church'; tn := r->>'name'; ch := nullif(r->>'id', '')::uuid;
  elsif p_table = 'services' then tk := 'service'; tn := r->>'name'; sv := nullif(r->>'id', '')::uuid;
  elsif p_table = 'classes'  then tk := 'class';   tn := r->>'name'; cl := nullif(r->>'id', '')::uuid;
  elsif p_table = 'events' then tk := 'event'; tn := r->>'name';
  elsif p_table = 'causes' then tk := 'cause'; tn := r->>'name';
  elsif p_table = 'call_feedbacks' then tk := 'feedback'; tn := r->>'name';
  elsif p_table = 'child_join_requests' then tk := 'person'; tn := r->>'name';
  elsif p_table = 'store_items' then tk := 'item'; tn := r->>'name';
  elsif p_table in ('exams', 'occasions', 'online_classes', 'library_books', 'library_lectures') then tk := 'content'; tn := r->>'title';
  elsif p_table in ('achievements', 'result_exams', 'library_subjects', 'permission_profiles', 'card_templates',
                    'birthday_card_templates', 'notification_automations', 'grading_systems', 'backup_schedules') then tk := 'content'; tn := r->>'name';
  elsif p_table = 'notifications' then tk := 'content'; tn := r->>'title';
  elsif p_table = 'module_access' then tk := 'module'; tn := r->>'module_key';
  elsif p_table = 'app_settings' then tk := 'setting'; tn := r->>'key';
  elsif p_table = 'chat_messages' then tk := 'message';
  end if;

  -- resolve person / scope through the enrollment
  if eid is not null then
    select * into e from public.enrollments x where x.id = eid;
    if found then
      pid := coalesce(pid, e.person_id);
      ch := coalesce(ch, e.church_id); sv := coalesce(sv, e.service_id); cl := coalesce(cl, e.class_id);
      if tk is null then tk := case when e.kind = 'servant' then 'servant' else 'person' end; end if;
    end if;
  end if;
  if sid is not null and (tn is null or tk = 'servant') then
    select * into se from public.servant_enrollments x where x.id = sid;
    if found then
      tn := coalesce(tn, se.full_name); tk := coalesce(tk, 'servant');
      ch := coalesce(ch, se.church_id); sv := coalesce(sv, se.service_id); cl := coalesce(cl, se.class_id);
    end if;
  end if;
  if pid is not null and tn is null then
    select * into p from public.persons x where x.id = pid;
    if found then tn := p.name; tk := coalesce(tk, 'person'); end if;
  end if;
  -- scope through the hierarchy when only a class / service is known
  if ch is null and cl is not null then
    select c.church_id, c.service_id into ch, sv from public.classes c where c.id = cl;
  end if;
  if ch is null and sv is not null then
    select s.church_id into ch from public.services s where s.id = sv;
  end if;

  return query select tk, pid, tn, eid, ch, sv, cl;
exception when others then
  return query select tk, pid, tn, eid, ch, sv, cl;
end $$;
revoke all on function public.activity_resolve_target(text, jsonb) from public, anon, authenticated;

-- Stable app-level action key for a table + op (the UI translates it)
create or replace function public.activity_action_key(p_table text, p_op text, p_old jsonb, p_new jsonb)
returns text language plpgsql immutable as $$
declare base text; verb text;
begin
  verb := case p_op when 'INSERT' then 'add' when 'DELETE' then 'remove' else 'update' end;
  base := case p_table
    when 'attendance_log' then 'attendance'
    when 'points_log' then 'points'
    when 'contact_log' then case coalesce(p_new->>'kind', p_old->>'kind') when 'call' then 'call' else 'message' end
    when 'persons' then 'person'
    when 'enrollments' then case when coalesce(p_new->>'kind', p_old->>'kind') = 'servant' then 'servant_mirror' else 'enrollment' end
    when 'servant_enrollments' then 'servant'
    when 'servant_scopes' then 'servant_scope'
    when 'permissions' then 'permission'
    when 'permission_profiles' then 'permission_profile'
    when 'module_access' then 'module_access'
    when 'churches' then 'church'
    when 'services' then 'service'
    when 'classes' then 'class'
    when 'events' then 'event'
    when 'causes' then 'cause'
    when 'call_feedbacks' then 'feedback'
    when 'card_print_requests' then 'print_request'
    when 'card_templates' then 'card_template'
    when 'data_change_requests' then 'data_request'
    when 'child_join_requests' then 'join_request'
    when 'person_credentials' then 'password'
    when 'shepherd_groups' then 'shepherd'
    when 'store_items' then 'store_item'
    when 'store_orders' then 'store_order'
    when 'exams' then 'exam'
    when 'exam_questions' then 'exam_question'
    when 'exam_attempts' then 'exam_attempt'
    when 'birthday_greetings' then 'birthday'
    when 'birthday_settings' then 'birthday_setting'
    when 'birthday_card_templates' then 'birthday_card'
    when 'chat_messages' then 'chat'
    when 'online_classes' then 'online_class'
    when 'online_class_participants' then 'online_participant'
    when 'achievements' then 'achievement'
    when 'user_achievements' then 'achievement_award'
    when 'occasions' then 'occasion'
    when 'occasion_registrations' then 'occasion_registration'
    when 'occasion_checklist_items' then 'occasion_checklist'
    when 'occasion_checklist_marks' then 'occasion_mark'
    when 'notifications' then 'notification'
    when 'notification_automations' then 'notification_automation'
    when 'app_settings' then 'setting'
    when 'result_exams' then 'result_exam'
    when 'result_subjects' then 'result_subject'
    when 'exam_results' then 'result'
    when 'grading_systems' then 'grading'
    when 'grading_grades' then 'grading_grade'
    when 'library_subjects' then 'library_subject'
    when 'library_books' then 'library_book'
    when 'library_lectures' then 'library_lecture'
    when 'library_favorites' then 'library_favorite'
    when 'backup_runs' then 'backup'
    when 'backup_schedules' then 'backup_schedule'
    else p_table end;

  -- a few semantic refinements
  if p_table = 'servant_enrollments' and p_op = 'UPDATE' then
    if p_old->>'status' is distinct from p_new->>'status' then
      verb := case p_new->>'status' when 'approved' then 'approve' when 'rejected' then 'reject'
                   when 'suspended' then 'suspend' else 'status' end;
    elsif p_old->>'role' is distinct from p_new->>'role' then verb := 'role';
    end if;
  elsif p_table = 'enrollments' and p_op = 'UPDATE' then
    if p_old->>'status' is distinct from p_new->>'status' then verb := case p_new->>'status' when 'stopped' then 'stop' else 'resume' end;
    elsif p_old->>'class_id' is distinct from p_new->>'class_id' then verb := 'move';
    elsif (p_old - 'attendance_count' - 'points' - 'edited_at' - 'edited_by') = (p_new - 'attendance_count' - 'points' - 'edited_at' - 'edited_by') then
      verb := 'counters';
    end if;
  elsif p_table = 'points_log' and p_op = 'INSERT' then
    verb := case when coalesce((p_new->>'delta')::int, 0) < 0 then 'deduct' else 'add' end;
  elsif p_table in ('store_orders', 'exam_attempts', 'occasion_registrations') and p_op = 'UPDATE'
        and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table in ('data_change_requests', 'child_join_requests') and p_op = 'UPDATE'
        and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table = 'result_exams' and p_op = 'UPDATE' and p_old->>'locked' is distinct from p_new->>'locked' then
    verb := case when (p_new->>'locked')::boolean then 'lock' else 'unlock' end;
  elsif p_table = 'online_classes' and p_op = 'UPDATE' and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table = 'exams' and p_op = 'UPDATE' and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  end if;
  return base || '.' || verb;
end $$;

-- Is auditing switched off for this transaction? (backup restore …)
create or replace function public.activity_off()
returns boolean language sql stable as $$
  select coalesce(current_setting('app.audit_off', true), '') = '1'
$$;

-- THE trigger. Statement level, transition tables. Writes one activity_log
-- row per affected row, all sharing a batch_id.
create or replace function public.activity_audit()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  a record;
  bid uuid := gen_random_uuid();
  n integer := 0;
  pk text := 'id';
begin
  if public.activity_off() then return null; end if;
  select * into a from public.activity_actor();

  if tg_op = 'INSERT' then
    execute format($q$
      insert into public.activity_log
        (actor_kind, actor_id, actor_name, actor_role, table_name, op, action, row_id,
         target_kind, target_person_id, target_name, enrollment_id, church_id, service_id, class_id,
         new_data, batch_id, source)
      select $1, $2, $3, $4, %1$L, 'INSERT', public.activity_action_key(%1$L, 'INSERT', null, j),
             nullif(j->>%2$L, '')::uuid,
             t.target_kind, t.target_person_id, t.target_name, t.enrollment_id, t.church_id, t.service_id, t.class_id,
             public.activity_trim(j), $5, 'db'
        from (select to_jsonb(x) j from new_rows x) r
        cross join lateral public.activity_resolve_target(%1$L, r.j) t
    $q$, tg_table_name, pk) using a.kind, a.id, a.name, a.role, bid;
  elsif tg_op = 'DELETE' then
    execute format($q$
      insert into public.activity_log
        (actor_kind, actor_id, actor_name, actor_role, table_name, op, action, row_id,
         target_kind, target_person_id, target_name, enrollment_id, church_id, service_id, class_id,
         old_data, batch_id, source)
      select $1, $2, $3, $4, %1$L, 'DELETE', public.activity_action_key(%1$L, 'DELETE', j, null),
             nullif(j->>%2$L, '')::uuid,
             t.target_kind, t.target_person_id, t.target_name, t.enrollment_id, t.church_id, t.service_id, t.class_id,
             public.activity_trim(j), $5, 'db'
        from (select to_jsonb(x) j from old_rows x) r
        cross join lateral public.activity_resolve_target(%1$L, r.j) t
    $q$, tg_table_name, pk) using a.kind, a.id, a.name, a.role, bid;
  else
    -- UPDATE: pair old/new on the primary key (row_number fallback for tables
    -- without an `id` column); keep only the columns that changed and skip
    -- rows where nothing but bookkeeping (edited_at / updated_at) moved.
    execute format($q$
      with o as (select to_jsonb(x) j, row_number() over () rn from old_rows x),
           nn as (select to_jsonb(x) j, row_number() over () rn from new_rows x),
           pairs as (
             select o.j oj, nn.j nj from o join nn
               on case when o.j ? %2$L then o.j->>%2$L = nn.j->>%2$L else o.rn = nn.rn end
           ),
           diff as (
             select oj, nj,
               (select coalesce(array_agg(k order by k), '{}') from (
                  select k from jsonb_each(nj) e(k, v) where oj->k is distinct from v
                  union select k from jsonb_object_keys(oj) k where not (nj ? k)) z) chg
             from pairs
           )
      insert into public.activity_log
        (actor_kind, actor_id, actor_name, actor_role, table_name, op, action, changed, row_id,
         target_kind, target_person_id, target_name, enrollment_id, church_id, service_id, class_id,
         old_data, new_data, batch_id, source)
      select $1, $2, $3, $4, %1$L, 'UPDATE', public.activity_action_key(%1$L, 'UPDATE', oj, nj), chg,
             nullif(nj->>%2$L, '')::uuid,
             t.target_kind, t.target_person_id, t.target_name, t.enrollment_id, t.church_id, t.service_id, t.class_id,
             public.activity_trim((select coalesce(jsonb_object_agg(k, oj->k), '{}') from unnest(chg) k)),
             public.activity_trim((select coalesce(jsonb_object_agg(k, nj->k), '{}') from unnest(chg) k)),
             $5, 'db'
        from diff
        cross join lateral public.activity_resolve_target(%1$L, nj) t
       where exists (select 1 from unnest(chg) k
                      where k not in ('edited_at', 'updated_at', 'last_seen_at', 'last_read_at', 'updated_by', 'edited_by'))
    $q$, tg_table_name, pk) using a.kind, a.id, a.name, a.role, bid;
  end if;

  get diagnostics n = row_count;
  if n > 1 then update public.activity_log set batch_size = n where batch_id = bid; end if;
  return null;
end $$;
revoke all on function public.activity_audit() from public, anon, authenticated;

-- Attach the three statement triggers to one table (idempotent)
create or replace function public.activity_audit_attach(p_table text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
                  where n.nspname = 'public' and c.relname = p_table and c.relkind = 'r') then
    return;
  end if;
  execute format('drop trigger if exists zza_audit_ins on public.%I', p_table);
  execute format('drop trigger if exists zza_audit_upd on public.%I', p_table);
  execute format('drop trigger if exists zza_audit_del on public.%I', p_table);
  execute format('create trigger zza_audit_ins after insert on public.%I referencing new table as new_rows for each statement execute function public.activity_audit()', p_table);
  execute format('create trigger zza_audit_upd after update on public.%I referencing old table as old_rows new table as new_rows for each statement execute function public.activity_audit()', p_table);
  execute format('create trigger zza_audit_del after delete on public.%I referencing old table as old_rows for each statement execute function public.activity_audit()', p_table);
end $$;
revoke all on function public.activity_audit_attach(text) from public, anon, authenticated;

create or replace function public.activity_audit_detach(p_table text)
returns void language plpgsql security definer set search_path = public as $$
begin
  execute format('drop trigger if exists zza_audit_ins on public.%I', p_table);
  execute format('drop trigger if exists zza_audit_upd on public.%I', p_table);
  execute format('drop trigger if exists zza_audit_del on public.%I', p_table);
exception when undefined_table then null;
end $$;
revoke all on function public.activity_audit_detach(text) from public, anon, authenticated;

-- The audited tables = every business table. Excluded on purpose:
--   activity_log (itself) · backup_restore_* (staging) · rt_gates ·
--   push_subscriptions (device keys) · child_sessions (token hashes) ·
--   online_class_sessions / chat_read_state / notification_recipients /
--   notification_automation_runs / online_class_check_responses (high-volume
--   heartbeat / delivery rows — noise, not operations).
create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules'
  ]
$$;

do $$ declare t text; begin
  foreach t in array public.activity_audited_tables() loop
    perform public.activity_audit_attach(t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 5. APP-LEVEL EVENTS — log_activity()
-- ---------------------------------------------------------------------
-- action: 'auth.login' · 'auth.logout' · 'auth.login_failed' · 'export.excel'
--         · 'print.cards' · 'scan.qr' · 'backup.download' · anything the app
--         wants (namespace.verb). Target is optional.
create or replace function public.log_activity(
  p_action text,
  p_target_person uuid default null,
  p_enrollment uuid default null,
  p_meta jsonb default '{}'::jsonb,
  p_church uuid default null, p_service uuid default null, p_class uuid default null
) returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  a record; tn text; ch uuid := p_church; sv uuid := p_service; cl uuid := p_class; lid uuid;
  e public.enrollments;
begin
  if p_action is null or p_action !~ '^[a-z_]+\.[a-z_]+$' then
    raise exception 'bad_action' using errcode = 'P0001';
  end if;
  select * into a from public.activity_actor();
  if a.kind = 'system' and auth.role() not in ('service_role') then
    -- an anonymous browser may only log auth events (failed logins)
    if p_action not like 'auth.%' then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  end if;
  if p_enrollment is not null then
    select * into e from public.enrollments where id = p_enrollment;
    if found then
      ch := coalesce(ch, e.church_id); sv := coalesce(sv, e.service_id); cl := coalesce(cl, e.class_id);
    end if;
  end if;
  if p_target_person is not null then
    select name into tn from public.persons where id = p_target_person;
  end if;
  -- no scope given → the actor's primary scope
  if ch is null and a.kind = 'servant' then
    select church_id, service_id, class_id into ch, sv, cl from public.servant_enrollments where id = a.id;
  end if;
  insert into public.activity_log
    (actor_kind, actor_id, actor_name, actor_role, table_name, op, action,
     target_kind, target_person_id, target_name, enrollment_id, church_id, service_id, class_id, meta, source)
  values
    (a.kind, a.id, a.name, a.role, split_part(p_action, '.', 1), 'EVENT', p_action,
     case when p_target_person is not null then 'person' end, p_target_person, tn, p_enrollment,
     ch, sv, cl, coalesce(public.activity_trim(p_meta), '{}'::jsonb), 'app')
  returning id into lid;
  return lid;
end $$;
grant execute on function public.log_activity(text, uuid, uuid, jsonb, uuid, uuid, uuid) to authenticated, anon, service_role;

-- Child-portal variant (token instead of auth session)
create or replace function public.child_portal_log_activity(p_token text, p_action text, p_meta jsonb default '{}'::jsonb)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare p public.persons; e public.enrollments;
begin
  p := public.child_portal_person(p_token);   -- stamps app.child_actor
  select * into e from public.enrollments where person_id = p.id and kind = 'child' order by created_at limit 1;
  return public.log_activity(p_action, p.id, e.id, p_meta, e.church_id, e.service_id, e.class_id);
end $$;
grant execute on function public.child_portal_log_activity(text, text, jsonb) to anon, authenticated;

-- child_login / child_logout also leave a trace
create or replace function public.activity_child_login_hook()
returns trigger language plpgsql security definer set search_path = public as $$
declare p public.persons; e public.enrollments;
begin
  if public.activity_off() then return null; end if;
  select * into p from public.persons where id = new.person_id;
  select * into e from public.enrollments where person_id = new.person_id and kind = 'child' order by created_at limit 1;
  insert into public.activity_log
    (actor_kind, actor_id, actor_name, actor_role, table_name, op, action,
     target_kind, target_person_id, target_name, enrollment_id, church_id, service_id, class_id, meta, source)
  values ('child', p.id, p.name, 'child', 'auth', 'EVENT', 'auth.child_login', 'person', p.id, p.name, e.id,
          e.church_id, e.service_id, e.class_id,
          jsonb_build_object('remember', new.remember, 'user_agent', left(new.user_agent, 200)), 'app');
  return null;
end $$;
drop trigger if exists zza_child_login on public.child_sessions;
create trigger zza_child_login after insert on public.child_sessions for each row execute function public.activity_child_login_hook();

-- ---------------------------------------------------------------------
-- 6. READ API
-- ---------------------------------------------------------------------
-- Filters (all optional):
--   actor_kind · actor_id · action (exact) · actions (array) · table_name ·
--   op · target_person_id · enrollment_id · church_id · service_id ·
--   class_id · from · to (timestamptz) · q (text: actor / target / action)
--   · batch_id · row_id
create or replace function public.activity_where(f jsonb)
returns text language sql immutable as $$
  select concat_ws(' and ', 'true',
    case when f->>'actor_kind' is not null then format('actor_kind = %L', f->>'actor_kind') end,
    case when f->>'actor_id' is not null then format('actor_id = %L::uuid', f->>'actor_id') end,
    case when f->>'action' is not null then format('action = %L', f->>'action') end,
    case when f->'actions' is not null and jsonb_typeof(f->'actions') = 'array' and jsonb_array_length(f->'actions') > 0
         then format('action = any(%L::text[])', (select array_agg(x) from jsonb_array_elements_text(f->'actions') x)) end,
    case when f->>'action_prefix' is not null then format('action like %L', (f->>'action_prefix') || '.%') end,
    case when f->>'table_name' is not null then format('table_name = %L', f->>'table_name') end,
    case when f->>'op' is not null then format('op = %L', f->>'op') end,
    case when f->>'target_person_id' is not null then format('target_person_id = %L::uuid', f->>'target_person_id') end,
    case when f->>'enrollment_id' is not null then format('enrollment_id = %L::uuid', f->>'enrollment_id') end,
    case when f->>'row_id' is not null then format('(row_id = %1$L::uuid or target_person_id = %1$L::uuid)', f->>'row_id') end,
    case when f->>'batch_id' is not null then format('batch_id = %L::uuid', f->>'batch_id') end,
    case when f->>'church_id' is not null then format('church_id = %L::uuid', f->>'church_id') end,
    case when f->>'service_id' is not null then format('service_id = %L::uuid', f->>'service_id') end,
    case when f->>'class_id' is not null then format('class_id = %L::uuid', f->>'class_id') end,
    case when f->>'from' is not null then format('created_at >= %L::timestamptz', f->>'from') end,
    case when f->>'to' is not null then format('created_at < %L::timestamptz', f->>'to') end,
    case when nullif(trim(f->>'q'), '') is not null then
      format('(actor_name ilike %1$L or target_name ilike %1$L or action ilike %1$L or table_name ilike %1$L)',
             '%' || trim(f->>'q') || '%') end
  )
$$;

-- Keyset page: newest first. Pass the last row's (created_at, id) to dig further.
create or replace function public.activity_feed(
  p_filters jsonb default '{}'::jsonb,
  p_limit integer default 100,
  p_before timestamptz default null,
  p_before_id uuid default null
) returns setof public.activity_log
language plpgsql stable security invoker set search_path = public as $$
declare lim integer := greatest(1, least(coalesce(p_limit, 100), 1000));
begin
  return query execute format(
    'select * from public.activity_log where %s %s order by created_at desc, id desc limit %s',
    public.activity_where(coalesce(p_filters, '{}'::jsonb)),
    case when p_before is not null then
      format('and (created_at, id) < (%L::timestamptz, %L::uuid)', p_before, coalesce(p_before_id, '00000000-0000-0000-0000-000000000000'::uuid))
    else '' end,
    lim);
end $$;
grant execute on function public.activity_feed(jsonb, integer, timestamptz, uuid) to authenticated;

-- Counts for the dashboard / the «by operation» and «by user» tabs.
create or replace function public.activity_summary(p_filters jsonb default '{}'::jsonb)
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare w text := public.activity_where(coalesce(p_filters, '{}'::jsonb)); out jsonb;
begin
  execute format($q$
    with base as (select * from public.activity_log where %s)
    select jsonb_build_object(
      'total', (select count(*) from base),
      'today', (select count(*) from base where created_at >= date_trunc('day', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo'),
      'first_at', (select min(created_at) from base),
      'last_at', (select max(created_at) from base),
      'by_action', (select coalesce(jsonb_agg(jsonb_build_object('action', action, 'n', n, 'last_at', last_at) order by n desc), '[]')
                      from (select action, count(*) n, max(created_at) last_at from base group by action) x),
      'by_table', (select coalesce(jsonb_agg(jsonb_build_object('table_name', table_name, 'n', n) order by n desc), '[]')
                     from (select table_name, count(*) n from base group by table_name) x),
      'by_op', (select coalesce(jsonb_agg(jsonb_build_object('op', op, 'n', n) order by n desc), '[]')
                  from (select op, count(*) n from base group by op) x),
      'by_actor', (select coalesce(jsonb_agg(jsonb_build_object('actor_kind', actor_kind, 'actor_id', actor_id, 'actor_name', actor_name,
                                                                'actor_role', actor_role, 'n', n, 'last_at', last_at) order by n desc), '[]')
                     from (select actor_kind, actor_id, max(actor_name) actor_name, max(actor_role) actor_role, count(*) n, max(created_at) last_at
                             from base group by actor_kind, actor_id) x),
      'by_day', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'n', n) order by d desc), '[]')
                   from (select (created_at at time zone 'Africa/Cairo')::date as d, count(*) as n
                           from base where created_at > now() - interval '30 days' group by 1) x),
      'by_hour', (select coalesce(jsonb_agg(jsonb_build_object('hour', h, 'n', n) order by h), '[]')
                    from (select extract(hour from created_at at time zone 'Africa/Cairo')::int as h, count(*) as n
                            from base where created_at > now() - interval '7 days' group by 1) x)
    )$q$, w) into out;
  return out;
end $$;
grant execute on function public.activity_summary(jsonb) to authenticated;

-- Every distinct actor (for the «by user» picker) with counts
create or replace function public.activity_actors(p_filters jsonb default '{}'::jsonb)
returns table (actor_kind text, actor_id uuid, actor_name text, actor_role text, n bigint, last_at timestamptz, first_at timestamptz)
language plpgsql stable security invoker set search_path = public as $$
begin
  return query execute format(
    'select actor_kind, actor_id, max(actor_name), max(actor_role), count(*), max(created_at), min(created_at)
       from public.activity_log where %s group by actor_kind, actor_id order by 5 desc',
    public.activity_where(coalesce(p_filters, '{}'::jsonb)));
end $$;
grant execute on function public.activity_actors(jsonb) to authenticated;

-- Everything about ONE person (target OR actor) — the «person history» view
create or replace function public.activity_person_history(p_person uuid, p_limit integer default 200, p_before timestamptz default null)
returns setof public.activity_log language sql stable security invoker set search_path = public as $$
  select * from public.activity_log
   where (target_person_id = p_person or (actor_kind = 'child' and actor_id = p_person))
     and (p_before is null or created_at < p_before)
   order by created_at desc, id desc
   limit greatest(1, least(coalesce(p_limit, 200), 1000))
$$;
grant execute on function public.activity_person_history(uuid, integer, timestamptz) to authenticated;

-- ---------------------------------------------------------------------
-- 7. SETTINGS + HOUSEKEEPING (owner)
-- ---------------------------------------------------------------------
-- app_settings.key = 'activity' → { keep_days: 365, enabled: true }
create or replace function public.activity_settings()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select value from public.app_settings where key = 'activity'), '{}'::jsonb)
         || jsonb_build_object('rows', (select count(*) from public.activity_log),
                               'oldest', (select min(created_at) from public.activity_log))
$$;
grant execute on function public.activity_settings() to authenticated;

create or replace function public.activity_settings_set(p_value jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v jsonb;
begin
  if not public.is_owner() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  v := jsonb_build_object(
    'keep_days', greatest(7, least(coalesce((p_value->>'keep_days')::int, 365), 3650)),
    'enabled', coalesce((p_value->>'enabled')::boolean, true));
  insert into public.app_settings (key, value, updated_by) values ('activity', v, auth.uid())
  on conflict (key) do update set value = excluded.value, updated_at = now(), updated_by = excluded.updated_by;
  return v;
end $$;
grant execute on function public.activity_settings_set(jsonb) to authenticated;

-- Delete rows older than keep_days (or the given number). Owner or cron.
create or replace function public.activity_prune(p_keep_days integer default null)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare days integer; n integer;
begin
  if not (public.is_owner() or auth.role() = 'service_role') then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  days := coalesce(p_keep_days, (select (value->>'keep_days')::int from public.app_settings where key = 'activity'), 365);
  days := greatest(7, days);
  delete from public.activity_log where created_at < now() - make_interval(days => days);
  get diagnostics n = row_count;
  perform public.log_activity('activity.prune', null, null, jsonb_build_object('keep_days', days, 'deleted', n));
  return n;
end $$;
grant execute on function public.activity_prune(integer) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 8. REALTIME (0046 bus) — one message per statement
-- ---------------------------------------------------------------------
-- THROTTLED: a scan burst writes several audit statements (attendance_log
-- insert → enrollments counter update → notification rows …). Each would
-- add a broadcast on top of the ones 0046 already sends, doubling the
-- realtime traffic that migration fought to cut. The log screen is a feed,
-- not a counter, so we send at most ONE `activity_log` message per
-- 3 seconds (gate row in rt_gates) — the screen refetches and catches
-- every row written meanwhile.
create or replace function public.rt_trg_activity_log()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[]; ids uuid[]; ok boolean := false;
begin
  if tg_op <> 'INSERT' then return null; end if;
  insert into public.rt_gates (key, fired_at) values ('activity_log', now())
  on conflict (key) do update set fired_at = now()
    where public.rt_gates.fired_at <= now() - interval '3 seconds'
  returning true into ok;
  if not coalesce(ok, false) then return null; end if;
  select array_agg(distinct church_id) filter (where church_id is not null), array_agg(id) into churches, ids from new_rows;
  if ids is not null then perform public.rt_notify_scope('activity_log', tg_op, churches, ids); end if;
  return null;
end $$;
drop trigger if exists zzz_rt_ins on public.activity_log;
create trigger zzz_rt_ins after insert on public.activity_log referencing new table as new_rows
  for each statement execute function public.rt_trg_activity_log();

-- ---------------------------------------------------------------------
-- 9. Backup restore leaves a trace (0044 disables user triggers on the
--    restored tables, so the log stays quiet during the apply — only the
--    job itself is logged: begin / done / failed)
-- ---------------------------------------------------------------------
do $$ begin
  perform public.activity_audit_attach('backup_restore_jobs');
end $$;



-- #####################################################################
-- ##  0048_scoped_defaults.sql
-- #####################################################################

-- =====================================================================
-- 0048: SCOPED DEFAULTS — الافتراضي لكل مستوى (كنيسة → خدمة → فصل)
--
-- Until now ONE event and ONE cause in the whole database could be
-- "the default" (the app cleared every other `is_default` before
-- saving). That does not fit a diocese: every church needs its own
-- default, a service may want a different one from its church, and a
-- class may want its own again.
--
-- New rule — ONE default PER EXACT SCOPE, resolved most-specific-first:
--
--   scope of the row      meaning
--   ─────────────────     ──────────────────────────────────────────
--   church, null, null    default for the WHOLE church
--   church, service, null default for that SERVICE (overrides church)
--   church, service, cls  default for that CLASS   (overrides service)
--
-- Resolution for a given selection (church → service → class):
--   1. default bound to exactly this class            → use it
--   2. else default bound to exactly this service     → use it
--   3. else default bound to the church (all services) → use it
--   4. else nothing is preselected
--
-- So "if there is a default for the church AND one for the service,
-- the service wins; if the service has none, the church's is used".
--
-- The uniqueness is enforced HERE (trigger) instead of in the app, so
-- the settings forms only need to save `is_default = true`; the other
-- default of the same exact scope is switched off automatically.
-- Defaults of OTHER scopes are never touched.
--
-- Also exposes `default_event_for(church, service, class)` and
-- `default_cause_for(...)` so SQL / RPC callers can resolve the same
-- chain the app resolves (`pickScopedDefault` in src/lib/defaults.ts).
--
-- Idempotent; run after 0047.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. One default per exact scope — events
-- ---------------------------------------------------------------------
create or replace function public.check_event_default_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.is_default and (tg_op = 'INSERT' or not old.is_default
      or old.church_id is distinct from new.church_id
      or old.service_id is distinct from new.service_id
      or old.class_id is distinct from new.class_id) then
    update public.events
       set is_default = false
     where id <> new.id and is_default
       and church_id = new.church_id
       and service_id is not distinct from new.service_id
       and class_id is not distinct from new.class_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_events_default_scope on public.events;
create trigger trg_events_default_scope before insert or update of is_default, church_id, service_id, class_id
  on public.events
  for each row execute function public.check_event_default_scope();

-- ---------------------------------------------------------------------
-- 2. One default per exact scope — causes
-- ---------------------------------------------------------------------
create or replace function public.check_cause_default_scope()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.is_default and (tg_op = 'INSERT' or not old.is_default
      or old.church_id is distinct from new.church_id
      or old.service_id is distinct from new.service_id
      or old.class_id is distinct from new.class_id) then
    update public.causes
       set is_default = false
     where id <> new.id and is_default
       and church_id = new.church_id
       and service_id is not distinct from new.service_id
       and class_id is not distinct from new.class_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_causes_default_scope on public.causes;
create trigger trg_causes_default_scope before insert or update of is_default, church_id, service_id, class_id
  on public.causes
  for each row execute function public.check_cause_default_scope();

-- ---------------------------------------------------------------------
-- 3. Clean up existing data: keep at most ONE default per exact scope
--    (the most recently edited one wins), so the new rule holds for
--    rows written before this migration.
-- ---------------------------------------------------------------------
with ranked as (
  select id,
         row_number() over (
           partition by church_id,
                        coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
                        coalesce(class_id,   '00000000-0000-0000-0000-000000000000'::uuid)
           order by edited_at desc, created_at desc, id
         ) as rn
    from public.events
   where is_default
)
update public.events e set is_default = false
  from ranked r where r.id = e.id and r.rn > 1;

with ranked as (
  select id,
         row_number() over (
           partition by church_id,
                        coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
                        coalesce(class_id,   '00000000-0000-0000-0000-000000000000'::uuid)
           order by edited_at desc, created_at desc, id
         ) as rn
    from public.causes
   where is_default
)
update public.causes c set is_default = false
  from ranked r where r.id = c.id and r.rn > 1;

-- ---------------------------------------------------------------------
-- 4. Indexes for the "find the default of this scope" lookups
-- ---------------------------------------------------------------------
create index if not exists idx_events_default_scope
  on public.events (church_id, service_id, class_id) where is_default;
create index if not exists idx_causes_default_scope
  on public.causes (church_id, service_id, class_id) where is_default;

-- ---------------------------------------------------------------------
-- 5. Resolvers — class → service → church (security invoker: RLS applies)
--    p_service / p_class may be null ("all") → only the wider levels are
--    consulted.
-- ---------------------------------------------------------------------
create or replace function public.default_event_for(p_church uuid, p_service uuid default null, p_class uuid default null)
returns uuid language sql stable security invoker set search_path = public as $$
  select e.id
    from public.events e
   where e.is_default
     and e.church_id = p_church
     and (e.service_id is null or e.service_id = p_service)
     and (e.class_id is null or e.class_id = p_class)
   order by (e.class_id is not null) desc, (e.service_id is not null) desc, e.edited_at desc
   limit 1
$$;

create or replace function public.default_cause_for(p_church uuid, p_service uuid default null, p_class uuid default null)
returns uuid language sql stable security invoker set search_path = public as $$
  select c.id
    from public.causes c
   where c.is_default
     and c.church_id = p_church
     and (c.service_id is null or c.service_id = p_service)
     and (c.class_id is null or c.class_id = p_class)
   order by (c.class_id is not null) desc, (c.service_id is not null) desc, c.edited_at desc
   limit 1
$$;

grant execute on function public.default_event_for(uuid, uuid, uuid) to authenticated;
grant execute on function public.default_cause_for(uuid, uuid, uuid) to authenticated;

comment on function public.default_event_for(uuid, uuid, uuid) is
  'Default event for a selection, most specific first: class → service → church (0048).';
comment on function public.default_cause_for(uuid, uuid, uuid) is
  'Default points cause for a selection, most specific first: class → service → church (0048).';


-- #####################################################################
-- ##  0049_card_print_profiles.sql
-- #####################################################################

-- =====================================================================
-- 0049: CARD PRINT PROFILES (ملفات الطباعة) + service / class logos on cards
--
-- 1. `card_print_profiles` — a NAMED, reusable set of print settings
--    (paper · orientation · margins · gaps · alignment · cut marks ·
--    center lines). Until now the print settings lived only INSIDE each
--    template (`card_templates.print_settings`) or in the browser's
--    localStorage on the bound-print page — so the same «A4 · 2×5 ·
--    هوامش 10» had to be typed again for every template and on every
--    device. A profile is saved once and applied to ANY template (the
--    designer's print tab, the birthday card print tab) or to the bound
--    print page. Applying COPIES the settings into the template — the
--    template keeps working even if the profile is deleted later.
--
--    Scope: church → service → class, exactly like the templates. A
--    servant READS every profile whose scope overlaps his (the church-wide
--    one, his service's, his class's) and WRITES only at his own level or
--    below. `church_id NULL` = shared with everyone who can see the cards
--    module (only the owner can write such rows — `can_access(null, …)` is
--    false for every other role).
--
-- 2. `child_portal_birthday()` now returns `service_logo_url` and
--    `class_logo_url` in `constants`, so birthday cards that use the new
--    «شعار الخدمة» / «شعار الفصل» elements render in the child portal too.
--    (The staff screens read `services.photo_url` / `classes.photo_url`
--    directly — no schema change was needed for the logos themselves.)
--
-- Idempotent; run after 0048.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Table
-- ---------------------------------------------------------------------
create table if not exists public.card_print_profiles (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  name        text not null,
  settings    jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint card_print_profiles_name_chk check (length(trim(name)) between 1 and 80),
  -- a class-level row must name its service; a service-level row its church
  constraint card_print_profiles_scope_chk check (
    (class_id is null or service_id is not null) and (service_id is null or church_id is not null)
  )
);

comment on table public.card_print_profiles is
  'ملفات الطباعة — named reusable print settings (paper / margins / gaps / alignment) for the card designer. church_id NULL = shared.';

create index if not exists idx_card_print_profiles_church on public.card_print_profiles(church_id);

drop trigger if exists trg_card_print_profiles_touch on public.card_print_profiles;
create trigger trg_card_print_profiles_touch before update on public.card_print_profiles
for each row execute function public.touch_edited();

-- ---------------------------------------------------------------------
-- 2. RLS — module `cards` + scope.
--    READ : shared rows (church_id null) + every profile whose scope
--           OVERLAPS mine (`scope_overlaps`, 0045) — a class servant can
--           USE the profile his service manager saved for the whole
--           service (and the church-wide one), which is the point of
--           saving a profile once.
--    WRITE: `can_access` — I can only create / edit / delete profiles at
--           my own level or below (shared rows → owner only).
-- ---------------------------------------------------------------------
alter table public.card_print_profiles enable row level security;

drop policy if exists card_print_profiles_select on public.card_print_profiles;
create policy card_print_profiles_select on public.card_print_profiles for select using (
  (select public.module_visible('cards'))
  and (church_id is null or (select public.scope_overlaps(church_id, service_id, class_id)))
);

drop policy if exists card_print_profiles_insert on public.card_print_profiles;
create policy card_print_profiles_insert on public.card_print_profiles for insert with check (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);

drop policy if exists card_print_profiles_update on public.card_print_profiles;
create policy card_print_profiles_update on public.card_print_profiles for update using (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
) with check (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);

drop policy if exists card_print_profiles_delete on public.card_print_profiles;
create policy card_print_profiles_delete on public.card_print_profiles for delete using (
  (select public.module_visible('cards'))
  and (select public.can_access(church_id, service_id, class_id))
);

-- ---------------------------------------------------------------------
-- 3. Realtime (classic postgres_changes — low-volume table) + activity log
-- ---------------------------------------------------------------------
do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'card_print_profiles') then
    alter publication supabase_realtime add table public.card_print_profiles;
  end if;
exception when undefined_object then null;
end $$;

do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('card_print_profiles');
  end if;
end $$;

-- register the table in the audited list (0047) so a re-run of 0047 keeps it
create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules'
  ]
$$;

-- ---------------------------------------------------------------------
-- 4. child_portal_birthday — add service / class logos to `constants`
--    (guarded: the function declares row types of the birthdays module 0028)
-- ---------------------------------------------------------------------
do $outer$ begin
  if to_regclass('public.birthday_card_templates') is null then return; end if;
  execute $fn$
create or replace function public.child_portal_birthday(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
  today date := (now() at time zone 'Africa/Cairo')::date;
  e public.enrollments;
  tpl public.birthday_card_templates;
  ch public.churches;
  sv public.services;
  cl public.classes;
  granted boolean := false;
  nb date;
begin
  p := public.child_portal_person(p_national_id);
  if p.birthdate is null then return jsonb_build_object('is_birthday', false, 'birthdate', null); end if;
  nb := public.next_birthday(p.birthdate, today);

  select * into e from public.enrollments where person_id = p.id order by created_at, id limit 1;
  if e.id is not null then
    granted := public.module_granted_for('birthdays', e.church_id, e.service_id, e.class_id);
    select * into ch from public.churches where id = e.church_id;
    select * into sv from public.services where id = e.service_id;
    select * into cl from public.classes  where id = e.class_id;
    if granted then
      select * into tpl from public.birthday_card_templates t
       where t.church_id = e.church_id
         and (t.service_id is null or t.service_id = e.service_id)
         and (t.class_id is null or t.class_id = e.class_id)
       -- most specific scope wins (class > service > church), then the default flag, then newest
       order by (t.class_id is not null) desc, (t.service_id is not null) desc, t.is_default desc, t.created_at desc
       limit 1;
    end if;
  end if;

  return jsonb_build_object(
    'is_birthday', nb = today,
    'birthdate', p.birthdate,
    'age', extract(year from age(today, p.birthdate))::int,
    'turns_age', extract(year from nb)::int - extract(year from p.birthdate)::int,
    'next_birthday', nb,
    'days_left', (nb - today),
    'module_granted', granted,
    'card', case when tpl.id is null then null else jsonb_build_object(
              'id', tpl.id, 'name', tpl.name, 'design', tpl.design) end,
    'constants', jsonb_build_object(
      'church_name', coalesce(ch.name, ''), 'service_name', coalesce(sv.name, ''),
      'class_name', coalesce(cl.name, ''), 'church_logo_url', ch.logo_url,
      'service_logo_url', sv.photo_url, 'class_logo_url', cl.photo_url),
    'gift', (select jsonb_build_object('points', g.points, 'created_at', g.created_at)
               from public.birthday_greetings g
              where g.person_id = p.id and g.kind = 'gift' and g.year = extract(year from today)::int
              limit 1)
  );
end $$;
  $fn$;
  grant execute on function public.child_portal_birthday(text) to anon, authenticated;
end $outer$;


-- #####################################################################
-- ##  0050_report_templates.sql
-- #####################################################################

-- =====================================================================
-- 0050: REPORTS & TABLES MODULE (تقارير وجداول) — report templates
--
-- The module lets a servant pick a DATA SOURCE (المخدومون · الحضور ·
-- النقاط · نتائج الامتحانات · الخدام), narrow it (كنيسة → خدمة → فصل ·
-- فترة · مناسبة · …), choose EXACTLY the fields he wants (order · title ·
-- filter · sort), preview the rows, arrange a REPORT on pages (title ·
-- text · logo · table · chart · variables · header / footer / page
-- numbers) and export it as PDF / Excel or print it.
--
-- Everything the module reads already exists and is already protected by
-- RLS (enrollments / persons / attendance_log / points_log / exam_results
-- / servant_enrollments …) — the browser only ever gets the rows the
-- caller may see. The ONLY new table is `report_templates`: a saved
-- design (the whole report definition as JSONB) that can be re-run later
-- against a new church / service / class / period.
--
-- Scope: church → service → class (null = shared with everyone who can
-- see the module — owner-only to write). READ = every template whose
-- scope overlaps mine (`scope_overlaps`, 0045); WRITE = `can_access`
-- (my level or below). Same rules as `card_print_profiles` (0049).
--
-- Idempotent; run after 0049.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Table
-- ---------------------------------------------------------------------
create table if not exists public.report_templates (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  name        text not null,
  description text,
  -- the data source key (app-code: 'enrollments' | 'attendance' | 'points' | 'exam_results' | 'servants' …)
  source      text not null,
  -- the whole report definition: { version, query: { filters, fields, sort }, design: { pages, header, footer, … } }
  definition  jsonb not null default '{}'::jsonb,
  is_default  boolean not null default false,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint report_templates_name_chk check (length(trim(name)) between 1 and 120),
  constraint report_templates_source_chk check (source ~ '^[a-z][a-z0-9_]{1,40}$'),
  -- a class-level row must name its service; a service-level row its church
  constraint report_templates_scope_chk check (
    (class_id is null or service_id is not null) and (service_id is null or church_id is not null)
  )
);

comment on table public.report_templates is
  'قوالب التقارير والجداول — saved report definitions (data query + page design) re-runnable against a new scope. church_id NULL = shared.';

create index if not exists idx_report_templates_church on public.report_templates(church_id);
create index if not exists idx_report_templates_source on public.report_templates(source);

drop trigger if exists trg_report_templates_touch on public.report_templates;
create trigger trg_report_templates_touch before update on public.report_templates
for each row execute function public.touch_edited();

-- ---------------------------------------------------------------------
-- 2. RLS — module `reports` + scope.
-- ---------------------------------------------------------------------
alter table public.report_templates enable row level security;

drop policy if exists report_templates_select on public.report_templates;
create policy report_templates_select on public.report_templates for select using (
  (select public.module_visible('reports'))
  and (church_id is null or (select public.scope_overlaps(church_id, service_id, class_id)))
);

drop policy if exists report_templates_insert on public.report_templates;
create policy report_templates_insert on public.report_templates for insert with check (
  (select public.module_visible('reports'))
  and (select public.can_access(church_id, service_id, class_id))
);

drop policy if exists report_templates_update on public.report_templates;
create policy report_templates_update on public.report_templates for update using (
  (select public.module_visible('reports'))
  and (select public.can_access(church_id, service_id, class_id))
) with check (
  (select public.module_visible('reports'))
  and (select public.can_access(church_id, service_id, class_id))
);

drop policy if exists report_templates_delete on public.report_templates;
create policy report_templates_delete on public.report_templates for delete using (
  (select public.module_visible('reports'))
  and (select public.can_access(church_id, service_id, class_id))
);

-- ---------------------------------------------------------------------
-- 3. Realtime (low-volume table) + activity log
-- ---------------------------------------------------------------------
do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'report_templates') then
    alter publication supabase_realtime add table public.report_templates;
  end if;
exception when undefined_object then null;
end $$;

do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('report_templates');
  end if;
end $$;

-- register the table in the audited list (0047) so a re-run of 0047 keeps it
create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules', 'report_templates'
  ]
$$;

-- ---------------------------------------------------------------------
-- 4. Aggregation helper for the report engine — attendance / points of a
--    set of enrollments INSIDE a period (the browser never downloads the
--    log rows for a whole scope; it asks for per-enrollment totals).
--    RLS on the log tables still applies (security invoker).
-- ---------------------------------------------------------------------
create or replace function public.report_enrollment_period_stats(
  p_enrollments uuid[],
  p_from date default null,
  p_to   date default null,
  p_event uuid default null
)
returns table (
  enrollment_id    uuid,
  attendance_count bigint,      -- attendance rows in the period (optionally one event)
  attendance_points bigint,     -- points that came with that attendance
  points_added     bigint,      -- positive cause deltas in the period
  points_removed   bigint,      -- abs(negative cause deltas) in the period
  first_attended   date,
  last_attended    date,
  calls_count      bigint,      -- follow-up calls in the period
  messages_count   bigint       -- whatsapp / sms / internal in the period
)
language sql stable security invoker set search_path = public as $$
  with ids as (select unnest(p_enrollments) as id),
  att as (
    select a.enrollment_id, count(*) c, coalesce(sum(a.points_delta), 0) p, min(a.attended_on) f, max(a.attended_on) l
      from public.attendance_log a join ids on ids.id = a.enrollment_id
     where (p_from is null or a.attended_on >= p_from)
       and (p_to   is null or a.attended_on <= p_to)
       and (p_event is null or a.event_id = p_event)
     group by a.enrollment_id
  ),
  pts as (
    select l.enrollment_id,
           coalesce(sum(case when l.delta > 0 then l.delta else 0 end), 0) added,
           coalesce(-sum(case when l.delta < 0 then l.delta else 0 end), 0) removed
      from public.points_log l join ids on ids.id = l.enrollment_id
     where (p_from is null or (l.created_at at time zone 'Africa/Cairo')::date >= p_from)
       and (p_to   is null or (l.created_at at time zone 'Africa/Cairo')::date <= p_to)
       and (p_event is null or l.event_id = p_event)
     group by l.enrollment_id
  ),
  con as (
    select c.enrollment_id,
           count(*) filter (where c.kind = 'call') calls,
           count(*) filter (where c.kind <> 'call') msgs
      from public.contact_log c join ids on ids.id = c.enrollment_id
     where (p_from is null or c.contacted_on >= p_from)
       and (p_to   is null or c.contacted_on <= p_to)
       and (p_event is null or c.event_id = p_event)
     group by c.enrollment_id
  )
  select ids.id,
         coalesce(att.c, 0), coalesce(att.p, 0),
         coalesce(pts.added, 0), coalesce(pts.removed, 0),
         att.f, att.l,
         coalesce(con.calls, 0), coalesce(con.msgs, 0)
    from ids
    left join att on att.enrollment_id = ids.id
    left join pts on pts.enrollment_id = ids.id
    left join con on con.enrollment_id = ids.id
$$;

grant execute on function public.report_enrollment_period_stats(uuid[], date, date, uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 5. No seed — like the other modules the OWNER grants the module from
--    وحدة المالك → صلاحيات الوحدات (owner always sees it).
-- ---------------------------------------------------------------------


-- #####################################################################
-- ##  0051_fix_app_settings_names_validation.sql
-- #####################################################################

-- =====================================================================
-- 0051: FIX — saving «الأسماء المخصصة» (app_settings.names) failed
--
-- 0040 rewrote validate_app_settings() and declared a loop variable
-- `kv record` for the code-system scope check. The older `names` check
-- (0036) uses `kv` as the SQL alias of jsonb_each(new.value) — PL/pgSQL
-- resolves `kv.value` to the (never assigned) record variable first and
-- raises:  record "kv" is not assigned yet.
-- Every insert / update of the 'names' key has been failing since 0040
-- (تخصيص التطبيق → الأسماء). This migration recreates the function with
-- the loop record renamed (`sc`); the checks themselves are unchanged.
--
-- Idempotent; run after 0050.
-- =====================================================================


create or replace function public.validate_app_settings()
returns trigger language plpgsql as $$
declare g text; gen jsonb; sc record;
begin
  if jsonb_typeof(new.value) <> 'object' then
    raise exception 'app_settings.value must be a JSON object (key %)', new.key;
  end if;
  if new.key = 'names' then
    if exists (
      select 1 from jsonb_each(new.value) kv
       where jsonb_typeof(kv.value) <> 'string'
          or length(kv.value #>> '{}') = 0
          or length(kv.value #>> '{}') > 30
    ) then
      raise exception 'app_settings.names: every label must be a 1–30 character string';
    end if;
  end if;
  if new.key = 'widgets' then
    if jsonb_typeof(new.value -> 'items') <> 'array'
       or jsonb_array_length(new.value -> 'items') > 40 then
      raise exception 'app_settings.widgets: items must be an array (max 40)';
    end if;
  end if;
  if new.key = 'codes' then
    perform public.validate_code_template(new.value -> 'default', 'default');
    if jsonb_array_length(new.value -> 'default' -> 'parts') = 0 then
      raise exception 'app_settings.codes: default template needs at least one part';
    end if;
    if new.value ? 'generators' then
      if jsonb_typeof(new.value -> 'generators') <> 'object' then
        raise exception 'app_settings.codes: generators must be an object';
      end if;
      for g, gen in select * from jsonb_each(new.value -> 'generators') loop
        if g not in ('person', 'servant', 'store_item', 'ticket') then
          raise exception 'app_settings.codes: unknown generator %', g;
        end if;
        if coalesce(gen ->> 'mode', 'legacy') not in ('default', 'custom', 'legacy') then
          raise exception 'app_settings.codes: generator % has an invalid mode', g;
        end if;
        if gen ? 'template' then perform public.validate_code_template(gen -> 'template', g); end if;
        if gen ->> 'mode' = 'custom' and jsonb_array_length(coalesce(gen -> 'template' -> 'parts', '[]'::jsonb)) = 0 then
          raise exception 'app_settings.codes: generator % is custom but has no parts', g;
        end if;
      end loop;
    end if;
    if new.value ? 'scopes' then
      for sc in
        select m.key as grp, e.key as id, e.value as abbr
          from jsonb_each(new.value -> 'scopes') m
          cross join lateral jsonb_each(m.value) e
      loop
        if sc.grp not in ('churches', 'services', 'classes') then
          raise exception 'app_settings.codes: unknown scope group %', sc.grp;
        end if;
        if jsonb_typeof(sc.abbr) <> 'string' or (sc.abbr #>> '{}') !~ '^[A-Za-z0-9._-]{1,8}$' then
          raise exception 'app_settings.codes: abbreviation for % must be 1–8 safe characters', sc.id;
        end if;
      end loop;
    end if;
  end if;
  return new;
end $$;

-- the trigger from 0040 (trg_validate_app_settings) stays bound to the function



-- #####################################################################
-- ##  20260922120000_backup_restore_fk_order.sql
-- #####################################################################

-- =====================================================================
-- 20260922120000: BACKUP RESTORE — FK cycles, deferred references,
--                 login accounts first
--
-- BUG (production): restoring a backup failed with
--   insert or update on table "app_settings" violates foreign key
--   constraint "app_settings_updated_by_fkey"
--
-- WHY: the schema has an FK CYCLE
--   persons.created_by / edited_by  → servant_enrollments
--   servant_enrollments.person_id   → persons
--   servant_enrollments.approved_by → servant_enrollments (self)
-- backup_topo_order() (0044) stopped at the first cycle and appended the
-- WHOLE remainder alphabetically, so app_settings (and ~55 other tables
-- that point at servant_enrollments) were applied BEFORE the servants.
-- Two more holes: servant_enrollments.id → auth.users, but the client
-- restored the login accounts LAST; and an audit column (updated_by …)
-- pointing at a servant that no longer exists (e.g. the owner got a new
-- id after a reset) aborted the whole restore.
--
-- FIX:
--   * backup_fk_edges(t)         — every FK of a table: column, parent
--                                  (schema-qualified), parent column,
--                                  nullable, on-delete rule
--   * backup_topo_order(tables)  — cycle-aware Kahn: when stuck, take the
--                                  table whose NOT NULL parents are all
--                                  ordered (its nullable refs are deferred)
--   * backup_restore_apply_chunk — TWO-PHASE: a nullable FK value whose
--                                  parent row does not exist yet is
--                                  inserted as NULL and remembered in
--                                  backup_restore_fixups; a row whose
--                                  NOT NULL parent lives outside public
--                                  (auth.users) and is missing is SKIPPED
--                                  and reported instead of aborting
--   * backup_restore_fixup(job)  — after every chunk: re-attach the
--                                  deferred references whose parent now
--                                  exists; the rest is reported as
--                                  «unresolved» (value stays NULL)
--   * backup_restore_delete_missing — replace mode: nullable references
--                                  (NO ACTION / RESTRICT) to the rows
--                                  about to be deleted are detached first
--                                  so a cycle cannot block the delete
--   * result per table: upserted · deleted · deferred · resolved ·
--                       unresolved (+ samples) · skipped (+ samples)
-- Client (src/lib/backup.ts) now restores the login accounts FIRST and
-- calls backup_restore_fixup before backup_restore_finish.
-- Idempotent. Depends on 0044.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Staging table for deferred references
-- ---------------------------------------------------------------------
create table if not exists public.backup_restore_fixups (
  job_id      uuid  not null references public.backup_restore_jobs(id) on delete cascade,
  table_name  text  not null,
  column_name text  not null,
  pk          jsonb not null,           -- {pkcol: value, …} of the child row
  value       jsonb not null,           -- the original FK value
  primary key (job_id, table_name, column_name, pk)
);
alter table public.backup_restore_fixups enable row level security;
comment on table public.backup_restore_fixups is
  'مرحلة الاسترجاع — مراجع (FK) اختيارية أُدخلت NULL لأن الصف الأب لم يكن موجودًا بعد؛ تُعاد بعد تطبيق كل الجداول';

-- ---------------------------------------------------------------------
-- 2. FK catalogue
-- ---------------------------------------------------------------------
-- Every single-column FK of a public table (multi-column FKs are rare and
-- returned with column = null so callers can ignore them).
create or replace function public.backup_fk_edges(t text)
returns table (
  column_name   text,
  column_type   text,
  nullable      boolean,
  parent_schema text,
  parent_table  text,
  parent_column text,
  on_delete     "char",
  constraint_name text
) language sql stable as $$
  select case when array_length(f.conkey, 1) = 1 then a.attname::text end,
         format_type(a.atttypid, a.atttypmod),
         not a.attnotnull,
         pn.nspname::text,
         p.relname::text,
         case when array_length(f.confkey, 1) = 1 then pa.attname::text end,
         f.confdeltype,
         f.conname::text
    from pg_constraint f
    join pg_class c on c.oid = f.conrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_class p on p.oid = f.confrelid
    join pg_namespace pn on pn.oid = p.relnamespace
    left join pg_attribute a  on a.attrelid  = c.oid and a.attnum  = f.conkey[1]  and array_length(f.conkey, 1) = 1
    left join pg_attribute pa on pa.attrelid = p.oid and pa.attnum = f.confkey[1] and array_length(f.confkey, 1) = 1
   where f.contype = 'f' and n.nspname = 'public' and c.relname = t
$$;

-- parents reached through at least one NOT NULL column (these cannot be
-- deferred — the parent MUST be applied first)
create or replace function public.backup_parents_required(t text)
returns text[] language sql stable as $$
  select coalesce(array_agg(distinct p.relname::text), '{}')
    from pg_constraint f
    join pg_class c on c.oid = f.conrelid
    join pg_class p on p.oid = f.confrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_namespace pn on pn.oid = p.relnamespace
   where f.contype = 'f' and n.nspname = 'public' and pn.nspname = 'public'
     and c.relname = t and p.relname <> t
     and exists (select 1 from unnest(f.conkey) k
                 join pg_attribute a on a.attrelid = c.oid and a.attnum = k
                 where a.attnotnull)
$$;

-- Cycle-aware Kahn order (parents first). When no table is free, the one
-- whose REQUIRED parents are all ordered is taken (fewest pending
-- nullable parents first, then by name) — its nullable references are
-- deferred by backup_restore_apply_chunk. Only a NOT NULL cycle (which
-- could never be inserted anyway) falls back to «the rest as-is».
create or replace function public.backup_topo_order(p_tables text[])
returns text[] language plpgsql stable as $$
declare
  remaining text[] := (select coalesce(array_agg(distinct x order by x), '{}') from unnest(p_tables) x);
  ordered   text[] := '{}';
  t text; progressed boolean; pick text;
begin
  while cardinality(remaining) > 0 loop
    progressed := false;
    foreach t in array remaining loop
      if not exists (
        select 1 from unnest(public.backup_parents(t)) p
         where p = any(remaining) and not (p = any(ordered))
      ) then
        ordered := ordered || t;
        remaining := array_remove(remaining, t);
        progressed := true;
      end if;
    end loop;
    if not progressed then
      select r into pick
        from unnest(remaining) r
       where not exists (select 1 from unnest(public.backup_parents_required(r)) p
                          where p = any(remaining) and not (p = any(ordered)))
       order by (select count(*) from unnest(public.backup_parents(r)) p
                  where p = any(remaining) and not (p = any(ordered))),          -- fewest deferred refs
                (select count(*) from unnest(remaining) c
                  where c <> r and r = any(public.backup_parents(c))) desc,      -- unblocks the most tables
                r
       limit 1;
      if pick is null then           -- NOT NULL cycle: append the rest as-is
        ordered := ordered || remaining;
        exit;
      end if;
      ordered := ordered || pick;
      remaining := array_remove(remaining, pick);
    end if;
  end loop;
  return ordered;
end $$;

-- ---------------------------------------------------------------------
-- 3. Apply one chunk — two-phase
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_apply_chunk(p_job uuid, p_table text, p_seq integer)
returns integer language plpgsql security definer set search_path = public as $$
declare
  j public.backup_restore_jobs; chunk jsonb; pk text[]; cols text[]; backup_cols text[];
  col_list text; sel_exprs text[]; sel_list text; set_list text; pk_list text; pk_json text; n integer; pos integer;
  e record; where_skip text := ''; deferred integer := 0; skipped integer := 0; skip_samples jsonb := '[]'::jsonb;
  tbl_result jsonb;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.status not in ('staging', 'applying') then raise exception 'job_closed' using errcode = 'P0001'; end if;
  if not (p_table = any(j.tables)) then raise exception 'table_not_in_job' using errcode = 'P0001'; end if;

  select rows into chunk from public.backup_restore_rows
   where job_id = p_job and table_name = p_table and seq = p_seq for update;
  if chunk is null then raise exception 'chunk_not_found' using errcode = 'P0001'; end if;
  if jsonb_array_length(chunk) = 0 then return 0; end if;

  pk := public.backup_pk_columns(p_table);
  cols := public.backup_columns(p_table);
  select coalesce(array_agg(x), '{}') into backup_cols
    from jsonb_array_elements_text(coalesce(j.meta->'columns'->p_table, (select jsonb_agg(k) from jsonb_object_keys(chunk->0) k))) x;
  cols := (select coalesce(array_agg(c order by ord), '{}') from unnest(cols) with ordinality as cc(c, ord) where c = any(backup_cols));
  if cardinality(cols) = 0 then raise exception 'no_columns' using errcode = 'P0001'; end if;

  select string_agg(format('%I', c), ', ') into col_list from unnest(cols) c;
  select coalesce(array_agg(format('r.%I', c) order by ord), '{}') into sel_exprs from unnest(cols) with ordinality as cc(c, ord);
  select string_agg(format('%I', c), ', ') into pk_list  from unnest(pk) c;
  select string_agg(format('%L, r.%I', c, c), ', ') into pk_json from unnest(pk) c;
  select string_agg(format('%1$I = excluded.%1$I', c), ', ') into set_list
    from unnest(cols) c where not (c = any(pk));

  -- FK handling, column by column
  for e in select * from public.backup_fk_edges(p_table)
            where column_name is not null and parent_column is not null and column_name = any(cols)
  loop
    if e.nullable and pk_list is not null and not (e.column_name = any(pk)) then
      -- DEFER: value → NULL when the parent row is not there yet; remember it
      execute format(
        'insert into public.backup_restore_fixups (job_id, table_name, column_name, pk, value)
           select $1, $2, %1$L, jsonb_build_object(%2$s), to_jsonb(r.%3$I)
             from jsonb_populate_recordset(null::public.%4$I, $3) r
            where r.%3$I is not null
              and not exists (select 1 from %5$I.%6$I p where p.%7$I = r.%3$I)
         on conflict do nothing',
        e.column_name, pk_json, e.column_name, p_table, e.parent_schema, e.parent_table, e.parent_column)
        using p_job, p_table, chunk;
      get diagnostics n = row_count;
      deferred := deferred + n;
      pos := array_position(cols, e.column_name);
      sel_exprs[pos] := format('(case when exists (select 1 from %I.%I p where p.%I = r.%I) then r.%I else null end)',
                               e.parent_schema, e.parent_table, e.parent_column, e.column_name, e.column_name);
    elsif not e.nullable and e.parent_schema <> 'public' then
      -- e.g. servant_enrollments.id → auth.users: the account must exist.
      -- Rows without it are skipped (reported), never abort the restore.
      execute format(
        'select count(*), coalesce(jsonb_agg(to_jsonb(r.%1$I)) filter (where rn <= 5), ''[]''::jsonb)
           from (select r.*, row_number() over () rn
                   from jsonb_populate_recordset(null::public.%2$I, $1) r
                  where not exists (select 1 from %3$I.%4$I p where p.%5$I = r.%1$I)) r',
        e.column_name, p_table, e.parent_schema, e.parent_table, e.parent_column)
        into n, skip_samples using chunk;
      if n > 0 then
        skipped := skipped + n;
        where_skip := where_skip || format(' and exists (select 1 from %I.%I p where p.%I = r.%I)',
                                           e.parent_schema, e.parent_table, e.parent_column, e.column_name);
      end if;
    end if;
  end loop;

  sel_list := array_to_string(sel_exprs, ', ');
  execute format('alter table public.%I disable trigger user', p_table);
  if pk_list is null then
    execute format('insert into public.%1$I (%2$s) select %3$s from jsonb_populate_recordset(null::public.%1$I, $1) r where true %4$s',
                   p_table, col_list, sel_list, where_skip) using chunk;
  elsif set_list is null then
    execute format('insert into public.%1$I (%2$s) select %3$s from jsonb_populate_recordset(null::public.%1$I, $1) r where true %5$s on conflict (%4$s) do nothing',
                   p_table, col_list, sel_list, pk_list, where_skip) using chunk;
  else
    execute format('insert into public.%1$I (%2$s) select %3$s from jsonb_populate_recordset(null::public.%1$I, $1) r where true %6$s on conflict (%4$s) do update set %5$s',
                   p_table, col_list, sel_list, pk_list, set_list, where_skip) using chunk;
  end if;
  get diagnostics n = row_count;
  execute format('alter table public.%I enable trigger user', p_table);

  update public.backup_restore_rows set applied = true
   where job_id = p_job and table_name = p_table and seq = p_seq;

  select coalesce(result->p_table, '{}'::jsonb) into tbl_result from public.backup_restore_jobs where id = p_job;
  tbl_result := tbl_result
    || jsonb_build_object('upserted', coalesce((tbl_result->>'upserted')::int, 0) + n)
    || jsonb_build_object('deferred', coalesce((tbl_result->>'deferred')::int, 0) + deferred)
    || jsonb_build_object('skipped',  coalesce((tbl_result->>'skipped')::int, 0) + skipped);
  if skipped > 0 then
    tbl_result := tbl_result || jsonb_build_object('skipped_samples',
      (select coalesce(jsonb_agg(x), '[]'::jsonb) from (
         select x from jsonb_array_elements(coalesce(tbl_result->'skipped_samples', '[]'::jsonb) || skip_samples) x limit 5) s));
  end if;
  update public.backup_restore_jobs set result = jsonb_set(result, array[p_table], tbl_result, true) where id = p_job;
  return n;
end $$;
revoke all on function public.backup_restore_apply_chunk(uuid, text, integer) from public;
grant execute on function public.backup_restore_apply_chunk(uuid, text, integer) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 4. Re-attach the deferred references (call once after every chunk)
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_fixup(p_job uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  j public.backup_restore_jobs; r record; e record; pk text[]; pk_match text; n integer;
  out jsonb := '{}'::jsonb; tbl_result jsonb; resolved integer; unresolved integer; samples jsonb;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.status not in ('staging', 'applying') then raise exception 'job_closed' using errcode = 'P0001'; end if;

  for r in select distinct table_name from public.backup_restore_fixups where job_id = p_job order by 1 loop
    pk := public.backup_pk_columns(r.table_name);
    select string_agg(format('%L, x.%I', c, c), ', ') into pk_match from unnest(pk) c;
    resolved := 0;
    execute format('alter table public.%I disable trigger user', r.table_name);
    for e in select f.column_name, f.column_type, f.parent_schema, f.parent_table, f.parent_column
               from public.backup_fk_edges(r.table_name) f
              where f.column_name in (select distinct column_name from public.backup_restore_fixups
                                       where job_id = p_job and table_name = r.table_name)
    loop
      execute format(
        'update public.%1$I x set %2$I = (f.value #>> ''{}'')::%3$s
           from public.backup_restore_fixups f
          where f.job_id = $1 and f.table_name = $2 and f.column_name = %2$L
            and jsonb_build_object(%4$s) = f.pk
            and exists (select 1 from %5$I.%6$I p where p.%7$I = (f.value #>> ''{}'')::%3$s)',
        r.table_name, e.column_name, e.column_type, pk_match, e.parent_schema, e.parent_table, e.parent_column)
        using p_job, r.table_name;
      get diagnostics n = row_count;
      resolved := resolved + n;
      execute format(
        'delete from public.backup_restore_fixups f
          where f.job_id = $1 and f.table_name = $2 and f.column_name = %1$L
            and exists (select 1 from %2$I.%3$I p where p.%4$I = (f.value #>> ''{}'')::%5$s)',
        e.column_name, e.parent_schema, e.parent_table, e.parent_column, e.column_type)
        using p_job, r.table_name;
    end loop;
    execute format('alter table public.%I enable trigger user', r.table_name);

    select count(*), coalesce(jsonb_agg(jsonb_build_object('pk', s.pk, 'column', s.column_name, 'value', s.value)) filter (where s.rn <= 5), '[]'::jsonb)
      into unresolved, samples
      from (select f.pk, f.column_name, f.value, row_number() over (order by f.column_name, f.pk) rn
              from public.backup_restore_fixups f where f.job_id = p_job and f.table_name = r.table_name) s;

    select coalesce(result->r.table_name, '{}'::jsonb) into tbl_result from public.backup_restore_jobs where id = p_job;
    tbl_result := tbl_result
      || jsonb_build_object('resolved', coalesce((tbl_result->>'resolved')::int, 0) + resolved,
                            'unresolved', unresolved, 'unresolved_samples', samples);
    update public.backup_restore_jobs set result = jsonb_set(result, array[r.table_name], tbl_result, true) where id = p_job;
    out := out || jsonb_build_object(r.table_name, jsonb_build_object('resolved', resolved, 'unresolved', unresolved));
  end loop;
  return out;
end $$;
revoke all on function public.backup_restore_fixup(uuid) from public;
grant execute on function public.backup_restore_fixup(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 5. Replace mode — detach nullable references before deleting
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_delete_missing(p_job uuid, p_table text)
returns integer language plpgsql security definer set search_path = public as $$
declare
  j public.backup_restore_jobs; pk text[]; keyexpr text; n integer; e record; detached integer := 0; m integer;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  select * into j from public.backup_restore_jobs where id = p_job;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  if j.mode <> 'replace' then return 0; end if;
  if not (p_table = any(j.tables)) then raise exception 'table_not_in_job' using errcode = 'P0001'; end if;
  pk := public.backup_pk_columns(p_table);
  if cardinality(pk) = 0 then return 0; end if;
  select string_agg(format('coalesce(t.%I::text, '''')', c), ' || ''|'' || ' order by ord)
    into keyexpr from unnest(pk) with ordinality as pc(c, ord);

  -- children that point at the doomed rows through a NULLABLE column with
  -- NO ACTION / RESTRICT: set the reference to NULL (otherwise the delete
  -- is refused — this is how the persons ⇄ servants cycle is broken)
  for e in
    select c.relname::text as child, a.attname::text as col, pa.attname::text as pcol
      from pg_constraint f
      join pg_class c on c.oid = f.conrelid
      join pg_namespace n on n.oid = c.relnamespace
      join pg_class p on p.oid = f.confrelid
      join pg_namespace pn on pn.oid = p.relnamespace
      join pg_attribute a  on a.attrelid  = c.oid and a.attnum  = f.conkey[1]
      join pg_attribute pa on pa.attrelid = p.oid and pa.attnum = f.confkey[1]
     where f.contype = 'f' and n.nspname = 'public' and pn.nspname = 'public'
       and p.relname = p_table and array_length(f.conkey, 1) = 1
       and not a.attnotnull and f.confdeltype in ('a', 'r')
  loop
    execute format('alter table public.%I disable trigger user', e.child);
    execute format(
      'update public.%1$I c set %2$I = null
        where c.%2$I in (select t.%3$I from public.%4$I t
                          where not exists (select 1 from public.backup_restore_keys k
                                             where k.job_id = $1 and k.table_name = $2 and k.key = %5$s))',
      e.child, e.col, e.pcol, p_table, keyexpr) using p_job, p_table;
    get diagnostics m = row_count;
    detached := detached + m;
    execute format('alter table public.%I enable trigger user', e.child);
  end loop;

  execute format('alter table public.%I disable trigger user', p_table);
  execute format(
    'delete from public.%I t where not exists (select 1 from public.backup_restore_keys k where k.job_id = $1 and k.table_name = $2 and k.key = %s)',
    p_table, keyexpr) using p_job, p_table;
  get diagnostics n = row_count;
  execute format('alter table public.%I enable trigger user', p_table);

  update public.backup_restore_jobs
     set result = jsonb_set(jsonb_set(result, array[p_table, 'deleted'], to_jsonb(n), true),
                            array[p_table, 'detached'], to_jsonb(detached), true)
   where id = p_job;
  return n;
end $$;
revoke all on function public.backup_restore_delete_missing(uuid, text) from public;
grant execute on function public.backup_restore_delete_missing(uuid, text) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 6. finish — also drop the fixups; stale-job cleanup covers them via FK
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_finish(p_job uuid, p_status text, p_error text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare j public.backup_restore_jobs;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if p_status not in ('done', 'failed') then raise exception 'bad_status' using errcode = 'P0001'; end if;
  update public.backup_restore_jobs
     set status = p_status, error = p_error, finished_at = now()
   where id = p_job
  returning * into j;
  if j.id is null then raise exception 'job_not_found' using errcode = 'P0001'; end if;
  delete from public.backup_restore_rows   where job_id = p_job;
  delete from public.backup_restore_keys   where job_id = p_job;
  delete from public.backup_restore_fixups where job_id = p_job;
  return jsonb_build_object('id', j.id, 'status', j.status, 'result', j.result, 'tables', to_jsonb(j.tables));
end $$;
revoke all on function public.backup_restore_finish(uuid, text, text) from public;
grant execute on function public.backup_restore_finish(uuid, text, text) to authenticated, service_role;



-- #####################################################################
-- ##  20260923120000_owner_persons_management.sql
-- #####################################################################

-- =====================================================================
-- OWNER MODULE → إدارة الأفراد (/owner/persons)
--
-- ONE page for the owner with EVERY person in the system (persons table —
-- children and servants alike) together with all his enrollments, filtered
-- by church → service → class (or «بدون تسجيلات» — persons that are in no
-- enrollment at all), with multi-select and bulk actions:
--   * add the selected persons to one or more class(es)   (owner_bulk_enroll)
--   * remove the selected persons from a scope             (owner_bulk_unenroll)
--   * delete the selected persons completely (cascade)     (owner_bulk_delete_persons)
--
-- Everything is owner-only (is_owner()) — the page itself sits behind
-- <OwnerGate>, the RPCs are the real wall. Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. owner_persons_page — the list (server-side filters + pagination)
--    p_scope_mode: 'all' | 'scope' | 'none'
--       all   → every person
--       scope → persons with ≥ 1 enrollment inside p_church [→ p_service [→ p_class]]
--       none  → persons with NO enrollment row at all
--    p_kind: 'all' | 'child' | 'servant'   (servant = has a servant account)
--    Each row carries ALL his enrollments (jsonb) + his servant account (jsonb
--    or null) + total_count (count(*) over ()) for the pager.
-- ---------------------------------------------------------------------
create or replace function public.owner_persons_page(
  p_search      text default null,
  p_scope_mode  text default 'all',
  p_church      uuid default null,
  p_service     uuid default null,
  p_class       uuid default null,
  p_gender      text default null,
  p_kind        text default 'all',
  p_limit       integer default 100,
  p_offset      integer default 0
) returns table (
  id            uuid,
  national_id   text,
  name          text,
  birthdate     date,
  gender        text,
  phone         text,
  address       text,
  notes         text,
  image_url     text,
  created_at    timestamptz,
  edited_at     timestamptz,
  enrollments   jsonb,
  servant       jsonb,
  has_password  boolean,
  total_count   bigint
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_mode   text := coalesce(p_scope_mode, 'all');
  v_kind   text := coalesce(p_kind, 'all');
  v_limit  integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.is_owner() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_mode not in ('all', 'scope', 'none') then
    raise exception 'invalid_scope_mode' using errcode = '22023';
  end if;
  if v_kind not in ('all', 'child', 'servant') then
    raise exception 'invalid_kind' using errcode = '22023';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender' using errcode = '22023';
  end if;
  if v_mode = 'scope' and p_church is null then
    raise exception 'church_required' using errcode = '22023';
  end if;

  return query
  with base as (
    select p.*
      from public.persons p
     where (v_search is null
            or p.name ilike '%' || v_search || '%'
            or p.phone ilike '%' || v_search || '%'
            or p.national_id ilike '%' || v_search || '%')
       and (p_gender is null or p.gender = p_gender)
       and (
         v_mode = 'all'
         or (v_mode = 'none' and not exists (select 1 from public.enrollments e where e.person_id = p.id))
         or (v_mode = 'scope' and exists (
              select 1 from public.enrollments e
               where e.person_id = p.id
                 and e.church_id = p_church
                 and (p_service is null or e.service_id = p_service)
                 and (p_class   is null or e.class_id   = p_class)))
       )
       and (
         v_kind = 'all'
         or (v_kind = 'servant' and     exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
         or (v_kind = 'child'   and not exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
       )
  ),
  counted as (
    select b.*, count(*) over () as total_count
      from base b
     order by b.name collate "C", b.id
     limit v_limit offset v_offset
  )
  select
    c.id, c.national_id, c.name, c.birthdate, c.gender, c.phone, c.address, c.notes, c.image_url,
    c.created_at, c.edited_at,
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
               'kind', e.kind, 'servant_id', e.servant_id, 'status', e.status,
               'points', e.points, 'attendance_count', e.attendance_count, 'created_at', e.created_at)
             order by e.created_at)
        from public.enrollments e where e.person_id = c.id
    ), '[]'::jsonb) as enrollments,
    (
      select jsonb_build_object(
               'id', s.id, 'role', s.role, 'status', s.status,
               'church_id', s.church_id, 'service_id', s.service_id, 'class_id', s.class_id,
               'scopes', coalesce((
                 select jsonb_agg(jsonb_build_object('church_id', x.church_id, 'service_id', x.service_id, 'class_id', x.class_id))
                   from public.servant_scopes x where x.servant_id = s.id), '[]'::jsonb))
        from public.servant_enrollments s where s.person_id = c.id
       limit 1
    ) as servant,
    exists (select 1 from public.person_credentials pc where pc.person_id = c.id) as has_password,
    c.total_count
  from counted c
  order by c.name collate "C", c.id;
end $$;

revoke all on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) from public, anon;
grant execute on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) to authenticated;

comment on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) is
  'إدارة الأفراد (المالك): كل الأشخاص مع تسجيلاتهم وحساب الخادم — بحث · نطاق (كنيسة → خدمة → فصل) أو «بدون تسجيلات» · النوع · الصنف · ترقيم صفحات';

-- ---------------------------------------------------------------------
-- 2. owner_persons_counts — the header counters
-- ---------------------------------------------------------------------
create or replace function public.owner_persons_counts()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.is_owner() then jsonb_build_object(
    'total',      (select count(*) from public.persons),
    'unenrolled', (select count(*) from public.persons p where not exists (select 1 from public.enrollments e where e.person_id = p.id)),
    'servants',   (select count(*) from public.persons p where     exists (select 1 from public.servant_enrollments s where s.person_id = p.id)),
    'children',   (select count(*) from public.persons p where not exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
  ) else null end
$$;
revoke all on function public.owner_persons_counts() from public, anon;
grant execute on function public.owner_persons_counts() to authenticated;

-- ---------------------------------------------------------------------
-- 3. owner_bulk_enroll — add MANY persons to MANY classes at once
--    p_scopes: jsonb array of {church_id, service_id, class_id} — every
--    level required (an enrollment is always a class). Existing
--    (person, class) pairs are skipped (unique key). Servant mirror rows
--    are never touched. Returns {added, skipped, persons, scopes}.
-- ---------------------------------------------------------------------
create or replace function public.owner_bulk_enroll(
  p_person_ids uuid[],
  p_scopes     jsonb
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_added   integer := 0;
  v_skipped integer := 0;
  v_persons integer := 0;
  v_n       integer;
  s         record;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_person_ids is null or cardinality(p_person_ids) = 0 then raise exception 'persons_required' using errcode = '22023'; end if;
  if p_scopes is null or jsonb_typeof(p_scopes) <> 'array' or jsonb_array_length(p_scopes) = 0 then
    raise exception 'scopes_required' using errcode = '22023';
  end if;

  select count(*) into v_persons from public.persons p where p.id = any (p_person_ids);

  for s in
    select distinct
           (x->>'church_id')::uuid  as church_id,
           (x->>'service_id')::uuid as service_id,
           (x->>'class_id')::uuid   as class_id
      from jsonb_array_elements(p_scopes) x
  loop
    if s.church_id is null or s.service_id is null or s.class_id is null then
      raise exception 'class_required' using errcode = '22023';
    end if;
    -- the class must really belong to the service / church
    if not exists (
      select 1 from public.classes c
       where c.id = s.class_id and c.service_id = s.service_id and c.church_id = s.church_id
    ) then
      raise exception 'invalid_scope' using errcode = '22023';
    end if;
    -- owner always passes; kept generic so a manager could reuse it within his scope
    if not public.can_access(s.church_id, s.service_id, s.class_id) then
      raise exception 'no_access' using errcode = '42501';
    end if;

    with ins as (
      insert into public.enrollments (person_id, church_id, service_id, class_id, created_by, edited_by)
      select p.id, s.church_id, s.service_id, s.class_id, auth.uid(), auth.uid()
        from public.persons p
       where p.id = any (p_person_ids)
      on conflict (person_id, class_id) do nothing
      returning 1
    )
    select count(*) into v_n from ins;
    v_added   := v_added + v_n;
    v_skipped := v_skipped + (v_persons - v_n);
  end loop;

  return jsonb_build_object(
    'added',   v_added,
    'skipped', v_skipped,
    'persons', v_persons,
    'scopes',  (select count(distinct x->>'class_id') from jsonb_array_elements(p_scopes) x)
  );
end $$;
revoke all on function public.owner_bulk_enroll(uuid[], jsonb) from public, anon;
grant execute on function public.owner_bulk_enroll(uuid[], jsonb) to authenticated;

comment on function public.owner_bulk_enroll(uuid[], jsonb) is
  'إضافة عدة أشخاص إلى عدة فصول دفعة واحدة — التسجيلات الموجودة تُتخطى (person_id, class_id فريد)';

-- ---------------------------------------------------------------------
-- 4. owner_bulk_unenroll — remove MANY persons from a scope
--    p_church [→ p_service [→ p_class]] — nulls = the whole level under.
--    Only CHILD rows go (servant mirror rows follow the servant account and
--    are managed from إدارة الخدام). FK cascade wipes the rows' logs.
-- ---------------------------------------------------------------------
create or replace function public.owner_bulk_unenroll(
  p_person_ids uuid[],
  p_church     uuid,
  p_service    uuid default null,
  p_class      uuid default null
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_removed integer := 0;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_person_ids is null or cardinality(p_person_ids) = 0 then raise exception 'persons_required' using errcode = '22023'; end if;
  if p_church is null then raise exception 'church_required' using errcode = '22023'; end if;
  if not public.can_access(p_church, p_service, p_class) then
    raise exception 'no_access' using errcode = '42501';
  end if;

  with del as (
    delete from public.enrollments e
     where e.person_id = any (p_person_ids)
       and e.kind = 'child'
       and e.church_id = p_church
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
    returning 1
  )
  select count(*) into v_removed from del;

  return jsonb_build_object('removed', v_removed);
end $$;
revoke all on function public.owner_bulk_unenroll(uuid[], uuid, uuid, uuid) from public, anon;
grant execute on function public.owner_bulk_unenroll(uuid[], uuid, uuid, uuid) to authenticated;

comment on function public.owner_bulk_unenroll(uuid[], uuid, uuid, uuid) is
  'حذف عدة أشخاص من نطاق (كنيسة → خدمة → فصل؛ null = كل ما تحته) — صفوف المخدومين فقط، ومعها حضورهم ونقاطهم في هذا النطاق';

-- ---------------------------------------------------------------------
-- 5. owner_bulk_delete_persons — delete MANY persons completely (cascade)
--    Owner only. A person who IS a servant account is skipped (the account
--    must be deleted from إدارة الخدام first). Returns {deleted, skipped_servants}.
-- ---------------------------------------------------------------------
create or replace function public.owner_bulk_delete_persons(p_person_ids uuid[])
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_deleted  integer := 0;
  v_servants integer := 0;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_person_ids is null or cardinality(p_person_ids) = 0 then raise exception 'persons_required' using errcode = '22023'; end if;

  select count(*) into v_servants
    from public.persons p
   where p.id = any (p_person_ids)
     and exists (select 1 from public.servant_enrollments s where s.person_id = p.id);

  with del as (
    delete from public.persons p
     where p.id = any (p_person_ids)
       and not exists (select 1 from public.servant_enrollments s where s.person_id = p.id)
    returning 1
  )
  select count(*) into v_deleted from del;

  return jsonb_build_object('deleted', v_deleted, 'skipped_servants', v_servants);
end $$;
revoke all on function public.owner_bulk_delete_persons(uuid[]) from public, anon;
grant execute on function public.owner_bulk_delete_persons(uuid[]) to authenticated;

comment on function public.owner_bulk_delete_persons(uuid[]) is
  'حذف نهائي متسلسل لعدة أشخاص (المالك فقط) — أصحاب حسابات الخدام يُتخطَّون ويُحذفون من إدارة الخدام';



-- #####################################################################
-- ##  20260924120000_families.sql
-- #####################################################################

-- =====================================================================
-- FAMILY MODULE (العائلات) — families + family_members
--
-- A FAMILY groups several persons (children and/or servants — everyone is
-- a `persons` row whose `national_id` is his code / QR). It lets a servant:
--   * build a family from the individual QR codes of its members
--     (العائلات → QR → إضافة أفراد: scan card after card)
--   * scan ONE member's code on the scanner and see EVERY code / person of
--     the family, pick the person the operation is meant for, and — when
--     that person is enrolled in 2+ services / classes — pick the service
--     too. The RPC also tells which service each member already attended
--     on the working day («تم التعرف على الخدمة»).
--   * every family also gets its OWN code (`families.code`, F-XXXXXX) so a
--     family card can be printed and scanned directly.
--
-- Tables
--   families        id · code (unique, auto) · name · phone · address · notes
--                   · created/edited audit
--   family_members  family_id → families · person_id → persons (UNIQUE — a
--                   person belongs to ONE family) · relation (أب · أم · ابن …)
--
-- Access (RLS + RPCs)
--   module_visible('family') gates everything.
--   family_can('family.view')   — every servant of a granted scope
--   family_can('family.manage') — owner / church manager / service manager,
--                                 or a class servant with the permission key
--   family_visible(id)          — owner · creator · or ≥ 1 member enrolled in
--                                 a scope the caller can access
--
-- RPCs
--   family_lookup(code, day)                 — scanner: person code OR family code →
--                                              family + members + their enrollments
--                                              (filtered by can_access) + attended_today
--   family_add_member_by_code(family, code, relation, move)
--   family_remove_member(member_id)
--   family_set_relation(member_id, relation)
--
-- Idempotent. Seeds ONE global module grant (like `cards`) so the module is
-- usable right away; the owner narrows it from وحدة المالك → صلاحيات الوحدات.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. Permission helper
-- ---------------------------------------------------------------------
create or replace function public.family_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('family')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or p_key = 'family.view'
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.family_can(text) to authenticated;

create or replace function public.family_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',   public.family_can('family.view'),
    'manage', public.family_can('family.manage')
  )
$$;
grant execute on function public.family_permissions() to authenticated;

-- ---------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------
-- A short, readable, unique family code: F-XXXXXX (no 0/O/1/I ambiguity)
create or replace function public.family_new_code()
returns text language plpgsql volatile set search_path = public as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_code text;
  i int;
begin
  loop
    v_code := 'F-';
    for i in 1..6 loop
      v_code := v_code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.families f where f.code = v_code)
          and not exists (select 1 from public.persons p where p.national_id = v_code);
  end loop;
  return v_code;
end $$;

create table if not exists public.families (
  id          uuid primary key default gen_random_uuid(),
  code        text not null unique,
  name        text not null,
  phone       text,
  address     text,
  notes       text,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint families_name_chk check (length(trim(name)) between 1 and 120)
);
comment on table public.families is
  'العائلات — a group of persons (children / servants). code = the family QR (F-XXXXXX).';

-- fill the code automatically when the client does not send one
create or replace function public.families_fill_code()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.code is null or length(trim(new.code)) = 0 then
    new.code := public.family_new_code();
  else
    new.code := trim(new.code);
  end if;
  new.name := trim(new.name);
  -- the creator always sees his family (even before the first member) —
  -- family_visible() relies on created_by
  if tg_op = 'INSERT' and new.created_by is null then
    new.created_by := auth.uid();
  end if;
  if tg_op = 'INSERT' and new.edited_by is null then
    new.edited_by := auth.uid();
  end if;
  return new;
end $$;
drop trigger if exists trg_families_fill_code on public.families;
create trigger trg_families_fill_code before insert or update on public.families
for each row execute function public.families_fill_code();

drop trigger if exists trg_families_touch on public.families;
create trigger trg_families_touch before update on public.families
for each row execute function public.touch_edited();

create table if not exists public.family_members (
  id          uuid primary key default gen_random_uuid(),
  family_id   uuid not null references public.families(id) on delete cascade,
  person_id   uuid not null references public.persons(id) on delete cascade,
  relation    text,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  constraint family_members_person_uq unique (person_id),
  constraint family_members_relation_chk check (
    relation is null or relation in (
      'father', 'mother', 'son', 'daughter', 'brother', 'sister',
      'grandfather', 'grandmother', 'husband', 'wife', 'other'
    )
  )
);
comment on table public.family_members is
  'أفراد العائلة — person ↔ family (a person belongs to ONE family). relation = صلة القرابة.';

create index if not exists idx_family_members_family on public.family_members(family_id);
create index if not exists idx_families_created_by on public.families(created_by);

-- ---------------------------------------------------------------------
-- 2. Visibility helper + RLS
-- ---------------------------------------------------------------------
create or replace function public.family_visible(p_family uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_owner()
      or exists (select 1 from public.families f where f.id = p_family and f.created_by = auth.uid())
      or exists (
        select 1
          from public.family_members m
          join public.enrollments e on e.person_id = m.person_id
         where m.family_id = p_family
           and public.can_access(e.church_id, e.service_id, e.class_id)
      )
$$;
grant execute on function public.family_visible(uuid) to authenticated;

alter table public.families enable row level security;
alter table public.family_members enable row level security;

drop policy if exists families_select on public.families;
create policy families_select on public.families for select using (
  (select public.family_can('family.view'))
  -- `created_by` checked on the row itself: an INSERT … RETURNING evaluates
  -- the select policy before the row is written, so a sub-select can't see it
  and (created_by = auth.uid() or public.family_visible(id))
);
drop policy if exists families_insert on public.families;
create policy families_insert on public.families for insert with check (
  (select public.family_can('family.manage'))
);
drop policy if exists families_update on public.families;
create policy families_update on public.families for update using (
  (select public.family_can('family.manage')) and (created_by = auth.uid() or public.family_visible(id))
) with check (
  (select public.family_can('family.manage'))
);
drop policy if exists families_delete on public.families;
create policy families_delete on public.families for delete using (
  (select public.family_can('family.manage')) and (created_by = auth.uid() or public.family_visible(id))
);

drop policy if exists family_members_select on public.family_members;
create policy family_members_select on public.family_members for select using (
  (select public.family_can('family.view')) and public.family_visible(family_id)
);
drop policy if exists family_members_insert on public.family_members;
create policy family_members_insert on public.family_members for insert with check (
  (select public.family_can('family.manage')) and public.family_visible(family_id)
);
drop policy if exists family_members_update on public.family_members;
create policy family_members_update on public.family_members for update using (
  (select public.family_can('family.manage')) and public.family_visible(family_id)
);
drop policy if exists family_members_delete on public.family_members;
create policy family_members_delete on public.family_members for delete using (
  (select public.family_can('family.manage')) and public.family_visible(family_id)
);

-- ---------------------------------------------------------------------
-- 3. RPC — family_lookup(code, day)
--    Scanner entry point. `p_code` may be a PERSON code (national_id) or a
--    FAMILY code. Returns:
--    {
--      matched: 'person' | 'family' | null,
--      person:  {…} | null,             -- the scanned person (person code)
--      family:  {id, code, name, …} | null,
--      members: [ { member_id, relation, person: {…},
--                   enrollments: [ {id, church_id, service_id, class_id, kind,
--                                   status, points, attendance_count,
--                                   attended_today, today_event_ids} ] } ]
--    }
--    A person with no family is returned as the single member of a null
--    family (so the caller works with one shape). Enrollments are limited
--    to the caller's scopes (`can_access`) — members with none are still
--    listed (name + code) so the family is complete, but nothing can be
--    done on them here.
-- ---------------------------------------------------------------------
create or replace function public.family_lookup(p_code text, p_day date default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_code   text := trim(coalesce(p_code, ''));
  v_day    date := coalesce(p_day, current_date);
  v_person public.persons%rowtype;
  v_family public.families%rowtype;
  v_found_person boolean := false;
  v_found_family boolean := false;
  v_members jsonb;
begin
  if not public.family_can('family.view') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_code = '' then
    return jsonb_build_object('matched', null, 'person', null, 'family', null, 'members', '[]'::jsonb);
  end if;

  select * into v_person from public.persons p where p.national_id = v_code;
  v_found_person := found;
  if v_found_person then
    select f.* into v_family
      from public.family_members m join public.families f on f.id = m.family_id
     where m.person_id = v_person.id;
    v_found_family := found;
  else
    select * into v_family from public.families f where f.code = v_code;
    v_found_family := found;
  end if;

  if not v_found_person and not v_found_family then
    return jsonb_build_object('matched', null, 'person', null, 'family', null, 'members', '[]'::jsonb);
  end if;

  -- members = the family's members, or the lone scanned person
  with mem as (
    select m.id as member_id, m.relation, m.person_id, m.created_at
      from public.family_members m
     where v_found_family and m.family_id = v_family.id
    union all
    select null::uuid, null::text, v_person.id, now()
     where v_found_person and not v_found_family
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'member_id', mem.member_id,
           'relation',  mem.relation,
           'person',    to_jsonb(p),
           'enrollments', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', e.id, 'person_id', e.person_id,
                      'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
                      'kind', e.kind, 'servant_id', e.servant_id, 'status', e.status,
                      'points', e.points, 'attendance_count', e.attendance_count, 'created_at', e.created_at,
                      'attended_today', exists (
                        select 1 from public.attendance_log a
                         where a.enrollment_id = e.id and a.attended_on = v_day),
                      'today_event_ids', coalesce((
                        select jsonb_agg(distinct a.event_id)
                          from public.attendance_log a
                         where a.enrollment_id = e.id and a.attended_on = v_day and a.event_id is not null), '[]'::jsonb),
                      'person', to_jsonb(p))
                    order by e.created_at)
               from public.enrollments e
              where e.person_id = p.id
                and public.can_access(e.church_id, e.service_id, e.class_id)
           ), '[]'::jsonb)
         ) order by mem.created_at, p.name), '[]'::jsonb)
    into v_members
    from mem join public.persons p on p.id = mem.person_id;

  return jsonb_build_object(
    'matched', case when v_found_person then 'person' else 'family' end,
    'person',  case when v_found_person then to_jsonb(v_person) else null end,
    'family',  case when v_found_family then to_jsonb(v_family) else null end,
    'members', v_members
  );
end $$;
revoke all on function public.family_lookup(text, date) from public, anon;
grant execute on function public.family_lookup(text, date) to authenticated;
comment on function public.family_lookup(text, date) is
  'الماسح: كود شخص أو كود عائلة → العائلة وكل أفرادها وتسجيلاتهم (في نطاق المستخدم) مع «حضر اليوم» لكل تسجيل';

-- ---------------------------------------------------------------------
-- 4. RPC — family_add_member_by_code(family, code, relation, move)
--    Adds the person whose code is `p_code` to the family. Errors:
--      family_not_found · no_access · person_not_found · already_member
--      in_other_family (DETAIL = the other family's name, HINT = its id)
--    `p_move = true` moves him from his current family instead of failing.
--    Returns { member_id, person, moved_from: {id, name} | null }.
-- ---------------------------------------------------------------------
create or replace function public.family_add_member_by_code(
  p_family   uuid,
  p_code     text,
  p_relation text default null,
  p_move     boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_code    text := trim(coalesce(p_code, ''));
  v_person  public.persons%rowtype;
  v_other   public.families%rowtype;
  v_member  public.family_members%rowtype;
  v_moved   jsonb := null;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.families f where f.id = p_family) then
    raise exception 'family_not_found' using errcode = 'P0001';
  end if;
  if not public.family_visible(p_family) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if p_relation is not null and p_relation not in (
    'father', 'mother', 'son', 'daughter', 'brother', 'sister',
    'grandfather', 'grandmother', 'husband', 'wife', 'other') then
    raise exception 'invalid_relation' using errcode = '22023';
  end if;

  select * into v_person from public.persons p where p.national_id = v_code;
  if not found then
    raise exception 'person_not_found' using errcode = 'P0002';
  end if;

  select * into v_member from public.family_members m where m.person_id = v_person.id;
  if found then
    if v_member.family_id = p_family then
      raise exception 'already_member' using errcode = 'P0001';
    end if;
    select * into v_other from public.families f where f.id = v_member.family_id;
    if not p_move then
      raise exception 'in_other_family' using errcode = 'P0001',
        detail = coalesce(v_other.name, ''), hint = v_member.family_id::text;
    end if;
    delete from public.family_members where id = v_member.id;
    v_moved := jsonb_build_object('id', v_other.id, 'name', v_other.name);
  end if;

  insert into public.family_members (family_id, person_id, relation, created_by)
  values (p_family, v_person.id, p_relation, auth.uid())
  returning * into v_member;

  update public.families set edited_at = now(), edited_by = auth.uid() where id = p_family;

  return jsonb_build_object(
    'member_id', v_member.id,
    'relation',  v_member.relation,
    'person',    to_jsonb(v_person),
    'moved_from', v_moved
  );
end $$;
revoke all on function public.family_add_member_by_code(uuid, text, text, boolean) from public, anon;
grant execute on function public.family_add_member_by_code(uuid, text, text, boolean) to authenticated;
comment on function public.family_add_member_by_code(uuid, text, text, boolean) is
  'إضافة فرد إلى عائلة بكوده (QR) — in_other_family عندما يكون في عائلة أخرى (DETAIL = اسمها)، p_move = نقله';

-- ---------------------------------------------------------------------
-- 5. RPC — family_remove_member / family_set_relation
-- ---------------------------------------------------------------------
create or replace function public.family_remove_member(p_member uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_family uuid;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select family_id into v_family from public.family_members where id = p_member;
  if not found then raise exception 'member_not_found' using errcode = 'P0002'; end if;
  if not public.family_visible(v_family) then raise exception 'no_access' using errcode = '42501'; end if;
  delete from public.family_members where id = p_member;
  update public.families set edited_at = now(), edited_by = auth.uid() where id = v_family;
end $$;
revoke all on function public.family_remove_member(uuid) from public, anon;
grant execute on function public.family_remove_member(uuid) to authenticated;

create or replace function public.family_set_relation(p_member uuid, p_relation text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_family uuid;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select family_id into v_family from public.family_members where id = p_member;
  if not found then raise exception 'member_not_found' using errcode = 'P0002'; end if;
  if not public.family_visible(v_family) then raise exception 'no_access' using errcode = '42501'; end if;
  update public.family_members set relation = nullif(trim(coalesce(p_relation, '')), '') where id = p_member;
end $$;
revoke all on function public.family_set_relation(uuid, text) from public, anon;
grant execute on function public.family_set_relation(uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 6. Module grant seed · realtime · activity log
-- ---------------------------------------------------------------------
insert into public.module_access (module_key, church_id, service_id, class_id)
select 'family', null, null, null
where not exists (select 1 from public.module_access where module_key = 'family');

do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'families') then
    alter publication supabase_realtime add table public.families;
  end if;
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'family_members') then
    alter publication supabase_realtime add table public.family_members;
  end if;
exception when undefined_object then null;
end $$;

do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('families');
    perform public.activity_audit_attach('family_members');
  end if;
end $$;

create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules', 'report_templates', 'families', 'family_members'
  ]
$$;



-- #####################################################################
-- ##  20260924130000_families_code_and_search.sql
-- #####################################################################

-- =====================================================================
-- FAMILY MODULE — v2: user-set family code · search persons · new member
--
--   * The family CODE is chosen by the servant when creating the family
--     (typed · scanned · generated by نظام الأكواد — new generator `family`).
--     The DB still fills one when none is sent. A family code may never be
--     a PERSON code (the scanner must tell them apart) → trigger check.
--   * `family_code_lookup(code)`   — live check while typing
--   * `family_search_persons(q)`   — name / phone / code search over the
--                                    persons the caller may see, with each
--                                    person's current family + places
--   * `family_add_member(family, person_id, relation, move)` — add an
--     EXISTING person picked from the search (by-code RPC now delegates)
--   * `family_add_new_member(...)` — create the person (+ optional
--     enrollment in church → service → class) AND add him to the family
--     in ONE transaction
--   * app_settings.codes validator accepts the `family` generator
-- Idempotent. Run after 20260924120000_families.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Code system — accept generator `family`
-- ---------------------------------------------------------------------
create or replace function public.validate_app_settings()
returns trigger language plpgsql as $$
declare g text; gen jsonb; sc record;
begin
  if jsonb_typeof(new.value) <> 'object' then
    raise exception 'app_settings.value must be a JSON object (key %)', new.key;
  end if;
  if new.key = 'names' then
    if exists (
      select 1 from jsonb_each(new.value) kv
       where jsonb_typeof(kv.value) <> 'string'
          or length(kv.value #>> '{}') = 0
          or length(kv.value #>> '{}') > 30
    ) then
      raise exception 'app_settings.names: every label must be a 1–30 character string';
    end if;
  end if;
  if new.key = 'widgets' then
    if jsonb_typeof(new.value -> 'items') <> 'array'
       or jsonb_array_length(new.value -> 'items') > 40 then
      raise exception 'app_settings.widgets: items must be an array (max 40)';
    end if;
  end if;
  if new.key = 'codes' then
    perform public.validate_code_template(new.value -> 'default', 'default');
    if jsonb_array_length(new.value -> 'default' -> 'parts') = 0 then
      raise exception 'app_settings.codes: default template needs at least one part';
    end if;
    if new.value ? 'generators' then
      if jsonb_typeof(new.value -> 'generators') <> 'object' then
        raise exception 'app_settings.codes: generators must be an object';
      end if;
      for g, gen in select * from jsonb_each(new.value -> 'generators') loop
        if g not in ('person', 'servant', 'store_item', 'ticket', 'family') then
          raise exception 'app_settings.codes: unknown generator %', g;
        end if;
        if coalesce(gen ->> 'mode', 'legacy') not in ('default', 'custom', 'legacy') then
          raise exception 'app_settings.codes: generator % has an invalid mode', g;
        end if;
        if gen ? 'template' then perform public.validate_code_template(gen -> 'template', g); end if;
        if gen ->> 'mode' = 'custom' and jsonb_array_length(coalesce(gen -> 'template' -> 'parts', '[]'::jsonb)) = 0 then
          raise exception 'app_settings.codes: generator % is custom but has no parts', g;
        end if;
      end loop;
    end if;
    if new.value ? 'scopes' then
      for sc in
        select m.key as grp, e.key as id, e.value as abbr
          from jsonb_each(new.value -> 'scopes') m
          cross join lateral jsonb_each(m.value) e
      loop
        if sc.grp not in ('churches', 'services', 'classes') then
          raise exception 'app_settings.codes: unknown scope group %', sc.grp;
        end if;
        if jsonb_typeof(sc.abbr) <> 'string' or length(sc.abbr #>> '{}') > 12 then
          raise exception 'app_settings.codes: abbreviation of % must be a string of at most 12 characters', sc.id;
        end if;
      end loop;
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 2. Family code trigger — normalise + refuse a PERSON code
-- ---------------------------------------------------------------------
create or replace function public.families_fill_code()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.code is null or length(trim(new.code)) = 0 then
    new.code := public.family_new_code();
  else
    new.code := trim(new.code);
    if length(new.code) > 60 then
      raise exception 'code_too_long' using errcode = '22023';
    end if;
    if exists (select 1 from public.persons p where p.national_id = new.code) then
      raise exception 'code_is_person' using errcode = '23505',
        detail = 'A family code cannot equal the code of a person';
    end if;
  end if;
  new.name := trim(new.name);
  if tg_op = 'INSERT' and new.created_by is null then
    new.created_by := auth.uid();
  end if;
  if tg_op = 'INSERT' and new.edited_by is null then
    new.edited_by := auth.uid();
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 3. family_code_lookup(code) — live check while typing / after a scan
--    { code, free, family: {id, name} | null, person: {id, name} | null }
-- ---------------------------------------------------------------------
create or replace function public.family_code_lookup(p_code text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_code text := trim(coalesce(p_code, ''));
  v_fam  record;
  v_per  record;
begin
  if not public.family_can('family.view') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_code = '' then
    return jsonb_build_object('code', '', 'free', false, 'family', null, 'person', null);
  end if;
  select id, name into v_fam from public.families where code = v_code;
  select id, name into v_per from public.persons where national_id = v_code;
  return jsonb_build_object(
    'code', v_code,
    'free', (v_fam.id is null and v_per.id is null),
    'family', case when v_fam.id is null then null else jsonb_build_object('id', v_fam.id, 'name', v_fam.name) end,
    'person', case when v_per.id is null then null else jsonb_build_object('id', v_per.id, 'name', v_per.name) end
  );
end $$;
revoke all on function public.family_code_lookup(text) from public, anon;
grant execute on function public.family_code_lookup(text) to authenticated;

-- ---------------------------------------------------------------------
-- 4. family_search_persons(q, limit) — persons the caller may see
--    (owner: everyone; others: ≥ 1 enrollment in a scope he can access,
--    or a person he created). Each row: person · family {id,name} | null
--    · places [{church_id, service_id, class_id}] (scoped).
-- ---------------------------------------------------------------------
create or replace function public.family_search_persons(p_query text, p_limit integer default 30)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_q     text := nullif(trim(coalesce(p_query, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_out   jsonb;
begin
  if not public.family_can('family.view') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_q is null or length(v_q) < 2 then
    return '[]'::jsonb;
  end if;

  with hits as (
    select p.*
      from public.persons p
     where (p.name ilike '%' || v_q || '%'
            or p.phone ilike '%' || v_q || '%'
            or p.national_id ilike '%' || v_q || '%')
       and (
         public.is_owner()
         or p.created_by = auth.uid()
         or exists (select 1 from public.enrollments e
                     where e.person_id = p.id
                       and public.can_access(e.church_id, e.service_id, e.class_id))
       )
     order by (p.national_id = v_q) desc, p.name collate "C"
     limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'person', to_jsonb(h),
           'family', (select jsonb_build_object('id', f.id, 'name', f.name)
                        from public.family_members m join public.families f on f.id = m.family_id
                       where m.person_id = h.id),
           'places', coalesce((
             select jsonb_agg(jsonb_build_object('church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id, 'kind', e.kind) order by e.created_at)
               from public.enrollments e
              where e.person_id = h.id
                and public.can_access(e.church_id, e.service_id, e.class_id)), '[]'::jsonb)
         ) order by (h.national_id = v_q) desc, h.name collate "C"), '[]'::jsonb)
    into v_out
    from hits h;
  return v_out;
end $$;
revoke all on function public.family_search_persons(text, integer) from public, anon;
grant execute on function public.family_search_persons(text, integer) to authenticated;
comment on function public.family_search_persons(text, integer) is
  'بحث عن أشخاص (اسم · هاتف · كود) في نطاق المستخدم لإضافتهم إلى عائلة — مع عائلتهم الحالية وأماكنهم';

-- ---------------------------------------------------------------------
-- 5. family_add_member(family, person_id, relation, move) — the core
--    add; the by-code RPC delegates to it.
-- ---------------------------------------------------------------------
create or replace function public.family_add_member(
  p_family   uuid,
  p_person   uuid,
  p_relation text default null,
  p_move     boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_person  public.persons%rowtype;
  v_other   public.families%rowtype;
  v_member  public.family_members%rowtype;
  v_moved   jsonb := null;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.families f where f.id = p_family) then
    raise exception 'family_not_found' using errcode = 'P0001';
  end if;
  if not public.family_visible(p_family) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if p_relation is not null and p_relation not in (
    'father', 'mother', 'son', 'daughter', 'brother', 'sister',
    'grandfather', 'grandmother', 'husband', 'wife', 'other') then
    raise exception 'invalid_relation' using errcode = '22023';
  end if;

  select * into v_person from public.persons p where p.id = p_person;
  if not found then
    raise exception 'person_not_found' using errcode = 'P0002';
  end if;

  select * into v_member from public.family_members m where m.person_id = v_person.id;
  if found then
    if v_member.family_id = p_family then
      raise exception 'already_member' using errcode = 'P0001';
    end if;
    select * into v_other from public.families f where f.id = v_member.family_id;
    if not p_move then
      raise exception 'in_other_family' using errcode = 'P0001',
        detail = coalesce(v_other.name, ''), hint = v_member.family_id::text;
    end if;
    delete from public.family_members where id = v_member.id;
    v_moved := jsonb_build_object('id', v_other.id, 'name', v_other.name);
  end if;

  insert into public.family_members (family_id, person_id, relation, created_by)
  values (p_family, v_person.id, p_relation, auth.uid())
  returning * into v_member;

  update public.families set edited_at = now(), edited_by = auth.uid() where id = p_family;

  return jsonb_build_object(
    'member_id', v_member.id,
    'relation',  v_member.relation,
    'person',    to_jsonb(v_person),
    'moved_from', v_moved
  );
end $$;
revoke all on function public.family_add_member(uuid, uuid, text, boolean) from public, anon;
grant execute on function public.family_add_member(uuid, uuid, text, boolean) to authenticated;

create or replace function public.family_add_member_by_code(
  p_family   uuid,
  p_code     text,
  p_relation text default null,
  p_move     boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v_person uuid;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select id into v_person from public.persons p where p.national_id = trim(coalesce(p_code, ''));
  if v_person is null then
    raise exception 'person_not_found' using errcode = 'P0002';
  end if;
  return public.family_add_member(p_family, v_person, p_relation, p_move);
end $$;

-- ---------------------------------------------------------------------
-- 6. family_add_new_member — create the person (+ optional enrollment)
--    and add him to the family in one transaction.
--    With p_class → add_person_and_enroll (same rules as إضافة مخدوم:
--    upsert by code, enrollment in church → service → class).
--    Without a class → a bare person row (parents who are in no service);
--    the code is required then (a bare person has no other identity).
--    Errors: forbidden · family_not_found · no_access · name_required ·
--            code_required · code_taken (code belongs to a FAMILY) ·
--            already_member · in_other_family (DETAIL = name)
-- ---------------------------------------------------------------------
create or replace function public.family_add_new_member(
  p_family      uuid,
  p_name        text,
  p_national_id text default null,
  p_gender      text default null,
  p_birthdate   date default null,
  p_phone       text default null,
  p_address     text default null,
  p_notes       text default null,
  p_image_url   text default null,
  p_church      uuid default null,
  p_service     uuid default null,
  p_class       uuid default null,
  p_relation    text default null,
  p_move        boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code   text := nullif(trim(coalesce(p_national_id, '')), '');
  v_name   text := nullif(trim(coalesce(p_name, '')), '');
  v_person uuid;
  v_res    jsonb;
  v_add    jsonb;
  v_created boolean := false;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.families f where f.id = p_family) then
    raise exception 'family_not_found' using errcode = 'P0001';
  end if;
  if not public.family_visible(p_family) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if v_name is null then
    raise exception 'name_required' using errcode = '22023';
  end if;
  if v_code is not null and exists (select 1 from public.families f where f.code = v_code) then
    raise exception 'code_taken' using errcode = '23505';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender' using errcode = '22023';
  end if;

  if p_class is not null then
    if p_church is null or p_service is null then
      raise exception 'invalid_scope' using errcode = '22023';
    end if;
    -- same path as إضافة مخدوم (validates scope + access, upserts by code)
    v_res := public.add_person_and_enroll(
      p_church, p_service, p_class, v_name, v_code, p_gender, p_birthdate,
      p_phone, p_address, p_notes, p_image_url, 0, null);
    v_person  := (v_res ->> 'person_id')::uuid;
    v_created := coalesce((v_res ->> 'person_created')::boolean, false);
  else
    if v_code is null then
      raise exception 'code_required' using errcode = '22023';
    end if;
    select id into v_person from public.persons where national_id = v_code;
    if v_person is null then
      insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
      values (v_code, v_name, p_gender, p_birthdate, p_phone, p_address, p_notes, p_image_url, auth.uid(), auth.uid())
      returning id into v_person;
      v_created := true;
    else
      -- existing person: fill the blanks only (typed data never overwrites)
      update public.persons set
        gender    = coalesce(gender, p_gender),
        birthdate = coalesce(birthdate, p_birthdate),
        phone     = coalesce(phone, p_phone),
        address   = coalesce(address, p_address),
        notes     = coalesce(notes, p_notes),
        image_url = coalesce(image_url, p_image_url),
        edited_at = now(), edited_by = auth.uid()
      where id = v_person;
    end if;
  end if;

  v_add := public.family_add_member(p_family, v_person, p_relation, p_move);
  return v_add || jsonb_build_object(
    'person_created', v_created,
    'enrollment_id', v_res ->> 'enrollment_id',
    'already_enrolled', coalesce((v_res ->> 'already_enrolled')::boolean, false)
  );
end $$;
revoke all on function public.family_add_new_member(uuid, text, text, text, date, text, text, text, text, uuid, uuid, uuid, text, boolean) from public, anon;
grant execute on function public.family_add_new_member(uuid, text, text, text, date, text, text, text, text, uuid, uuid, uuid, text, boolean) to authenticated;
comment on function public.family_add_new_member(uuid, text, text, text, date, text, text, text, text, uuid, uuid, uuid, text, boolean) is
  'إنشاء شخص جديد (مع تسجيله في فصل اختيارياً) وإضافته إلى العائلة في عملية واحدة';



-- #####################################################################
-- ##  20260925120000_access_control.sql
-- #####################################################################

-- =====================================================================
-- ACCESS MODULE (التحكم في الدخول) — access events · rules · allowed list · log
--
-- An ACCESS EVENT (بوابة دخول) is something a person is let INTO (a party,
-- a trip bus, a hall, a meal…). At the door the servant scans the person's
-- QR (or searches him) and the app answers **مسموح / مرفوض** with the
-- person's name, photo, points, attendance history — and EVERY rule with
-- its own fulfilled / not-fulfilled status.
--
-- Decision = ALLOWED-LIST  AND  RULE-TREE
--   * allowed list (المسموح لهم): specific persons · a class · a service ·
--     a whole church · any combination (`access_allowed`). A person who is
--     NOT covered is denied even when every rule passes. `allow_all` on the
--     event skips the list («الجميع»).
--   * rule tree: rules (`access_rules`) sit in groups (`access_rule_groups`)
--     nested under each other; every group combines its children with
--     AND / OR; the event's `root_op` combines the top level. Disabled rules
--     are ignored; a group with nothing enabled is vacuously true.
--
-- Rule kinds (params jsonb)
--   points            {op, value, value2}                          sum of points of the person's enrollments in the event's scope
--   attendance_count  {op, value, value2, from, to, event_id}      attendances (counter, or attendance_log rows when filtered)
--   attended_events   {event_ids[], mode: all|any, from, to}       attended these specific events
--   gender            {value: male|female}
--   age               {op, value, value2}                          years from birthdate
--   enrolled_in       {church_id, service_id, class_id}            has an active enrollment there
--   person_field      {field, op: present|absent|contains|equals, value}
--   exam_passed       {exam_id}                                    passed a quiz (exam_attempts.passed)
--   achievement       {achievement_id}                             earned it (user_achievements)
--   occasion          {occasion_id, statuses[]}                    registered in an occasion (default confirmed / checked_in)
--   not_entered       {period: day|ever}                           was not already granted entry to THIS access event
--   op ∈ gte · lte · eq · neq · between
--
-- Scope of the metrics: the person's ACTIVE enrollments inside the event's
-- church → service → class; when he has none there, all his active
-- enrollments (so a guest listed by person can still be measured).
--
-- Access (RLS + RPCs)
--   module_visible('access') gates everything.
--   access_can('access.check')  — every servant of a granted scope (the door)
--   access_can('access.manage') — owner / church manager / service manager,
--                                 or a class servant with the permission key
--   events are visible by scope_overlaps(); managed by can_access().
--
-- RPCs
--   access_check(event, code | person, log)  — the door: full decision payload
--   access_search_persons(q, limit)          — name / phone / code search (scoped)
--   access_permissions()                     — {check, manage}
--
-- Idempotent. Seeds ONE global module grant (like `family`).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. Permission helpers
-- ---------------------------------------------------------------------
create or replace function public.access_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('access')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or p_key = 'access.check'
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.access_can(text) to authenticated;

create or replace function public.access_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'check',  public.access_can('access.check'),
    'manage', public.access_can('access.manage')
  )
$$;
grant execute on function public.access_permissions() to authenticated;

-- ---------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------
create table if not exists public.access_events (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,   -- null = whole church
  class_id    uuid references public.classes(id)  on delete cascade,   -- null = whole service
  name        text not null,
  description text,
  is_active   boolean not null default true,
  allow_all   boolean not null default false,                          -- true = skip the allowed list
  root_op     text not null default 'and' check (root_op in ('and', 'or')),
  starts_at   timestamptz,
  ends_at     timestamptz,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint access_events_name_chk check (length(trim(name)) between 1 and 120),
  constraint access_events_class_needs_service check (class_id is null or service_id is not null)
);
comment on table public.access_events is
  'بوابات الدخول — مناسبة يُتحكم في الدخول إليها بقواعد وقائمة مسموح لهم. root_op = ربط قواعد المستوى الأعلى (and/or)';

create table if not exists public.access_rule_groups (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.access_events(id) on delete cascade,
  parent_id   uuid references public.access_rule_groups(id) on delete cascade,  -- null = under the root
  name        text,
  op          text not null default 'and' check (op in ('and', 'or')),
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);
comment on table public.access_rule_groups is
  'مجموعات القواعد — تجمع قواعد (ومجموعات فرعية) بـ AND أو OR داخل بوابة الدخول';

create table if not exists public.access_rules (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.access_events(id) on delete cascade,
  group_id    uuid references public.access_rule_groups(id) on delete cascade,  -- null = root level
  name        text not null,
  kind        text not null check (kind in (
                'points', 'attendance_count', 'attended_events', 'gender', 'age', 'enrolled_in',
                'person_field', 'exam_passed', 'achievement', 'occasion', 'not_entered')),
  params      jsonb not null default '{}'::jsonb,
  enabled     boolean not null default true,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint access_rules_name_chk check (length(trim(name)) between 1 and 160),
  constraint access_rules_params_obj check (jsonb_typeof(params) = 'object')
);
comment on table public.access_rules is
  'قواعد الدخول — شرط واحد (نقاط · حضور · مناسبات · نوع · عمر · تسجيل · بيانات · امتحان · إنجاز · فعالية · لم يدخل بعد) بمعاملاته';

create table if not exists public.access_allowed (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.access_events(id) on delete cascade,
  person_id   uuid references public.persons(id) on delete cascade,
  church_id   uuid references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id)  on delete cascade,
  note        text,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  constraint access_allowed_target check (
    (person_id is not null and church_id is null and service_id is null and class_id is null)
    or (person_id is null and church_id is not null)
  ),
  constraint access_allowed_class_needs_service check (class_id is null or service_id is not null)
);
comment on table public.access_allowed is
  'المسموح لهم — شخص محدد، أو فصل / خدمة / كنيسة كاملة (service/class فارغة = المستوى كله)';
create unique index if not exists uq_access_allowed_person on public.access_allowed(event_id, person_id) where person_id is not null;
create unique index if not exists uq_access_allowed_scope on public.access_allowed(
  event_id, church_id, coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(class_id, '00000000-0000-0000-0000-000000000000'::uuid)
) where person_id is null;

create table if not exists public.access_log (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.access_events(id) on delete cascade,
  person_id   uuid references public.persons(id) on delete set null,
  code        text,
  granted     boolean not null,
  allowed     boolean not null,
  rules_ok    boolean not null,
  reason      text,
  details     jsonb,
  checked_by  uuid references public.servant_enrollments(id) on delete set null,
  checked_on  date not null default ((now() at time zone 'Africa/Cairo')::date),
  created_at  timestamptz not null default now()
);
comment on table public.access_log is 'سجل الدخول — كل عملية تحقق عند البوابة بنتيجتها وتفاصيل القواعد';

create index if not exists idx_access_events_scope   on public.access_events(church_id, service_id, class_id);
create index if not exists idx_access_groups_event   on public.access_rule_groups(event_id, parent_id, sort_order);
create index if not exists idx_access_rules_event    on public.access_rules(event_id, group_id, sort_order);
create index if not exists idx_access_allowed_event  on public.access_allowed(event_id);
create index if not exists idx_access_allowed_person on public.access_allowed(person_id) where person_id is not null;
create index if not exists idx_access_log_event      on public.access_log(event_id, created_at desc);
create index if not exists idx_access_log_person     on public.access_log(person_id, event_id, checked_on);

-- audit triggers
create or replace function public.access_fill_audit()
returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then new.created_by := auth.uid(); end if;
    if new.edited_by is null then new.edited_by := auth.uid(); end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_access_events_audit on public.access_events;
create trigger trg_access_events_audit before insert on public.access_events
for each row execute function public.access_fill_audit();
drop trigger if exists trg_access_events_touch on public.access_events;
create trigger trg_access_events_touch before update on public.access_events
for each row execute function public.touch_edited();
drop trigger if exists trg_access_rules_audit on public.access_rules;
create trigger trg_access_rules_audit before insert on public.access_rules
for each row execute function public.access_fill_audit();
drop trigger if exists trg_access_rules_touch on public.access_rules;
create trigger trg_access_rules_touch before update on public.access_rules
for each row execute function public.touch_edited();

-- a group / rule must belong to the same event as its parent group
create or replace function public.access_check_group_parent()
returns trigger language plpgsql set search_path = public as $$
declare v_event uuid;
begin
  if tg_table_name = 'access_rule_groups' then
    if new.parent_id is not null then
      if new.parent_id = new.id then raise exception 'group_self_parent' using errcode = '23514'; end if;
      select event_id into v_event from public.access_rule_groups where id = new.parent_id;
      if v_event is distinct from new.event_id then raise exception 'group_parent_other_event' using errcode = '23514'; end if;
    end if;
  else
    if new.group_id is not null then
      select event_id into v_event from public.access_rule_groups where id = new.group_id;
      if v_event is distinct from new.event_id then raise exception 'rule_group_other_event' using errcode = '23514'; end if;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_access_groups_parent on public.access_rule_groups;
create trigger trg_access_groups_parent before insert or update on public.access_rule_groups
for each row execute function public.access_check_group_parent();
drop trigger if exists trg_access_rules_group on public.access_rules;
create trigger trg_access_rules_group before insert or update on public.access_rules
for each row execute function public.access_check_group_parent();

-- ---------------------------------------------------------------------
-- 2. Visibility helpers + RLS
-- ---------------------------------------------------------------------
create or replace function public.access_event_visible(p_event uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.access_events e
     where e.id = p_event and public.scope_overlaps(e.church_id, e.service_id, e.class_id)
  )
$$;
grant execute on function public.access_event_visible(uuid) to authenticated;

create or replace function public.access_event_manageable(p_event uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.access_can('access.manage') and exists (
    select 1 from public.access_events e
     where e.id = p_event and public.can_access(e.church_id, e.service_id, e.class_id)
  )
$$;
grant execute on function public.access_event_manageable(uuid) to authenticated;

alter table public.access_events      enable row level security;
alter table public.access_rule_groups enable row level security;
alter table public.access_rules       enable row level security;
alter table public.access_allowed     enable row level security;
alter table public.access_log         enable row level security;

drop policy if exists access_events_select on public.access_events;
create policy access_events_select on public.access_events for select using (
  (select public.access_can('access.check')) and public.scope_overlaps(church_id, service_id, class_id)
);
drop policy if exists access_events_insert on public.access_events;
create policy access_events_insert on public.access_events for insert with check (
  (select public.access_can('access.manage')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists access_events_update on public.access_events;
create policy access_events_update on public.access_events for update using (
  (select public.access_can('access.manage')) and public.can_access(church_id, service_id, class_id)
) with check (
  (select public.access_can('access.manage')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists access_events_delete on public.access_events;
create policy access_events_delete on public.access_events for delete using (
  (select public.access_can('access.manage')) and public.can_access(church_id, service_id, class_id)
);

-- child tables: readable when the event is visible, writable when manageable
do $$
declare t text;
begin
  foreach t in array array['access_rule_groups', 'access_rules', 'access_allowed'] loop
    execute format('drop policy if exists %1$s_select on public.%1$s', t);
    execute format('create policy %1$s_select on public.%1$s for select using ((select public.access_can(''access.check'')) and public.access_event_visible(event_id))', t);
    execute format('drop policy if exists %1$s_insert on public.%1$s', t);
    execute format('create policy %1$s_insert on public.%1$s for insert with check (public.access_event_manageable(event_id))', t);
    execute format('drop policy if exists %1$s_update on public.%1$s', t);
    execute format('create policy %1$s_update on public.%1$s for update using (public.access_event_manageable(event_id)) with check (public.access_event_manageable(event_id))', t);
    execute format('drop policy if exists %1$s_delete on public.%1$s', t);
    execute format('create policy %1$s_delete on public.%1$s for delete using (public.access_event_manageable(event_id))', t);
  end loop;
end $$;

drop policy if exists access_log_select on public.access_log;
create policy access_log_select on public.access_log for select using (
  (select public.access_can('access.check')) and public.access_event_visible(event_id)
);
drop policy if exists access_log_delete on public.access_log;
create policy access_log_delete on public.access_log for delete using (
  public.access_event_manageable(event_id)
);
-- inserts happen only through access_check() (security definer)

-- ---------------------------------------------------------------------
-- 3. Rule engine
-- ---------------------------------------------------------------------
create or replace function public.access_cmp(p_actual numeric, p_op text, p_v1 numeric, p_v2 numeric)
returns boolean language sql immutable as $$
  select case
    when p_actual is null then false
    when p_op = 'gte' then p_actual >= coalesce(p_v1, 0)
    when p_op = 'lte' then p_actual <= coalesce(p_v1, 0)
    when p_op = 'eq'  then p_actual =  coalesce(p_v1, 0)
    when p_op = 'neq' then p_actual <> coalesce(p_v1, 0)
    when p_op = 'between' then p_actual >= coalesce(p_v1, 0) and p_actual <= coalesce(p_v2, p_v1, 0)
    else p_actual >= coalesce(p_v1, 0)
  end
$$;

-- forgiving parsers (bad input = null, never an exception)
create or replace function public.access_num(p text)
returns numeric language plpgsql immutable as $$
begin
  return nullif(trim(coalesce(p, '')), '')::numeric;
exception when others then return null;
end $$;
create or replace function public.access_date(p text)
returns date language plpgsql immutable as $$
begin
  return nullif(trim(coalesce(p, '')), '')::date;
exception when others then return null;
end $$;

-- Evaluate ONE rule for a person. Returns {fulfilled, actual}.
create or replace function public.access_eval_rule(
  p_rule   public.access_rules,
  p_person public.persons,
  p_enr    uuid[],
  p_event  public.access_events
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  pr      jsonb := coalesce(p_rule.params, '{}'::jsonb);
  v_op    text := coalesce(pr ->> 'op', 'gte');
  v_v1    numeric;
  v_v2    numeric;
  v_from  date;
  v_to    date;
  v_num   numeric;
  v_ok    boolean := false;
  v_actual jsonb := 'null'::jsonb;
  v_ids   uuid[];
  v_hit   int;
  v_txt   text;
begin
  -- numeric / date params are parsed only for the kinds that use them
  -- (`value` is a text for gender / person_field)
  if p_rule.kind in ('points', 'attendance_count', 'age') then
    v_v1 := public.access_num(pr ->> 'value');
    v_v2 := public.access_num(pr ->> 'value2');
  end if;
  if p_rule.kind in ('attendance_count', 'attended_events') then
    v_from := public.access_date(pr ->> 'from');
    v_to   := public.access_date(pr ->> 'to');
  end if;

  case p_rule.kind
    when 'points' then
      select coalesce(sum(e.points), 0) into v_num from public.enrollments e where e.id = any(p_enr);
      v_ok := public.access_cmp(v_num, v_op, v_v1, v_v2);
      v_actual := to_jsonb(v_num);

    when 'attendance_count' then
      if v_from is null and v_to is null and nullif(pr ->> 'event_id', '') is null then
        select coalesce(sum(e.attendance_count), 0) into v_num from public.enrollments e where e.id = any(p_enr);
      else
        select count(*) into v_num
          from public.attendance_log a
         where a.enrollment_id = any(p_enr)
           and (v_from is null or a.attended_on >= v_from)
           and (v_to is null or a.attended_on <= v_to)
           and (nullif(pr ->> 'event_id', '') is null or a.event_id = (pr ->> 'event_id')::uuid);
      end if;
      v_ok := public.access_cmp(v_num, v_op, v_v1, v_v2);
      v_actual := to_jsonb(v_num);

    when 'attended_events' then
      select coalesce(array_agg(x::uuid), '{}') into v_ids from jsonb_array_elements_text(coalesce(pr -> 'event_ids', '[]'::jsonb)) x;
      select count(distinct a.event_id) into v_hit
        from public.attendance_log a
       where a.enrollment_id = any(p_enr)
         and a.event_id = any(v_ids)
         and (v_from is null or a.attended_on >= v_from)
         and (v_to is null or a.attended_on <= v_to);
      v_ok := case when coalesce(array_length(v_ids, 1), 0) = 0 then true
                   when coalesce(pr ->> 'mode', 'all') = 'any' then v_hit >= 1
                   else v_hit >= array_length(v_ids, 1) end;
      v_actual := jsonb_build_object('hit', v_hit, 'of', coalesce(array_length(v_ids, 1), 0), 'event_ids', coalesce((
        select jsonb_agg(distinct a.event_id) from public.attendance_log a
         where a.enrollment_id = any(p_enr) and a.event_id = any(v_ids)
           and (v_from is null or a.attended_on >= v_from) and (v_to is null or a.attended_on <= v_to)), '[]'::jsonb));

    when 'gender' then
      v_ok := p_person.gender is not null and p_person.gender::text = (pr ->> 'value');
      v_actual := to_jsonb(p_person.gender::text);

    when 'age' then
      if p_person.birthdate is null then
        v_ok := false; v_actual := 'null'::jsonb;
      else
        v_num := extract(year from age(current_date, p_person.birthdate));
        v_ok := public.access_cmp(v_num, v_op, v_v1, v_v2);
        v_actual := to_jsonb(v_num);
      end if;

    when 'enrolled_in' then
      select count(*) into v_hit
        from public.enrollments e
       where e.person_id = p_person.id
         and coalesce(e.status::text, 'active') = 'active'
         and (nullif(pr ->> 'church_id', '') is null or e.church_id = (pr ->> 'church_id')::uuid)
         and (nullif(pr ->> 'service_id', '') is null or e.service_id = (pr ->> 'service_id')::uuid)
         and (nullif(pr ->> 'class_id', '') is null or e.class_id = (pr ->> 'class_id')::uuid);
      v_ok := v_hit > 0;
      v_actual := to_jsonb(v_hit > 0);

    when 'person_field' then
      v_txt := case pr ->> 'field'
        when 'phone' then p_person.phone
        when 'address' then p_person.address
        when 'notes' then p_person.notes
        when 'image_url' then p_person.image_url
        when 'birthdate' then p_person.birthdate::text
        when 'name' then p_person.name
        when 'national_id' then p_person.national_id
        else null end;
      v_ok := case coalesce(pr ->> 'op', 'present')
        when 'present'  then nullif(trim(coalesce(v_txt, '')), '') is not null
        when 'absent'   then nullif(trim(coalesce(v_txt, '')), '') is null
        when 'contains' then coalesce(v_txt, '') ilike '%' || coalesce(pr ->> 'value', '') || '%'
        when 'equals'   then trim(coalesce(v_txt, '')) = trim(coalesce(pr ->> 'value', ''))
        else false end;
      v_actual := to_jsonb(case when pr ->> 'field' in ('image_url') then (case when v_txt is null then null else 'موجودة' end) else v_txt end);

    when 'exam_passed' then
      v_ok := nullif(pr ->> 'exam_id', '') is not null and exists (
        select 1 from public.exam_attempts a
         where a.person_id = p_person.id and a.exam_id = (pr ->> 'exam_id')::uuid
           and a.status = 'submitted' and a.passed = true);
      v_actual := to_jsonb(v_ok);

    when 'achievement' then
      v_ok := nullif(pr ->> 'achievement_id', '') is not null and exists (
        select 1 from public.user_achievements u
         where u.person_id = p_person.id and u.achievement_id = (pr ->> 'achievement_id')::uuid);
      v_actual := to_jsonb(v_ok);

    when 'occasion' then
      v_ok := nullif(pr ->> 'occasion_id', '') is not null and exists (
        select 1 from public.occasion_registrations r
         where r.person_id = p_person.id and r.occasion_id = (pr ->> 'occasion_id')::uuid
           and r.status = any (coalesce(
             (select array_agg(x) from jsonb_array_elements_text(pr -> 'statuses') x),
             array['confirmed', 'checked_in'])));
      v_actual := to_jsonb(v_ok);

    when 'not_entered' then
      select count(*) into v_hit
        from public.access_log l
       where l.event_id = p_event.id and l.person_id = p_person.id and l.granted
         and (coalesce(pr ->> 'period', 'day') <> 'day' or l.checked_on = (now() at time zone 'Africa/Cairo')::date);
      v_ok := v_hit = 0;
      v_actual := to_jsonb(v_hit);

    else
      v_ok := false;
      v_actual := 'null'::jsonb;
  end case;

  return jsonb_build_object('fulfilled', v_ok, 'actual', v_actual);
exception when others then
  return jsonb_build_object('fulfilled', false, 'actual', 'null'::jsonb, 'error', sqlerrm);
end $$;
revoke all on function public.access_eval_rule(public.access_rules, public.persons, uuid[], public.access_events) from public, anon, authenticated;

-- Evaluate a GROUP (null = root) recursively.
-- Returns {ok, empty, rules: [...], groups: [...]} — rules / groups are FLAT
-- lists of every descendant so the UI can render the tree from parent ids.
create or replace function public.access_eval_group(
  p_event  public.access_events,
  p_group  uuid,
  p_op     text,
  p_person public.persons,
  p_enr    uuid[]
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  r       public.access_rules;
  g       public.access_rule_groups;
  res     jsonb;
  sub     jsonb;
  rules   jsonb := '[]'::jsonb;
  groups  jsonb := '[]'::jsonb;
  n_children int := 0;
  n_true  int := 0;
  v_ok    boolean;
begin
  for r in
    select * from public.access_rules x
     where x.event_id = p_event.id and x.group_id is not distinct from p_group
     order by x.sort_order, x.created_at
  loop
    if r.enabled then
      res := public.access_eval_rule(r, p_person, p_enr, p_event);
      n_children := n_children + 1;
      if (res ->> 'fulfilled')::boolean then n_true := n_true + 1; end if;
      rules := rules || jsonb_build_object(
        'id', r.id, 'group_id', r.group_id, 'name', r.name, 'kind', r.kind, 'params', r.params,
        'enabled', true, 'sort_order', r.sort_order,
        'fulfilled', (res ->> 'fulfilled')::boolean, 'actual', res -> 'actual', 'error', res ->> 'error');
    else
      rules := rules || jsonb_build_object(
        'id', r.id, 'group_id', r.group_id, 'name', r.name, 'kind', r.kind, 'params', r.params,
        'enabled', false, 'sort_order', r.sort_order, 'fulfilled', null, 'actual', null);
    end if;
  end loop;

  for g in
    select * from public.access_rule_groups x
     where x.event_id = p_event.id and x.parent_id is not distinct from p_group
     order by x.sort_order, x.created_at
  loop
    sub := public.access_eval_group(p_event, g.id, g.op, p_person, p_enr);
    if not (sub ->> 'empty')::boolean then
      n_children := n_children + 1;
      if (sub ->> 'ok')::boolean then n_true := n_true + 1; end if;
    end if;
    groups := groups || jsonb_build_object(
      'id', g.id, 'parent_id', g.parent_id, 'name', g.name, 'op', g.op, 'sort_order', g.sort_order,
      'ok', (sub ->> 'ok')::boolean, 'empty', (sub ->> 'empty')::boolean);
    groups := groups || (sub -> 'groups');
    rules := rules || (sub -> 'rules');
  end loop;

  v_ok := case when n_children = 0 then true
               when p_op = 'or' then n_true > 0
               else n_true = n_children end;
  return jsonb_build_object('ok', v_ok, 'empty', n_children = 0, 'rules', rules, 'groups', groups);
end $$;
revoke all on function public.access_eval_group(public.access_events, uuid, text, public.persons, uuid[]) from public, anon, authenticated;

-- Which allowed entries cover this person? → jsonb array (empty = none)
create or replace function public.access_allowed_matches(p_event uuid, p_person uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', a.id, 'person_id', a.person_id, 'church_id', a.church_id, 'service_id', a.service_id, 'class_id', a.class_id)), '[]'::jsonb)
    from public.access_allowed a
   where a.event_id = p_event
     and (
       a.person_id = p_person
       or (a.person_id is null and exists (
         select 1 from public.enrollments e
          where e.person_id = p_person
            and coalesce(e.status::text, 'active') = 'active'
            and e.church_id = a.church_id
            and (a.service_id is null or e.service_id = a.service_id)
            and (a.class_id is null or e.class_id = a.class_id)))
     )
$$;
revoke all on function public.access_allowed_matches(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. RPC — access_check(event, code | person, log)
-- ---------------------------------------------------------------------
create or replace function public.access_check(
  p_event  uuid,
  p_code   text default null,
  p_person uuid default null,
  p_log    boolean default true
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  ev        public.access_events%rowtype;
  p         public.persons%rowtype;
  v_code    text := nullif(trim(coalesce(p_code, '')), '');
  v_found   boolean := false;
  v_enr     uuid[];
  v_in_scope boolean := true;
  v_allowed_by jsonb;
  v_allowed boolean;
  v_tree    jsonb;
  v_rules_ok boolean;
  v_granted boolean;
  v_reason  text;
  v_log_id  uuid;
  v_enrollments jsonb;
  v_history jsonb;
  v_visits  jsonb;
  v_summary jsonb;
  v_today   date := (now() at time zone 'Africa/Cairo')::date;
begin
  if not public.access_can('access.check') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into ev from public.access_events e where e.id = p_event;
  if not found or not public.scope_overlaps(ev.church_id, ev.service_id, ev.class_id) then
    raise exception 'event_not_found' using errcode = 'P0002';
  end if;

  if p_person is not null then
    select * into p from public.persons x where x.id = p_person;
    v_found := found;
  elsif v_code is not null then
    select * into p from public.persons x where x.national_id = v_code;
    v_found := found;
  end if;

  if not v_found then
    if p_log and v_code is not null then
      insert into public.access_log (event_id, person_id, code, granted, allowed, rules_ok, reason, checked_by)
      values (ev.id, null, v_code, false, false, false, 'not_found', auth.uid())
      returning id into v_log_id;
    end if;
    return jsonb_build_object(
      'event', to_jsonb(ev), 'matched', false, 'person', null, 'code', v_code,
      'granted', false, 'allowed', false, 'reason', 'not_found', 'log_id', v_log_id);
  end if;

  -- metrics scope: active enrollments inside the event's scope, else all active
  select coalesce(array_agg(e.id), '{}') into v_enr
    from public.enrollments e
   where e.person_id = p.id and coalesce(e.status::text, 'active') = 'active'
     and e.church_id = ev.church_id
     and (ev.service_id is null or e.service_id = ev.service_id)
     and (ev.class_id is null or e.class_id = ev.class_id);
  if coalesce(array_length(v_enr, 1), 0) = 0 then
    v_in_scope := false;
    select coalesce(array_agg(e.id), '{}') into v_enr
      from public.enrollments e
     where e.person_id = p.id and coalesce(e.status::text, 'active') = 'active';
  end if;

  -- allowed list
  if ev.allow_all then
    v_allowed := true; v_allowed_by := '[]'::jsonb;
  else
    v_allowed_by := public.access_allowed_matches(ev.id, p.id);
    v_allowed := jsonb_array_length(v_allowed_by) > 0;
  end if;

  -- rules
  v_tree := public.access_eval_group(ev, null, ev.root_op, p, v_enr);
  v_rules_ok := (v_tree ->> 'ok')::boolean;

  v_granted := ev.is_active and v_allowed and v_rules_ok;
  v_reason := case
    when not ev.is_active then 'inactive'
    when not v_allowed then 'not_allowed'
    when not v_rules_ok then 'rules'
    else null end;

  -- person context for the door screen
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
           'church_name', c.name, 'service_name', s.name, 'class_name', k.name,
           'points', e.points, 'attendance_count', e.attendance_count, 'status', coalesce(e.status::text, 'active'),
           'kind', coalesce(e.kind::text, 'child'), 'in_scope', e.id = any(v_enr))
           order by (e.id = any(v_enr)) desc, e.created_at), '[]'::jsonb)
    into v_enrollments
    from public.enrollments e
    left join public.churches c on c.id = e.church_id
    left join public.services s on s.id = e.service_id
    left join public.classes  k on k.id = e.class_id
   where e.person_id = p.id;

  select coalesce(jsonb_agg(x order by x -> 'created_at' desc), '[]'::jsonb) into v_history
    from (
      select jsonb_build_object(
               'id', a.id, 'attended_on', a.attended_on, 'created_at', a.created_at,
               'event_id', a.event_id, 'event_name', evn.name, 'points_delta', a.points_delta,
               'service_name', s.name, 'class_name', k.name) as x
        from public.attendance_log a
        join public.enrollments e on e.id = a.enrollment_id
        left join public.events evn on evn.id = a.event_id
        left join public.services s on s.id = e.service_id
        left join public.classes  k on k.id = e.class_id
       where e.person_id = p.id
       order by a.created_at desc
       limit 12
    ) h;

  select coalesce(jsonb_agg(x order by x -> 'created_at' desc), '[]'::jsonb) into v_visits
    from (
      select jsonb_build_object('id', l.id, 'created_at', l.created_at, 'granted', l.granted, 'reason', l.reason,
                                'checked_by_name', se.full_name) as x
        from public.access_log l
        left join public.servant_enrollments se on se.id = l.checked_by
       where l.event_id = ev.id and l.person_id = p.id
       order by l.created_at desc
       limit 6
    ) v;

  select jsonb_build_object(
           'points', coalesce((select sum(e.points) from public.enrollments e where e.id = any(v_enr)), 0),
           'attendance_count', coalesce((select sum(e.attendance_count) from public.enrollments e where e.id = any(v_enr)), 0),
           'last_attended_on', (select max(a.attended_on) from public.attendance_log a where a.enrollment_id = any(v_enr)),
           'attended_today', exists (select 1 from public.attendance_log a where a.enrollment_id = any(v_enr) and a.attended_on = v_today),
           'entered_today', (select count(*) from public.access_log l where l.event_id = ev.id and l.person_id = p.id and l.granted and l.checked_on = v_today),
           'entered_total', (select count(*) from public.access_log l where l.event_id = ev.id and l.person_id = p.id and l.granted),
           'in_scope', v_in_scope,
           'scope_enrollments', coalesce(array_length(v_enr, 1), 0))
    into v_summary;

  if p_log then
    insert into public.access_log (event_id, person_id, code, granted, allowed, rules_ok, reason, details, checked_by)
    values (ev.id, p.id, coalesce(v_code, p.national_id), v_granted, v_allowed, v_rules_ok, v_reason,
            jsonb_build_object('rules', v_tree -> 'rules', 'groups', v_tree -> 'groups', 'allowed_by', v_allowed_by), auth.uid())
    returning id into v_log_id;
  end if;

  return jsonb_build_object(
    'event', to_jsonb(ev),
    'matched', true,
    'person', to_jsonb(p),
    'code', coalesce(v_code, p.national_id),
    'enrollments', v_enrollments,
    'summary', v_summary,
    'history', v_history,
    'visits', v_visits,
    'allowed', v_allowed,
    'allowed_by', v_allowed_by,
    'rules', jsonb_build_object('ok', v_rules_ok, 'empty', (v_tree ->> 'empty')::boolean, 'root_op', ev.root_op,
                                'rules', v_tree -> 'rules', 'groups', v_tree -> 'groups'),
    'granted', v_granted,
    'reason', v_reason,
    'log_id', v_log_id
  );
end $$;
revoke all on function public.access_check(uuid, text, uuid, boolean) from public, anon;
grant execute on function public.access_check(uuid, text, uuid, boolean) to authenticated;
comment on function public.access_check(uuid, text, uuid, boolean) is
  'البوابة: كود شخص (أو معرّفه) + بوابة دخول → مسموح / مرفوض مع كل قاعدة وحالتها، وبيانات الشخص وحضوره؛ p_log = تسجيل المحاولة';

-- ---------------------------------------------------------------------
-- 5. RPC — access_search_persons(q, limit)
-- ---------------------------------------------------------------------
create or replace function public.access_search_persons(p_query text, p_limit integer default 30)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_q     text := nullif(trim(coalesce(p_query, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_out   jsonb;
begin
  if not public.access_can('access.check') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_q is null or length(v_q) < 2 then
    return '[]'::jsonb;
  end if;
  with hits as (
    select p.*
      from public.persons p
     where (p.name ilike '%' || v_q || '%' or p.phone ilike '%' || v_q || '%' or p.national_id ilike '%' || v_q || '%')
       and (
         public.is_owner()
         or exists (select 1 from public.enrollments e
                     where e.person_id = p.id and public.can_access(e.church_id, e.service_id, e.class_id))
       )
     order by (p.national_id = v_q) desc, p.name collate "C"
     limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'person', to_jsonb(h),
           'places', coalesce((
             select jsonb_agg(jsonb_build_object('church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
                                                 'points', e.points, 'attendance_count', e.attendance_count) order by e.created_at)
               from public.enrollments e
              where e.person_id = h.id and public.can_access(e.church_id, e.service_id, e.class_id)), '[]'::jsonb)
         ) order by (h.national_id = v_q) desc, h.name collate "C"), '[]'::jsonb)
    into v_out
    from hits h;
  return v_out;
end $$;
revoke all on function public.access_search_persons(text, integer) from public, anon;
grant execute on function public.access_search_persons(text, integer) to authenticated;

