-- ---------------------------------------------------------------------
-- 4. HELPERS
-- ---------------------------------------------------------------------
create or replace function public.cairo_today_date()
returns date language sql stable as $$ select (now() at time zone 'Africa/Cairo')::date $$;

-- person → compact json for the portal lists
create or replace function public.priest_person_json(p public.persons)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'id', p.id, 'national_id', p.national_id, 'name', p.name, 'gender', p.gender,
    'birthdate', p.birthdate, 'phone', p.phone, 'address', p.address, 'notes', p.notes,
    'image_url', p.image_url, 'created_at', p.created_at)
$$;

-- the places of a person (church → service → class names) — for the lists
create or replace function public.priest_person_places(p_person uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'enrollment_id', e.id, 'kind', e.kind, 'status', e.status,
           'church_name', ch.name, 'service_name', sv.name, 'class_name', cl.name) order by e.created_at), '[]'::jsonb)
    from public.enrollments e
    join public.churches ch on ch.id = e.church_id
    join public.services sv on sv.id = e.service_id
    join public.classes cl on cl.id = e.class_id
   where e.person_id = p_person
$$;

-- ---------------------------------------------------------------------
-- 5. SESSIONS — resolver · login · logout · touch · change password
-- ---------------------------------------------------------------------
create or replace function public.priest_portal_self(p_token text)
returns public.priests language plpgsql stable security definer set search_path = public, extensions as $$
declare
  s public.priest_sessions;
  pr public.priests;
begin
  if p_token is null or length(trim(p_token)) < 20 then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;
  select * into s from public.priest_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
  if not found or s.expires_at < now() then
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  select * into pr from public.priests where id = s.priest_id;
  if not found then raise exception 'session_expired' using errcode = 'P0002'; end if;
  if pr.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
  perform set_config('app.priest_actor', pr.id::text, true);
  return pr;
end $$;
revoke all on function public.priest_portal_self(text) from public, anon, authenticated;

create or replace function public.priest_login(p_code text, p_password text, p_remember boolean default false, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  pr public.priests;
  v_token text;
  v_exp timestamptz;
begin
  if nullif(trim(coalesce(p_code, '')), '') is null then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  if exists (select 1 from public.priest_requests r where r.code = trim(p_code) and r.status = 'pending') then
    raise exception 'pending_approval' using errcode = 'P0001';
  end if;
  select * into p from public.persons where national_id = trim(p_code);
  if not found then raise exception 'unknown_code' using errcode = 'P0002'; end if;
  select * into pr from public.priests where person_id = p.id;
  if not found then raise exception 'not_priest' using errcode = 'P0002'; end if;
  if coalesce(p_password, '') = '' or pr.password_hash <> crypt(p_password, pr.password_hash) then
    perform pg_sleep(0.25);
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  if pr.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
  if pr.status = 'rejected' then raise exception 'account_rejected' using errcode = 'P0001'; end if;
  if pr.status = 'suspended' then raise exception 'account_stopped' using errcode = 'P0001'; end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_exp := case when coalesce(p_remember, false) then now() + interval '90 days' else now() + interval '12 hours' end;
  insert into public.priest_sessions (priest_id, token_hash, remember, expires_at, user_agent)
  values (pr.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, false), v_exp, left(p_user_agent, 300));
  delete from public.priest_sessions where expires_at < now() - interval '1 day';
  perform set_config('app.priest_actor', pr.id::text, true);
  return jsonb_build_object('token', v_token, 'expires_at', v_exp, 'priest_id', pr.id, 'remember', coalesce(p_remember, false));
end $$;
grant execute on function public.priest_login(text, text, boolean, text) to anon, authenticated;

create or replace function public.priest_logout(p_token text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if nullif(trim(coalesce(p_token, '')), '') is null then return; end if;
  delete from public.priest_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
end $$;
grant execute on function public.priest_logout(text) to anon, authenticated;

create or replace function public.priest_session_touch(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare s public.priest_sessions; pr public.priests;
begin
  if p_token is null or length(trim(p_token)) < 20 then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into s from public.priest_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
  if not found then raise exception 'session_expired' using errcode = 'P0002'; end if;
  if s.expires_at < now() then
    delete from public.priest_sessions where id = s.id;
    raise exception 'session_expired' using errcode = 'P0002';
  end if;
  select * into pr from public.priests where id = s.priest_id;
  if not found or pr.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
  update public.priest_sessions
     set last_seen_at = now(),
         expires_at = case when remember then greatest(expires_at, now() + interval '90 days') else expires_at end
   where id = s.id
   returning * into s;
  return jsonb_build_object('priest_id', s.priest_id, 'expires_at', s.expires_at, 'remember', s.remember);
end $$;
grant execute on function public.priest_session_touch(text) to anon, authenticated;

create or replace function public.priest_change_password(p_token text, p_current text, p_new text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  if length(coalesce(p_new, '')) < 6 then raise exception 'weak_password' using errcode = 'P0001'; end if;
  if pr.password_hash <> crypt(coalesce(p_current, ''), pr.password_hash) then
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  update public.priests set password_hash = crypt(p_new, gen_salt('bf', 10)) where id = pr.id;
  delete from public.priest_sessions
   where priest_id = pr.id and token_hash <> encode(digest(trim(p_token), 'sha256'), 'hex');
end $$;
grant execute on function public.priest_change_password(text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. SIGNUP (anonymous) → a pending request the OWNER reviews
-- ---------------------------------------------------------------------
create or replace function public.priest_signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'exists', exists (select 1 from public.persons p where p.national_id = trim(p_code)),
      'is_priest', exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id where p.national_id = trim(p_code)),
      'pending', exists (select 1 from public.priest_requests r where r.code = trim(p_code) and r.status = 'pending'),
      'name', (select p.name from public.persons p where p.national_id = trim(p_code) limit 1)
    )
  end
$$;
grant execute on function public.priest_signup_lookup_code(text) to anon, authenticated;

create or replace function public.priest_signup(
  p_code text, p_name text, p_password text, p_church uuid,
  p_title text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid;
begin
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if p_church is null or not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  if exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id where p.national_id = v_code) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  if exists (select 1 from public.priest_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;
  insert into public.priest_requests (code, name, title, gender, birthdate, phone, address, notes, image_url, password_hash, church_id)
  values (v_code, trim(p_name), nullif(trim(coalesce(p_title, '')), ''), p_gender, p_birthdate,
          nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
          nullif(trim(coalesce(p_notes, '')), ''), p_image_url, crypt(p_password, gen_salt('bf', 10)), p_church)
  returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'code', v_code);
end $$;
grant execute on function public.priest_signup(text, text, text, uuid, text, text, date, text, text, text, text) to anon, authenticated;

create or replace function public.priest_signup_status(p_request uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('status', r.status, 'decision_note', r.decision_note, 'code', r.code)
    from public.priest_requests r where r.id = p_request
$$;
grant execute on function public.priest_signup_status(uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 7. OWNER — review · add · edit · password · delete · overview
-- ---------------------------------------------------------------------
create or replace function public.owner_review_priest_request(
  p_request uuid, p_approve boolean, p_note text default null, p_church uuid default null, p_title text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  r public.priest_requests;
  v_person public.persons%rowtype;
  v_church uuid;
  v_priest uuid;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into r from public.priest_requests where id = p_request;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;

  if not p_approve then
    update public.priest_requests
       set status = 'rejected', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now()
     where id = r.id;
    return jsonb_build_object('status', 'rejected');
  end if;

  v_church := coalesce(p_church, r.church_id);
  if v_church is null or not exists (select 1 from public.churches c where c.id = v_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;

  select * into v_person from public.persons where national_id = r.code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (r.code, r.name, r.gender, r.birthdate, r.phone, r.address, r.notes, r.image_url, auth.uid(), auth.uid())
    returning * into v_person;
  else
    update public.persons set
      gender = coalesce(gender, r.gender), birthdate = coalesce(birthdate, r.birthdate),
      phone = coalesce(phone, r.phone), address = coalesce(address, r.address),
      notes = coalesce(notes, r.notes), image_url = coalesce(image_url, r.image_url),
      edited_by = auth.uid(), edited_at = now()
    where id = v_person.id returning * into v_person;
  end if;
  if exists (select 1 from public.priests where person_id = v_person.id) then
    raise exception 'already_registered' using errcode = '23505';
  end if;

  insert into public.priests (person_id, church_id, title, status, password_hash, approved_by, approved_at)
  values (v_person.id, v_church, coalesce(nullif(trim(coalesce(p_title, '')), ''), r.title), 'approved', r.password_hash, auth.uid(), now())
  returning id into v_priest;

  update public.priest_requests
     set status = 'approved', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now(),
         church_id = v_church, priest_id = v_priest
   where id = r.id;
  return jsonb_build_object('status', 'approved', 'priest_id', v_priest, 'person_id', v_person.id);
end $$;
revoke all on function public.owner_review_priest_request(uuid, boolean, text, uuid, text) from public, anon;
grant execute on function public.owner_review_priest_request(uuid, boolean, text, uuid, text) to authenticated;

create or replace function public.owner_add_priest(
  p_code text, p_name text, p_password text, p_church uuid,
  p_title text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_person public.persons%rowtype;
  v_priest uuid;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if p_church is null or not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  select * into v_person from public.persons where national_id = v_code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, trim(p_name), p_gender, p_birthdate, nullif(trim(coalesce(p_phone, '')), ''),
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''), p_image_url, auth.uid(), auth.uid())
    returning * into v_person;
  else
    update public.persons set
      name = coalesce(nullif(trim(p_name), ''), name),
      gender = coalesce(p_gender, gender), birthdate = coalesce(p_birthdate, birthdate),
      phone = coalesce(nullif(trim(coalesce(p_phone, '')), ''), phone),
      address = coalesce(nullif(trim(coalesce(p_address, '')), ''), address),
      notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
      image_url = coalesce(p_image_url, image_url),
      edited_by = auth.uid(), edited_at = now()
    where id = v_person.id returning * into v_person;
  end if;
  if exists (select 1 from public.priests where person_id = v_person.id) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  insert into public.priests (person_id, church_id, title, status, password_hash, approved_by, approved_at)
  values (v_person.id, p_church, nullif(trim(coalesce(p_title, '')), ''), 'approved', crypt(p_password, gen_salt('bf', 10)), auth.uid(), now())
  returning id into v_priest;
  -- a pending request for the same code is closed
  update public.priest_requests set status = 'approved', decided_by = auth.uid(), decided_at = now(), priest_id = v_priest
   where code = v_code and status = 'pending';
  return jsonb_build_object('priest_id', v_priest, 'person_id', v_person.id, 'code', v_code);
end $$;
revoke all on function public.owner_add_priest(text, text, text, uuid, text, text, date, text, text, text, text) from public, anon;
grant execute on function public.owner_add_priest(text, text, text, uuid, text, text, date, text, text, text, text) to authenticated;

-- edit the priest row (church · title · status · notes · reminder) — the
-- person data is edited through `persons` (owner RLS)
create or replace function public.owner_update_priest(
  p_priest uuid, p_church uuid default null, p_title text default null, p_status text default null,
  p_notes text default null, p_reminder_days integer default null
) returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status is not null and p_status not in ('approved', 'suspended') then raise exception 'invalid_status' using errcode = '22023'; end if;
  if p_church is not null and not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  update public.priests set
    church_id = coalesce(p_church, church_id),
    title = case when p_title is null then title else nullif(trim(p_title), '') end,
    status = coalesce(p_status, status),
    notes = case when p_notes is null then notes else nullif(trim(p_notes), '') end,
    reminder_days = coalesce(p_reminder_days, reminder_days)
  where id = p_priest;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if p_status = 'suspended' then delete from public.priest_sessions where priest_id = p_priest; end if;
end $$;
revoke all on function public.owner_update_priest(uuid, uuid, text, text, text, integer) from public, anon;
grant execute on function public.owner_update_priest(uuid, uuid, text, text, text, integer) to authenticated;

create or replace function public.owner_set_priest_password(p_priest uuid, p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  update public.priests set password_hash = crypt(p_password, gen_salt('bf', 10)) where id = p_priest;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  delete from public.priest_sessions where priest_id = p_priest;
end $$;
revoke all on function public.owner_set_priest_password(uuid, text) from public, anon;
grant execute on function public.owner_set_priest_password(uuid, text) to authenticated;

-- delete the priest account (the person row stays — he may be a servant / parent)
create or replace function public.owner_delete_priest(p_priest uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  delete from public.priests where id = p_priest;
end $$;
revoke all on function public.owner_delete_priest(uuid) from public, anon;
grant execute on function public.owner_delete_priest(uuid) to authenticated;

-- the owner page: every priest with his person, church and counters
create or replace function public.owner_priests_overview()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.is_owner() then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', pr.id, 'person_id', pr.person_id, 'church_id', pr.church_id, 'church_name', ch.name,
      'title', pr.title, 'status', pr.status, 'reminder_days', pr.reminder_days, 'notes', pr.notes,
      'approved_at', pr.approved_at, 'created_at', pr.created_at,
      'person', public.priest_person_json(p),
      'confessors_count', (select count(*) from public.priest_confessors c where c.priest_id = pr.id),
      'confessions_count', (select count(*) from public.confessions c where c.priest_id = pr.id),
      'pending_appointments', (select count(*) from public.confession_appointments a where a.priest_id = pr.id and a.status = 'pending'),
      'last_seen_at', (select max(s.last_seen_at) from public.priest_sessions s where s.priest_id = pr.id)
    ) order by p.name collate "C")
    from public.priests pr
    join public.persons p on p.id = pr.person_id
    join public.churches ch on ch.id = pr.church_id), '[]'::jsonb)
  else '[]'::jsonb end
$$;
revoke all on function public.owner_priests_overview() from public, anon;
grant execute on function public.owner_priests_overview() to authenticated;

create or replace function public.pending_priest_requests_count()
returns integer language sql stable security definer set search_path = public as $$
  select case when public.is_owner() then (select count(*)::int from public.priest_requests where status = 'pending') else 0 end
$$;
grant execute on function public.pending_priest_requests_count() to authenticated;



-- #####################################################################
-- ##  20260927130000_priests_confessors.sql
-- #####################################################################

-- =====================================================================
-- 20260927130000 — PRIEST PORTAL part 2: المعترفين · الاعترافات · المواعيد ·
--                  الافتقاد + the child-portal side (طلب موعد اعتراف)
-- Requires 20260927120000_priests_portal.sql (tables + sessions + owner).
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. PROFILE
-- ---------------------------------------------------------------------
create or replace function public.priest_portal_profile(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons; ch public.churches;
begin
  pr := public.priest_portal_self(p_token);
  select * into p from public.persons where id = pr.person_id;
  select * into ch from public.churches where id = pr.church_id;
  return jsonb_build_object(
    'priest', jsonb_build_object('id', pr.id, 'title', pr.title, 'status', pr.status, 'reminder_days', pr.reminder_days,
                                 'church_id', pr.church_id, 'created_at', pr.created_at),
    'person', public.priest_person_json(p),
    'church', jsonb_build_object('id', ch.id, 'name', ch.name, 'logo_url', ch.logo_url),
    'counts', jsonb_build_object(
      'confessors', (select count(*) from public.priest_confessors c where c.priest_id = pr.id),
      'overdue', (select count(*) from public.priest_confessors c where c.priest_id = pr.id
                    and coalesce((select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id), c.created_at::date)
                        < public.cairo_today_date() - pr.reminder_days),
      'pending_appointments', (select count(*) from public.confession_appointments a where a.priest_id = pr.id and a.status = 'pending'),
      'today_appointments', (select count(*) from public.confession_appointments a where a.priest_id = pr.id and a.status = 'approved'
                               and coalesce(a.scheduled_on, a.requested_on) = public.cairo_today_date())
    ),
    'server_today', public.cairo_today_date()
  );
end $$;
grant execute on function public.priest_portal_profile(text) to anon, authenticated;

create or replace function public.priest_set_reminder_days(p_token text, p_days integer)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  if p_days is null or p_days < 1 or p_days > 365 then raise exception 'invalid_days' using errcode = '22023'; end if;
  update public.priests set reminder_days = p_days where id = pr.id;
end $$;
grant execute on function public.priest_set_reminder_days(text, integer) to anon, authenticated;

-- the priest edits his own person data (name · phone · address · photo …)
create or replace function public.priest_update_self(p_token text, p_changes jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons;
begin
  pr := public.priest_portal_self(p_token);
  update public.persons set
    name      = coalesce(nullif(trim(p_changes->>'name'), ''), name),
    phone     = case when p_changes ? 'phone' then nullif(trim(p_changes->>'phone'), '') else phone end,
    address   = case when p_changes ? 'address' then nullif(trim(p_changes->>'address'), '') else address end,
    birthdate = case when p_changes ? 'birthdate' then nullif(p_changes->>'birthdate', '')::date else birthdate end,
    image_url = case when p_changes ? 'image_url' then nullif(p_changes->>'image_url', '') else image_url end,
    edited_at = now()
  where id = pr.person_id returning * into p;
  if p_changes ? 'title' then update public.priests set title = nullif(trim(p_changes->>'title'), '') where id = pr.id; end if;
  return public.priest_person_json(p);
end $$;
grant execute on function public.priest_update_self(text, jsonb) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 2. JSON BUILDERS
-- ---------------------------------------------------------------------
create or replace function public.priest_appointment_json(a public.confession_appointments)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', a.id, 'person_id', a.person_id, 'requested_by', a.requested_by,
    'requested_on', a.requested_on, 'requested_time', a.requested_time, 'note', a.note,
    'status', a.status, 'scheduled_on', a.scheduled_on, 'scheduled_time', a.scheduled_time,
    'on', coalesce(a.scheduled_on, a.requested_on), 'time', coalesce(a.scheduled_time, a.requested_time),
    'decision_note', a.decision_note, 'decided_at', a.decided_at, 'created_at', a.created_at,
    'person', (select public.priest_person_json(p) from public.persons p where p.id = a.person_id),
    'is_confessor', exists (select 1 from public.priest_confessors c where c.priest_id = a.priest_id and c.person_id = a.person_id),
    'last_confession', (select max(x.confessed_on) from public.confessions x where x.priest_id = a.priest_id and x.person_id = a.person_id)
  )
$$;

create or replace function public.priest_confessor_json(pr public.priests, c public.priest_confessors)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', c.id, 'person_id', c.person_id, 'notes', c.notes, 'created_at', c.created_at,
    'person', public.priest_person_json(p),
    'places', public.priest_person_places(p.id),
    'last_confession', (select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id),
    'confessions_count', (select count(*) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id),
    'days_since', public.cairo_today_date() - coalesce(
        (select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id), c.created_at::date),
    'overdue', coalesce((select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id), c.created_at::date)
               < public.cairo_today_date() - pr.reminder_days,
    'last_contact', (select jsonb_build_object('kind', k.kind, 'created_at', k.created_at)
                       from public.priest_contacts k where k.priest_id = pr.id and k.person_id = c.person_id
                      order by k.created_at desc limit 1),
    'next_appointment', (select jsonb_build_object('id', a.id, 'status', a.status,
                                 'on', coalesce(a.scheduled_on, a.requested_on), 'time', coalesce(a.scheduled_time, a.requested_time),
                                 'requested_by', a.requested_by)
                           from public.confession_appointments a
                          where a.priest_id = pr.id and a.person_id = c.person_id and a.status in ('pending', 'approved')
                            and coalesce(a.scheduled_on, a.requested_on) >= public.cairo_today_date()
                          order by coalesce(a.scheduled_on, a.requested_on), coalesce(a.scheduled_time, a.requested_time) nulls last limit 1)
  ) from public.persons p where p.id = c.person_id
$$;

-- ---------------------------------------------------------------------
-- 3. المعترفين — list · lookup · search · add (code / id / new) · edit · remove
-- ---------------------------------------------------------------------
create or replace function public.priest_confessors_list(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return coalesce((select jsonb_agg(public.priest_confessor_json(pr, c) order by c.created_at desc)
                     from public.priest_confessors c where c.priest_id = pr.id), '[]'::jsonb);
end $$;
grant execute on function public.priest_confessors_list(text) to anon, authenticated;

create or replace function public.priest_lookup_code(p_token text, p_code text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons; c public.priest_confessors; v_is boolean;
begin
  pr := public.priest_portal_self(p_token);
  select * into p from public.persons where national_id = trim(coalesce(p_code, ''));
  if not found then return jsonb_build_object('found', false, 'code', trim(coalesce(p_code, ''))); end if;
  select * into c from public.priest_confessors where priest_id = pr.id and person_id = p.id;
  v_is := found;
  return jsonb_build_object('found', true, 'person', public.priest_person_json(p), 'places', public.priest_person_places(p.id),
                            'is_confessor', v_is, 'confessor', case when v_is then public.priest_confessor_json(pr, c) else null end);
end $$;
grant execute on function public.priest_lookup_code(text, text) to anon, authenticated;

-- persons of HIS church (enrolled there) · his confessors · persons with no
-- enrollment at all (adults created by a priest / a family)
create or replace function public.priest_search_persons(p_token text, p_query text, p_limit integer default 30)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare
  pr public.priests;
  v_q text := nullif(trim(coalesce(p_query, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
begin
  pr := public.priest_portal_self(p_token);
  if v_q is null or length(v_q) < 2 then return '[]'::jsonb; end if;
  return coalesce((
    with hits as (
      select p.* from public.persons p
       where (p.name ilike '%' || v_q || '%' or p.phone ilike '%' || v_q || '%' or p.national_id ilike '%' || v_q || '%')
         and (exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id)
              or exists (select 1 from public.priest_confessors c where c.person_id = p.id and c.priest_id = pr.id)
              or not exists (select 1 from public.enrollments e where e.person_id = p.id))
       order by (p.national_id = v_q) desc, p.name collate "C"
       limit v_limit)
    select jsonb_agg(jsonb_build_object(
             'person', public.priest_person_json(h), 'places', public.priest_person_places(h.id),
             'is_confessor', exists (select 1 from public.priest_confessors c where c.priest_id = pr.id and c.person_id = h.id),
             'other_priest', (select pp.name from public.priest_confessors c join public.priests x on x.id = c.priest_id
                                join public.persons pp on pp.id = x.person_id where c.person_id = h.id and c.priest_id <> pr.id limit 1)
           ) order by (h.national_id = v_q) desc, h.name collate "C")
      from hits h), '[]'::jsonb);
end $$;
grant execute on function public.priest_search_persons(text, text, integer) to anon, authenticated;

create or replace function public.priest_add_confessor(p_token text, p_person uuid, p_notes text default null, p_last_confession date default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; c public.priest_confessors;
begin
  pr := public.priest_portal_self(p_token);
  if not exists (select 1 from public.persons where id = p_person) then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.priest_confessors where priest_id = pr.id and person_id = p_person) then
    raise exception 'already_member' using errcode = 'P0001';
  end if;
  insert into public.priest_confessors (priest_id, person_id, notes) values (pr.id, p_person, nullif(trim(coalesce(p_notes, '')), ''))
  returning * into c;
  if p_last_confession is not null then
    if p_last_confession > public.cairo_today_date() then raise exception 'future_date' using errcode = '22023'; end if;
    insert into public.confessions (priest_id, person_id, confessed_on, notes) values (pr.id, p_person, p_last_confession, 'آخر اعتراف عند الإضافة');
  end if;
  return public.priest_confessor_json(pr, c);
end $$;
grant execute on function public.priest_add_confessor(text, uuid, text, date) to anon, authenticated;

create or replace function public.priest_add_confessor_by_code(p_token text, p_code text, p_notes text default null, p_last_confession date default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid;
begin
  perform public.priest_portal_self(p_token);
  select id into v_person from public.persons where national_id = trim(coalesce(p_code, ''));
  if v_person is null then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  return public.priest_add_confessor(p_token, v_person, p_notes, p_last_confession);
end $$;
grant execute on function public.priest_add_confessor_by_code(text, text, text, date) to anon, authenticated;

-- create the person here (no enrollment — he may be an adult) and add him;
-- a code that already belongs to a person → his blanks are filled and he is added
create or replace function public.priest_add_new_confessor(
  p_token text, p_name text, p_code text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null,
  p_last_confession date default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  pr public.priests;
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_person public.persons%rowtype;
begin
  pr := public.priest_portal_self(p_token);
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_code is not null then
    select * into v_person from public.persons where national_id = v_code;
    if found then
      update public.persons set
        gender = coalesce(gender, p_gender), birthdate = coalesce(birthdate, p_birthdate),
        phone = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')), address = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
        image_url = coalesce(image_url, p_image_url), edited_at = now()
      where id = v_person.id returning * into v_person;
      return public.priest_add_confessor(p_token, v_person.id, p_notes, p_last_confession) || jsonb_build_object('created', false);
    end if;
    if exists (select 1 from public.families f where f.code = v_code) then raise exception 'code_taken' using errcode = '23505'; end if;
  end if;
  if v_code is null then
    insert into public.persons (name, gender, birthdate, phone, address, notes, image_url)
    values (trim(p_name), p_gender, p_birthdate, nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
            nullif(trim(coalesce(p_notes, '')), ''), p_image_url) returning * into v_person;
  else
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url)
    values (v_code, trim(p_name), p_gender, p_birthdate, nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
            nullif(trim(coalesce(p_notes, '')), ''), p_image_url) returning * into v_person;
  end if;
  return public.priest_add_confessor(p_token, v_person.id, null, p_last_confession) || jsonb_build_object('created', true);
end $$;
grant execute on function public.priest_add_new_confessor(text, text, text, text, date, text, text, text, text, date) to anon, authenticated;

create or replace function public.priest_update_confessor(p_token text, p_confessor uuid, p_notes text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  update public.priest_confessors set notes = nullif(trim(coalesce(p_notes, '')), '') where id = p_confessor and priest_id = pr.id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_update_confessor(text, uuid, text) to anon, authenticated;

create or replace function public.priest_remove_confessor(p_token text, p_confessor uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.priest_confessors where id = p_confessor and priest_id = pr.id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_remove_confessor(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. CONFESSIONS + CONTACTS (الافتقاد) + HISTORY
-- ---------------------------------------------------------------------
create or replace function public.priest_record_confession(p_token text, p_person uuid, p_on date default null, p_notes text default null, p_appointment uuid default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; v public.confessions; c public.priest_confessors;
begin
  pr := public.priest_portal_self(p_token);
  select * into c from public.priest_confessors where priest_id = pr.id and person_id = p_person;
  if not found then
    insert into public.priest_confessors (priest_id, person_id) values (pr.id, p_person) returning * into c;
  end if;
  if p_on is not null and p_on > public.cairo_today_date() then raise exception 'future_date' using errcode = '22023'; end if;
  insert into public.confessions (priest_id, person_id, confessed_on, notes, appointment_id)
  values (pr.id, p_person, coalesce(p_on, public.cairo_today_date()), nullif(trim(coalesce(p_notes, '')), ''), p_appointment)
  returning * into v;
  if p_appointment is not null then
    update public.confession_appointments set status = 'done', decided_at = now() where id = p_appointment and priest_id = pr.id;
  end if;
  return jsonb_build_object('id', v.id, 'confessed_on', v.confessed_on, 'confessor', public.priest_confessor_json(pr, c));
end $$;
grant execute on function public.priest_record_confession(text, uuid, date, text, uuid) to anon, authenticated;

create or replace function public.priest_delete_confession(p_token text, p_confession uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.confessions where id = p_confession and priest_id = pr.id;
end $$;
grant execute on function public.priest_delete_confession(text, uuid) to anon, authenticated;

create or replace function public.priest_log_contact(p_token text, p_person uuid, p_kind text, p_message text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; k public.priest_contacts;
begin
  pr := public.priest_portal_self(p_token);
  if p_kind not in ('call', 'whatsapp', 'sms', 'note') then raise exception 'invalid_kind' using errcode = '22023'; end if;
  if not exists (select 1 from public.priest_confessors where priest_id = pr.id and person_id = p_person) then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  insert into public.priest_contacts (priest_id, person_id, kind, message)
  values (pr.id, p_person, p_kind, nullif(trim(coalesce(p_message, '')), '')) returning * into k;
  return jsonb_build_object('id', k.id, 'kind', k.kind, 'message', k.message, 'created_at', k.created_at);
end $$;
grant execute on function public.priest_log_contact(text, uuid, text, text) to anon, authenticated;

create or replace function public.priest_delete_contact(p_token text, p_contact uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.priest_contacts where id = p_contact and priest_id = pr.id;
end $$;
grant execute on function public.priest_delete_contact(text, uuid) to anon, authenticated;

create or replace function public.priest_confessor_history(p_token text, p_person uuid)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return jsonb_build_object(
    'confessions', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'confessed_on', x.confessed_on, 'notes', x.notes, 'created_at', x.created_at)
                                order by x.confessed_on desc, x.created_at desc)
                              from public.confessions x where x.priest_id = pr.id and x.person_id = p_person), '[]'::jsonb),
    'contacts', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'kind', k.kind, 'message', k.message, 'created_at', k.created_at)
                              order by k.created_at desc)
                            from public.priest_contacts k where k.priest_id = pr.id and k.person_id = p_person), '[]'::jsonb),
    'appointments', coalesce((select jsonb_agg(public.priest_appointment_json(a) order by coalesce(a.scheduled_on, a.requested_on) desc)
                                from public.confession_appointments a where a.priest_id = pr.id and a.person_id = p_person), '[]'::jsonb)
  );
end $$;
grant execute on function public.priest_confessor_history(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. APPOINTMENTS — priest side
-- ---------------------------------------------------------------------
create or replace function public.priest_appointments_list(p_token text, p_from date default null, p_to date default null, p_include_past boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return coalesce((
    select jsonb_agg(public.priest_appointment_json(a) order by coalesce(a.scheduled_on, a.requested_on), coalesce(a.scheduled_time, a.requested_time) nulls last, a.created_at)
      from public.confession_appointments a
     where a.priest_id = pr.id
       and (p_from is null or coalesce(a.scheduled_on, a.requested_on) >= p_from)
       and (p_to is null or coalesce(a.scheduled_on, a.requested_on) <= p_to)
       and (p_include_past or a.status = 'pending' or coalesce(a.scheduled_on, a.requested_on) >= public.cairo_today_date() - 1)
  ), '[]'::jsonb);
end $$;
grant execute on function public.priest_appointments_list(text, date, date, boolean) to anon, authenticated;

create or replace function public.priest_create_appointment(p_token text, p_person uuid, p_on date, p_time time default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; a public.confession_appointments;
begin
  pr := public.priest_portal_self(p_token);
  if p_on is null then raise exception 'date_required' using errcode = '22023'; end if;
  if not exists (select 1 from public.persons where id = p_person) then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.priest_confessors where priest_id = pr.id and person_id = p_person) then
    insert into public.priest_confessors (priest_id, person_id) values (pr.id, p_person);
  end if;
  insert into public.confession_appointments (priest_id, person_id, requested_by, requested_on, requested_time, note, status, scheduled_on, scheduled_time, decided_at)
  values (pr.id, p_person, 'priest', p_on, p_time, nullif(trim(coalesce(p_note, '')), ''), 'approved', p_on, p_time, now())
  returning * into a;
  return public.priest_appointment_json(a);
end $$;
grant execute on function public.priest_create_appointment(text, uuid, date, time, text) to anon, authenticated;

-- approve (optionally moving it) · reject · cancel · done (→ confession row)
create or replace function public.priest_decide_appointment(p_token text, p_appointment uuid, p_action text, p_on date default null, p_time time default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; a public.confession_appointments;
begin
  pr := public.priest_portal_self(p_token);
  select * into a from public.confession_appointments where id = p_appointment and priest_id = pr.id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if p_action = 'approve' then
    if a.status not in ('pending', 'approved') then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.confession_appointments
       set status = 'approved', scheduled_on = coalesce(p_on, a.scheduled_on, a.requested_on),
           scheduled_time = case when p_on is not null or p_time is not null then p_time else coalesce(a.scheduled_time, a.requested_time) end,
           decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now()
     where id = a.id returning * into a;
    if not exists (select 1 from public.priest_confessors where priest_id = pr.id and person_id = a.person_id) then
      insert into public.priest_confessors (priest_id, person_id) values (pr.id, a.person_id);
    end if;
  elsif p_action = 'reject' then
    if a.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.confession_appointments set status = 'rejected', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now()
     where id = a.id returning * into a;
  elsif p_action = 'cancel' then
    if a.status not in ('pending', 'approved') then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.confession_appointments set status = 'cancelled', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now()
     where id = a.id returning * into a;
  elsif p_action = 'done' then
    if a.status <> 'approved' then raise exception 'not_pending' using errcode = 'P0001'; end if;
    perform public.priest_record_confession(p_token, a.person_id, least(coalesce(a.scheduled_on, a.requested_on), public.cairo_today_date()), p_note, a.id);
    select * into a from public.confession_appointments where id = p_appointment;
  else
    raise exception 'invalid_action' using errcode = '22023';
  end if;
  return public.priest_appointment_json(a);
end $$;
grant execute on function public.priest_decide_appointment(text, uuid, text, date, time, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. CHILD PORTAL — الاعتراف: my priest(s) · ask for a date · my appointments
-- ---------------------------------------------------------------------
create or replace function public.child_portal_confession(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare p public.persons;
begin
  p := public.child_portal_person(p_token);
  return jsonb_build_object(
    'priests', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', pr.id, 'name', pp.name, 'title', pr.title, 'image_url', pp.image_url, 'church_id', pr.church_id, 'church_name', ch.name,
               'is_mine', exists (select 1 from public.priest_confessors c where c.priest_id = pr.id and c.person_id = p.id),
               'last_confession', (select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = p.id)
             ) order by exists (select 1 from public.priest_confessors c where c.priest_id = pr.id and c.person_id = p.id) desc, pp.name collate "C")
        from public.priests pr
        join public.persons pp on pp.id = pr.person_id
        join public.churches ch on ch.id = pr.church_id
       where pr.status = 'approved'
         and (exists (select 1 from public.priest_confessors c where c.priest_id = pr.id and c.person_id = p.id)
              or exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id))
    ), '[]'::jsonb),
    'appointments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', a.id, 'priest_id', a.priest_id, 'priest_name', pp.name, 'priest_title', pr.title,
               'requested_on', a.requested_on, 'requested_time', a.requested_time, 'note', a.note,
               'status', a.status, 'on', coalesce(a.scheduled_on, a.requested_on), 'time', coalesce(a.scheduled_time, a.requested_time),
               'decision_note', a.decision_note, 'decided_at', a.decided_at, 'created_at', a.created_at)
             order by coalesce(a.scheduled_on, a.requested_on) desc, a.created_at desc)
        from public.confession_appointments a
        join public.priests pr on pr.id = a.priest_id
        join public.persons pp on pp.id = pr.person_id
       where a.person_id = p.id
    ), '[]'::jsonb),
    'server_today', public.cairo_today_date()
  );
end $$;
grant execute on function public.child_portal_confession(text) to anon, authenticated;

create or replace function public.child_request_confession(p_token text, p_priest uuid, p_on date, p_time time default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons; pr public.priests; a public.confession_appointments;
begin
  p := public.child_portal_person(p_token);
  select * into pr from public.priests where id = p_priest and status = 'approved';
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if not (exists (select 1 from public.priest_confessors c where c.priest_id = pr.id and c.person_id = p.id)
          or exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id)) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_on is null or p_on < public.cairo_today_date() then raise exception 'past_date' using errcode = '22023'; end if;
  if exists (select 1 from public.confession_appointments x where x.person_id = p.id and x.priest_id = pr.id and x.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;
  insert into public.confession_appointments (priest_id, person_id, requested_by, requested_on, requested_time, note, status)
  values (pr.id, p.id, 'child', p_on, p_time, nullif(trim(coalesce(p_note, '')), ''), 'pending') returning * into a;
  return jsonb_build_object('id', a.id, 'status', a.status, 'on', a.requested_on, 'time', a.requested_time);
end $$;
grant execute on function public.child_request_confession(text, uuid, date, time, text) to anon, authenticated;

create or replace function public.child_cancel_confession_request(p_token text, p_appointment uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons;
begin
  p := public.child_portal_person(p_token);
  update public.confession_appointments set status = 'cancelled', decided_at = now()
   where id = p_appointment and person_id = p.id and status in ('pending', 'approved');
  if not found then raise exception 'not_pending' using errcode = 'P0001'; end if;
end $$;
grant execute on function public.child_cancel_confession_request(text, uuid) to anon, authenticated;



-- #####################################################################
-- ##  20260928120000_priest_areas_families_visits.sql
-- #####################################################################

-- =====================================================================
-- 20260928120000 — PRIEST PORTAL part 3: الافتقاد الأسري
--   المناطق → الشوارع → العمارات → العائلات → الأفراد  +  الزيارات
-- Requires 20260927120000 + 20260927130000 (priest portal) and
--          20260924120000 + 20260924130000 (family module).
-- =====================================================================
-- WHAT
--   * The FAMILY MODULE moves from the servants' app to the PRIEST PORTAL.
--     Servants keep READ access (list + the scanner family picker); the
--     priest creates / edits families and their members.
--   * A geographic hierarchy under the church:
--       areas (المناطق)        church_id · connected to ONE OR MORE priests
--                              (area_priests) · optional location
--       streets (الشوارع)      area_id · optional location
--       buildings (العمارات)   street_id · number · floors · optional location
--     A family is bound to church → area → street → building (+ floor /
--     apartment). Every level may carry a LOCATION (lat / lng · maps_url ·
--     note); the family's effective location = family → building → street
--     → area (first one set) — used for «الاتجاهات» (navigation).
--   * VISITS (family_visits): the priest RECORDS a visit he made (done +
--     visited_on), SCHEDULES one (approved + scheduled_on) or the FAMILY
--     REQUESTS one from the child portal (pending → the priest approves /
--     moves / rejects, then marks it done). «آخر زيارة» = max(visited_on).
--   * Child portal → عائلتي: my family, its members, the PRIESTS OF MY AREA
--     (call / WhatsApp), request a visit, my family's visits.
-- SECURITY — same model as the rest of the priest portal: SECURITY DEFINER
--   RPCs resolve the priest token (`priest_portal_self`) or the child token
--   (`child_portal_person`). No direct table access for anon.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. TABLES
-- ---------------------------------------------------------------------
create table if not exists public.areas (
  id             uuid primary key default gen_random_uuid(),
  church_id      uuid not null references public.churches(id) on delete cascade,
  name           text not null check (length(trim(name)) between 1 and 120),
  description    text,
  lat            double precision check (lat is null or lat between -90 and 90),
  lng            double precision check (lng is null or lng between -180 and 180),
  maps_url       text,
  location_note  text,
  created_by_priest uuid references public.priests(id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists idx_areas_church on public.areas(church_id);
comment on table public.areas is 'المناطق — تقسيم جغرافي داخل الكنيسة يخدمه كاهن أو أكثر (area_priests)';
alter table public.areas enable row level security;
revoke all on public.areas from anon, authenticated;

create table if not exists public.area_priests (
  area_id    uuid not null references public.areas(id) on delete cascade,
  priest_id  uuid not null references public.priests(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (area_id, priest_id)
);
create index if not exists idx_area_priests_priest on public.area_priests(priest_id);
comment on table public.area_priests is 'الكهنة المرتبطون بكل منطقة';
alter table public.area_priests enable row level security;
revoke all on public.area_priests from anon, authenticated;

create table if not exists public.streets (
  id             uuid primary key default gen_random_uuid(),
  area_id        uuid not null references public.areas(id) on delete cascade,
  name           text not null check (length(trim(name)) between 1 and 120),
  lat            double precision check (lat is null or lat between -90 and 90),
  lng            double precision check (lng is null or lng between -180 and 180),
  maps_url       text,
  location_note  text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists idx_streets_area on public.streets(area_id);
comment on table public.streets is 'الشوارع داخل المنطقة';
alter table public.streets enable row level security;
revoke all on public.streets from anon, authenticated;

create table if not exists public.buildings (
  id             uuid primary key default gen_random_uuid(),
  street_id      uuid not null references public.streets(id) on delete cascade,
  name           text not null check (length(trim(name)) between 1 and 120),
  number         text,
  floors_count   integer check (floors_count is null or floors_count between 0 and 200),
  lat            double precision check (lat is null or lat between -90 and 90),
  lng            double precision check (lng is null or lng between -180 and 180),
  maps_url       text,
  location_note  text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists idx_buildings_street on public.buildings(street_id);
comment on table public.buildings is 'العمارات داخل الشارع — العائلات تسكن فيها';
alter table public.buildings enable row level security;
revoke all on public.buildings from anon, authenticated;

-- families: church → area → street → building + floor / apartment + location
alter table public.families add column if not exists church_id     uuid references public.churches(id) on delete set null;
alter table public.families add column if not exists area_id       uuid references public.areas(id) on delete set null;
alter table public.families add column if not exists street_id     uuid references public.streets(id) on delete set null;
alter table public.families add column if not exists building_id   uuid references public.buildings(id) on delete set null;
alter table public.families add column if not exists floor         text;
alter table public.families add column if not exists apartment     text;
alter table public.families add column if not exists lat           double precision;
alter table public.families add column if not exists lng           double precision;
alter table public.families add column if not exists maps_url      text;
alter table public.families add column if not exists location_note text;
alter table public.families add column if not exists created_by_priest uuid references public.priests(id) on delete set null;
create index if not exists idx_families_church on public.families(church_id);
create index if not exists idx_families_area on public.families(area_id);
create index if not exists idx_families_street on public.families(street_id);
create index if not exists idx_families_building on public.families(building_id);

create table if not exists public.family_visits (
  id                   uuid primary key default gen_random_uuid(),
  family_id            uuid not null references public.families(id) on delete cascade,
  priest_id            uuid not null references public.priests(id) on delete cascade,
  requested_by         text not null default 'priest' check (requested_by in ('priest', 'family')),
  requested_by_person  uuid references public.persons(id) on delete set null,
  requested_on         date,
  requested_time       time,
  note                 text,
  status               text not null default 'approved' check (status in ('pending', 'approved', 'rejected', 'cancelled', 'done')),
  scheduled_on         date,
  scheduled_time       time,
  visited_on           date,
  decision_note        text,
  visit_note           text,
  decided_at           timestamptz,
  created_at           timestamptz not null default now()
);
create index if not exists idx_family_visits_family on public.family_visits(family_id, status, visited_on desc);
create index if not exists idx_family_visits_priest on public.family_visits(priest_id, status, scheduled_on);
comment on table public.family_visits is 'زيارات الكاهن للعائلات — مسجَّلة (done + visited_on) أو مرتَّبة (approved) أو مطلوبة من العائلة (pending)';
alter table public.family_visits enable row level security;
revoke all on public.family_visits from anon, authenticated;

-- updated_at
create or replace function public.geo_touch()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists trg_areas_touch on public.areas;
create trigger trg_areas_touch before update on public.areas for each row execute function public.geo_touch();
drop trigger if exists trg_streets_touch on public.streets;
create trigger trg_streets_touch before update on public.streets for each row execute function public.geo_touch();
drop trigger if exists trg_buildings_touch on public.buildings;
create trigger trg_buildings_touch before update on public.buildings for each row execute function public.geo_touch();

-- keep the family's place chain consistent: building → street → area → church
create or replace function public.families_fill_place()
returns trigger language plpgsql set search_path = public as $$
declare v_street uuid; v_area uuid; v_church uuid;
begin
  -- on UPDATE a parent that vanished (FK cascade in progress) simply drops out;
  -- on INSERT an unknown parent is an error
  if new.building_id is not null then
    select b.street_id into v_street from public.buildings b where b.id = new.building_id;
    if v_street is null then
      if tg_op = 'INSERT' then raise exception 'building_not_found' using errcode = 'P0002'; end if;
      new.building_id := null;
    else
      new.street_id := v_street;
    end if;
  end if;
  if new.street_id is not null then
    select s.area_id into v_area from public.streets s where s.id = new.street_id;
    if v_area is null then
      if tg_op = 'INSERT' then raise exception 'street_not_found' using errcode = 'P0002'; end if;
      new.street_id := null;
    else
      new.area_id := v_area;
    end if;
  end if;
  if new.area_id is not null then
    select a.church_id into v_church from public.areas a where a.id = new.area_id;
    if v_church is null then
      if tg_op = 'INSERT' then raise exception 'area_not_found' using errcode = 'P0002'; end if;
      new.area_id := null;
    else
      if new.church_id is not null and new.church_id <> v_church then raise exception 'area_church_mismatch' using errcode = '22023'; end if;
      new.church_id := v_church;
    end if;
  end if;
  if new.lat is not null and (new.lat < -90 or new.lat > 90) then raise exception 'invalid_location' using errcode = '22023'; end if;
  if new.lng is not null and (new.lng < -180 or new.lng > 180) then raise exception 'invalid_location' using errcode = '22023'; end if;
  return new;
end $$;
drop trigger if exists trg_families_fill_place on public.families;
create trigger trg_families_fill_place before insert or update on public.families
for each row execute function public.families_fill_place();

-- backfill: a legacy family whose members are all enrolled in ONE church → that church
update public.families f set church_id = x.church_id
  from (select m.family_id, min(e.church_id::text)::uuid as church_id
          from public.family_members m join public.enrollments e on e.person_id = m.person_id
         group by m.family_id having count(distinct e.church_id) = 1) x
 where f.id = x.family_id and f.church_id is null;

-- ---------------------------------------------------------------------
-- 2. AUDIT
-- ---------------------------------------------------------------------
create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules', 'report_templates', 'families', 'family_members',
    'access_events', 'access_rule_groups', 'access_rules', 'access_allowed', 'access_log',
    'priests', 'priest_requests', 'priest_confessors', 'confessions', 'confession_appointments', 'priest_contacts',
    'areas', 'area_priests', 'streets', 'buildings', 'family_visits'
  ]
$$;
do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('areas');
    perform public.activity_audit_attach('area_priests');
    perform public.activity_audit_attach('streets');
    perform public.activity_audit_attach('buildings');
    perform public.activity_audit_attach('family_visits');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 3. JSON BUILDERS
-- ---------------------------------------------------------------------
create or replace function public.geo_location_json(p_lat double precision, p_lng double precision, p_url text, p_note text, p_source text)
returns jsonb language sql immutable as $$
  select case when p_lat is null and nullif(trim(coalesce(p_url, '')), '') is null then null
         else jsonb_build_object('lat', p_lat, 'lng', p_lng, 'maps_url', nullif(trim(coalesce(p_url, '')), ''), 'note', p_note, 'source', p_source) end
$$;

-- the family's EFFECTIVE location: family → building → street → area
create or replace function public.family_location_json(f public.families)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(
    public.geo_location_json(f.lat, f.lng, f.maps_url, f.location_note, 'family'),
    (select public.geo_location_json(b.lat, b.lng, b.maps_url, b.location_note, 'building') from public.buildings b where b.id = f.building_id),
    (select public.geo_location_json(s.lat, s.lng, s.maps_url, s.location_note, 'street') from public.streets s where s.id = f.street_id),
    (select public.geo_location_json(a.lat, a.lng, a.maps_url, a.location_note, 'area') from public.areas a where a.id = f.area_id)
  )
$$;

create or replace function public.family_member_json(m public.family_members)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', m.id, 'family_id', m.family_id, 'person_id', m.person_id, 'relation', m.relation, 'created_at', m.created_at,
    'person', public.priest_person_json(p), 'places', public.priest_person_places(p.id))
    from public.persons p where p.id = m.person_id
$$;

create or replace function public.priest_short_json(pr public.priests)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', pr.id, 'name', p.name, 'title', pr.title, 'phone', p.phone, 'image_url', p.image_url,
                            'church_id', pr.church_id, 'status', pr.status)
    from public.persons p where p.id = pr.person_id
$$;

create or replace function public.family_visit_json(v public.family_visits)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', v.id, 'family_id', v.family_id, 'priest_id', v.priest_id,
    'priest', (select public.priest_short_json(pr) from public.priests pr where pr.id = v.priest_id),
    'requested_by', v.requested_by,
    'requested_by_person', (select jsonb_build_object('id', p.id, 'name', p.name) from public.persons p where p.id = v.requested_by_person),
    'requested_on', v.requested_on, 'requested_time', v.requested_time, 'note', v.note,
    'status', v.status, 'scheduled_on', v.scheduled_on, 'scheduled_time', v.scheduled_time, 'visited_on', v.visited_on,
    'on', coalesce(v.visited_on, v.scheduled_on, v.requested_on), 'time', coalesce(v.scheduled_time, v.requested_time),
    'decision_note', v.decision_note, 'visit_note', v.visit_note, 'decided_at', v.decided_at, 'created_at', v.created_at,
    'family', (select jsonb_build_object('id', f.id, 'code', f.code, 'name', f.name, 'phone', f.phone, 'address', f.address,
                        'area_id', f.area_id, 'street_id', f.street_id, 'building_id', f.building_id, 'floor', f.floor, 'apartment', f.apartment,
                        'area_name', (select a.name from public.areas a where a.id = f.area_id),
                        'street_name', (select s.name from public.streets s where s.id = f.street_id),
                        'building_name', (select concat_ws(' ', b.name, nullif(b.number, '')) from public.buildings b where b.id = f.building_id),
                        'location', public.family_location_json(f),
                        'members_count', (select count(*) from public.family_members m where m.family_id = f.id))
                 from public.families f where f.id = v.family_id)
  )
$$;

create or replace function public.priest_family_json(f public.families)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', f.id, 'code', f.code, 'name', f.name, 'phone', f.phone, 'address', f.address, 'notes', f.notes,
    'church_id', f.church_id, 'area_id', f.area_id, 'street_id', f.street_id, 'building_id', f.building_id,
    'floor', f.floor, 'apartment', f.apartment,
    'lat', f.lat, 'lng', f.lng, 'maps_url', f.maps_url, 'location_note', f.location_note,
    'created_at', f.created_at, 'edited_at', f.edited_at, 'created_by_priest', f.created_by_priest,
    'area_name', (select a.name from public.areas a where a.id = f.area_id),
    'street_name', (select s.name from public.streets s where s.id = f.street_id),
    'building_name', (select concat_ws(' ', b.name, nullif(b.number, '')) from public.buildings b where b.id = f.building_id),
    'location', public.family_location_json(f),
    'members', coalesce((select jsonb_agg(public.family_member_json(m) order by m.created_at) from public.family_members m where m.family_id = f.id), '[]'::jsonb),
    'members_count', (select count(*) from public.family_members m where m.family_id = f.id),
    'last_visit', (select max(v.visited_on) from public.family_visits v where v.family_id = f.id and v.status = 'done'),
    'visits_count', (select count(*) from public.family_visits v where v.family_id = f.id and v.status = 'done'),
    'days_since_visit', public.cairo_today_date() - (select max(v.visited_on) from public.family_visits v where v.family_id = f.id and v.status = 'done'),
    'next_visit', (select jsonb_build_object('id', v.id, 'status', v.status, 'on', coalesce(v.scheduled_on, v.requested_on),
                                             'time', coalesce(v.scheduled_time, v.requested_time), 'requested_by', v.requested_by, 'priest_id', v.priest_id)
                     from public.family_visits v
                    where v.family_id = f.id and v.status in ('pending', 'approved')
                      and coalesce(v.scheduled_on, v.requested_on) >= public.cairo_today_date()
                    order by coalesce(v.scheduled_on, v.requested_on), coalesce(v.scheduled_time, v.requested_time) nulls last limit 1),
    'pending_requests', (select count(*) from public.family_visits v where v.family_id = f.id and v.status = 'pending'),
    'area_priests', coalesce((select jsonb_agg(public.priest_short_json(pr) order by pr.created_at)
                                from public.area_priests ap join public.priests pr on pr.id = ap.priest_id
                               where ap.area_id = f.area_id and pr.status = 'approved'), '[]'::jsonb)
  )
$$;

-- ---------------------------------------------------------------------
-- 4. VISIBILITY HELPERS (priest side)
-- ---------------------------------------------------------------------
-- a family the priest may see / manage: bound to his church, or (legacy,
-- no church yet) with ≥ 1 member enrolled in his church, or created by him
create or replace function public.priest_family_visible(pr public.priests, f public.families)
returns boolean language sql stable security definer set search_path = public as $$
  select f.church_id = pr.church_id
      or f.created_by_priest = pr.id
      or (f.church_id is null and exists (
            select 1 from public.family_members m join public.enrollments e on e.person_id = m.person_id
             where m.family_id = f.id and e.church_id = pr.church_id))
$$;

create or replace function public.priest_family_get(pr public.priests, p_family uuid)
returns public.families language plpgsql stable security definer set search_path = public as $$
declare f public.families;
begin
  select * into f from public.families where id = p_family;
  if not found then raise exception 'family_not_found' using errcode = 'P0002'; end if;
  if not public.priest_family_visible(pr, f) then raise exception 'no_access' using errcode = '42501'; end if;
  return f;
end $$;

-- ---------------------------------------------------------------------
-- 5. PROFILE (counters extended)
-- ---------------------------------------------------------------------
create or replace function public.priest_portal_profile(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons; ch public.churches;
begin
  pr := public.priest_portal_self(p_token);
  select * into p from public.persons where id = pr.person_id;
  select * into ch from public.churches where id = pr.church_id;
  return jsonb_build_object(
    'priest', jsonb_build_object('id', pr.id, 'title', pr.title, 'status', pr.status, 'reminder_days', pr.reminder_days,
                                 'church_id', pr.church_id, 'created_at', pr.created_at),
    'person', public.priest_person_json(p),
    'church', jsonb_build_object('id', ch.id, 'name', ch.name, 'logo_url', ch.logo_url),
    'counts', jsonb_build_object(
      'confessors', (select count(*) from public.priest_confessors c where c.priest_id = pr.id),
      'overdue', (select count(*) from public.priest_confessors c where c.priest_id = pr.id
                    and coalesce((select max(x.confessed_on) from public.confessions x where x.priest_id = pr.id and x.person_id = c.person_id), c.created_at::date)
                        < public.cairo_today_date() - pr.reminder_days),
      'pending_appointments', (select count(*) from public.confession_appointments a where a.priest_id = pr.id and a.status = 'pending'),
      'today_appointments', (select count(*) from public.confession_appointments a where a.priest_id = pr.id and a.status = 'approved'
                               and coalesce(a.scheduled_on, a.requested_on) = public.cairo_today_date()),
      'areas', (select count(*) from public.areas a where a.church_id = pr.church_id),
      'my_areas', (select count(*) from public.area_priests ap where ap.priest_id = pr.id),
      'families', (select count(*) from public.families f where public.priest_family_visible(pr, f)),
      'never_visited', (select count(*) from public.families f where public.priest_family_visible(pr, f)
                          and not exists (select 1 from public.family_visits v where v.family_id = f.id and v.status = 'done')),
      'pending_visits', (select count(*) from public.family_visits v where v.priest_id = pr.id and v.status = 'pending'),
      'today_visits', (select count(*) from public.family_visits v where v.priest_id = pr.id and v.status = 'approved'
                         and coalesce(v.scheduled_on, v.requested_on) = public.cairo_today_date())
    ),
    'server_today', public.cairo_today_date()
  );
end $$;
grant execute on function public.priest_portal_profile(text) to anon, authenticated;


-- ---------------------------------------------------------------------
-- 6. AREAS · STREETS · BUILDINGS
-- ---------------------------------------------------------------------
-- the whole tree of his church: areas (with their priests, streets and
-- buildings, family counters) + the priests of the church (for the picker)
create or replace function public.priest_areas_tree(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return jsonb_build_object(
    'areas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'church_id', a.church_id, 'name', a.name, 'description', a.description,
        'lat', a.lat, 'lng', a.lng, 'maps_url', a.maps_url, 'location_note', a.location_note,
        'location', public.geo_location_json(a.lat, a.lng, a.maps_url, a.location_note, 'area'),
        'created_by_priest', a.created_by_priest, 'created_at', a.created_at,
        'is_mine', exists (select 1 from public.area_priests ap where ap.area_id = a.id and ap.priest_id = pr.id),
        'priest_ids', coalesce((select jsonb_agg(ap.priest_id) from public.area_priests ap where ap.area_id = a.id), '[]'::jsonb),
        'priests', coalesce((select jsonb_agg(public.priest_short_json(x) order by x.created_at)
                               from public.area_priests ap join public.priests x on x.id = ap.priest_id where ap.area_id = a.id), '[]'::jsonb),
        'families_count', (select count(*) from public.families f where f.area_id = a.id),
        'streets', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', s.id, 'area_id', s.area_id, 'name', s.name,
            'lat', s.lat, 'lng', s.lng, 'maps_url', s.maps_url, 'location_note', s.location_note,
            'location', public.geo_location_json(s.lat, s.lng, s.maps_url, s.location_note, 'street'),
            'created_at', s.created_at,
            'families_count', (select count(*) from public.families f where f.street_id = s.id),
            'buildings', coalesce((
              select jsonb_agg(jsonb_build_object(
                'id', b.id, 'street_id', b.street_id, 'name', b.name, 'number', b.number, 'floors_count', b.floors_count,
                'lat', b.lat, 'lng', b.lng, 'maps_url', b.maps_url, 'location_note', b.location_note,
                'location', public.geo_location_json(b.lat, b.lng, b.maps_url, b.location_note, 'building'),
                'created_at', b.created_at,
                'families_count', (select count(*) from public.families f where f.building_id = b.id)
              ) order by b.name collate "C", b.number collate "C")
                from public.buildings b where b.street_id = s.id), '[]'::jsonb)
          ) order by s.name collate "C") from public.streets s where s.area_id = a.id), '[]'::jsonb)
      ) order by a.name collate "C")
        from public.areas a where a.church_id = pr.church_id), '[]'::jsonb),
    'church_priests', coalesce((select jsonb_agg(public.priest_short_json(x) order by x.created_at)
                                  from public.priests x where x.church_id = pr.church_id and x.status = 'approved'), '[]'::jsonb),
    'server_today', public.cairo_today_date()
  );
end $$;
grant execute on function public.priest_areas_tree(text) to anon, authenticated;

-- connect the priests of the SAME church to the area (replaces the list)
create or replace function public.priest_area_set_priests(p_token text, p_area uuid, p_priest_ids uuid[])
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; a public.areas;
begin
  pr := public.priest_portal_self(p_token);
  select * into a from public.areas where id = p_area and church_id = pr.church_id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if exists (select 1 from unnest(coalesce(p_priest_ids, '{}'::uuid[])) u(id)
              where not exists (select 1 from public.priests x where x.id = u.id and x.church_id = pr.church_id)) then
    raise exception 'priest_other_church' using errcode = '22023';
  end if;
  delete from public.area_priests where area_id = a.id and not (priest_id = any (coalesce(p_priest_ids, '{}'::uuid[])));
  insert into public.area_priests (area_id, priest_id)
  select a.id, u.id from unnest(coalesce(p_priest_ids, '{}'::uuid[])) u(id) on conflict do nothing;
  return coalesce((select jsonb_agg(ap.priest_id) from public.area_priests ap where ap.area_id = a.id), '[]'::jsonb);
end $$;
grant execute on function public.priest_area_set_priests(text, uuid, uuid[]) to anon, authenticated;

create or replace function public.priest_area_save(
  p_token text, p_id uuid, p_name text, p_description text default null,
  p_lat double precision default null, p_lng double precision default null, p_maps_url text default null, p_location_note text default null,
  p_priest_ids uuid[] default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; a public.areas; v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  pr := public.priest_portal_self(p_token);
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'invalid_location' using errcode = '22023'; end if;
  if p_id is null then
    insert into public.areas (church_id, name, description, lat, lng, maps_url, location_note, created_by_priest)
    values (pr.church_id, v_name, nullif(trim(coalesce(p_description, '')), ''), p_lat, p_lng, nullif(trim(coalesce(p_maps_url, '')), ''),
            nullif(trim(coalesce(p_location_note, '')), ''), pr.id)
    returning * into a;
    -- the creator is connected to his area (unless an explicit list was sent)
    if p_priest_ids is null then
      insert into public.area_priests (area_id, priest_id) values (a.id, pr.id) on conflict do nothing;
    end if;
  else
    select * into a from public.areas where id = p_id and church_id = pr.church_id;
    if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
    update public.areas set name = v_name, description = nullif(trim(coalesce(p_description, '')), ''),
           lat = p_lat, lng = p_lng, maps_url = nullif(trim(coalesce(p_maps_url, '')), ''), location_note = nullif(trim(coalesce(p_location_note, '')), '')
     where id = a.id returning * into a;
  end if;
  if p_priest_ids is not null then perform public.priest_area_set_priests(p_token, a.id, p_priest_ids); end if;
  return jsonb_build_object('id', a.id, 'name', a.name);
end $$;
grant execute on function public.priest_area_save(text, uuid, text, text, double precision, double precision, text, text, uuid[]) to anon, authenticated;

create or replace function public.priest_area_delete(p_token text, p_id uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.areas where id = p_id and church_id = pr.church_id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_area_delete(text, uuid) to anon, authenticated;

create or replace function public.priest_street_save(
  p_token text, p_id uuid, p_area uuid, p_name text,
  p_lat double precision default null, p_lng double precision default null, p_maps_url text default null, p_location_note text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; s public.streets; v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  pr := public.priest_portal_self(p_token);
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'invalid_location' using errcode = '22023'; end if;
  if p_id is null then
    if not exists (select 1 from public.areas a where a.id = p_area and a.church_id = pr.church_id) then raise exception 'area_not_found' using errcode = 'P0002'; end if;
    insert into public.streets (area_id, name, lat, lng, maps_url, location_note)
    values (p_area, v_name, p_lat, p_lng, nullif(trim(coalesce(p_maps_url, '')), ''), nullif(trim(coalesce(p_location_note, '')), ''))
    returning * into s;
  else
    select s0.* into s from public.streets s0 join public.areas a on a.id = s0.area_id where s0.id = p_id and a.church_id = pr.church_id;
    if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
    if p_area is not null and p_area <> s.area_id then
      if not exists (select 1 from public.areas a where a.id = p_area and a.church_id = pr.church_id) then raise exception 'area_not_found' using errcode = 'P0002'; end if;
    end if;
    update public.streets set area_id = coalesce(p_area, area_id), name = v_name, lat = p_lat, lng = p_lng,
           maps_url = nullif(trim(coalesce(p_maps_url, '')), ''), location_note = nullif(trim(coalesce(p_location_note, '')), '')
     where id = s.id returning * into s;
    -- families follow the street when it moves to another area
    update public.families set area_id = s.area_id where street_id = s.id and area_id is distinct from s.area_id;
  end if;
  return jsonb_build_object('id', s.id, 'name', s.name, 'area_id', s.area_id);
end $$;
grant execute on function public.priest_street_save(text, uuid, uuid, text, double precision, double precision, text, text) to anon, authenticated;

create or replace function public.priest_street_delete(p_token text, p_id uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.streets s using public.areas a where a.id = s.area_id and s.id = p_id and a.church_id = pr.church_id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_street_delete(text, uuid) to anon, authenticated;

create or replace function public.priest_building_save(
  p_token text, p_id uuid, p_street uuid, p_name text, p_number text default null, p_floors integer default null,
  p_lat double precision default null, p_lng double precision default null, p_maps_url text default null, p_location_note text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; b public.buildings; v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  pr := public.priest_portal_self(p_token);
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'invalid_location' using errcode = '22023'; end if;
  if p_id is null then
    if not exists (select 1 from public.streets s join public.areas a on a.id = s.area_id where s.id = p_street and a.church_id = pr.church_id) then
      raise exception 'street_not_found' using errcode = 'P0002';
    end if;
    insert into public.buildings (street_id, name, number, floors_count, lat, lng, maps_url, location_note)
    values (p_street, v_name, nullif(trim(coalesce(p_number, '')), ''), p_floors, p_lat, p_lng,
            nullif(trim(coalesce(p_maps_url, '')), ''), nullif(trim(coalesce(p_location_note, '')), ''))
    returning * into b;
  else
    select b0.* into b from public.buildings b0 join public.streets s on s.id = b0.street_id join public.areas a on a.id = s.area_id
     where b0.id = p_id and a.church_id = pr.church_id;
    if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
    if p_street is not null and p_street <> b.street_id then
      if not exists (select 1 from public.streets s join public.areas a on a.id = s.area_id where s.id = p_street and a.church_id = pr.church_id) then
        raise exception 'street_not_found' using errcode = 'P0002';
      end if;
    end if;
    update public.buildings set street_id = coalesce(p_street, street_id), name = v_name, number = nullif(trim(coalesce(p_number, '')), ''),
           floors_count = p_floors, lat = p_lat, lng = p_lng,
           maps_url = nullif(trim(coalesce(p_maps_url, '')), ''), location_note = nullif(trim(coalesce(p_location_note, '')), '')
     where id = b.id returning * into b;
    -- families follow the building when it moves to another street (trigger fixes area / church)
    update public.families set street_id = b.street_id where building_id = b.id and street_id is distinct from b.street_id;
  end if;
  return jsonb_build_object('id', b.id, 'name', b.name, 'street_id', b.street_id);
end $$;
grant execute on function public.priest_building_save(text, uuid, uuid, text, text, integer, double precision, double precision, text, text) to anon, authenticated;

create or replace function public.priest_building_delete(p_token text, p_id uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.buildings b using public.streets s, public.areas a
   where s.id = b.street_id and a.id = s.area_id and b.id = p_id and a.church_id = pr.church_id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_building_delete(text, uuid) to anon, authenticated;


-- ---------------------------------------------------------------------
-- 7. FAMILIES — list · detail · save · delete · code lookup
-- ---------------------------------------------------------------------
create or replace function public.priest_families_list(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return coalesce((select jsonb_agg(public.priest_family_json(f) order by f.name collate "C")
                     from public.families f where public.priest_family_visible(pr, f)), '[]'::jsonb);
end $$;
grant execute on function public.priest_families_list(text) to anon, authenticated;

create or replace function public.priest_family_detail(p_token text, p_family uuid)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; f public.families;
begin
  pr := public.priest_portal_self(p_token);
  f := public.priest_family_get(pr, p_family);
  return public.priest_family_json(f) || jsonb_build_object(
    'visits', coalesce((select jsonb_agg(public.family_visit_json(v) order by coalesce(v.visited_on, v.scheduled_on, v.requested_on) desc, v.created_at desc)
                          from public.family_visits v where v.family_id = f.id), '[]'::jsonb));
end $$;
grant execute on function public.priest_family_detail(text, uuid) to anon, authenticated;

-- live check for the family code (typed / scanned / generated)
create or replace function public.priest_family_code_lookup(p_token text, p_code text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v_code text := trim(coalesce(p_code, '')); v_fam record; v_per record;
begin
  perform public.priest_portal_self(p_token);
  if v_code = '' then return jsonb_build_object('code', '', 'free', false, 'family', null, 'person', null); end if;
  select id, name into v_fam from public.families where code = v_code;
  select id, name into v_per from public.persons where national_id = v_code;
  return jsonb_build_object('code', v_code, 'free', (v_fam.id is null and v_per.id is null),
    'family', case when v_fam.id is null then null else jsonb_build_object('id', v_fam.id, 'name', v_fam.name) end,
    'person', case when v_per.id is null then null else jsonb_build_object('id', v_per.id, 'name', v_per.name) end);
end $$;
grant execute on function public.priest_family_code_lookup(text, text) to anon, authenticated;

create or replace function public.priest_family_save(
  p_token text, p_id uuid, p_name text, p_code text default null, p_phone text default null, p_address text default null, p_notes text default null,
  p_area uuid default null, p_street uuid default null, p_building uuid default null, p_floor text default null, p_apartment text default null,
  p_lat double precision default null, p_lng double precision default null, p_maps_url text default null, p_location_note text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  pr public.priests; f public.families;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_code text := nullif(trim(coalesce(p_code, '')), '');
begin
  pr := public.priest_portal_self(p_token);
  if v_name is null then raise exception 'name_required' using errcode = '22023'; end if;
  if (p_lat is null) <> (p_lng is null) then raise exception 'invalid_location' using errcode = '22023'; end if;
  if p_area is not null and not exists (select 1 from public.areas a where a.id = p_area and a.church_id = pr.church_id) then
    raise exception 'area_not_found' using errcode = 'P0002';
  end if;
  if v_code is not null and exists (select 1 from public.persons p where p.national_id = v_code) then
    raise exception 'code_is_person' using errcode = '23505';
  end if;
  if p_id is null then
    if v_code is not null and exists (select 1 from public.families x where x.code = v_code) then raise exception 'code_taken' using errcode = '23505'; end if;
    insert into public.families (code, name, phone, address, notes, church_id, area_id, street_id, building_id, floor, apartment,
                                 lat, lng, maps_url, location_note, created_by_priest)
    values (v_code, v_name, nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            pr.church_id, p_area, p_street, p_building, nullif(trim(coalesce(p_floor, '')), ''), nullif(trim(coalesce(p_apartment, '')), ''),
            p_lat, p_lng, nullif(trim(coalesce(p_maps_url, '')), ''), nullif(trim(coalesce(p_location_note, '')), ''), pr.id)
    returning * into f;
  else
    f := public.priest_family_get(pr, p_id);
    if v_code is not null and v_code <> f.code and exists (select 1 from public.families x where x.code = v_code) then
      raise exception 'code_taken' using errcode = '23505';
    end if;
    update public.families set
      code = coalesce(v_code, code), name = v_name,
      phone = nullif(trim(coalesce(p_phone, '')), ''), address = nullif(trim(coalesce(p_address, '')), ''), notes = nullif(trim(coalesce(p_notes, '')), ''),
      church_id = coalesce(church_id, pr.church_id),
      area_id = p_area, street_id = p_street, building_id = p_building,
      floor = nullif(trim(coalesce(p_floor, '')), ''), apartment = nullif(trim(coalesce(p_apartment, '')), ''),
      lat = p_lat, lng = p_lng, maps_url = nullif(trim(coalesce(p_maps_url, '')), ''), location_note = nullif(trim(coalesce(p_location_note, '')), ''),
      edited_at = now()
    where id = f.id returning * into f;
  end if;
  return public.priest_family_json(f);
end $$;
grant execute on function public.priest_family_save(text, uuid, text, text, text, text, text, uuid, uuid, uuid, text, text, double precision, double precision, text, text) to anon, authenticated;

create or replace function public.priest_family_delete(p_token text, p_family uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; f public.families;
begin
  pr := public.priest_portal_self(p_token);
  f := public.priest_family_get(pr, p_family);
  delete from public.families where id = f.id;
end $$;
grant execute on function public.priest_family_delete(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. FAMILY MEMBERS — search · add (id / code / new person) · relation · remove
-- ---------------------------------------------------------------------
create or replace function public.priest_family_add_member(p_token text, p_family uuid, p_person uuid, p_relation text default null, p_move boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; f public.families; v_person public.persons; v_member public.family_members; v_other public.families; v_moved jsonb;
begin
  pr := public.priest_portal_self(p_token);
  f := public.priest_family_get(pr, p_family);
  if p_relation is not null and p_relation not in ('father', 'mother', 'son', 'daughter', 'brother', 'sister', 'grandfather', 'grandmother', 'husband', 'wife', 'other') then
    raise exception 'invalid_relation' using errcode = '22023';
  end if;
  select * into v_person from public.persons where id = p_person;
  if not found then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  select * into v_member from public.family_members where person_id = v_person.id;
  if found then
    if v_member.family_id = f.id then raise exception 'already_member' using errcode = 'P0001'; end if;
    select * into v_other from public.families where id = v_member.family_id;
    if not p_move then
      raise exception 'in_other_family' using errcode = 'P0001', detail = coalesce(v_other.name, ''), hint = v_member.family_id::text;
    end if;
    delete from public.family_members where id = v_member.id;
    v_moved := jsonb_build_object('id', v_other.id, 'name', v_other.name);
  end if;
  insert into public.family_members (family_id, person_id, relation) values (f.id, v_person.id, p_relation) returning * into v_member;
  update public.families set edited_at = now() where id = f.id;
  return public.family_member_json(v_member) || jsonb_build_object('moved_from', v_moved);
end $$;
grant execute on function public.priest_family_add_member(text, uuid, uuid, text, boolean) to anon, authenticated;

create or replace function public.priest_family_add_member_by_code(p_token text, p_family uuid, p_code text, p_relation text default null, p_move boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid;
begin
  perform public.priest_portal_self(p_token);
  select id into v_person from public.persons where national_id = trim(coalesce(p_code, ''));
  if v_person is null then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  return public.priest_family_add_member(p_token, p_family, v_person, p_relation, p_move);
end $$;
grant execute on function public.priest_family_add_member_by_code(text, uuid, text, text, boolean) to anon, authenticated;

-- create the person here (code optional → auto) and add him to the family
create or replace function public.priest_family_add_new_member(
  p_token text, p_family uuid, p_name text, p_code text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null,
  p_relation text default null, p_move boolean default false
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; v_code text := nullif(trim(coalesce(p_code, '')), ''); v_person public.persons; v_created boolean := false;
begin
  pr := public.priest_portal_self(p_token);
  perform public.priest_family_get(pr, p_family);
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_code is not null then
    if exists (select 1 from public.families x where x.code = v_code) then raise exception 'code_taken' using errcode = '23505'; end if;
    select * into v_person from public.persons where national_id = v_code;
    if found then
      update public.persons set
        gender = coalesce(gender, p_gender), birthdate = coalesce(birthdate, p_birthdate),
        phone = coalesce(phone, nullif(trim(coalesce(p_phone, '')), '')), address = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
        notes = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')), image_url = coalesce(image_url, p_image_url), edited_at = now()
      where id = v_person.id returning * into v_person;
    end if;
  end if;
  if v_person.id is null then
    if v_code is null then
      insert into public.persons (name, gender, birthdate, phone, address, notes, image_url)
      values (trim(p_name), p_gender, p_birthdate, nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
              nullif(trim(coalesce(p_notes, '')), ''), p_image_url) returning * into v_person;
    else
      insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url)
      values (v_code, trim(p_name), p_gender, p_birthdate, nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
              nullif(trim(coalesce(p_notes, '')), ''), p_image_url) returning * into v_person;
    end if;
    v_created := true;
  end if;
  return public.priest_family_add_member(p_token, p_family, v_person.id, p_relation, p_move) || jsonb_build_object('person_created', v_created);
end $$;
grant execute on function public.priest_family_add_new_member(text, uuid, text, text, text, date, text, text, text, text, text, boolean) to anon, authenticated;

create or replace function public.priest_family_set_relation(p_token text, p_member uuid, p_relation text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; m public.family_members;
begin
  pr := public.priest_portal_self(p_token);
  select * into m from public.family_members where id = p_member;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  perform public.priest_family_get(pr, m.family_id);
  if p_relation is not null and p_relation not in ('father', 'mother', 'son', 'daughter', 'brother', 'sister', 'grandfather', 'grandmother', 'husband', 'wife', 'other') then
    raise exception 'invalid_relation' using errcode = '22023';
  end if;
  update public.family_members set relation = nullif(trim(coalesce(p_relation, '')), '') where id = m.id;
end $$;
grant execute on function public.priest_family_set_relation(text, uuid, text) to anon, authenticated;

create or replace function public.priest_family_remove_member(p_token text, p_member uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; m public.family_members;
begin
  pr := public.priest_portal_self(p_token);
  select * into m from public.family_members where id = p_member;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  perform public.priest_family_get(pr, m.family_id);
  delete from public.family_members where id = m.id;
  update public.families set edited_at = now() where id = m.family_id;
end $$;
grant execute on function public.priest_family_remove_member(text, uuid) to anon, authenticated;

-- person search for the family (his church · his confessors · members of his
-- families · persons with no enrollment) — each hit carries the CURRENT family
create or replace function public.priest_family_search_persons(p_token text, p_query text, p_limit integer default 30)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; v_q text := nullif(trim(coalesce(p_query, '')), ''); v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
begin
  pr := public.priest_portal_self(p_token);
  if v_q is null or length(v_q) < 2 then return '[]'::jsonb; end if;
  return coalesce((
    with hits as (
      select p.* from public.persons p
       where (p.name ilike '%' || v_q || '%' or p.phone ilike '%' || v_q || '%' or p.national_id ilike '%' || v_q || '%')
         and (exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id)
              or exists (select 1 from public.priest_confessors c where c.person_id = p.id and c.priest_id = pr.id)
              or exists (select 1 from public.family_members m join public.families f on f.id = m.family_id where m.person_id = p.id and public.priest_family_visible(pr, f))
              or not exists (select 1 from public.enrollments e where e.person_id = p.id))
       order by (p.national_id = v_q) desc, p.name collate "C" limit v_limit)
    select jsonb_agg(jsonb_build_object(
             'person', public.priest_person_json(h), 'places', public.priest_person_places(h.id),
             'family', (select jsonb_build_object('id', f.id, 'name', f.name) from public.family_members m join public.families f on f.id = m.family_id where m.person_id = h.id)
           ) order by (h.national_id = v_q) desc, h.name collate "C") from hits h), '[]'::jsonb);
end $$;
grant execute on function public.priest_family_search_persons(text, text, integer) to anon, authenticated;

-- a scanned / typed code → the person (+ his family) OR a family
create or replace function public.priest_family_lookup_code(p_token text, p_code text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons; f public.families;
begin
  pr := public.priest_portal_self(p_token);
  select * into p from public.persons where national_id = trim(coalesce(p_code, ''));
  if found then
    select x.* into f from public.family_members m join public.families x on x.id = m.family_id where m.person_id = p.id;
    return jsonb_build_object('found', 'person', 'person', public.priest_person_json(p), 'places', public.priest_person_places(p.id),
                              'family', case when f.id is null then null else jsonb_build_object('id', f.id, 'name', f.name, 'visible', public.priest_family_visible(pr, f)) end);
  end if;
  select * into f from public.families where code = trim(coalesce(p_code, ''));
  if found and public.priest_family_visible(pr, f) then
    return jsonb_build_object('found', 'family', 'family', public.priest_family_json(f));
  end if;
  return jsonb_build_object('found', null, 'code', trim(coalesce(p_code, '')));
end $$;
grant execute on function public.priest_family_lookup_code(text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 9. VISITS — priest side
-- ---------------------------------------------------------------------
create or replace function public.priest_visits_list(p_token text, p_from date default null, p_to date default null, p_include_past boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  return coalesce((
    select jsonb_agg(public.family_visit_json(v) order by coalesce(v.visited_on, v.scheduled_on, v.requested_on), coalesce(v.scheduled_time, v.requested_time) nulls last, v.created_at)
      from public.family_visits v
     where v.priest_id = pr.id
       and (p_from is null or coalesce(v.visited_on, v.scheduled_on, v.requested_on) >= p_from)
       and (p_to is null or coalesce(v.visited_on, v.scheduled_on, v.requested_on) <= p_to)
       and (p_include_past or v.status = 'pending' or (v.status = 'approved' and coalesce(v.scheduled_on, v.requested_on) >= public.cairo_today_date() - 1))
  ), '[]'::jsonb);
end $$;
grant execute on function public.priest_visits_list(text, date, date, boolean) to anon, authenticated;

-- record a visit that HAPPENED (p_done → status done, visited_on = p_on ≤ today)
-- or schedule one (approved, scheduled_on = p_on)
create or replace function public.priest_visit_create(p_token text, p_family uuid, p_on date, p_time time default null, p_note text default null, p_done boolean default false, p_visit_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; f public.families; v public.family_visits;
begin
  pr := public.priest_portal_self(p_token);
  f := public.priest_family_get(pr, p_family);
  if p_on is null then raise exception 'date_required' using errcode = '22023'; end if;
  if coalesce(p_done, false) then
    if p_on > public.cairo_today_date() then raise exception 'future_date' using errcode = '22023'; end if;
    insert into public.family_visits (family_id, priest_id, requested_by, requested_on, requested_time, note, status, scheduled_on, scheduled_time, visited_on, visit_note, decided_at)
    values (f.id, pr.id, 'priest', p_on, p_time, nullif(trim(coalesce(p_note, '')), ''), 'done', p_on, p_time, p_on, nullif(trim(coalesce(p_visit_note, '')), ''), now())
    returning * into v;
  else
    insert into public.family_visits (family_id, priest_id, requested_by, requested_on, requested_time, note, status, scheduled_on, scheduled_time, decided_at)
    values (f.id, pr.id, 'priest', p_on, p_time, nullif(trim(coalesce(p_note, '')), ''), 'approved', p_on, p_time, now())
    returning * into v;
  end if;
  return public.family_visit_json(v);
end $$;
grant execute on function public.priest_visit_create(text, uuid, date, time, text, boolean, text) to anon, authenticated;

-- approve (optionally moving) · reject · cancel · done (p_on = the day it happened)
create or replace function public.priest_visit_decide(p_token text, p_visit uuid, p_action text, p_on date default null, p_time time default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; v public.family_visits;
begin
  pr := public.priest_portal_self(p_token);
  select * into v from public.family_visits where id = p_visit and priest_id = pr.id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if p_action = 'approve' then
    if v.status not in ('pending', 'approved') then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.family_visits
       set status = 'approved', scheduled_on = coalesce(p_on, v.scheduled_on, v.requested_on),
           scheduled_time = case when p_on is not null or p_time is not null then p_time else coalesce(v.scheduled_time, v.requested_time) end,
           decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now()
     where id = v.id returning * into v;
  elsif p_action = 'reject' then
    if v.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.family_visits set status = 'rejected', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now() where id = v.id returning * into v;
  elsif p_action = 'cancel' then
    if v.status not in ('pending', 'approved') then raise exception 'not_pending' using errcode = 'P0001'; end if;
    update public.family_visits set status = 'cancelled', decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now() where id = v.id returning * into v;
  elsif p_action = 'done' then
    if v.status not in ('pending', 'approved') then raise exception 'not_pending' using errcode = 'P0001'; end if;
    if p_on is not null and p_on > public.cairo_today_date() then raise exception 'future_date' using errcode = '22023'; end if;
    update public.family_visits
       set status = 'done', visited_on = coalesce(p_on, least(coalesce(v.scheduled_on, v.requested_on), public.cairo_today_date())),
           visit_note = nullif(trim(coalesce(p_note, '')), ''), decided_at = now()
     where id = v.id returning * into v;
  else
    raise exception 'invalid_action' using errcode = '22023';
  end if;
  return public.family_visit_json(v);
end $$;
grant execute on function public.priest_visit_decide(text, uuid, text, date, time, text) to anon, authenticated;

create or replace function public.priest_visit_delete(p_token text, p_visit uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  delete from public.family_visits where id = p_visit and priest_id = pr.id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
end $$;
grant execute on function public.priest_visit_delete(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 10. CHILD PORTAL — عائلتي: my family · the priests of my area · visits
-- ---------------------------------------------------------------------
create or replace function public.child_portal_family(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare p public.persons; f public.families; v_area_priests jsonb; v_fallback boolean := false;
begin
  p := public.child_portal_person(p_token);
  select x.* into f from public.family_members m join public.families x on x.id = m.family_id where m.person_id = p.id;
  -- priests of the family's area; otherwise (no area / no priest there) the priests of the family's church / my churches
  v_area_priests := coalesce((select jsonb_agg(public.priest_short_json(pr) order by pr.created_at)
                                from public.area_priests ap join public.priests pr on pr.id = ap.priest_id
                               where f.id is not null and ap.area_id = f.area_id and pr.status = 'approved'), '[]'::jsonb);
  if jsonb_array_length(v_area_priests) = 0 then
    v_fallback := true;
    v_area_priests := coalesce((select jsonb_agg(public.priest_short_json(pr) order by pr.created_at)
                                  from public.priests pr
                                 where pr.status = 'approved'
                                   and (pr.church_id = f.church_id
                                        or exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id))), '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'family', case when f.id is null then null else public.priest_family_json(f) end,
    'me', jsonb_build_object('id', p.id, 'name', p.name),
    'priests', v_area_priests,
    'priests_fallback', v_fallback,
    'visits', coalesce((select jsonb_agg(public.family_visit_json(v) order by coalesce(v.visited_on, v.scheduled_on, v.requested_on) desc, v.created_at desc)
                          from public.family_visits v where f.id is not null and v.family_id = f.id), '[]'::jsonb),
    'server_today', public.cairo_today_date()
  );
end $$;
grant execute on function public.child_portal_family(text) to anon, authenticated;

create or replace function public.child_request_visit(p_token text, p_priest uuid, p_on date, p_time time default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons; f public.families; pr public.priests; v public.family_visits;
begin
  p := public.child_portal_person(p_token);
  select x.* into f from public.family_members m join public.families x on x.id = m.family_id where m.person_id = p.id;
  if not found then raise exception 'no_family' using errcode = 'P0002'; end if;
  select * into pr from public.priests where id = p_priest and status = 'approved';
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if not (exists (select 1 from public.area_priests ap where ap.area_id = f.area_id and ap.priest_id = pr.id)
          or pr.church_id = f.church_id
          or exists (select 1 from public.enrollments e where e.person_id = p.id and e.church_id = pr.church_id)) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_on is null or p_on < public.cairo_today_date() then raise exception 'past_date' using errcode = '22023'; end if;
  if exists (select 1 from public.family_visits x where x.family_id = f.id and x.priest_id = pr.id and x.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;
  insert into public.family_visits (family_id, priest_id, requested_by, requested_by_person, requested_on, requested_time, note, status)
  values (f.id, pr.id, 'family', p.id, p_on, p_time, nullif(trim(coalesce(p_note, '')), ''), 'pending') returning * into v;
  return public.family_visit_json(v);
end $$;
grant execute on function public.child_request_visit(text, uuid, date, time, text) to anon, authenticated;

create or replace function public.child_cancel_visit(p_token text, p_visit uuid)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons; f public.families;
begin
  p := public.child_portal_person(p_token);
  select x.* into f from public.family_members m join public.families x on x.id = m.family_id where m.person_id = p.id;
  if not found then raise exception 'no_family' using errcode = 'P0002'; end if;
  update public.family_visits set status = 'cancelled', decided_at = now()
   where id = p_visit and family_id = f.id and status in ('pending', 'approved');
  if not found then raise exception 'not_pending' using errcode = 'P0001'; end if;
end $$;
grant execute on function public.child_cancel_visit(text, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 11. SERVANTS keep READ access to the geo tables (reports / scanner).
--     The servant-side family RPCs remain for the owner; the servants' app
--     no longer exposes the manage UI (the priest does it).
-- ---------------------------------------------------------------------
-- any servant whose scope is inside the church may READ the geo tree
create or replace function public.geo_church_readable(p_church uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_owner() or exists (select 1 from public.my_scopes() s where s.church_id = p_church or s.role = 'owner')
$$;
grant execute on function public.geo_church_readable(uuid) to authenticated;

drop policy if exists areas_read on public.areas;
create policy areas_read on public.areas for select to authenticated using (public.geo_church_readable(church_id));
grant select on public.areas to authenticated;
drop policy if exists streets_read on public.streets;
create policy streets_read on public.streets for select to authenticated using (exists (select 1 from public.areas a where a.id = area_id and public.geo_church_readable(a.church_id)));
grant select on public.streets to authenticated;
drop policy if exists buildings_read on public.buildings;
create policy buildings_read on public.buildings for select to authenticated
  using (exists (select 1 from public.streets s join public.areas a on a.id = s.area_id where s.id = street_id and public.geo_church_readable(a.church_id)));
grant select on public.buildings to authenticated;
drop policy if exists area_priests_read on public.area_priests;
create policy area_priests_read on public.area_priests for select to authenticated using (exists (select 1 from public.areas a where a.id = area_id and public.geo_church_readable(a.church_id)));
grant select on public.area_priests to authenticated;



-- #####################################################################
-- ##  20260928130000_scope_sort_order_single_confession_father.sql
-- #####################################################################

-- =====================================================================
-- 20260928130000 — (A) ترتيب الكنائس / الخدمات / الفصول يدويًا
--                  (B) أب اعتراف واحد لكل شخص
-- =====================================================================
--
-- (A) MANUAL ORDER — churches · services · classes
--   * `sort_order integer` on the three structural tables. The manager
--     decides what comes first and what comes next; EVERY list / select /
--     tree in the app (settings pages, scope filters, scanner, children
--     page, statistics…) reads `order by sort_order, name` so the chosen
--     order is the one shown everywhere.
--   * Backfill: existing rows are numbered 1..n by name inside their parent
--     (churches globally · services per church · classes per service).
--   * BEFORE INSERT trigger: a new row without an explicit order goes to the
--     END of its siblings (max + 1) — never «jumps» in front of the others.
--   * RPC `reorder_scope_items(p_table, p_ids)` — the caller sends the ids
--     of the siblings in the wanted order and the rows are renumbered
--     1..n. SECURITY INVOKER → the normal RLS update policies decide who
--     may reorder what (owner everything · church manager his services and
--     classes · service manager his classes). A row the caller may not
--     update raises `forbidden`.
--   * `stats_attendance_by_class` follows the manual order too.
--
-- (B) ONE CONFESSION FATHER — priest_confessors
--   A person can NOT be the confessor of two priests at the same time.
--   * Existing duplicates are collapsed: the priest with the most recent
--     confession wins (then the most recently added row).
--   * `unique (person_id)` on priest_confessors.
--   * BEFORE INSERT trigger: adding the person to a priest DELETES his row
--     at any other priest first — «the new one replaces the old one». This
--     covers every path that binds a confessor: add by scan / search / new
--     person, تسجيل اعتراف, موعد created by the priest, approving a child's
--     appointment request.
--   * `priest_add_confessor` returns `moved_from` (the previous priest's
--     name) so the UI can say «تم نقله من أبونا فلان»;
--     `priest_lookup_code` returns `other_priest` like the search does.
--   The old priest keeps his confession history rows (`confessions`) — only
--     the binding moves.
--
-- Idempotent. Run after 20260928120000.
-- =====================================================================

-- ---------------------------------------------------------------------
-- A1. sort_order columns + backfill
-- ---------------------------------------------------------------------
alter table public.churches add column if not exists sort_order integer not null default 0;
alter table public.services add column if not exists sort_order integer not null default 0;
alter table public.classes  add column if not exists sort_order integer not null default 0;

comment on column public.churches.sort_order is 'الترتيب اليدوي — الأصغر يظهر أولاً في كل القوائم';
comment on column public.services.sort_order is 'الترتيب اليدوي داخل الكنيسة — الأصغر يظهر أولاً في كل القوائم';
comment on column public.classes.sort_order  is 'الترتيب اليدوي داخل الخدمة — الأصغر يظهر أولاً في كل القوائم';

-- number the rows that were never ordered (0) by name inside their parent,
-- AFTER the rows that already carry an order (re-running is harmless)
with r as (
  select id, row_number() over (order by (sort_order = 0), sort_order, name collate "C", created_at) as rn
    from public.churches)
update public.churches c set sort_order = r.rn from r where r.id = c.id and c.sort_order <> r.rn;

with r as (
  select id, row_number() over (partition by church_id order by (sort_order = 0), sort_order, name collate "C", created_at) as rn
    from public.services)
update public.services s set sort_order = r.rn from r where r.id = s.id and s.sort_order <> r.rn;

with r as (
  select id, row_number() over (partition by service_id order by (sort_order = 0), sort_order, name collate "C", created_at) as rn
    from public.classes)
update public.classes k set sort_order = r.rn from r where r.id = k.id and k.sort_order <> r.rn;

create index if not exists idx_churches_sort on public.churches(sort_order, name);
create index if not exists idx_services_sort on public.services(church_id, sort_order, name);
create index if not exists idx_classes_sort  on public.classes(service_id, sort_order, name);

-- ---------------------------------------------------------------------
-- A2. new rows go to the end of their siblings
-- ---------------------------------------------------------------------
create or replace function public.scope_item_default_order()
returns trigger language plpgsql as $$
begin
  if new.sort_order is null or new.sort_order <= 0 then
    if tg_table_name = 'churches' then
      select coalesce(max(sort_order), 0) + 1 into new.sort_order from public.churches;
    elsif tg_table_name = 'services' then
      select coalesce(max(sort_order), 0) + 1 into new.sort_order from public.services where church_id = new.church_id;
    else
      select coalesce(max(sort_order), 0) + 1 into new.sort_order from public.classes where service_id = new.service_id;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_churches_default_order on public.churches;
create trigger trg_churches_default_order before insert on public.churches
  for each row execute function public.scope_item_default_order();
drop trigger if exists trg_services_default_order on public.services;
create trigger trg_services_default_order before insert on public.services
  for each row execute function public.scope_item_default_order();
drop trigger if exists trg_classes_default_order on public.classes;
create trigger trg_classes_default_order before insert on public.classes
  for each row execute function public.scope_item_default_order();

-- ---------------------------------------------------------------------
-- A3. reorder RPC — siblings renumbered 1..n in the given order (RLS applies)
-- ---------------------------------------------------------------------
create or replace function public.reorder_scope_items(p_table text, p_ids uuid[])
returns void language plpgsql volatile security invoker set search_path = public as $$
declare i integer; n integer;
begin
  if p_table not in ('churches', 'services', 'classes') then
    raise exception 'invalid_table' using errcode = '22023';
  end if;
  if p_ids is null or array_length(p_ids, 1) is null then return; end if;
  for i in 1 .. array_length(p_ids, 1) loop
    execute format('update public.%I set sort_order = $1 where id = $2', p_table) using i, p_ids[i];
    get diagnostics n = row_count;
    if n = 0 then raise exception 'forbidden' using errcode = '42501'; end if;
  end loop;
end $$;
revoke all on function public.reorder_scope_items(text, uuid[]) from public, anon;
grant execute on function public.reorder_scope_items(text, uuid[]) to authenticated;
comment on function public.reorder_scope_items(text, uuid[]) is 'إعادة ترتيب الكنائس / الخدمات / الفصول — المعرّفات بالترتيب المطلوب؛ صلاحيات RLS تُطبَّق';

-- ---------------------------------------------------------------------
-- A4. statistics follow the manual order
-- ---------------------------------------------------------------------
create or replace function public.stats_attendance_by_class(
  p_day date,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  class_id     uuid,
  class_name   text,
  service_name text,
  church_name  text,
  enrolled     bigint,
  attendees    bigint,
  attendance   bigint,
  points       bigint
)
language sql stable security invoker set search_path = public as $$
  with sc as (
    select e.id, e.person_id, e.class_id
      from public.enrollments e
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
  ),
  att as (
    select sc.class_id, sc.person_id, a.points_delta
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on = p_day
  )
  select c.id, c.name, s.name, ch.name,
         (select count(*) from sc where sc.class_id = c.id)::bigint,
         (select count(distinct person_id) from att where att.class_id = c.id)::bigint,
         (select count(*) from att where att.class_id = c.id)::bigint,
         (select coalesce(sum(points_delta), 0) from att where att.class_id = c.id)::bigint
    from public.classes c
    join public.services s on s.id = c.service_id
    join public.churches ch on ch.id = c.church_id
   where c.id in (select distinct class_id from sc)
   order by ch.sort_order, ch.name, s.sort_order, s.name, c.sort_order, c.name
$$;

-- ---------------------------------------------------------------------
-- B1. one confession father per person — collapse duplicates
-- ---------------------------------------------------------------------
with ranked as (
  select c.id,
         row_number() over (
           partition by c.person_id
           order by (select max(x.confessed_on) from public.confessions x where x.priest_id = c.priest_id and x.person_id = c.person_id) desc nulls last,
                    c.created_at desc) as rn
    from public.priest_confessors c)
delete from public.priest_confessors where id in (select id from ranked where rn > 1);

create unique index if not exists uq_priest_confessors_person on public.priest_confessors(person_id);

-- B2. adding him to a priest removes him from any other priest
create or replace function public.priest_confessors_single_father()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  delete from public.priest_confessors where person_id = new.person_id and priest_id <> new.priest_id;
  return new;
end $$;
drop trigger if exists trg_priest_confessors_single_father on public.priest_confessors;
create trigger trg_priest_confessors_single_father before insert or update of person_id, priest_id on public.priest_confessors
  for each row execute function public.priest_confessors_single_father();

-- B3. RPCs — report the previous priest
create or replace function public.priest_add_confessor(p_token text, p_person uuid, p_notes text default null, p_last_confession date default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests; c public.priest_confessors; v_prev text;
begin
  pr := public.priest_portal_self(p_token);
  if not exists (select 1 from public.persons where id = p_person) then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.priest_confessors where priest_id = pr.id and person_id = p_person) then
    raise exception 'already_member' using errcode = 'P0001';
  end if;
  -- the priest he confesses at today (if any) — the insert below moves him here
  select pp.name into v_prev
    from public.priest_confessors x
    join public.priests px on px.id = x.priest_id
    join public.persons pp on pp.id = px.person_id
   where x.person_id = p_person and x.priest_id <> pr.id
   limit 1;
  insert into public.priest_confessors (priest_id, person_id, notes) values (pr.id, p_person, nullif(trim(coalesce(p_notes, '')), ''))
  returning * into c;
  if p_last_confession is not null then
    if p_last_confession > public.cairo_today_date() then raise exception 'future_date' using errcode = '22023'; end if;
    insert into public.confessions (priest_id, person_id, confessed_on, notes) values (pr.id, p_person, p_last_confession, 'آخر اعتراف عند الإضافة');
  end if;
  return public.priest_confessor_json(pr, c) || jsonb_build_object('moved_from', v_prev);
end $$;
grant execute on function public.priest_add_confessor(text, uuid, text, date) to anon, authenticated;

create or replace function public.priest_lookup_code(p_token text, p_code text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare pr public.priests; p public.persons; c public.priest_confessors; v_is boolean;
begin
  pr := public.priest_portal_self(p_token);
  select * into p from public.persons where national_id = trim(coalesce(p_code, ''));
  if not found then return jsonb_build_object('found', false, 'code', trim(coalesce(p_code, ''))); end if;
  select * into c from public.priest_confessors where priest_id = pr.id and person_id = p.id;
  v_is := found;
  return jsonb_build_object('found', true, 'person', public.priest_person_json(p), 'places', public.priest_person_places(p.id),
                            'is_confessor', v_is, 'confessor', case when v_is then public.priest_confessor_json(pr, c) else null end,
                            'other_priest', (select pp.name from public.priest_confessors x
                                               join public.priests px on px.id = x.priest_id
                                               join public.persons pp on pp.id = px.person_id
                                              where x.person_id = p.id and x.priest_id <> pr.id limit 1));
end $$;
grant execute on function public.priest_lookup_code(text, text) to anon, authenticated;

notify pgrst, 'reload schema';


-- #####################################################################
-- ##  20260928140000_finance.sql
-- #####################################################################

-- =====================================================================
-- FINANCE MODULE (الخزينة — الإيرادات والمصروفات)
--
-- The simplest possible money book for a church / service / class:
--   * an ENTRY (finance_entries) = kind (income | expense) + amount + a
--     CAUSE + optional note, on a day, inside a scope.
--   * a CAUSE (finance_causes) is either
--       - a STATIC cause created once for the scope (e.g. عشور · تبرعات ·
--         رحلة · مطبوعات), reused from a list, or
--       - a FREE-TEXT cause typed for one entry («أخرى» in the form →
--         `cause_text` on the entry, `cause_id` = null).
--     Causes are typed per kind (income / expense / both).
--   * summaries: the balance we have now (Σ income − Σ expense), and how
--     much came in / went out per day / month / year, per cause — served
--     by ONE RPC `finance_summary(scope, from, to, bucket)`.
--
-- Access (RLS + RPCs)
--   module_visible('finance') gates everything.
--   finance_can('finance.view')   — every servant of a granted scope sees
--                                   the entries / causes of scopes that
--                                   overlap his.
--   finance_can('finance.add')    — add entries (class servants need the key;
--                                   managers hold it)
--   finance_can('finance.manage') — edit / delete entries, manage causes
--   A row is visible by scope_overlaps(); written by can_access().
--
-- Idempotent. Seeds ONE global module grant (like `family` / `access`).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. Permission helpers
-- ---------------------------------------------------------------------
create or replace function public.finance_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('finance')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or p_key = 'finance.view'
       or public.has_permission(p_key)
     )
$$;
grant execute on function public.finance_can(text) to authenticated;

create or replace function public.finance_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',   public.finance_can('finance.view'),
    'add',    public.finance_can('finance.add'),
    'manage', public.finance_can('finance.manage')
  )
$$;
grant execute on function public.finance_permissions() to authenticated;

-- ---------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------
create table if not exists public.finance_causes (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,   -- null = whole church
  class_id    uuid references public.classes(id)  on delete cascade,   -- null = whole service
  name        text not null,
  kind        text not null default 'both' check (kind in ('income', 'expense', 'both')),
  color       text,
  is_active   boolean not null default true,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint finance_causes_name_chk check (length(trim(name)) between 1 and 80),
  constraint finance_causes_class_needs_service check (class_id is null or service_id is not null)
);
comment on table public.finance_causes is
  'أسباب الخزينة الثابتة — سبب إيراد أو مصروف (أو كليهما) يُنشأ مرة ويُختار من قائمة عند التسجيل';
create unique index if not exists uq_finance_causes_scope_name on public.finance_causes(
  church_id,
  coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(class_id,   '00000000-0000-0000-0000-000000000000'::uuid),
  lower(trim(name))
);

create table if not exists public.finance_entries (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id)  on delete cascade,
  kind        text not null check (kind in ('income', 'expense')),
  amount      numeric(14, 2) not null check (amount > 0),
  cause_id    uuid references public.finance_causes(id) on delete set null,
  cause_text  text,                                                    -- free-text cause («أخرى»)
  note        text,
  entry_date  date not null default ((now() at time zone 'Africa/Cairo')::date),
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint finance_entries_cause_chk check (cause_id is not null or length(trim(coalesce(cause_text, ''))) between 1 and 160),
  constraint finance_entries_class_needs_service check (class_id is null or service_id is not null)
);
comment on table public.finance_entries is
  'قيود الخزينة — إيراد أو مصروف بمبلغ وسبب (ثابت cause_id أو مكتوب cause_text) في يوم داخل نطاق';

create index if not exists idx_finance_causes_scope  on public.finance_causes(church_id, service_id, class_id, kind, sort_order);
create index if not exists idx_finance_entries_scope on public.finance_entries(church_id, service_id, class_id, entry_date desc);
create index if not exists idx_finance_entries_date  on public.finance_entries(entry_date desc, created_at desc);
create index if not exists idx_finance_entries_cause on public.finance_entries(cause_id) where cause_id is not null;

-- audit
create or replace function public.finance_fill_audit()
returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then new.created_by := auth.uid(); end if;
    if new.edited_by is null then new.edited_by := auth.uid(); end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_finance_causes_audit on public.finance_causes;
create trigger trg_finance_causes_audit before insert on public.finance_causes
for each row execute function public.finance_fill_audit();
drop trigger if exists trg_finance_causes_touch on public.finance_causes;
create trigger trg_finance_causes_touch before update on public.finance_causes
for each row execute function public.touch_edited();
drop trigger if exists trg_finance_entries_audit on public.finance_entries;
create trigger trg_finance_entries_audit before insert on public.finance_entries
for each row execute function public.finance_fill_audit();
drop trigger if exists trg_finance_entries_touch on public.finance_entries;
create trigger trg_finance_entries_touch before update on public.finance_entries
for each row execute function public.touch_edited();

-- an entry's static cause must be usable in the entry's scope and kind:
-- the cause is at the same level or a level ABOVE (church cause → every
-- service / class of the church), and its kind covers the entry's kind.
create or replace function public.finance_check_entry_cause()
returns trigger language plpgsql set search_path = public as $$
declare c public.finance_causes;
begin
  if new.cause_id is null then
    new.cause_text := nullif(trim(coalesce(new.cause_text, '')), '');
    return new;
  end if;
  select * into c from public.finance_causes where id = new.cause_id;
  if not found then raise exception 'cause_not_found' using errcode = '23503'; end if;
  if c.church_id <> new.church_id
     or (c.service_id is not null and c.service_id is distinct from new.service_id)
     or (c.class_id is not null and c.class_id is distinct from new.class_id) then
    raise exception 'cause_out_of_scope' using errcode = '23514';
  end if;
  if c.kind <> 'both' and c.kind <> new.kind then
    raise exception 'cause_kind_mismatch' using errcode = '23514';
  end if;
  -- keep the cause's name on the row so the history survives a rename / delete
  new.cause_text := c.name;
  return new;
end $$;
drop trigger if exists trg_finance_entries_cause on public.finance_entries;
create trigger trg_finance_entries_cause before insert or update on public.finance_entries
for each row execute function public.finance_check_entry_cause();

-- ---------------------------------------------------------------------
-- 2. RLS
-- ---------------------------------------------------------------------
alter table public.finance_causes  enable row level security;
alter table public.finance_entries enable row level security;

drop policy if exists finance_causes_select on public.finance_causes;
create policy finance_causes_select on public.finance_causes for select using (
  (select public.finance_can('finance.view')) and public.scope_overlaps(church_id, service_id, class_id)
);
drop policy if exists finance_causes_insert on public.finance_causes;
create policy finance_causes_insert on public.finance_causes for insert with check (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists finance_causes_update on public.finance_causes;
create policy finance_causes_update on public.finance_causes for update using (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
) with check (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists finance_causes_delete on public.finance_causes;
create policy finance_causes_delete on public.finance_causes for delete using (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
);

drop policy if exists finance_entries_select on public.finance_entries;
create policy finance_entries_select on public.finance_entries for select using (
  (select public.finance_can('finance.view')) and public.scope_overlaps(church_id, service_id, class_id)
);
drop policy if exists finance_entries_insert on public.finance_entries;
create policy finance_entries_insert on public.finance_entries for insert with check (
  (select public.finance_can('finance.add')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists finance_entries_update on public.finance_entries;
create policy finance_entries_update on public.finance_entries for update using (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
) with check (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
);
drop policy if exists finance_entries_delete on public.finance_entries;
create policy finance_entries_delete on public.finance_entries for delete using (
  (select public.finance_can('finance.manage')) and public.can_access(church_id, service_id, class_id)
);

-- ---------------------------------------------------------------------
-- 3. Summary RPC
--    finance_summary(church, service, class, from, to, bucket)
--    scope nulls = «الكل» at that level (church null = every church the
--    caller may see). Returns:
--    {
--      balance: { income, expense, net }                 -- ALL TIME, this scope
--      period:  { income, expense, net, count }          -- from..to
--      series:  [{ key: 'YYYY-MM-DD', income, expense }] -- per bucket (day|week|month|year)
--      by_cause:[{ kind, cause_id, cause, total, count }] -- from..to, sorted desc
--    }
-- ---------------------------------------------------------------------
create or replace function public.finance_summary(
  p_church  uuid default null,
  p_service uuid default null,
  p_class   uuid default null,
  p_from    date default null,
  p_to      date default null,
  p_bucket  text default 'month'
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_bucket text := case when p_bucket in ('day', 'week', 'month', 'year') then p_bucket else 'month' end;
  v_from   date := coalesce(p_from, (now() at time zone 'Africa/Cairo')::date - 29);
  v_to     date := coalesce(p_to,   (now() at time zone 'Africa/Cairo')::date);
  v_out    jsonb;
begin
  if not public.finance_can('finance.view') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  with scoped as (
    select e.*
      from public.finance_entries e
     where public.scope_overlaps(e.church_id, e.service_id, e.class_id)
       and (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
  ),
  in_period as (
    select * from scoped where entry_date between v_from and v_to
  ),
  balance as (
    select coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense
      from scoped
  ),
  period as (
    select coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense,
           count(*) as cnt
      from in_period
  ),
  series as (
    select date_trunc(v_bucket, entry_date)::date as k,
           coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense
      from in_period
     group by 1 order by 1
  ),
  by_cause as (
    select kind, cause_id, coalesce(cause_text, '—') as cause, sum(amount) as total, count(*) as cnt
      from in_period
     group by kind, cause_id, coalesce(cause_text, '—')
     order by sum(amount) desc
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'bucket', v_bucket,
    'balance', (select jsonb_build_object('income', income, 'expense', expense, 'net', income - expense) from balance),
    'period',  (select jsonb_build_object('income', income, 'expense', expense, 'net', income - expense, 'count', cnt) from period),
    'series',  coalesce((select jsonb_agg(jsonb_build_object('key', k, 'income', income, 'expense', expense) order by k) from series), '[]'::jsonb),
    'by_cause', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'cause_id', cause_id, 'cause', cause, 'total', total, 'count', cnt)) from by_cause), '[]'::jsonb)
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.finance_summary(uuid, uuid, uuid, date, date, text) from public, anon;
grant execute on function public.finance_summary(uuid, uuid, uuid, date, date, text) to authenticated;

-- ---------------------------------------------------------------------
-- 4. Module grant seed · realtime · activity log
-- ---------------------------------------------------------------------
insert into public.module_access (module_key, church_id, service_id, class_id)
select 'finance', null, null, null
where not exists (select 1 from public.module_access where module_key = 'finance');

do $$
declare t text;
begin
  foreach t in array array['finance_causes', 'finance_entries'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
exception when undefined_object then null;
end $$;

create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules', 'report_templates', 'families', 'family_members',
    'access_events', 'access_rule_groups', 'access_rules', 'access_allowed', 'access_log',
    'priests', 'priest_requests', 'priest_confessors', 'confessions', 'confession_appointments', 'priest_contacts',
    'areas', 'area_priests', 'streets', 'buildings', 'family_visits',
    'finance_causes', 'finance_entries'
  ]
$$;
do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('finance_causes');
    perform public.activity_audit_attach('finance_entries');
  end if;
end $$;



-- #####################################################################
-- ##  20260928150000_fix_families_code_trigger_on_update.sql
-- #####################################################################

-- =====================================================================
-- FIX: migration 20260928120000 fails on databases where an OLD family has
-- a code equal to a person's code.
--
--   ERROR: code_is_person (SQLSTATE 23505)
--   At statement: update public.families f set church_id = …   (backfill)
--
-- Why: `families_fill_code` (20260924130000) runs BEFORE INSERT OR UPDATE
-- and re-validates `new.code` on EVERY update — even when the code is not
-- being touched (the backfill only sets church_id). A legacy family whose
-- code collides with a person (created before the rule existed, or a
-- person who received that code later) therefore aborts the whole
-- migration, and every migration after it stays pending on that project.
--
-- Fix:
--   1. validate the code only when it is INSERTED or actually CHANGED
--      (new.code is distinct from old.code) — an unrelated update never
--      fails on a pre-existing collision. New / edited codes keep the rule.
--   2. re-run the backfill of 20260928120000 (it was never applied there).
--
-- Idempotent — safe on projects where 20260928120000 already succeeded
-- (the backfill then updates 0 rows).
-- =====================================================================


create or replace function public.families_fill_code()
returns trigger language plpgsql set search_path = public as $$
declare
  v_code_changed boolean := tg_op = 'INSERT' or new.code is distinct from old.code;
begin
  if new.code is null or length(trim(new.code)) = 0 then
    new.code := public.family_new_code();
  else
    new.code := trim(new.code);
    if v_code_changed then
      if length(new.code) > 60 then
        raise exception 'code_too_long' using errcode = '22023';
      end if;
      if exists (select 1 from public.persons p where p.national_id = new.code) then
        raise exception 'code_is_person' using errcode = '23505',
          detail = 'A family code cannot equal the code of a person';
      end if;
    end if;
  end if;
  new.name := trim(new.name);
  if tg_op = 'INSERT' and new.created_by is null then
    new.created_by := auth.uid();
  end if;
  if tg_op = 'INSERT' and new.edited_by is null then
    new.edited_by := auth.uid();
  end if;
  return new;
end $$;

-- the backfill of 20260928120000, repeated (no-op where it already ran)
do $$ begin
  if to_regclass('public.family_members') is not null
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'families' and column_name = 'church_id') then
    update public.families f set church_id = x.church_id
      from (select m.family_id, min(e.church_id::text)::uuid as church_id
              from public.family_members m join public.enrollments e on e.person_id = m.person_id
             group by m.family_id having count(distinct e.church_id) = 1) x
     where f.id = x.family_id and f.church_id is null;
  end if;
end $$;



-- #####################################################################
-- ##  20260929120000_finance_budgets.sql
-- #####################################################################

-- =====================================================================
-- FINANCE v2 — BUDGETS (الميزانيات)
--
-- The scenario:
--   1. Someone creates a BUDGET (ميزانية) — a name + a place: a church,
--      a service, a class — or «الكل» (no place at all).
--   2. ONLY THE PEOPLE ALLOWED see that budget: the creator (as manager)
--      and the servants he adds as members with a role
--        viewer  (يرى)   — sees the overview and the entries
--        editor  (يسجّل) — + records income / expense
--        manager (يدير)  — + edits / deletes entries, manages causes,
--                           members and the budget itself
--      The app owner sees every budget (manager everywhere).
--   3. Inside the budget everything stays as in v1: entries with a static
--      or typed cause, balance, per-period / per-cause summaries.
--
-- The place of a budget is INFORMATIONAL (where the money belongs, and it
-- is the only thing that decides WHO MAY CREATE it — can_access). It does
-- not grant visibility: a servant of that class does NOT see the budget
-- unless he is a member.
--
-- Migration of v1 data: every distinct (church, service, class) that has
-- entries / causes becomes one budget named after the place; the servants
-- who recorded there become members (creators → manager).
--
-- Access
--   module_visible('finance')             — the module must be granted
--   finance.create   (permission key)     — create a budget (managers by role,
--                                           class servants via a profile)
--   finance_budget_role(budget)           — the caller's role in a budget
--   RLS: read when member (or owner); write by role.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Budgets + members
-- ---------------------------------------------------------------------
create table if not exists public.finance_budgets (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  description text,
  church_id   uuid references public.churches(id) on delete cascade,   -- null = «الكل»
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id)  on delete cascade,
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint finance_budgets_name_chk check (length(trim(name)) between 1 and 120),
  constraint finance_budgets_service_needs_church check (service_id is null or church_id is not null),
  constraint finance_budgets_class_needs_service check (class_id is null or service_id is not null)
);
comment on table public.finance_budgets is
  'الميزانيات — ميزانية باسم ومكان (كنيسة ← خدمة ← فصل أو الكل)؛ لا يراها إلا أعضاؤها';

create table if not exists public.finance_budget_members (
  id          uuid primary key default gen_random_uuid(),
  budget_id   uuid not null references public.finance_budgets(id) on delete cascade,
  servant_id  uuid not null references public.servant_enrollments(id) on delete cascade,
  role        text not null default 'viewer' check (role in ('viewer', 'editor', 'manager')),
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  unique (budget_id, servant_id)
);
comment on table public.finance_budget_members is
  'أعضاء الميزانية — من يرى الميزانية ودوره فيها: viewer يرى · editor يسجّل · manager يدير';

create index if not exists idx_finance_budget_members_servant on public.finance_budget_members(servant_id, budget_id);
create index if not exists idx_finance_budgets_scope on public.finance_budgets(church_id, service_id, class_id);

-- audit
drop trigger if exists trg_finance_budgets_audit on public.finance_budgets;
create trigger trg_finance_budgets_audit before insert on public.finance_budgets
for each row execute function public.finance_fill_audit();
drop trigger if exists trg_finance_budgets_touch on public.finance_budgets;
create trigger trg_finance_budgets_touch before update on public.finance_budgets
for each row execute function public.touch_edited();

create or replace function public.finance_budget_members_fill()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.created_by is null then new.created_by := auth.uid(); end if;
  return new;
end $$;
drop trigger if exists trg_finance_budget_members_fill on public.finance_budget_members;
create trigger trg_finance_budget_members_fill before insert on public.finance_budget_members
for each row execute function public.finance_budget_members_fill();

-- the creator becomes a manager automatically
create or replace function public.finance_budget_add_creator()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.created_by is not null then
    insert into public.finance_budget_members (budget_id, servant_id, role, created_by)
    values (new.id, new.created_by, 'manager', new.created_by)
    on conflict (budget_id, servant_id) do update set role = 'manager';
  end if;
  return new;
end $$;
drop trigger if exists trg_finance_budget_add_creator on public.finance_budgets;
create trigger trg_finance_budget_add_creator after insert on public.finance_budgets
for each row execute function public.finance_budget_add_creator();

-- ---------------------------------------------------------------------
-- 2. budget_id on causes + entries
-- ---------------------------------------------------------------------
alter table public.finance_causes  add column if not exists budget_id uuid references public.finance_budgets(id) on delete cascade;
alter table public.finance_entries add column if not exists budget_id uuid references public.finance_budgets(id) on delete cascade;

-- ---- migrate v1 rows: one budget per distinct place ----
do $$
declare r record; v_id uuid; v_name text;
begin
  for r in (
    select church_id, service_id, class_id from public.finance_entries where budget_id is null
    union
    select church_id, service_id, class_id from public.finance_causes where budget_id is null
  ) loop
    select coalesce(
      (select k.name from public.classes k where k.id = r.class_id),
      (select s.name from public.services s where s.id = r.service_id),
      (select c.name from public.churches c where c.id = r.church_id),
      'الميزانية العامة') into v_name;
    insert into public.finance_budgets (name, church_id, service_id, class_id, created_by)
    values ('ميزانية ' || v_name, r.church_id, r.service_id, r.class_id,
            (select e.created_by from public.finance_entries e
              where e.church_id = r.church_id and e.service_id is not distinct from r.service_id and e.class_id is not distinct from r.class_id
                and e.created_by is not null order by e.created_at limit 1))
    returning id into v_id;
    update public.finance_entries set budget_id = v_id
     where budget_id is null and church_id = r.church_id and service_id is not distinct from r.service_id and class_id is not distinct from r.class_id;
    update public.finance_causes set budget_id = v_id
     where budget_id is null and church_id = r.church_id and service_id is not distinct from r.service_id and class_id is not distinct from r.class_id;
    -- everyone who recorded there keeps access as an editor
    insert into public.finance_budget_members (budget_id, servant_id, role)
    select distinct v_id, e.created_by, 'editor' from public.finance_entries e
     where e.budget_id = v_id and e.created_by is not null
    on conflict (budget_id, servant_id) do nothing;
  end loop;
end $$;

alter table public.finance_causes  alter column budget_id set not null;
alter table public.finance_entries alter column budget_id set not null;

-- the place is now carried by the budget; the row columns become optional
-- mirrors (kept for the reports / activity log) filled by trigger
alter table public.finance_causes  alter column church_id drop not null;
alter table public.finance_entries alter column church_id drop not null;

create or replace function public.finance_mirror_budget_scope()
returns trigger language plpgsql security definer set search_path = public as $$
declare b public.finance_budgets;
begin
  select * into b from public.finance_budgets where id = new.budget_id;
  if not found then raise exception 'budget_not_found' using errcode = '23503'; end if;
  new.church_id  := b.church_id;
  new.service_id := b.service_id;
  new.class_id   := b.class_id;
  return new;
end $$;
drop trigger if exists trg_finance_causes_scope on public.finance_causes;
create trigger trg_finance_causes_scope before insert or update of budget_id on public.finance_causes
for each row execute function public.finance_mirror_budget_scope();
drop trigger if exists trg_finance_entries_scope on public.finance_entries;
create trigger trg_finance_entries_scope before insert or update of budget_id on public.finance_entries
for each row execute function public.finance_mirror_budget_scope();

-- causes: unique per budget + name (replaces the per-scope index)
drop index if exists public.uq_finance_causes_scope_name;
create unique index if not exists uq_finance_causes_budget_name on public.finance_causes(budget_id, lower(trim(name)));
create index if not exists idx_finance_causes_budget  on public.finance_causes(budget_id, kind, sort_order);
create index if not exists idx_finance_entries_budget on public.finance_entries(budget_id, entry_date desc, created_at desc);

-- the entry's static cause must belong to the SAME budget + fit the kind
create or replace function public.finance_check_entry_cause()
returns trigger language plpgsql set search_path = public as $$
declare c public.finance_causes;
begin
  if new.cause_id is null then
    new.cause_text := nullif(trim(coalesce(new.cause_text, '')), '');
    return new;
  end if;
  select * into c from public.finance_causes where id = new.cause_id;
  if not found then raise exception 'cause_not_found' using errcode = '23503'; end if;
  if c.budget_id <> new.budget_id then
    raise exception 'cause_out_of_scope' using errcode = '23514';
  end if;
  if c.kind <> 'both' and c.kind <> new.kind then
    raise exception 'cause_kind_mismatch' using errcode = '23514';
  end if;
  new.cause_text := c.name;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 3. Permission helpers
-- ---------------------------------------------------------------------
-- may the caller CREATE budgets? owner / church manager / service manager
-- by role, class servants with the key
create or replace function public.finance_can_create()
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('finance')
     and (
       (select role from public.my_scope()) in ('owner', 'church_manager', 'service_manager')
       or public.has_permission('finance.create')
     )
$$;
grant execute on function public.finance_can_create() to authenticated;

-- the caller's role in a budget: 'manager' | 'editor' | 'viewer' | null
create or replace function public.finance_budget_role(p_budget uuid)
returns text language sql stable security definer set search_path = public as $$
  select case
    when not public.module_visible('finance') then null
    when (select public.is_owner()) then 'manager'
    else (select m.role from public.finance_budget_members m where m.budget_id = p_budget and m.servant_id = auth.uid())
  end
$$;
grant execute on function public.finance_budget_role(uuid) to authenticated;

create or replace function public.finance_budget_can(p_budget uuid, p_min text)
returns boolean language sql stable security definer set search_path = public as $$
  select case public.finance_budget_role(p_budget)
    when 'manager' then true
    when 'editor'  then p_min in ('editor', 'viewer')
    when 'viewer'  then p_min = 'viewer'
    else false
  end
$$;
grant execute on function public.finance_budget_can(uuid, text) to authenticated;

-- module-level answer for the UI
create or replace function public.finance_permissions()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'view',   public.module_visible('finance'),
    'create', public.finance_can_create(),
    -- kept for compatibility with v1 clients
    'add',    public.finance_can_create(),
    'manage', public.finance_can_create()
  )
$$;

-- ---------------------------------------------------------------------
-- 4. RLS
-- ---------------------------------------------------------------------
alter table public.finance_budgets        enable row level security;
alter table public.finance_budget_members enable row level security;

drop policy if exists finance_budgets_select on public.finance_budgets;
create policy finance_budgets_select on public.finance_budgets for select using (
  public.finance_budget_role(id) is not null
);
drop policy if exists finance_budgets_insert on public.finance_budgets;
create policy finance_budgets_insert on public.finance_budgets for insert with check (
  (select public.finance_can_create())
  and (church_id is null and (select public.is_owner())
       or church_id is not null and public.can_access(church_id, service_id, class_id))
);
drop policy if exists finance_budgets_update on public.finance_budgets;
create policy finance_budgets_update on public.finance_budgets for update using (
  public.finance_budget_can(id, 'manager')
) with check (
  public.finance_budget_can(id, 'manager')
);
drop policy if exists finance_budgets_delete on public.finance_budgets;
create policy finance_budgets_delete on public.finance_budgets for delete using (
  public.finance_budget_can(id, 'manager')
);

drop policy if exists finance_budget_members_select on public.finance_budget_members;
create policy finance_budget_members_select on public.finance_budget_members for select using (
  public.finance_budget_can(budget_id, 'viewer')
);
drop policy if exists finance_budget_members_insert on public.finance_budget_members;
create policy finance_budget_members_insert on public.finance_budget_members for insert with check (
  public.finance_budget_can(budget_id, 'manager')
);
drop policy if exists finance_budget_members_update on public.finance_budget_members;
create policy finance_budget_members_update on public.finance_budget_members for update using (
  public.finance_budget_can(budget_id, 'manager')
) with check (
  public.finance_budget_can(budget_id, 'manager')
);
drop policy if exists finance_budget_members_delete on public.finance_budget_members;
create policy finance_budget_members_delete on public.finance_budget_members for delete using (
  public.finance_budget_can(budget_id, 'manager')
);

-- causes: viewer reads · manager writes
drop policy if exists finance_causes_select on public.finance_causes;
create policy finance_causes_select on public.finance_causes for select using (public.finance_budget_can(budget_id, 'viewer'));
drop policy if exists finance_causes_insert on public.finance_causes;
create policy finance_causes_insert on public.finance_causes for insert with check (public.finance_budget_can(budget_id, 'manager'));
drop policy if exists finance_causes_update on public.finance_causes;
create policy finance_causes_update on public.finance_causes for update using (public.finance_budget_can(budget_id, 'manager')) with check (public.finance_budget_can(budget_id, 'manager'));
drop policy if exists finance_causes_delete on public.finance_causes;
create policy finance_causes_delete on public.finance_causes for delete using (public.finance_budget_can(budget_id, 'manager'));

-- entries: viewer reads · editor adds · manager edits / deletes
drop policy if exists finance_entries_select on public.finance_entries;
create policy finance_entries_select on public.finance_entries for select using (public.finance_budget_can(budget_id, 'viewer'));
drop policy if exists finance_entries_insert on public.finance_entries;
create policy finance_entries_insert on public.finance_entries for insert with check (public.finance_budget_can(budget_id, 'editor'));
drop policy if exists finance_entries_update on public.finance_entries;
create policy finance_entries_update on public.finance_entries for update using (public.finance_budget_can(budget_id, 'manager')) with check (public.finance_budget_can(budget_id, 'manager'));
drop policy if exists finance_entries_delete on public.finance_entries;
create policy finance_entries_delete on public.finance_entries for delete using (public.finance_budget_can(budget_id, 'manager'));

-- ---------------------------------------------------------------------
-- 5. RPCs
-- ---------------------------------------------------------------------
-- my budgets with role + balance (the list page)
create or replace function public.finance_my_budgets()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', b.id, 'name', b.name, 'description', b.description,
    'church_id', b.church_id, 'service_id', b.service_id, 'class_id', b.class_id,
    'is_active', b.is_active, 'created_at', b.created_at, 'created_by', b.created_by,
    'role', public.finance_budget_role(b.id),
    'members', (select count(*) from public.finance_budget_members m where m.budget_id = b.id),
    'income',  coalesce((select sum(e.amount) from public.finance_entries e where e.budget_id = b.id and e.kind = 'income'), 0),
    'expense', coalesce((select sum(e.amount) from public.finance_entries e where e.budget_id = b.id and e.kind = 'expense'), 0),
    'last_entry', (select max(e.entry_date) from public.finance_entries e where e.budget_id = b.id)
  ) order by b.is_active desc, b.created_at desc), '[]'::jsonb)
  from public.finance_budgets b
  where public.finance_budget_role(b.id) is not null
$$;
revoke all on function public.finance_my_budgets() from public, anon;
grant execute on function public.finance_my_budgets() to authenticated;

-- members with names (the members panel)
create or replace function public.finance_budget_members_list(p_budget uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.finance_budget_can(p_budget, 'viewer') then coalesce(jsonb_agg(jsonb_build_object(
    'id', m.id, 'budget_id', m.budget_id, 'servant_id', m.servant_id, 'role', m.role, 'created_at', m.created_at,
    'full_name', s.full_name, 'user_id', s.user_id, 'photo_url', s.photo_url, 'servant_role', s.role,
    'church_id', s.church_id, 'service_id', s.service_id, 'class_id', s.class_id
  ) order by case m.role when 'manager' then 0 when 'editor' then 1 else 2 end, s.full_name collate "C"), '[]'::jsonb) else '[]'::jsonb end
  from public.finance_budget_members m
  join public.servant_enrollments s on s.id = m.servant_id
  where m.budget_id = p_budget
$$;
revoke all on function public.finance_budget_members_list(uuid) from public, anon;
grant execute on function public.finance_budget_members_list(uuid) to authenticated;

-- servants a manager may add: every approved servant he can reach (or all, for the owner)
create or replace function public.finance_budget_candidates(p_budget uuid, p_q text default '')
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.finance_budget_can(p_budget, 'manager') then coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id, 'full_name', s.full_name, 'user_id', s.user_id, 'photo_url', s.photo_url, 'role', s.role,
      'church_id', s.church_id, 'service_id', s.service_id, 'class_id', s.class_id
    ) order by s.full_name collate "C")
    from (
      select s.* from public.servant_enrollments s
       where s.status = 'approved'
         and s.id <> auth.uid()
         and ((select public.is_owner()) or public.servant_in_my_scope(s.id))
         and not exists (select 1 from public.finance_budget_members m where m.budget_id = p_budget and m.servant_id = s.id)
         and (coalesce(trim(p_q), '') = '' or s.full_name ilike '%' || trim(p_q) || '%' or s.user_id ilike '%' || trim(p_q) || '%')
       limit 80
    ) s), '[]'::jsonb) else '[]'::jsonb end
$$;
revoke all on function public.finance_budget_candidates(uuid, text) from public, anon;
grant execute on function public.finance_budget_candidates(uuid, text) to authenticated;

-- summary — now per BUDGET (same payload as v1)
drop function if exists public.finance_summary(uuid, uuid, uuid, date, date, text);
create or replace function public.finance_summary(
  p_budget  uuid,
  p_from    date default null,
  p_to      date default null,
  p_bucket  text default 'month'
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_bucket text := case when p_bucket in ('day', 'week', 'month', 'year') then p_bucket else 'month' end;
  v_from   date := coalesce(p_from, (now() at time zone 'Africa/Cairo')::date - 29);
  v_to     date := coalesce(p_to,   (now() at time zone 'Africa/Cairo')::date);
  v_out    jsonb;
begin
  if not public.finance_budget_can(p_budget, 'viewer') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  with scoped as (
    select e.* from public.finance_entries e where e.budget_id = p_budget
  ),
  in_period as (select * from scoped where entry_date between v_from and v_to),
  balance as (
    select coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense
      from scoped
  ),
  period as (
    select coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense,
           count(*) as cnt
      from in_period
  ),
  series as (
    select date_trunc(v_bucket, entry_date)::date as k,
           coalesce(sum(amount) filter (where kind = 'income'),  0) as income,
           coalesce(sum(amount) filter (where kind = 'expense'), 0) as expense
      from in_period group by 1 order by 1
  ),
  by_cause as (
    select kind, cause_id, coalesce(cause_text, '—') as cause, sum(amount) as total, count(*) as cnt
      from in_period group by kind, cause_id, coalesce(cause_text, '—') order by sum(amount) desc
  )
  select jsonb_build_object(
    'from', v_from, 'to', v_to, 'bucket', v_bucket,
    'balance', (select jsonb_build_object('income', income, 'expense', expense, 'net', income - expense) from balance),
    'period',  (select jsonb_build_object('income', income, 'expense', expense, 'net', income - expense, 'count', cnt) from period),
    'series',  coalesce((select jsonb_agg(jsonb_build_object('key', k, 'income', income, 'expense', expense) order by k) from series), '[]'::jsonb),
    'by_cause', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'cause_id', cause_id, 'cause', cause, 'total', total, 'count', cnt)) from by_cause), '[]'::jsonb)
  ) into v_out;
  return v_out;
end $$;
revoke all on function public.finance_summary(uuid, date, date, text) from public, anon;
grant execute on function public.finance_summary(uuid, date, date, text) to authenticated;

-- ---------------------------------------------------------------------
-- 6. Realtime · activity log
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['finance_budgets', 'finance_budget_members'] loop
    if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
exception when undefined_object then null;
end $$;

create or replace function public.activity_audited_tables()
returns text[] language sql immutable as $$
  select array[
    'persons', 'enrollments', 'servant_enrollments', 'servant_scopes', 'permissions', 'permission_profiles',
    'module_access', 'churches', 'services', 'classes', 'events', 'causes', 'call_feedbacks',
    'attendance_log', 'points_log', 'contact_log', 'card_print_requests', 'card_templates', 'card_print_profiles',
    'data_change_requests', 'child_join_requests', 'person_credentials', 'shepherd_groups',
    'store_items', 'store_orders', 'exams', 'exam_questions', 'exam_attempts',
    'birthday_greetings', 'birthday_settings', 'birthday_card_templates', 'chat_messages',
    'online_classes', 'online_class_participants', 'online_class_checks', 'online_class_questions', 'online_class_answers',
    'achievements', 'user_achievements', 'occasions', 'occasion_registrations',
    'occasion_checklist_items', 'occasion_checklist_marks', 'occasion_notifications',
    'notifications', 'notification_automations', 'app_settings',
    'result_exams', 'result_subjects', 'exam_results', 'grading_systems', 'grading_grades',
    'library_subjects', 'library_books', 'library_lectures', 'library_favorites',
    'backup_runs', 'backup_schedules', 'report_templates', 'families', 'family_members',
    'access_events', 'access_rule_groups', 'access_rules', 'access_allowed', 'access_log',
    'priests', 'priest_requests', 'priest_confessors', 'confessions', 'confession_appointments', 'priest_contacts',
    'areas', 'area_priests', 'streets', 'buildings', 'family_visits',
    'finance_causes', 'finance_entries', 'finance_budgets', 'finance_budget_members'
  ]
$$;
do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('finance_budgets');
    perform public.activity_audit_attach('finance_budget_members');
  end if;
end $$;



-- #####################################################################
-- ##  20260930120000_person_code_not_family_code.sql
-- #####################################################################

-- =====================================================================
-- ONE CODE SPACE FOR PERSONS AND FAMILIES (كود واحد — شخص أو عائلة)
--
-- A code (QR) identifies EITHER a person (persons.national_id) OR a
-- family (families.code) — never both. The family side has been enforced
-- since 20260924130000 (`families_fill_code` refuses a person code); the
-- person side was only checked inside three RPCs (family_add_new_member ·
-- priest_family_new_member · priest_confessor_new). Every other path that
-- writes persons.national_id — add_person_and_enroll (إضافة مخدوم, bulk
-- import, extra classes), admin_add_servant, servant_signup, the
-- «تغيير الكود» modal (direct update), the servant-account API, the code
-- generator `new_person_code` — could still give a person a family code.
--
-- This migration closes the gap at the ONE place every path goes through:
--
--   1. trigger `persons_code_not_family` (BEFORE INSERT OR UPDATE OF
--      national_id) → `code_is_family` (SQLSTATE 23505) when the code
--      belongs to a family. Same shape as the family trigger: validated
--      only when the code is inserted or actually CHANGED, so an unrelated
--      update of a legacy person never fails on a pre-existing collision.
--   2. `new_person_code()` (generator fallback) skips codes used by a
--      family — same as `family_new_code()` already skips person codes.
--   3. `person_code_lookup(code)` → { code, free, person, family } — the
--      live check for the person-side forms (mirror of family_code_lookup).
--   4. `admin_servant_code_lookup` / `signup_lookup_code` /
--      `child_signup_lookup_code` gain a `family` key so the servant /
--      signup forms can warn before submitting.
--
-- Backup restore (`alter table … disable trigger user`) is unaffected: it
-- disables user triggers while loading, exactly like the family trigger.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. persons trigger — a person code can never equal a family code
-- ---------------------------------------------------------------------
create or replace function public.persons_code_not_family()
returns trigger language plpgsql set search_path = public as $$
declare
  v_code_changed boolean := tg_op = 'INSERT' or new.national_id is distinct from old.national_id;
begin
  if v_code_changed and new.national_id is not null
     and to_regclass('public.families') is not null
     and exists (select 1 from public.families f where f.code = new.national_id) then
    raise exception 'code_is_family' using errcode = '23505',
      detail = 'A person code cannot equal the code of a family',
      hint = new.national_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_persons_code_not_family on public.persons;
create trigger trg_persons_code_not_family
before insert or update of national_id on public.persons
for each row execute function public.persons_code_not_family();

-- ---------------------------------------------------------------------
-- 2. new_person_code — the generated fallback must also be free of families
--    (same body as 0040, one more `exists` in the exit condition)
-- ---------------------------------------------------------------------
create or replace function public.new_person_code(p_church uuid, p_service uuid, p_class uuid)
returns text language plpgsql volatile security definer set search_path = public as $$
declare v text; i int := 0; t jsonb; scopes jsonb;
begin
  t := public.code_template_for('person');
  select value -> 'scopes' into scopes from public.app_settings where key = 'codes';
  loop
    if t is not null then
      v := public.render_code(t, coalesce(scopes, '{}'::jsonb), p_church, p_service, p_class);
      if i > 0 then v := v || '-' || public.random_code_chars(2, 'alnum'); end if;
    end if;
    if v is null then v := 'P-' || public.random_code_chars(8, 'alnum'); end if;
    exit when not exists (select 1 from public.persons p where p.national_id = v)
          and not exists (select 1 from public.families f where f.code = v);
    i := i + 1;
    if i > 20 then raise exception 'person_code_collision'; end if;
    perform pg_sleep(0.001);
  end loop;
  return v;
end $$;
revoke all on function public.new_person_code(uuid, uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. person_code_lookup(code) — live check while typing / after a scan
--    { code, free, person: {id, name} | null, family: {id, name} | null }
--    Any approved servant may call it (same exposure as
--    find_person_by_national_id — the servant already holds the card).
-- ---------------------------------------------------------------------
create or replace function public.person_code_lookup(p_code text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_code text := trim(coalesce(p_code, ''));
  v_per  record;
  v_fam  record;
begin
  if public.my_role() is null then
    raise exception 'not_approved' using errcode = '42501';
  end if;
  if v_code = '' then
    return jsonb_build_object('code', '', 'free', false, 'person', null, 'family', null);
  end if;
  select id, name into v_per from public.persons  where national_id = v_code;
  select id, name into v_fam from public.families where code = v_code;
  return jsonb_build_object(
    'code', v_code,
    'free', (v_per.id is null and v_fam.id is null),
    'person', case when v_per.id is null then null else jsonb_build_object('id', v_per.id, 'name', v_per.name) end,
    'family', case when v_fam.id is null then null else jsonb_build_object('id', v_fam.id, 'name', v_fam.name) end
  );
end $$;
revoke all on function public.person_code_lookup(text) from public, anon;
grant execute on function public.person_code_lookup(text) to authenticated;

-- ---------------------------------------------------------------------
-- 4. existing lookups gain a `family` key (name of the family that owns
--    the code, or null) so the forms can refuse the code before submit
-- ---------------------------------------------------------------------
create or replace function public.admin_servant_code_lookup(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'user_id', public.code_to_user_id(trim(p_code)),
      'login_taken', exists (select 1 from public.servant_enrollments s
                              where s.user_id = public.code_to_user_id(trim(p_code))),
      'person', (
        select jsonb_build_object(
          'name', p.name, 'gender', p.gender, 'birthdate', p.birthdate,
          'phone', p.phone, 'address', p.address, 'notes', p.notes, 'image_url', p.image_url,
          'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
        from public.persons p where p.national_id = trim(p_code) limit 1),
      'family', (select f.name from public.families f where f.code = trim(p_code) limit 1)
    )
  end
$$;
revoke all on function public.admin_servant_code_lookup(text) from public, anon;
grant execute on function public.admin_servant_code_lookup(text) to authenticated;

-- servant self-signup («الكود» step): the person (if any) + is it a family code
create or replace function public.signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else coalesce(
      (select jsonb_build_object(
          'name', p.name, 'gender', p.gender, 'birthdate', p.birthdate,
          'phone', p.phone, 'address', p.address, 'image_url', p.image_url,
          'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
         from public.persons p where p.national_id = trim(p_code) limit 1),
      case when exists (select 1 from public.families f where f.code = trim(p_code))
           then jsonb_build_object('family', true) end)
  end
$$;
grant execute on function public.signup_lookup_code(text) to anon, authenticated;

-- child self-signup («الكود» step)
create or replace function public.child_signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'exists', exists (select 1 from public.persons p where p.national_id = trim(p_code)),
      'has_password', exists (select 1 from public.persons p join public.person_credentials c on c.person_id = p.id
                               where p.national_id = trim(p_code)),
      'pending', exists (select 1 from public.child_join_requests r where r.code = trim(p_code) and r.status = 'pending'),
      'name', (select p.name from public.persons p where p.national_id = trim(p_code) limit 1),
      'family', exists (select 1 from public.families f where f.code = trim(p_code))
    )
  end
$$;
grant execute on function public.child_signup_lookup_code(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. Report (NOTICE only) — legacy collisions that exist today. They are
--    NOT touched (which side should give up its code is a human decision);
--    the owner sees them in the migration log and fixes them from the app.
-- ---------------------------------------------------------------------
do $$
declare r record; n int := 0;
begin
  for r in select p.national_id as code, p.name as person, f.name as family
             from public.persons p join public.families f on f.code = p.national_id
  loop
    n := n + 1;
    raise notice 'code shared by person and family: % (person «%», family «%») — change one of them', r.code, r.person, r.family;
  end loop;
  if n > 0 then
    raise notice '% code(s) are used by both a person and a family — new / edited codes are refused from now on', n;
  end if;
end $$;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  20260930130000_families_managed_by_owner_and_church_manager.sql
-- #####################################################################

-- =====================================================================
-- FAMILIES — the OWNER and the CHURCH MANAGER manage them too
-- (العائلات — مالك التطبيق ومدير الكنيسة يضيفان العائلات بجانب الكاهن)
--
-- Since 20260928120000 the families were created and managed only by the
-- PRIEST (his portal). The servants' app kept a read-only list. Now, when
-- the owner has opened the family module (module_access 'family'):
--
--   * مالك التطبيق (owner)         → creates / edits / deletes ANY family,
--                                    chooses the church of a new family
--   * مدير الكنيسة (church manager) → creates / edits / deletes the families
--                                    OF HIS CHURCH (church_id is filled
--                                    automatically from his scope)
--   * everybody else in the servants' app → read only (as before)
--   * the priest portal → unchanged (token RPCs, its own visibility)
--
-- Changes
--   1. family_can('family.manage') = module visible AND (owner OR church
--      manager). The service manager and the 'family.manage' permission
--      key no longer grant management (the module moved to the priest /
--      the church level). 'family.view' is unchanged.
--   2. families_fill_church trigger — a family created from the servants'
--      app by a church manager gets his church; the owner must pick one
--      (church_required) unless the place chain already fixes it. A church
--      manager can't create a family in another church (church_forbidden).
--   3. family_visible(id) — a family OF the caller's church (church_id) is
--      visible to him (church manager / any servant of that church), in
--      addition to the older rules (owner · creator · member in scope).
--   4. RLS update / delete — a church manager may only touch families of
--      his church (or that he created).
--   5. family_manage_churches() → the churches the caller may create a
--      family in (owner: all · church manager: his) — for the form.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. permission
-- ---------------------------------------------------------------------
create or replace function public.family_can(p_key text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('family')
     and (
       p_key = 'family.view'
       or (p_key = 'family.manage'
           and exists (select 1 from public.my_scopes() s where s.role in ('owner', 'church_manager')))
       or (p_key not in ('family.view', 'family.manage') and public.has_permission(p_key))
     )
$$;
grant execute on function public.family_can(text) to authenticated;

-- ---------------------------------------------------------------------
-- 2. church of a family created from the servants' app
-- ---------------------------------------------------------------------
create or replace function public.family_manage_churches()
returns setof uuid language sql stable security definer set search_path = public as $$
  select c.id from public.churches c
   where public.module_visible('family')
     and (public.is_owner()
          or exists (select 1 from public.my_scopes() s where s.role = 'church_manager' and s.church_id = c.id))
   order by c.sort_order, c.name
$$;
grant execute on function public.family_manage_churches() to authenticated;

create or replace function public.families_fill_church()
returns trigger language plpgsql set search_path = public as $$
declare v_churches uuid[];
begin
  -- the priest portal (created_by_priest) and the backup restore are not concerned
  if auth.uid() is null or new.created_by_priest is not null then return new; end if;
  if tg_op = 'UPDATE' and new.church_id is not distinct from old.church_id then return new; end if;
  -- families_fill_place (earlier trigger, alphabetical order) may already have
  -- derived the church from area → street → building
  select array_agg(id) into v_churches from public.family_manage_churches();
  if new.church_id is null then
    if v_churches is null then return new; end if;              -- not a manager → RLS decides
    if cardinality(v_churches) = 1 then
      new.church_id := v_churches[1];                            -- church manager of ONE church: his church
    else
      -- the owner, or a manager of several churches, must choose
      raise exception 'church_required' using errcode = '22023',
        detail = 'Choose the church of the family';
    end if;
  elsif not public.is_owner() and not (new.church_id = any (coalesce(v_churches, '{}'::uuid[]))) then
    raise exception 'church_forbidden' using errcode = '42501',
      detail = 'A church manager can only create families in his own church';
  end if;
  return new;
end $$;

-- Postgres fires the BEFORE triggers of one event in NAME order; this one
-- must run AFTER trg_families_fill_place (which may derive the church from
-- the area) — hence the "zz" in its name.
drop trigger if exists trg_families_zz_fill_church on public.families;
create trigger trg_families_zz_fill_church before insert or update on public.families
for each row execute function public.families_fill_church();

-- ---------------------------------------------------------------------
-- 3. visibility — the CHURCH MANAGER sees every family of his church
--    (also an empty one the priest created); other servants keep the
--    older rule (creator · a member enrolled in their scope)
-- ---------------------------------------------------------------------
create or replace function public.family_visible(p_family uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_owner()
      or exists (select 1 from public.families f where f.id = p_family and f.created_by = auth.uid())
      or exists (select 1 from public.families f join public.my_scopes() s
                    on s.role = 'church_manager' and s.church_id = f.church_id
                  where f.id = p_family)
      or exists (
        select 1
          from public.family_members m
          join public.enrollments e on e.person_id = m.person_id
         where m.family_id = p_family
           and public.can_access(e.church_id, e.service_id, e.class_id)
      )
$$;
grant execute on function public.family_visible(uuid) to authenticated;

-- a manager may CHANGE a family only when it is his church's (or he created it)
create or replace function public.family_manageable(p_family uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.family_can('family.manage') and (
      public.is_owner()
      or exists (select 1 from public.families f where f.id = p_family and f.created_by = auth.uid())
      or exists (select 1 from public.families f join public.my_scopes() s
                    on s.role = 'church_manager' and s.church_id = f.church_id
                  where f.id = p_family)
  )
$$;
grant execute on function public.family_manageable(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 4. RLS
-- ---------------------------------------------------------------------
drop policy if exists families_update on public.families;
create policy families_update on public.families for update using (
  (select public.family_can('family.manage')) and (created_by = auth.uid() or public.family_manageable(id))
) with check (
  (select public.family_can('family.manage'))
);
drop policy if exists families_delete on public.families;
create policy families_delete on public.families for delete using (
  (select public.family_can('family.manage')) and (created_by = auth.uid() or public.family_manageable(id))
);

drop policy if exists family_members_insert on public.family_members;
create policy family_members_insert on public.family_members for insert with check (
  public.family_manageable(family_id)
);
drop policy if exists family_members_update on public.family_members;
create policy family_members_update on public.family_members for update using (
  public.family_manageable(family_id)
);
drop policy if exists family_members_delete on public.family_members;
create policy family_members_delete on public.family_members for delete using (
  public.family_manageable(family_id)
);

-- the member RPCs: manage right on THAT family (not only the module)
create or replace function public.family_add_member(
  p_family   uuid,
  p_person   uuid,
  p_relation text default null,
  p_move     boolean default false
) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_person  public.persons%rowtype;
  v_other   public.families%rowtype;
  v_member  public.family_members%rowtype;
  v_moved   jsonb := null;
begin
  if not public.family_can('family.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.families f where f.id = p_family) then
    raise exception 'family_not_found' using errcode = 'P0001';
  end if;
  if not public.family_manageable(p_family) then
    raise exception 'no_access' using errcode = '42501';
  end if;
  if p_relation is not null and p_relation not in (
    'father', 'mother', 'son', 'daughter', 'brother', 'sister',
    'grandfather', 'grandmother', 'husband', 'wife', 'other') then
    raise exception 'invalid_relation' using errcode = '22023';
  end if;

  select * into v_person from public.persons p where p.id = p_person;
  if not found then
    raise exception 'person_not_found' using errcode = 'P0002';
  end if;

  select * into v_member from public.family_members m where m.person_id = v_person.id;
  if found then
    if v_member.family_id = p_family then
      raise exception 'already_member' using errcode = 'P0001';
    end if;
    select * into v_other from public.families f where f.id = v_member.family_id;
    if not p_move then
      raise exception 'in_other_family' using errcode = 'P0001',
        detail = coalesce(v_other.name, ''), hint = v_member.family_id::text;
    end if;
    delete from public.family_members where id = v_member.id;
    v_moved := jsonb_build_object('id', v_other.id, 'name', v_other.name);
  end if;

  insert into public.family_members (family_id, person_id, relation, created_by)
  values (p_family, v_person.id, p_relation, auth.uid())
  returning * into v_member;

  update public.families set edited_at = now(), edited_by = auth.uid() where id = p_family;

  return jsonb_build_object(
    'member_id', v_member.id,
    'relation',  v_member.relation,
    'person',    to_jsonb(v_person),
    'moved_from', v_moved
  );
end $$;
revoke all on function public.family_add_member(uuid, uuid, text, boolean) from public, anon;
grant execute on function public.family_add_member(uuid, uuid, text, boolean) to authenticated;

-- family_add_new_member / family_add_member_by_code delegate to
-- family_add_member, so the manageable check above covers them too (the
-- whole call is one transaction — a refused add creates no person).

-- ---------------------------------------------------------------------
-- 5. back-fill — the church of a legacy family with a single church of members
--    (repeat of 20260928120000 / 150000 — no-op where already done)
-- ---------------------------------------------------------------------
update public.families f set church_id = x.church_id
  from (select m.family_id, min(e.church_id::text)::uuid as church_id
          from public.family_members m join public.enrollments e on e.person_id = m.person_id
         group by m.family_id having count(distinct e.church_id) = 1) x
 where f.id = x.family_id and f.church_id is null;

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  20261001120000_store_shops_and_child_requests.sql
-- #####################################################################

-- =====================================================================
-- STORE SHOPS + CHILD PURCHASE REQUESTS
-- (إستبدال النقاط — المتاجر وطلبات الشراء من بوابة المخدوم)
--
-- Until now the points store was ONE flat inventory sold at the servant's
-- POS. This migration adds the missing pieces the user asked for:
--
--   1. المتاجر (store_shops) — a shop / kiosk with a name, picture and an
--      ACTIVATION switch (is_active). A shop is connected to one or MANY
--      places through store_shop_targets: a church, a service, a class,
--      several of them, or «الكل» (a target row with church_id = null).
--      Items (store_items.shop_id) belong to a shop; the legacy items
--      without a shop keep working exactly as before at the POS.
--   2. بوابة المخدوم — an ACTIVE shop whose targets cover one of the
--      child's enrollments appears in his portal (child_portal_shops). He
--      browses its items (child_portal_shop_items), builds a cart and SENDS
--      IT to the servants (child_portal_store_request → store_requests +
--      store_request_items, status = pending). He may cancel while pending.
--   3. الطلبات — the servants of the child's scope see the request live
--      (RLS on store_requests). To approve, the servant SCANS THE CHILD'S
--      CARD as a confirmation (store_request_approve(p_request, p_card_code)
--      refuses when the code is not the child's) → the request becomes an
--      ORDER through the very same store_checkout logic (stock, balance,
--      points_log, receipt) → status approved + order_id. Or he rejects it
--      (store_request_reject) with an optional reason.
--   4. Receipts — store_orders.shop_id + request_id (+ source 'pos' |
--      'request'). The child sees every receipt with its lines in the portal
--      (child_portal_store_orders now carries shop_name / source) and the
--      servant sees it in the module archive as before.
--
-- Idempotent — safe to re-run. Depends on 0026 (store), 0027
-- (module_granted_for), 0042 (child_portal_person = session token), 0046
-- (broadcast bus), 0047 (activity log).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. TABLE: store_shops (المتاجر)
-- ---------------------------------------------------------------------
create table if not exists public.store_shops (
  id          uuid primary key default gen_random_uuid(),
  church_id   uuid not null references public.churches(id) on delete cascade,   -- owning church (RLS write)
  name        text not null,
  description text,
  image_url   text,
  is_active   boolean not null default false,          -- «تفعيل» → visible in the child portal
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  edited_at   timestamptz not null default now(),
  edited_by   uuid references public.servant_enrollments(id) on delete set null,
  constraint store_shops_name_not_blank check (length(trim(name)) > 0)
);
comment on table public.store_shops is
  'إستبدال النقاط — المتاجر: متجر له اسم وصورة وزر تفعيل، مرتبط بكنيسة / خدمة / فصل أو أكثر (store_shop_targets)';

create index if not exists idx_store_shops_church on public.store_shops(church_id);
create index if not exists idx_store_shops_active on public.store_shops(church_id, is_active);

drop trigger if exists trg_store_shops_touch on public.store_shops;
create trigger trg_store_shops_touch before update on public.store_shops
for each row execute function public.touch_edited();

create or replace function public.store_shops_fill()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.name := trim(new.name);
  if tg_op = 'INSERT' and new.created_by is null then new.created_by := auth.uid(); end if;
  if tg_op = 'UPDATE' then new.edited_by := coalesce(auth.uid(), new.edited_by); end if;
  return new;
end $$;
drop trigger if exists trg_store_shops_fill on public.store_shops;
create trigger trg_store_shops_fill before insert or update on public.store_shops
for each row execute function public.store_shops_fill();

-- ---------------------------------------------------------------------
-- 2. TABLE: store_shop_targets — where the shop is connected
--    church_id null           → «الكل» (every church)
--    church only              → the whole church
--    church + service         → the whole service
--    church + service + class → that class
--    Several rows = several places.
-- ---------------------------------------------------------------------
create table if not exists public.store_shop_targets (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null references public.store_shops(id) on delete cascade,
  church_id  uuid references public.churches(id) on delete cascade,
  service_id uuid references public.services(id) on delete cascade,
  class_id   uuid references public.classes(id)  on delete cascade,
  created_at timestamptz not null default now(),
  constraint store_shop_targets_chain check (
    not (service_id is not null and church_id is null)
    and not (class_id is not null and service_id is null))
);
comment on table public.store_shop_targets is
  'إستبدال النقاط — أماكن المتجر: كل صف = كنيسة / خدمة / فصل يظهر فيه المتجر (church_id null = الكل)';

create unique index if not exists uq_store_shop_targets
  on public.store_shop_targets (shop_id, coalesce(church_id, '00000000-0000-0000-0000-000000000000'::uuid),
                                coalesce(service_id, '00000000-0000-0000-0000-000000000000'::uuid),
                                coalesce(class_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index if not exists idx_store_shop_targets_shop  on public.store_shop_targets(shop_id);
create index if not exists idx_store_shop_targets_scope on public.store_shop_targets(church_id, service_id, class_id);

create or replace function public.check_store_shop_target()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.service_id is not null and not exists (
    select 1 from public.services s where s.id = new.service_id and s.church_id = new.church_id) then
    raise exception 'service does not belong to the church';
  end if;
  if new.class_id is not null and not exists (
    select 1 from public.classes c
     where c.id = new.class_id and c.service_id = new.service_id and c.church_id = new.church_id) then
    raise exception 'class does not belong to the service';
  end if;
  return new;
end $$;
drop trigger if exists trg_store_shop_target on public.store_shop_targets;
create trigger trg_store_shop_target before insert or update on public.store_shop_targets
for each row execute function public.check_store_shop_target();

-- does this shop cover the given enrollment scope?
create or replace function public.store_shop_covers(p_shop uuid, p_church uuid, p_service uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.store_shop_targets t
     where t.shop_id = p_shop
       and (t.church_id is null
            or (t.church_id = p_church
                and (t.service_id is null or t.service_id = p_service)
                and (t.class_id   is null or t.class_id   = p_class)))
  )
$$;
grant execute on function public.store_shop_covers(uuid, uuid, uuid, uuid) to authenticated, anon;

-- can the caller see the shop? owner / church manager of the owning church
-- (scope_contains) — or ANY target overlaps his scope (a class servant sees
-- the shops connected to his class, not the ones of other classes)
create or replace function public.store_shop_visible(p_shop uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('store') and (
    exists (select 1 from public.store_shops s where s.id = p_shop and public.scope_contains(s.church_id, null, null))
    or exists (
      select 1 from public.store_shop_targets t
       where t.shop_id = p_shop
         and (t.church_id is null or public.scope_overlaps(t.church_id, t.service_id, t.class_id)))
  )
$$;
grant execute on function public.store_shop_visible(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 3. store_items.shop_id · store_orders.shop_id / request_id / source
-- ---------------------------------------------------------------------
alter table public.store_items
  add column if not exists shop_id uuid references public.store_shops(id) on delete set null;
create index if not exists idx_store_items_shop on public.store_items(shop_id);

alter table public.store_orders
  add column if not exists shop_id    uuid references public.store_shops(id) on delete set null,
  add column if not exists request_id uuid,                                  -- FK added below (table created after)
  add column if not exists source     text not null default 'pos';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'store_orders_source_check') then
    alter table public.store_orders add constraint store_orders_source_check check (source in ('pos', 'request'));
  end if;
end $$;
create index if not exists idx_store_orders_shop on public.store_orders(shop_id);

-- ---------------------------------------------------------------------
-- 4. TABLES: store_requests (طلبات الشراء) + store_request_items
-- ---------------------------------------------------------------------
create table if not exists public.store_requests (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null references public.store_shops(id) on delete cascade,
  enrollment_id  uuid not null references public.enrollments(id) on delete cascade,
  person_id      uuid not null references public.persons(id) on delete cascade,
  church_id      uuid not null references public.churches(id) on delete cascade,
  service_id     uuid not null references public.services(id) on delete cascade,
  class_id       uuid not null references public.classes(id)  on delete cascade,
  status         text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  items_count    integer not null default 0,
  total_points   integer not null default 0 check (total_points >= 0),
  balance_at_request integer not null default 0,     -- the child's balance when he sent it (info)
  note           text,                               -- the child's note
  decision_note  text,                               -- the servant's reason (reject)
  order_id       uuid references public.store_orders(id) on delete set null,   -- when approved
  decided_by     uuid references public.servant_enrollments(id) on delete set null,
  decided_at     timestamptz,
  created_at     timestamptz not null default now()
);
comment on table public.store_requests is
  'إستبدال النقاط — طلبات الشراء من بوابة المخدوم: سلة أرسلها المخدوم، يعتمدها الخادم بعد مسح كارته أو يرفضها';

create index if not exists idx_store_requests_status  on public.store_requests(status, created_at desc);
create index if not exists idx_store_requests_church  on public.store_requests(church_id, status);
create index if not exists idx_store_requests_service on public.store_requests(service_id);
create index if not exists idx_store_requests_class   on public.store_requests(class_id);
create index if not exists idx_store_requests_person  on public.store_requests(person_id, created_at desc);
create index if not exists idx_store_requests_shop    on public.store_requests(shop_id);

create table if not exists public.store_request_items (
  id         uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.store_requests(id) on delete cascade,
  item_id    uuid references public.store_items(id) on delete set null,
  item_code  text not null,
  item_name  text not null,
  image_url  text,
  unit_price integer not null check (unit_price >= 0),
  qty        integer not null check (qty > 0),
  line_total integer not null check (line_total >= 0)
);
create index if not exists idx_store_request_items_request on public.store_request_items(request_id);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'store_orders_request_id_fkey') then
    alter table public.store_orders
      add constraint store_orders_request_id_fkey foreign key (request_id)
      references public.store_requests(id) on delete set null;
  end if;
end $$;
create index if not exists idx_store_orders_request on public.store_orders(request_id);

-- ---------------------------------------------------------------------
-- 5. RLS
-- ---------------------------------------------------------------------
alter table public.store_shops          enable row level security;
alter table public.store_shop_targets   enable row level security;
alter table public.store_requests       enable row level security;
alter table public.store_request_items  enable row level security;

-- shops: read = store_shop_visible; create = any servant of the church
-- (he then connects the places his scope contains); edit / delete /
-- activate = whoever can see the shop
drop policy if exists store_shops_select on public.store_shops;
create policy store_shops_select on public.store_shops for select using (
  public.store_shop_visible(id)
);
drop policy if exists store_shops_insert on public.store_shops;
create policy store_shops_insert on public.store_shops for insert with check (
  (select public.module_visible('store')) and (select public.scope_overlaps(church_id, null, null))
);
drop policy if exists store_shops_update on public.store_shops;
create policy store_shops_update on public.store_shops for update using (
  public.store_shop_visible(id)
) with check (
  (select public.module_visible('store')) and (select public.scope_overlaps(church_id, null, null))
);
drop policy if exists store_shops_delete on public.store_shops;
create policy store_shops_delete on public.store_shops for delete using (
  public.store_shop_visible(id)
);

-- targets: read with the shop; write when my scope CONTAINS the target
-- (a class servant can only connect his class; «الكل» is owner-only)
drop policy if exists store_shop_targets_select on public.store_shop_targets;
create policy store_shop_targets_select on public.store_shop_targets for select using (
  public.store_shop_visible(shop_id)
);
drop policy if exists store_shop_targets_insert on public.store_shop_targets;
create policy store_shop_targets_insert on public.store_shop_targets for insert with check (
  (select public.module_visible('store'))
  and exists (select 1 from public.store_shops s where s.id = shop_id and public.scope_overlaps(s.church_id, null, null))
  and (case when church_id is null then public.is_owner() else public.scope_contains(church_id, service_id, class_id) end)
);
drop policy if exists store_shop_targets_delete on public.store_shop_targets;
create policy store_shop_targets_delete on public.store_shop_targets for delete using (
  (select public.module_visible('store'))
  and exists (select 1 from public.store_shops s where s.id = shop_id and public.scope_overlaps(s.church_id, null, null))
  and (case when church_id is null then public.is_owner() else public.scope_contains(church_id, service_id, class_id) end)
);

-- requests: the servants who can see the child's enrollment; no direct
-- writes — everything goes through the RPCs
drop policy if exists store_requests_select on public.store_requests;
create policy store_requests_select on public.store_requests for select using (
  (select public.module_visible('store'))
  and public.enrollment_visible(church_id, service_id, class_id,
    (select role from public.my_scope()), (select church_id from public.my_scope()),
    (select service_id from public.my_scope()), (select class_id from public.my_scope()))
);
drop policy if exists store_request_items_select on public.store_request_items;
create policy store_request_items_select on public.store_request_items for select using (
  exists (
    select 1 from public.store_requests r
     where r.id = store_request_items.request_id
       and (select public.module_visible('store'))
       and public.enrollment_visible(r.church_id, r.service_id, r.class_id,
         (select role from public.my_scope()), (select church_id from public.my_scope()),
         (select service_id from public.my_scope()), (select class_id from public.my_scope()))
  )
);

-- ---------------------------------------------------------------------
-- 6. store_checkout learns shop_id / request_id / source (internal
--    variant) — the public 3-arg signature stays and delegates to it.
-- ---------------------------------------------------------------------
create or replace function public.store_checkout_internal(
  p_enrollment uuid, p_lines jsonb, p_note text, p_shop uuid, p_request uuid, p_source text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  s        record;
  e        public.enrollments;
  it       public.store_items;
  ln       record;
  v_order  uuid;
  v_total  integer := 0;
  v_count  integer := 0;
  v_before integer;
  v_after  integer;
  v_pl     uuid;
begin
  if auth.uid() is null then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if not public.module_visible('store') then
    raise exception 'module_not_visible' using errcode = 'P0001';
  end if;
  select * into s from public.my_scope();
  if not found then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  select * into e from public.enrollments where id = p_enrollment for update;
  if not found then
    raise exception 'enrollment_not_found' using errcode = 'P0002';
  end if;
  if not public.enrollment_visible(e.church_id, e.service_id, e.class_id,
                                   s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'empty_basket' using errcode = 'P0001';
  end if;

  v_before := e.points;

  insert into public.store_orders (
    enrollment_id, person_id, church_id, service_id, class_id,
    balance_before, balance_after, note, recorded_by, shop_id, request_id, source)
  values (e.id, e.person_id, e.church_id, e.service_id, e.class_id,
          v_before, v_before, nullif(trim(coalesce(p_note, '')), ''), auth.uid(),
          p_shop, p_request, coalesce(p_source, 'pos'))
  returning id into v_order;

  for ln in
    select (x->>'item_id')::uuid as item_id, sum((x->>'qty')::int) as qty
      from jsonb_array_elements(p_lines) x
     group by 1
  loop
    if ln.item_id is null or ln.qty is null or ln.qty <= 0 then
      raise exception 'invalid_line' using errcode = 'P0001';
    end if;
    select * into it from public.store_items where id = ln.item_id for update;
    if not found then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
    if not it.is_active then
      raise exception 'item_inactive:%', it.name using errcode = 'P0001';
    end if;
    -- an item of a shop applies where the SHOP is connected; a legacy item
    -- (no shop) applies by its own scope columns
    if it.shop_id is not null then
      if not public.store_shop_covers(it.shop_id, e.church_id, e.service_id, e.class_id) then
        raise exception 'item_out_of_scope:%', it.name using errcode = 'P0001';
      end if;
    elsif not (it.church_id = e.church_id
            and (it.service_id is null or it.service_id = e.service_id)
            and (it.class_id   is null or it.class_id   = e.class_id)) then
      raise exception 'item_out_of_scope:%', it.name using errcode = 'P0001';
    end if;
    if it.stock < ln.qty then
      raise exception 'insufficient_stock:%', it.name using errcode = 'P0001';
    end if;

    update public.store_items set stock = stock - ln.qty where id = it.id;

    insert into public.store_order_items (
      order_id, item_id, item_code, item_name, image_url, unit_price, qty, line_total)
    values (v_order, it.id, it.code, it.name, it.image_url, it.price, ln.qty, it.price * ln.qty);

    v_total := v_total + it.price * ln.qty;
    v_count := v_count + ln.qty;
  end loop;

  if v_total > v_before then
    raise exception 'insufficient_points' using errcode = 'P0001';
  end if;

  if v_total > 0 then
    insert into public.points_log (enrollment_id, cause_id, event_id, delta, recorded_by)
    values (e.id, null, null, -v_total, auth.uid())
    returning id into v_pl;
  end if;

  select points into v_after from public.enrollments where id = e.id;

  update public.store_orders
     set items_count = v_count, total_points = v_total,
         balance_after = v_after, points_log_id = v_pl
   where id = v_order;

  return jsonb_build_object(
    'order_id', v_order, 'total_points', v_total, 'items_count', v_count,
    'balance_before', v_before, 'balance_after', v_after);
end $$;
revoke all on function public.store_checkout_internal(uuid, jsonb, text, uuid, uuid, text) from public, anon, authenticated;

-- POS entry point (unchanged signature). The shop of the sale is the shop
-- of the first line (all lines of one basket come from one shop / counter).
create or replace function public.store_checkout(
  p_enrollment uuid, p_lines jsonb, p_note text default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid;
begin
  if p_lines is not null and jsonb_typeof(p_lines) = 'array' and jsonb_array_length(p_lines) > 0 then
    select it.shop_id into v_shop from public.store_items it
     where it.id = nullif(p_lines->0->>'item_id', '')::uuid;
  end if;
  return public.store_checkout_internal(p_enrollment, p_lines, p_note, v_shop, null, 'pos');
end $$;
grant execute on function public.store_checkout(uuid, jsonb, text) to authenticated;

-- ---------------------------------------------------------------------
-- 7. CHILD PORTAL — shops · items · send / cancel a request · my requests
-- ---------------------------------------------------------------------

-- the ACTIVE shops that cover one of my enrollments (module granted there)
create or replace function public.child_portal_shops(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.persons; res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'name', s.name, 'description', s.description, 'image_url', s.image_url,
           'church_id', s.church_id, 'church_name', ch.name,
           'items_count', (select count(*) from public.store_items i where i.shop_id = s.id and i.is_active and i.stock > 0),
           'enrollment_ids', (
             select jsonb_agg(distinct e.id) from public.enrollments e
              where e.person_id = p.id and e.kind = 'child' and e.status = 'active'
                and public.store_shop_covers(s.id, e.church_id, e.service_id, e.class_id)
                and public.module_granted_for('store', e.church_id, e.service_id, e.class_id)),
           'pending_requests', (select count(*) from public.store_requests r where r.shop_id = s.id and r.person_id = p.id and r.status = 'pending')
         ) order by s.sort_order, s.name), '[]'::jsonb)
    into res
    from public.store_shops s
    join public.churches ch on ch.id = s.church_id
   where s.is_active
     and exists (
       select 1 from public.enrollments e
        where e.person_id = p.id and e.kind = 'child' and e.status = 'active'
          and public.store_shop_covers(s.id, e.church_id, e.service_id, e.class_id)
          and public.module_granted_for('store', e.church_id, e.service_id, e.class_id));
  return res;
end $$;
grant execute on function public.child_portal_shops(text) to anon, authenticated;

-- the sellable items of ONE shop I can see
create or replace function public.child_portal_shop_items(p_national_id text, p_shop uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.persons; res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  if not exists (
    select 1 from public.store_shops s
     where s.id = p_shop and s.is_active
       and exists (
         select 1 from public.enrollments e
          where e.person_id = p.id and e.kind = 'child' and e.status = 'active'
            and public.store_shop_covers(s.id, e.church_id, e.service_id, e.class_id)
            and public.module_granted_for('store', e.church_id, e.service_id, e.class_id))) then
    raise exception 'shop_not_found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.id, 'code', i.code, 'name', i.name, 'description', i.description,
           'image_url', i.image_url, 'price', i.price, 'stock', i.stock
         ) order by i.sort_order, i.name), '[]'::jsonb)
    into res
    from public.store_items i
   where i.shop_id = p_shop and i.is_active;
  return res;
end $$;
grant execute on function public.child_portal_shop_items(text, uuid) to anon, authenticated;

-- shape of one request (used by the child list + the servant RPCs)
create or replace function public.store_request_json(p_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', r.id, 'shop_id', r.shop_id, 'shop_name', s.name, 'shop_image_url', s.image_url,
    'enrollment_id', r.enrollment_id, 'person_id', r.person_id,
    'status', r.status, 'items_count', r.items_count, 'total_points', r.total_points,
    'balance_at_request', r.balance_at_request, 'note', r.note, 'decision_note', r.decision_note,
    'order_id', r.order_id, 'decided_at', r.decided_at, 'created_at', r.created_at,
    'decided_by_name', pr.full_name,
    'class_name', cl.name, 'service_name', sv.name, 'church_name', ch.name,
    'items', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', li.id, 'item_id', li.item_id, 'item_name', li.item_name, 'item_code', li.item_code,
               'image_url', li.image_url, 'unit_price', li.unit_price,
               'qty', li.qty, 'line_total', li.line_total) order by li.item_name), '[]'::jsonb)
        from public.store_request_items li where li.request_id = r.id))
    from public.store_requests r
    join public.store_shops s on s.id = r.shop_id
    left join public.servant_enrollments pr on pr.id = r.decided_by
    join public.classes  cl on cl.id = r.class_id
    join public.services sv on sv.id = r.service_id
    join public.churches ch on ch.id = r.church_id
   where r.id = p_id
$$;
revoke all on function public.store_request_json(uuid) from public, anon, authenticated;

-- «أرسل الطلب» — the child's cart → a pending request
--   p_lines = [{ "item_id": uuid, "qty": int }, ...]
create or replace function public.child_portal_store_request(
  p_national_id text, p_shop uuid, p_lines jsonb, p_enrollment uuid default null, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p public.persons; s public.store_shops; e public.enrollments; it public.store_items; ln record;
  v_req uuid; v_total int := 0; v_count int := 0;
begin
  p := public.child_portal_person(p_national_id);
  select * into s from public.store_shops where id = p_shop;
  if not found or not s.is_active then raise exception 'shop_not_found' using errcode = 'P0002'; end if;

  -- the enrollment the shop is connected to (explicit when the child is in several)
  select * into e from public.enrollments x
   where x.person_id = p.id and x.kind = 'child' and x.status = 'active'
     and (p_enrollment is null or x.id = p_enrollment)
     and public.store_shop_covers(s.id, x.church_id, x.service_id, x.class_id)
     and public.module_granted_for('store', x.church_id, x.service_id, x.class_id)
   order by x.created_at limit 1;
  if not found then raise exception 'shop_not_found' using errcode = 'P0002'; end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'empty_basket' using errcode = 'P0001';
  end if;
  -- one open request per shop at a time
  if exists (select 1 from public.store_requests r where r.person_id = p.id and r.shop_id = s.id and r.status = 'pending') then
    raise exception 'request_pending' using errcode = 'P0001';
  end if;

  insert into public.store_requests (shop_id, enrollment_id, person_id, church_id, service_id, class_id,
                                     balance_at_request, note)
  values (s.id, e.id, e.person_id, e.church_id, e.service_id, e.class_id,
          e.points, nullif(trim(coalesce(p_note, '')), ''))
  returning id into v_req;

  for ln in
    select (x->>'item_id')::uuid as item_id, sum((x->>'qty')::int) as qty
      from jsonb_array_elements(p_lines) x group by 1
  loop
    if ln.item_id is null or ln.qty is null or ln.qty <= 0 then
      raise exception 'invalid_line' using errcode = 'P0001';
    end if;
    select * into it from public.store_items where id = ln.item_id;
    if not found or it.shop_id is distinct from s.id then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
    if not it.is_active then raise exception 'item_inactive:%', it.name using errcode = 'P0001'; end if;
    if it.stock < ln.qty then raise exception 'insufficient_stock:%', it.name using errcode = 'P0001'; end if;
    insert into public.store_request_items (request_id, item_id, item_code, item_name, image_url, unit_price, qty, line_total)
    values (v_req, it.id, it.code, it.name, it.image_url, it.price, ln.qty, it.price * ln.qty);
    v_total := v_total + it.price * ln.qty;
    v_count := v_count + ln.qty;
  end loop;

  if v_total > e.points then raise exception 'insufficient_points' using errcode = 'P0001'; end if;

  update public.store_requests set items_count = v_count, total_points = v_total where id = v_req;
  return public.store_request_json(v_req);
end $$;
grant execute on function public.child_portal_store_request(text, uuid, jsonb, uuid, text) to anon, authenticated;

-- the child cancels his own PENDING request
create or replace function public.child_portal_store_request_cancel(p_national_id text, p_request uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare p public.persons; r public.store_requests;
begin
  p := public.child_portal_person(p_national_id);
  select * into r from public.store_requests where id = p_request and person_id = p.id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
  update public.store_requests set status = 'cancelled', decided_at = now() where id = r.id;
  return public.store_request_json(r.id);
end $$;
grant execute on function public.child_portal_store_request_cancel(text, uuid) to anon, authenticated;

-- my requests (all statuses), newest first
create or replace function public.child_portal_store_requests(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare p public.persons; res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(public.store_request_json(r.id) order by r.created_at desc), '[]'::jsonb)
    into res from public.store_requests r where r.person_id = p.id;
  return res;
end $$;
grant execute on function public.child_portal_store_requests(text) to anon, authenticated;

-- my receipts — now with the shop and the source (pos | request)
create or replace function public.child_portal_store_orders(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  p public.persons;
  res jsonb;
begin
  p := public.child_portal_person(p_national_id);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id,
           'enrollment_id', o.enrollment_id,
           'status', o.status,
           'source', o.source,
           'shop_id', o.shop_id,
           'shop_name', sh.name,
           'request_id', o.request_id,
           'items_count', o.items_count,
           'total_points', o.total_points,
           'balance_before', o.balance_before,
           'balance_after', o.balance_after,
           'note', o.note,
           'created_at', o.created_at,
           'cancelled_at', o.cancelled_at,
           'recorded_by_name', pr.full_name,
           'class_name', cl.name,
           'service_name', sv.name,
           'church_name', ch.name,
           'items', (
             select coalesce(jsonb_agg(jsonb_build_object(
                      'id', li.id, 'item_name', li.item_name, 'item_code', li.item_code,
                      'image_url', li.image_url, 'unit_price', li.unit_price,
                      'qty', li.qty, 'line_total', li.line_total) order by li.item_name), '[]'::jsonb)
               from public.store_order_items li where li.order_id = o.id)
         ) order by o.created_at desc), '[]'::jsonb)
    into res
    from public.store_orders o
    join public.enrollments e on e.id = o.enrollment_id
    left join public.servant_enrollments pr on pr.id = o.recorded_by
    left join public.store_shops sh on sh.id = o.shop_id
    join public.classes  cl on cl.id = o.class_id
    join public.services sv on sv.id = o.service_id
    join public.churches ch on ch.id = o.church_id
   where e.person_id = p.id;
  return res;
end $$;
grant execute on function public.child_portal_store_orders(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. SERVANT SIDE — approve (after scanning the child's card) / reject
-- ---------------------------------------------------------------------
create or replace function public.store_request_approve(p_request uuid, p_card_code text, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  s record; r public.store_requests; p public.persons; lines jsonb; res jsonb;
begin
  if auth.uid() is null then raise exception 'forbidden' using errcode = 'P0001'; end if;
  if not public.module_visible('store') then raise exception 'module_not_visible' using errcode = 'P0001'; end if;
  select * into s from public.my_scope();
  if not found then raise exception 'forbidden' using errcode = 'P0001'; end if;

  select * into r from public.store_requests where id = p_request for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if not public.enrollment_visible(r.church_id, r.service_id, r.class_id, s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;

  -- the CONFIRMATION: the scanned card must be the child's own code
  select * into p from public.persons where id = r.person_id;
  if nullif(trim(coalesce(p_card_code, '')), '') is null
     or lower(trim(p_card_code)) <> lower(trim(p.national_id)) then
    raise exception 'card_mismatch' using errcode = 'P0001';
  end if;

  select jsonb_agg(jsonb_build_object('item_id', li.item_id, 'qty', li.qty))
    into lines from public.store_request_items li where li.request_id = r.id;
  if lines is null then raise exception 'empty_basket' using errcode = 'P0001'; end if;
  if exists (select 1 from public.store_request_items li where li.request_id = r.id and li.item_id is null) then
    raise exception 'item_not_found' using errcode = 'P0002';
  end if;

  -- the sale itself — same rules as the POS (stock · scope · balance)
  res := public.store_checkout_internal(r.enrollment_id, lines,
           coalesce(nullif(trim(coalesce(p_note, '')), ''), r.note), r.shop_id, r.id, 'request');

  update public.store_requests
     set status = 'approved', order_id = (res->>'order_id')::uuid,
         decided_by = auth.uid(), decided_at = now(),
         decision_note = nullif(trim(coalesce(p_note, '')), '')
   where id = r.id;

  return public.store_request_json(r.id) || res;
end $$;
grant execute on function public.store_request_approve(uuid, text, text) to authenticated;

create or replace function public.store_request_reject(p_request uuid, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s record; r public.store_requests;
begin
  if auth.uid() is null then raise exception 'forbidden' using errcode = 'P0001'; end if;
  if not public.module_visible('store') then raise exception 'module_not_visible' using errcode = 'P0001'; end if;
  select * into s from public.my_scope();
  if not found then raise exception 'forbidden' using errcode = 'P0001'; end if;
  select * into r from public.store_requests where id = p_request for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if not public.enrollment_visible(r.church_id, r.service_id, r.class_id, s.role, s.church_id, s.service_id, s.class_id) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
  update public.store_requests
     set status = 'rejected', decided_by = auth.uid(), decided_at = now(),
         decision_note = nullif(trim(coalesce(p_note, '')), '')
   where id = r.id;
  return public.store_request_json(r.id);
end $$;
grant execute on function public.store_request_reject(uuid, text) to authenticated;

-- one request with its lines for the servant UI (RLS-checked)
create or replace function public.store_request_detail(p_request uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.store_requests r where r.id = p_request
                             and public.module_visible('store')
                             and public.enrollment_visible(r.church_id, r.service_id, r.class_id,
                                   (select role from public.my_scope()), (select church_id from public.my_scope()),
                                   (select service_id from public.my_scope()), (select class_id from public.my_scope())))
         then public.store_request_json(p_request) else null end
$$;
grant execute on function public.store_request_detail(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 9. REALTIME — shops / targets via postgres_changes (cold tables);
--    requests on the broadcast bus (hot, like store_orders)
-- ---------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'store_shops') then
    alter publication supabase_realtime add table public.store_shops;
  end if;
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'store_shop_targets') then
    alter publication supabase_realtime add table public.store_shop_targets;
  end if;
exception when undefined_object then null;
end $$;
alter table public.store_shops        replica identity full;
alter table public.store_shop_targets replica identity full;

do $$
begin
  if to_regprocedure('public.rt_trg_scoped()') is not null then
    execute 'drop trigger if exists zzz_rt_ins on public.store_requests';
    execute 'drop trigger if exists zzz_rt_upd on public.store_requests';
    execute 'drop trigger if exists zzz_rt_del on public.store_requests';
    execute 'create trigger zzz_rt_ins after insert on public.store_requests referencing new table as new_rows for each statement execute function public.rt_trg_scoped()';
    execute 'create trigger zzz_rt_upd after update on public.store_requests referencing old table as old_rows new table as new_rows for each statement execute function public.rt_trg_scoped()';
    execute 'create trigger zzz_rt_del after delete on public.store_requests referencing old table as old_rows for each statement execute function public.rt_trg_scoped()';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 10. ACTIVITY LOG — audit the new tables
-- ---------------------------------------------------------------------
do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('store_shops');
    perform public.activity_audit_attach('store_shop_targets');
    perform public.activity_audit_attach('store_requests');
  end if;
end $$;

-- action keys: store_shop.add / .activate / .deactivate · store_shop_target.add
-- · store_request.add (by the child) / .approved / .rejected / .cancelled
do $$ begin
  if to_regprocedure('public.activity_action_key(text,text,jsonb,jsonb)') is not null then
    execute $fn$
create or replace function public.activity_action_key(p_table text, p_op text, p_old jsonb, p_new jsonb)
returns text language plpgsql immutable as $body$
declare base text; verb text;
begin
  verb := case p_op when 'INSERT' then 'add' when 'DELETE' then 'remove' else 'update' end;
  base := case p_table
    when 'attendance_log' then 'attendance'
    when 'points_log' then 'points'
    when 'contact_log' then case coalesce(p_new->>'kind', p_old->>'kind') when 'call' then 'call' else 'message' end
    when 'persons' then 'person'
    when 'enrollments' then case when coalesce(p_new->>'kind', p_old->>'kind') = 'servant' then 'servant_mirror' else 'enrollment' end
    when 'servant_enrollments' then 'servant'
    when 'servant_scopes' then 'servant_scope'
    when 'permissions' then 'permission'
    when 'permission_profiles' then 'permission_profile'
    when 'module_access' then 'module_access'
    when 'churches' then 'church'
    when 'services' then 'service'
    when 'classes' then 'class'
    when 'events' then 'event'
    when 'causes' then 'cause'
    when 'call_feedbacks' then 'feedback'
    when 'card_print_requests' then 'print_request'
    when 'card_templates' then 'card_template'
    when 'data_change_requests' then 'data_request'
    when 'child_join_requests' then 'join_request'
    when 'person_credentials' then 'password'
    when 'shepherd_groups' then 'shepherd'
    when 'store_items' then 'store_item'
    when 'store_orders' then 'store_order'
    when 'store_shops' then 'store_shop'
    when 'store_shop_targets' then 'store_shop_target'
    when 'store_requests' then 'store_request'
    when 'exams' then 'exam'
    when 'exam_questions' then 'exam_question'
    when 'exam_attempts' then 'exam_attempt'
    when 'birthday_greetings' then 'birthday'
    when 'birthday_settings' then 'birthday_setting'
    when 'birthday_card_templates' then 'birthday_card'
    when 'chat_messages' then 'chat'
    when 'online_classes' then 'online_class'
    when 'online_class_participants' then 'online_participant'
    when 'achievements' then 'achievement'
    when 'user_achievements' then 'achievement_award'
    when 'occasions' then 'occasion'
    when 'occasion_registrations' then 'occasion_registration'
    when 'occasion_checklist_items' then 'occasion_checklist'
    when 'occasion_checklist_marks' then 'occasion_mark'
    when 'notifications' then 'notification'
    when 'notification_automations' then 'notification_automation'
    when 'app_settings' then 'setting'
    when 'result_exams' then 'result_exam'
    when 'result_subjects' then 'result_subject'
    when 'exam_results' then 'result'
    when 'grading_systems' then 'grading'
    when 'grading_grades' then 'grading_grade'
    when 'library_subjects' then 'library_subject'
    when 'library_books' then 'library_book'
    when 'library_lectures' then 'library_lecture'
    when 'library_favorites' then 'library_favorite'
    when 'backup_runs' then 'backup'
    when 'backup_schedules' then 'backup_schedule'
    else p_table end;

  -- a few semantic refinements
  if p_table = 'servant_enrollments' and p_op = 'UPDATE' then
    if p_old->>'status' is distinct from p_new->>'status' then
      verb := case p_new->>'status' when 'approved' then 'approve' when 'rejected' then 'reject'
                   when 'suspended' then 'suspend' else 'status' end;
    elsif p_old->>'role' is distinct from p_new->>'role' then verb := 'role';
    end if;
  elsif p_table = 'enrollments' and p_op = 'UPDATE' then
    if p_old->>'status' is distinct from p_new->>'status' then verb := case p_new->>'status' when 'stopped' then 'stop' else 'resume' end;
    elsif p_old->>'class_id' is distinct from p_new->>'class_id' then verb := 'move';
    elsif (p_old - 'attendance_count' - 'points' - 'edited_at' - 'edited_by') = (p_new - 'attendance_count' - 'points' - 'edited_at' - 'edited_by') then
      verb := 'counters';
    end if;
  elsif p_table = 'points_log' and p_op = 'INSERT' then
    verb := case when coalesce((p_new->>'delta')::int, 0) < 0 then 'deduct' else 'add' end;
  elsif p_table = 'store_shops' and p_op = 'UPDATE' and p_old->>'is_active' is distinct from p_new->>'is_active' then
    verb := case when (p_new->>'is_active')::boolean then 'activate' else 'deactivate' end;
  elsif p_table in ('store_orders', 'store_requests', 'exam_attempts', 'occasion_registrations') and p_op = 'UPDATE'
        and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table in ('data_change_requests', 'child_join_requests') and p_op = 'UPDATE'
        and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table = 'result_exams' and p_op = 'UPDATE' and p_old->>'locked' is distinct from p_new->>'locked' then
    verb := case when (p_new->>'locked')::boolean then 'lock' else 'unlock' end;
  elsif p_table = 'online_classes' and p_op = 'UPDATE' and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  elsif p_table = 'exams' and p_op = 'UPDATE' and p_old->>'status' is distinct from p_new->>'status' then
    verb := coalesce(p_new->>'status', 'status');
  end if;
  return base || '.' || verb;
end $body$;
    $fn$;
  end if;
end $$;

do $$ begin
