analyze public.store_shops;
analyze public.store_shop_targets;
analyze public.store_requests;
analyze public.store_request_items;



-- #####################################################################
-- ##  20261002120000_store_shop_is_the_container.sql
-- #####################################################################

-- =====================================================================
-- 20261002120000 — إستبدال النقاط: المتجر هو الوعاء (the shop is the container)
-- =====================================================================
-- Follow-up of 20261001120000 after the first live use:
--
-- 1. BUG «ليس لديك صلاحية» when adding a shop.
--    `insert into store_shops … returning *` failed for EVERY role (even
--    the owner). Postgres evaluates the SELECT policy on the RETURNING row;
--    the policy called store_shop_visible(id), a STABLE security-definer
--    function that re-reads store_shops — inside the same statement it does
--    not see the row being inserted → false → «new row violates row-level
--    security policy». Fix: the policies use the row's own columns
--    (church_id) and the targets table only; no self-lookup on store_shops.
--
-- 2. The shop is the container: everything of the module (items, POS,
--    requests, archive) lives INSIDE a shop.
--      • store_items.shop_id is REQUIRED for new items (legacy items
--        without a shop keep working until they are moved).
--      • item visibility / write rights follow the SHOP (whoever can see /
--        manage the shop manages its items), not the item's scope columns —
--        the item's church_id is copied from the shop by trigger.
--      • the item code is unique per SHOP (a legacy per-church index is
--        kept for shop-less items).
--      • store_shop_stats(shop) → items · stock · pending · orders · points
--        for the shops list.
--
-- Idempotent — safe to re-run.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. store_shops — RLS that works with RETURNING
-- ---------------------------------------------------------------------
-- Who may SEE (and manage) a shop:
--   • owner / church manager of the owning church (scope_contains), or
--   • the servant who CREATED it (so `insert … returning` works before any
--     target exists and a class servant always keeps his own shop), or
--   • any target of the shop overlaps the caller's scope (a class servant
--     sees the shops connected to his class; «الكل» → everybody).
-- All helpers are SECURITY DEFINER so the policies never recurse
-- (shops ↔ targets ↔ items).

-- any target of the shop overlaps my scope?
create or replace function public.store_shop_target_overlaps(p_shop uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.store_shop_targets t
     where t.shop_id = p_shop
       and (t.church_id is null or public.scope_overlaps(t.church_id, t.service_id, t.class_id)))
$$;
grant execute on function public.store_shop_target_overlaps(uuid) to authenticated;

-- the church of a shop (bypasses the shops RLS)
create or replace function public.store_shop_church(p_shop uuid)
returns uuid language sql stable security definer set search_path = public as $$
  select church_id from public.store_shops where id = p_shop
$$;
grant execute on function public.store_shop_church(uuid) to authenticated;

-- row-level rule (used by the store_shops policies on the row's own columns)
create or replace function public.store_shop_row_visible(p_shop uuid, p_church uuid, p_created_by uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('store') and (
    public.scope_contains(p_church, null, null)
    or (p_created_by is not null and p_created_by = auth.uid())
    or public.store_shop_target_overlaps(p_shop))
$$;
grant execute on function public.store_shop_row_visible(uuid, uuid, uuid) to authenticated;

-- by id (used everywhere else: items, requests, stats, RPCs)
create or replace function public.store_shop_visible(p_shop uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select public.store_shop_row_visible(s.id, s.church_id, s.created_by)
                     from public.store_shops s where s.id = p_shop), false)
$$;
grant execute on function public.store_shop_visible(uuid) to authenticated;

-- who may CREATE a shop of a church: module + my scope overlaps the church
create or replace function public.store_shop_creatable(p_church uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.module_visible('store') and public.scope_overlaps(p_church, null, null)
$$;
grant execute on function public.store_shop_creatable(uuid) to authenticated;

drop policy if exists store_shops_select on public.store_shops;
create policy store_shops_select on public.store_shops for select using (
  public.store_shop_row_visible(id, church_id, created_by)
);
drop policy if exists store_shops_insert on public.store_shops;
create policy store_shops_insert on public.store_shops for insert with check (
  (select public.store_shop_creatable(church_id))
);
drop policy if exists store_shops_update on public.store_shops;
create policy store_shops_update on public.store_shops for update using (
  public.store_shop_row_visible(id, church_id, created_by)
) with check (
  (select public.store_shop_creatable(church_id))
);
drop policy if exists store_shops_delete on public.store_shops;
create policy store_shops_delete on public.store_shops for delete using (
  public.store_shop_row_visible(id, church_id, created_by)
);

-- targets: read with the shop; write when I can manage the shop AND my
-- scope CONTAINS the target («الكل» is owner-only)
drop policy if exists store_shop_targets_select on public.store_shop_targets;
create policy store_shop_targets_select on public.store_shop_targets for select using (
  public.store_shop_visible(shop_id)
);
drop policy if exists store_shop_targets_insert on public.store_shop_targets;
create policy store_shop_targets_insert on public.store_shop_targets for insert with check (
  public.store_shop_visible(shop_id)
  and (case when church_id is null then public.is_owner() else public.scope_contains(church_id, service_id, class_id) end)
);
drop policy if exists store_shop_targets_delete on public.store_shop_targets;
create policy store_shop_targets_delete on public.store_shop_targets for delete using (
  public.store_shop_visible(shop_id)
  and (case when church_id is null then public.is_owner() else public.scope_contains(church_id, service_id, class_id) end)
);

-- ---------------------------------------------------------------------
-- 2. store_items — inside a shop
-- ---------------------------------------------------------------------
-- new items must belong to a shop; the church is copied from the shop
create or replace function public.store_items_fill_from_shop()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_church uuid;
begin
  if new.shop_id is not null then
    select church_id into v_church from public.store_shops where id = new.shop_id;
    if v_church is null then
      raise exception 'shop_not_found' using errcode = 'P0002';
    end if;
    new.church_id  := v_church;
    new.service_id := null;     -- the place of a shop item is the shop's
    new.class_id   := null;
  elsif tg_op = 'INSERT' then
    raise exception 'shop_required' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists trg_store_items_fill_from_shop on public.store_items;
create trigger trg_store_items_fill_from_shop before insert or update on public.store_items
for each row execute function public.store_items_fill_from_shop();

-- code unique per SHOP (legacy per-church index stays for shop-less items)
drop index if exists public.uq_store_items_church_code;
create unique index if not exists uq_store_items_church_code_legacy
  on public.store_items (church_id, lower(trim(code))) where shop_id is null;
create unique index if not exists uq_store_items_shop_code
  on public.store_items (shop_id, lower(trim(code))) where shop_id is not null;

-- RLS: a shop item is read / written by whoever can see / manage the shop;
-- a legacy item keeps the 0026 scope rules
drop policy if exists store_items_select on public.store_items;
create policy store_items_select on public.store_items for select using (
  (select public.module_visible('store')) and (
    case when shop_id is null then (select public.scope_overlaps(church_id, service_id, class_id))
         else public.store_shop_visible(shop_id) end)
);
drop policy if exists store_items_insert on public.store_items;
create policy store_items_insert on public.store_items for insert with check (
  (select public.module_visible('store')) and (
    case when shop_id is null then (select public.scope_contains(church_id, service_id, class_id))
         else public.store_shop_visible(shop_id) end)
);
drop policy if exists store_items_update on public.store_items;
create policy store_items_update on public.store_items for update using (
  (select public.module_visible('store')) and (
    case when shop_id is null then (select public.scope_contains(church_id, service_id, class_id))
         else public.store_shop_visible(shop_id) end)
) with check (
  (select public.module_visible('store')) and (
    case when shop_id is null then (select public.scope_contains(church_id, service_id, class_id))
         else public.store_shop_visible(shop_id) end)
);
drop policy if exists store_items_delete on public.store_items;
create policy store_items_delete on public.store_items for delete using (
  (select public.module_visible('store')) and (
    case when shop_id is null then (select public.scope_contains(church_id, service_id, class_id))
         else public.store_shop_visible(shop_id) end)
);

-- the scanned-label lookup stays RLS-scoped (security invoker) — nothing to
-- change; the UI narrows the rows to the current shop.

-- ---------------------------------------------------------------------
-- 3. store_shop_stats — numbers for the shops list
-- ---------------------------------------------------------------------
create or replace function public.store_shop_stats(p_shop uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select case when not public.store_shop_visible(p_shop) then null else jsonb_build_object(
    'items',   (select count(*) from public.store_items i where i.shop_id = p_shop and i.is_active),
    'stock',   (select coalesce(sum(i.stock), 0) from public.store_items i where i.shop_id = p_shop and i.is_active),
    'pending', (select count(*) from public.store_requests r where r.shop_id = p_shop and r.status = 'pending'),
    'orders',  (select count(*) from public.store_orders o where o.shop_id = p_shop and o.status = 'completed'),
    'points',  (select coalesce(sum(o.total_points), 0) from public.store_orders o where o.shop_id = p_shop and o.status = 'completed')
  ) end
$$;
grant execute on function public.store_shop_stats(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- 4. store_checkout(p_enrollment, p_lines, p_note, p_shop) — the POS is
--    inside a shop: every line must belong to that shop
-- ---------------------------------------------------------------------
-- the 3-arg version would make 3-arg calls ambiguous → replace it
drop function if exists public.store_checkout(uuid, jsonb, text);
create or replace function public.store_checkout(
  p_enrollment uuid, p_lines jsonb, p_note text default null, p_shop uuid default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := p_shop; v_bad text;
begin
  if v_shop is null and p_lines is not null and jsonb_typeof(p_lines) = 'array' and jsonb_array_length(p_lines) > 0 then
    select it.shop_id into v_shop from public.store_items it
     where it.id = nullif(p_lines->0->>'item_id', '')::uuid;
  end if;
  if v_shop is not null then
    if not public.store_shop_visible(v_shop) then
      raise exception 'shop_not_found' using errcode = 'P0002';
    end if;
    select it.name into v_bad
      from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) x
      join public.store_items it on it.id = nullif(x->>'item_id', '')::uuid
     where it.shop_id is distinct from v_shop
     limit 1;
    if v_bad is not null then
      raise exception 'item_out_of_scope:%', v_bad using errcode = 'P0001';
    end if;
  end if;
  return public.store_checkout_internal(p_enrollment, p_lines, p_note, v_shop, null, 'pos');
end $$;
grant execute on function public.store_checkout(uuid, jsonb, text, uuid) to authenticated;


-- #####################################################################
-- ##  20261003120000_unified_person_accounts.sql
-- #####################################################################

-- =====================================================================
-- 20261003120000 — ONE PERSON · ONE CODE · ONE PASSWORD · MANY ACCOUNTS
--   (حساب واحد للشخص — خادم · مخدوم · كاهن — وتبديل الحساب بلا خروج)
--
-- Before this migration the SAME code could carry THREE different
-- passwords: the servant one in Supabase Auth, the child one in
-- `person_credentials`, the priest one in `priests.password_hash`.
-- Signing up a second time with the same code was refused.
--
-- Now:
--   1. `person_credentials` is THE password of the person. Every path that
--      sets a password writes it there (and mirrors it to `priests` for the
--      legacy priest_login; the servant Auth account is synced by the server
--      route /api/account/sync-password with the service role — the DB
--      cannot touch Supabase Auth).
--   2. `person_accounts(person)` lists the accounts (kinds) of a person
--      without duplicates: servant (with role / status / places), child
--      (classes), priest (church / title / status).
--   3. Signup «as another kind» for an existing code = ADD an enrollment to
--      the same person after proving the EXISTING password
--      (`person_verify_password`). The wizard RPCs accept the current
--      password instead of inventing a second one.
--   4. Switching accounts WITHOUT signing out: `account_switch` verifies the
--      current session (child token / priest token / servant JWT) and mints
--      the target session. For the servant target it issues a one-time
--      SWITCH TICKET that the server exchanges for an Auth session
--      (`account_switch_tickets`).
--
-- Idempotent: create or replace / if not exists everywhere.
-- =====================================================================

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------
-- 0. person_credentials — who set it & from where (audit only)
-- ---------------------------------------------------------------------
alter table public.person_credentials add column if not exists source text;
comment on column public.person_credentials.source is
  'آخر مصدر ضبط كلمة المرور: child_signup · servant_signup · priest_signup · admin · self · migration';

-- ---------------------------------------------------------------------
-- 1. Back-fill — a priest whose person has no credentials yet: his priest
--    password becomes the person's password. (Servant Auth passwords cannot
--    be read; the owner may re-sync them from the UI — see README.)
-- ---------------------------------------------------------------------
insert into public.person_credentials (person_id, password_hash, source)
select pr.person_id, pr.password_hash, 'migration'
  from public.priests pr
 where pr.password_hash is not null
   and not exists (select 1 from public.person_credentials c where c.person_id = pr.person_id)
on conflict (person_id) do nothing;

-- and the other direction: a priest row keeps the SAME hash as the person
update public.priests pr
   set password_hash = c.password_hash
  from public.person_credentials c
 where c.person_id = pr.person_id
   and pr.password_hash is distinct from c.password_hash;

-- ---------------------------------------------------------------------
-- 2. The ONE write path for the password + the verifier
-- ---------------------------------------------------------------------
create or replace function public.person_set_password_hash(p_person uuid, p_hash text, p_source text default null, p_set_by uuid default null)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if p_person is null or coalesce(p_hash, '') = '' then return; end if;
  insert into public.person_credentials (person_id, password_hash, set_by, source)
  values (p_person, p_hash, p_set_by, p_source)
  on conflict (person_id) do update
    set password_hash = excluded.password_hash,
        set_by = coalesce(excluded.set_by, public.person_credentials.set_by),
        source = excluded.source,
        updated_at = now();
  -- mirror: the priest row (legacy column still read by priest_login)
  update public.priests set password_hash = p_hash, updated_at = now()
   where person_id = p_person and password_hash is distinct from p_hash;
end $$;
revoke all on function public.person_set_password_hash(uuid, text, text, uuid) from public, anon, authenticated;

create or replace function public.person_set_password(p_person uuid, p_password text, p_source text default null, p_set_by uuid default null)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  perform public.person_set_password_hash(p_person, crypt(p_password, gen_salt('bf', 10)), p_source, p_set_by);
end $$;
revoke all on function public.person_set_password(uuid, text, text, uuid) from public, anon, authenticated;

-- true when the password matches the person's password (the DEFAULT
-- password 000000 applies while none was ever set — same rule as child_login)
create or replace function public.person_password_ok(p_person uuid, p_password text)
returns boolean language plpgsql stable security definer set search_path = public, extensions as $$
declare c public.person_credentials;
begin
  if p_person is null then return false; end if;
  select * into c from public.person_credentials where person_id = p_person;
  if not found then
    return coalesce(p_password, '') = public.default_password();
  end if;
  return coalesce(p_password, '') <> '' and c.password_hash = crypt(p_password, c.password_hash);
end $$;
revoke all on function public.person_password_ok(uuid, text) from public, anon, authenticated;

-- keep the priest mirror in sync when the credentials row changes by any path
create or replace function public.person_credentials_mirror_priest()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.priests set password_hash = new.password_hash, updated_at = now()
   where person_id = new.person_id and password_hash is distinct from new.password_hash;
  return new;
end $$;
drop trigger if exists trg_person_credentials_mirror_priest on public.person_credentials;
create trigger trg_person_credentials_mirror_priest
after insert or update of password_hash on public.person_credentials
for each row execute function public.person_credentials_mirror_priest();

-- a NEW priest row always carries the person's password when one exists
create or replace function public.priests_take_person_password()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_hash text;
begin
  select password_hash into v_hash from public.person_credentials where person_id = new.person_id;
  if v_hash is not null then
    new.password_hash := v_hash;
  elsif new.password_hash is not null then
    -- first password of the person = the one typed for the priest account
    insert into public.person_credentials (person_id, password_hash, source)
    values (new.person_id, new.password_hash, 'priest_signup')
    on conflict (person_id) do nothing;
  end if;
  return new;
end $$;
drop trigger if exists trg_priests_take_person_password on public.priests;
create trigger trg_priests_take_person_password
before insert on public.priests
for each row execute function public.priests_take_person_password();

-- ---------------------------------------------------------------------
-- 3. Existing RPCs now write through the ONE path
-- ---------------------------------------------------------------------
-- 3a. child self change (old + new) — same body as 0043, writes via helper
create or replace function public.child_change_password(p_token text, p_current text, p_new text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons;
begin
  p := public.child_portal_person(p_token);
  if length(coalesce(p_new, '')) < 6 then raise exception 'weak_password' using errcode = 'P0001'; end if;
  if not public.person_password_ok(p.id, p_current) then raise exception 'wrong_password' using errcode = 'P0010'; end if;
  perform public.person_set_password(p.id, p_new, 'self', null);
  delete from public.child_sessions where person_id = p.id and token_hash <> encode(digest(trim(p_token), 'sha256'), 'hex');
  delete from public.priest_sessions s using public.priests pr where pr.id = s.priest_id and pr.person_id = p.id;
end $$;
grant execute on function public.child_change_password(text, text, text) to anon, authenticated;

-- 3b. priest self change (old + new) → the PERSON password
create or replace function public.priest_change_password(p_token text, p_current text, p_new text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare pr public.priests;
begin
  pr := public.priest_portal_self(p_token);
  if length(coalesce(p_new, '')) < 6 then raise exception 'weak_password' using errcode = 'P0001'; end if;
  if not public.person_password_ok(pr.person_id, p_current) then raise exception 'wrong_password' using errcode = 'P0010'; end if;
  perform public.person_set_password(pr.person_id, p_new, 'self', null);
  delete from public.priest_sessions where priest_id = pr.id and token_hash <> encode(digest(trim(p_token), 'sha256'), 'hex');
  delete from public.child_sessions where person_id = pr.person_id;
end $$;
grant execute on function public.priest_change_password(text, text, text) to anon, authenticated;

-- 3c. a superior resets a child → the person password
create or replace function public.admin_set_child_password(p_person uuid, p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if not (public.is_owner() or public.can_access_person(p_person)
          or exists (select 1 from public.persons x where x.id = p_person and x.created_by = auth.uid())) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  perform public.person_set_password(p_person, p_password, 'admin', auth.uid());
  delete from public.child_sessions where person_id = p_person;
  delete from public.priest_sessions s using public.priests pr where pr.id = s.priest_id and pr.person_id = p_person;
end $$;
revoke all on function public.admin_set_child_password(uuid, text) from public, anon;
grant execute on function public.admin_set_child_password(uuid, text) to authenticated;

-- 3d. the owner resets a priest → the person password
create or replace function public.owner_set_priest_password(p_priest uuid, p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  select person_id into v_person from public.priests where id = p_priest;
  if v_person is null then raise exception 'not_found' using errcode = 'P0002'; end if;
  perform public.person_set_password(v_person, p_password, 'admin', auth.uid());
  delete from public.priest_sessions where priest_id = p_priest;
  delete from public.child_sessions where person_id = v_person;
end $$;
revoke all on function public.owner_set_priest_password(uuid, text) from public, anon;
grant execute on function public.owner_set_priest_password(uuid, text) to authenticated;

-- 3e. priest login — accepts the PERSON password (the mirror column is kept
--     in sync, but the credentials row is authoritative)
create or replace function public.priest_login(p_code text, p_password text, p_remember boolean default false, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons;
  pr public.priests;
  v_token text;
  v_exp timestamptz;
begin
  if nullif(trim(coalesce(p_code, '')), '') is null then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  if exists (select 1 from public.priest_requests r where r.code = trim(p_code) and r.status = 'pending') then
    raise exception 'pending_approval' using errcode = 'P0001';
  end if;
  select * into p from public.persons where national_id = trim(p_code);
  if not found then raise exception 'unknown_code' using errcode = 'P0002'; end if;
  select * into pr from public.priests where person_id = p.id;
  if not found then raise exception 'not_priest' using errcode = 'P0002'; end if;
  if not public.person_password_ok(p.id, p_password)
     and not (coalesce(p_password, '') <> '' and pr.password_hash = crypt(p_password, pr.password_hash)) then
    perform pg_sleep(0.25);
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  if pr.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
  if pr.status = 'rejected' then raise exception 'account_rejected' using errcode = 'P0001'; end if;
  if pr.status = 'suspended' then raise exception 'account_stopped' using errcode = 'P0001'; end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_exp := case when coalesce(p_remember, false) then now() + interval '90 days' else now() + interval '12 hours' end;
  insert into public.priest_sessions (priest_id, token_hash, remember, expires_at, user_agent)
  values (pr.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, false), v_exp, left(p_user_agent, 300));
  delete from public.priest_sessions where expires_at < now() - interval '1 day';
  perform set_config('app.priest_actor', pr.id::text, true);
  return jsonb_build_object('token', v_token, 'expires_at', v_exp, 'priest_id', pr.id, 'remember', coalesce(p_remember, false));
end $$;
grant execute on function public.priest_login(text, text, boolean, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. person_accounts(person) — every account of the person, no duplicates
-- ---------------------------------------------------------------------
create or replace function public.person_accounts(p_person uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_agg(a order by a->>'order') from (
      -- servant (one login account per person)
      select jsonb_build_object(
          'order', '1', 'kind', 'servant', 'id', s.id, 'status', s.status, 'role', s.role,
          'label', 'خادم',
          'places', (select coalesce(jsonb_agg(jsonb_build_object('church', ch.name, 'service', sv.name, 'class', cl.name)), '[]'::jsonb)
                       from (select s.church_id, s.service_id, s.class_id
                             union select x.church_id, x.service_id, x.class_id from public.servant_scopes x where x.servant_id = s.id) sc
                       left join public.churches ch on ch.id = sc.church_id
                       left join public.services sv on sv.id = sc.service_id
                       left join public.classes cl on cl.id = sc.class_id
                       where sc.church_id is not null)) a
        from public.servant_enrollments s where s.person_id = p_person
      union all
      -- child (ONE entry for all his classes)
      select jsonb_build_object(
          'order', '2', 'kind', 'child', 'id', p_person,
          'status', case when exists (select 1 from public.enrollments e where e.person_id = p_person and e.kind = 'child' and e.status = 'active') then 'active' else 'stopped' end,
          'label', 'مخدوم',
          'places', (select coalesce(jsonb_agg(jsonb_build_object('church', ch.name, 'service', sv.name, 'class', cl.name) order by ch.name, sv.name, cl.name), '[]'::jsonb)
                       from public.enrollments e
                       join public.churches ch on ch.id = e.church_id
                       join public.services sv on sv.id = e.service_id
                       join public.classes cl on cl.id = e.class_id
                      where e.person_id = p_person and e.kind = 'child'))
       where exists (select 1 from public.enrollments e where e.person_id = p_person and e.kind = 'child')
      union all
      -- priest
      select jsonb_build_object(
          'order', '3', 'kind', 'priest', 'id', pr.id, 'status', pr.status, 'title', pr.title,
          'label', 'كاهن',
          'places', jsonb_build_array(jsonb_build_object('church', ch.name, 'service', null, 'class', null)))
        from public.priests pr join public.churches ch on ch.id = pr.church_id
       where pr.person_id = p_person
    ) t(a)
  ), '[]'::jsonb)
$$;
revoke all on function public.person_accounts(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. Who am I (from ANY session) → person + accounts
--    p_kind: 'servant' (auth.uid()) · 'child' (child token) · 'priest' (priest token)
-- ---------------------------------------------------------------------
create or replace function public.session_person(p_kind text, p_token text default null)
returns uuid language plpgsql stable security definer set search_path = public, extensions as $$
declare v uuid; s public.child_sessions; ps public.priest_sessions;
begin
  if p_kind = 'servant' then
    if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
    select person_id into v from public.servant_enrollments where id = auth.uid();
    if v is null then raise exception 'not_found' using errcode = 'P0002'; end if;
    return v;
  elsif p_kind = 'child' then
    if p_token is null or length(trim(p_token)) < 20 then raise exception 'session_expired' using errcode = 'P0002'; end if;
    select * into s from public.child_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
    if not found or s.expires_at < now() then raise exception 'session_expired' using errcode = 'P0002'; end if;
    return s.person_id;
  elsif p_kind = 'priest' then
    if p_token is null or length(trim(p_token)) < 20 then raise exception 'session_expired' using errcode = 'P0002'; end if;
    select * into ps from public.priest_sessions where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex');
    if not found or ps.expires_at < now() then raise exception 'session_expired' using errcode = 'P0002'; end if;
    select person_id into v from public.priests where id = ps.priest_id;
    if v is null then raise exception 'session_expired' using errcode = 'P0002'; end if;
    return v;
  end if;
  raise exception 'invalid_kind' using errcode = '22023';
end $$;
revoke all on function public.session_person(text, text) from public, anon, authenticated;

create or replace function public.my_accounts(p_kind text, p_token text default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v uuid; p public.persons;
begin
  v := public.session_person(p_kind, p_token);
  select * into p from public.persons where id = v;
  return jsonb_build_object(
    'person', jsonb_build_object('id', p.id, 'name', p.name, 'code', p.national_id, 'image_url', p.image_url),
    'current', p_kind,
    'accounts', public.person_accounts(v));
end $$;
grant execute on function public.my_accounts(text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. SWITCH ACCOUNT — no sign-out, no password
-- ---------------------------------------------------------------------
create table if not exists public.account_switch_tickets (
  id           uuid primary key default gen_random_uuid(),
  person_id    uuid not null references public.persons(id) on delete cascade,
  servant_id   uuid not null references public.servant_enrollments(id) on delete cascade,
  ticket_hash  text not null unique,
  remember     boolean not null default true,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  used_at      timestamptz
);
comment on table public.account_switch_tickets is
  'تذاكر تبديل الحساب إلى حساب الخادم — تُستبدل مرة واحدة خلال دقيقتين بجلسة Supabase Auth عبر /api/account/switch';
alter table public.account_switch_tickets enable row level security;
revoke all on public.account_switch_tickets from anon, authenticated;

create or replace function public.account_switch(p_from_kind text, p_from_token text, p_to_kind text, p_remember boolean default true)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_person uuid;
  p public.persons;
  s public.servant_enrollments;
  pr public.priests;
  v_token text;
  v_exp timestamptz;
begin
  v_person := public.session_person(p_from_kind, p_from_token);
  select * into p from public.persons where id = v_person;
  v_exp := case when coalesce(p_remember, true) then now() + interval '90 days' else now() + interval '12 hours' end;

  if p_to_kind = 'child' then
    if not exists (select 1 from public.enrollments e where e.person_id = v_person and e.kind = 'child') then
      raise exception 'no_such_account' using errcode = 'P0002';
    end if;
    if not exists (select 1 from public.enrollments e where e.person_id = v_person and e.kind = 'child' and e.status = 'active') then
      raise exception 'account_stopped' using errcode = 'P0011';
    end if;
    v_token := encode(gen_random_bytes(32), 'hex');
    insert into public.child_sessions (person_id, token_hash, remember, expires_at, user_agent)
    values (v_person, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), v_exp, 'switch:' || p_from_kind);
    return jsonb_build_object('kind', 'child', 'token', v_token, 'expires_at', v_exp, 'person_id', v_person);

  elsif p_to_kind = 'priest' then
    select * into pr from public.priests where person_id = v_person;
    if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
    if pr.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
    if pr.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
    v_token := encode(gen_random_bytes(32), 'hex');
    insert into public.priest_sessions (priest_id, token_hash, remember, expires_at, user_agent)
    values (pr.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), v_exp, 'switch:' || p_from_kind);
    perform set_config('app.priest_actor', pr.id::text, true);
    return jsonb_build_object('kind', 'priest', 'token', v_token, 'expires_at', v_exp, 'priest_id', pr.id);

  elsif p_to_kind = 'servant' then
    select * into s from public.servant_enrollments where person_id = v_person;
    if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
    if s.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
    if s.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
    -- one-time ticket, 2 minutes, exchanged by the server for an Auth session
    v_token := encode(gen_random_bytes(32), 'hex');
    delete from public.account_switch_tickets where expires_at < now();
    insert into public.account_switch_tickets (person_id, servant_id, ticket_hash, remember, expires_at)
    values (v_person, s.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), now() + interval '2 minutes');
    return jsonb_build_object('kind', 'servant', 'ticket', v_token, 'servant_id', s.id, 'code', p.national_id);
  end if;
  raise exception 'invalid_kind' using errcode = '22023';
end $$;
grant execute on function public.account_switch(text, text, text, boolean) to anon, authenticated;

-- the server (service role) redeems the ticket exactly once
create or replace function public.account_switch_redeem(p_ticket text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare t public.account_switch_tickets; s public.servant_enrollments;
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_ticket is null or length(trim(p_ticket)) < 20 then raise exception 'invalid_ticket' using errcode = 'P0001'; end if;
  select * into t from public.account_switch_tickets where ticket_hash = encode(digest(trim(p_ticket), 'sha256'), 'hex');
  if not found or t.used_at is not null or t.expires_at < now() then raise exception 'invalid_ticket' using errcode = 'P0001'; end if;
  update public.account_switch_tickets set used_at = now() where id = t.id;
  select * into s from public.servant_enrollments where id = t.servant_id;
  if not found or s.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
  return jsonb_build_object('servant_id', s.id, 'user_id', s.user_id, 'remember', t.remember, 'person_id', t.person_id);
end $$;
revoke all on function public.account_switch_redeem(text) from public, anon, authenticated;
grant execute on function public.account_switch_redeem(text) to service_role;

-- ---------------------------------------------------------------------
-- 7. SIGNUP as another kind for an EXISTING code
-- ---------------------------------------------------------------------
-- 7a. One lookup for every wizard: does the code already belong to a person
--     with an account, and which kinds? The wizard then asks for the
--     EXISTING password instead of a new one.
create or replace function public.account_code_lookup(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    when exists (select 1 from public.families f where f.code = trim(p_code)) then jsonb_build_object('family', true, 'exists', false)
    else coalesce((
      select jsonb_build_object(
        'exists', true, 'family', false,
        'name', p.name, 'image_url', p.image_url,
        'has_password', exists (select 1 from public.person_credentials c where c.person_id = p.id),
        'is_servant', exists (select 1 from public.servant_enrollments s where s.person_id = p.id),
        'servant_status', (select s.status::text from public.servant_enrollments s where s.person_id = p.id limit 1),
        'is_child', exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child'),
        'is_priest', exists (select 1 from public.priests pr where pr.person_id = p.id),
        'priest_status', (select pr.status from public.priests pr where pr.person_id = p.id limit 1),
        'child_pending', exists (select 1 from public.child_join_requests r where r.code = p.national_id and r.status = 'pending'),
        'priest_pending', exists (select 1 from public.priest_requests r where r.code = p.national_id and r.status = 'pending'),
        'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id)
                    or exists (select 1 from public.priests pr where pr.person_id = p.id)
                    or exists (select 1 from public.person_credentials c where c.person_id = p.id)
      ) from public.persons p where p.national_id = trim(p_code) limit 1),
      jsonb_build_object('exists', false, 'family', false,
        'child_pending', exists (select 1 from public.child_join_requests r where r.code = trim(p_code) and r.status = 'pending'),
        'priest_pending', exists (select 1 from public.priest_requests r where r.code = trim(p_code) and r.status = 'pending')))
  end
$$;
grant execute on function public.account_code_lookup(text) to anon, authenticated;

-- 7b. prove the existing password of a code (anonymous — rate-limited by
--     the pg_sleep; returns true/false only, never the person)
create or replace function public.person_verify_password(p_code text, p_password text)
returns boolean language plpgsql volatile security definer set search_path = public, extensions as $$
declare v uuid; ok boolean;
begin
  select id into v from public.persons where national_id = trim(coalesce(p_code, ''));
  if v is null then return false; end if;
  -- an account must exist for the default-password rule to apply
  if not exists (select 1 from public.person_credentials c where c.person_id = v)
     and not exists (select 1 from public.enrollments e where e.person_id = v and e.kind = 'child') then
    return false;
  end if;
  ok := public.person_password_ok(v, p_password);
  if not ok then perform pg_sleep(0.25); end if;
  return ok;
end $$;
grant execute on function public.person_verify_password(text, text) to anon, authenticated;

-- 7c. child signup for a code that already has an account (servant / priest):
--     the EXISTING password is required; the request is created as usual and
--     keeps the person's hash (so approval never overwrites it).
create or replace function public.child_signup(
  p_code text, p_name text, p_password text,
  p_gender text default null, p_birthdate date default null, p_phone text default null,
  p_address text default null, p_notes text default null, p_image_url text default null,
  p_church uuid default null, p_service uuid default null, p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid;
  v_person public.persons;
  v_hash text;
begin
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if p_church is null then raise exception 'church_required' using errcode = '22023'; end if;
  if p_service is not null and not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and (p_service is null
      or not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  if exists (select 1 from public.families f where f.code = v_code) then raise exception 'code_is_family' using errcode = '23505'; end if;
  if exists (select 1 from public.child_join_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;

  select * into v_person from public.persons where national_id = v_code;
  if found then
    if exists (select 1 from public.person_credentials c where c.person_id = v_person.id) then
      -- already a CHILD account with a password → log in instead (0042 rule)
      if exists (select 1 from public.enrollments e where e.person_id = v_person.id and e.kind = 'child') then
        raise exception 'already_registered' using errcode = '23505';
      end if;
      -- another kind of account (servant / priest) → the SAME password is required
      if not public.person_password_ok(v_person.id, p_password) then
        perform pg_sleep(0.25);
        raise exception 'wrong_password' using errcode = 'P0010';
      end if;
      select password_hash into v_hash from public.person_credentials where person_id = v_person.id;
    end if;
    -- no password yet (a child added by a servant, or a pre-migration servant /
    -- priest account): the typed password becomes the person's password on approval
  end if;
  v_hash := coalesce(v_hash, crypt(p_password, gen_salt('bf', 10)));

  insert into public.child_join_requests
    (code, name, gender, birthdate, phone, address, notes, image_url, password_hash, church_id, service_id, class_id)
  values
    (v_code, trim(p_name), p_gender, p_birthdate,
     nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
     nullif(trim(coalesce(p_notes, '')), ''), p_image_url, v_hash, p_church, p_service, p_class)
  returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'code', v_code, 'linked', v_person.id is not null);
end $$;
grant execute on function public.child_signup(text, text, text, text, date, text, text, text, text, uuid, uuid, uuid) to anon, authenticated;

-- 7d. approval of a child request keeps the person's EXISTING password
create or replace function public.review_child_join_request(
  p_request uuid, p_approve boolean, p_note text default null,
  p_church uuid default null, p_service uuid default null, p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  r public.child_join_requests;
  v_church uuid; v_service uuid; v_class uuid;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_enr uuid;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  select * into r from public.child_join_requests where id = p_request;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
  if not (public.is_owner() or (r.church_id is not null and public.can_access(r.church_id, r.service_id, r.class_id))) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not p_approve then
    update public.child_join_requests
       set status = 'rejected', decision_note = nullif(trim(coalesce(p_note, '')), ''),
           decided_by = auth.uid(), decided_at = now()
     where id = r.id;
    return jsonb_build_object('status', 'rejected');
  end if;

  v_church := coalesce(p_church, r.church_id);
  v_service := coalesce(p_service, r.service_id);
  v_class := coalesce(p_class, r.class_id);
  if v_church is null or v_service is null or v_class is null then
    raise exception 'scope_required' using errcode = '22023';
  end if;
  if not exists (select 1 from public.classes c where c.id = v_class and c.service_id = v_service and c.church_id = v_church) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  if not public.can_access(v_church, v_service, v_class) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into v_person from public.persons where national_id = r.code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (r.code, r.name, r.gender, r.birthdate, r.phone, r.address, r.notes, r.image_url, auth.uid(), auth.uid())
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, r.gender),
      birthdate = coalesce(birthdate, r.birthdate),
      phone     = coalesce(phone, r.phone),
      address   = coalesce(address, r.address),
      notes     = coalesce(notes, r.notes),
      image_url = coalesce(image_url, r.image_url),
      edited_by = auth.uid(), edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  insert into public.enrollments (person_id, church_id, service_id, class_id, created_by, edited_by)
  values (v_person.id, v_church, v_service, v_class, auth.uid(), auth.uid())
  on conflict (person_id, class_id) do nothing
  returning id into v_enr;
  if v_enr is null then
    select id into v_enr from public.enrollments where person_id = v_person.id and class_id = v_class;
  end if;

  -- the person's password: set ONLY when he has none yet (one password per person)
  if not exists (select 1 from public.person_credentials c where c.person_id = v_person.id) then
    perform public.person_set_password_hash(v_person.id, r.password_hash, 'child_signup', auth.uid());
  end if;

  update public.child_join_requests
     set status = 'approved', decision_note = nullif(trim(coalesce(p_note, '')), ''),
         decided_by = auth.uid(), decided_at = now(),
         church_id = v_church, service_id = v_service, class_id = v_class,
         person_id = v_person.id, enrollment_id = v_enr
   where id = r.id;

  return jsonb_build_object('status', 'approved', 'person_id', v_person.id, 'person_created', v_created, 'enrollment_id', v_enr);
end $$;
revoke all on function public.review_child_join_request(uuid, boolean, text, uuid, uuid, uuid) from public, anon;
grant execute on function public.review_child_join_request(uuid, boolean, text, uuid, uuid, uuid) to authenticated;

-- 7e. priest signup for a code that already has an account → same password
create or replace function public.priest_signup(
  p_code text, p_name text, p_password text, p_church uuid,
  p_title text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid;
  v_person public.persons;
  v_hash text;
begin
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if p_church is null or not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  if exists (select 1 from public.families f where f.code = v_code) then raise exception 'code_is_family' using errcode = '23505'; end if;
  if exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id where p.national_id = v_code) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  if exists (select 1 from public.priest_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;

  select * into v_person from public.persons where national_id = v_code;
  if found and exists (select 1 from public.person_credentials c where c.person_id = v_person.id) then
    if not public.person_password_ok(v_person.id, p_password) then
      perform pg_sleep(0.25);
      raise exception 'wrong_password' using errcode = 'P0010';
    end if;
    select password_hash into v_hash from public.person_credentials where person_id = v_person.id;
  end if;
  v_hash := coalesce(v_hash, crypt(p_password, gen_salt('bf', 10)));

  insert into public.priest_requests (code, name, title, gender, birthdate, phone, address, notes, image_url, password_hash, church_id)
  values (v_code, trim(p_name), nullif(trim(coalesce(p_title, '')), ''), p_gender, p_birthdate,
          nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
          nullif(trim(coalesce(p_notes, '')), ''), p_image_url, v_hash, p_church)
  returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'code', v_code, 'linked', v_person.id is not null);
end $$;
grant execute on function public.priest_signup(text, text, text, uuid, text, text, date, text, text, text, text) to anon, authenticated;

-- (owner_review_priest_request / owner_add_priest insert into priests → the
--  BEFORE INSERT trigger adopts the person's password or seeds it — no change
--  to their bodies is needed.)

-- 7f. servant signup lookup — `has_account` now means «has a SERVANT
--     account» (unchanged meaning), plus the other kinds so the wizard can
--     ask for the existing password
create or replace function public.signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else coalesce(
      (select jsonb_build_object(
          'name', p.name, 'gender', p.gender, 'birthdate', p.birthdate,
          'phone', p.phone, 'address', p.address, 'image_url', p.image_url,
          'has_account', exists (select 1 from public.servant_enrollments s where s.person_id = p.id),
          'has_password', exists (select 1 from public.person_credentials c where c.person_id = p.id),
          'is_child', exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child'),
          'is_priest', exists (select 1 from public.priests pr where pr.person_id = p.id))
         from public.persons p where p.national_id = trim(p_code) limit 1),
      case when exists (select 1 from public.families f where f.code = trim(p_code))
           then jsonb_build_object('family', true) end)
  end
$$;
grant execute on function public.signup_lookup_code(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 8. Servant password changes (Auth side) are mirrored to the person by
--    the server routes with the service role — this is the helper they call.
--    p_hash: a bcrypt hash computed in the DB from the plain password.
-- ---------------------------------------------------------------------
create or replace function public.admin_mirror_servant_password(p_servant uuid, p_password text, p_source text default 'admin')
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid;
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select person_id into v_person from public.servant_enrollments where id = p_servant;
  if v_person is null then return; end if;
  perform public.person_set_password(v_person, p_password, p_source, null);
  delete from public.child_sessions where person_id = v_person;
  delete from public.priest_sessions s using public.priests pr where pr.id = s.priest_id and pr.person_id = v_person;
end $$;
revoke all on function public.admin_mirror_servant_password(uuid, text, text) from public, anon, authenticated;
grant execute on function public.admin_mirror_servant_password(uuid, text, text) to service_role;

-- the signed-in servant changed HIS OWN password in Auth (old + new) → mirror
-- Called after every successful servant login too (the Auth password just
-- proved itself) — a no-op when the person's password already matches, so
-- legacy accounts converge without kicking the other portals' sessions.
create or replace function public.servant_mirror_own_password(p_password text)
returns void language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select person_id into v_person from public.servant_enrollments where id = auth.uid();
  if v_person is null then return; end if;
  if exists (select 1 from public.person_credentials c where c.person_id = v_person)
     and public.person_password_ok(v_person, p_password) then
    return;
  end if;
  perform public.person_set_password(v_person, p_password, 'self', auth.uid());
  delete from public.child_sessions where person_id = v_person;
  delete from public.priest_sessions s using public.priests pr where pr.id = s.priest_id and pr.person_id = v_person;
end $$;
grant execute on function public.servant_mirror_own_password(text) to authenticated;

-- ---------------------------------------------------------------------
-- 9. The child / priest wizard lookups learn about the OTHER kinds
-- ---------------------------------------------------------------------
create or replace function public.child_signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'exists', exists (select 1 from public.persons p where p.national_id = trim(p_code)),
      'has_password', exists (select 1 from public.persons p join public.person_credentials c on c.person_id = p.id
                               where p.national_id = trim(p_code)),
      'is_child', exists (select 1 from public.persons p join public.enrollments e on e.person_id = p.id and e.kind = 'child'
                           where p.national_id = trim(p_code)),
      'is_servant', exists (select 1 from public.persons p join public.servant_enrollments s on s.person_id = p.id
                             where p.national_id = trim(p_code)),
      'is_priest', exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id
                            where p.national_id = trim(p_code)),
      'pending', exists (select 1 from public.child_join_requests r where r.code = trim(p_code) and r.status = 'pending'),
      'name', (select p.name from public.persons p where p.national_id = trim(p_code) limit 1),
      'family', exists (select 1 from public.families f where f.code = trim(p_code))
    )
  end
$$;
grant execute on function public.child_signup_lookup_code(text) to anon, authenticated;

create or replace function public.priest_signup_lookup_code(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when nullif(trim(p_code), '') is null then null
    else jsonb_build_object(
      'exists', exists (select 1 from public.persons p where p.national_id = trim(p_code)),
      'is_priest', exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id where p.national_id = trim(p_code)),
      'is_servant', exists (select 1 from public.persons p join public.servant_enrollments s on s.person_id = p.id where p.national_id = trim(p_code)),
      'is_child', exists (select 1 from public.persons p join public.enrollments e on e.person_id = p.id and e.kind = 'child' where p.national_id = trim(p_code)),
      'has_password', exists (select 1 from public.persons p join public.person_credentials c on c.person_id = p.id where p.national_id = trim(p_code)),
      'pending', exists (select 1 from public.priest_requests r where r.code = trim(p_code) and r.status = 'pending'),
      'family', exists (select 1 from public.families f where f.code = trim(p_code)),
      'name', (select p.name from public.persons p where p.national_id = trim(p_code) limit 1)
    )
  end
$$;
grant execute on function public.priest_signup_lookup_code(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 11. /api/account/sync-password — a child / priest changed the ONE password
--     in his portal; the server must push it to the servant Auth account.
--     Service role only: resolves the session, re-checks that `p_password`
--     IS the person's current password, returns the servant account id.
-- ---------------------------------------------------------------------
create or replace function public.account_servant_for_sync(p_kind text, p_token text, p_password text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_person uuid; v_servant uuid;
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  v_person := public.session_person(p_kind, p_token);
  if not public.person_password_ok(v_person, p_password) then raise exception 'wrong_password' using errcode = 'P0010'; end if;
  select id into v_servant from public.servant_enrollments where person_id = v_person;
  return jsonb_build_object('person_id', v_person, 'servant_id', v_servant);
end $$;
revoke all on function public.account_servant_for_sync(text, text, text) from public, anon, authenticated;
grant execute on function public.account_servant_for_sync(text, text, text) to service_role;

-- ---------------------------------------------------------------------
-- 12. /api/servants/create — the manager adds a servant whose code ALREADY
--     belongs to a person with a password (a child / priest): the new Auth
--     account is created with the SAME bcrypt hash (auth.admin.createUser
--     accepts password_hash), so the typed password is ignored and the
--     person keeps his one password. Service role only.
-- ---------------------------------------------------------------------
create or replace function public.admin_person_password_hash(p_code text)
returns text language plpgsql stable security definer set search_path = public as $$
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return (select c.password_hash from public.person_credentials c
            join public.persons p on p.id = c.person_id
           where p.national_id = trim(coalesce(p_code, '')) limit 1);
end $$;
revoke all on function public.admin_person_password_hash(text) from public, anon, authenticated;
grant execute on function public.admin_person_password_hash(text) to service_role;

-- (backup label of `account_switch_tickets` lives in src/lib/backup.ts)



-- #####################################################################
-- ##  20261004120000_single_login_enrollment_sessions_invites.sql
-- #####################################################################

-- =====================================================================
-- 20261004120000 — ONE LOGIN PAGE · ONE ENROLLMENT PER SESSION · INVITE-ONLY SIGNUP
--   (دخول واحد · الجلسة لتسجيل واحد · التسجيل بالدعوة فقط)
--
-- Builds on 20261003120000 (one person · one password · many accounts).
--
--   1. SESSION = ONE ENROLLMENT. A servant who serves in several places and
--      a child who is in several classes no longer see everything at once:
--        • child_sessions.enrollment_id — the class of THIS session; the
--          child profile RPC reads only that enrollment (null = legacy / all).
--        • servant_active_places — the place the servant chose for his
--          current login; my_scopes() returns ONLY that place when chosen.
--      person_accounts() lists ONE ROW PER ENROLLMENT (servant per place,
--      child per class, priest once) and account_switch() targets one.
--   2. ONE PRIEST ACCOUNT per person (unique(person_id) + explicit refusal)
--      — unlimited servant / child enrollments beside it.
--   3. ONE LOGIN: account_login(code, password) verifies the ONE password and
--      returns the person + his accounts; the client picks (or prompts when
--      several) and mints the session via account_session_from_login.
--   4. INVITE-ONLY SIGNUP: signup_invites (kind · scope · expiry · max uses)
--      are created from the app; the three wizards need ?invite=<token> and
--      the signup RPCs verify + consume it.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. child_sessions.enrollment_id — the class of this session
-- ---------------------------------------------------------------------
alter table public.child_sessions add column if not exists enrollment_id uuid references public.enrollments(id) on delete cascade;
create index if not exists idx_child_sessions_enrollment on public.child_sessions(enrollment_id);
comment on column public.child_sessions.enrollment_id is 'التسجيل (الفصل) الذي تعمل عليه هذه الجلسة — null = كل الفصول (جلسات قديمة)';

create or replace function public.child_session_enrollment(p_token text)
returns uuid language sql stable security definer set search_path = public, extensions as $$
  select s.enrollment_id from public.child_sessions s
   where s.token_hash = encode(digest(trim(coalesce(p_token, '')), 'sha256'), 'hex')
$$;
revoke all on function public.child_session_enrollment(text) from public, anon, authenticated;

create or replace function public.child_portal_profile(p_national_id text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare p public.persons; enr jsonb; v_enr uuid;
begin
  p := public.child_portal_person(p_national_id);
  v_enr := public.child_session_enrollment(p_national_id);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
           'attendance_count', e.attendance_count, 'points', e.points, 'created_at', e.created_at, 'status', e.status,
           'church_name', ch.name, 'church_logo', ch.logo_url,
           'service_name', sv.name, 'service_photo', sv.photo_url,
           'class_name', cl.name, 'class_photo', cl.photo_url
         ) order by e.created_at), '[]'::jsonb)
    into enr
    from public.enrollments e
    join public.churches ch on ch.id = e.church_id
    join public.services sv on sv.id = e.service_id
    join public.classes  cl on cl.id = e.class_id
   where e.person_id = p.id and e.kind = 'child'
     and (v_enr is null or e.id = v_enr);
  return jsonb_build_object(
    'person', jsonb_build_object(
      'id', p.id, 'national_id', p.national_id, 'name', p.name, 'birthdate', p.birthdate, 'gender', p.gender,
      'phone', p.phone, 'address', p.address, 'image_url', p.image_url, 'created_at', p.created_at),
    'enrollments', enr,
    'session_enrollment_id', v_enr,
    'other_enrollments', (select count(*) from public.enrollments e
                           where e.person_id = p.id and e.kind = 'child' and v_enr is not null and e.id <> v_enr));
end $$;
grant execute on function public.child_portal_profile(text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 2. servant_active_places — the place of the servant's current login
-- ---------------------------------------------------------------------
create table if not exists public.servant_active_places (
  servant_id  uuid primary key references public.servant_enrollments(id) on delete cascade,
  church_id   uuid references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  updated_at  timestamptz not null default now()
);
comment on table public.servant_active_places is
  'المكان الذي اختاره الخادم لجلسته الحالية (من بين أماكن خدمته) — my_scopes() يُرجع هذا المكان فقط';
alter table public.servant_active_places enable row level security;
revoke all on public.servant_active_places from anon, authenticated;
grant select on public.servant_active_places to authenticated;
drop policy if exists servant_active_places_self on public.servant_active_places;
create policy servant_active_places_self on public.servant_active_places for select to authenticated using (servant_id = auth.uid());
alter table public.servant_active_places replica identity full;
do $$ begin
  alter publication supabase_realtime add table public.servant_active_places;
exception when duplicate_object then null; end $$;

create or replace function public.servant_places(p_servant uuid)
returns table (church_id uuid, service_id uuid, class_id uuid, is_primary boolean)
language sql stable security definer set search_path = public as $$
  select s.church_id, s.service_id, s.class_id, true
    from public.servant_enrollments s where s.id = p_servant and s.church_id is not null
  union
  select x.church_id, x.service_id, x.class_id, false
    from public.servant_scopes x where x.servant_id = p_servant
$$;
revoke all on function public.servant_places(uuid) from public, anon;
grant execute on function public.servant_places(uuid) to authenticated;

create or replace function public.servant_set_active_place(p_church uuid, p_service uuid default null, p_class uuid default null)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if p_church is null then
    delete from public.servant_active_places where servant_id = auth.uid();
    return;
  end if;
  if not exists (select 1 from public.servant_places(auth.uid()) p
                  where p.church_id = p_church and p.service_id is not distinct from p_service and p.class_id is not distinct from p_class) then
    raise exception 'scope_not_allowed' using errcode = '42501';
  end if;
  insert into public.servant_active_places (servant_id, church_id, service_id, class_id)
  values (auth.uid(), p_church, p_service, p_class)
  on conflict (servant_id) do update
    set church_id = excluded.church_id, service_id = excluded.service_id, class_id = excluded.class_id, updated_at = now();
end $$;
grant execute on function public.servant_set_active_place(uuid, uuid, uuid) to authenticated;

-- my_scopes(): ONLY the active place when one is chosen (and still his)
create or replace function public.my_scopes()
returns table (role public.app_role, church_id uuid, service_id uuid, class_id uuid)
language sql stable security definer set search_path = public as $$
  with me as (select s.id, s.role, s.church_id, s.service_id, s.class_id
                from public.servant_enrollments s where s.id = auth.uid() and s.status = 'approved'),
  active as (
    select a.church_id, a.service_id, a.class_id
      from public.servant_active_places a join me on me.id = a.servant_id
     where exists (select 1 from public.servant_places(me.id) p
                    where p.church_id = a.church_id and p.service_id is not distinct from a.service_id and p.class_id is not distinct from a.class_id))
  select me.role, active.church_id, active.service_id, active.class_id from me, active
  union all
  select me.role, me.church_id, me.service_id, me.class_id from me where not exists (select 1 from active)
  union all
  select me.role, x.church_id, x.service_id, x.class_id
    from me join public.servant_scopes x on x.servant_id = me.id
   where not exists (select 1 from active)
$$;
grant execute on function public.my_scopes() to authenticated, anon;

-- single-row helper used by my_role() and legacy code → the first active scope
create or replace function public.my_scope()
returns table (role public.app_role, church_id uuid, service_id uuid, class_id uuid)
language sql stable security definer set search_path = public as $$
  select role, church_id, service_id, class_id from public.my_scopes() limit 1
$$;

-- the two predicates inlined by the ~30 policies now follow my_scopes()
create or replace function public.extra_scope_visible(p_church uuid, p_service uuid, p_class uuid, s_role public.app_role)
returns boolean language sql stable security definer set search_path = public cost 500 as $$
  select s_role is not null and s_role <> 'owner' and exists (
    select 1 from public.my_scopes() x
     where case s_role
         when 'church_manager' then p_church = x.church_id
         when 'service_manager' then (x.service_id is null and p_church = x.church_id) or p_service = x.service_id
         when 'class_servant' then
           (x.class_id is null and ((x.service_id is null and p_church = x.church_id) or p_service = x.service_id))
           or p_class = x.class_id
         else false
       end)
$$;
grant execute on function public.extra_scope_visible(uuid, uuid, uuid, public.app_role) to authenticated, anon;

-- enrollment_visible keeps the 0045 shape: the fast check on the caller's
-- (now ACTIVE) scope passed by the policy, then the rest of my_scopes().
create or replace function public.enrollment_visible(p_church uuid, p_service uuid, p_class uuid,
  s_role public.app_role, s_church uuid, s_service uuid, s_class uuid)
returns boolean language sql stable as $$
  select coalesce(case s_role
    when 'owner' then true
    when 'church_manager' then p_church = s_church
    when 'service_manager' then (s_service is null and p_church = s_church) or p_service = s_service
    when 'class_servant' then
      (s_class is null and ((s_service is null and p_church = s_church) or p_service = s_service))
      or p_class = s_class
    else false
  end, false)
  or public.extra_scope_visible(p_church, p_service, p_class, s_role)
$$;

-- ---------------------------------------------------------------------
-- 3. person_accounts — ONE ROW PER ENROLLMENT (servant per place · child per
--    class · priest once). `enrollment_id` identifies the row to switch to.
-- ---------------------------------------------------------------------
create or replace function public.person_accounts(p_person uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_agg(a order by a->>'order', a->>'label2') from (
      select jsonb_build_object(
          'order', '1', 'kind', 'servant', 'id', s.id, 'status', s.status, 'role', s.role, 'label', 'خادم',
          'enrollment_id', s.id,
          'church_id', pl.church_id, 'service_id', pl.service_id, 'class_id', pl.class_id,
          'is_primary', coalesce(pl.is_primary, true),
          'label2', coalesce(ch.name, '') || coalesce(' ← ' || sv.name, '') || coalesce(' ← ' || cl.name, ''),
          'places', case when pl.church_id is null then '[]'::jsonb
                         else jsonb_build_array(jsonb_build_object('church', ch.name, 'service', sv.name, 'class', cl.name)) end) a
        from public.servant_enrollments s
        left join lateral public.servant_places(s.id) pl on true
        left join public.churches ch on ch.id = pl.church_id
        left join public.services sv on sv.id = pl.service_id
        left join public.classes cl on cl.id = pl.class_id
       where s.person_id = p_person
      union all
      select jsonb_build_object(
          'order', '2', 'kind', 'child', 'id', e.id, 'enrollment_id', e.id, 'status', e.status, 'label', 'مخدوم',
          'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
          'label2', ch.name || ' ← ' || sv.name || ' ← ' || cl.name,
          'places', jsonb_build_array(jsonb_build_object('church', ch.name, 'service', sv.name, 'class', cl.name)))
        from public.enrollments e
        join public.churches ch on ch.id = e.church_id
        join public.services sv on sv.id = e.service_id
        join public.classes cl on cl.id = e.class_id
       where e.person_id = p_person and e.kind = 'child'
      union all
      select jsonb_build_object(
          'order', '3', 'kind', 'priest', 'id', pr.id, 'enrollment_id', pr.id, 'status', pr.status, 'title', pr.title, 'label', 'كاهن',
          'church_id', pr.church_id, 'label2', ch.name,
          'places', jsonb_build_array(jsonb_build_object('church', ch.name, 'service', null, 'class', null)))
        from public.priests pr join public.churches ch on ch.id = pr.church_id
       where pr.person_id = p_person
    ) t(a)
  ), '[]'::jsonb)
$$;
revoke all on function public.person_accounts(uuid) from public, anon, authenticated;

create or replace function public.my_accounts(p_kind text, p_token text default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v uuid; p public.persons; v_cur uuid; v_place jsonb;
begin
  v := public.session_person(p_kind, p_token);
  select * into p from public.persons where id = v;
  if p_kind = 'child' then
    v_cur := public.child_session_enrollment(p_token);
  elsif p_kind = 'priest' then
    select pr.id into v_cur from public.priests pr where pr.person_id = v;
  else
    v_cur := auth.uid();
    select jsonb_build_object('church_id', a.church_id, 'service_id', a.service_id, 'class_id', a.class_id)
      into v_place from public.servant_active_places a where a.servant_id = auth.uid();
  end if;
  return jsonb_build_object(
    'person', jsonb_build_object('id', p.id, 'name', p.name, 'code', p.national_id, 'image_url', p.image_url),
    'current', p_kind, 'current_enrollment_id', v_cur, 'current_place', v_place,
    'accounts', public.person_accounts(v));
end $$;
grant execute on function public.my_accounts(text, text) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. Minting a session for ONE enrollment (shared by login + switch)
-- ---------------------------------------------------------------------
alter table public.account_switch_tickets add column if not exists church_id uuid;
alter table public.account_switch_tickets add column if not exists service_id uuid;
alter table public.account_switch_tickets add column if not exists class_id uuid;

create or replace function public.account_mint(
  p_person uuid, p_to_kind text, p_enrollment uuid, p_remember boolean, p_ua text,
  p_church uuid default null, p_service uuid default null, p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  p public.persons; s public.servant_enrollments; pr public.priests; e public.enrollments;
  v_token text; v_exp timestamptz;
begin
  select * into p from public.persons where id = p_person;
  v_exp := case when coalesce(p_remember, true) then now() + interval '90 days' else now() + interval '12 hours' end;

  if p_to_kind = 'child' then
    if p_enrollment is not null then
      select * into e from public.enrollments where id = p_enrollment and person_id = p_person and kind = 'child';
      if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
      if e.status <> 'active' then raise exception 'account_stopped' using errcode = 'P0011'; end if;
    else
      if not exists (select 1 from public.enrollments x where x.person_id = p_person and x.kind = 'child') then
        raise exception 'no_such_account' using errcode = 'P0002';
      end if;
      if not exists (select 1 from public.enrollments x where x.person_id = p_person and x.kind = 'child' and x.status = 'active') then
        raise exception 'account_stopped' using errcode = 'P0011';
      end if;
    end if;
    v_token := encode(gen_random_bytes(32), 'hex');
    insert into public.child_sessions (person_id, token_hash, remember, expires_at, user_agent, enrollment_id)
    values (p_person, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), v_exp, left(p_ua, 300), p_enrollment);
    return jsonb_build_object('kind', 'child', 'token', v_token, 'expires_at', v_exp, 'person_id', p_person, 'enrollment_id', p_enrollment);

  elsif p_to_kind = 'priest' then
    select * into pr from public.priests where person_id = p_person;
    if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
    if pr.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
    if pr.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
    v_token := encode(gen_random_bytes(32), 'hex');
    insert into public.priest_sessions (priest_id, token_hash, remember, expires_at, user_agent)
    values (pr.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), v_exp, left(p_ua, 300));
    perform set_config('app.priest_actor', pr.id::text, true);
    return jsonb_build_object('kind', 'priest', 'token', v_token, 'expires_at', v_exp, 'priest_id', pr.id);

  elsif p_to_kind = 'servant' then
    select * into s from public.servant_enrollments where person_id = p_person;
    if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
    if s.status = 'pending' then raise exception 'pending_approval' using errcode = 'P0001'; end if;
    if s.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
    if p_church is not null and not exists (select 1 from public.servant_places(s.id) x
         where x.church_id = p_church and x.service_id is not distinct from p_service and x.class_id is not distinct from p_class) then
      raise exception 'scope_not_allowed' using errcode = '42501';
    end if;
    v_token := encode(gen_random_bytes(32), 'hex');
    delete from public.account_switch_tickets where expires_at < now();
    insert into public.account_switch_tickets (person_id, servant_id, ticket_hash, remember, expires_at, church_id, service_id, class_id)
    values (p_person, s.id, encode(digest(v_token, 'sha256'), 'hex'), coalesce(p_remember, true), now() + interval '2 minutes',
            p_church, p_service, p_class);
    return jsonb_build_object('kind', 'servant', 'ticket', v_token, 'servant_id', s.id, 'code', p.national_id);
  end if;
  raise exception 'invalid_kind' using errcode = '22023';
end $$;
revoke all on function public.account_mint(uuid, text, uuid, boolean, text, uuid, uuid, uuid) from public, anon, authenticated;

-- redeem: the chosen place becomes the active one of the servant's login
create or replace function public.account_switch_redeem(p_ticket text)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare t public.account_switch_tickets; s public.servant_enrollments;
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_ticket is null or length(trim(p_ticket)) < 20 then raise exception 'invalid_ticket' using errcode = 'P0001'; end if;
  select * into t from public.account_switch_tickets where ticket_hash = encode(digest(trim(p_ticket), 'sha256'), 'hex');
  if not found or t.used_at is not null or t.expires_at < now() then raise exception 'invalid_ticket' using errcode = 'P0001'; end if;
  update public.account_switch_tickets set used_at = now() where id = t.id;
  select * into s from public.servant_enrollments where id = t.servant_id;
  if not found or s.status <> 'approved' then raise exception 'account_stopped' using errcode = 'P0001'; end if;
  if t.church_id is not null then
    insert into public.servant_active_places (servant_id, church_id, service_id, class_id)
    values (s.id, t.church_id, t.service_id, t.class_id)
    on conflict (servant_id) do update
      set church_id = excluded.church_id, service_id = excluded.service_id, class_id = excluded.class_id, updated_at = now();
  else
    delete from public.servant_active_places where servant_id = s.id;
  end if;
  return jsonb_build_object('servant_id', s.id, 'user_id', s.user_id, 'remember', t.remember, 'person_id', t.person_id);
end $$;
revoke all on function public.account_switch_redeem(text) from public, anon, authenticated;
grant execute on function public.account_switch_redeem(text) to service_role;

drop function if exists public.account_switch(text, text, text, boolean);
create or replace function public.account_switch(
  p_from_kind text, p_from_token text, p_to_kind text, p_remember boolean default true,
  p_enrollment uuid default null, p_church uuid default null, p_service uuid default null, p_class uuid default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
begin
  return public.account_mint(public.session_person(p_from_kind, p_from_token), p_to_kind, p_enrollment, p_remember,
                             'switch:' || p_from_kind, p_church, p_service, p_class);
end $$;
grant execute on function public.account_switch(text, text, text, boolean, uuid, uuid, uuid, uuid) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. ONE LOGIN — code + password → a 5-minute grant + the accounts
-- ---------------------------------------------------------------------
create table if not exists public.login_grants (
  id          uuid primary key default gen_random_uuid(),
  person_id   uuid not null references public.persons(id) on delete cascade,
  grant_hash  text not null unique,
  remember    boolean not null default false,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null
);
comment on table public.login_grants is 'إثبات دخول قصير العمر (5 دقائق) بين التحقق من كلمة المرور واختيار الحساب في صفحة الدخول الواحدة';
alter table public.login_grants enable row level security;
revoke all on public.login_grants from anon, authenticated;

create or replace function public.account_login(p_code text, p_password text, p_remember boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare p public.persons; v_grant text; acc jsonb;
begin
  if nullif(trim(coalesce(p_code, '')), '') is null then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  select * into p from public.persons where national_id = trim(p_code);
  if not found then perform pg_sleep(0.25); raise exception 'unknown_code' using errcode = 'P0002'; end if;
  acc := public.person_accounts(p.id);
  if jsonb_array_length(acc) = 0 then
    if exists (select 1 from public.child_join_requests r where r.code = p.national_id and r.status = 'pending')
       or exists (select 1 from public.priest_requests r where r.code = p.national_id and r.status = 'pending') then
      raise exception 'pending_approval' using errcode = 'P0001';
    end if;
    raise exception 'no_account' using errcode = 'P0002';
  end if;
  -- a servant / priest whose password was never mirrored (legacy): the
  -- client falls back to Supabase Auth and the mirror catches up
  if not exists (select 1 from public.person_credentials c where c.person_id = p.id)
     and not exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child') then
    raise exception 'password_unknown' using errcode = 'P0012';
  end if;
  if not public.person_password_ok(p.id, p_password) then
    perform pg_sleep(0.25);
    raise exception 'wrong_password' using errcode = 'P0010';
  end if;
  v_grant := encode(gen_random_bytes(32), 'hex');
  delete from public.login_grants where expires_at < now();
  insert into public.login_grants (person_id, grant_hash, remember, expires_at)
  values (p.id, encode(digest(v_grant, 'sha256'), 'hex'), coalesce(p_remember, false), now() + interval '5 minutes');
  return jsonb_build_object(
    'grant', v_grant,
    'person', jsonb_build_object('id', p.id, 'name', p.name, 'code', p.national_id, 'image_url', p.image_url),
    'accounts', acc);
end $$;
grant execute on function public.account_login(text, text, boolean) to anon, authenticated;

create or replace function public.account_session_from_login(
  p_grant text, p_kind text, p_enrollment uuid default null,
  p_church uuid default null, p_service uuid default null, p_class uuid default null, p_user_agent text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare g public.login_grants;
begin
  if p_grant is null or length(trim(p_grant)) < 20 then raise exception 'session_expired' using errcode = 'P0002'; end if;
  select * into g from public.login_grants where grant_hash = encode(digest(trim(p_grant), 'sha256'), 'hex');
  if not found or g.expires_at < now() then raise exception 'session_expired' using errcode = 'P0002'; end if;
  delete from public.login_grants where id = g.id;
  return public.account_mint(g.person_id, p_kind, p_enrollment, g.remember, p_user_agent, p_church, p_service, p_class);
end $$;
grant execute on function public.account_session_from_login(text, text, uuid, uuid, uuid, uuid, text) to anon, authenticated;


-- ---------------------------------------------------------------------
-- 6. INVITE-ONLY SIGNUP — دعوات التسجيل
-- ---------------------------------------------------------------------
create table if not exists public.signup_invites (
  id          uuid primary key default gen_random_uuid(),
  kind        text not null check (kind in ('servant', 'child', 'priest')),
  token_hash  text not null unique,
  church_id   uuid references public.churches(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  class_id    uuid references public.classes(id) on delete cascade,
  created_by  uuid references public.servant_enrollments(id) on delete set null,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null,
  max_uses    integer,
  uses        integer not null default 0,
  revoked_at  timestamptz,
  note        text
);
create index if not exists idx_signup_invites_creator on public.signup_invites(created_by, created_at desc);
comment on table public.signup_invites is
  'دعوات التسجيل — التسجيل (خادم · مخدوم · كاهن) لا يُفتح إلا برابط/QR يحمل دعوة صالحة أنشأها مسؤول من التطبيق';
alter table public.signup_invites enable row level security;
revoke all on public.signup_invites from anon, authenticated;
grant select (id, kind, church_id, service_id, class_id, created_by, created_at, expires_at, max_uses, uses, revoked_at, note),
      update (revoked_at) on public.signup_invites to authenticated;
drop policy if exists signup_invites_mine on public.signup_invites;
create policy signup_invites_mine on public.signup_invites for select to authenticated
  using (created_by = auth.uid() or (select public.is_owner()));
drop policy if exists signup_invites_revoke on public.signup_invites;
create policy signup_invites_revoke on public.signup_invites for update to authenticated
  using (created_by = auth.uid() or (select public.is_owner()));

-- who may invite: servant → owner / church manager / service manager (inside
-- scope) · child → anyone who can access the class · priest → OWNER only
create or replace function public.signup_invite_create(
  p_kind text, p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_days integer default 7, p_max_uses integer default null, p_note text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_role public.app_role := public.my_role(); v_token text; v_id uuid; v_exp timestamptz;
begin
  if v_role is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_kind not in ('servant', 'child', 'priest') then raise exception 'invalid_kind' using errcode = '22023'; end if;
  if p_kind = 'priest' and not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_kind = 'servant' and v_role = 'class_servant' then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_kind = 'child' then
    if p_church is null or p_service is null or p_class is null then raise exception 'scope_required' using errcode = '22023'; end if;
    if not public.can_access(p_church, p_service, p_class) then raise exception 'forbidden' using errcode = '42501'; end if;
  elsif p_kind = 'servant' and p_church is not null and not public.scope_contains(p_church, p_service, p_class) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_service is not null and not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  v_exp := now() + make_interval(days => greatest(1, least(coalesce(p_days, 7), 365)));
  v_token := encode(gen_random_bytes(18), 'hex');
  insert into public.signup_invites (kind, token_hash, church_id, service_id, class_id, created_by, expires_at, max_uses, note)
  values (p_kind, encode(digest(v_token, 'sha256'), 'hex'), p_church, p_service, p_class, auth.uid(), v_exp, p_max_uses, nullif(trim(coalesce(p_note, '')), ''))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'token', v_token, 'kind', p_kind, 'church_id', p_church, 'service_id', p_service, 'class_id', p_class, 'expires_at', v_exp);
end $$;
grant execute on function public.signup_invite_create(text, uuid, uuid, uuid, integer, integer, text) to authenticated;

create or replace function public.signup_invite_check(p_token text, p_kind text)
returns jsonb language sql stable security definer set search_path = public, extensions as $$
  select coalesce((
    select jsonb_build_object('valid', true, 'kind', i.kind, 'church_id', i.church_id, 'service_id', i.service_id, 'class_id', i.class_id,
                              'church_name', (select name from public.churches where id = i.church_id),
                              'service_name', (select name from public.services where id = i.service_id),
                              'class_name', (select name from public.classes where id = i.class_id),
                              'expires_at', i.expires_at)
      from public.signup_invites i
     where i.token_hash = encode(digest(trim(coalesce(p_token, '')), 'sha256'), 'hex')
       and i.kind = p_kind and i.revoked_at is null and i.expires_at > now()
       and (i.max_uses is null or i.uses < i.max_uses)
  ), jsonb_build_object('valid', false))
$$;
grant execute on function public.signup_invite_check(text, text) to anon, authenticated;

create or replace function public.signup_invite_consume(p_token text, p_kind text)
returns public.signup_invites language plpgsql volatile security definer set search_path = public, extensions as $$
declare i public.signup_invites;
begin
  if nullif(trim(coalesce(p_token, '')), '') is null then raise exception 'invite_required' using errcode = '42501'; end if;
  select * into i from public.signup_invites
   where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex') and kind = p_kind for update;
  if not found or i.revoked_at is not null or i.expires_at < now() or (i.max_uses is not null and i.uses >= i.max_uses) then
    raise exception 'invite_invalid' using errcode = '42501';
  end if;
  update public.signup_invites set uses = uses + 1 where id = i.id;
  return i;
end $$;
revoke all on function public.signup_invite_consume(text, text) from public, anon, authenticated;


-- 6a. child_signup — invite required; its scope wins. A person who is a child
--     in ANOTHER class may add this class (same password).
drop function if exists public.child_signup(text, text, text, text, date, text, text, text, text, uuid, uuid, uuid);
create or replace function public.child_signup(
  p_code text, p_name text, p_password text,
  p_gender text default null, p_birthdate date default null, p_phone text default null,
  p_address text default null, p_notes text default null, p_image_url text default null,
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_invite text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid; v_person public.persons; v_hash text; inv public.signup_invites;
  v_church uuid; v_service uuid; v_class uuid;
begin
  inv := public.signup_invite_consume(p_invite, 'child');
  v_church := coalesce(inv.church_id, p_church); v_service := coalesce(inv.service_id, p_service); v_class := coalesce(inv.class_id, p_class);
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_church is null then raise exception 'church_required' using errcode = '22023'; end if;
  if v_service is not null and not exists (select 1 from public.services s where s.id = v_service and s.church_id = v_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if v_class is not null and (v_service is null or not exists (select 1 from public.classes c where c.id = v_class and c.service_id = v_service)) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  if exists (select 1 from public.families f where f.code = v_code) then raise exception 'code_is_family' using errcode = '23505'; end if;
  if exists (select 1 from public.child_join_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;
  select * into v_person from public.persons where national_id = v_code;
  if found then
    if v_class is not null and exists (select 1 from public.enrollments e where e.person_id = v_person.id and e.class_id = v_class) then
      raise exception 'already_registered' using errcode = '23505';
    end if;
    if exists (select 1 from public.person_credentials c where c.person_id = v_person.id) then
      if not public.person_password_ok(v_person.id, p_password) then
        perform pg_sleep(0.25);
        raise exception 'wrong_password' using errcode = 'P0010';
      end if;
      select password_hash into v_hash from public.person_credentials where person_id = v_person.id;
    end if;
  end if;
  v_hash := coalesce(v_hash, crypt(p_password, gen_salt('bf', 10)));
  insert into public.child_join_requests
    (code, name, gender, birthdate, phone, address, notes, image_url, password_hash, church_id, service_id, class_id)
  values
    (v_code, trim(p_name), p_gender, p_birthdate,
     nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
     nullif(trim(coalesce(p_notes, '')), ''), p_image_url, v_hash, v_church, v_service, v_class)
  returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'code', v_code, 'linked', v_person.id is not null);
end $$;
grant execute on function public.child_signup(text, text, text, text, date, text, text, text, text, uuid, uuid, uuid, text) to anon, authenticated;

-- 6b. priest_signup — the OWNER's invite; ONE priest account per person
drop function if exists public.priest_signup(text, text, text, uuid, text, text, date, text, text, text, text);
create or replace function public.priest_signup(
  p_code text, p_name text, p_password text, p_church uuid,
  p_title text default null, p_gender text default null, p_birthdate date default null,
  p_phone text default null, p_address text default null, p_notes text default null, p_image_url text default null,
  p_invite text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_code text := nullif(trim(coalesce(p_code, '')), '');
  v_id uuid; v_person public.persons; v_hash text; inv public.signup_invites; v_church uuid;
begin
  inv := public.signup_invite_consume(p_invite, 'priest');
  v_church := coalesce(inv.church_id, p_church);
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if length(coalesce(p_password, '')) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_church is null or not exists (select 1 from public.churches c where c.id = v_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  if exists (select 1 from public.families f where f.code = v_code) then raise exception 'code_is_family' using errcode = '23505'; end if;
  if exists (select 1 from public.persons p join public.priests pr on pr.person_id = p.id where p.national_id = v_code) then
    raise exception 'already_registered' using errcode = '23505';   -- ONE priest account per person
  end if;
  if exists (select 1 from public.priest_requests r where r.code = v_code and r.status = 'pending') then
    raise exception 'pending_exists' using errcode = '23505';
  end if;
  select * into v_person from public.persons where national_id = v_code;
  if found and exists (select 1 from public.person_credentials c where c.person_id = v_person.id) then
    if not public.person_password_ok(v_person.id, p_password) then
      perform pg_sleep(0.25);
      raise exception 'wrong_password' using errcode = 'P0010';
    end if;
    select password_hash into v_hash from public.person_credentials where person_id = v_person.id;
  end if;
  v_hash := coalesce(v_hash, crypt(p_password, gen_salt('bf', 10)));
  insert into public.priest_requests (code, name, title, gender, birthdate, phone, address, notes, image_url, password_hash, church_id)
  values (v_code, trim(p_name), nullif(trim(coalesce(p_title, '')), ''), p_gender, p_birthdate,
          nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_address, '')), ''),
          nullif(trim(coalesce(p_notes, '')), ''), p_image_url, v_hash, v_church)
  returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'code', v_code, 'linked', v_person.id is not null);
end $$;
grant execute on function public.priest_signup(text, text, text, uuid, text, text, date, text, text, text, text, text) to anon, authenticated;


-- 6c. servant_signup — invite required (the wizard checks it BEFORE auth.signUp
--     so no orphan Auth account is created; the RPC re-checks and consumes)
drop function if exists public.servant_signup(text, text, text, date, text, text, text, uuid, uuid, uuid, text, jsonb);
create or replace function public.servant_signup(
  p_code text,
  p_full_name text,
  p_gender text default null,
  p_birthdate date default null,
  p_phone text default null,
  p_address text default null,
  p_notes text default null,
  p_church uuid default null,
  p_service uuid default null,
  p_class uuid default null,
  p_image_url text default null,
  p_scopes jsonb default null,
  p_invite text default null
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_code text := nullif(trim(p_code), '');
  v_user_id text;
  v_person public.persons%rowtype;
  v_created boolean := false;
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_scopes jsonb;
  v jsonb; v_c uuid; v_s uuid; v_k uuid;
  v_i int := 0;
  inv public.signup_invites;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  inv := public.signup_invite_consume(p_invite, 'servant');
  if v_code is null then raise exception 'code_required' using errcode = '22023'; end if;
  if coalesce(trim(p_full_name), '') = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_phone is null then raise exception 'phone_required' using errcode = '22023'; end if;

  -- the list of places: p_scopes, or the legacy single scope
  v_scopes := case
    when p_scopes is not null and jsonb_typeof(p_scopes) = 'array' and jsonb_array_length(p_scopes) > 0 then p_scopes
    when p_church is not null then jsonb_build_array(jsonb_build_object('church_id', p_church, 'service_id', p_service, 'class_id', p_class))
    when inv.church_id is not null then jsonb_build_array(jsonb_build_object('church_id', inv.church_id, 'service_id', inv.service_id, 'class_id', inv.class_id))
    else '[]'::jsonb end;

  -- every chain must be consistent (all optional — the approver may set it)
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_c := nullif(v->>'church_id', '')::uuid; v_s := nullif(v->>'service_id', '')::uuid; v_k := nullif(v->>'class_id', '')::uuid;
    if v_c is null then raise exception 'church_required' using errcode = '22023'; end if;
    if v_s is not null and not exists (select 1 from public.services s where s.id = v_s and s.church_id = v_c) then
      raise exception 'service_not_in_church' using errcode = '22023';
    end if;
    if v_k is not null and (v_s is null or not exists (select 1 from public.classes c where c.id = v_k and c.service_id = v_s)) then
      raise exception 'class_not_in_service' using errcode = '22023';
    end if;
  end loop;
  -- primary = the first place
  v_c := nullif(v_scopes->0->>'church_id', '')::uuid;
  v_s := nullif(v_scopes->0->>'service_id', '')::uuid;
  v_k := nullif(v_scopes->0->>'class_id', '')::uuid;

  v_user_id := public.code_to_user_id(v_code);
  if exists (select 1 from public.servant_enrollments s where s.user_id = v_user_id and s.id <> v_uid) then
    raise exception 'code_taken' using errcode = '23505';
  end if;

  perform set_config('app.in_servant_signup', '1', true);
  insert into public.servant_enrollments (id, full_name, user_id, phone, role, status, church_id, service_id, class_id)
  values (v_uid, trim(p_full_name), v_user_id, v_phone, 'class_servant', 'pending', v_c, v_s, v_k)
  on conflict (id) do nothing;
  if not exists (select 1 from public.servant_enrollments s where s.id = v_uid and s.status = 'pending') then
    raise exception 'already_registered' using errcode = '23505';
  end if;

  select * into v_person from public.persons where national_id = v_code;
  if not found then
    insert into public.persons (national_id, name, gender, birthdate, phone, address, notes, image_url, created_by, edited_by)
    values (v_code, trim(p_full_name), p_gender, p_birthdate, v_phone,
            nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_notes, '')), ''),
            p_image_url, v_uid, v_uid)
    returning * into v_person;
    v_created := true;
  else
    update public.persons set
      gender    = coalesce(gender, p_gender),
      birthdate = coalesce(birthdate, p_birthdate),
      phone     = coalesce(phone, v_phone),
      address   = coalesce(address, nullif(trim(coalesce(p_address, '')), '')),
      notes     = coalesce(notes, nullif(trim(coalesce(p_notes, '')), '')),
      image_url = coalesce(image_url, p_image_url),
      edited_by = v_uid, edited_at = now()
    where id = v_person.id
    returning * into v_person;
  end if;

  update public.servant_enrollments set
    person_id  = v_person.id,
    full_name  = v_person.name,
    user_id    = v_user_id,
    phone      = coalesce(v_person.phone, v_phone),
    church_id  = v_c,
    service_id = v_s,
    class_id   = v_k,
    photo_url  = v_person.image_url,
    updated_at = now()
  where id = v_uid and status = 'pending';

  -- the other requested places (re-running the signup refreshes them)
  delete from public.servant_scopes where servant_id = v_uid;
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_i := v_i + 1;
    if v_i = 1 then continue; end if;
    insert into public.servant_scopes (servant_id, church_id, service_id, class_id, created_by)
    values (v_uid, nullif(v->>'church_id', '')::uuid, nullif(v->>'service_id', '')::uuid, nullif(v->>'class_id', '')::uuid, v_uid)
    on conflict do nothing;
  end loop;

  perform set_config('app.in_servant_signup', '0', true);
  return jsonb_build_object('person_id', v_person.id, 'person_created', v_created,
                            'national_id', v_person.national_id, 'user_id', v_user_id,
                            'scopes', jsonb_array_length(v_scopes));
end $$;
grant execute on function public.servant_signup(text, text, text, date, text, text, text, uuid, uuid, uuid, text, jsonb, text) to authenticated;



-- #####################################################################
-- ##  20261005120000_person_enrollment_kinds_merge.sql
-- #####################################################################

-- =====================================================================
-- إدارة الأفراد — enrollment KINDS · add any kind · MERGE two persons
--
-- 1. owner_persons_page / owner_persons_counts learn about the PRIEST
--    account (`priest` jsonb) and the kind filter accepts 'priest'.
--    'child' now means «has ≥ 1 child enrollment» (not «is not a servant»).
-- 2. owner_add_priest_for_person — add a PRIEST account to an EXISTING
--    person from إدارة الأفراد (the child kind goes through
--    owner_bulk_enroll, the servant kind through POST /api/servants/create
--    → admin_add_servant with the person's code).
-- 3. owner_merge_persons(keep, remove, fields) — TWO persons rows that are
--    really ONE human (e.g. a servant account registered under one code and
--    a child enrollment under another): every row that points at `remove`
--    is re-pointed at `keep` (enrollments — same-class pairs are merged
--    with their counters and logs —, servant account, priest account,
--    confessors, families, store, exams, …), the owner CHOOSES the value of
--    every identity field (name · gender · birthdate · phone · address ·
--    notes · photo · code) and `remove` is deleted. Refused when both
--    persons own a servant account or both own a priest account.
--
-- Everything is owner-only. Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. owner_persons_page — + priest · kind 'priest' · child = has child row
-- ---------------------------------------------------------------------
drop function if exists public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer);
create or replace function public.owner_persons_page(
  p_search      text default null,
  p_scope_mode  text default 'all',
  p_church      uuid default null,
  p_service     uuid default null,
  p_class       uuid default null,
  p_gender      text default null,
  p_kind        text default 'all',
  p_limit       integer default 100,
  p_offset      integer default 0
) returns table (
  id            uuid,
  national_id   text,
  name          text,
  birthdate     date,
  gender        text,
  phone         text,
  address       text,
  notes         text,
  image_url     text,
  created_at    timestamptz,
  edited_at     timestamptz,
  enrollments   jsonb,
  servant       jsonb,
  priest        jsonb,
  has_password  boolean,
  total_count   bigint
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_mode   text := coalesce(p_scope_mode, 'all');
  v_kind   text := coalesce(p_kind, 'all');
  v_limit  integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.is_owner() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_mode not in ('all', 'scope', 'none') then
    raise exception 'invalid_scope_mode' using errcode = '22023';
  end if;
  if v_kind not in ('all', 'child', 'servant', 'priest') then
    raise exception 'invalid_kind' using errcode = '22023';
  end if;
  if p_gender is not null and p_gender not in ('male', 'female') then
    raise exception 'invalid_gender' using errcode = '22023';
  end if;
  if v_mode = 'scope' and p_church is null then
    raise exception 'church_required' using errcode = '22023';
  end if;

  return query
  with base as (
    select p.*
      from public.persons p
     where (v_search is null
            or p.name ilike '%' || v_search || '%'
            or p.phone ilike '%' || v_search || '%'
            or p.national_id ilike '%' || v_search || '%')
       and (p_gender is null or p.gender = p_gender)
       and (
         v_mode = 'all'
         or (v_mode = 'none' and not exists (select 1 from public.enrollments e where e.person_id = p.id)
                               and not exists (select 1 from public.priests pr where pr.person_id = p.id))
         or (v_mode = 'scope' and (
              exists (
                select 1 from public.enrollments e
                 where e.person_id = p.id
                   and e.church_id = p_church
                   and (p_service is null or e.service_id = p_service)
                   and (p_class   is null or e.class_id   = p_class))
              or (p_service is null and p_class is null
                  and exists (select 1 from public.priests pr where pr.person_id = p.id and pr.church_id = p_church))))
       )
       and (
         v_kind = 'all'
         or (v_kind = 'servant' and exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
         or (v_kind = 'child'   and exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child'))
         or (v_kind = 'priest'  and exists (select 1 from public.priests pr where pr.person_id = p.id))
       )
  ),
  counted as (
    select b.*, count(*) over () as total_count
      from base b
     order by b.name collate "C", b.id
     limit v_limit offset v_offset
  )
  select
    c.id, c.national_id, c.name, c.birthdate, c.gender, c.phone, c.address, c.notes, c.image_url,
    c.created_at, c.edited_at,
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
               'kind', e.kind, 'servant_id', e.servant_id, 'status', e.status,
               'points', e.points, 'attendance_count', e.attendance_count, 'created_at', e.created_at)
             order by e.created_at)
        from public.enrollments e where e.person_id = c.id
    ), '[]'::jsonb) as enrollments,
    (
      select jsonb_build_object(
               'id', s.id, 'role', s.role, 'status', s.status,
               'church_id', s.church_id, 'service_id', s.service_id, 'class_id', s.class_id,
               'scopes', coalesce((
                 select jsonb_agg(jsonb_build_object('church_id', x.church_id, 'service_id', x.service_id, 'class_id', x.class_id))
                   from public.servant_scopes x where x.servant_id = s.id), '[]'::jsonb))
        from public.servant_enrollments s where s.person_id = c.id
       limit 1
    ) as servant,
    (
      select jsonb_build_object('id', pr.id, 'church_id', pr.church_id, 'title', pr.title, 'status', pr.status, 'created_at', pr.created_at)
        from public.priests pr where pr.person_id = c.id
       limit 1
    ) as priest,
    exists (select 1 from public.person_credentials pc where pc.person_id = c.id) as has_password,
    c.total_count
  from counted c
  order by c.name collate "C", c.id;
end $$;

revoke all on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) from public, anon;
grant execute on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) to authenticated;

comment on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) is
  'إدارة الأفراد (المالك): كل الأشخاص مع تسجيلاتهم وحساب الخادم وحساب الكاهن — بحث · نطاق · الصنف (مخدوم/خادم/كاهن) · النوع · ترقيم';

create or replace function public.owner_persons_counts()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.is_owner() then jsonb_build_object(
    'total',      (select count(*) from public.persons),
    'unenrolled', (select count(*) from public.persons p
                    where not exists (select 1 from public.enrollments e where e.person_id = p.id)
                      and not exists (select 1 from public.priests pr where pr.person_id = p.id)),
    'servants',   (select count(*) from public.persons p where exists (select 1 from public.servant_enrollments s where s.person_id = p.id)),
    'children',   (select count(*) from public.persons p where exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child')),
    'priests',    (select count(*) from public.persons p where exists (select 1 from public.priests pr where pr.person_id = p.id))
  ) else null end
$$;
revoke all on function public.owner_persons_counts() from public, anon;
grant execute on function public.owner_persons_counts() to authenticated;

-- ---------------------------------------------------------------------
-- 2. owner_add_priest_for_person — a PRIEST account for an existing person
--    (approved at once). The password: the person's existing one (BEFORE
--    INSERT trigger priests_take_person_password adopts it) — otherwise
--    p_password, or the default password when none is given.
-- ---------------------------------------------------------------------
create or replace function public.owner_add_priest_for_person(
  p_person uuid, p_church uuid, p_title text default null, p_password text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_priest uuid; v_code text;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  select national_id into v_code from public.persons where id = p_person;
  if v_code is null then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  if p_church is null or not exists (select 1 from public.churches c where c.id = p_church) then
    raise exception 'church_required' using errcode = '22023';
  end if;
  if exists (select 1 from public.priests where person_id = p_person) then
    raise exception 'already_registered' using errcode = '23505';
  end if;
  if p_password is not null and length(p_password) < 6 then raise exception 'weak_password' using errcode = '22023'; end if;
  insert into public.priests (person_id, church_id, title, status, password_hash, approved_by, approved_at)
  values (p_person, p_church, nullif(trim(coalesce(p_title, '')), ''), 'approved',
          crypt(coalesce(p_password, public.default_password()), gen_salt('bf', 10)), auth.uid(), now())
  returning id into v_priest;
  update public.priest_requests set status = 'approved', decided_by = auth.uid(), decided_at = now(), priest_id = v_priest
   where code = v_code and status = 'pending';
  return jsonb_build_object('priest_id', v_priest, 'person_id', p_person, 'code', v_code);
end $$;
revoke all on function public.owner_add_priest_for_person(uuid, uuid, text, text) from public, anon;
grant execute on function public.owner_add_priest_for_person(uuid, uuid, text, text) to authenticated;
comment on function public.owner_add_priest_for_person(uuid, uuid, text, text) is
  'إدارة الأفراد: إضافة حساب كاهن لشخص موجود (معتمد فورًا، بكلمة مرور الشخص نفسها)';

-- ---------------------------------------------------------------------
-- 3. MERGE helpers
-- ---------------------------------------------------------------------
-- Re-point every row of `p_table.p_col` from p_remove to p_keep. A row that
-- would collide with an existing one of p_keep (unique key — the same fact
-- recorded for both persons) is DELETED instead. Internal.
create or replace function public.merge_repoint(p_table regclass, p_col name, p_keep uuid, p_remove uuid)
returns integer language plpgsql volatile security definer set search_path = public as $$
declare n integer := 0; r record;
begin
  begin
    execute format('update %s set %I = $1 where %I = $2', p_table, p_col, p_col) using p_keep, p_remove;
    get diagnostics n = row_count;
    return n;
  exception when unique_violation or check_violation or raise_exception or exclusion_violation then
    null;   -- fall back to row by row below
  end;
  for r in execute format('select ctid as t from %s where %I = $1', p_table, p_col) using p_remove loop
    begin
      execute format('update %s set %I = $1 where ctid = $2', p_table, p_col) using p_keep, r.t;
      n := n + 1;
    exception when unique_violation or check_violation or raise_exception or exclusion_violation then
      execute format('delete from %s where ctid = $1', p_table) using r.t;
    end;
  end loop;
  return n;
end $$;
revoke all on function public.merge_repoint(regclass, name, uuid, uuid) from public, anon, authenticated;

-- Fold enrollment p_remove into p_keep (same person, same class): counters
-- are summed, every log / request / session that pointed at p_remove is
-- re-pointed, then p_remove goes. Internal.
create or replace function public.merge_enrollments(p_keep uuid, p_remove uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare rm public.enrollments; fk record;
begin
  if p_keep = p_remove or not exists (select 1 from public.enrollments where id = p_remove) then return; end if;
  -- 1) move every log / request / session (a duplicate — e.g. the same
  --    attendance day — is dropped; its delete trigger adjusts p_remove's
  --    counters, so the counters read below are exact)
  for fk in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
     where c.contype = 'f' and c.confrelid = 'public.enrollments'::regclass and array_length(c.conkey, 1) = 1
  loop
    perform public.merge_repoint(fk.tbl, fk.col, p_keep, p_remove);
  end loop;
  -- 2) counters + kind
  select * into rm from public.enrollments where id = p_remove;
  update public.enrollments
     set attendance_count = attendance_count + rm.attendance_count,
         points = points + rm.points,
         -- a servant mirror wins over a plain child row (the servant account decides)
         kind = case when rm.kind = 'servant' then 'servant' else kind end,
         servant_id = coalesce(servant_id, rm.servant_id)
   where id = p_keep;
  -- 3) nothing is left under p_remove
  delete from public.enrollments where id = p_remove;
end $$;
revoke all on function public.merge_enrollments(uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. owner_merge_persons(keep, remove, fields)
--    p_fields: {name, gender, birthdate, phone, address, notes, image_url,
--    national_id} — the value the owner picked for every field (a missing
--    key keeps `keep`'s value). national_id may be either person's code.
--    Returns {person_id, code, moved: {table: n}, servant_id, priest_id,
--    realign_servant} — realign_servant = the servant Auth account must be
--    re-synced (e-mail / password hash) by POST /api/servants/account
--    {action: 'realign'} because its code or password changed.
-- ---------------------------------------------------------------------
create or replace function public.owner_merge_persons(p_keep uuid, p_remove uuid, p_fields jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  k public.persons; r public.persons;
  fk record; pair record; n integer;
  v_moved jsonb := '{}'::jsonb;
  v_code text; v_tmp text;
  v_servant uuid; v_priest uuid;
  v_keep_servant uuid; v_rm_servant uuid;
  v_keep_pw text; v_rm_pw text;
  v_realign boolean := false;
  v_gender text; v_birth date;
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_keep is null or p_remove is null or p_keep = p_remove then raise exception 'two_persons_required' using errcode = '22023'; end if;
  select * into k from public.persons where id = p_keep for update;
  if not found then raise exception 'person_not_found' using errcode = 'P0002'; end if;
  select * into r from public.persons where id = p_remove for update;
  if not found then raise exception 'person_not_found' using errcode = 'P0002'; end if;

  select id into v_keep_servant from public.servant_enrollments where person_id = p_keep limit 1;
  select id into v_rm_servant   from public.servant_enrollments where person_id = p_remove limit 1;
  if v_keep_servant is not null and v_rm_servant is not null then
    raise exception 'both_servants' using errcode = 'P0001',
      hint = 'احذف أحد حسابي الخادم من إدارة الخدام أولاً';
  end if;
  if exists (select 1 from public.priests where person_id = p_keep) and exists (select 1 from public.priests where person_id = p_remove) then
    raise exception 'both_priests' using errcode = 'P0001',
      hint = 'احذف أحد حسابي الكاهن من الكهنة أولاً';
  end if;

  -- the chosen code (default: keep's)
  v_code := coalesce(nullif(trim(coalesce(p_fields->>'national_id', '')), ''), k.national_id);
  if v_code not in (k.national_id, r.national_id) then raise exception 'invalid_code' using errcode = '22023'; end if;
  v_gender := coalesce(p_fields->>'gender', k.gender);
  if v_gender is not null and v_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  v_birth := case when p_fields ? 'birthdate' then nullif(p_fields->>'birthdate', '')::date else k.birthdate end;

  -- password: keep's wins; remove's is adopted only when keep has none
  select password_hash into v_keep_pw from public.person_credentials where person_id = p_keep;
  select password_hash into v_rm_pw   from public.person_credentials where person_id = p_remove;
  if v_keep_pw is null and v_rm_pw is not null then
    update public.person_credentials set person_id = p_keep where person_id = p_remove;
  end if;
  -- the servant Auth account (login e-mail = code, bcrypt hash) must be
  -- re-synced when the code or the password of ITS person changed
  if v_keep_servant is not null then
    v_realign := v_code <> k.national_id or coalesce(v_keep_pw, v_rm_pw) is distinct from v_keep_pw;
  elsif v_rm_servant is not null then
    v_realign := v_code <> r.national_id or coalesce(v_keep_pw, v_rm_pw) is distinct from v_rm_pw;
  end if;

  -- a) same-class enrollment pairs → fold
  for pair in
    select e1.id as keep_e, e2.id as rm_e
      from public.enrollments e1
      join public.enrollments e2 on e2.class_id = e1.class_id
     where e1.person_id = p_keep and e2.person_id = p_remove
  loop
    perform public.merge_enrollments(pair.keep_e, pair.rm_e);
  end loop;
  -- b) the remaining enrollments → keep (before the servant account moves,
  --    so its mirror rows are already his when sync_servant_mirrors runs)
  n := public.merge_repoint('public.enrollments'::regclass, 'person_id', p_keep, p_remove);
  if n > 0 then v_moved := v_moved || jsonb_build_object('enrollments', n); end if;

  -- c) every other table that points at persons
  for fk in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
     where c.contype = 'f' and c.confrelid = 'public.persons'::regclass and array_length(c.conkey, 1) = 1
       and c.conrelid not in ('public.enrollments'::regclass, 'public.person_credentials'::regclass)
     order by case when c.conrelid = 'public.servant_enrollments'::regclass then 1 else 0 end
  loop
    n := public.merge_repoint(fk.tbl, fk.col, p_keep, p_remove);
    if n > 0 then v_moved := v_moved || jsonb_build_object(replace(fk.tbl::text, 'public.', ''), n); end if;
  end loop;

  -- d) requests keyed by the CODE text
  if v_code <> r.national_id then
    update public.child_join_requests set code = v_code where code = r.national_id;
    update public.priest_requests     set code = v_code where code = r.national_id;
  end if;

  -- e) the code: free remove's first when it is the chosen one
  if v_code = r.national_id and v_code <> k.national_id then
    v_tmp := 'merged-' || replace(p_remove::text, '-', '');
    update public.persons set national_id = v_tmp where id = p_remove;
  end if;

  -- f) the chosen identity values (LAST — the servant→person sync trigger
  --    may have written the servant's name / phone / photo above)
  update public.persons set
    national_id = v_code,
    name      = coalesce(nullif(trim(coalesce(p_fields->>'name', '')), ''), k.name),
    gender    = v_gender,
    birthdate = v_birth,
    phone     = case when p_fields ? 'phone'     then nullif(trim(coalesce(p_fields->>'phone', '')), '')     else k.phone end,
    address   = case when p_fields ? 'address'   then nullif(trim(coalesce(p_fields->>'address', '')), '')   else k.address end,
    notes     = case when p_fields ? 'notes'     then nullif(trim(coalesce(p_fields->>'notes', '')), '')     else k.notes end,
    image_url = case when p_fields ? 'image_url' then nullif(trim(coalesce(p_fields->>'image_url', '')), '') else k.image_url end,
    edited_by = auth.uid(), edited_at = now()
  where id = p_keep;

  -- g) the servant account must show the final identity (login name = code)
  select id into v_servant from public.servant_enrollments where person_id = p_keep limit 1;
  if v_servant is not null then
    perform set_config('app.in_servant_signup', '1', true);
    update public.servant_enrollments s
       set user_id = public.code_to_user_id(v_code),
           full_name = p.name, phone = coalesce(p.phone, s.phone), photo_url = p.image_url, updated_at = now()
      from public.persons p
     where s.id = v_servant and p.id = p_keep;
    perform set_config('app.in_servant_signup', '0', true);
    perform public.sync_servant_mirrors(v_servant);
  end if;
  -- the priest mirror hash follows the person's ONE password
  select id into v_priest from public.priests where person_id = p_keep limit 1;
  if v_priest is not null then
    update public.priests pr set password_hash = c.password_hash, updated_at = now()
      from public.person_credentials c
     where pr.id = v_priest and c.person_id = p_keep and pr.password_hash is distinct from c.password_hash;
  end if;

  -- h) good-bye
  delete from public.persons where id = p_remove;

  return jsonb_build_object(
    'person_id', p_keep, 'code', v_code, 'moved', v_moved,
    'servant_id', v_servant, 'priest_id', v_priest,
    'realign_servant', v_realign and v_servant is not null);
end $$;
revoke all on function public.owner_merge_persons(uuid, uuid, jsonb) from public, anon;
grant execute on function public.owner_merge_persons(uuid, uuid, jsonb) to authenticated;
comment on function public.owner_merge_persons(uuid, uuid, jsonb) is
  'دمج شخصين في شخص واحد (المالك): تُنقل كل التسجيلات والحسابات والسجلات إلى الشخص المُبقى، والمالك يختار قيمة كل حقل (الاسم · النوع · الميلاد · الهاتف · العنوان · الملاحظات · الصورة · الكود)؛ يُرفض إن كان للاثنين حساب خادم أو حساب كاهن';

-- ---------------------------------------------------------------------
-- 5. Service-role helper for the realign step — the servant account's code
--    (login e-mail) and password hash as they must be after a merge.
-- ---------------------------------------------------------------------
create or replace function public.admin_servant_identity(p_servant uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if auth.role() <> 'service_role' and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return (select jsonb_build_object(
            'servant_id', s.id, 'person_id', s.person_id, 'code', p.national_id,
            'user_id', public.code_to_user_id(p.national_id),
            'password_hash', (select c.password_hash from public.person_credentials c where c.person_id = p.id))
            from public.servant_enrollments s join public.persons p on p.id = s.person_id
           where s.id = p_servant);
end $$;
revoke all on function public.admin_servant_identity(uuid) from public, anon, authenticated;
grant execute on function public.admin_servant_identity(uuid) to service_role;



-- #####################################################################
-- ##  20261006120000_servant_scope_requests_unenrolled_fix.sql
-- #####################################################################

-- =====================================================================
-- 1. «بدون تسجيلات» = NO church at all.
--    A servant bound to a whole church («كل الخدمات») or a whole service
--    («كل الفصول») has no mirror `enrollments` row (mirrors exist per CLASS
--    only), so إدارة الأفراد counted him as «بدون تسجيلات». Now a person is
--    unenrolled ONLY when he has no child enrollment, no servant place with
--    a church, and no priest account. The scope filter matches a servant
--    whose place is the whole church / service too.
--
-- 2. A servant who ALREADY has an account opens a new دعوة خادم (another
--    service / class): instead of «ask the manager», he proves his password,
--    signs in and REQUESTS the new places → `servant_scope_requests`
--    (pending). The responsible manager approves them from
--    إدارة الخدام → الطلبات (→ set_servant_scopes adds the places) or rejects.
--
-- 3. The owner may add another SERVANT place / PRIEST church from إدارة
--    الأفراد → تسجيل even when the person already holds that kind:
--    `owner_add_servant_places(servant, places)` appends places (keeps the
--    existing ones) — the priest stays one church (its church can be edited
--    from الكهنة).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 2. servant_scope_requests — «أريد خدمة أخرى» from an existing servant
-- ---------------------------------------------------------------------
create table if not exists public.servant_scope_requests (
  id            uuid primary key default gen_random_uuid(),
  servant_id    uuid not null references public.servant_enrollments(id) on delete cascade,
  church_id     uuid not null references public.churches(id) on delete cascade,
  service_id    uuid references public.services(id) on delete cascade,
  class_id      uuid references public.classes(id) on delete cascade,
  status        text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  invite_id     uuid references public.signup_invites(id) on delete set null,
  decision_note text,
  decided_by    uuid references public.servant_enrollments(id) on delete set null,
  decided_at    timestamptz,
  created_at    timestamptz not null default now()
);
comment on table public.servant_scope_requests is
  'طلبات أماكن خدمة إضافية من خادم له حساب بالفعل (دعوة خادم جديدة) — يعتمدها مسؤول النطاق فتُضاف إلى أماكنه';
create index if not exists idx_servant_scope_requests_servant on public.servant_scope_requests(servant_id);
create index if not exists idx_servant_scope_requests_pending on public.servant_scope_requests(status) where status = 'pending';
alter table public.servant_scope_requests enable row level security;
alter table public.servant_scope_requests replica identity full;
revoke all on public.servant_scope_requests from anon, authenticated;
grant select on public.servant_scope_requests to authenticated;
grant all on public.servant_scope_requests to service_role;
drop policy if exists servant_scope_requests_select on public.servant_scope_requests;
create policy servant_scope_requests_select on public.servant_scope_requests for select to authenticated using (
  servant_id = auth.uid()
  or (select public.is_owner())
  or public.scope_grantable(church_id, service_id, class_id)
);
do $$ begin
  alter publication supabase_realtime add table public.servant_scope_requests;
exception when duplicate_object then null; end $$;
do $$ begin
  if to_regprocedure('public.activity_audit_attach(text)') is not null then
    perform public.activity_audit_attach('servant_scope_requests');
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. unenrolled = no church anywhere
-- ---------------------------------------------------------------------
create or replace function public.person_has_any_place(p_person uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.enrollments e where e.person_id = p_person)
      or exists (select 1 from public.priests pr where pr.person_id = p_person)
      or exists (select 1 from public.servant_enrollments s
                  where s.person_id = p_person
                    and (s.church_id is not null
                         or exists (select 1 from public.servant_scopes x where x.servant_id = s.id)))
$$;
revoke all on function public.person_has_any_place(uuid) from public, anon;
grant execute on function public.person_has_any_place(uuid) to authenticated;

drop function if exists public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer);
create or replace function public.owner_persons_page(
  p_search      text default null,
  p_scope_mode  text default 'all',
  p_church      uuid default null,
  p_service     uuid default null,
  p_class       uuid default null,
  p_gender      text default null,
  p_kind        text default 'all',
  p_limit       integer default 100,
  p_offset      integer default 0
) returns table (
  id            uuid,
  national_id   text,
  name          text,
  birthdate     date,
  gender        text,
  phone         text,
  address       text,
  notes         text,
  image_url     text,
  created_at    timestamptz,
  edited_at     timestamptz,
  enrollments   jsonb,
  servant       jsonb,
  priest        jsonb,
  has_password  boolean,
  total_count   bigint
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_mode   text := coalesce(p_scope_mode, 'all');
  v_kind   text := coalesce(p_kind, 'all');
  v_limit  integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_mode not in ('all', 'scope', 'none') then raise exception 'invalid_scope_mode' using errcode = '22023'; end if;
  if v_kind not in ('all', 'child', 'servant', 'priest') then raise exception 'invalid_kind' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female') then raise exception 'invalid_gender' using errcode = '22023'; end if;
  if v_mode = 'scope' and p_church is null then raise exception 'church_required' using errcode = '22023'; end if;

  return query
  with base as (
    select p.*
      from public.persons p
     where (v_search is null
            or p.name ilike '%' || v_search || '%'
            or p.phone ilike '%' || v_search || '%'
            or p.national_id ilike '%' || v_search || '%')
       and (p_gender is null or p.gender = p_gender)
       and (
         v_mode = 'all'
         or (v_mode = 'none' and not public.person_has_any_place(p.id))
         or (v_mode = 'scope' and (
              exists (
                select 1 from public.enrollments e
                 where e.person_id = p.id
                   and e.church_id = p_church
                   and (p_service is null or e.service_id = p_service)
                   and (p_class   is null or e.class_id   = p_class))
              -- a servant whose place is the whole church / service (no mirror row)
              or exists (
                select 1 from public.servant_enrollments s
                join public.servant_all_scopes(s.id) t on true
                 where s.person_id = p.id
                   and t.church_id = p_church
                   and (p_service is null or t.service_id is null or t.service_id = p_service)
                   and (p_class   is null or t.class_id   is null or t.class_id   = p_class))
              or (p_service is null and p_class is null
                  and exists (select 1 from public.priests pr where pr.person_id = p.id and pr.church_id = p_church))))
       )
       and (
         v_kind = 'all'
         or (v_kind = 'servant' and exists (select 1 from public.servant_enrollments s where s.person_id = p.id))
         or (v_kind = 'child'   and exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child'))
         or (v_kind = 'priest'  and exists (select 1 from public.priests pr where pr.person_id = p.id))
       )
  ),
  counted as (
    select b.*, count(*) over () as total_count
      from base b
     order by b.name collate "C", b.id
     limit v_limit offset v_offset
  )
  select
    c.id, c.national_id, c.name, c.birthdate, c.gender, c.phone, c.address, c.notes, c.image_url,
    c.created_at, c.edited_at,
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e.id, 'church_id', e.church_id, 'service_id', e.service_id, 'class_id', e.class_id,
               'kind', e.kind, 'servant_id', e.servant_id, 'status', e.status,
               'points', e.points, 'attendance_count', e.attendance_count, 'created_at', e.created_at)
             order by e.created_at)
        from public.enrollments e where e.person_id = c.id
    ), '[]'::jsonb) as enrollments,
    (
      select jsonb_build_object(
               'id', s.id, 'role', s.role, 'status', s.status,
               'church_id', s.church_id, 'service_id', s.service_id, 'class_id', s.class_id,
               'scopes', coalesce((
                 select jsonb_agg(jsonb_build_object('church_id', x.church_id, 'service_id', x.service_id, 'class_id', x.class_id))
                   from public.servant_scopes x where x.servant_id = s.id), '[]'::jsonb),
               'pending_scopes', coalesce((
                 select jsonb_agg(jsonb_build_object('church_id', r.church_id, 'service_id', r.service_id, 'class_id', r.class_id))
                   from public.servant_scope_requests r where r.servant_id = s.id and r.status = 'pending'), '[]'::jsonb))
        from public.servant_enrollments s where s.person_id = c.id
       limit 1
    ) as servant,
    (
      select jsonb_build_object('id', pr.id, 'church_id', pr.church_id, 'title', pr.title, 'status', pr.status, 'created_at', pr.created_at)
        from public.priests pr where pr.person_id = c.id
       limit 1
    ) as priest,
    exists (select 1 from public.person_credentials pc where pc.person_id = c.id) as has_password,
    c.total_count
  from counted c
  order by c.name collate "C", c.id;
end $$;
revoke all on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) from public, anon;
grant execute on function public.owner_persons_page(text, text, uuid, uuid, uuid, text, text, integer, integer) to authenticated;

create or replace function public.owner_persons_counts()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.is_owner() then jsonb_build_object(
    'total',      (select count(*) from public.persons),
    'unenrolled', (select count(*) from public.persons p where not public.person_has_any_place(p.id)),
    'servants',   (select count(*) from public.persons p where exists (select 1 from public.servant_enrollments s where s.person_id = p.id)),
    'children',   (select count(*) from public.persons p where exists (select 1 from public.enrollments e where e.person_id = p.id and e.kind = 'child')),
    'priests',    (select count(*) from public.persons p where exists (select 1 from public.priests pr where pr.person_id = p.id))
  ) else null end
$$;
revoke all on function public.owner_persons_counts() from public, anon;
grant execute on function public.owner_persons_counts() to authenticated;

-- the signed-in servant asks for more places (the invite is consumed; its
-- scope is the first place when none is given)
create or replace function public.servant_request_scopes(p_scopes jsonb, p_invite text default null)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  v_uid uuid := auth.uid(); s public.servant_enrollments; inv public.signup_invites;
  v jsonb; v_c uuid; v_s uuid; v_k uuid; v_scopes jsonb; n int := 0; v_skipped int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into s from public.servant_enrollments where id = v_uid;
  if not found then raise exception 'no_such_account' using errcode = 'P0002'; end if;
  if s.status <> 'approved' then raise exception 'account_not_approved' using errcode = 'P0001'; end if;
  inv := public.signup_invite_consume(p_invite, 'servant');
  v_scopes := case
    when p_scopes is not null and jsonb_typeof(p_scopes) = 'array' and jsonb_array_length(p_scopes) > 0 then p_scopes
    when inv.church_id is not null then jsonb_build_array(jsonb_build_object('church_id', inv.church_id, 'service_id', inv.service_id, 'class_id', inv.class_id))
    else '[]'::jsonb end;
  if jsonb_array_length(v_scopes) = 0 then raise exception 'scopes_required' using errcode = '22023'; end if;
  for v in select * from jsonb_array_elements(v_scopes) loop
    v_c := nullif(v->>'church_id', '')::uuid; v_s := nullif(v->>'service_id', '')::uuid; v_k := nullif(v->>'class_id', '')::uuid;
    if v_c is null then raise exception 'church_required' using errcode = '22023'; end if;
    if s.role = 'church_manager' then v_s := null; v_k := null; end if;
    if s.role = 'service_manager' then v_k := null; end if;
    if v_s is not null and not exists (select 1 from public.services x where x.id = v_s and x.church_id = v_c) then
      raise exception 'service_not_in_church' using errcode = '22023';
    end if;
    if v_k is not null and (v_s is null or not exists (select 1 from public.classes x where x.id = v_k and x.service_id = v_s)) then
      raise exception 'class_not_in_service' using errcode = '22023';
    end if;
    -- already one of his places, or already requested → skip
    if exists (select 1 from public.servant_all_scopes(v_uid) t
                where t.church_id = v_c and t.service_id is not distinct from v_s and t.class_id is not distinct from v_k)
       or exists (select 1 from public.servant_scope_requests r
                   where r.servant_id = v_uid and r.status = 'pending'
                     and r.church_id = v_c and r.service_id is not distinct from v_s and r.class_id is not distinct from v_k) then
      v_skipped := v_skipped + 1; continue;
    end if;
    insert into public.servant_scope_requests (servant_id, church_id, service_id, class_id, invite_id)
    values (v_uid, v_c, v_s, v_k, inv.id);
    n := n + 1;
  end loop;
  return jsonb_build_object('requested', n, 'skipped', v_skipped);
end $$;
grant execute on function public.servant_request_scopes(jsonb, text) to authenticated;

-- the manager decides (approve → the place is appended to the servant's places)
create or replace function public.review_servant_scope_request(p_request uuid, p_approve boolean, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare r public.servant_scope_requests; cur jsonb;
begin
  if public.my_role() is null then raise exception 'not_approved' using errcode = '42501'; end if;
  select * into r from public.servant_scope_requests where id = p_request for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'pending' then raise exception 'not_pending' using errcode = 'P0001'; end if;
  if not (public.is_owner() or public.scope_grantable(r.church_id, r.service_id, r.class_id)) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_approve then
    -- current places + the new one (set_servant_scopes keeps the ones outside the caller's area)
    select coalesce(jsonb_agg(jsonb_build_object('church_id', t.church_id, 'service_id', t.service_id, 'class_id', t.class_id)), '[]'::jsonb)
      into cur from public.servant_all_scopes(r.servant_id) t;
    perform public.set_servant_scopes(r.servant_id,
      cur || jsonb_build_object('church_id', r.church_id, 'service_id', r.service_id, 'class_id', r.class_id));
  end if;
  update public.servant_scope_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         decision_note = nullif(trim(coalesce(p_note, '')), ''), decided_by = auth.uid(), decided_at = now()
   where id = r.id;
  return jsonb_build_object('status', case when p_approve then 'approved' else 'rejected' end, 'servant_id', r.servant_id);
end $$;
revoke all on function public.review_servant_scope_request(uuid, boolean, text) from public, anon;
grant execute on function public.review_servant_scope_request(uuid, boolean, text) to authenticated;

-- the pending-count badge of إدارة الخدام counts both kinds of requests
create or replace function public.pending_servant_requests_count()
returns integer language sql stable security definer set search_path = public as $$
  select (select count(*) from public.servant_enrollments s where s.status = 'pending'
            and (public.is_owner() or public.servant_in_my_scope(s.id) or s.church_id is null
                 or public.scope_grantable(s.church_id, s.service_id, s.class_id)))::int
       + (select count(*) from public.servant_scope_requests r where r.status = 'pending'
            and (public.is_owner() or public.scope_grantable(r.church_id, r.service_id, r.class_id)))::int
$$;
revoke all on function public.pending_servant_requests_count() from public, anon;
grant execute on function public.pending_servant_requests_count() to authenticated;

-- ---------------------------------------------------------------------
-- 3. owner appends places to an EXISTING servant account (إدارة الأفراد → تسجيل كخادم)
-- ---------------------------------------------------------------------
create or replace function public.owner_add_servant_places(p_servant uuid, p_scopes jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare cur jsonb;
begin
  if not (public.is_owner() or public.can_manage_servant(p_servant)) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_scopes is null or jsonb_typeof(p_scopes) <> 'array' or jsonb_array_length(p_scopes) = 0 then
    raise exception 'scopes_required' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('church_id', t.church_id, 'service_id', t.service_id, 'class_id', t.class_id)), '[]'::jsonb)
    into cur from public.servant_all_scopes(p_servant) t;
  return public.set_servant_scopes(p_servant, cur || p_scopes);
end $$;
revoke all on function public.owner_add_servant_places(uuid, jsonb) from public, anon;
grant execute on function public.owner_add_servant_places(uuid, jsonb) to authenticated;
comment on function public.owner_add_servant_places(uuid, jsonb) is
  'إضافة أماكن خدمة إلى حساب خادم موجود (تبقى أماكنه الحالية) — المالك أو مدير نطاقه';



-- #####################################################################
-- ##  20261007120000_activity_rls_fast_invites_editable.sql
-- #####################################################################

-- =====================================================================
-- 1. سجل النشاط — the feed / summary used to TIME OUT for every non-owner
--    («تعذر تحميل السجل», empty «نظرة عامة»).
--    The select policy on activity_log called activity_row_visible() PER
--    ROW, and that function re-ran is_owner() → activity_can() →
--    module_visible() → my_scope() → my_scopes() → has_permission() →
--    scope_overlaps() … (each a security-definer query) for every row.
--    The owner short-circuits on the first branch; a servant / manager
--    pays the whole chain: ~6 ms × rows → activity_summary over a few
--    thousand rows exceeds the statement timeout.
--
--    Fix: `activity_visibility()` computes the caller's context ONCE
--    (owner · may view · sees whole church · the scope list) and the
--    policy wraps it in an InitPlan `(select …)` so Postgres evaluates it
--    a single time per statement; the per-row part is a pure comparison
--    against the arrays. activity_row_visible() keeps its signature
--    (same truth table) for anything still calling it.
--
-- 2. دعوات التسجيل — the invite link vanished when the page was reopened:
--    only the sha256 hash was stored, the raw token lived in React state.
--    Now the token is stored too (`signup_invites.token`, readable only by
--    the creator / owner through RLS) so the link / QR can be shown again,
--    `signup_invite_update()` edits validity · uses · note, and the
--    creator / owner may DELETE an invite. The hash column remains the
--    lookup key for check / consume (token is never read by anon).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. activity_log — one context per statement
-- ---------------------------------------------------------------------
-- Returned once per statement by the policy's InitPlan:
--   is_owner      → everything
--   can_view      → activity.view (false → nothing)
--   whole_church  → church manager OR activity.view_all: every row of his
--                   churches (+ rows without church made by servants of
--                   his churches)
--   churches / scopes → the caller's places (my_scopes())
create or replace function public.activity_visibility()
returns table (is_owner boolean, can_view boolean, whole_church boolean, churches uuid[], scopes jsonb)
language sql stable security definer set search_path = public as $$
  with me as (select role, church_id, service_id, class_id from public.my_scopes()),
       r as (select role from me limit 1)
  select
    coalesce((select role from r) = 'owner', false)                                   as is_owner,
    public.activity_can('activity.view')                                              as can_view,
    coalesce((select role from r) = 'church_manager', false)
      or public.has_permission('activity.view_all')                                   as whole_church,
    coalesce((select array_agg(distinct church_id) from me where church_id is not null), '{}'::uuid[]) as churches,
    coalesce((select jsonb_agg(jsonb_build_object('c', church_id, 's', service_id, 'k', class_id))
                from me where church_id is not null), '[]'::jsonb)                   as scopes
$$;
grant execute on function public.activity_visibility() to authenticated;

-- Pure (no table reads) per-row test against the context above.
-- Same truth table as activity_row_visible() / scope_overlaps():
--   whole church → church ∈ churches
--   else         → one scope with the same church whose service / class are
--                  unset on either side or equal.
create or replace function public.activity_row_in_scope(
  p_church uuid, p_service uuid, p_class uuid, p_whole boolean, p_churches uuid[], p_scopes jsonb
) returns boolean language sql immutable as $$
  select case
    when p_whole then p_church = any(p_churches)
    else exists (
      select 1 from jsonb_array_elements(coalesce(p_scopes, '[]'::jsonb)) s
       where (s->>'c')::uuid = p_church
         and (s->>'s' is null or p_service is null or (s->>'s')::uuid = p_service)
         and (s->>'k' is null or p_class is null or (s->>'k')::uuid = p_class)
    )
  end
$$;

-- Rows WITHOUT a church: a church manager (or view_all) sees what the
-- servants of his churches did. Set-valued once per statement too.
create or replace function public.activity_visible_actors(p_churches uuid[])
returns uuid[] language sql stable security definer set search_path = public as $$
  select coalesce((
    select array_agg(distinct se.id)
      from public.servant_enrollments se
     where se.church_id = any(p_churches)
        or exists (select 1 from public.servant_scopes x where x.servant_id = se.id and x.church_id = any(p_churches))
  ), '{}'::uuid[])
$$;
grant execute on function public.activity_visible_actors(uuid[]) to authenticated;

drop policy if exists activity_log_select on public.activity_log;
create policy activity_log_select on public.activity_log for select using (
  (select v.is_owner from public.activity_visibility() v)
  or (
    (select v.can_view from public.activity_visibility() v)
    and case
      when church_id is not null then
        public.activity_row_in_scope(church_id, service_id, class_id,
          (select v.whole_church from public.activity_visibility() v),
          (select v.churches from public.activity_visibility() v),
          (select v.scopes from public.activity_visibility() v))
      when actor_kind = 'servant' and actor_id is not null then
        (select v.whole_church from public.activity_visibility() v)
        and actor_id = any ((select public.activity_visible_actors(v.churches) from public.activity_visibility() v)::uuid[])
      else false
    end
  )
);

-- Keep the old helper consistent (person history / tests / older callers)
create or replace function public.activity_row_visible(
  p_church uuid, p_service uuid, p_class uuid, p_actor_kind text, p_actor_id uuid
) returns boolean language sql stable security definer set search_path = public as $$
  select v.is_owner
      or (v.can_view and case
            when p_church is not null then public.activity_row_in_scope(p_church, p_service, p_class, v.whole_church, v.churches, v.scopes)
            when p_actor_kind = 'servant' and p_actor_id is not null then
              v.whole_church and p_actor_id = any (public.activity_visible_actors(v.churches))
            else false
          end)
    from public.activity_visibility() v
$$;

-- The summary over a big log: cap the work to the filter's period (the
-- UI always sends `from`); the by_day / by_hour windows are unchanged.
-- Nothing else to change — once the policy is cheap the RPCs are fast.

-- ---------------------------------------------------------------------
-- 2. signup_invites — stored token · update · delete
-- ---------------------------------------------------------------------
alter table public.signup_invites add column if not exists token text;
alter table public.signup_invites add column if not exists updated_at timestamptz;

-- RLS already limits rows to the creator / owner; the column grant lets
-- them read the token to rebuild the link / QR. anon has NO grant.
grant select (token, updated_at) on public.signup_invites to authenticated;
grant delete on public.signup_invites to authenticated;
drop policy if exists signup_invites_delete on public.signup_invites;
create policy signup_invites_delete on public.signup_invites for delete to authenticated
  using (created_by = auth.uid() or (select public.is_owner()));

-- create: store the token as well (same rules as before)
create or replace function public.signup_invite_create(
  p_kind text, p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_days integer default 7, p_max_uses integer default null, p_note text default null
) returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare v_role public.app_role := public.my_role(); v_token text; v_id uuid; v_exp timestamptz;
begin
  if v_role is null then raise exception 'not_approved' using errcode = '42501'; end if;
  if p_kind not in ('servant', 'child', 'priest') then raise exception 'invalid_kind' using errcode = '22023'; end if;
  if p_kind = 'priest' and not public.is_owner() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_kind = 'servant' and v_role = 'class_servant' then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_kind = 'child' then
    if p_church is null or p_service is null or p_class is null then raise exception 'scope_required' using errcode = '22023'; end if;
    if not public.can_access(p_church, p_service, p_class) then raise exception 'forbidden' using errcode = '42501'; end if;
  elsif p_kind = 'servant' and p_church is not null and not public.scope_contains(p_church, p_service, p_class) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_service is not null and not exists (select 1 from public.services s where s.id = p_service and s.church_id = p_church) then
    raise exception 'service_not_in_church' using errcode = '22023';
  end if;
  if p_class is not null and not exists (select 1 from public.classes c where c.id = p_class and c.service_id = p_service) then
    raise exception 'class_not_in_service' using errcode = '22023';
  end if;
  v_exp := now() + make_interval(days => greatest(1, least(coalesce(p_days, 7), 365)));
  v_token := encode(gen_random_bytes(18), 'hex');
  insert into public.signup_invites (kind, token_hash, token, church_id, service_id, class_id, created_by, expires_at, max_uses, note)
  values (p_kind, encode(digest(v_token, 'sha256'), 'hex'), v_token, p_church, p_service, p_class, auth.uid(), v_exp, p_max_uses, nullif(trim(coalesce(p_note, '')), ''))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'token', v_token, 'kind', p_kind, 'church_id', p_church, 'service_id', p_service, 'class_id', p_class, 'expires_at', v_exp);
end $$;
grant execute on function public.signup_invite_create(text, uuid, uuid, uuid, integer, integer, text) to authenticated;

-- update: validity (days from NOW) · max uses · note · un-revoke.
-- Scope / kind are immutable (make a new invite). Creator or owner only.
create or replace function public.signup_invite_update(
  p_id uuid, p_days integer default null, p_max_uses integer default null, p_clear_max_uses boolean default false,
  p_note text default null, p_reactivate boolean default false
) returns public.signup_invites language plpgsql volatile security definer set search_path = public as $$
declare i public.signup_invites;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into i from public.signup_invites where id = p_id for update;
  if not found then raise exception 'invite_not_found' using errcode = 'P0002'; end if;
  if not (i.created_by = auth.uid() or public.is_owner()) then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.signup_invites set
    expires_at = case when p_days is not null then now() + make_interval(days => greatest(1, least(p_days, 365))) else expires_at end,
    max_uses   = case when p_clear_max_uses then null when p_max_uses is not null then greatest(1, p_max_uses) else max_uses end,
    note       = case when p_note is not null then nullif(trim(p_note), '') else note end,
    revoked_at = case when p_reactivate then null else revoked_at end,
    updated_at = now()
  where id = p_id returning * into i;
  return i;
end $$;
grant execute on function public.signup_invite_update(uuid, integer, integer, boolean, text, boolean) to authenticated;

-- delete: creator / owner (also covered by the policy above; the RPC adds
-- a clear error instead of a silent 0-row delete)
create or replace function public.signup_invite_delete(p_id uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare i public.signup_invites;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into i from public.signup_invites where id = p_id;
  if not found then raise exception 'invite_not_found' using errcode = 'P0002'; end if;
  if not (i.created_by = auth.uid() or public.is_owner()) then raise exception 'forbidden' using errcode = '42501'; end if;
  delete from public.signup_invites where id = p_id;
end $$;
grant execute on function public.signup_invite_delete(uuid) to authenticated;



-- #####################################################################
-- ##  20261008120000_fix_families_fill_church_trigger.sql
-- #####################################################################

-- =====================================================================
-- 20261008120000 — FIX: adding a family from the servants' app failed
--   («تعذر الحفظ … تأكد من تطبيق تحديث قاعدة البيانات» on + عائلة)
--
-- Cause — 20260930130000 introduced the trigger families_fill_church()
-- (fills / validates families.church_id for the owner and the church
-- manager). It read the allowed churches with
--
--     select array_agg(id) into v_churches from public.family_manage_churches();
--
-- but family_manage_churches() returns `setof uuid` — a SCALAR set whose
-- only column is named after the function, not `id`. Postgres therefore
-- raised  ERROR: column "id" does not exist  (SQLSTATE 42703) on EVERY
-- insert into public.families made by a logged-in servant (owner / church
-- manager), and on every update that changes church_id. The priest portal
-- was not affected (the trigger returns early for created_by_priest /
-- auth.uid() is null), which is why only /family broke.
--
-- Fix — same logic, the set is aliased and aggregated correctly. Nothing
-- else changes (church_required / church_forbidden behave as documented).
-- =====================================================================


create or replace function public.families_fill_church()
returns trigger language plpgsql set search_path = public as $$
declare v_churches uuid[];
begin
  -- the priest portal (created_by_priest) and the backup restore are not concerned
  if auth.uid() is null or new.created_by_priest is not null then return new; end if;
  if tg_op = 'UPDATE' and new.church_id is not distinct from old.church_id then return new; end if;
  -- families_fill_place (earlier trigger, alphabetical order) may already have
  -- derived the church from area → street → building
  select array_agg(c) into v_churches from public.family_manage_churches() as c;
  if new.church_id is null then
    if v_churches is null then return new; end if;              -- not a manager → RLS decides
    if cardinality(v_churches) = 1 then
      new.church_id := v_churches[1];                            -- church manager of ONE church: his church
    else
      -- the owner, or a manager of several churches, must choose
      raise exception 'church_required' using errcode = '22023',
        detail = 'Choose the church of the family';
    end if;
  elsif not public.is_owner() and not (new.church_id = any (coalesce(v_churches, '{}'::uuid[]))) then
    raise exception 'church_forbidden' using errcode = '42501',
      detail = 'A church manager can only create families in his own church';
  end if;
  return new;
end $$;

-- the trigger itself is unchanged (trg_families_zz_fill_church, created by
-- 20260930130000) — recreate it defensively in case it is missing
drop trigger if exists trg_families_zz_fill_church on public.families;
create trigger trg_families_zz_fill_church before insert or update on public.families
for each row execute function public.families_fill_church();

notify pgrst, 'reload schema';



-- #####################################################################
-- ##  20261009120000_backup_scope_owner_module.sql
-- #####################################################################

-- =====================================================================
-- 20261009120000: SCOPED BACKUPS — نسخة احتياطية لكنيسة / خدمة / فصل
--                 + the backup module moves into the OWNER module
--
-- The owner can now back up ONE church, ONE service or ONE class instead of
-- the whole database. A scope is a jsonb object:
--     {"church_id": uuid, "service_id": uuid | null, "class_id": uuid | null}
-- (null = everything, exactly as before).
--
-- Which rows belong to a scope is derived from the schema — nothing is
-- hard-coded, new tables are picked up automatically:
--   • churches / services / classes      → the selected branch of the tree
--     (the parents of the selected level are always included so the file
--     can be restored on its own).
--   • tables with scope columns          → church_id / service_id / class_id
--     (a column counts when it has no FK or an FK to churches / services /
--     classes — `online_class_answers.class_id → online_classes` does NOT).
--     A row is in the scope when every scope column it has is either NULL
--     (= church-wide / service-wide / global row, e.g. a default event, a
--     church-wide cause, the owner's servant row) or equal to the scope.
--   • persons                            → every person referenced (any FK
--     column) by a row of a scoped table that is in the scope: the children
--     enrolled there, the servants, the priests, the family members …
--   • every other table                  → follows its NOT NULL foreign keys
--     to the parent (attendance_log → enrollments, exam_answers →
--     exam_attempts → exams, buildings → streets → areas …), recursively,
--     with a cycle guard. A table with no scoped parent at all (app_settings,
--     permission_profiles, push_subscriptions …) is copied completely and
--     flagged `scoped = false` in the catalogue so the UI can say so.
--
-- New / changed functions (all owner-or-service-role, security definer):
--   backup_scope_check(scope)                 validates + fills the parents
--   backup_scope_describe(scope)              names + Arabic label
--   backup_scope_predicate(table, scope, alias) SQL predicate text (for tests)
--   backup_tables(scope default null)         catalogue with rows IN SCOPE
--                                             + `scoped` flag per table
--   backup_dump_table(t, offset, limit, scope default null)
--   backup_dump_auth_users(scope default null)
--   backup_restore_begin(...)                 refuses mode = replace when the
--                                             file is a scoped backup
--                                             (`scoped_replace`) — replace
--                                             would delete everything outside
--                                             the scope.
-- Tables: backup_runs.scope · backup_schedules.scope (jsonb, null = all).
-- Idempotent.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 0. scope columns on the history + schedules
-- ---------------------------------------------------------------------
alter table public.backup_schedules add column if not exists scope jsonb;
alter table public.backup_runs      add column if not exists scope jsonb;
comment on column public.backup_schedules.scope is 'نطاق النسخة: {church_id, service_id, class_id} — null = كل البيانات';
comment on column public.backup_runs.scope      is 'نطاق النسخة: {church_id, service_id, class_id} — null = كل البيانات';

-- ---------------------------------------------------------------------
-- 1. Scope validation + description
-- ---------------------------------------------------------------------
-- Returns the normalised scope (parents filled from the class / service) or
-- NULL when p_scope is null / empty. Raises `bad_scope` when an id is unknown
-- or the levels do not belong to each other.
create or replace function public.backup_scope_check(p_scope jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  c uuid; s uuid; k uuid; r record;
begin
  if p_scope is null or jsonb_typeof(p_scope) <> 'object' then return null; end if;
  begin
    c := nullif(p_scope->>'church_id', '')::uuid;
    s := nullif(p_scope->>'service_id', '')::uuid;
    k := nullif(p_scope->>'class_id', '')::uuid;
  exception when others then
    raise exception 'bad_scope' using errcode = 'P0001';
  end;
  if c is null and s is null and k is null then return null; end if;

  if k is not null then
    select church_id, service_id into r from public.classes where id = k;
    if not found then raise exception 'bad_scope:class' using errcode = 'P0001'; end if;
    if s is not null and s <> r.service_id then raise exception 'bad_scope:class_service' using errcode = 'P0001'; end if;
    if c is not null and c <> r.church_id then raise exception 'bad_scope:class_church' using errcode = 'P0001'; end if;
    s := r.service_id; c := r.church_id;
  end if;
  if s is not null then
    select church_id into r from public.services where id = s;
    if not found then raise exception 'bad_scope:service' using errcode = 'P0001'; end if;
    if c is not null and c <> r.church_id then raise exception 'bad_scope:service_church' using errcode = 'P0001'; end if;
    c := r.church_id;
  end if;
  if not exists (select 1 from public.churches where id = c) then
    raise exception 'bad_scope:church' using errcode = 'P0001';
  end if;
  return jsonb_build_object('church_id', c, 'service_id', s, 'class_id', k);
end $$;
revoke all on function public.backup_scope_check(jsonb) from public;
grant execute on function public.backup_scope_check(jsonb) to authenticated, service_role;

-- {church_id, service_id, class_id, church_name, service_name, class_name,
--  level: 'church'|'service'|'class', label: 'كنيسة أ ← مدارس الأحد ← فصل ٣'}
create or replace function public.backup_scope_describe(p_scope jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  sc jsonb := public.backup_scope_check(p_scope);
  cn text; sn text; kn text; lvl text;
begin
  if sc is null then return null; end if;
  select name into cn from public.churches where id = (sc->>'church_id')::uuid;
  if sc->>'service_id' is not null then select name into sn from public.services where id = (sc->>'service_id')::uuid; end if;
  if sc->>'class_id' is not null then select name into kn from public.classes where id = (sc->>'class_id')::uuid; end if;
  lvl := case when kn is not null then 'class' when sn is not null then 'service' else 'church' end;
  return sc || jsonb_build_object(
    'church_name', cn, 'service_name', sn, 'class_name', kn, 'level', lvl,
    'label', concat_ws(' ← ', cn, sn, kn));
end $$;
revoke all on function public.backup_scope_describe(jsonb) from public;
grant execute on function public.backup_scope_describe(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 2. Which columns of a table are scope columns?
--    {church: col|null, service: col|null, class: col|null}
--    A column named church_id / service_id / class_id with no FK, or with an
--    FK to churches / services / classes; otherwise any column with an FK to
--    that structure table (e.g. online_class_participants.room_class_id).
-- ---------------------------------------------------------------------
create or replace function public.backup_scope_columns(t text)
returns jsonb language plpgsql stable as $$
declare
  out jsonb := '{}'::jsonb;
  lvl record; col text;
begin
  for lvl in select * from (values ('church', 'church_id', 'churches'), ('service', 'service_id', 'services'), ('class', 'class_id', 'classes')) v(key, col, parent) loop
    select a.attname::text into col
      from pg_attribute a
      join pg_class c on c.oid = a.attrelid
      join pg_namespace n on n.oid = c.relnamespace
      left join pg_constraint f on f.conrelid = c.oid and f.contype = 'f' and f.conkey = array[a.attnum]
      left join pg_class p on p.oid = f.confrelid
     where n.nspname = 'public' and c.relname = t and a.attnum > 0 and not a.attisdropped
       and (
         (a.attname = lvl.col and (f.oid is null or p.relname = lvl.parent))
         or (a.attname <> lvl.col and p.relname = lvl.parent)
       )
     order by (a.attname = lvl.col) desc, a.attnum
     limit 1;
    out := out || jsonb_build_object(lvl.key, col);
  end loop;
  return out;
end $$;

-- ---------------------------------------------------------------------
-- 3. The predicate — SQL text over alias `p_alias`, 'true' = unscoped table
-- ---------------------------------------------------------------------
create or replace function public.backup_scope_predicate(
  p_table text, p_scope jsonb, p_alias text default 't', p_visited text[] default '{}'
) returns text language plpgsql stable security definer set search_path = public as $$
declare
  sc jsonb; c text; s text; k text;
  cols jsonb; cc text; sc_col text; kc text;
  parts text[] := '{}';
  e record; sub text; depth int;
  alias2 text;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  sc := public.backup_scope_check(p_scope);
  if sc is null then return 'true'; end if;
  if not public.backup_is_table(p_table) then raise exception 'unknown_table' using errcode = 'P0001'; end if;
  if p_table = any(p_visited) then return 'true'; end if;      -- cycle guard
  c := quote_literal(sc->>'church_id') || '::uuid';
  s := case when sc->>'service_id' is null then null else quote_literal(sc->>'service_id') || '::uuid' end;
  k := case when sc->>'class_id' is null then null else quote_literal(sc->>'class_id') || '::uuid' end;

  -- a) the structure itself — the selected branch (parents always included)
  if p_table = 'churches' then
    return format('%I.id = %s', p_alias, c);
  elsif p_table = 'services' then
    return format('%1$I.church_id = %2$s', p_alias, c)
      || case when s is null then '' else format(' and %1$I.id = %2$s', p_alias, s) end;
  elsif p_table = 'classes' then
    return format('%1$I.church_id = %2$s', p_alias, c)
      || case when s is null then '' else format(' and %1$I.service_id = %2$s', p_alias, s) end
      || case when k is null then '' else format(' and %1$I.id = %2$s', p_alias, k) end;
  end if;

  -- b) direct scope columns
  cols := public.backup_scope_columns(p_table);
  cc := cols->>'church'; sc_col := cols->>'service'; kc := cols->>'class';
  if cc is not null or sc_col is not null or kc is not null then
    -- church level
    if cc is not null then
      parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I = %3$s)', p_alias, cc, c);
    elsif sc_col is not null then
      parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I in (select id from public.services where church_id = %3$s))', p_alias, sc_col, c);
    else
      parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I in (select id from public.classes where church_id = %3$s))', p_alias, kc, c);
    end if;
    -- service level
    if s is not null then
      if sc_col is not null then
        parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I = %3$s)', p_alias, sc_col, s);
      elsif kc is not null then
        parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I in (select id from public.classes where service_id = %3$s))', p_alias, kc, s);
      end if;
    end if;
    -- class level
    if k is not null and kc is not null then
      parts := parts || format('(%1$I.%2$I is null or %1$I.%2$I = %3$s)', p_alias, kc, k);
    end if;
    return array_to_string(parts, ' and ');
  end if;

  -- c) persons — referenced by a scoped row of a directly-scoped table
  if p_table = 'persons' then
    for e in
      select c2.relname::text as child, a.attname::text as col
        from pg_constraint f
        join pg_class c2 on c2.oid = f.conrelid
        join pg_namespace n on n.oid = c2.relnamespace
        join pg_class p on p.oid = f.confrelid
        join pg_attribute a on a.attrelid = c2.oid and a.attnum = f.conkey[1]
       where f.contype = 'f' and n.nspname = 'public' and p.relname = 'persons'
         and array_length(f.conkey, 1) = 1 and c2.relname <> 'persons'
         and c2.relname not like 'backup\_restore\_%'
       order by 1, 2
    loop
      cols := public.backup_scope_columns(e.child);
      if cols->>'church' is null and cols->>'service' is null and cols->>'class' is null then continue; end if;
      alias2 := 'x' || (cardinality(parts) + 1)::text;
      sub := public.backup_scope_predicate(e.child, sc, alias2, p_visited || p_table);
      parts := parts || format('exists (select 1 from public.%1$I %2$I where %2$I.%3$I = %4$I.id and %5$s)', e.child, alias2, e.col, p_alias, sub);
    end loop;
    return case when cardinality(parts) = 0 then 'true' else '(' || array_to_string(parts, ' or ') || ')' end;
  end if;

  -- d) everything else — NOT NULL foreign keys to scoped parents (AND)
  depth := 0;
  for e in
    select p.relname::text as parent, a.attname::text as col, pa.attname::text as pcol
      from pg_constraint f
      join pg_class c2 on c2.oid = f.conrelid
      join pg_namespace n on n.oid = c2.relnamespace
      join pg_class p on p.oid = f.confrelid
      join pg_namespace pn on pn.oid = p.relnamespace
      join pg_attribute a  on a.attrelid  = c2.oid and a.attnum  = f.conkey[1]
      join pg_attribute pa on pa.attrelid = p.oid  and pa.attnum = f.confkey[1]
     where f.contype = 'f' and n.nspname = 'public' and pn.nspname = 'public'
       and c2.relname = p_table and array_length(f.conkey, 1) = 1
       and a.attnotnull and p.relname <> p_table
       and not (p.relname = any(p_visited))
     order by 1, 2
  loop
    depth := depth + 1;
    alias2 := 'y' || cardinality(p_visited)::text || '_' || depth::text;
    sub := public.backup_scope_predicate(e.parent, sc, alias2, p_visited || p_table);
    if sub = 'true' then continue; end if;
    parts := parts || format('exists (select 1 from public.%1$I %2$I where %2$I.%3$I = %4$I.%5$I and %6$s)', e.parent, alias2, e.pcol, p_alias, e.col, sub);
  end loop;
  return case when cardinality(parts) = 0 then 'true' else array_to_string(parts, ' and ') end;
end $$;
revoke all on function public.backup_scope_predicate(text, jsonb, text, text[]) from public;
grant execute on function public.backup_scope_predicate(text, jsonb, text, text[]) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 4. Catalogue + dump — now scope-aware
-- ---------------------------------------------------------------------
drop function if exists public.backup_tables();
create or replace function public.backup_tables(p_scope jsonb default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  out jsonb := '[]'::jsonb;
  sc jsonb; r record; n bigint; pred text;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  sc := public.backup_scope_check(p_scope);
  for r in
    select c.relname::text as name
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind in ('r', 'p')
       and c.relname not like 'backup\_restore\_%'
     order by c.relname
  loop
    pred := case when sc is null then 'true' else public.backup_scope_predicate(r.name, sc, 't') end;
    execute format('select count(*) from public.%I t where %s', r.name, pred) into n;
    out := out || jsonb_build_object(
      'name', r.name,
      'rows', n,
      'pk', to_jsonb(public.backup_pk_columns(r.name)),
      'columns', to_jsonb(public.backup_columns(r.name)),
      'parents', to_jsonb(public.backup_parents(r.name)),
      'scoped', (sc is not null and pred <> 'true')
    );
  end loop;
  return out;
end $$;
revoke all on function public.backup_tables(jsonb) from public;
grant execute on function public.backup_tables(jsonb) to authenticated, service_role;

drop function if exists public.backup_dump_table(text, integer, integer);
create or replace function public.backup_dump_table(
  p_table text, p_offset integer default 0, p_limit integer default 1000, p_scope jsonb default null
) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  pk text[]; ord text; out jsonb; sc jsonb; pred text;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if not public.backup_is_table(p_table) then raise exception 'unknown_table' using errcode = 'P0001'; end if;
  sc := public.backup_scope_check(p_scope);
  pred := case when sc is null then 'true' else public.backup_scope_predicate(p_table, sc, 't') end;
  pk := public.backup_pk_columns(p_table);
  select string_agg(format('%I', c), ', ') into ord from unnest(pk) c;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.%I t where %s order by %s offset %s limit %s) t',
    p_table, pred, coalesce(ord, '1'), greatest(p_offset, 0), least(greatest(p_limit, 1), 2000)
  ) into out;
  return out;
end $$;
revoke all on function public.backup_dump_table(text, integer, integer, jsonb) from public;
grant execute on function public.backup_dump_table(text, integer, integer, jsonb) to authenticated, service_role;

drop function if exists public.backup_dump_auth_users();
create or replace function public.backup_dump_auth_users(p_scope jsonb default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare out jsonb; sc jsonb; pred text;
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  sc := public.backup_scope_check(p_scope);
  pred := case when sc is null then 'true' else public.backup_scope_predicate('servant_enrollments', sc, 's') end;
  execute format($q$
    select coalesce(jsonb_agg(
             jsonb_build_object(
               'id', u.id,
               'email', j->>'email',
               'phone', j->>'phone',
               'encrypted_password', j->>'encrypted_password',
               'email_confirmed_at', j->>'email_confirmed_at',
               'raw_user_meta_data', coalesce(j->'raw_user_meta_data', '{}'::jsonb),
               'raw_app_meta_data', coalesce(j->'raw_app_meta_data', '{}'::jsonb),
               'created_at', j->>'created_at'
             ) order by j->>'created_at'), '[]'::jsonb)
      from auth.users u
      cross join lateral to_jsonb(u) j
     where exists (select 1 from public.servant_enrollments s where s.id = u.id and %s)
  $q$, pred) into out;
  return out;
end $$;
revoke all on function public.backup_dump_auth_users(jsonb) from public;
grant execute on function public.backup_dump_auth_users(jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------
-- 5. Restore — a scoped file may only be MERGED
--    (replace deletes every row the file does not contain → it would wipe
--    the other churches / services / classes).
-- ---------------------------------------------------------------------
create or replace function public.backup_restore_begin(p_mode text, p_tables text[], p_meta jsonb default '{}'::jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare jid uuid; t text; bad text[] := '{}';
begin
  if not public.backup_allowed() then raise exception 'not_allowed' using errcode = 'P0001'; end if;
  if p_mode not in ('merge', 'replace') then raise exception 'bad_mode' using errcode = 'P0001'; end if;
  if p_tables is null or cardinality(p_tables) = 0 then raise exception 'no_tables' using errcode = 'P0001'; end if;
  if p_mode = 'replace' and coalesce(p_meta->'file'->'scope', 'null'::jsonb) <> 'null'::jsonb then
    raise exception 'scoped_replace' using errcode = 'P0001';
  end if;
  foreach t in array p_tables loop
    if not public.backup_is_table(t) then bad := bad || t; end if;
  end loop;
  if cardinality(bad) > 0 then
    raise exception 'unknown_table:%', array_to_string(bad, ',') using errcode = 'P0001';
  end if;
  -- forget stale jobs of the same caller (abandoned uploads)
  delete from public.backup_restore_jobs
   where status = 'staging' and created_at < now() - interval '6 hours';
  insert into public.backup_restore_jobs (mode, tables, meta, created_by)
  values (p_mode, public.backup_topo_order(p_tables), coalesce(p_meta, '{}'::jsonb), auth.uid())
  returning id into jid;
  return jid;
end $$;
revoke all on function public.backup_restore_begin(text, text[], jsonb) from public;
grant execute on function public.backup_restore_begin(text, text[], jsonb) to authenticated, service_role;



-- #####################################################################
-- ##  20261010120000_reduce_platform_log_ingest.sql
-- #####################################################################

-- =====================================================================
-- 20261010120000: REDUCE SUPABASE «LOGS INGEST» — خفض سجلات المنصة
--
-- PROBLEM. The Supabase usage page showed a very high «Logs Ingest» (and a
-- high «Logs Query») figure. Logs Ingest is the volume of PLATFORM logs
-- (Postgres server log · PostgREST API gateway · Auth · Realtime · Storage)
-- that Supabase collects — it is NOT our own سجل النشاط (`activity_log`),
-- which is an ordinary table and costs nothing on that meter. So the fix is
-- to make the database and the app emit fewer platform log lines, without
-- touching what the activity module records or shows.
--
-- WHAT WRITES TO THE POSTGRES SERVER LOG IN THIS SCHEMA
--   1. `raise notice / warning` inside functions that run on EVERY hot
--      operation. Each RAISE is one server-log line regardless of
--      `log_statement` — Supabase documents this as a classic source of
--      «large, otherwise-unexplained» ingest. The culprits here were the
--      `exception when others then raise notice …` safety nets inside the
--      per-row triggers on attendance_log · points_log · user_achievements
--      (notif_on_* / achievements_on_attendance) and inside rt_send(), the
--      broadcast helper called 2–3× per statement on every hot table. When
--      the notifications module is not granted, or realtime is briefly
--      unavailable, these fire on EVERY scan — thousands of lines a day.
--      → the safety nets stay (an error must never block the attendance)
--        but they no longer RAISE. The failure is still visible: the
--        notification simply does not appear, and the activity log keeps
--        the real operation.
--   2. pg_cron `notif_tick` every minute = 1 440 cron runs a day, each one
--      logged by `cron.log_statement` and `cron.log_run` (+ its own
--      statements). The job only releases scheduled sends / reminders whose
--      time has come; a 5-minute granularity is more than enough (the
--      header bells also kick the dispatcher every ~5–7 min).
--      → `*/5 * * * *` (cron.log_run / cron.log_statement are server-level
--        settings → the CLI script below turns them off).
--   3. Postgres GUCs that can be changed with plain SQL at the database
--      level (`alter database … set …`): `log_min_messages`,
--      `log_min_error_statement`, `log_statement`, `log_lock_waits`,
--      `log_temp_files`, `log_min_duration_statement`. We raise them to
--      quiet-but-useful values: ERRORs are still logged (with the failing
--      statement), DDL is still logged, slow queries ≥ 5 s are still logged.
--      Superuser-only / `postmaster` settings (log_connections …) cannot be
--      set from SQL — see supabase/scripts/supabase_log_settings.sh and
--      README → «Supabase log ingest».
--
-- The app side (same PR) reduces the API-gateway log volume: fewer polling
-- requests from the child / priest portals and the realtime fallback, a
-- longer lookup cache, fewer dispatcher kicks.
--
-- Idempotent — safe to re-run. Nothing here changes behaviour visible to
-- users except that scheduled notifications may leave up to 5 minutes later
-- than their `scheduled_at` (was: up to 1 minute).
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Silent safety nets — same bodies as 0046 / 0034 / 0031, minus RAISE
-- ---------------------------------------------------------------------

-- 0046 §1: broadcast helper. Called by rt_notify_scope / rt_notify_users on
-- every statement of every hot table (2–3 calls per scan). A realtime
-- hiccup used to produce one NOTICE per call.
create or replace function public.rt_send(p_topic text, p_payload jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  begin
    perform realtime.send(p_payload, 'change', p_topic, true);
  exception
    when others then
      null; -- realtime not installed / temporarily unavailable → nothing to do, nothing to log
  end;
end $$;
revoke all on function public.rt_send(text, jsonb) from public, anon, authenticated;

-- 0034: attendance → child notification (per row on attendance_log)
create or replace function public.notif_on_attendance()
returns trigger language plpgsql security definer set search_path = public as $$
declare ev text;
begin
  begin
    select name into ev from public.events where id = new.event_id;
    perform public.notif_fire_enrollment('attendance', new.enrollment_id,
      jsonb_build_object('المناسبة', coalesce(ev, 'الحضور'), 'النقاط', new.points_delta, '_delta', new.points_delta),
      '/child/attendance', 'att:' || coalesce(new.event_id::text, '-') || ':' || (now() at time zone 'Africa/Cairo')::date);
  exception when others then
    null; -- best effort: a notification failure must never block (or log) the attendance
  end;
  return new;
end $$;

-- 0034: points added / deducted (per row on points_log)
create or replace function public.notif_on_points()
returns trigger language plpgsql security definer set search_path = public as $$
declare cause text; ev text;
begin
  if new.delta = 0 then return new; end if;
  begin
    select name into cause from public.causes where id = new.cause_id;
    select name into ev from public.events where id = new.event_id;
    perform public.notif_fire_enrollment(
      case when new.delta > 0 then 'points_added' else 'points_deducted' end, new.enrollment_id,
      jsonb_build_object('النقاط', abs(new.delta), 'السبب', coalesce(cause, ''), 'المناسبة', coalesce(ev, ''), '_delta', new.delta),
      '/child/points', null);
  exception when others then
    null;
  end;
  return new;
end $$;

-- 0034: achievement earned (per row on user_achievements)
create or replace function public.notif_on_achievement()
returns trigger language plpgsql security definer set search_path = public as $$
declare a_name text;
begin
  begin
    select name into a_name from public.achievements where id = new.achievement_id;
    perform public.notif_fire_enrollment('achievement_earned', new.enrollment_id,
      jsonb_build_object('الإنجاز', coalesce(a_name, ''), 'النقاط', new.points_awarded, '_delta', new.points_awarded),
      '/child/achievements', null);
  exception when others then
    null;
  end;
  return new;
end $$;

-- 0034: online class went live
create or replace function public.notif_on_online_live()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'live' and (tg_op = 'INSERT' or old.status is distinct from 'live') then
    begin
      perform public.notif_fire_scope('online_class_started', new.church_id, new.service_id, new.class_id,
        jsonb_build_object('العنوان', new.title, 'المنصة', new.platform,
                           'الوقت', to_char(new.starts_at at time zone 'Africa/Cairo', 'HH24:MI')),
        '/child/online/' || new.id, 'online:' || new.id || ':' || coalesce(new.started_at, now())::date);
    exception when others then
      null;
    end;
  end if;
  return new;
end $$;

-- 0034: exam published
create or replace function public.notif_on_exam_published()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published')
     and (new.opens_at is null or new.opens_at <= now()) then
    begin
      perform public.notif_fire_scope('exam_published', new.church_id, new.service_id, new.class_id,
        jsonb_build_object('العنوان', new.title,
                           'آخر موعد', coalesce(to_char(new.closes_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI'), '')),
        '/child/exams/' || new.id, 'exam:' || new.id);
    exception when others then
      null;
    end;
  end if;
  return new;
end $$;

-- 0031 §11: automatic achievements after every attendance_log insert.
-- `raise warning` is logged even at the default log_min_messages=warning.
create or replace function public.achievements_on_attendance()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  e public.enrollments;
  a record;
begin
  begin
    select * into e from public.enrollments where id = new.enrollment_id;
    if not found then return new; end if;
    if not public.module_granted_for('achievements', e.church_id, e.service_id, e.class_id) then
      return new;
    end if;
    for a in
      select x.id, x.event_id from public.achievements x
       where x.is_active and x.kind = 'attendance'
         and x.church_id = e.church_id
         and (x.service_id is null or x.service_id = e.service_id)
         and (x.class_id   is null or x.class_id   = e.class_id)
         and (x.event_id   is null or x.event_id   = new.event_id)
       order by x.sort_order, x.name
    loop
      perform public.achievement_grant(a.id, e.id, new.recorded_by, 'attendance',
                                       new.id, new.event_id, null, false);
    end loop;
  exception when others then
    null; -- best effort — never block the attendance, never spam the server log
  end;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- 2. pg_cron: notif_tick every 5 minutes instead of every minute
--    (1 440 → 288 logged runs a day). Skipped silently where pg_cron is
--    not installed (local Postgres).
-- ---------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'notif_tick';
    perform cron.schedule('notif_tick', '*/5 * * * *', 'select public.notif_tick()');
  end if;
exception when others then
  null;
end $$;

-- ---------------------------------------------------------------------
-- 3. Postgres log settings that CAN be set from SQL (database level).
--    Each one is tried on its own — on a plain local Postgres or a role
--    without the privilege the statement is skipped, not failed.
--
--    log_min_messages           warning → error    (NOTICE / WARNING lines dropped)
--    log_min_error_statement    error              (keep: the failing statement IS useful)
--    log_statement              ddl                (keep Supabase default; `all`/`mod` would be huge)
--    log_min_duration_statement 5 s                (only genuinely slow statements)
--    log_lock_waits             off                (no lock-contention symptoms)
--    log_temp_files             -1                 (off)
--    (`log_connections`, `cron.log_run`, `cron.log_statement` are server-
--     level: CLI only — supabase/scripts/supabase_log_settings.sh)
-- ---------------------------------------------------------------------
do $$
declare
  stmt text;
  db   text := current_database();
begin
  foreach stmt in array array[
    format('alter database %I set log_min_messages = error', db),
    format('alter database %I set log_min_error_statement = error', db),
    format('alter database %I set log_statement = ddl', db),
    format('alter database %I set log_min_duration_statement = ''5s''', db),
    format('alter database %I set log_lock_waits = off', db),
    format('alter database %I set log_temp_files = -1', db)
  ] loop
    begin
      execute stmt;
    exception when others then
      null; -- not permitted here / unknown parameter → leave the platform default
    end;
  end loop;
end $$;

-- Per-role too: PostgREST connects as `authenticator` and switches to
-- anon / authenticated / service_role; role-level settings win over the
-- database-level ones, so make sure none of them re-enables chatter.
do $$
declare
  r text; stmt text;
begin
  foreach r in array array['authenticator', 'anon', 'authenticated', 'service_role', 'postgres'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      foreach stmt in array array[
        format('alter role %I set log_min_messages = error', r),
        format('alter role %I set log_min_error_statement = error', r),
        format('alter role %I set log_statement = ddl', r),
        format('alter role %I set log_min_duration_statement = ''5s''', r),
        format('alter role %I set log_lock_waits = off', r),
        format('alter role %I set log_temp_files = -1', r)
      ] loop
        begin
          execute stmt;
        exception when others then
          null;
        end;
      end loop;
    end if;
  end loop;
end $$;



-- #####################################################################
-- ##  20261012120000_call_feedback_other_note.sql
-- #####################################################################

-- =====================================================================
-- 20261012120000: CALL FEEDBACK «أخرى» — a manually written cause
--
-- The call-feedback picker (opened automatically when the servant comes
-- back to the app after a call) gets a fixed extra choice «أخرى» shown
-- with a «!» icon. Choosing it lets the servant WRITE the cause himself
-- instead of picking one of the predefined `call_feedbacks`.
--
-- Storage: the same `contact_log` row model as 0023 —
--     kind = 'call' · occurrence_on = the followed-up occurrence
--     feedback_id = NULL  (no predefined feedback)
--     note        = the written cause            ← NEW COLUMN
-- The badge shows «أخرى» (!) for such a row; the history modal shows the
-- note text. A row is a FEEDBACK row when `occurrence_on` is set and
-- (feedback_id is not null OR note is not null); a plain dial logged when
-- the call button is pressed has both null (and no occurrence_on).
--
-- Idempotent — safe to re-run. Depends on 0023.
-- =====================================================================


alter table public.contact_log
  add column if not exists note text;   -- the cause written for «أخرى» (feedback_id is null)

-- A note is a short free text (1..500 chars after trimming)
alter table public.contact_log drop constraint if exists contact_log_note_len;
alter table public.contact_log
  add constraint contact_log_note_len
  check (note is null or char_length(btrim(note)) between 1 and 500);

-- Badge lookup now covers BOTH kinds of feedback rows (predefined + «أخرى»)
drop index if exists public.idx_contact_log_feedback_lookup;
create index if not exists idx_contact_log_followup_lookup
  on public.contact_log(event_id, occurrence_on, enrollment_id, created_at desc)
  where feedback_id is not null or note is not null;

comment on column public.contact_log.note is
  'الافتقاد «أخرى»: السبب المكتوب يدويًا عندما لا تُختار نتيجة معرّفة (feedback_id null)';

analyze public.contact_log;



-- #####################################################################
-- ##  20261015120000_bootstrap_rpcs_config_broadcast.sql
-- #####################################################################

-- =====================================================================
-- 20261015120000: ONE request to open the app — app_bootstrap() ·
--                 child_portal_bootstrap() · config tables on the bus
--
-- Third round on the Supabase «Logs Ingest» meter (the API gateway logs one
-- line per HTTP request and cannot be switched off). The previous rounds
-- removed background polling and the realtime fan-out; what is left is the
-- «every open» cost — the requests every device makes each time the app
-- starts, which scales with the number of PEOPLE, not with activity.
--
--   STAFF — a full load / PWA cold start / new tab ran, before the page's
--   own data: servant_enrollments (1) · servant_scopes + persons + churches
--   + services + servant_active_places (5) · module_access (1) ·
--   permission_profiles + permissions (2) · app_settings (1) = 10 requests,
--   then 4 `postgres_changes` joins on the cold config tables (each join =
--   a realtime handshake + per-change RLS work).
--
--   CHILD PORTAL — opening any page ran profile · exams · chat overview ·
--   online classes · achievements · occasions · notifications · library ·
--   shops · store requests = 10 RPCs, and the SAME 10 again on every tab
--   focus, plus 4 anon `postgres_changes` joins.
--
-- FIX
--   1. app_bootstrap()                → everything AuthProvider · Modules ·
--                                       Permissions · Customization need,
--                                       as one jsonb. RLS-equivalent: the
--                                       function runs as the caller
--                                       (security INVOKER) so every row is
--                                       exactly what the 10 queries returned.
--   2. child_portal_bootstrap(token)  → session touch + the 10 blocks in one
--                                       call (each block is the existing RPC;
--                                       a block that fails — module not
--                                       granted / migration missing — is
--                                       null, the others still arrive).
--   3. The four config tables (app_settings · module_access ·
--      permission_profiles · permissions) join the 0046 broadcast bus with
--      a statement-level trigger that notifies EVERY church topic (+
--      scope:all) — they are global, change about once a month, and every
--      signed-in device needs to hear about it. The app drops its four
--      postgres_changes channels for them.
--
-- Idempotent. No behaviour change on screen.
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. STAFF BOOTSTRAP — security invoker: RLS applies exactly as before
-- ---------------------------------------------------------------------
create or replace function public.app_bootstrap()
returns jsonb language plpgsql stable security invoker set search_path = public as $$
declare
  uid uuid := auth.uid();
  prof public.servant_enrollments;
  out jsonb;
begin
  if uid is null then return jsonb_build_object('profile', null); end if;
  select * into prof from public.servant_enrollments where id = uid;
  if not found then return jsonb_build_object('profile', null); end if;

  out := jsonb_build_object(
    'profile', to_jsonb(prof),
    'scopes', coalesce((select jsonb_agg(jsonb_build_object('church_id', church_id, 'service_id', service_id, 'class_id', class_id))
                          from public.servant_scopes where servant_id = uid), '[]'::jsonb),
    'person',  (select to_jsonb(p) from public.persons p where p.id = prof.person_id),
    'church',  (select to_jsonb(c) from public.churches c where c.id = prof.church_id),
    'service', (select to_jsonb(s) from public.services s where s.id = prof.service_id),
    'active_place', (select jsonb_build_object('church_id', church_id, 'service_id', service_id, 'class_id', class_id)
                       from public.servant_active_places where servant_id = uid limit 1)
  );

  -- the rest only for an approved servant (the providers skip it otherwise)
  if prof.status = 'approved' then
    out := out || jsonb_build_object(
      'module_access', coalesce((select jsonb_agg(to_jsonb(m)) from public.module_access m), '[]'::jsonb),
      'permission_profiles', coalesce((select jsonb_agg(to_jsonb(pp) order by pp.sort_order, pp.name) from public.permission_profiles pp), '[]'::jsonb),
      'permissions', coalesce((select jsonb_agg(to_jsonb(pe)) from public.permissions pe), '[]'::jsonb),
      'app_settings', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'value', value))
                                  from public.app_settings where key in ('navigation', 'widgets', 'names', 'codes')), '[]'::jsonb)
    );
  end if;
  return out;
end $$;
revoke all on function public.app_bootstrap() from public, anon;
grant execute on function public.app_bootstrap() to authenticated;
comment on function public.app_bootstrap() is 'كل ما يحتاجه التطبيق عند الفتح في طلب واحد — profile · scopes · person · church · service · active_place · module_access · permission_profiles · permissions · app_settings (security invoker → نفس RLS)';

-- ---------------------------------------------------------------------
-- 2. CHILD PORTAL BOOTSTRAP — one call = session touch + every block.
--    Each block is the existing RPC; a failing one becomes null so a
--    module that is not granted / a migration not yet applied never takes
--    the whole portal down.
-- ---------------------------------------------------------------------
create or replace function public.child_portal_bootstrap(p_token text, p_notif_limit integer default 80)
returns jsonb language plpgsql volatile security definer set search_path = public, extensions as $$
declare
  out jsonb := '{}'::jsonb;
  v jsonb;
begin
  -- session first: this raises session_expired / invalid_code exactly like
  -- child_session_touch did, so the client logs the child out the same way
  v := public.child_session_touch(p_token);
  out := out || jsonb_build_object('session', v);

  -- profile is mandatory — if it fails the whole call fails (same as before)
  out := out || jsonb_build_object('profile', public.child_portal_profile(p_token));

  begin v := public.child_portal_exams(p_token);            exception when others then v := null; end; out := out || jsonb_build_object('exams', v);
  begin v := public.child_chat_overview(p_token);           exception when others then v := null; end; out := out || jsonb_build_object('conversations', v);
  begin v := public.child_online_classes(p_token);          exception when others then v := null; end; out := out || jsonb_build_object('online_classes', v);
  begin v := public.child_portal_achievements(p_token);     exception when others then v := null; end; out := out || jsonb_build_object('achievements', v);
  begin v := public.child_portal_occasions(p_token);        exception when others then v := null; end; out := out || jsonb_build_object('occasions', v);
  begin v := public.child_notifications(p_token, p_notif_limit); exception when others then v := null; end; out := out || jsonb_build_object('notifications', v);
  begin v := public.child_portal_library(p_token);          exception when others then v := null; end; out := out || jsonb_build_object('library', v);
  begin v := public.child_portal_shops(p_token);            exception when others then v := null; end; out := out || jsonb_build_object('shops', v);
  begin v := public.child_portal_store_requests(p_token);   exception when others then v := null; end; out := out || jsonb_build_object('store_requests', v);
  return out;
end $$;
revoke all on function public.child_portal_bootstrap(text, integer) from public;
grant execute on function public.child_portal_bootstrap(text, integer) to anon, authenticated;
comment on function public.child_portal_bootstrap(text, integer) is 'بوابة المخدوم — تمديد الجلسة + كل بيانات البوابة في طلب واحد (كل كتلة = الدالة القديمة؛ الكتلة الفاشلة = null)';

-- ---------------------------------------------------------------------
-- 3. CONFIG TABLES → broadcast bus (every church topic + scope:all)
-- ---------------------------------------------------------------------
create or replace function public.rt_trg_global()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[];
begin
  select array_agg(id) into churches from public.churches;
  perform public.rt_notify_scope(tg_table_name, tg_op, churches, null);
  return null;
end $$;
revoke all on function public.rt_trg_global() from public, anon, authenticated;

do $$
declare t text;
begin
  foreach t in array array['app_settings', 'module_access', 'permission_profiles', 'permissions'] loop
    if to_regclass('public.' || t) is null then continue; end if;
    execute format('drop trigger if exists zzz_rt_ins on public.%I', t);
    execute format('drop trigger if exists zzz_rt_upd on public.%I', t);
    execute format('drop trigger if exists zzz_rt_del on public.%I', t);
    execute format('create trigger zzz_rt_ins after insert on public.%I for each statement execute function public.rt_trg_global()', t);
    execute format('create trigger zzz_rt_upd after update on public.%I for each statement execute function public.rt_trg_global()', t);
    execute format('create trigger zzz_rt_del after delete on public.%I for each statement execute function public.rt_trg_global()', t);
    -- leave the postgres_changes publication (no more per-subscriber RLS work)
    begin
      execute format('alter publication supabase_realtime drop table public.%I', t);
    exception when others then null; -- not in the publication / no publication locally
    end;
  end loop;
end $$;



-- #####################################################################
-- ##  20261016120000_rls_initplan_realtime_consolidation.sql
-- #####################################################################

-- =====================================================================
-- 20261016120000: RLS evaluated ONCE per statement · every table on the
--                 broadcast bus · stats_attendance_timeline pre-aggregated
--
-- Evidence (pg_stat_statements, production, 30 days):
--   realtime.list_changes            2 995 255 calls   32 755 s
--   realtime.subscription insert        81 032 calls
--   enrollments (list select)        ~21 000 calls    1.1–1.2 s avg
--   stats_attendance_timeline           6 767 calls    1.28 s avg
--   attendance_log event/ids badge     14 142 calls    553 ms avg
--
-- Three root causes, three fixes — NO behaviour change for the user:
--
-- 1. RLS cost. `enrollment_visible(..., (select … from my_scope()) ×4)` is
--    cheap per row, but it ends with `or extra_scope_visible(...)` which
--    calls `my_scopes()` → `servant_places()` → `servant_scopes` for EVERY
--    ROW the planner looks at (cost 500, SECURITY DEFINER → never inlined).
--    A church manager's 200-row page scans ~1 000 rows → 1 000 scope
--    look-ups → 350 ms; the owner's 14-day timeline → 29 s locally.
--    Fix: `my_scope_sets()` returns the caller's visibility as FOUR ARRAYS
--    in one row; `scope_visible(row cols, arrays)` is a pure IMMUTABLE SQL
--    function the planner inlines, and the four `(select … from
--    my_scope_sets())` become InitPlans evaluated ONCE per statement.
--    The 33 policies that used enrollment_visible are rewritten
--    mechanically (same tables, same commands, same roles, same other
--    predicates). `enrollment_visible` itself stays (other code may call
--    it) — it just no longer pays for extra_scope_visible per row because
--    it is only reached outside policies now.
--    Local bench (3 000 enrollments, 45 k attendance rows):
--       church manager list page   348 ms →   4.5 ms
--       class servant whole scope 1 293 ms →   8.5 ms
--       timeline (class servant)  5 312 ms →  39 ms
--       timeline (owner)         29 177 ms →  39 ms
--    Semantic equivalence verified for owner / church manager / service
--    manager (with & without service) / class servant (class, service-wide,
--    extra scope) / pending / unknown — 0 mismatches over every enrollment.
--
-- 2. `realtime.list_changes` ×3 M. Every `postgres_changes` subscription is
--    polled continuously by the Realtime server, independently of whether
--    anything changed; 60 cold tables × 58 hook sites × every open device.
--    The broadcast bus (0046) already carries the 18 hot tables with ONE
--    statement-level trigger each and NO per-subscriber polling. This
--    migration puts the remaining tables on the same bus and drops them
--    from the publication:
--       • tables with a NOT NULL church_id → rt_trg_scoped_nullable
--         (church topics; rows with NULL church_id = global → every church)
--       • tables without church_id       → rt_trg_global (every church)
--    `BUS_TABLES` in src/lib/realtime.ts lists the same tables; the hook
--    then never opens a channel for them — zero component changes.
--    After this the publication is EMPTY: list_changes → 0.
--
-- 3. `stats_attendance_timeline`: joined `events` (whose policy runs
--    scope_overlaps + activity_item_can per row) for every one of 21 k
--    attendance rows before grouping. Now: scope once, aggregate, THEN join
--    events on the ~100 grouped rows. SECURITY DEFINER with the caller's
--    scope applied explicitly (same rows as before). Plus a composite
--    index attendance_log(enrollment_id, attended_on) for the join.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Visibility as arrays, once per statement
-- ---------------------------------------------------------------------
create or replace function public.my_scope_sets()
returns table (is_owner boolean, churches uuid[], services uuid[], classes uuid[])
language sql stable security definer set search_path = public as $$
  select
    coalesce(bool_or(s.role = 'owner'), false),
    array_agg(s.church_id) filter (where s.church_id is not null and (
         s.role = 'church_manager'
      or (s.role = 'service_manager' and s.service_id is null)
      or (s.role = 'class_servant'   and s.class_id is null and s.service_id is null))),
    array_agg(s.service_id) filter (where s.service_id is not null and (
         s.role = 'service_manager'
      or (s.role = 'class_servant' and s.class_id is null))),
    array_agg(s.class_id) filter (where s.class_id is not null and s.role = 'class_servant')
  from public.my_scopes() s
$$;
grant execute on function public.my_scope_sets() to authenticated, anon;

-- Pure predicate → inlined into the policy; the arrays arrive as InitPlans.
create or replace function public.scope_visible(p_church uuid, p_service uuid, p_class uuid,
  s_owner boolean, s_churches uuid[], s_services uuid[], s_classes uuid[])
returns boolean language sql immutable as $$
  select coalesce(s_owner, false)
      or p_church  = any (coalesce(s_churches, '{}'::uuid[]))
      or p_service = any (coalesce(s_services, '{}'::uuid[]))
      or p_class   = any (coalesce(s_classes,  '{}'::uuid[]))
$$;
grant execute on function public.scope_visible(uuid, uuid, uuid, boolean, uuid[], uuid[], uuid[]) to authenticated, anon;

-- Rewrite every policy that calls enrollment_visible(..., my_scope() ×4).
do $$
declare
  r record; q text; w text; n int := 0;
  pat constant text :=
    'enrollment_visible\(([^,]+), ([^,]+), ([^,]+), \( SELECT my_scope\.role\s+FROM my_scope\(\) my_scope\(role, church_id, service_id, class_id\)\), \( SELECT my_scope\.church_id\s+FROM my_scope\(\) my_scope\(role, church_id, service_id, class_id\)\), \( SELECT my_scope\.service_id\s+FROM my_scope\(\) my_scope\(role, church_id, service_id, class_id\)\), \( SELECT my_scope\.class_id\s+FROM my_scope\(\) my_scope\(role, church_id, service_id, class_id\)\)\)';
  rep constant text :=
    'public.scope_visible(\1, \2, \3, (select ss.is_owner from public.my_scope_sets() ss), (select ss.churches from public.my_scope_sets() ss), (select ss.services from public.my_scope_sets() ss), (select ss.classes from public.my_scope_sets() ss))';
begin
  for r in
    select schemaname, tablename, policyname, cmd, roles, permissive, qual, with_check
      from pg_policies
     where schemaname = 'public'
       and (qual ilike '%enrollment_visible(%' or with_check ilike '%enrollment_visible(%')
  loop
    q := regexp_replace(r.qual, pat, rep, 'g');
    w := regexp_replace(r.with_check, pat, rep, 'g');
    if (q is not distinct from r.qual) and (w is not distinct from r.with_check) then
      raise notice 'policy %.% left as is (unexpected shape)', r.tablename, r.policyname;
      continue;
    end if;
    execute format('drop policy %I on %I.%I', r.policyname, r.schemaname, r.tablename);
    execute format('create policy %I on %I.%I as %s for %s to %s %s %s',
      r.policyname, r.schemaname, r.tablename, r.permissive, r.cmd,
      array_to_string(r.roles, ', '),
      case when q is not null then 'using (' || q || ')' else '' end,
      case when w is not null then 'with check (' || w || ')' else '' end);
    n := n + 1;
  end loop;
  raise notice 'scope_visible: rewrote % policies', n;
end $$;

-- ---------------------------------------------------------------------
-- 2. stats_attendance_timeline — scope once, aggregate, then name events
-- ---------------------------------------------------------------------
create index if not exists idx_attendance_log_enrollment_day
  on public.attendance_log(enrollment_id, attended_on);

create or replace function public.stats_attendance_timeline(
  p_from date, p_to date, p_bucket text default 'day',
  p_church uuid default null, p_service uuid default null, p_class uuid default null,
  p_kind text default 'child')
returns table (
  bucket      date,
  event_id    uuid,
  event_name  text,
  church_id   uuid,
  attendance  bigint,
  attendees   bigint,
  points      bigint
)
language sql stable security definer set search_path = public as $$
  with ss as (select * from public.my_scope_sets()),
  sc as (
    select e.id, e.person_id
      from public.enrollments e, ss
     where (p_church  is null or e.church_id  = p_church)
       and (p_service is null or e.service_id = p_service)
       and (p_class   is null or e.class_id   = p_class)
       and (p_kind is null or p_kind = 'all' or e.kind = p_kind)
       and (ss.is_owner
            or e.church_id  = any (coalesce(ss.churches, '{}'::uuid[]))
            or e.service_id = any (coalesce(ss.services, '{}'::uuid[]))
            or e.class_id   = any (coalesce(ss.classes,  '{}'::uuid[])))
  ),
  agg as (
    select case lower(coalesce(p_bucket, 'day'))
             when 'week'  then date_trunc('week',  a.attended_on::timestamp)::date
             when 'month' then date_trunc('month', a.attended_on::timestamp)::date
             else a.attended_on
           end as bucket,
           a.event_id,
           count(*)::bigint                      as attendance,
           count(distinct sc.person_id)::bigint  as attendees,
           coalesce(sum(a.points_delta), 0)::bigint as points
      from public.attendance_log a join sc on sc.id = a.enrollment_id
     where a.attended_on between p_from and p_to
     group by 1, 2
  )
  select agg.bucket, agg.event_id,
         coalesce(ev.name, 'بدون مناسبة') as event_name,
         ev.church_id, agg.attendance, agg.attendees, agg.points
    from agg
    left join public.events ev on ev.id = agg.event_id
   order by agg.bucket, event_name
$$;
grant execute on function public.stats_attendance_timeline(date, date, text, uuid, uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------------
-- 3. Every remaining table → broadcast bus; publication emptied
-- ---------------------------------------------------------------------
-- church-scoped rows; NULL church_id (owner-global templates / settings)
-- is broadcast to every church so each device refreshes its copy.
create or replace function public.rt_trg_scoped_nullable()
returns trigger language plpgsql security definer set search_path = public as $$
declare churches uuid[]; ids uuid[]; has_null boolean;
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct church_id) filter (where church_id is not null), bool_or(church_id is null), array_agg(id)
      into churches, has_null, ids from new_rows;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct church_id) filter (where church_id is not null), bool_or(church_id is null), array_agg(id)
      into churches, has_null, ids from old_rows;
  else
    select array_agg(distinct church_id) filter (where church_id is not null), bool_or(church_id is null), array_agg(distinct id)
      into churches, has_null, ids
      from (select church_id, id from new_rows union all select church_id, id from old_rows) x;
  end if;
  if ids is null then return null; end if;
  if coalesce(has_null, false) then
    select array_agg(c.id) into churches from public.churches c;
  end if;
  perform public.rt_notify_scope(tg_table_name, tg_op, churches, ids);
  return null;
end $$;
revoke all on function public.rt_trg_scoped_nullable() from public, anon, authenticated;

-- rt_trg_global (20261015) handles tables without church_id; it does not
-- read the transition tables so it can be attached without REFERENCING.
do $$
declare
  t record; has_church boolean; has_id boolean;
begin
  for t in
    select tablename from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public'
  loop
    select exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = t.tablename and column_name = 'church_id'),
           exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = t.tablename and column_name = 'id' and data_type = 'uuid')
      into has_church, has_id;
    execute format('drop trigger if exists zzz_rt_ins on public.%I', t.tablename);
    execute format('drop trigger if exists zzz_rt_upd on public.%I', t.tablename);
    execute format('drop trigger if exists zzz_rt_del on public.%I', t.tablename);
    if has_church and has_id then
      execute format('create trigger zzz_rt_ins after insert on public.%I referencing new table as new_rows for each statement execute function public.rt_trg_scoped_nullable()', t.tablename);
      execute format('create trigger zzz_rt_upd after update on public.%I referencing old table as old_rows new table as new_rows for each statement execute function public.rt_trg_scoped_nullable()', t.tablename);
      execute format('create trigger zzz_rt_del after delete on public.%I referencing old table as old_rows for each statement execute function public.rt_trg_scoped_nullable()', t.tablename);
    else
      execute format('create trigger zzz_rt_ins after insert on public.%I for each statement execute function public.rt_trg_global()', t.tablename);
      execute format('create trigger zzz_rt_upd after update on public.%I for each statement execute function public.rt_trg_global()', t.tablename);
      execute format('create trigger zzz_rt_del after delete on public.%I for each statement execute function public.rt_trg_global()', t.tablename);
    end if;
    begin
      execute format('alter publication supabase_realtime drop table public.%I', t.tablename);
    exception when others then null;
    end;
  end loop;
end $$;

-- the child portal has no auth session → cannot join private topics; its
-- two remaining postgres_changes uses (data_change_requests · online room)
-- become focus/poll refreshes in the client. Nothing else reads the
-- publication, so it is intentionally empty from now on.

